COLLDATA("nasai","ur",[[1540,"عبداللہ بن عمر رضی اللہ عنہم بیان کرتے تھے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوف کی نماز پڑھی، نبی اکرم صلی اللہ علیہ وسلم نے اللہ اکبر کہا، اور ہم میں سے ایک گروہ نے آپ کے پیچھے صف بنائی، اور دوسرا گروہ دشمن کے سامنے رہا، تو نبی اکرم صلی اللہ علیہ وسلم نے انہیں ایک رکوع اور دو سجدے کرائے، پھر یہ لوگ پلٹے اور دشمن کے مقابلہ میں آ گئے، اور دوسرا گروہ آیا تو اس نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھی، تو آپ نے (اس کے ساتھ بھی) اسی طرح کیا، پھر آپ نے سلام پھیرا، پھر دونوں گروہوں میں سے ہر آدمی کھڑا ہوا، اور اس نے خود سے ایک رکوع اور دو سجدے کیے۔","الألباني: صحيح لغيره",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے تھے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی۔ نبی صلی اللہ علیہ وسلم نے اللہ اکبر کہا۔ ہم میں سے ایک گروہ نے آپ کے پیچھے صف بندی کی اور دوسرا گروہ دشمن کے مقابل رہا۔ نبی صلی اللہ علیہ وسلم نے پہلے گروہ کے ساتھ ایک رکوع اور دو سجدے کیے (یعنی ایک رکعت پڑھائی)، پھر وہ چلے گئے اور دشمن کے مقابل صف آراء ہوگئے اور دوسرا گروہ آپ کے پیچھے کھڑا ہوگیا اور انھوں نے نبی صلی اللہ علیہ وسلم کے ساتھ نماز شروع کردی۔ آپ نے اسی طرح کیا (یعنی ان کو بھی ایک رکعت پڑھائی۔) پھر آپ نے سلام پھیر دیا، پھر دونوں گروہوں میں سے ہر شخص اٹھا اور اس نے اپنے طور پر ایک رکوع اور دو سجدے کرلیے۔ (یعنی ایک ایک رکعت پڑھ لی۔)"}],[1541,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خوف کی نماز پڑھائی، تو آپ کھڑے ہوئے، اور اللہ اکبر کہا، تو آپ کے پیچھے ہم میں سے ایک گروہ نے نماز پڑھی، اور ایک گروہ دشمن کے سامنے رہا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس کے ساتھ ایک رکوع اور دو سجدے کئے، پھر وہ لوگ پلٹے حالانکہ انہوں نے ابھی سلام نہیں پھیرا تھا، اور دشمن کے بالمقابل آ گئے، اور ان کی جگہ صف بستہ ہو گئے، اور دوسرا گروہ آیا، اور وہ رسول اللہ صلی اللہ علیہ وسلم کے پیچھے صف بستہ ہو گیا، تو آپ صلی اللہ علیہ وسلم نے اس کے ساتھ ایک رکوع اور دو سجدے کئے، پھر رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، اس حال میں کہ آپ نے دو رکوع اور چار سجدے مکمل کر لیے تھے، پھر دونوں گروہ کھڑے ہوئے، اور ان میں سے ہر شخص نے خود سے ایک رکوع اور دو سجدے کیے۔ ابوبکر بن السنی کہتے ہیں: زہری نے ابن عمر رضی اللہ عنہم سے دو حدیثیں سنی ہیں، لیکن یہ حدیث انہوں نے ان سے نہیں سنی ہے ۱؎۔\n§وضاحت\n۱؎: زہری کی ملاقات ابن عمر رضی اللہ عنہما سے ہے یا نہیں یہ مسئلہ مختلف فیہ ہے صحیح یہ ہے کہ ملاقات نہیں ہے، زہری ابن عمر رضی اللہ عنہم کے بیٹے سالم کے واسطہ ہی سے ان سے روایت کرتے ہیں، معمر کی جن دو روایتوں کے متعلق آیا ہے کہ اسے انہوں نے ابن عمر رضی اللہ عنہم سے سنا ہے، یہ صحیح نہیں، کیونکہ معمر کے علاوہ دوسرے لوگوں نے اسے زہری سے روایت کیا ہے، اس میں زہری اور ابن عمر کے درمیان سالم کا واسطہ ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز خوف پڑھائی۔ آپ کھڑے ہوئے اور اللہ اکبر کہا تو ہم میں سے ایک گروہ آپ کے پیچھے نماز پڑھنے لگا اور دوسرا گروہ دشمن کے مقابل رہا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ ایک رکوع اور دو سجدے کیے، پھر وہ سلام پھیرے بغیر چلے گئے اور دوسروں کی جگہ دشمن کے سامنے کھڑے ہوگئے، پھر دوسرے گروہ نے آکر آپ کے پیچھے صف بندی کی۔ آپ نے ان کے ساتھ بھی ایک رکوع اور دو سجدے کیے، پھر رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیر دیا جبکہ آپ دو رکوع اور چار سجدے (یعنی دو رکعتیں) مکمل فرما چکے تھے، پھر دونوں گروہ اٹھے اور ان میں سے ہر شخص نے اپنے اپنے طور پر ایک رکوع اور دو سجدے کرلیے۔\n(امام نسائی رحمہ اللہ کے شاگرد) ابوبکر بن سنی بیان کرتے ہیں کہ امام زہری نے حضرت ابن عمر رضی اللہ عنہما سے صرف دو حدیثیں سنی ہیں لیکن یہ روایت ان میں شامل نہیں۔ (گویا اس روایت کی سند میں انقطاع ہے۔)","f2":"یہ حضرت ابوبکر بن سنی کا خیال ہے۔ حضرت علی بن مدینی نے بھی یہی قول بیان کیا ہے مگر امام احمد بن حنبل اور حضرت یحییٰ بن معین کے نزدیک امام زہری نے کوئی روایت بھی حضرت عبداللہ بن عمر رضی اللہ عنہما سے نہیں سنی اور یہی موقف درست اور راجح ہے، لہٰذا مذکورہ سند منقطع ہے لیکن یہ انقطاع سابقہ دونوں روایتوں سے رفع ہو جاتا ہے کیونکہ ان دو روایات میں سالم کا واسطہ مذکور ہے۔ واللہ اعلم۔ مزید دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۷؍۱۲۶، ۱۲۷)"}],[1542,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے بعض غزوات میں خوف کی نماز پڑھی، تو ایک گروہ آپ کے ساتھ کھڑا ہوا، اور دوسرا گروہ دشمن کے مقابلہ میں رہا، تو جو لوگ آپ کے ساتھ تھے انہیں آپ نے ایک رکعت پڑھائی، پھر یہ لوگ چلے گئے، اور دوسرے لوگ آ گئے تو آپ نے انہیں(بھی) ایک رکعت پڑھائی، پھر دونوں گروہوں نے ایک ایک رکعت پوری کی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما بیان کرتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے کسی جنگ کے دنوں میں نمازخوف پڑھائی تو ایک گروہ آپ کے پیچھے کھڑا ہوگیا اور دوسرا گروہ دشمن کے مقابل کھڑا رہا۔ آپ نے اپنے ساتھ والوں کو ایک رکعت پڑھا دی، پھر وہ چلے گئے اور دوسرے آگئے۔ آپ نے ان کو بھی ایک رکعت پڑھا دی، پھر دونوں گروہوں نے ایک ایک رکعت اپنے طور پر پڑھ لی۔","f2":"ان احادیث میں نماز کے دوران میں آنا جانا، دشمن کے مقابل کھڑا ہونا، خواہ منہ کسی طرف بھی کرنا پڑے، اسی طرح امام کا ٹھہرنا اور آنے جانے والوں کا انتظار کرنا یہ سب نماز خوف کی خصوصیات ہیں۔ یہ اللہ تعالیٰ کی مہربانی اور کرم نوازی ہے، ان سے نماز کی حیثیت اور ثواب میں کوئی کمی نہیں آئے گی بلکہ ممکن ہے نماز کی شان بڑھ جائے۔"}],[1543,"مروان بن حکم سے روایت ہے کہ انہوں نے ابوہریرہ رضی اللہ عنہ سے پوچھا کہ کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوف کی نماز پڑھی ہے؟ تو ابوہریرہ نے کہا: ہاں پڑھی ہے، انہوں نے پوچھا: کب؟ ابوہریرہ رضی اللہ عنہ نے کہا: نجد کے غزوہ کے سال رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز کے لیے کھڑے ہوئے، ایک گروہ آپ کے ساتھ کھڑا ہوا، اور دوسرا گروہ دشمن کے مقابل رہا، اور ان کی پیٹھ قبلہ کی طرف تھی، رسول اللہ صلی اللہ علیہ وسلم نے اللہ اکبر کہا، تو جو آپ کے ساتھ تھے اور جو دشمن کا مقابلہ کر رہے تھے سبھوں نے اللہ اکبر کہا، پھر رسول اللہ صلی اللہ علیہ وسلم نے ایک رکوع کیا، اور اس گروہ نے بھی جو آپ کے ساتھ تھا رکوع کیا، پھر آپ نے سجدہ کیا، اور اس گروہ نے بھی سجدہ کیا جو آپ کے ساتھ تھا، اور دوسرے لوگ دشمن کے مقابل کھڑے رہے، پھر رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور وہ گروہ جو آپ کے ساتھ تھا، پھر یہ لوگ جا کر دشمن کے بالمقابل کھڑے ہو گئے، پھر وہ گروہ جو دشمن کے بالمقابل تھا آیا، چنانچہ ان لوگوں نے(بھی) رکوع کیا، اور سجدہ کیا، اور رسول اللہ صلی اللہ علیہ وسلم کھڑے رہے جیسے تھے، پھر وہ لوگ کھڑے ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے دوسرا رکوع کیا، تو ان لوگوں نے بھی آپ کے ساتھ رکوع کیا، آپ نے سجدہ کیا، اور ان لوگوں نے بھی آپ کے ساتھ سجدہ کیا، پھر وہ گروہ آیا جو دشمن کے مقابل میں کھڑا تھا، تو اس نے بھی رکوع اور سجدہ کیا، اور رسول اللہ صلی اللہ علیہ وسلم اور وہ لوگ جو آپ کے ساتھ تھے بیٹھے ہوئے تھے، پھر سلام پھیرنے (کا وقت آیا) تو رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، اور تمام لوگوں نے سلام پھیرا، تو اس طرح رسول اللہ صلی اللہ علیہ وسلم کی دو رکعت ہوئی، اور دونوں گروہوں کے ہر ہر فرد کی (بھی) دو دو رکعت ہوئی۔","الألباني: صحيح",{"u2":"حضرت مروان بن حکم نے حضرت ابوہریرہ رضی اللہ عنہ سے پوچھا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نماز خوف پڑھی ہے؟ حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا: ہاں۔ اس نے کہا: کب؟ آپ نے فرمایا: غزوۂ نجد کے سال۔ رسول اللہ صلی اللہ علیہ وسلم عصر کی نماز کے لیے اٹھے اور ایک گروہ آپ کے ساتھ کھڑا ہوا جبکہ دوسرا گروہ دشمن کے مقابل تھا اور ان کی پشت قبلے کی طرف تھی۔ رسول اللہ صلی اللہ علیہ وسلم نے اللہ اکبر کہا (یعنی نماز شروع کرلی) آپ کے ساتھ والوں نے بھی اور انھوں نے بھی جو دشمن کے مقابل تھے، پھر رسول اللہ صلی اللہ علیہ وسلم نے رکوع فرمایا تو آپ کے ساتھ والے گروہ نے بھی رکوع کیا، پھر آپ نے سجدہ فرمایا تو آپ کے ساتھ والے گروہ نے بھی سجدہ کیا جب کہ دوسرے گروہ والے دشمن کے مقابل کھڑے رہے، پھر رسول اللہ صلی اللہ علیہ وسلم اٹھ کھڑے ہوئے تو آپ کے ساتھ والے بھی اٹھ کھڑے ہوئے اور وہ دشمن کی طرف جا کر ان کے مقابل کھڑے ہوگئے اور جو پہلے دشمن کے مقابل تھے انھوں نے آپ کے پیچھے آکر اپنا رکوع اور سجود کیا (یعنی ایک رکعت اپنے طور پر پڑھ لی۔) اس دوران میں رسول اللہ صلی اللہ علیہ وسلم اسی طرح کھڑے رہے (جس طرح آپ کھڑے تھے۔)، پھر وہ کھڑے ہوئے تو رسول اللہ صلی اللہ علیہ وسلم نے دوسری رکعت کا رکوع فرمایا انھوں نے بھی آپ کے ساتھ رکوع کیا، پھر آپ نے سجدہ فرمایا تو انھوں نے بھی آپ کے ساتھ سجدے کیے، پھر وہ گروہ بھی آگیا جو دشمن کے مقابل تھا۔ انھوں نے (اپنے طور پر) رکوع اور سجود کیے۔ (یعنی اپنی بقیہ رکعت پڑھ لی۔) رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ والے اس دوران میں بیٹھے رہے۔ پھر سلام کا وقت آیا تو رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیر دیا اور سب (دونوں گروہوں) نے سلام پھیردیا، اس طرح رسول اللہ صلی اللہ علیہ وسلم کی دو رکعتیں ہوگئیں اور دونوں گروہوں میں سے ہر ایک کی بھی دو رکعتیں ہوگئیں۔","f2":"(۱)یہ نماز خوف کی ایک اور صورت ہے۔ یہ اس وقت قابل عمل ہوگی جب خوف زیادہ نہ ہو کیونکہ شروع نماز میں بھی سب اکٹھے تھے اور آخر نماز میں بھی سب اکٹھے تھے، بلکہ آخر میں تو دشمن کے مقابل کوئی بھی نہ رہا۔ سب آپ کے پیچھے تھے۔ ایک گروہ اپنی نماز کی باقی رکعت پڑھ رہے تھے اور دوسرے ویسے آپ کے پیچھے بیٹھے تھے۔ سلام سب نے بیک وقت پھیرا۔ (۲)نجد اونچے علاقے کو کہتے ہیں اور یہ کئی علاقوں میں تھا، مثلاً: نجد حجاز، نجد عراق اور نجد یمن۔ مندرجہ بالا حدیث میں نجد سے نجد حجاز مراد ہے۔ اور بددعا والی حدیث میں نجد عراق۔ اس کا پتہ قرائن اور دیگر احادیث سے چلتا ہے۔"}],[1544,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ضجنان اور عسفان کے درمیان اترے آپ مشرکین کا محاصرہ کئے ہوئے تھے، مشرکین نے (آپس میں) کہا: ان لوگوں کی ایک ایسی نماز ہے جو انہیں اپنی اولاد اور اپنی بیویوں سے بھی زیادہ محبوب ہے، تو ایسا کرو تم سب تیار رہو (جب یہ نماز پڑھنے لگیں) تو یکبارگی ان پر پل پڑو، تو جبرائیل علیہ السلام (آپ کے پاس) آئے، اور انہوں نے آپ کو حکم دیا کہ آپ صحابہ کو دو حصوں میں بانٹ دیں، ان میں سے ایک گروہ کو آپ نماز پڑھائیں، اور ایک گروہ دشمن کے مقابل اپنے بچاؤ کی چیز اور اپنے ہتھیار لے کر کھڑا رہے، آپ انہیں ایک رکعت پڑھائیں، پھر یہ لوگ پیچھے ہٹ جائیں، اور وہ لوگ آگے آ جائیں جو دشمن کے مقابل ہوں، تو پھر آپ انہیں ایک رکعت پڑھائیں، تو لوگوں کی نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ایک ایک رکعت ہو گی، اور نبی اکرم صلی اللہ علیہ وسلم کی دو رکعتیں ہوں گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کوہ ضجنان اور عسفان کے درمیان قیام فرما تھے اور مشرکین کا محاصرہ کیے ہوئے تھے۔ مشرکوں نے کہا (پروگرام بنایا) کہ ان مسلمانوں کی ایک نماز ایسی ہے (نماز عصر) جو انھیں اپنے نوجوان بیٹوں اور بیٹیوں سے بھی زیادہ پیاری ہے تو تم بات طے کر لو (پختہ پروگرام بنالو) اور (اس نماز کے دوران میں) ان پر یکبارگی حملہ کردو۔ ادھر سے حضرت جبریل علیہ السلام تشریف لائے اور آپ کو حکم دیا کہ آپ اپنے صحابہ کے دوگروہ بنا دیں۔ آپ ان میں سے ایک گروہ کو نماز پڑھائیں اور دوسرا گروہ دشمن کی طرف متوجہ رہے۔ وہ محتاط رہیں اور اپنا اسلحہ پہنے رہیں۔ آپ پہلے گروہ کو ایک رکعت پڑھا دیں، پھر وہ پیچھے ہٹ جائیں (اور دشمن کے مقابل چلے جائیں) اور دوسرے آجائیں پھر ایک رکعت آپ ان کو پڑھا دیں تو اس طرح ان کی نبی صلی اللہ علیہ وسلم کے ساتھ ایک ایک رکعت ہوجائے گی اور نبی صلی اللہ علیہ وسلم کی دو رکعتیں ہوجائیں گی۔","f2":"ظاہر الفاظ سے یہی معلوم ہوتا ہے کہ دونوں گروہوں نے ایک ایک رکعت ہی پر اکتفا کیا، البتہ اس بات کا بھی احتمال ہے کہ انھوں نے دوسری رکعت اپنے طور پر پڑھی ہو کیونکہ الفاظ حدیث: ’’نبی صلی اللہ علیہ وسلم کے ساتھ‘‘ سے اس کا اشارہ ملتا ہے۔ سنن نسائی کے شارح شیخ اتیوبی صلی اللہ علیہ وسلم نے اپنی شرح ذخیرۃ العقبٰی میں پہلی بات کو زیادہ قوی قرار دیا ہے۔ واللہ اعلم: دیکھیے: (ذخیرۃ العقبٰی، شرح سنن النسائی: ۱۷؍۱۳۴)"}],[1545,"جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو خوف کی نماز پڑھائی، تو ایک صف آپ کے آگے کھڑی ہوئی، اور ایک صف آپ کے پیچھے، آپ نے ان لوگوں کے ساتھ جو آپ کے پیچھے تھے ایک رکوع اور دو سجدے کئے، پھر یہ لوگ آگے چلے گئے یہاں تک کہ جا کر اپنے ساتھیوں کی جگہ میں کھڑے ہو گئے، اور وہ لوگ آ کر ان لوگوں کی جگہ کھڑے ہو گئے، اور رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ (بھی) ایک رکوع اور دو سجدے کئے، پھر آپ نے سلام پھیرا، تو نبی کریم صلی اللہ علیہ وسلم کی دو رکعتیں ہوئیں، اور لوگوں کی ایک ایک۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز خوف پڑھائی۔ ایک صف آپ کے آگے (دشمن کے مقابل) کھڑی ہوگئی اور دوسری آپ کے پیچھے۔ آپ نے اپنے پیچھے کھڑے ہونے والوں کو ایک رکوع اور دوسجدے، یعنی ایک رکعت پڑھائی، پھر یہ آگے چلے گئے اور اپنے ساتھیوں کی جگہ کھڑے ہوگئے اور وہ آگئے اور (آپ کے پیچھے) ان کی جگہ کھڑے ہوگئے۔ رسول اللہ صلی اللہ علیہ وسلم نے انھیں بھی ایک رکوع اور دو سجدے، یعنی ایک رکعت پڑھائی، پھر آپ نے سلام پھیر دیا۔ اس طرح نبی صلی اللہ علیہ وسلم کی دو رکعتیں ہوگئیں اور ان کی ایک ایک۔"}],[1546,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ ہم (ایک غزوہ میں) رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھے (نماز کا وقت ہوا) تو نماز کھڑی کی گئی، رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور آپ کے پیچھے ایک گروہ کھڑا ہوا، اور ایک گروہ دشمن کے مقابل کھڑا رہا، آپ نے ان لوگوں کے ساتھ جو آپ کے پیچھے تھے ایک رکوع اور دو سجدے کیے، پھر وہ چلے گئے، اور ان لوگوں کی جگہ آ کر کھڑے ہو گئے جو دشمن کے بالمقابل تھے، اور وہ گروہ آیا، رسول اللہ صلی اللہ علیہ وسلم نے ان کے ساتھ بھی ایک رکوع اور دو سجدے کئے، پھر رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، تو آپ کے پیچھے والوں نے بھی سلام پھیرا، اور ان لوگوں نے بھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (ایک جنگ میں) تھے۔ نماز کی اقامت ہوئی تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے اور مسلمانوں کا ایک گروہ بھی آپ کے پیچھے کھڑا ہوگیا جبکہ دوسرا گروہ دشمن کے مقابل رہا۔ آپ نے اپنے پیچھے کھڑے ہونے والوں کو ایک رکوع اور دو سجدے، یعنی ایک رکعت پڑھائی، پھر وہ چلے گئے اور ان لوگوں کی جگہ کھڑے ہوگئے جو دشمن کے مقابلے میں تھے اور وہ دوسرا گروہ آگیا۔ آپ نے انھیں بھی ایک رکوع اور دوسجدے، یعنی ایک رکعت پڑھائی، پھر رسول اللہ صلی اللہ علیہ وسلم نے سلام پھیرا، آپ کے پیچھے والے لوگوں نے بھی اور دوسروں نے بھی سلام پھیرا۔"}],[1547,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ خوف کی نماز میں موجود تھے، ہم آپ کے پیچھے کھڑے ہوئے، اور ہم نے دو صفیں کیں، اور دشمن ہمارے اور قبلہ کے درمیان تھا، رسول اللہ صلی اللہ علیہ وسلم نے تکبیر (تکبیر تحریمہ) کہی، اور ہم نے بھی کہی، آپ نے رکوع کیا ہم نے بھی رکوع کیا، آپ(رکوع سے) اٹھے اور ہم بھی اٹھے، پھر جب آپ سجدے کے لیے جھکے تو رسول اللہ صلی اللہ علیہ وسلم نے اور ان لوگوں نے جو آپ کے قریب (یعنی پہلی صف میں)تھے سجدہ کیا، اور دوسری صف اس وقت تک کھڑی رہی جب تک رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ والی صف نے سر اٹھایا، پھر دوسری صف نے جس وقت رسول اللہ صلی اللہ علیہ وسلم نے سر اٹھایا، اپنی جگہوں پر سجدہ کیا، پھر جو صف نبی اکرم صلی اللہ علیہ وسلم سے قریب تھی پیچھے ہٹ گئی، اور پیچھے والی صف آگے آ گئی، اور آ کر ان کی جگہوں میں کھڑی ہو گئی، اور یہ لوگ پچھلے والوں کی جگہوں میں جا کر کھڑے ہو گئے، پھر نبی اکرم صلی اللہ علیہ وسلم نے رکوع کیا، اور ہم نے بھی رکوع کیا، پھر آپ نے رکوع سے سر اٹھایا اور ہم نے بھی اٹھایا، پھر جب آپ سجدے کے لیے جھکے تو ان لوگوں نے سجدہ کیا جو آپ سے قریب تھے، اور دوسرے کھڑے رہے، پھر جب رسول اللہ صلی اللہ علیہ وسلم نے اور ان لوگوں نے جو آپ سے قریب تھے (سجدے سے سر) اٹھایا تو دوسروں نے سجدہ کیا، پھر آپ نے سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نمازخوف میں حاضر ہوئے۔ ہم آپ کے پیچھے دو صفوں میں کھڑے ہوگئے۔ دشمن ہمارے اور قبلے کے درمیان تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اللہ اکبر کہا، ہم سب نے بھی اللہ اکبر کہا پھر آپ نے رکوع کیا تو ہم نے بھی رکوع کیا، پھر آپ نے سر اٹھایا تو ہم نے بھی (رکوع سے) سر اٹھایا، پھر جب آپ سجدے کے لیے جھکے تورسول اللہ صلی اللہ علیہ وسلم نے سجدہ کیا اور ان لوگوں نے بھی جو آپ کے ساتھ قریبی (پہلی) صف میں تھے جبکہ دوسری صف والے کھڑے رہے، جب رسول اللہ صلی اللہ علیہ وسلم نے (سجدے سے) سر اٹھایا اور اس صف والوں نے جو آپ کے قریب تھی تو دوسری صف نے اپنی جگہ ہی اپنے سجدے ادا کیے، پھر نبی صلی اللہ علیہ وسلم کے ساتھ والی صف والے پیچھے ہٹ گئے اور دوسرے صف والے آگے ہوکر پہلی صف والوں کی جگہ کھڑے ہوگئے اور وہ ان کی جگہ کھڑے ہوگئے، پھر (دوسری رکعت میں) نبی صلی اللہ علیہ وسلم نے رکوع فرمایا تو ہم نے بھی آپ کے ساتھ رکوع کیا، پھر آپ نے (رکوع سے) سر اٹھایا تو سب نے بھی (رکوع سے) سر اٹھایا۔ جب آپ سجدے کے لیے زمین کی طرف جھکے تو آپ کے ساتھ والی صف نے سجدے کیے اور دوسری صف والے کھڑے رہے، پھر جب رسول اللہ صلی اللہ علیہ وسلم اور آپ کے ساتھ والوں نے اپنے طور پر سجدے کرلیے، پھر آپ نے (سب کے ساتھ بیک وقت) سلام پھیر دیا۔"}],[1548,"جابر رضی اللہ عنہ کہتے ہیں کہ ہم لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ کچھ کھجور کے باغات میں تھے، اور دشمن ہمارے اور قبلہ کے درمیان تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے تکبیر تحریمہ کہی، تو سبھوں نے تکبیر تحریمہ کہی، پھر آپ نے رکوع کیا، تو سبھوں نے رکوع کیا، پھر نبی اکرم صلی اللہ علیہ وسلم نے اور اس صف نے جو آپ سے قریب تھی سجدہ کیا، اور دوسرے لوگ کھڑے ان کی حفاظت کرتے رہے، پھر جب وہ کھڑے ہو گئے تو دوسروں نے بھی اپنی جگہوں پر جہاں وہ تھے سجدہ کیا، پھر وہ لوگ ان لوگوں کی جگہ پر آگے آ گئے ۱؎ پھر آپ نے رکوع کیا، تو سبھوں نے ایک ساتھ رکوع کیا، پھر آپ نے (رکوع سے سر) اٹھایا تو سبھوں نے سر اٹھایا، پھر نبی اکرم صلی اللہ علیہ وسلم نے سجدہ کیا، اور اس صف نے جو آپ سے قریب تھی، اور دوسرے لوگ کھڑے ان کی پہریداری کرتے رہے، پھر جب وہ لوگ سجدہ کر چکے اور (سجدہ کے بعد) بیٹھ گئے، تو دوسروں نے بھی اپنی جگہوں میں سجدہ کیا، پھر آپ نے سلام پھیرا، جابر رضی اللہ عنہ نے کہا: جس طرح تمہارے امراء کرتے ہیں، (یعنی سلام پھیرتے ہیں)۔\n§وضاحت\n۱؎: یعنی رسول اللہ صلی اللہ علیہ وسلم کے قریب آ گئے، اور جو لوگ آپ سے قریب تھے ان کی جگہ پر چلے گئے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے ہیں کہ ہم مقام نخل (مدینے سے دورات کے فاصلے پر) میں نبی صلی اللہ علیہ وسلم کے ساتھ تھے جبکہ دشمن ہمارے اور قبلے کے درمیان تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے تکبیر تحریمہ کہی تو سب مسلمانوں نے تکبیر تحریمہ کہی، پھر آپ نے رکوع فرمایا تو ان سب نے بھی رکوع کیا، پھر نبی صلی اللہ علیہ وسلم اور آپ کے ساتھ والی صف نے سجدہ کیا جبکہ دوسری صف والے کھڑے ان کی حفاظت کرتے رہے، پھر جب وہ سجدوں کے بعد اٹھے تو پچھلی صف والوں نے اپنی جگہ ہی میں سجدے (مکمل) کرلیے، پھر یہ ان کی جگہ چلے گئے (اور وہ آگئے۔) پھر آپ نے (دوسری رکعت کا) رکوع کیا تو سب نے رکوع کیا۔ پھر آپ نے سر اٹھایا تو ان سب نے بھی اپنے سر اٹھائے، پھر نبی صلی اللہ علیہ وسلم اور آٓپ کے ساتھ والی صف نے سجدہ کیا اور دوسرے کھڑے ان کی حفاظت کرتے رہے۔ جب وہ سجدوں سے فارغ ہوکر بیٹھ گئے تو پچھلی صف والوں نے اپنی جگہ ہی میں سجدے کرلیے، پھر آپ نے سلام پھیرا۔\nحضرت جابر رضی اللہ عنہ فرماتے ہیں کہ جیسے تمھارے امراء (کے پہرے دار) کرتے ہیں۔"}],[1549,"ابوعیاش زرقی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم مقام عسفان میں دشمن کے مقابلہ میں صف آرا تھے، مشرکین کی کمان خالد بن ولید رضی اللہ عنہ کے ہاتھ میں تھی، نبی اکرم صلی اللہ علیہ وسلم نے لوگوں کو ظہر کی نماز پڑھائی، تو مشرک آپ سے میں کہنے لگے کہ ان کی اس نماز کے بعد جو نماز ہے وہ انہیں اپنے اموال و اولاد سے بھی زیادہ محبوب ہے، (چنانچہ جب عصر کا وقت ہوا) تو رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو عصر کی نماز پڑھائی، تو آپ نے اپنے پیچھے ان کی دو صفیں بنائیں، پھر آپ نے ان سبھوں کے ساتھ رکوع کیا، پھر جب لوگوں نے اپنے سروں کو رکوع سے اٹھا لیا تو (آپ کے ساتھ) اس صف نے سجدہ کیا جو آپ سے قریب تھی، اور دوسرے کھڑے رہے، پھر جب ان لوگوں نے اپنے سروں کو سجدے سے اٹھا لیا تو پچھلی صف نے بھی سجدہ کیا اپنے اس رکوع کے ساتھ جسے انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کیا تھا، پھر پہلی صف پیچھے چلی گئی، اور پچھلی صف آگے بڑھ آئی، ان میں سے ہر ایک اپنے ساتھی کی جگہ پر کھڑا ہو گیا، پھر رسول اللہ صلی اللہ علیہ وسلم نے سبھوں کے ساتھ مل کر رکوع کیا، پھر جب لوگوں نے رکوع سے اپنے سر اٹھا لیے تو وہ صف جو آپ سے قریب تھی سجدہ میں گئی، اور دوسرے لوگ کھڑے رہے، پھر جب یہ لوگ سجدے سے فارغ ہو گئے، تو دوسروں نے سجدہ کیا، پھر نبی اکرم صلی اللہ علیہ وسلم نے سبھوں کے ساتھ سلام پھیرا۔\n§وضاحت\n۱؎: \"مقام عسفان\" مکہ اور مدینہ کے درمیان ایک جگہ کا نام ہے۔","الألباني: صحيح",{"u2":"حضرت ابوعیاش زرقی رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم عسفان کے علاقے میں دشمن کے ساتھ جنگ کی حالت میں تھے۔ مشرکین کے امیر خالد بن ولید تھے۔ (جو اس وقت مسلمان نہیں ہوئے تھے۔) نبی صلی اللہ علیہ وسلم نے مسلمانوں کو ظہر کی نماز پڑھائی تو مشرکین نے کہا: اس نماز کے بعد ایک ایسی نماز ہے (نماز عصر) جو ان مسلمانوں کو اپنے مال و منال اور اولاد سے بھی زیادہ پیاری ہے۔ (لہٰذا اس نماز میں ان پر حملہ کردو۔) تو رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو عصر کی نماز اس طرح پڑھائی کہ اپنے پیچھے ان کی دو صفیں بنالیں، پھر آپ نے ان سب کے ساتھ رکوع کیا، پھر جب انھوں نے رکوع سے سر اٹھایا (اورآپ سجدے میں گئے) تو آپ کے ساتھ والی (یعنی پہلی) صف ہی نے سجدے کیے اور دوسری صف والے کھڑے رہے۔ جب انھوں نے سجدوں سے سر اٹھائے تو دوسری صف نے سجدے کیے جبکہ رکوع تو وہ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ کر چکے تھے، پھر اگلی صف پیچھے ہوگئی اور پچھلی آگے اور وہ ایک دوسرے کی جگہ میں کھڑے ہوگئے، پھر اللہ کے رسول صلی اللہ علیہ وسلم نے ان سب کے ساتھ رکوع کیا۔ جب انھوں نے رکوع سے سر اٹھائے تو آپ کے ساتھ صرف آپ کے ساتھ والی صف نے سجدے کیے جبکہ دوسرے کھڑے رہے، پھر جب وہ اپنے سجدوں سے فارغ ہوئے تو پچھلی صف والوں نے (اپنے) سجدے ادا کیے، پھر نبی صلی اللہ علیہ وسلم نے ان سب کے ساتھ بیک وقت سلام پھیرا۔"}],[1550,"ابوعیاش زرقی رضی اللہ عنہ کہتے ہیں کہ ہم لوگ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ مقام عسفان میں تھے، آپ صلی اللہ علیہ وسلم نے ہمیں ظہر کی نماز پڑھائی، اس وقت مشرکین کی کمان خالد بن ولید رضی اللہ عنہ کر رہے تھے، مشرکوں نے (آپ سے میں) کہا: ہم نے انہیں دھوکہ دینے اور انہیں غفلت میں (دبوچنے کا)موقع پا لیا ہے، تو ظہر اور عصر کے درمیان خوف کی نماز نازل ہوئی، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز عصر پڑھائی تو ہم دو گروہوں میں بٹ گئے، ایک گروہ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھنے لگا، اور ایک گروہ ان کی حفاظت کرتا رہا، آپ نے جو آپ کے ساتھ کھڑے تھے، اور جو آپ کی حفاظت میں لگے تھے سبھوں کے ساتھ تکبیر تحریمہ کہی، پھر آپ نے رکوع کیا، تو ان لوگوں نے اور ان لوگوں نے سبھوں نے ایک ساتھ رکوع کیا، پھر جو آپ کے قریب تھے ان لوگوں نے سجدہ کیا، اور سجدہ کر کے وہ پیچھے ہٹ گئے اور پیچھے والے آگے بڑھ آئے، پھر انہوں نے سجدہ کیا، پھر آپ کھڑے ہوئے، پھر جو آپ کے قریب تھے اور جو آپ کی حفاظت کر رہے تھے سبھوں کے ساتھ مل کر آپ نے دوسرا رکوع کیا، پھر آپ نے اپنے پاس والوں کے ساتھ سجدہ کیا، پھر وہ لوگ پیچھے ہٹ گئے، اور اپنے ساتھیوں کی صف میں کھڑے ہو گئے اور پیچھے والے آگے بڑھ آئے اور انہوں نے سجدہ کیا، پھر آپ نے ان پر سلام پھیرا، تو ان میں سے ہر ایک کی امام کے ساتھ دو دو رکعت ہو گئی، اور ایک بار آپ نے بنی سلیم کی سر زمین میں (بھی) خوف کی نماز پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابوعیاش زرقی رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عسفان کے مقام پر تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ظہر کی نماز پڑھائی۔ ان دنوں مشرکین کے امیر خالد بن ولید تھے۔ مشرکین نے کہا: افسوس! ہم نے انھیں غافل پایا تھا۔ (کاش ہم حملہ کردیتے) تو ظہر اور عصر کے درمیان نماز خوف کا حکم اترا۔ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے اس طرح عصر کی نماز پڑھائی کہ ہمارے دو گروہ بنادیے۔ ایک گروہ نبی صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتا تھا اور دوسرا گروہ ان کی حفاظت کرتا تھا۔ آپ نے سب کے ساتھ تکبیر کہی، جو آپ کے ساتھ تھے اور جو ان کی حفاظت کرتے تھے، پھر آپ نے رکوع فرمایا تو دونوں گروہوں نے رکوع کیا، پھر آپ کے ساتھ والے گروہ نے سجدے کیے، پھر ساتھ والے پیچھے ہٹ آئے اور دوسرے آگے بڑھے اور انھوں نے اپنے سجدے مکمل کیے، پھر آپ (دوسری رکعت کے لیے) اٹھے اور سب کے ساتھ رکوع کیا، جو آپ کے ساتھ تھے اور جو ان کی حفاظت کرتے تھے، پھر آپ نے اپنے ساتھ والوں کے ساتھ سجدے کیے، پھر وہ پیچھے ہٹ گئے اور اپنے دوسرے ساتھیوں کی جگہ میں کھڑے ہوگئے اور دوسرے آگے بڑھے اور انھوں نےاپنے سجدے پورے کیے، پھر آپ نے سب کے ساتھ سلام پھیرا۔ اس طرح ان میں سے ہر ایک کی اپنے امام کے ساتھ دو دو رکعتیں ہوگئیں، اور ایک دفعہ آپ نے بنوسلیم کے علاقے میں نمازخوف پڑھی تھی۔","f2":"سابقہ روایت سے یہ روایت اس بات میں مختلف ہے کہ ان میں پچھلی صف والے اپنی جگہ میں سجدے ادا کرکے پھر اگلی صف میں آتے تھے مگر اس روایت میں پچھلی صف والوں نے اگلی صف میں آکر اپنے سجدے پورے کیے۔ اگر یہ راوی کی غلط فہمی نہیں تو یہ نماز خوف کی ایک اور صورت بن جائے گی۔ واللہ اعلم۔"}],[1551,"ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے کچھ لوگوں کو خوف کی نماز دو رکعت پڑھائی، پھر آپ نے سلام پھیر دیا، پھر آپ نے دوسرے لوگوں کو دو رکعت پڑھائی، پھر آپ نے سلام پھیر دیا، تو نبی اکرم صلی اللہ علیہ وسلم نے چار رکعت پڑھی (اور لوگوں نے دو دو رکعت)۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک گروہ کو نماز خوف دو رکعت پڑھائی، پھر سلام پھیر دیا، پھر دوسرے گروہ کو دو رکعتیں پڑھائیں اورپھر سلام پھیر دیا۔ اس طرح نبی صلی اللہ علیہ وسلم نے چار رکعات پڑھیں۔","f2":"یہ نماز خوف کی ایک اور صورت ہے جو سادہ ہے مگر احناف کے نزدیک یہ صورت جائز نہیں ہے کیونکہ بعد والی اور دو رکعتیں امام صاحب کی نفل ہوں گی اور دوسرے گروہ کی فرض۔ اور احناف کے نزدیک نفل پڑھنے والے کے پیچھے فرض جائز نہیں۔ خیر! احناف کے نزدیک، خواہ یہ صورت درست نہ ہو مگر رسول اللہ صلی اللہ علیہ وسلم نے تو پڑھائی ہے اور عمل آپ کی سنت پر ہے۔ اس سے یہ بھی معلوم ہوتا ہے کہ اگر امام کو دوبارہ نماز پڑھانی پڑ جائے تو کوئی حرج نہیں، سب کی نماز درست ہوگی۔"}],[1552,"جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے اپنے صحابہ میں سے ایک گروہ کو (خوف کی نماز) دو رکعت پڑھائی، پھر سلام پھیر دیا، پھر دوسرے لوگوں کو بھی آپ نے دو رکعت پڑھائی، پھر آپ نے سلام پھیرا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے صحابہ میں سے ایک گروہ کو دو رکعتیں پڑھائیں، پھر سلام پھیرا، پھر دوسرے گروہ کو بھی دو رکعتیں پڑھائیں، پھر سلام پھیرا۔"}],[1553,"سہل بن ابی حثمہ رضی اللہ عنہ نماز خوف کے سلسلہ میں کہتے ہیں امام قبلہ رو کھڑا ہو گا، اور اس کے لشکر میں سے ایک گروہ اس کے ساتھ کھڑا ہو گا، اور ایک گروہ دشمن کے سامنے رہے گا، ان کے چہرے دشمن کی طرف ہوں گے، پھر امام ان کے ساتھ ایک رکعت پڑھے گا، اور ایک رکوع اور دو سجدے وہ خود سے اپنی جگہوں پر کریں گے، اور ان لوگوں کی جگہ میں چلے جائیں گے، پھر وہ لوگ آئیں گے، تو امام ان کے ساتھ (بھی) ایک رکوع اور دو سجدے کرے گا، تو (اس طرح) اس کی دو رکعتیں ہوں گی، اور ان لوگوں کی ایک ہو گی، تو پھر یہ لوگ ایک ایک رکوع اور دو دو سجدے کریں گے۔","الألباني: صحيح",{"u2":"حضرت سہل بن ابی حثمہ رضی اللہ عنہ سے نماز خوف کے بارے میں روایت ہے کہ امام قبلہ رخ کھڑا ہو، اور مقتدیوں میں سے ایک گروہ اس کے ساتھ کھڑا ہو جائے اور دوسرا گروہ دشمن کے مقابل ان کی طرف منہ کرکے کھڑا رہے۔ تو امام پہلے گروہ کو ایک رکعت پڑھادے، پھر وہ اپنی جگہ کھڑے ہوکر دوسری رکعت کے رکوع سجدے ادا کرلیں۔ اور دوسروں کی جگہ چلے جائیں اور وہ آجائیں تو امام انھیں بھی رکوع اور دو سجدے پڑھادے۔ اس طرح امام کی دو رکعتیں ہوجائیں گی اور ان کی ایک رکعت، پھر وہ خود دوسری رکعت کے رکوع اور دو سجدے ادا کرلیں۔","f2":"یہ صورت اجمالاً اور صراحتاً پیچھے گزر چکی ہے۔ دیکھیے حدیث نمبر: ۱۵۳۷ اور ۱۵۳۸۔"}],[1554,"جابر بن عبداللہ رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کو خوف کی نماز پڑھائی، تو ایک گروہ نے آپ کے ساتھ نماز پڑھی، اور ایک گروہ کے چہرے دشمن کے مقابل رہے، تو آپ نے انہیں دو رکعت پڑھائی، پھر وہ لوگ اٹھ کر دوسرے لوگوں کی جگہ میں جا کھڑے ہوئے، اور دوسرے ان کی جگہ آ گئے تو آپ نے انہیں (بھی) دو رکعت پڑھائی، پھر آپ نے سلام پھیر دیا۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنے صحابہ کو نمازخوف پڑھائی۔ ان میں سے ایک گروہ نے آپ کے ساتھ نماز پڑھی اور دوسرے گروہ کے چہرے دشمن کی طرف تھے۔ تو آپ نے ایک گروہ کو دو رکعت پڑھا دیں، پھر وہ دوسرے گروہ کی جگہ چلے گئے اور دوسرے آگئے۔ آپ نے انھیں بھی دو رکعتیں پڑھائیں اور سلام پھیر دیا۔"}],[1555,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے ان لوگوں کو جو آپ کے پیچھے تھے انہیں نماز خوف دو رکعت پڑھائی، اور جو اس کے بعد آئے انہیں بھی دو رکعت پڑھائی، تو (اس طرح) نبی اکرم صلی اللہ علیہ وسلم کی چار رکعت ہوئی، اور لوگوں کی دو دو رکعت ہوئی۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے اپنے پیچھے کھڑے لوگوں کو دو رکعتیں پڑھائیں، پھر جوان کے بعد آئے، انھیں بھی دو رکعتیں پڑھائیں۔ تو نبی صلی اللہ علیہ وسلم کی چار رکعتیں ہوگئیں اور ان کی دو دو۔","f2":"ان دو روایات میں پہلی دو رکعات کے بعد سلام پھیرنے کا ذکر نہیں جبکہ احادیث: ۱۵۵۲ اور ۱۵۵۳ میں الگ الگ سلام کا ذکر ہے اور وہ روایات بھی انھی بزرگوں سے ہیں، لہٰذا یہاں بھی ہر دو کے بعد سلام مانا جائے گا گویا کہ رسول اللہ صلی اللہ علیہ وسلم کی چار رکعات دوسلام کے ساتھ تھیں۔ کہا جاسکتا ہے کہ یہ بھی ایک صورت ہے کہ امام ایک سلام کے ساتھ چار رکعات پڑھائے مگر یہ مرجوح بات ہے۔"}],[1556,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ جاہلیت کے لوگوں کے لیے سال میں دو دن ایسے ہوتے تھے جن میں وہ کھیل کود کیا کرتے تھے، جب نبی اکرم صلی اللہ علیہ وسلم (مکہ سے ہجرت کر کے) مدینہ آئے تو آپ نے فرمایا: \"تمہارے لیے دو دن تھے جن میں تم کھیل کود کیا کرتے تھے (اب) اللہ تعالی نے تمہیں ان کے بدلہ ان سے بہتر دو دن دے دیئے ہیں: ایک عید الفطر کا دن اور دوسرا عید الاضحی کا دن\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ دور جاہلیت کے لوگوں کے لیے سال میں دو دن تھے جن میں وہ کھیلتے کودتے تھے۔ جب نبی صلی اللہ علیہ وسلم مدینہ منورہ تشریف لائے تو آپ نے فرمایا: ’’تمھارے لیے دودن تھے جن میں تم کھیلا کودا کرتے تھے۔ اب اللہ تعالیٰ نے تمھیں ان کے بجائے دو اچھے دن دے دیے ہیں۔ ایک عیدالفطر کا دن اور ایک عیدالاضحیٰ کا دن۔‘‘","f2":"(۱)’’دودن‘‘ سے نوروز اورمہرجان مراد ہیں۔ نوروز تو نئے سال کا پہلا دن ہوتا تھا اور مہرجان موسم بہار کی مناسبت سے جشن کی صورت میں منایا جاتا تھا۔ یہ دونوں ایرانیوں کی عیدیں تھیں۔ عرب صرف نقالی کے طور پر انھیں مناتے تھے۔ (۲)’’دو اچھے دن‘‘ کیونکہ ان کا تعلق نہ تو موسم کی خوش گواری سے ہے، نہ کسی بادشاہ کی تاجپوشی سے، بلکہ ان کا تعلق دو عظیم عبادات کی ادائیگی سے ہے، لہٰذا ان میں بجائے لہوولعب کے عبادت، تشکر اور دعا کی حکمرانی ہوگی۔ باقی رہی خوشی تو یہ ایک ذہنی چیز ہے۔ ایک کھلنڈرا شخص جس طرح کھیل کود میں خوش ہوتا ہے، مومن اس طرح بلکہ اس سے بڑھ کر عبادت میں لذت محسوس کرتا ہے، پھر لہوولعب کی خوشی تو صرف امراء کے ساتھ خاص ہے مگر عبادت کی خوشی میں امیرغریب سب شریک ہوسکتے ہیں۔ عبادات کی ادائیگی کے بعد مناسب کھیل کود میں بھی کوئی حرج نہیں، جیسے بچیوں کا دف بجانا اور حبشیوں کا جنگی کھیل کھیلنا احادیث سے ثابت ہے۔ مگر ایسی خوشی جس کی بنیاد فخروغرور اور دولت کی نمائش و اسراف پر ہو ایک فطری دین کے سراسر خلاف ہے۔ (۳)’’عید‘‘ عود سے ہے، یعنی بار بار پلٹ کے آنے والی چیز، ظاہر ہے عید بار بار آتی ہے، نیز ہر آدمی ان سے بار بار لطف اندوز ہونے کی خواہش رکھتا ہے اور ایک دوسرے کو ’’کئی عیدوں‘‘ کی دعا بھی دی جاتی ہے۔ (۴)اس حدیث سے یہ بھی واضح ہوا کہ مسلمانوں کی صرف دو ہی عیدیں ہیں، تیسری کوئی عید نہیں، اس لیے ’’عیدمیلاد‘‘ کی کوئی شرعی حیثیت نہیں، یہ بدعت اور خانہ ساز ہے۔ اس کے جواز کے لیے جو ’’دلائل‘‘ دیے جاتے ہیں، ان کی حقیقت جاننے کے لیے ملاحظہ ہو، حافظ صلاح الدین یوسف رحمہ اللہ کی تالیف ’’جشن عیدمیلاد اور مجوزین کے دلائل کا جائزہ۔‘‘"}],[1557,"ابو عمیر بن انس اپنے ایک چچا سے روایت کرتے ہیں کہ کچھ لوگوں نے عید کا چاند دیکھا تو وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے (اور آپ سے اس کا ذکر کیا) آپ نے انہیں دن چڑھ آنے کے بعد حکم دیا کہ وہ روزہ توڑ دیں، اور عید کی نماز کی لیے کل نکلیں۔","الألباني: صحيح",{"u2":"حضرت ابوعمیر بن انس اپنے چچائوں سے بیان کرتے ہیں کہ کچھ لوگوں نے عید کا چاند دیکھا (مگر نبی صلی اللہ علیہ وسلم کو بروقت اطلاع نہ مل سکی اور عام لوگوں نے روزہ رکھ لیا)، پھر وہ نبی صلی اللہ علیہ وسلم کے پاس آئے (اور اطلاع کی) تو آپ نے لوگوں کو دن چڑھ آنے کے بعد روزہ کھولنے کا اور اگلے دن نماز (عید) کے لیے نکلنے کا حکم دیا۔","f2":"(۱)’’روزہ کھول دینے کا حکم دیا‘‘ گویا ضروری نہیں کہ سب لوگ یا ہر شہر اور بستی والے چاند دیکھیں بلکہ کچھ لوگ چاند دیکھ لیں تو وہ دوسرے لوگوں اور شہروں کے لیے بھی کافی ہوگا۔ ظاہر یہی ہے کہ چاند دیکھنے والے مذکورہ لوگ مدینہ سے باہر کے ہوں گے ورنہ وہ رات کے وقت ہی آپ کو اطلاع کردیتے۔ اگر مدینے سے باہر والے لوگوں کا چاند دیکھنا مدینہ منورہ والوں کے لیے کافی ہے تو دیگر شہروں کے لیے بھی یہی حکم ہوگا، الایہ کہ مطلع میں اتنا فرق ہو کہ چاند نظر آنے میں ایک دن یا زائد کا فرق ممکن ہو۔ اس صورت میں ان کا حساب الگ ہوگا۔ یہ بھی معلوم ہوا کہ چاند کی اطلاع جب بھی ملے، اس پر عمل کرنا واجب ہے۔ روزہ رکھنے کی صورت میں اسے کھولنا واجب ہوگا۔ اگر اسی دن عید پڑھنا ممکن ہو تو اسی دن زوال سے قبل عید پڑھی جائے گی اور اگر زوال سے پہلے عید پڑھنا ممکن نہ ہو تو اگلے دن عید کی نماز ادا کی جائے گی۔ چونکہ چاند کی رؤیت میں عموماً ایک ہی دن کا فرق ممکن ہے، لہٰذا ایک دن سے زائد نماز عید مؤخر نہ کی جائے۔ احادیث میں بھی ایک ہی دن کا ذکر ہے۔ اس مسئلے میں دونوں عیدیں برابر ہیں۔ (۲) اگر بارش یا اندھیری وغیرہ کی وجہ سے اصل دن عید پڑھنا ممکن نہ ہو تو بھی یہی حکم ہے۔ (۳)’’نماز عید کے لیے نکلنے کا‘‘ اصل یہی ہے کہ نماز عید آبادی سے باہر کھلے میدان میں پڑھی جائے کہ اس میں شان و شوکت کا زیادہ اظہار ہے۔ اور یہ بھی عید کا ایک مقصدہے۔ بعض حضرات نے اس حکم کی علت یہ قرار دی ہے کہ چونکہ مسجد میں پوری آبادی کے لوگ سما نہیں سکتے، اس لیے جگہ کی تنگی کے پیش نظر باہر نکلنے کا حکم دیا۔ گویا اگر کہیں مسجد اور اس کے ساتھ اتنی جگہ خالی ہو کہ تمام لوگ اس میں آرام سے نماز پڑھ سکیں تو نماز عید مسجد میں بھی پڑھی جاسکتی ہے جیسا کہ حرمین (بیت اللہ شریف اور مسجد نبوی شریف) میں ہوتا ہے۔ مگر ضروری نہیں کہ مذکورہ حکم کی علت یہی ہو، لہٰذا سنت نبوی پر عمل ہی اولیٰ ہے۔ واللہ اعلم۔"}],[1558,"حفصہ بنت سرین کہتی ہیں کہ ام عطیہ رضی اللہ عنہا جب بھی رسول اللہ صلی اللہ علیہ وسلم کا ذکر کرتیں تو کہتی تھیں: \"میرے باپ آپ پر فدا ہوں\" تو میں نے ان سے پوچھا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو ایسا ایسا ذکر کرتے سنا ہے؟ تو انہوں نے کہا: ہاں، میرے باپ آپ پر فدا ہوں، آپ نے فرمایا: \"چاہیئے کہ دوشیزائیں، پردہ والیاں، اور جو حیض سے ہوں (عید گاہ کو) نکلیں اور سب عید میں اور مسلمانوں کی دعا میں شریک رہیں، البتہ جو حائضہ ہوں وہ صلاۃ گاہ سے الگ رہیں\"۔","الألباني: صحيح",{"u2":"حضرت حفصہ (بنت سیرین) سے روایت ہے کہ حضرت ام عطیہ رضی اللہ عنہا جب بھی رسول اللہ صلی اللہ علیہ وسلم کا ذکر کرتی تھیں تو [بابا] ’’میرا باپ آپ پر فدا ہوجائے‘‘ ضرور کہتی تھیں۔ (ایک دفعہ) میں نے ان سے کہا: کیا آپ نے رسول اللہ صلی اللہ علیہ وسلم کو ایسے ایسے (یعنی عیدین میں عورتوں کے باہر جانے کے بارے میں) فرماتے سنا ہے؟ تو انھوں نے کہا: ہاں، [بابا] آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بالغ اور پردہ نشین حتی کہ حیض والی عورتیں بھی باہر عید کے لیے جائیں اور نماز عید اور مسلمانوں کی دعا میں شریک ہوں، البتہ حیض والی عورتیں نماز والی جگہ سے الگ بیٹھی رہیں۔‘‘","f2":"(۱)تمام صحابہ و صحابیات رضی اللہ عنھن رسول اللہ صلی اللہ علیہ وسلم سے بے پناہ محبت رکھتے تھے اور اپنی ہر چیز آپ پر فدا کرنے کے لیے تیار رہتے تھے۔ مگر مذکورہ صحابیہ کا یہ خصوصی اظہارِ عقیدت تھا کہ آپ کے غائبانہ ذکر پر بھی [بابا] جیسا پیار لفظ بولتی تھیں۔ ویسے صحابہ عموماً نبی صلی اللہ علیہ وسلم سے خطاب کے وقت [بابی انت ومی یا رسول اللہ] ’’اے اللہ کے رسول! میرے ماں باپ آپ پر فد اہوجائیں‘‘ کے الفاظ سے اظہار محبت فرمایا کرتے تھے۔ رضی اللہ عنھم وارضاھم۔ (۲)عید خوشی اور شان و شوکت، نیز تشکرودعا کا خاص موقع ہے، اس لیے اس میں مردوں اور عورتوں سب کو حاضری کا حکم دیا حتیٰ کہ نماز نہ پڑھنے والی عورتوں کو بھی حاضری کی تاکید کی گئی تاکہ عید کے دیگر مقاصد پورے ہوسکیں۔ معلوم ہوا عید مسلمانوں کا شعار (خصوصی نشان) ہے۔ عوام الناس کے نزدیک بھی عید میں بلاوجہ شریک نہ ہونے والا اچھی نگاہ سے نہیں دیکھا جاتا۔ (۳)’’الگ بیٹھی رہیں‘‘ اس سے استدلال کیا گیا ہے کہ یہاں نماز والی جگہ کو مسجد کا حکم دیا گیا، لہٰذا حیض سے تکلیف نہ ہو، البتہ اس قسم کی عورتیں وعظ اور دعا میں شریک ہوں گی۔ (۴)عید کے مقاصد میں سے ایک اہم مقصد دعا بھی ہے، لہٰذا عید کے خطبے میں دعا کا خصوصی اہتمام کیا جائے جس میں نہ صرف اپنے لیے بلکہ جمیع مسلمانوں کے لیے دعائیں کی جائیں۔"}],[1559,"محمد بن سیرین کہتے ہیں کہ میں نے ام عطیہ رضی اللہ عنہا سے ملاقات کی اور میں نے ان سے پوچھا: کیا آپ نے نبی اکرم صلی اللہ علیہ وسلم سے (ایسا ایسا کہتے ہوئے)سنا ہے؟ اور وہ جب بھی آپ کا ذکر کرتیں تو کہتیں: میرے باپ آپ پر فدا ہوں، (انہوں نے کہا: ہاں) آپ نے فرمایا: \"بالغ لڑکیوں کو اور پردہ والیوں کو بھی (عید کی نماز کے لیے) نکالو تاکہ وہ عید میں اور مسلمانوں کی دعا میں شریک رہیں، اور حائضہ عورتیں مصلی (عید گاہ) سے الگ تھلگ رہیں\"۔","الألباني: صحيح",{"u2":"حضرت محمد (بن سیرین) سے روایت ہے، انھوں نے کہا کہ میں حضرت ام عطیہ رضی اللہ عنہا سے ملا اور ان سے پوچھا: کیا آپ نے نبی صلی اللہ علیہ وسلم سے (نماز عید میں عورتوں کی شرکت کے بارے میں) کچھ سنا ہے؟ اور وہ جب بھی آپ صلی اللہ علیہ وسلم کا ذکر کرتی تھیں تو وہ کہتی تھیں: [بابا] ’’میرا باپ آپ پر فدا ہوجائے۔‘‘ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بالغ اور پردہ نشین عورتوں کو بھی (عید میں) ساتھ لے کر جائو تاکہ وہ بھی اس نیکی اور مسلمانوں کی دعا میں شریک ہوں، البتہ حیض والی عورتیں لوگوں کی نماز والی جگہ (عیدگاہ) سے الگ رہیں۔‘‘","f2":"نوجوان عورتوں کو عید کے لیے جانے کے حکم سے صاف سمجھ آتا ہے کہ دوسری عورتوں تو بدرجۂ اولیٰ جائیں گی۔"}],[1560,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ عمر بن خطاب رضی اللہ عنہ نے بازار میں موٹے ریشمی کپڑے کا ایک جوڑا (بکتے ہوئے) پایا، تو اسے لیا، اور اسے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور آپ سے عرض کیا: اللہ کے رسول! اسے خرید لیں، اور عید کے لیے اور وفود سے ملتے وقت اسے پہنیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ اس شخص کا لباس ہے جس کا (آخرت میں) کوئی حصہ نہ ہو گا، یا اسے تو وہی پہنے گا جس کا (آخرت میں) کوئی حصہ نہ ہو گا\"، تو عمر رضی اللہ عنہ ٹھہرے رہے جب تک اللہ نے چاہا، پھر رسول اللہ صلی اللہ علیہ وسلم نے ان کے پاس باریک ریشمی کپڑے کا ایک جبہ بھیجا، تو وہ اسے لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے، اور عرض کیا: اللہ کے رسول! آپ نے فرمایا تھا کہ یہ اس شخص کا لباس ہے جس کا (آخرت میں) کوئی حصہ نہیں، پھر آپ نے اسے میرے پاس بھیج دیا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اسے بیچ دو، اور اس سے اپنی ضرورت پوری کرو\" ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ میں نے اسے تمہارے پاس اس لیے نہیں بھیجا ہے کہ تم خود اسے پہنو، بلکہ اس لیے بھیجا ہے کہ بیچ کر تم اس کی قیمت اپنی ضرورت میں صرف کرو۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ حضرت عمر بن خطاب رضی اللہ عنہ نے بازار میں ریشم کا ایک جوڑا (برائے فروخت) دیکھا۔ وہ اسے لے کر رسول اللہ صلی اللہ علیہ وسلم کی خدمت عالیہ میں حاضر ہوئے اور گزارش کی: اے اللہ کے رسول! اسے خریدلیں اور عید اور وفود سے ملاقات کے مواقع پر زیب تن فرمایا کریں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ (ریشم) تو ان لوگوں کا لباس ہے جن کا (آخرت میں) کوئی حصہ نہیں۔‘‘ یا (فرمایا:) ’’اسے تو وہ لوگ پہنتے ہیں جن کو (آخرت میں) کچھ نہیں ملے گا۔‘‘ کچھ عرصہ، جتنا کہ اللہ تعالیٰ نے چاہا، حضرت عمر رضی اللہ عنہ ٹھہرے رہے، پھر رسول اللہ صلی اللہ علیہ وسلم نے حضرت عمر رضی اللہ عنہ کے پاس ریشم کا ایک جبہ بھیجا۔ حضرت عمر رضی اللہ عنہ اس جبے کو لے کر رسول اللہ صلی اللہ علیہ وسلم کے پاس حاضر ہوئے اور عرض کیا: اے اللہ کے رسول! آپ نے تو فرمایا تھا: ’’یہ ان کا لباس ہے جن کا (آخرت میں) کوئی حصہ نہیں۔‘‘ پھر آپ نے یہ جبہ مجھے بھیج دیا؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسے بیچ کر اپنی ضروریات پوری کرو۔‘‘","f2":"(۱)رسول اللہ صلی اللہ علیہ وسلم نے وہ جبہ نہیں خریدا اس کی وجہ اس کا ریشمی ہونا تھا، نہ کہ زیب و زینت ہونا، لہٰذا مصنف رحمہ اللہ کا باب پر اس روایت سے استدلال صحیح ہے۔ (۲)جس چیز کا استعمال بعض افراد کے لیے جائز ہو اور بعض کے لیے ناجائز، اسے کسی کو بھی بطور تحفہ دیا جاسکتا ہے کیونکہ وہ خود استعمال نہ کرے گا تو دوسرے کو دے دے گا یا بیچ ڈالے گا۔ ایسی چیز کی تجارت بھی جائز ہے، جیسے ریشم وغیرہ، البتہ جو چیز مطلقاً حرام ہے وہ نہ کسی کو تحفے میں دی جاسکتی ہے اور نہ اس کی تجارت جائز ہے، جیسے شراب اور خنزیر وغیرہ۔ (۳)’’یہ ان کا لباس ہے۔۔۔الخ‘‘ اس کا مطلب یہ ہے کہ کافر لوگ ریشم پہنتے ہیں، مسلمان نہیں پہنتے بلکہ انھیں آخرت میں بطور اکرام ملے گا۔ (۴)’’جوریشم پہنے، اس کا آخرت میں کوئی حصہ نہیں‘‘ اس کا مطلب یہ نہیں کہ وہ کافر ہے کیونکہ ریشم پہننا گناہ ہے، کفر نہیں بلکہ مطلب یہ ہے کہ اس پر مؤاخذہ ہوسکتا ہے اگر اس نے توبہ نہ کی۔ واللہ اعلم۔"}],[1561,"ثعلبہ بن زہدم سے روایت ہے کہ علی رضی اللہ عنہ نے ابومسعود رضی اللہ عنہ کو لوگوں پر اپنا نائب مقرر کیا، تو (جب) وہ عید کے دن نکلے تو کہنے لگے: لوگو! یہ سنت نہیں ہے کہ امام سے پہلے نماز پڑھی جائے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ثعلبہ بن زہدم سے مروی ہے کہ حضرت علی رضی اللہ عنہ نے حضرت ابومسعودرضی اللہ عنہ کو (ایک دفعہ) لوگوں پر اپنا نائب مقرر فرمایا۔ وہ عید کے دن (عید کے لیے) باہر نکلے تو فرمایا: اے لوگو! یہ نبی صلی اللہ علیہ وسلم کا طریقہ نہیں کہ امام (کے نماز عید پڑھانے) سے پہلے کوئی نفل نماز پڑھی جائے۔","f2":"صحابی کے ایسے الفاظ روایت کو مرفوع (نبی صلی اللہ علیہ وسلم کے قول و فعل) کے حکم میں مانا جاتا ہے۔ نمازعید سے پہلے نوافل پڑھنا منع ہیں کیونکہ یہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ کے معمول کے خلاف ہے، البتہ نماز عید کے بعد واپس آکر گھر میں نوافل پڑھنے کی اجازت ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے، نماز عید کے بعد گھر میں دو رکعت نماز پڑھنا منقول ہے۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی: ۱۷؍۱۶۲، ۱۶۳)"}],[1562,"جابر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں بغیر اذان اور بغیر اقامت کے خطبہ سے پہلے عید کی نماز پڑھائی۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں نماز عید، خطبے سے قبل اذان اور اقامت کے بغیر پڑھائی۔","f2":"سنت یہی ہے کیونکہ اذان و اقامت پانچ وقت کی فرض نمازوں اور جمعۃ المبارک کے لیے ہے جیسا کہ متعدد احادیث سے پتہ چلتا ہے۔ غرض عیدین میں رسول اللہ صلی اللہ علیہ وسلم کا یہ عمل نہ تھا، اس لیے اس کا نہ کرنا ہی سنت ہے۔ واللہ اعلم۔"}],[1563,"شعبی (عامر بن شراحیل) کہتے ہیں کہ ہم سے براء بن عازب رضی اللہ عنہم نے مسجد کے ستونوں میں سے ایک ستون کے پاس بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے قربانی کے دن خطبہ دیا، تو آپ نے فرمایا: \"اپنے اس دن میں سب سے پہلا کام یہ ہے کہ ہم نماز پڑھیں، پھر قربانی کریں، تو جس نے ایسا کیا تو اس نے ہماری سنت کو پا لیا، اور جس نے اس سے پہلے ذبح کر لیا تو وہ محض گوشت ہے جسے وہ اپنے گھر والوں کو پہلے پیش کر رہا ہے\"، ابوبردہ ابن نیار (نماز سے پہلے ہی) ذبح کر چکے تھے، تو انہوں نے عرض کیا: اللہ کے رسول! میرے پاس ایک سال کا ایک دنبہ ہے، جو دانت والے دنبہ سے بہتر ہے، تو آپ نے فرمایا: \"اسے ہی ذبح کر لو، لیکن تمہارے بعد اور کسی کے لیے یہ کافی نہیں ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت شعبی بیان کرتے ہیں کہ حضرت براء بن عازب رضی اللہ عنہما نے ہمیں مسجد کے ستونوں میں سے ایک ستون کے پاس بیان کیا کہ نبی صلی اللہ علیہ وسلم نے ہمیں عیدالاضحیٰ کے دن خطبہ دیتے ہوئے فرمایا: ’’آج کے دن ہم سب سے پہلے جس چیز کی ابتدا کریں گے وہ یہ ہے کہ ہم نماز پڑھیں گے، پھر (قربانی) ذبح کریں گے۔ جو شخص ایسا کرے گا، وہ ہماری سنت پر عمل کرے گا اور جو اس (نماز پڑھنے) سے پہلے ذبح کرے گا تو یہ (قربانی نہیں بلکہ) اس نے اپنے گھر والوں کے لیے گوشت تیار کیا ہے۔‘‘ اتفاقاً حضرت ابوبردہ بن نیار نے (نماز عید سے قبل) قربانی ذبح کردی تھی۔ وہ کہنے لگے: اے اللہ کے رسول! میرے پاس ایک جزعہ (نوجوان بکرا) جو دو دانتے سے (جسمانی طور پر) بہتر ہے۔ آپ نے فرمایا: ’’چلو اسے ذبح کردو لیکن ایسا جانور تیرے علاوہ کسی سے کفایت نہ کرے گا۔‘‘","f2":"(۱)’’کفایت نہ کرے گا‘‘ کیونکہ قربانی کے لیے بکرے، گائے اور اونٹ کا دودانتا (جس کے سامنے کے دو دانت گر چکے ہوں) ہونا ضروری ہے۔ حدیث میں مذکورہ جزعہ (بکرا) دو دانتا، یعنی مسنہ نہیں ہوتا بلکہ اس سے کم عمر ہوتا ہے، لہٰذا یہ کفایت نہیں کرے گا۔ بکرے کے جذعے کی رخصت خاص ابوبردہ رضی اللہ عنہ کے لیے تھی جیسا کہ حدیث میں ہے۔ جبکہ دنبے اور چھترے کا جذعہ جائز ہے، کسی فرد سے اس کی تخصیص نہیں۔ بنابریں جس جانور کی قربانی کرنا بعد والوں کے لیے جائز نہیں، خواہ مجبور ہی کیوں نہ ہوں، وہ بکرے کے جذعے کی قربانی ہے۔ احادیث کے مجموعے سے یہی ثابت ہوتا ہے۔ واللہ اعلم۔ (۲)حدیث میں جذعہ سے مراد بکرے کا جذع ہے۔ بھیڑ کا جذع عموماً ایک سال کا ہوتا ہے، جمہور کی یہی رائے ہے۔ بعض نے چھ ماہ کے بھیڑ کے بچے کو بھی جذعہ کہا ہے مگر جمہور کی رائے کے مقابلے میں یہ موقف مرجوح ہے۔ واللہ اعلم۔ اس مسئلے کی تفصیل کے لیے اسی کتاب کی کتاب الضحایا کو دیکھیے۔"}],[1564,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم، ابوبکر اور عمر رضی اللہ عنہم عیدین کی نماز خطبہ سے پہلے پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم اور حضرت ابوبکر و عمر رضی اللہ عنہما عیدین میں نماز خطبے سے قبل پڑھا کرتے تھے۔","f2":"یہ بات متفق علیہ ہے۔ بنوامیہ نے اپنے دور میں خطبہ نماز سے پہلے کردیا تھا مگر یہ شاہی حکم ان کی حکومت ختم ہونے کے ساتھ ہی ختم ہوگیا۔ بقا سنت ہی کو ہے۔"}],[1565,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عید الفطر اور عید الاضحی دونوں میں نیزہ لے جاتے اور اسے گاڑتے، پھر اس کی جانب رخ کر کے نماز پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم عیدالفطر اور عیدالاضحیٰ کے دن چھوٹا نیزہ ساتھ لے جایا کرتے تھے، پھر اسے گاڑ لیتے اور اس کی طرف نماز پڑھتے۔","f2":"(۱)باب کا مفہوم یہ ہے کہ کھلی جگہ میں امام کے آگے سترہ ہونا چاہیے تاکہ کسی کے گزرنے سے نماز نہ ٹوٹ جائے۔ (۲)سترے کی غرض سے نیزہ وغیرہ لے جایا جاسکتا ہے اگرچہ آپ نے بھیڑ کے موقع پر اسلحہ لے جانے سے روکا ہے کیونکہ کسی کو اتفاقاً زخم بھی لگ سکتا ہے، البتہ صرف امام کے ساتھ نیزہ ہو تو ایسا کوئی خطرہ نہیں، لہٰذا جائز ہے۔"}],[1566,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ عید الاضحی کی نماز دو رکعت ہے، عید الفطر کی نماز دو رکعت ہے، مسافر کی نماز دو رکعت ہے، اور جمعہ کی نماز دو رکعت ہے۔ اور یہ سب (دو دو رکعت ہونے کے باوجود) بزبان نبی اکرم صلی اللہ علیہ وسلم مکمل ہیں، ان میں کوئی کمی نہیں۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ بیان کرتے ہیں کہ عیدالاضحیٰ کی نماز دورکعت ہے، عیدالفطر کی نماز دورکعت ہے، مسافر کی نماز دو رکعت ہے اور جمعے کی نماز بھی دو رکعت ہے۔ یہ تمام نمازیں نبی صلی اللہ علیہ وسلم کی زبانی مکمل ہیں، ان میں کوئی کمی اور نقص نہیں۔","f2":"یہ مسئلہ بھی متفق علیہ ہے۔ اس میں کوئی اختلاف نہیں، البتہ جمہور علماء آثار صحابہ کی روشنی میں فرماتے ہیں کہ مسافر چاہے تو پوری نماز، یعنی چار رکعت پڑھ سکتا ہے۔ تاہم رسول اللہ صلی اللہ علیہ وسلم نے سفر کی نماز ہمیشہ دو رکعت ہی پڑھی ہے، اس لیے افضل قصر ہی ہے۔"}],[1567,"عبیداللہ بن عبداللہ کہتے ہیں کہ (ایک دفعہ) عید کے دن عمر رضی اللہ عنہ نکلے تو انہوں نے ابوواقد لیثی سے پوچھا کہ نبی اکرم صلی اللہ علیہ وسلم آج کے دن کون سی(سورتیں) پڑھا کرتے تھے؟ تو انہوں نے کہا: سورۃ \"قٓ\" اور سورۃ \"اقتربت\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ عید کے دن نکلے تو آپ نے حضرت ابوواقد لیثی رضی اللہ عنہ سے پوچھا کہ نبی صلی اللہ علیہ وسلم اس دن کون سی سورتیں (نماز عید میں) پڑھا کرتے تھے؟ انھوں نے کہا: سورۂ (ق) اور سورۂ (اقتربت الساعۃ)"}],[1568,"نعمان بن بشیر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عیدین میں اور جمعہ کے دن «سبح اسم ربك الأعلى» اور «هل أتاك حديث الغاشية» پڑھتے تھے، اور کبھی یہ دونوں ایک ساتھ ایک ہی دن میں جمع ہو جاتے، تو بھی انہیں دونوں سورتوں کو پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عیدین اور جمعے کے دن سورۂ (سبح اسم ربک الاعلیٰ) اور (ھل اتک حدیث الغاشیۃ) پڑھا کرتے تھے۔ کبھی جمع اور عید ایک دن میں اکٹھے ہوجاتے تو بھی آپ یہی دونوں سورتیں پڑھتے۔","f2":"عیدین میں مقتدیوں یا موقع ومحل کا لحاظ رکھتے ہوئے دونوں حدیثوں میں سے کسی حدیث پر بھی عمل کیا جاسکتا ہے اور یہ اولیٰ ہے۔"}],[1569,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ میں گواہی دیتا ہوں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید میں شریک رہا، تو آپ نے خطبہ سے پہلے نماز شروع کی، پھر آپ نے خطبہ دیا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما فرماتے ہیں: میں گواہی دیتا ہوں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید کے موقع پر حاضر ہوا۔ آپ نے خطبے سے پہلے نماز پڑھی، پھر خطبہ دیا۔"}],[1570,"براء بن عازب رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں قربانی کے دن نماز کے بعد خطبہ دیا۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے عید قربان کے دن نماز کے بعد خطبہ دیا۔"}],[1571,"عبداللہ بن سائب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے عید کی نماز پڑھی، پھر فرمایا: \"جو (واپس) لوٹنا چاہے لوٹ جائے، اور جو خطبہ سننے کے لیے ٹھہرنا چاہے ٹھہرے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن سائب رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے عید کی نمازپڑھائی، پھر فرمایا: ’’جو آدمی جانا چاہے وہ جاسکتا ہے اور جو خطبہ سننے کے لیے ٹھہرنا چاہتا ہے، وہ ٹھہرے۔","f2":"عید کا خطبہ سننا فرض نہیں، مستحب ہے، شاید اسی لیے نماز پہلے کردی گئی ہے تاکہ جو شخص نماز کے بعد جانا چاہے جاسکے، بخلاف جمعے کے خطبے کے جو شخص نماز سے پہلے آجائے، وہ خطبہ ضرور سنے گا۔\nعید کا خطبہ سننا فرض نہیں، مستحب ہے، شاید اسی لیے نماز پہلے کردی گئی ہے تاکہ جو شخص نماز کے بعد جانا چاہے جاسکے، بخلاف جمعے کے خطبے کے جو شخص نماز سے پہلے آجائے، وہ خطبہ ضرور سنے گا۔"}],[1572,"ابورمثہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ خطبہ دے رہے تھے اور آپ پر ہرے رنگ کی دو چادریں تھیں۔","الألباني: صحيح",{"u2":"حضرت ابورمثہ رضی اللہ عنہ سے روایت ہے کہ میں نے نبی صلی اللہ علیہ وسلم کو خطبہ ارشاد فرماتے سنا جبکہ آپ دو سبز چادریں اوڑھے ہوئے تھے۔","f2":"(۱)برددھاری دار چادر کو کہا جاتا تھا۔ یہ عام طور پر یمن میں بنی جاتی تھیں۔ گویا وہ چادریں خالص سبز نہ تھیں بلکہ ان میں سبز دھاریاں تھیں۔ ظاہر ہے اس قسم کا کپڑا زینت کے لیے پہنا جاتا ہے۔ (۲)امام کو چاہیے کہ وہ اچھا لباس زیب تن کرے تاکہ اس کی شخصیت کے بارے میں اچھا تاثر قائم ہو۔ باطنی طہارت کے ساتھ ظاہری تجمل سونے پر سہاگا ہے، البتہ باطنی خباثت پر خوب صورت لباس ایسے ہے جیسے خنزیر کے گلے میں موتی۔ [اعاذنا اللہ من مثل السوء]"}],[1573,"ابو کاہل احمسی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ ایک اونٹنی پر سوار ہو کر خطبہ دے رہے تھے اور ایک حبشی اونٹنی کی نکیل تھامے ہوئے تھا۔","الألباني: حسن",{"u2":"حضرت ابوکاہل احمسی رضی اللہ عنہ سے منقول ہے، فرماتے ہیں: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اونٹنی پر سوار خطبہ ارشاد فرماتے دیکھا جبکہ ایک حبشی (سیدنا حضرت بلال رضی اللہ عنہ) نے اونٹنی کی مہار تھام رکھی تھی۔","f2":"اس روایت میں عید کا ذکر نہیں جبکہ مسند احمد: (۴؍۳۰۶) میں صراحت ہے کہ آپ لوگوں سے عید کا خطبہ ارشاد فرما رہے تھے۔ یہ بھی ممکن ہے کہ امام صاحب کا استدلال عموم سے ہو۔ بنابریں لوگ زیادہ ہوں اور آواز سب تک نہ پہنچتی ہو یا امام و خطیب نظر نہ آتا ہو تو جانور پر سوار ہوکر بھی خطبہ دیا جاسکتا ہے۔ یا کسی اور اونچی چیز پر، البتہ قصداً منبر عیدگاہ میں لے جانا درست نہیں کہ یہ تکلف میں شمار ہوگا۔"}],[1574,"سماک کہتے ہیں کہ میں نے جابر رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو کر خطبہ دیتے تھے؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو کر خطبہ دیتے تھے، پھر آپ کچھ دیر بیٹھتے تھے پھر کھڑے ہو جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت سماک نے کہا کہ میں نے حضرت جابر رضی اللہ عنہ سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ ارشاد فرماتے تھے؟ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ ارشاد فرماتے تھے، پھر کچھ دیر بیٹھتے، پھر کھڑے ہوجاتے۔","f2":"اس روایت میں بھی عید کا ذکر نہیں ہے مگر معلوم ہوتا ہے کہ مصنف رحمہ اللہ عید کے خطبے کو جمعے کے خطبے کی طرح سمجھتے ہیں، یعنی اس کے بھی دو خطبے ہوں گے۔ درمیان میں امام بیٹھے گا۔ جمہور اہل علم اسی بات کے قائل ہیں، البتہ اس بات میں اختلاف ہے کہ درمیان میں بیٹھنا خطبے کی طوالت اور امام کی سہولت اور آرام کے لیے ہے یا اختتام خطبہ کا قرب ظاہر کرنے کے لیے؟ دوسری وجہ ہو تو دوسرا خطبہ مختصر ہونا چاہیے اور یہی درست ہے۔ پہلی وجہ ہو تو دونوں خطبے برابر ہونے چاہییں مگر یہ معمول نہیں۔ بعض محققین علماء نے عید میں ایک خطبہ ہی درست سمجھا ہے کیونکہ کسی صحیح روایت میں صراحتاً عید کے دو خطبوں کا ذکر نہیں۔ سنن ابن ماجہ کی جس روایت میں دو خطبوں کا ذکر ہے، وہ روایت ابوبحر عبدالرحمن بن عثمان بن امیہ اور اس کے شیخ اسماعیل بن مسلم الخولانی کی وجہ سے ضعیف اور ناقابل حجت ہے کیونکہ یہ دونوں راوی ضعیف ہیں۔ واللہ اعلم۔ (سنن ابن ماجہ، اقامۃ الصلوات، حدیث:۱۲۸۹) بنابریں یہ کیفیت، یعنی درمیان میں بیٹھنا، صرف خطبۂ جمعہ میں ثابت ہے۔ راجح اور درست موقف یہی معلوم ہوتا ہے کہ عید میں ایک ہی خطبہ ہے۔ واللہ اعلم۔"}],[1575,"جابر رضی اللہ عنہ کہتے ہیں کہ میں عید کے دن نماز میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ موجود تھا، آپ نے خطبہ سے پہلے بغیر اذان اور بغیر اقامت کے نماز پڑھی، پھر جب نماز پوری کر لی، تو آپ بلال رضی اللہ عنہ پر ٹیک لگا کر کھڑے ہوئے، اور آپ نے اللہ کی حمد و ثنا بیان کی، لوگوں کو نصیحتیں کیں، اور انہیں (آخرت کی) یاد دلائی، اور اللہ تعالی کی اطاعت پر ابھارا، پھر آپ مڑے اور عورتوں کی طرف چلے، بلال رضی اللہ عنہ آپ کے ساتھ تھے، آپ نے انہیں (بھی) اللہ تعالی سے ڈرنے کا حکم دیا، اور انہیں نصیحت کی اور (آخرت کی) یاد دلائی، اور اللہ تعالی کی حمد و ثناء بیان کی، پھر انہیں اللہ تعالی کی اطاعت پر ابھارا، پھر فرمایا: \"تم صدقہ کیا کرو کیونکہ عورتیں ہی زیادہ تر جہنم کا ایندھن ہوں گی، تو ایک عام درجہ کی ہلکے کالے رنگ کے گالوں والی عورت نے پوچھا: کس سبب سے اللہ کے رسول؟ آپ نے فرمایا:\"(کیونکہ) وہ شکوے اور گلے بہت کرتی ہیں، اور شوہر کی ناشکری کرتی ہیں\"، عورتوں نے یہ سنا تو وہ اپنے ہار، بالیاں اور انگوٹھیاں اتار اتار کر بلال رضی اللہ عنہ کے کپڑے میں ڈالنے لگیں، وہ انہیں صدقہ میں دے رہی تھیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید کی نماز میں حاضر ہوا۔ آپ نے بغیر اذان اور اقامت کے خطبے سے پہلے نماز عید پڑھائی۔ جب آپ نے نماز پوری فرمائی تو بلال کے کندھے پر ہاتھ رکھ کر کھڑے ہوگئے۔ اللہ تعالیٰ کی حمدوثنا کی، لوگوں کو وعظ و نصیحت کرتے ہوئے انھیں (اللہ اور رسول کی) اطاعت کی تلقین فرمائی، پھر آپ ایک طرف سے ہوکر عورتوں کی طرف گئے، بلال رضی اللہ عنہ بدستور آپ کے ساتھ تھے۔ آپ نے ان (عورتوں) کو اللہ تعالیٰ سے ڈرنے کا حکم دیا اور انھیں وعظ و نصیحت فرمائی۔ اللہ تعالیٰ کی حمدوثنا کی اور انھیں اللہ (اور رسول) کی اطاعت کی رغبت دلائی، پھر فرمایا: ’’(اے عورتو!) صدقہ کرو کیونکہ اکثر عورتیں جہنم کا ایندھن بنیں گی۔‘‘ تو ایک سیاہ مٹیالے رخساروں والی عام سی عورت نے کہا: اے اللہ کے رسول! کیوں؟ آپ نے فرمایا: ’’تم شکوے شکایت زیادہ کرتی ہو اور خاوند کی ناشکری کرتی ہو۔‘‘ عورتیں اپنے ہار، بالیاں اور انگوٹھیاں اتار کر بطور صدقہ حضرت بلال رضی اللہ عنہ کے کپڑے میں ڈالنے لگیں (تاکہ وہ بیت المال میں جمع کروادیں۔)","f2":"(۱)رسول اللہ صلی اللہ علیہ وسلم کا خطاب اگرچہ صحابیات سے تھا مگر مراد عام عورتیں ہیں۔ یہ دووصف اگرچہ مردوں میں بھی ممکن ہیں مگر عورتوں میں تقریباً یہ لازمہ ہیں، اس لیے انھیں خصوصاً تنبیہ فرمائی۔ (۲)جمہورِ اہل علم کے نزدیک عورتوں سے الگ خطاب کرنا رسول اللہ صلی اللہ علیہ وسلم کا خاصہ ہے کیونکہ آپ کے بعد خلفائے راشدین نے ایسا نہیں کیا، حالانکہ وہ سنتوں کے شیدائی تھے، نیز اس میں خطبوں کی کثرت یا قطعِ خطبہ لازم ہے۔ دونوں امور درست نہیں۔ بعض کا کہنا ہے کہ امام کے لیے ضروری ہے کہ وہ عورتوں کو بھی الگ طور پر وعظ و نصیحت کرے لیکن یہ صحیح نہیں کیونکہ یہ قول شاذ ہے، تاہم اگر کہیں اس کی ضرورت ہو تو اور بات ہے، وہاں ضرورت کے مطابق عمل کیا جاسکتا ہے۔ واللہ اعلم۔ (۳)عیدین کی نماز اذان واقامت کے بغیر ہوتی ہے۔ (۴) عیدین کی نماز پہلے ہوتی ہے اور خطبہ بعد میں ہوتا ہے۔ (۵)عورتیں بھی نماز عید کے لیے عیدگاہ میں جائیں گی۔ ان کے لیے عیدگاہ میں معقول اور محفوظ انتظام ہونا چاہیے۔ (۶)عورت اپنے مال سے خاوند کو بتائے بغیر صدقہ کرسکتی ہے۔ (۷)صدقہ ردبلا ہے۔ (۸)فقراء ومساکین پر خرچ کرنے اور ان کی ضروریات کو پورا کرنے کے لیے مالدار حضرات سے صدقہ و خیرات کا مطالبہ جائز ہے۔"}],[1576,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عید الفطر اور عید الاضحی کے دن عید گاہ کی طرف نکلتے تو لوگوں کو نماز پڑھاتے، پھر جب دوسری رکعت میں بیٹھتے اور سلام پھیرتے، تو کھڑے ہوتے اور اپنا چہرہ لوگوں کی طرف کرتے، اور لوگ بیٹھے رہتے، پھر اگر آپ کو کوئی ضرورت ہوتی جیسے کہیں فوج بھیجنا ہو تو لوگوں سے اس کا ذکر کرتے، ورنہ لوگوں کو صدقہ دینے کا حکم دیتے، تین بار کہتے: \"صدقہ کرو\"، تو صدقہ دینے والوں میں زیادہ تر عورتیں ہوتی تھیں۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم عیدالفطر اور عیدالاضحیٰ میں عیدگاہ تشریف لے جاتے اور لوگوں کو نماز پڑھاتے۔ جب دوسری رکعت کے بعد بیٹھ کر سلام پھیرتے تو لوگوں کی طرف منہ کرکے کھڑے ہوجاتے۔ سب لوگ (اپنی اپنی جگہوں پر) بیٹھے رہتے۔ اگر آپ لشکر بھیجنے کی ضرورت محسوس فرماتے تو لوگوں کے سامنے ذکر فرماتے، ورنہ لوگوں کو صدقہ وغیرہ کرنے کا حکم دیتے۔تین دفعہ فرماتے: ’’صدقہ کرو۔‘‘ تو صدقہ کرنے والی اکثر عورتیں ہی ہوتیں۔"}],[1577,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم نے اپنے ساتھی سے کہا: خاموش رہو، اور امام خطبہ دے رہا ہو تو تم نے لغو حرکت کی\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تو نے امام صاحب کے خطبے کے دوران میں اپنے ساتھی کو زبان سے کہا: چپ رہ تو تو نے بھی فضول کام کیا۔‘‘","f2":"یہ حدیث خطبۂ جمعہ کے بارے میں جیسا کہ بعض روایات میں یوم الجمعۃ کی صراحت ہے۔ جبکہ یہاں امام صاحب رحمہ اللہ کا استدلال (والامام یخطب) ’’اور امام خطبہ دے رہا ہو‘‘ کے عموم سے ہے۔ لگتا ہے ان کے نزدیک نماز عید کا خطبہ، خطبۂ جمعہ کی مثل ہے، جس سے اس کا سننا بھی ضروری ٹھہرتا ہے، حالانکہ حدیث: ۱۵۷۲ میں خطبۂ عید سننے یا نہ سننے کی اجازت مروی ہے۔ بنابریں خطبۂ عید کو خطبۂ جمعۃ المبارک پر قیاس کرنا یا اس کی مثل ٹھہرانا قیاس مع الفارق ہے کیونکہ خطبہ لجمعہ سننا واجب ہے، اور واجب پر غیرواجب کا قیاس درست نہیںَ علامہ سندھی رحمہ اللہ نے اس کا جواب دینے کی کوشش کی ہے۔ جس کا ماحصل یہ ہے کہ جو جانا چاہے جاسکتا ہے لیکن جو بیٹھ رہے اس کے لیے خطبۂ عید سننا ضروری ہے اور اثنائے خطبہ کلام درست نہیں، لیکن یہ تطبیق محل نظر ہے کیونکہ اصول ہے کہ اگر نص مطلق ہو تو اسے مقید پر محمول کرتے ہیں اور یہاں یہی صورت حاصل ہے کیونکہ اسی حدیث کے ایک طریق میں یوم الجمعۃ کی قید بھی موجود ہے، جس سے پتہ چلتا ہے کہ صرف خطبہ جمعہ ہی میں خاموشی ضروری ہوگی اور حدیث میں واردوعید بھی صرف خطبۂ جمعہ سے متعلق ہے، ہاں اس بات میں کوئی دوسری رائے نہیں کہ خطبۂ عید بھی توجہ اور انہماک سے سننا مستحب ہے۔ واللہ اعلم۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۷؍۲۰۵) (۲)زبان سے روکنا اس لیے منع ہے کہ بسااوقات چپ کرانے والوں کا شور بولنے والے سے بڑھ جاتا ہے، لہٰذا اشارے سے کام لیا جائے تاکہ خطبے میں سکون رہے۔ (۳)’’فضول کام کیا‘‘ یعنی تو نے اپنے جمعے کا ثواب ضائع کرلیا کیونکہ دوران جمعہ میں فضول کام کرنا ثواب کو باطل کردیتا ہے۔"}],[1578,"جابر بن عبداللہ رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنے خطبہ میں اللہ کی حمد و ثنا بیان کرتے جو اس کی شایان شان ہوتی، پھر آپ فرماتے: \"جسے اللہ راہ دکھائے تو کوئی اسے گمراہ نہیں کر سکتا، اور جسے گمراہ کر دے تو اسے کوئی ہدایت نہیں دے سکتا، سب سے سچی بات اللہ کی کتاب ہے، اور سب سے بہتر طریقہ محمد صلی اللہ علیہ وسلم کا طریقہ ہے، اور بدترین کام نئے کام ہیں، اور ہر نیا کام بدعت ہے اور ہر بدعت گمراہی ہے، اور ہر گمراہی جہنم میں لے جانے والی ہے\"، پھر آپ فرماتے: \"میں اور قیامت دونوں اس قدر نزدیک ہیں جیسے یہ دونوں انگلیاں ایک دوسرے سے ملی ہیں\"، اور جب آپ قیامت کا ذکر کرتے تو آپ کے دونوں رخسار سرخ ہو جاتے، اور آواز بلند ہو جاتی، اور آپ کا غصہ بڑھ جاتا جیسے آپ کسی لشکر کو ڈرا رہے ہوں، اور کہہ رہے ہوں: (ہوشیار رہو! دشمن) تم پر صبح میں حملہ کرنے والا ہے، یا شام میں، پھر آپ فرماتے: \"جو (مرنے کے بعد) مال چھوڑے تو وہ اس کے گھر والوں کا ہے، اور جو قرض چھوڑے یا بال بچے چھوڑ کر مرے تو وہ میری طرف یا میرے ذمہ ہیں، اور میں مومنوں کا ولی ہوں ۱؎۔\n§وضاحت\n۱؎: یعنی جن کا کفیل کوئی نہیں ان کا کفیل میں ہوں۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنا خطبہ یوں شروع فرماتے کہ پہلے اللہ تعالیٰ کی حمدوثنا بیان فرماتے جو اللہ تعالیٰ کی شان گرامی کے لائق ہے، پھر فرماتے: ’’جسے اللہ تعالیٰ راہ راست پر لے آئے، اسے کوئی گمراہ کرنے والا نہیں اور جسے اللہ تعالیٰ گمراہ کردے، اسے کوئی راہ راست پر لانے والا نہیں۔ بلاشبہ سب سے زیادہ سچی بات اللہ تعالیٰ کی کتاب ہے اور بہترین طریقہ محمد (صلی اللہ علیہ وسلم) کا طریقہ ہے۔ اور بدترین کام وہ ہیں جنھیں (شریعت میں) اپنی طرف سے جاری کیا گیا۔ ہر ایسا کام بدعت ہے اور ہر بدعت گمراہی ہے اور ہر گمراہی آگ میں لے جائے گی۔‘‘ پھر آپ فرماتے: ’’مجھے اور قیامت کو ان دو انگلیوں (انگشت شہادت اور ساتھ والی) کی طرح (ملا کر) بھیجا گیا ہے۔ آپ جب قیامت کا ذکر فرماتے تو آپ کے رخسار مبارک سرخ ہوجاتے، آواز بلند ہوجاتی اور غصے کے آثار چہرے پر نمایاں ہوجاتے۔ یوں لگتا جیسے آپ کسی لشکر سے ڈرا رہے ہیں (یعنی اس کے حملے کی خبر دے رہے ہیں) کہ تم پر صبح حملہ کردے گا یا شام کو۔ (پھر فرماتے:) ’’جو شخص مال چھوڑجائے، وہ تو اس کے رشتے داروں کو ملے گا اور جو آدمی قرض یا چھوٹے چھوٹے بچے (جن کے ضائع ہونے کا خطرہ ہے) چھوڑ جائے تو وہ میرے سپرد ہوں اور ان کے اخراجات اور قرض وغیرہ کی ادائیگی میرے ذمے ہوگی کیونکہ مومنین سے میرا تعلق اور رشتہ تمام رشتوں سے قوی اور مضبوط ہے۔‘‘","f2":"(۱)ضروری نہیں کہ ہر خطبے میں یہی الفاظ اور مضمون ہو اور نہ یہ ممکن اور مناسب ہے، بلکہ مقصد یہ ہے کہ خطبہ اس قسم کا ہونا چاہیے، یعنی اس کی ابتدا اللہ تعالیٰ کی حمدوثنا سے ہو۔ رسول اللہ صلی اللہ علیہ وسلم کا تذکرہ بھی خطبے کا لازمی جزو ہے۔ لوگوں کو شریعت حقہ کی پابندی اور بدعات سے احتراز کی طرف توجہ دلائی جائے۔ ان کو اللہ تعالیٰ اور قیامت سے ڈرایا جائے اور ضروری مسائل بیان کیے جائیںَ عنوان اور مضمون کوئی بھی ہوسکتا ہے۔ (۲)’’بدعت‘‘ سے مراد ہر وہ کام ہے جس کی سرے سے کوئی اصل شریعت اسلامیہ میں نہ ہو اور اسے اپنی طرف سے یا کسی دوسرے مذہب والوں کی نقالی میں اسلام میں داخل کیا جائے اور اسے دین اسلام کا جزو یا کارِ ثواب خیال کیا ہے۔ یا اس کی اصل تو موجود ہو لیکن اس کے لیے ایسی کیفیت، کوئی وقت یا صورت اختراع کر لی جائے کہ جس کی شرع میں دلیل نہ ہو تو وہ بھی بدعت ہی ہوگی۔ دنیوی امور میں کوئی نئی چیز اختیار کرنا بدعت نہیں۔ حضرت عمر رضی اللہ عنہ کا تراویح کی جماعت کو [انعمت البدعۃ] (صحیح البخاری، صلاۃ التراویح، حدیث:۲۰۱۰) کہنا لغت کے لحاظ سے ہے نہ کہ شرعاً۔ اسی طرح بدعت کی تقسیم حسنہ اور سیئہ بھی غلط ہے کیونکہ ہر شرعی بدعت گمراہی ہے، ا س کا مستحسن ہونا ممکن نہیں، تاہم اگر کوئی کام اصلاً شرع میں ثابت ہو مگر وصفاً ثابت نہ ہو، مثلاً: جماعت کے بعد شرعی حکم نہ سمجھ کر محض اتفاقیہ طور پر امام صاحب سے مصافحہ کرنا یا عید کے بعد گلے ملنا وغیرہ، تو ایسے کاموں کو بدعت نہیں کہا جائے گا کیونکہ انھیں سنت سمجھ کر نہیں کیا جاتا بلکہ ایک قومی رواج کے طور پر کیا جاتا ہے جس میں شرعاً کوئی حرج نہیں۔ بعض لوگ تشدد کرتے ہوئے یہ فرق نہیں کرتے۔ (۳)’’ان دو انگلیوں کی طرح‘‘ مراد یہ ہے کہ میری نبوت قیامت تک جاری رہے گی۔ اب نہ کوئی نبی آئے گا اور نہ کوئی اور شریعت۔ میں پہلے آگیا ہوں۔ قیامت میرے بعد آرہی ہے۔ درمیان میں کسی اور نبی کا فاصلہ نہیں۔ اگرچہ اس میں ہزاروں سال لگ جائیں۔ (۴)رسول اللہ صلی اللہ علیہ وسلم کا مومنین سے تعلق تمام رشتوں سے قوی اور مضبوط ہے۔ ہر رشتہ آپ پر فدا ہے۔ آپ سے محبت ایمان کا جزو ہے۔ یہ اٹوٹ رشتہ ہے۔ دنیا کے بعد آخرت میں بھی اور ہر خوف ناک موقع پر بھی قائم رہے گا۔ رسول اور نبی ہونے کے علاوہ آپ حاکم اور امیر بھی تھے اور حاکم و امیر اپنی رعایا کاذمے دار ہوتا ہے۔ حدیث میں مذکورہ اخراجات بیت المال سے پورے کیے جائیں گے۔"}],[1579,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم عید کے دن نکلتے تو دو رکعتیں پڑھتے، پھر خطبہ دیتے تو صدقہ کرنے کا حکم دیتے، تو صدقہ کرنے والوں میں زیادہ تر عورتیں ہوتی تھی، پھر اگر آپ کو کوئی حاجت ہوتی یا کوئی لشکر بھیجنے کا ارادہ ہوتا تو ذکر کرتے ورنہ لوٹ آتے۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم عید کے دن باہر تشریف لے جاتے، دو رکعتیں پڑھتے، پھر خطبہ ارشاد فرماتے اور صدقے کا حکم دیتے۔ اکثر عورتیں ہی صدقہ کرتیں۔ اگر کوئی ضرورت پیش ہوتی یا لشکر بھیجنا مقصود ہوتا تو اس سے متعلق کلام فرماتے، ورنہ واپس تشریف لے آتے۔"}],[1580,"حسن بصری سے روایت ہے کہ ابن عباس رضی اللہ عنہم نے بصرہ میں خطبہ دیا تو کہا: تم لوگ اپنے روزوں کی زکاۃ ادا کرو، تو (یہ سن کر) لوگ ایک دوسرے کی طرف دیکھنے لگے، تو انہوں نے کہا: یہاں مدینہ والے کون کون ہیں، تم اپنے بھائیوں کے پاس جاؤ، اور انہیں سکھاؤ کیونکہ یہ لوگ نہیں جانتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے صدقۃ الفطر آدھا صاع گیہوں یا ایک صاع کھجور یا جو، چھوٹے، بڑے، آزاد، غلام، مرد، عورت سب پر فرض کیا ہے۔","الألباني: صحيح المرفوع منه",{"u2":"حضرت حسن بصری سے منقول ہے کہ حضرت ابن عباس رضی اللہ عنہما نے بصرہ میں خطبہ دیا اور فرمایا: اپنے روزوں کی زکاۃ ادا کرو۔ لوگ ایک دوسرے کو دیکھنے لگے۔ آپ نے فرمایا: یہاں اہل مدینہ میں سے کون لوگ ہیں؟ (اے اہل مدینہ!) اٹھو اور اپنے (ان بصری) بھائیوں کو تعلیم دو (بتلاؤ) کیونکہ وہ نہیں جانتے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر چھوٹے، بڑے، آزاد، غلام اورمذکرومؤنث پر صدقۂ فطر نصف صاع گندم یا جو مقررفرمایا ہے۔","f2":"مذکورہ روایت سنداً ضعیف ہے کیونکہ حسن بصری رحمہ اللہ کا حضرت ابن عباس رضی اللہ عنہما سے سماع ثابت نہیں ہے، تاہم روایت میں بیان کردہ مسئلہ صدقۃ الفطر دیگر صحیح احادیث سے ثابت ہے۔ غالباً اسی وجہ سے محققین نے روایت کے پہلے حصے [ان ابن عباس خطب بالبصرۃ۔۔۔۔ فانھم لایعلمون] کو ضعیف قرار دیا ہے اور دوسرے حصے [ان رسول اللہ صلی اللہ علیہ وسلم فرض۔۔۔ من تعر او شعیر] کو دیگر شواہد کی بنا پر صحیح قرار دیا ہے۔ تفصیل کے لیے دیکھیے: (ضعیف سنن ابی داود (مفصل) للالبانی: ۲؍۱۲۱۔۱۲۳، رقم:۲۸۸، ذخیرۃ العقبی شرح سنن النسائی:۲۲؍۲۸۰۔۲۸۶) بنابریں یہی موقف دلائل کی رو سے صحیح ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہر چھوٹے، بڑے، آزاد، غلام اور مذکرو مؤنث پر نصف صاع گندم یا ایک صاع کھجور یا ایک صاع جو صدقۃ الفطر معلوم ہوتا ہے کہ اگر کوئی شخص ایک صاع کی بجائے آدھا صاع گندم بھی فطرانے میں دے دیتا ہے تو ان شاءاللہ یہ بھی جائز ہوگا۔ اسے صرف کسی صحابی کی رائے اور اجتہاد قرار دینا محل نظر ہے کیونکہ یہ مرفوعاً بھی ثابت ہے، البتہ پورا صاع دینا افضل اور اولیٰ ہے جیسا کہ عمومی احادیث سے اس کی تائید ہوتی ہے۔ واللہ اعلم۔ مزید تفصیل کے لیے سنن نسائی کی کتاب الزکاۃ، باب مکیلۃ زکاۃ الفطر دیکھیے۔"}],[1581,"براء رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قربانی کے دن نماز کے بعد خطبہ دیا، پھر فرمایا: \"جس نے ہماری (طرح) نماز پڑھی، اور ہماری طرح قربانی کی تو اس نے قربانی کو پا لیا، اور جس نے نماز سے پہلے قربانی کر دی، تو وہ گوشت کی بکری ہے ۱؎ تو ابوبردہ بن نیار رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! قسم اللہ کی! میں نے تو نماز کے لیے نکلنے سے پہلے ہی ذبح کر دیا، میں نے سمجھا کہ آج کا دن کھانے پینے کا دن ہے، اس لیے میں نے جلدی کر دی، چنانچہ میں نے (خود)کھایا، اور اپنے گھر والوں کو اور پڑوسیوں کو بھی کھلایا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ تو گوشت کی بکری ہوئی\" (اب قربانی کے طور پر دوسری کرو) تو انہوں نے کہا: میرے پاس ایک سال کا ایک دنبہ ہے، جو گوشت کی دو بکریوں سے (بھی) اچھا ہے، تو کیا وہ میری طرف سے کافی ہو گا؟ آپ نے فرمایا: \"ہاں، مگر تمہارے بعد وہ کسی کے لیے کافی نہیں ہو گا\"۔\n§وضاحت\n۱؎: یعنی یہ قربانی کے لیے نہیں بلکہ صرف کھانے کے لیے ذبح کی گئی بکری ہے۔","الألباني: صحيح",{"u2":"حضرت براء رضی اللہ عنہ فرماتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے قربانیوں والے دن نماز عید کے بعد خطبہ ارشاد فرمایا، پھر فرمایا: ’’جس شخص نے ہماری (نماز کی طرح) نماز پڑھی اور ہماری طرح (نماز کے بعد) قربانی کی، اس کی قربانی صحیح ہے، لیکن جس نے نمازعید سے قبل قربانی ذبح کردی تو یہ گوشت کھانے کے لیے بکری ذبح کی گئی ہے (قربانی نہیں)۔‘‘ حضرت ابوبردہ بن نیار رضی اللہ عنہ کہنے لگے: اے اللہ کے رسول! واللہ! میں نے تو نماز عید کے لیے آنے سے قبل ہی قربانی ذبح کردی ہے۔ میں نے سوچا کہ آج کھانے پینے کا دن ہے، اس لیے میں نے جلدی کی۔ خود بھی گوشت کھایا، اہل و عیال اور پڑوسیوں کو بھی کھلایا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ تو گوشت کے لیے بکری ذبح کی گئی ہے۔‘‘ انھوں نے کہا: میرے پاس ایک (بکری کی قسم سے) موٹا تازہ جذع ہے جو گوشت کے لحاظ سے دو بکریوں سے بہتر ہے (مگر وہ دانتا نہیں، چھوٹا ہے) تو کیا وہ میری طرف سے کفایت کرجائے گا (اگر میں اسے ذبح کردوں؟) آپ نے فرمایا: ’’ہاں، لیکن یہ تیرے علاوہ کسی سے کفایت نہیں کرے گا۔‘‘","f2":"تفصیل کے لیے دیکھیے: حدیث نمبر۱۵۶۴۔"}],[1582,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے ساتھ نماز پڑھتا تھا، تو آپ کی نماز درمیانی ہوتی تھی، اور آپ کا خطبہ (بھی) درمیانہ (اوسط درجہ کا) ہوتا تھا۔","الألباني: حسن",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے ساتھ نماز پڑھا کرتا تھا۔ آپ کی نماز بھی درمیانی ہوتی تھی اور خطبہ بھی درمیانہ ہوتا تھا۔","f2":"نماز نہ بہت طویل ہوتی کہ لوگ اکتا جائیں اور نہ بہت مختصر کہ لوگ ساتھ نہ مل سکیں۔ یہ مطلب نہیں کہ نماز اور خطبہ برابر ہوتے تھے کیونکہ دونوں اپنی حقیقت اور ہیئت میں ایک دوسرے سے مختلف ہیں، لہٰذا ان کے پیمانے الگ الگ ہیں۔"}],[1583,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کھڑے ہو کر خطبہ دیتے دیکھا، پھر آپ تھوڑی دیر کے لیے بیٹھتے اس میں بولتے نہیں، پھر کھڑے ہوتے، اور دوسرا خطبہ دیتے، تو جو شخص تمہیں یہ خبر دے کہ نبی اکرم صلی اللہ علیہ وسلم نے بیٹھ کر خطبہ دیا تو اس کی تصدیق نہ کرنا ۱؎۔\n§وضاحت\n۱؎: یہ مؤلف کا محض استنباط ہے، جس کی بنیاد عیدین کے خطبہ کو جمعہ کے خطبہ پر قیاس ہے، خاص طور پر عیدین کے خطبہ کے سلسلے میں نبی اکرم صلی اللہ علیہ وسلم سے کوئی صراحت مروی نہیں ہے، اس لیے بعض علماء جمعہ کے خطبہ پر قیاس کر کے عیدین میں بھی دو خطبے کے قائل ہیں، جب کہ بعض علماء صرف ایک خطبہ کے قائل ہیں، عیدین کے سلسلے میں ایک خطبہ ہی قرین قیاس ہے۔","الألباني: حسن",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ (پہلے) کھڑے ہوکر خطبہ ارشاد فرماتے، پھر (تھوڑی دیر کے لیے) بیٹھ جاتے اور اس دوران میں (کوئی تقریریا) بات چیت نہ کرتے، پھر کھڑے ہوجاتے اور دوسرا خطبہ ارشاد فرماتے، لہٰذا جو شخص تجھے بتائے کہ نبی صلی اللہ علیہ وسلم بیٹھ کر خطبہ دیتے تھے، اس کی تصدیق نہ کر۔","f2":"(۱)دو خطبوں کے درمیان بیٹھے ہوئے خاموش رہنے کا مطلب یہ ہے کہ اس دوران میں خطبہ روک دینا چاہیے۔ یہ مطلب نہیں کہ وہ ذکر اذکار بھی نہیں کرسکتا۔ حدیث میں کلام کی نفی ہے۔ عرف عام میں ذکر کو کلام نہیں کیا جاتا، لہٰذا ذکر جائز ہے۔ (۲)خطبۂ جمعہ یا خطبۂ عید کھڑے ہوکر ہی دینا چاہیے الایہ کہ کوئی معقول عذر ہو، مثلاً: بیماری، معذوری وغیرہ۔ لیکن بلاوجہ بیٹھ کر خطبہ دینے کو معمول بنالینا خلاف سنت ہے۔"}],[1584,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کھڑے ہو کر خطبہ دیتے، پھر بیٹھتے، پھر کھڑے ہوتے، اور بعض آیتیں پڑھتے اور اللہ کا ذکر کرتے، اور آپ کا خطبہ اور آپ کی نماز متوسط (درمیانی) ہوا کرتی تھی۔","الألباني: حسن",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ فرماتے ہیں کہ نبی صلی اللہ علیہ وسلم کھڑے ہوکر خطبہ ارشاد فرماتے، پھر بیٹھ جاتے، پھر کھڑے ہوجاتے اور چند آیات تلاوت فرماتے اور اللہ کی باتیں ذکر فرماتے۔ آپ کا خطبہ بھی درمیانہ ہوتا اور نماز بھی۔","f2":"’’اللہ کی باتیں ذکر فرماتے۔‘‘ دوسرے معنی یہ ہیں کہ ’’اللہ کا ذکر فرماتے۔‘‘ (نیز دیکھیے، حدیث: ۱۵۸۳)"}],[1585,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم منبر پر خطبہ دے رہے تھے کہ اسی دوران حسن اور حسین رضی اللہ عنہم سرخ قمیص پہنے گرتے پڑتے آتے دکھائی دیے، آپ منبر سے اتر پڑے، اور ان دونوں کو اٹھا لیا، اور فرمایا: اللہ تعالی نے سچ فرمایا ہے: «إنما أموالكم وأولادكم فتنة» \"تمہارے مال اور اولاد فتنہ ہیں\" میں نے ان دونوں کو ان کی قمیصوں میں گرتے پڑتے آتے دیکھا تو میں صبر نہ کر سکا یہاں تک کہ میں منبر سے اتر گیا، اور میں نے ان کو اٹھا لیا۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ سے مروی ہے کہ ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم منبر پر خطبہ ارشاد فرما رہے تھے کہ حسن و حسین رضی اللہ عنہم سامنے آگئے۔ انھوں نے سرخ قمیصیں پہن رکھی تھیں۔ وہ چلتے تھے تو (قمیصوں کی وجہ سے) لڑکھڑاتے تھے۔ (یعنی گرتے پڑتے آرہے تھے۔) آپ منبر سے اترے، انھیں اٹھایا اور فرمایا: ’’اللہ تعالیٰ نے سچ فرمایا ہے: (انما اموالکم واولادکم فتنۃ) ’’تمھارے مال و اولاد تمھارے لیے آزمائش ہیں۔‘‘ میں نے انھیں دیکھا کہ اپنی قمیصوں میں گرتے پڑتے آرہے ہیں تو میں صبر نہ کرسکا حتی کہ میں منبر سے اترا اور انھیں اٹھایا۔‘‘","f2":"بچوں سے محبت اور شفقت انسانی تقاضا ہے، لہٰذا انھیں پیار کرنے اور تکلیف سے بچانے کے لیے خطبہ روکنا، منبر سے اترنا اور انھیں اٹھالینا عین فطرت انسانیہ کا تقاضا ہے، اگرچہ اس میں وقتی طور پر عبادت سے توجہ ہٹ جائے گی مگر انسان عبادت کے علاوہ اور احکام کا بھی مکلف ہے۔ اور ان سے صرفِ نظر ممکن نہیں۔ باقی رہی آزمائش تو انسان اور اس کی ہر چیز آزمائش ہے۔ اس سے مذمت ثابت نہیں ہوتی الایہ کہ انسان ان چیزوں اور کی وجہ سے گمراہ ہوجائے۔ اعاذ نااللہ۔ نیز رسول اللہ صلی اللہ علیہ وسلم تمام انسانوں کے لیے اسوۂ حسنہ تھے، اس لیے آپ اپنے ظاہری افعال میں عام انسانی جذبات ملحوظ رکھتے تھے، اپنے روحانی درجے اور رتبے کو لوگوں کے لیے تکلیف کا ذریعہ نہیں بناتے تھے۔"}],[1586,"عبدالرحمٰن بن عابس کہتے ہیں میں نے ابن عباس رضی اللہ عنہم سے سنا کہ ایک آدمی نے ان سے پوچھا: کیا آپ عیدین کے لیے جاتے وقت رسول اللہ صلی اللہ علیہ وسلم کے ساتھ موجود تھے؟ تو انہوں نے کہا: جی ہاں، اور اگر میری آپ سے قرابت نہ ہوتی تو میں آپ کے ساتھ نہ ہوتا یعنی اپنی کم سنی کی وجہ سے، آپ اس نشان کے پاس آئے جو کثیر بن صلت کے گھر کے پاس ہے، تو آپ نے (وہاں) نماز پڑھی، پھر خطبہ دیا، پھر آپ عورتوں کے پاس آئے، اور انہیں بھی آپ نے نصیحت کی اور(آخرت کی) یاد دلائی، اور صدقہ کرنے کا حکم دیا، تو عورتیں اپنا ہاتھ اپنے گلے کی طرف بڑھانے (اور اپنا زیور اتار اتار کر) بلال رضی اللہ عنہ کے کپڑے میں ڈالنے لگیں۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن عابس سے روایت ہے کہ ایک آدمی نے حضرت ابن عباس رضی اللہ عنہما سے کہا: کیا آپ کبھی رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عید کے لیے باہر گئے تھے؟ انھوں نے فرمایا: ہاں اور اگر آپ سے مجھے قربت نہ ہوتی تو میں ایسے موقع پر آپ کے ساتھ نہ ہوتا کیونکہ وہ اس وقت بچے تھےآپ اس نشان کے پاس آئے جو کثیر بن صلت کے گھر کے پاس ہے اور وہاں نماز پڑھی، پھر خطبہ ارشاد فرمایا، پھر آپ عورتوں کے پاس تشریف لے گئے۔ انھیں وعظ و نصیحت فرمائی اور صدقے کا حکم دیا۔ عورتیں اپنے ہاتھ اپنے حلق کی طرف بڑھا کر زیور اتارنے لگیں اور حضرت بلال کے کپڑے میں ڈالنے لگیں۔","f2":"(۱)حضرت ابن عباس رضی اللہ عنہما سے یہ سوال اس لیے کیا گیا کہ وہ اس وقت بالغ نہیں تھے اور بچے عام طور پر اس عمر میں عبادات کے بجائے کھیلوں میں زیادہ دلچسپی لیتے ہیں اور اگر عبادات میں شامل بھی ہوں تو امام صاحب سے پچھلی صفوں ہی میں رہتے ہیں مگر ابن عباس رضی اللہ عنہما کی تو بات ہی اور تھی۔ (۲)’’نشان‘‘ سوال و جواب کے وقت یہ جگہ مصلیٰ نہ رہی تھی بلکہ وہاں حضرت کثیر بن صلت تابعی کا گھر بن چکا تھا، البتہ بطور یادگار وہاں نشان تھا۔ آپ کے دور میں وہاں کھلا میدان تھا جہاں عیدوجنازہ وغیرہ پڑھے جاتے تھے۔ (۳)عورتوں سے الگ خطاب کے سلسلے میں دیکھیے، حدیث نمبر:۱۵۷۶کا فائدہ نمبر۲۔"}],[1587,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم عید کے دن نکلے، تو آپ نے دو رکعت نماز پڑھی، نہ تو ان سے پہلے کوئی نماز پڑھی، اور نہ ہی ان کے بعد۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم عید کے دن باہر نکلے اور دورکعتیں پڑھیں۔ ان (دورکعت) سے پہلے یا ان کے بعد کوئی (نفل) نماز نہیں پڑھی۔","f2":"دورکعتوں سے مراد عید کی دورکعتیں ہیں نماز عید سے پہلے اور بعد میں نفل نماز پڑھنے یا نہ پڑھنے سے متعلق بحث پیچھے گزر چکی ہے، تاہم نماز عید کے بعد واپس گھر آکر نوافل پڑھنے کی اجازت ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے عید کی نماز کے بعد گھر میں دو رکعت پڑھنا ثابت ہے۔ واللہ اعلم۔ مزید دیکھیے، حدیث:۱۵۶۲ کے فوائدومسائل اور اسی کتاب کا ابتدائیہ۔"}],[1588,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے عید الاضحی کے دن ہمیں خطبہ دیا، اور (اس کے بعد) آپ دو چتکبرے مینڈھوں کی طرف جھکے اور انہیں ذبح کیا۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں رسول اللہ صلی اللہ علیہ وسلم نے قربانی کے دن خطبہ ارشاد فرمایا، پھر اپنے دو سفید و سیاہ رنگ کے (ابلق) مینڈھوں کی طرف متوجہ ہوئے اور انھیں ذبح فرمایا۔"}],[1589,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عید گاہ ہی میں ذبح یا نحر کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم عیدگاہ میں قربانی کیا کرتے تھے۔","f2":"لوگوں کے سامنے یا عیدگاہ میں قربانی ذبح کرنے کا مقصد لوگوں کو قربانی پر ابھارنا ہے۔ قول کے بعد عملاً بھی، لہٰذا یہ مستحب ہے مگر لازم نہیں۔ اسی طرح دو جانور ذبح کرنا بھی ضروری نہیں، ایک بھی کافی ہے۔ رسول اللہ صلی اللہ علیہ وسلم ایک جانور اپنی اور اپنے آل کی طرف سے اور ایک اپنی امت کی طرف سے ذبح فرمایا کرتے تھے۔ (صحیح مسلم، الاضاحی، حدیث:۱۹۶۷) امت کی طرف سے قربانی کی بابت بعض علماء یوں فرماتے ہیں کہ وہ آپ کا خاصہ ہے جس میں امت کے لیے آپ کی اقتدا جائز نہیں۔ دیکھیے: (ارواءالغلیل:۴؍۳۵۴) امام پر قربانی تبھی ہے اگر وہ قربانی کی طاقت رکھتا ہو۔ امام مالک رحمہ اللہ کے نزدیک ایسے امام کے پیچھے نماز عید نہیں پڑھنی چاہیے جو قربانی نہیں کرسکتا یا نہیں کرتا مگر جمہور اہل علم اس کے قائل نہیں کیونکہ امامت کے لیے تقویٰ اور علم اور شرط ہیں، نہ کہ مالدار ہونا۔ بہرصورت امام قربانی کرنے والا ہو اورعلانیہ لوگوں کے سامنے قربانی کرے تو اچھی بات ہے۔ واللہ اعلم۔"}],[1590,"نعمان بن بشیر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعہ اور عید دونوں میں «سبح اسم ربك الأعلى» اور «هل أتاك حديث الغاشية» پڑھتے تھے، اور جب جمعہ اور عید ایک ہی دن میں جمع ہو جاتے تو بھی آپ انہیں دونوں سورتوں کو پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت نعمان بن بشیر رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جمعے اور عید کی نمازوں میں سورۂ (سبح اسم ربک الاعلیٰ) اور (ھل اتک حدیث الغاشیۃ) پڑھتے تھے۔ جب جمعہ اور عید ایک دن اکٹھے ہوجاتے تو پھر بھی آپ یہی دونوں سورتیں پڑھتے۔","f2":"گویا نبی صلی اللہ علیہ وسلم دونوں نمازیں پڑھاتے تھے اور صحابۂ کرام رضی اللہ عنہم بھی آپ کے پیچھے دونوں نمازیں پڑھتے تھے کیونکہ دونوں مختلف نمازیں ہیں۔ اوقات مختلف ہیں۔ ہیئت میں بھی فرق ہے۔ ایک نفل ہے دوسری فرض۔ بعض حضرات کا خیال ہے کہ عید کا خطبہ جمعے کے خطبے سے کفایت کرجائے گا اور جمعے کی جگہ اصل نماز، یعنی ظہر پڑھی جاسکتی ہے، گویا عید والے دن جمعے کے بجائے ظہر پڑھ لی جائے تو درست ہے مگر یہ انفرادی طور پر ہوسکتا ہے، اجتماعی طور پر جمع ہی پڑھا جائے گا۔ رسول اللہ صلی اللہ علیہ وسلم کی یہی سنت ہے۔ آئندہ حدیث میں رخصت کو انفراد پر محمول کیا جائے گا، نیز یہ رخصت قرب و جوار میں رہنے والے یا دور سے آنے والے سب لوگوں کے لیے یکساں ہے۔ دونوں قسم کے لوگ اس سے مستفید ہوسکتے ہیں کیونکہ حدیث عام ہے۔ کسی فرد کی تخصیص نہیں۔ واللہ اعلم۔"}],[1591,"ایاس بن ابی رملہ کہتے ہیں کہ میں نے معاویہ رضی اللہ عنہ کو سنا، انہوں نے زید بن ارقم رضی اللہ عنہ سے پوچھا: کیا آپ رسول اللہ صلی اللہ علیہ وسلم کے ساتھ عیدین میں رہے ہیں؟ انہوں نے کہا: جی ہاں، آپ نے صبح میں عید کی نماز پڑھی، پھر آپ نے جمعہ نہ پڑھنے کی رخصت دی۔\n§وضاحت\n۱؎: عیدین سے مراد وہ دن ہے جس میں عید اور جمعہ دونوں ایک ساتھ آ پڑتے ہوں۔","الألباني: صحيح",{"u2":"حضرت معاویہ رضی اللہ عنہ نے حضرت زید بن ارقم رضی اللہ عنہ سے پوچھا: کیا آپ عیدین میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر ہوئے تھے؟ انھوں نے فرمایا: ہاں، آپ نے دن کے آغاز میں عید کی نماز پڑھی، پھر آپ نے جمعے کی رخصت دے دی۔","f2":"تفصیل کے لیے دیکھیے‘حدیث‘1591۔"}],[1592,"وہب بن کیسان کہتے ہیں کہ ابن زبیر رضی اللہ عنہم کے دور میں دونوں عیدیں ایک ہی دن میں جمع ہو گئیں، تو ابن زبیر رضی اللہ عنہ نے نکلنے میں تاخیر کی یہاں تک کہ دن چڑھ آیا، پھر وہ نکلے، اور انہوں نے خطبہ دیا، تو لمبا خطبہ دیا، پھر وہ اترے اور نماز پڑھی۔ اس دن انہوں نے لوگوں کو جمعہ نہیں پڑھایا یہ بات ابن عباس رضی اللہ عنہم سے بیان کی گئی تو انہوں نے کہا: انہوں نے سنت پر عمل کیا ہے ۱؎۔\n§وضاحت\n۱؎: صحیح صورت حال یہ ہے کہ آپ صلی اللہ علیہ وسلم نے خود اہل مدینہ کے ساتھ جمعہ پڑھا بھی اور انہیں پڑھایا بھی، ہاں دور سے آنے والے لوگوں کو جمعہ میں آنے سے رخصت دے دی، آپ نے فرمایا تھا: «نحن مجمعون» یعنی ہم تو جمعہ پڑھیں گے، :(ابوداؤد، ابن ماجہ من حدیث ابوہریرہ وابن عباس ) نیز ابھی حدیث رقم ۱۵۹۰ میں گزرا کہ \" جب عید اور جمعہ ایک ہی دن آ پڑتے تھے تو آپ «سبح اسم ربك الأعلى» اور «هل أتاك حديث الغاشية»دونوں میں پڑھا کرتے تھے \"۔","الألباني: صحيح",{"u2":"حضرت وہب بن کیسان نے بیان کیا کہ حضرت عبداللہ بن زبیر رضی اللہ عنہما کے دور (خلافت) میں جمعہ اور عید اکٹھے ہوگئے تو انھوں نے عید کے لیے نکلنے میں دیر کردی حتی کہ دن (کافی) اونچا ہوگیا، پھر وہ نکلے اور خطبہ دیا اور بہت لمبا خطبہ دیا، پھر اترے اور عید کی نماز پڑھائی اور اس دن لوگوں کو جمعہ نہیں پڑھایا۔ یہ بات حضرت ابن عباس رضی اللہ عنہما سے ذکر کی گئی تو انھوں نے فرمایا: انھوں نے سنت پر عمل کیا۔","f2":"یہاں سنت سے مراد رخصت ہے۔ چونکہ رخصت نبی صلی اللہ علیہ وسلم کے قول سے ثابت ہے، لہٰذا اسے سنت کہا۔ ورنہ آپ کی سنت، یعنی عمل تو عید کے بعد جمعہ پڑھنا اور پڑھانا ہے۔ عمل بھی آپ کی سنت ہی پر کرنا چاہیے۔ اگرچہ رخصت کی گنجائش ہے مگر فرداً نہ کہ اجتماعاً۔ سنن ابی داود اور سنن ابن ماجہ کی روایت میں صراحت ہے کہ ہم جمعہ قائم کریں گے۔ (سنن ابی داود، الصلاۃ، حدیث:۱۰۷۳، وسنن ابن ماجہ، اقامۃ الصلوات والسنۃ فیھا، حدیث:۱۳۱۱)، لہٰذا جمعہ قائم ہونا چاہیے۔"}],[1593,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ان کے پاس دو لڑکیاں دف بجا رہی تھیں اور رسول اللہ صلی اللہ علیہ وسلم ان کے پاس تشریف لائے، تو ان دونوں کو ابوبکر رضی اللہ عنہ نے ڈانٹا، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"انہیں چھوڑو (بجانے دو) کیونکہ ہر قوم کی ایک عید ہوتی ہے\" (جس میں لوگ کھیلتے کودتے اور خوشی مناتے ہیں)۔","الألباني: صحيح",{"u2":"حضرت عائشہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (عید کے دن) ان کے پاس تشریف لے گئے اور ان کے ہاں (گھر میں) دو بچیاں دف بجا رہی تھیں۔ (آپ نے انھیں نہ روکا، پھر ابوبکرداخل ہوئے تو) ابوبکر رضی اللہ عنہ نے انھیں ڈانٹا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’رہنے دو! ہر قوم کی عید ہوتی ہے (جس میں وہ کھیل کود بھی لیتے ہیں)۔‘‘","f2":"(۱)دف بجانا غیرضروری کام تو ہے مگر حرام نہیں، لہٰذا خوشی کے موقع پر نابالغ و غیرمکلف بچیاں اگر یہ کام کرلیں تو عید کی وسعت چشم پوشی کا تقاضا کرتی ہے۔ اگرچہ اس کی حوصلہ افزائی نہیں کی جائے گی مگر روکا بھی نہیں جائے گا، البتہ حرام کام، مثلاً: موسیقی یا ڈھول وغیرہ، کو روکا جائے گا۔ حوصلہ افزائی تو کسی صورت بھی نہ کی جائے گی۔ جبکہ دیگر احادیث میں ہے کہ آپ چہرہ انور ڈھانپ کرلیٹے ہوئے تھے۔ دیکھیے: (حدیث:۱۵۹۸ اور اس کے فوائد ملاحظہ فرمائیے) گویا نہ ان کی طرف توجہ کی، نہ دیکھا، نہ ان سے پیار کیا، نہ شاباش دی بلکہ اعراض کیا اور چشم پوشی فرمائی۔ (۲)عید اور شادی وغیرہ کے موقع پر اگر چھوٹی بچیاں اپنے طور پر دف بجالیں اور پاکیزہ گانے گالیں تو کوئی حرج نہیں، البتہ اس کام کا اہتمام نہ کیا جائے۔ (۳)دف نصف ڈھول کو کہہ سکتے ہیں، یعنی ایک طرف سے بند اور دوسری طرف سے کھلا۔ اسے بجانے سے زیادہ آواز نہیں پیدا ہوتی۔ گھڑا یا پرات وغیرہ بجانا بھی دف کی ذیل میں آسکتا ہے لیکن شرط یہ ہے کہ بجانے والیں نابالغ بچیاں ہوں، البتہ ڈھول کی آواز بہت بلند اورمکروہ ہوتی ہے، لہٰذا وہ منع ہے۔"}],[1594,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ عید کے دن حبشی لوگ آئے وہ نبی اکرم صلی اللہ علیہ وسلم کے سامنے کھیل کود رہے تھے، آپ نے مجھے بلایا، تو میں انہیں آپ کے کندھے کے اوپر سے دیکھ رہی تھی میں برابر دیکھتی رہی یہاں تک کہ میں (خود) ہی لوٹ آئی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ عید کے دن حبشی آئے اور نبی صلی اللہ علیہ وسلم کے سامنے کھیلنے لگے۔ آپ نے مجھے بلایا۔ میں (آپ کی اوٹ میں کھڑی ہوکر) آپ کے کندھے کے اوپر سے انھیں کھیلتے دیکھنے لگی۔ میں دیکھتی رہی حتی کہ میں خود ہی ہٹ گئی۔","f2":"کھیلنا خصوصاً جنگی تربیت والے کھیل کھیلتا تو قطعاً مکروہ نہیں۔ عید کے دن بدرجۂ اولیٰ جائز ہیں۔ حضرت عائشہ رضی اللہ عنہا ان کے سامنے نہیں تھیں بلکہ اپنے حجرے میں تھیں اور آپ کی اوٹ میں تھیں۔ ان کو نظر نہ آتی تھیں، نیز حضرت عائشہ رضی اللہ عنہا ان حبشیوں کو نہیں بلکہ ان کا کھیل دیکھ رہی تھیں۔ عورتوں کے لیے مردوں کو قصداً دیکھنا منع ہے بالتبع دیکھنا منع نہیں۔ یہاں مقصود کھیل دیکھنا تھا، نہ کہ مرد۔ اگرچہ بالتبع وہ بھی نظر آتے تھے۔ جیسے راستے پر چلتے وقت باوجود پردے کے عورت کو مرد نظر آتے ہیں۔"}],[1595,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا کہ آپ مجھے اپنی چادر سے آڑ کئے ہوئے تھے، اور میں حبشیوں کو دیکھ رہی تھی کہ وہ مسجد میں کھیل رہے تھے، یہاں تک کہ میں خود ہی اکتا گئی، تم خود ہی اندازہ لگا لو کہ ایک کم سن لڑکی کھیل کود (دیکھنے) کی کتنی حریص ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: میں نے اللہ کے رسول صلی اللہ علیہ وسلم کو دیکھا، آپ نے مجھے اپنی چادر سے چھپایا ہوا تھا اور میں حبشیوں کو مسجد میں کھیلتے ہوئے دیکھ رہی تھی حتی کہ میں ہی اکتا گئی۔ ذرا اندازہ لگائو ایک نوعمر لڑکی جو کھیل کی بہت شائق ہو، کتنی دیر تک کھڑی دیکھتی رہی ہوگی۔ (آپ اتنی دیر تک اس کے لیے کھڑے رہے۔)","f2":"مسجد میں کھیلنے اور عورت کا اسے دیکھنے کی تفصیل سابقہ حدیث کے حاشیے میں گزر چکی ہے۔ اس واقعے سے رسول اللہ صلی اللہ علیہ وسلم کے خلق عظیم اور بیوی سے حسن سلوک کا پتہ چلتا ہے کہ آپ نے اپنی بیوی کے جذبات کا کس قدر خیال رکھا، اچھا انسان وہی ہے جو دوسروں کے جائز جذبات کا خیال رکھے۔ اپنے جذبات کا تو ہر کوئی خیال رکھتا ہے۔"}],[1596,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ عمر رضی اللہ عنہ (مسجد میں) داخل ہوئے، حبشی لوگ مسجد میں کھیل رہے تھے تو آپ انہیں ڈانٹنے لگے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمر! انہیں چھوڑو (کھیلنے دو) یہ \"بنو ارفدہ\" ہی تو ہیں\"۔\n§وضاحت\n۱؎: بنی ارفدہ حبشیوں کا لقب ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ حضرت عمر رضی اللہ عنہ مسجد میں داخل ہوئے تو حبشی مسجد میں (جنگی کھیل) کھیل رہے تھے۔ حضرت عمر رضی اللہ عنہ نے انھیں ڈانٹا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’عمر! رہنے دو۔ یہ بنوارفدہ (حبشی لوگ) ہیں (اور جنگی کھیل کھیلنا ان کی فطرت میں داخل ہے)۔‘‘","f2":"(۱)مسجد کھیل کود کے لیے نہیں ہوتی مگر چونکہ یہ کھیل فضول نہ تھا بلکہ نیزوں اور برچھیوں سے کھیل رہے تھے جو کہ مسلمانوں کی جہادی قوت کا ذریعہ ہے، لہٰذا اسے مسجد میں گوارا فرمایا۔ ورنہ فٹ بال اور کرکٹ وغیرہ مسجد میں نہیں کھیلے جاسکتے کہ وہ صرف لہوولعب ہیں یا زیادہ سے زیادہ جسمانی ورزش کے لیے ہیں۔ ان کو کھیلنے والے کی نیت ’’جہادی‘‘ نہیں ہوتی۔ (۲)’’بنوارفدہ‘‘ حبشیوں کا لقب ہے یا ان کے جدامجد کی طرف نسبت ہے۔"}],[1597,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ابوبکر صدیق رضی اللہ عنہ ان کے (گھر میں) داخل ہوئے، ان کے پاس دو لڑکیاں دف بجا رہی تھیں، اور گانا گا رہی تھیں۱؎، رسول اللہ صلی اللہ علیہ وسلم اپنا چہرہ اپنے کپڑے سے ڈھانپے ہوئے تھے، تو آپ نے اپنا چہرہ کھولا، اور فرمایا: \"ابوبکر! انہیں چھوڑو کھیلنے دو، یہ عید کے دن ہیں، اور منی کے دن تھے\" ۲؎ اور رسول اللہ صلی اللہ علیہ وسلم ان دنوں مدینہ میں تھے۔\nكتاب قيام الليل وتطوع النهار\n§وضاحت\n۱؎: یہ گانا کوئی فحش گانا نہیں تھا، بلکہ ان کے آباء و اجداد کی بہادری کے قصے تھے، فحش گانے کسی بھی صورت میں اور کسی بھی موقع پر جائز نہیں، نیز جائز گانوں میں بھی موسیقی کی آمیزش ہو تو جائز نہیں۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ (والدمحترم) حضرت ابوبکرصدیق رضی اللہ عنہ میرے ہاں تشریف لائے تو میرے پاس دو بچیاں دف بجارہی تھیں اور (جنگی) نغمے گا رہی تھیں جبکہ رسول اللہ صلی اللہ علیہ وسلم کپڑا اوڑھے لیٹے ہوئے تھے۔ (حضرت ابوبکر نے انھیں جھڑکا تو) آپ صلی اللہ علیہ وسلم نے اپنے چہرۂ مبارک سے کپڑا ہٹایا اورفرمایا: ’’ابوبکر! انھیں رہنے دو۔ یہ عید کے دن ہیں۔‘‘ یہ وہ دن تھے جن میں حاجی منٰی میں ہوتے ہیں۔ (یعنی ایام تشریق) اور اللہ کے رسول صلی اللہ علیہ وسلم ان دنوں مدینہ منورہ میں تھے۔","f2":"یہ حدیث پیچھے گزر چکی ہے۔ تفصیل کے لیے دیکھیے فوائدومسائل حدیث نمبر: ۱۵۹۴۔ تعجب ہے بعض لوگوں نے اس سے موسیقی اور سماع کے جواز پر استدلال کیا ہے اور، پھر اس بنیاد پر مجالس سماع ووجد منعقدکی جاتی ہیں جن میں قوال غلط سلط اشعار، جن سے توحید کے بجائے شرک پر زیادہ دلالت ہوتی ہے، آلات موسیقی سمیت الاپتے ہیں اور سامعین نہ صرف سردھنتے ہیں بلکہ وجد میں آخر بے ہودہ حرکات کرتے ہیں۔ اس لہوولعب میں مشغولیت کی بنا پر نماز اور قرآن سے بھی بے نیازی برتی جاتی ہے۔ ذرا سوچیے! کیا یہ اتفاقی اور سادہ واقعہ اتنی بڑی واہیات عمارت کی بنیاد بن سکتا ہے؟ ایک بزرگ نے کیا خوب کہا ہے کہ اگر اس واقعے سے استدلال کرنا ہے تو تمام جزئیات سمیت کیا جائے۔ نابالغ بچیاں صرف دف پر جنگی اشعار پڑھیں۔ داخل ہونے والا اس میں دلچسپی نہ لے بلکہ ان سے منہ موڑ کر ایک طرف لیٹ جائے، پھر کوئی آنے والا انھیں جھڑکے اور ڈانٹے مگر اسے مارنے سے روک دیا جائے، پھر وہ بچیاں بھی خوف زدہ ہوکر چپ ہوجائیں، پھر اشارے سے انھیں بھگا دیا جائے۔ اگر اسے آپ محفل سماع یا بزم غنا کا نام دے سکیں تو بڑے شوق سے ایسی مجلس منعقد فرمائیں۔ ورنہ حدیث کا نام لے کر دین کو بدنام نہ کریں۔ موت کو یاد رکھیں اور تمام قدرتوں کے مالک اللہ تعالیٰ سے ڈریں۔"}],[1598,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اپنے گھروں میں نماز پڑھو، انہیں قبرستان نہ بناؤ\"۔\n§وضاحت\n۱؎: نماز سے مراد نوافل اور سنتیں ہیں۔ \"انہیں قبرستان نہ بناؤ\" یعنی اس سے معلوم ہوا کہ جن گھروں میں نوافل کی ادائیگی کا اہتمام نہیں ہوتا وہ قبرستان کی طرح ہوتے ہیں، جس طرح قبریں عمل اور عبادت سے خالی ہوتی ہیں اسی طرح ایسے گھر بھی عمل اور عبادت سے محروم ہوتے ہیں۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنے گھروں میں نماز (نفل) پڑھا کرو۔ انھیں قبرستان نہ بنالو۔‘‘","f2":"(۱)عذر کے سوا فرض نماز مسجد میں باجماعت پڑھنی چاہیے، البتہ نفل نماز گھر اور مسجد دونوں میں پڑھی جاسکتی ہے۔ مسجد فرض نمازوں سے آباد ہوجائے گی۔ گھروں کو نفل نماز ہی سے آباد کیا جاسکتا ہے، لہٰذا نفل نماز گھر میں پڑھنا بہتر اور افضل ہے۔ عورتوں کے لیے فرض نماز بھی گھر ہی میں پڑھنا افضل ہے اگرچہ مسجد میں بھی وہ فرض نماز پڑھ سکتی ہیں۔ اس طرح گھروں کو اللہ کے ذکر سے آباد کیا جاسکتا ہے۔ گھر اور دل وہی آباد اور زندہ ہیں جن میں اللہ کا ذکر ہو ورنہ ویران اورمردہ ہیں۔ اس لحاظ سے نبی صلی اللہ علیہ وسلم نے ان گھروں کو قبرستان سے تشبیہ دی ہے جہاں اللہ کا ذکر نہیں ہوتا اور جہاں نماز پڑھنی قطعاً منع ہے۔ اور اللہ کے ذکر کی اصل اور اعلیٰ صورت نماز ہی ہے۔ (۲) اس روایت سے ضمناً یہ بھی معلوم ہوتا ہے کہ قبرستان میں نماز نہیں پڑھی جاسکتی سوائے نماز جنازہ کے کہ اس میں رکوع اور سجدہ نہیں ہے۔ بعض شارعین نے اس روایت کے یہ معنی بھی کیے ہیں کہ گھروں میں قبریں نہ بناؤ ورنہ قبروں کی وجہ سے گھروں میں نماز نہ پڑھ سکو گے۔ یہ مسئلہ تو صحیح ہے مگر اس معنی میں ذرا تکلف ہے۔ (۳)اس روایت کا یہ مطلب نہیں کہ مسجد میں نفل اور سنت پڑھے نہیں جاسکتے بلکہ مطلب یہ ہے کہ گھروں میں بھی نوافل پڑھا کرو۔"}],[1599,"زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے مسجد میں چٹائی سے گھیر کر ایک کمرہ بنایا، تو آپ نے اس میں کئی راتیں نمازیں پڑھیں یہاں تک کہ لوگ آپ کے پاس جمع ہونے لگے، پھر ان لوگوں نے ایک رات آپ کی آواز نہیں سنی، وہ سمجھے کہ آپ سو گئے ہیں، تو ان میں سے کچھ لوگ کھکھارنے لگے، تاکہ آپ ان کی طرف نکلیں تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں اس کام میں برابر لگا دیکھا تو ڈرا کہ کہیں وہ تم پر فرض نہ کر دی جائے، اور اگر وہ تم پر فرض کر دی گئی تو تم اسے ادا نہیں کر سکو گے، تو لوگو! تم اپنے گھروں میں نمازیں پڑھا کرو، کیونکہ آدمی کی سب سے افضل (بہترین) نماز وہ ہے جو اس کے گھر میں ہو سوائے فرض نماز کے\"۔\n§وضاحت\n۱؎: یہ حکم تمام نفلی نمازوں کو شامل ہے، البتہ اس حکم سے وہ نمازوں مستثنی ہیں جو شعائر اسلام میں شمار کی جاتی ہیں مثلاً عیدین، استسقاء اور کسوف و خسوف :(چاند اور سورج گرہن ) کی نمازوں۔","الألباني: صحيح",{"u2":"حضرت زید بن ثابت رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے مسجد میں کھجور کی چٹائی کو کھڑا کرکے حجرہ سا بنالیا (تاکہ سکون سے رات کی نماز پڑھ سکیں) اللہ کے رسول صلی اللہ علیہ وسلم نے کئی راتیں اس میں نماز پڑھی حتی کہ لوگ بھی آپ کے قریب جمع ہونے لگ گئے (اور آپ کی نماز کے ساتھ نماز پڑھنے لگے) پھر ایک رات انھوں نے آپ کی آواز محسوس نہ کی۔ انھوں نے سمجھا کہ آپ سوئے ہوئے ہیں۔ ان میں سے کچھ کھنکارنے لگے تاکہ آپ (جاگ کر) ان کی طرف تشریف لے آئیں۔ (مگر آپ نہ نکلے، پھر صبح کے وقت) آپ نے فرمایا: ’جو کچھ تم کرتے رہے ہو میں دیکھتا رہا ہوں (مگر، اس لیے نہیں نکلا کہ) مجھے خطرہ پیدا ہوا کہ کہیں (تمھارے ذوق شوق کی وجہ سے) تم پر رات کی نماز فرض ہی نہ کردی جائے۔ اور اگر تم پر فرض کردی جاتی تو تم اسے ادا نہ کر پاتے، لہٰذا اے لوگو رات کی نماز اپنے گھروں میں پڑھ لیا کرو کیونکہ فرض نماز کے علاوہ انسان کی افضل نماز وہ ہے جو گھر میں پڑھے۔‘‘","f2":"(۱)دوسری روایات میں صراحت ہے کہ یہ رمضان المبارک کی بات ہے اور یہاں رات کی نماز سے مراد تراویح ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے حجرہ سا بنانے سے معلوم ہوتا ہے کہ آپ معتکف ہوں گے ورنہ آپ رات کی نماز گھر میں پڑھا کرتے تھے۔ یا ممکن ہے کہ گھر میں کسی وجہ سے تنگی ہو اور آپ نے علیحدگی میں نماز پڑھنے کے لیے چٹائی کھڑی کی ہو۔ (۲)’’فرض نہ کردی جائے‘‘ رمضان المبارک میں تراویح کا فرض ہوجانا پانچ نمازوں میں اضافے کے مترادف نہیں کہ اعتراض پیدا ہوکہ (لا یبدل القول لذی) کے الفاظ (جو اللہ تعالیٰ نے لیلۃ الاسراء میں پانچ نماز کی فرضیت کے وقت فرمائے تھے) کے بعد تو فرضیت کا خطرہ نہیں تھا کیونکہ اس قول میں صرف روزانہ کی پانچ نمازوں میں اضافہ یا کمی کی نفی کی گئی ہے اور تراویح کی، بالفرض، فرضیت سے یومیہ نمازوں میں کوئی فرق نہیں پڑتا۔ (۳)رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد فرضیت کا خطرہ ناپید ہوگیا، لہٰذا نماز تراویح کو مسجد میں مستقل باجماعت جاری کردیا گیا جو خلفائے راشدین کے دور سے لے کر اب تک بلانزاع امت میں جاری و ساری ہے اور اجماعی مسئلہ ہے اور سنت المسلمین بن چکا ہے۔ اب کسی مسجد کو اس سعادت سے محروم نہیں رکھا جائے گا، البتہ اگر کوئی شخص انفرادی طور پر گھر میں ادا کرنا چاہے تو بھی جائز ہے مگر ضروری ہے کہ وہ نماز تراویح میں قرآن مجید زیادہ پڑھنے کے قابل ہوتاکہ اصل مقصد پورا ہو، نہ کہ صرف رکعات کی گنتی پوری کرے۔"}],[1600,"کعب بن عجرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مغرب کی نماز قبیلہ بنی عبدالاشہل کی مسجد میں پڑھی، جب آپ پڑھ چکے تو کچھ لوگ کھڑے ہو کر سنت پڑھنے لگے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس (سنت) نماز کو گھروں میں پڑھنے کی پابندی کرو\"۔","الألباني: صحيح",{"u2":"حضرت کعب بن حجرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے (ایک دفعہ) مغرب کی نماز بنوعبدالاشہل کی مسجد میں پڑھی۔ جب آپ نماز (فرض) سے فارغ ہوئے تو کچھ لوگ اٹھ کر نوافل (مغرب کی سنتیں) پڑھنے لگے۔ آپ نے فرمایا: ’’یہ نماز گھروں میں پڑھا کرو۔‘‘","f2":"یہ ’’نماز‘‘ یعنی مغرب کی سنتیں یا مطلقاً سنتیں اور نافل۔ یہ امر استحباب کے لیے ہے، نہ کہ وجوب کے لیے کیونکہ خود رسول اللہ صلی اللہ علیہ وسلم سے مغرب کے بعد نوافل مسجد میں پڑھنا ثابت ہے۔ دیکھیے: (سنن ابی داود، التطوع، حدیث:۱۳۰۱) آج کل زندگی اس قدر تیز اور مصروف ہوگئی ہے کہ فرضوں کے بعد والی سنتیں رہ جانے کا خطرہ ہے جو ایک قبیح باب ہے اگر ایسی ہو تو سنن رواتب فرض نماز کے بعد مسجد ہی میں ادا کرلینی چاہییں۔"}],[1601,"سعد بن ہشام سے روایت ہے کہ وہ ابن عباس رضی اللہ عنہم سے ملے تو ان سے وتر کے متعلق پوچھا، تو انہوں نے کہا: کیا میں تمہیں اہل زمین میں رسول اللہ صلی اللہ علیہ وسلم کی وتر کے بارے میں سب سے زیادہ جاننے والے کے بارے میں نہ بتاؤں؟ سعد نے کہا: کیوں نہیں (ضرور بتائیے) تو انہوں نے کہا: وہ ام المؤمنین عائشہ رضی اللہ عنہا ہیں، ان کے پاس جاؤ، اور ان سے سوال کرو، پھر میرے پاس لوٹ کر آؤ، اور وہ تمہیں جو جواب دیں اسے مجھے بتاؤ، چنانچہ میں حکیم بن افلح کے پاس آیا، اور ان سے میں نے اپنے ساتھ ام المؤمنین عائشہ رضی اللہ عنہا کے پاس لے چلنے کے لیے کہا، تو انہوں نے انکار کیا، اور کہنے لگے: میں ان سے نہیں مل سکتا، میں نے انہیں ان دو گروہوں ۱؎ کے متعلق کچھ بولنے سے منع کیا تھا، مگر وہ بولے بغیر نہ رہیں، تو میں نے حکیم بن افلح کو قسم دلائی، تو وہ میرے ساتھ آئے، چنانچہ وہ عائشہ رضی اللہ عنہا کے گھر میں داخل ہوئے، تو انہوں نے حکیم سے کہا: تمہارے ساتھ یہ کون ہیں؟ میں نے کہا: سعد بن ہشام ہیں، تو انہوں نے کہا: کون ہشام؟ میں نے کہا: عامر کے لڑکے، تو انہوں نے ان (عامر) کے لیے رحم کی دعا کی، اور کہا: عامر کتنے اچھے آدمی تھے۔ سعد نے کہا: ام المؤمنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کے اخلاق کے بارے میں بتائیے تو انہوں نے کہا: کیا تم قرآن نہیں پڑھتے؟ میں نے کہا: کیوں نہیں، ضرور پڑھتا ہوں، تو انہوں نے کہا: نبی کریم صلی اللہ علیہ وسلم کے اخلاق سراپا قرآن تھے، پھر میں نے اٹھنے کا ارادہ کیا تو مجھے رسول اللہ صلی اللہ علیہ وسلم کے قیام اللیل کے متعلق پوچھنے کا خیال آیا، تو میں نے کہا: ام المؤمنین! مجھے نبی کریم صلی اللہ علیہ وسلم کے قیام اللیل کے متعلق بتائیے، انہوں نے کہا: کیا تم سورۃ «يا أيها المزمل» نہیں پڑھتے؟ میں نے کہا: کیوں نہیں، ضرور پڑھتا ہوں، تو انہوں نے کہا: اللہ تعالی نے اس سورۃ کے شروع میں قیام اللیل کو فرض قرار دیا، تو نبی کریم صلی اللہ علیہ وسلم اور آپ کے صحابہ نے ایک سال تک قیام کیا یہاں تک کہ ان کے قدم سوج گئے، اللہ تعالی نے اس سورۃ کی آخر کی آیتوں کو بارہ مہینے تک روکے رکھا، پھر اللہ تعالی نے اس سورۃ کے آخر میں تخفیف نازل فرمائی، اور رات کا قیام اس کے بعد کہ وہ فرض تھا نفل ہو گیا، میں نے پھر اٹھنے کا ارادہ کیا، تو میرے دل میں یہ بات آئی کہ میں رسول اللہ صلی اللہ علیہ وسلم کی وتر کے متعلق بھی پوچھ لوں، تو میں نے کہا: ام المؤمنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کی وتر کے بارے میں بھی بتائیے تو انہوں نے کہا: ہم آپ کے لیے مسواک اور وضو کا پانی رکھ دیتے، تو اللہ تعالی رات میں آپ کو جب اٹھانا چاہتا اٹھا دیتا تو آپ مسواک کرتے، اور وضو کرتے، اور آٹھ رکعتیں پڑھتے ۲؎ جن میں آپ صرف آٹھویں رکعت میں بیٹھتے، ذکر الٰہی کرتے، دعا کرتے، پھر سلام پھیرتے جو ہمیں سنائی دیتا، پھر سلام پھیرنے کے بعد آپ بیٹھے بیٹھے دو رکعتیں پڑھتے، پھر ایک رکعت پڑھتے تو اس طرح کل گیارہ رکعتیں ہوئیں۔ پھر جب رسول اللہ صلی اللہ علیہ وسلم بوڑھے ہو گئے، اور جسم پر گوشت چڑھ گیا تو وتر کی سات رکعتیں پڑھنے لگے، اور سلام پھیرنے کے بعد بیٹھے بیٹھے دو رکعتیں پڑھتے، تو میرے بیٹے! اس طرح کل نو رکعتیں ہوئیں، اور رسول اللہ صلی اللہ علیہ وسلم جب کوئی نماز پڑھتے تو آپ کو یہ پسند ہوتا کہ اس پر مداومت کریں، اور جب آپ نیند، بیماری یا کسی تکلیف کی وجہ سے رات کا قیام نہیں کر پاتے تو آپ (اس کے بدلہ میں) دن میں بارہ رکعتیں پڑھتے تھے، اور میں نہیں جانتی کہ نبی اکرم صلی اللہ علیہ وسلم نے پورا قرآن ایک رات میں پڑھا ہو، اور نہ ہی آپ پوری رات صبح تک قیام ہی کرتے، اور نہ ہی کسی مہینے کے پورے روزے رکھتے، سوائے رمضان کے، پھر میں ابن عباس رضی اللہ عنہم کے پاس آیا، اور میں نے ان سے ان کی یہ حدیث بیان کی، تو انہوں نے کہا: عائشہ رضی اللہ عنہا نے سچ کہا، رہا میں تو اگر میں ان کے یہاں جاتا ہوتا تو میں ان کے پاس ضرور جاتا یہاں تک کہ وہ مجھ سے براہ راست بالمشافہ یہ حدیث بیان کرتیں۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: اسی طرح میری کتاب میں ہے، اور میں نہیں جانتا کہ کس شخص سے آپ کی وتر کی جگہ کے بارے میں غلطی ہوئی ہے ۳؎۔\n§وضاحت\n۱؎: یعنی معاویہ اور علی رضی اللہ عنہم کے درمیان میں۔ ۲؎: کسی راوی سے وہم ہو گیا ہے، صحیح \" نو رکعتیں \" ہے، جیسا کہ صحیح مسلم میں ہے، آٹھ رکعتیں لگاتار پڑھتے، اور آٹھویں رکعت پر بیٹھ کر نویں رکعت کے لیے اٹھتے۔ ۳؎: وتر کی جگہ میں غلطی اس طرح ہوئی ہے کہ اس حدیث میں بیٹھ کر پڑھی جانے والی دونوں رکعتوں کو اس وتر کی رکعت پر مقدم کر دیا گیا جسے آپ آٹھویں کے بعد پڑھتے تھے، صحیح یہ ہے کہ آپ ان دونوں رکعتوں کو بیٹھ کر وتر کے بعد پڑھتے تھے جیسا کہ مسلم کی روایت میں ہے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ہشام سے روایت ہے کہ میں حضرت ابن عباس رضی اللہ عنہما سے ملا اور ان سے نماز وتر کے بارے میں پوچھا تو انھوں نے فرمایا: کیامیں تجھے اس شخصیت کے بارے میں نہ بتاؤں جو روئے زمین پر بسنے والے انسانوں میں سے سب سے زیادہ رسول اللہ صلی اللہ علیہ وسلم کی نماز وتر کو جانتی ہو؟ سعد نے کہا: ہاں، ضرور۔ انھوں نے فرمایا: وہ حضرت عائشہ رضی اللہ عنہا ہیں۔ ان سے جاکر پوچھو، پھر واپس آکر مجھے بھی بتاؤ کہ انھوں نے کیا جواب دیا، چنانچہ میں حضرت حکیم بن افلح کے پاس آیا اور انھیں بھی ساتھ چلنے کے لیے کہا۔ وہ کہنے لگے: میں تو ان کے پاس نہیں جاؤں گا کیونکہ میں نے ان سے گزارش کی تھی کہ آپ ان دو لڑنے والے گروہوں (عثمانی و علوی) کے بارے میں کچھ بھی نہ کہیں مگر انھوں نے میری بات نہیں مانی بلکہ اپنی مرضی کی۔ میں نے انھیں قسم دی (کہ وہ ضرور چلیں) تو وہ میرے ساتھ چل پڑے اور حضرت عائشہ رضی اللہ عنہا کے پاس پہنچے۔ حضرت عائشہ رضی اللہ عنہا نے ان سے کہا: یہ تمھارے ساتھ کون ہے؟ میں نےکہا: سعد بن ہشام۔ انھوں نے فرمایا: کون سا ہشام؟ میں نے کہا: ہشام بن عامر۔ تو آپ نے ان کےلیے رحمت کی دعا کی اور فرمایا: عامر بہت اچھے انسان تھے۔ میرے ساتھی نے کہا: اے ام المومنین! آپ مجھے رسول اللہ صلی اللہ علیہ وسلم کے اخلاق عالیہ کے بارے میں بتائیے۔تو فرمانے لگیں: کیا تم قرآن نہیں پڑھتے؟ میں نے کہا: کیوں نہیں (پڑھتا ہوں) انھوں نے فرمایا: نبی صلی اللہ علیہ وسلم کے اخلاق عالیہ عین قرآن کے مطابق تھے۔ میں نے اٹھنے کا ارادہ کیا تو میرے ذہن میں رسول اللہ صلی اللہ علیہ وسلم کے قیام اللیل (رات کی عبادت) کا خیال آیا۔ میں نے کہا: اے ام المومنین! مجھے نبی صلی اللہ علیہ وسلم کے قیام اللیل کے بارے میں بتائیے۔ انھوں نے فرمایا: کیا تم یہ سورت (یایھا المزمل) نہیں پڑھتے؟ میں نے کہا: کیوں نہیں (پڑھتا ہوں۔) فرمانے لگیں: اللہ تعالیٰ نے اس سورت کے شروع میں رات کا قیام فرض کیا تھا۔ تو نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ ایک سال تک قیام کرتے رہے حتی کہ ان کے پاؤں سوج گئے۔ اللہ تعالیٰ نے اس سورت کی آخری آیتیں (دوسرا رکوع) بارہ مہینے روک رکھیں، پھر ان آیات میں تخفیف نازل فرمائی تو قیام اللیل نفل بن گیا جبکہ پہلے فرض تھا۔ میں نے، پھر اٹھنے کا ارادہ کیا کہ اچانک میرے ذہن میں رسول اللہ صلی اللہ علیہ وسلم کی نماز وتر کا خیال آگیا۔ میں نے کہا: اے ام المومنین! مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز وتر کے بارے میں بتائیے۔ انھوں نے فرمایا: ہم رات کو آپ کی مسواک اور طہارت کا پانی تیار کرکے رکھ دیتے تھے، پھر اللہ تعالیٰ جب پسند فرماتا آپ کو جگا دیتا۔ آپ (اٹھ کر) مسواک فرماتے اور وضو کرتے، پھر آٹھ رکعات اس طرح پڑھتے کہ ان میں سے کسی رکعت کے بعد نہیں بیٹھتے تھے مگر آٹھویں رکعت کے بعد بیٹھتے، اللہ تعالیٰ کا ذکر فرماتے اور دعائیں کرتے، پھر اتنی آواز سے سلام کہتے کہ ہمیں سنائی دیتا، پھر سلام کے بعد بیٹھے بیٹھے دو رکعت پڑھتے، پھر ایک رکعت پڑھتے۔ بیٹا! اس طرح یہ گیارہ رکعتیں بن گئی، پھر جب رسول اللہ صلی اللہ علیہ وسلم کی عمر زیادہ ہوگئی اور بوجھل ہوگئے تو سات رکعات پڑھتے اور سلام کے بعد بیٹھے بیٹھے دو رکعتیں پڑھتے۔ بیٹا! اس طرح یہ نو رکعتیں بن گئیں۔ رسول اللہ صلی اللہ علیہ وسلم جب کوئی نماز شروع فرمالیتے تو مناسب سمجھتے تھے کہ اسے ہمیشہ پڑھا کریں اور اگر کبھی نیند یا بیماری یا کوئی تکلیف رات کی نماز سے رکاوٹ بن جاتی تو دن کو (بجائے گیارہ کے) بارہ رکعات پڑھ لیتے۔ اور مجھے علم نہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی ایک رات میں پورا قرآن پڑھا ہو یا کبھی صبح تک ساری رات نماز پڑھتے رہے ہوں یا رمضان المبارک کے علاوہ کبھی پورا مہینہ روزے رکھے ہوں، پھر میں حضرت ابن عباس رضی اللہ عنہما کے پاس آیا اور ان کے سامنے یہ پوری حدیث بیان کی۔ آپ فرمانے لگے: سچ کہا حضرت عائشہ رضی اللہ عنہا نے۔ واللہ! اگر میں ان کے پاس جاتا ہوتا تو ضرور جاتا کہ وہ مجھے براہ راست یہ حدیث بیان فرمائیں۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث میری کتاب میں ایسے ہی ہے۔ میں نہیں جانتا آپ صلی اللہ علیہ وسلم کے وتر کے بیان میں کس سے غلطی ہوگئی؟","f2":"(۱)امام نسائی رحمہ اللہ کے اس فرمان میں اشارہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے گیارہ رکعت وتر کے بیان میں کسی راوی سے خطا ہوگئی ہے کیونکہ یہاں دو رکعتوں کو ایک رکعت سے مقدم بیان کیا گیا ہے، حالانکہ صحیح مسلم کی ایک روایت کے مطابق صحیح یہ ہے کہ آپ نو رکعتیں اس طرح پڑھتے کہ صرف آٹھویں رکعت پر بیٹھتے، پھر اللہ تعالیٰ کا ذکر فرماتے اور دعائیں کرتے، پھر سلام پھیرے بغیر کھڑے ہوجاتے اور نویں رکعت پڑھ کر بیٹھ جاتے اور ذکروددعا وغیرہ کے بعد آواز کے ساتھ سلام پھیرتے کہ ہمیں سنائی دیتا، پھر سلام کے بعد بیٹھے بیٹھے دو رکعتیں پڑھتے۔ اس طرح یہ گیارہ رکعتیں ہوگئیں۔ (صحیح مسلم، صلاۃ المسافرین، حدیث:۷۴۶) کسی راوی سے تقدیم و تاخیر ہوگئی۔ آگے نو رکعت وتر کے بیان سے بھی اس غلطی کی نشان دہی ہوتی ہے کیونکہ وہاں مسلم کی روایت کی طرح دو رکعتوں کو ایک رکعت سے مؤخر بتایا گیا ہے اور یہی صحیح ہے۔ (۲)’’عین قرآن کے مطابق تھے۔‘‘ یعنی قرآن مجید میں جو اخلاق عالیہ فاضلہ تمام انبیاء و صلحا کے بیان کیے گئے ہیں، نبی صلی اللہ علیہ وسلم میں وہ سب بدرجۂ اتم پائے جاتے تھے اور جن چیزوں سے قرآن مجید میں روکا گیا ہے، ان کی گرد بھی آپ کو نہیں پہنچتی تھی۔ (۳)حضرت عائشہ رضی اللہ عنہا کے بیان کے مطابق ایک سال کے بعد نبی صلی اللہ علیہ وسلم سےبھی قیام اللیل کی فرضیت ساقط ہوگئی تھی، مگر قرآن مجید کے الفاظ میں دو امکان ہیں، ایک یہ کہ قیام اللیل صرف صحابہ سے ساقط کیا گیا تھا، آپ صلی اللہ علیہ وسلم پر بدستور فرض رہا لیکن یہ مؤقف درست نہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے بعض سفروں میں تہجد پڑھنا ثابت نہیں جیسا کہ ایک دفعہ سفر میں سیدنا بلال رضی اللہ عنہ بھی سوئے رہے اور رسول اللہ صلی اللہ علیہ وسلم بھی، کسی کو جاگ نہ آئی، تہجد بروقت پڑھنا تو کجا، نمازفجر بھی آپ صلی اللہ علیہ وسلم نے سورج چڑھے پڑھی، اسی طرح مزدلفہ کی رات بھی آپ صلی اللہ علیہ وسلم سے تہجد پڑھنا منقول نہیں۔ اس سے تہجد کی فرضیت کے قائلین کا مؤقف مل نظر ٹھہرتا ہے۔ دوسرے یہ کہ فرضیت نبی صلی اللہ علیہ وسلم سے بھی ساقط کردی گئی، جیسا کہ سیدہ عائشہ صدیقہ رضی اللہ عنہا کا بیان ہے۔ واللہ اعلم۔ (۴)قیام اللیل اور نماز وتر کوئی الگ الگ نمازیں نہیں بلکہ ایک ہی نماز کو وقت کی نسبت سے قیام اللیل کہا گیا اور رکعات کی تعداد کی نسبت سے وتر کہا گیا ہے۔ رمضان المبارک میں اسی کو تراویح اور عام دنوں میں اسی کو تہجد کہہ دیا جاتا ہے کیونکہ عام دنوں میں یہ نماز سونے کے بعد اٹھ کر پڑھی جاتی ہے اور تہجد کے معنی بھی نیند سے اٹھنا ہیں۔ تراویح اس کو پڑھنے کی کیفیت کے لحاظ سے کہا جاتا ہے، یعنی وقفے وقفے سے آرام کرکے پڑھنا۔ تراوی میں ہر چار رکعت کے بعد کافی وقفہ کیا جاتا ہے۔ اگرچہ آج کل یہ وقفہ تقریباً متروک ہوچکا ہے اور یہ ضروری بھی نہیں۔ (۵)رات کو جو نفل نماز بھی پڑھی جائے گی، اس کی تعداد طاق ہونی چاہیے، پھر ان سب کو وتر ہی کہا جائے گا، البتہ اگر دن کو قضا کرنی ہو تو طاق کے بجائے جفت پڑھی جائے گی کیونکہ طاق نفل نماز رات کے ساتھ خاص ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا دن کو گیارہ کے بجائے بارہ رکعت پڑھنا صریح دلیل ہے۔ یہ بھی معلوم ہوا کہ وتر نفل ہیں، فرض نہیں، نیز نفل کی بھی قضادی جاسکتی ہے۔ (۶)’’مجھے علم نہیں‘‘ مقصود یہ ہے کہ عبادت کے ساتھ ساتھ اپنے جسم اور اس کے آرام و صحت کا خیال رکھنا بھی ضروری ہے، ورنہ جسم عاجز آجائے گا، پھر نفل تو ایک طرف رہے فرض رہ جانے کی نوبت بھی آسکتی ہے۔ (۷)’’اگر میں ان کے پاس جاتا ہوتا‘‘ دراصل اس وقت غلط فہمی کی وجہ سے بعض صحابۂ کرام رضی اللہ عنہن میں سیاسی اختلافات پیدا ہوچکے تھے جس نے ان کو ایک دوسرے سے دور کردیا تھا۔ جنگ جمل اور جنگ صفین اسی دور کی تلخ یادیں ہیں۔ حضرت عائشہ، حضرت علی اور حضرت عبداللہ بن عباس رضی اللہ عنہم کے درمیان بھی ان اختلافات کی وجہ سے باہم شکر رنجی تھی، البتہ وہ سب نیک نیت تھے۔ رضوان اللہ علیہم اجمعین۔ (۸)سلف صالحین ہر کام میں اسوۂ رسول تلاش کرتے تھے کہ ان کی اقتدا کریں۔ اس مقصد کے لیے وہ وقت بھی دیتے تھے اور علماء سے استفسار بھی کرتے اور اگر سفر کی ضرورت پیش آتی تو سفر بھی کرتے۔ رحمہ اللہ۔ (۹)جس سے سوال پوچھا جارہا ہے اگر اس سے بڑا عالم موجود ہے تو اسے چاہیے کہ سائل کی اس کی طرف رہنمائی کرے کیونکہ دین خیرخواہی کا نام ہے۔ (۱۰)حضرت عائشہ رضی اللہ عنہا کی فضیلت ظاہر ہوتی ہے کہ وہ نبیٔ اکرم صلی اللہ علیہ وسلم کی عبادت کے بارے میں زیادہ جانتی تھیں۔ (۱۱)محبوب ترین عمل وہ ہے جس پر آدمی ہمیشگی کرے اگرچہ وہ کم ہی ہو۔ (۱۲)ساری ساری رات عبادت میں گزار دینا رسول اللہ صلی اللہ علیہ وسلم کا طریقہ نہیں بلکہ اپنی آنکھوں، جسم اور اہل عیال کا بھی انسان پر حق ہے، البتہ کبھی کبھار یہ جائز ہے۔"}],[1602,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص رمضان میں ایمان کی حالت میں ثواب کی نیت سے (رات کا) قیام کرے گا، تو اس کے گناہ جو پہلے ہو چکے ہوں بخش دیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جوشخص ایمان کی بنا پر ثواب کی نیت سے رمضان المبارک کی راتوں میں قیام کرے (نماز تراویح پڑھے) تو اس کے پہلے سب گناہ معاف کردیے جاتے ہیں۔"}],[1603,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص رمضان میں ایمان کی حالت میں ثواب کی نیت سے (رات کا) قیام کرے گا، تو اس کے اگلے گناہ بخش دیے جائیں گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص نے ایمان کے تقاضے سے اور صرف ثواب حاصل کرنے کے لیے رمضان المبارک کی راتوں کا قیام کیا، اس کے پہلے سب گناہ معاف کردیے جاتے ہیں۔‘‘","f2":"(۱)’’ایمان کی بناپر‘‘ مراد اللہ تعالیٰ پر ایمان ہے یا روزے کے مذکورہ ثواب پر ایمان ہے اگر ایمان کی بجائے رسم سمجھ کر مذکورہ نماز پڑھی تو اس پر ثواب کا وعدہ نہیں ہے۔ (۲)’’ثواب کی نیت سے‘‘ یعنی نیت ثواب حاصل کرنے کی ہو، ریاکاری، حصول تعریف یادنیوی مقصد (مثلاً صحت وغیرہ) پیش نظر نہ ہو۔ گویا ایمان روزے کی بنیاد ہو اور ثواب مقصد۔ (۳)’’پہلے سب گناہ‘‘ اس میں اللہ تعالیٰ کی بے پایاں رحمت و شفقت کا اظہار ہے۔ وہ معاف کرنے پر آئے تو صرف راستے سے ٹہنی ہٹانے والے اور کتے کو پانی پلانے والی بدکار عورت کو بھی معاف فرما دے۔ واللہ غفور رحیم۔"}],[1604,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک رات مسجد میں نماز پڑھی، آپ کی نماز کے ساتھ کچھ اور لوگوں نے بھی نماز پڑھی، پھر آپ نے آنے والی رات میں بھی نماز پڑھی اور لوگ بڑھ گئے تھے، پھر تیسری یا چوتھی رات میں لوگ جمع ہوئے تو رسول اللہ صلی اللہ علیہ وسلم ان کی طرف نکلے ہی نہیں، پھر جب صبح ہوئی تو آپ نے فرمایا: \"تم نے جو دلچسپی دکھائی اسے میں نے دیکھا، تو تمہاری طرف نکلنے سے مجھے صرف اس چیز نے روک دیا کہ میں ڈرا کہ کہیں وہ تمہارے اوپر فرض نہ کر دی جائے\"، یہ رمضان کا واقعہ تھا ۱؎۔\n§وضاحت\n۱؎: رسول اللہ صلی اللہ علیہ وسلم کی رحلت کے بعد یہ اندیشہ باقی نہیں رہا اس لیے تراویح کی نماز جماعت سے پڑھنے میں اب کوئی حرج نہیں، بلکہ یہ مشروع ہے، رہا یہ مسئلہ کہ رسول اللہ صلی اللہ علیہ وسلم نے ان تینوں راتوں میں تراویح کی کتنی رکعتیں پڑھیں، تو دیگر صحیح روایات سے ثابت ہے کہ آپ نے ان راتوں میں اور بقیہ قیام اللیل میں آٹھ رکعتیں پڑھیں اور وتر کی رکعتوں کو ملا کر اکثر گیارہ اور کبھی تیرہ رکعت تک پڑھنا ثابت ہے، یہی صحابہ سے اور خلفاء راشدین سے منقول ہے، اور ایک روایت میں ہے کہ آپ نے بیس رکعتیں پڑھیں لیکن یہ روایت منکر اور ضعیف ہے، لائق استناد نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک رات مسجد میں نماز (تراویح) پڑھی۔ کچھ لوگ بھی آپ کی اقتدا میں نماز پڑھنے لگے، پھر اگلی رات آپ نے (مسجد میں) نماز پڑھی تو لوگ پہلے سے زیادہ ہوگئے، پھر تیسری یا چوتھی رات تو سب لوگ ہی جمع ہوگئے لیکن رسول اللہ صلی اللہ علیہ وسلم تشریف نہ لائے۔ جب صبح ہوئی تو آپ نے فرمایا: ’’رات جو تم نے کیا میں دیکھ رہا تھا(یعنی تمھارا اجتماع اور ذوق و شوق) مگر مجھے آنے سے یہ چیز مانع تھی کہ مجھے خطرہ پیدا ہوا کہ کہیں یہ نماز تم پر فرض ہی نہ کردی جائے۔‘‘ اور یہ رمضان المبارک کی بات ہے۔","f2":"(۱)یہ روایت تفصیلاً پیچھے گزر چکی ہے۔ دیکھیے فوائدومسائل حدیث نمبر:۱۶۰۰ (۲)مذکورہ روایت میں یہ ہے کہ تیسری یا چوتھی رات آپ تشریف نہ لائے جبکہ ایک صحیح روایت میں صراحت ہے کہ تین راتیں لوگوں نے آپ کی اقتدا میں نماز تراویح پڑھی اور آپ نے انھیں تینوں راتیں آٹھ رکعت اور وتر پڑھائے تھے۔ چوتھی رات آپ تشریف نہ لائے۔ دیکھیے: (مسند ابی یعلی بتحقیق شیختا ارشاد الحق الاثر، برقم:۱۷۹۶، وقال الذھبی: اسنادہ وسط، و میزان الاعتدال:۳؍۲۱۱، وصحیح ابن خزیمہ، رقم:۱۰۷۰، وصحیح ابن حیان، رقم:۲۴۵۱ فی مواضع) (۳)معلوم ہوا کہ لوگوں کا ذوق شوق اور نفل کام پر اصرار بھی فرضیت کا ایک سبب ہے جس طرح اور بھی بہت سے اسباب ہیں۔ اگر اللہ تعالیٰ کا امر بھی ہوگیا تو وہ فرض ہوجائے گاورنہ باوجود مداومت اور اصرار کے نفل ہی رہے گا۔ ان الفاظ کا یہ مطلب نہیں کہ نفل پر مداومت نہیں کرنی چاہیے۔ خصوصاً اب جبکہ فرضیت کا امکان ہی نہیں تو کسی بھی نفل پر مداومت، اصرار اور پابندی میں کوئی حرج نہیں۔"}],[1605,"ابوذر رضی اللہ عنہ کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رمضان میں روزے رکھے، تو آپ ہمارے ساتھ (تراویح کے لیے) کھڑے نہیں ہوئے یہاں تک کہ مہینے کی سات راتیں باقی رہ گئیں، تو آپ نے ہمارے ساتھ قیام کیا یہاں تک کہ ایک تہائی رات گزر گئی، پھر چوبیسویں رات کو قیام نہیں کیا، پھر پچیسویں رات کو قیام کیا یہاں تک کہ آدھی رات گزر گئی، میں نے عرض کیا: اللہ کے رسول! کاش آپ ہماری اس رات کے باقی حصہ میں بھی اسی طرح نفلی نماز پڑھاتے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص امام کے ساتھ قیام کرے یہاں تک کہ وہ فارغ ہو جائے تو اللہ تعالی اس شخص کے حق میں پوری رات کے قیام(کا ثواب) لکھے گا\"، پھر آپ نے ہمیں نماز نہیں پڑھائی، اور نہ آپ نے قیام کیا یہاں تک کہ مہینے کی تین راتیں باقی رہ گئیں، تو آپ نے ستائیسویں رات میں ہمارے ساتھ قیام کیا، اور اپنے اہل و عیال کو بھی جمع کیا یہاں تک کہ ہمیں ڈر ہوا کہ کہیں ہم سے فلاح چھوٹ نہ جائے، میں نے پوچھا: فلاح کیا ہے؟ کہنے لگے: سحری ہے۔","الألباني: صحيح",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے کہ ہم نے رمضان المبارک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ روزے رکھے۔ آپ نے ہمیں رات کی نماز نہیں پڑھائی حتی کہ اس ماہ مبارک کے سات دن باقی رہ گئے۔ آپ نے ہمیں رات کی نماز (تراویح) پڑھائی حتی کہ رات کا تہائی حصہ گزر گیا، پھر اگلے دن ہمیں نماز نہیں پڑھائی، پھر پچیسویں رات ہمیں نماز پڑھائی حتی کہ نصف رات گزر گئی۔ میں نے کہا: اے اللہ کے رسول! کیا ہی خوب ہوتا اگر آپ باقی رات بھی نماز پڑھاتے۔ آپ نے فرمایا: ’’جس شخص نے امام کے ساتھ اس کے فارغ ہونے تک نماز پڑھی، اس کے لیے پوری رات کے قیام کا ثواب لکھا جاتا ہے (خواہ اس کے بعد وہ سو ہی جائے)۔‘‘ پھر آپ نے اگلی رات نماز نہیں پڑھائی حتی کہ اس ماہ مبارک کے تین دن باقی رہ گئے تو آپ نے ہمیں ستائیسویں رات نماز پڑھائی اور اپنے گھر والوں اور بیویوں کو بھی جمع فرمایا (اور اتنی لمبی نماز پڑھائی) حتی کہ ہمیں خطہ ہوا کہ ہم سے فلاح رہ جائے گی۔ (جبیر کہتے ہیں) میں نے (حضرت ابوذر سے) پچھا: فلاح سے کیا مراد ہے؟ انھوں نے فرمایا: سحری۔","f2":"(۱)ظاہر تو یہی ہے کہ یہ حدیث ماقبل حدیث ہی کی تفصیل ہے، لہٰذا رکعات تو تینوں راتوں میں گیارہ ہی تھیں مگر دوسری رات میں پہلی رات سے اور تیسری رات میں دوسری رات سے قراءت طویل کرکے رکعات کو لمبا کردیا گیا۔ (۲)’’امام کے ساتھ۔۔۔‘‘ معلوم ہوا امام کے ساتھ تراویح یا قیام اللیل کرنا اکیلے پڑھنے سے بہت افضل ہے۔ آپ کے دور میں مجبوری تھی۔"}],[1606,"نعیم بن زیاد ابوطلحہ کہتے ہیں کہ میں نے نعمان بشیر رضی اللہ عنہم کو حمص میں منبر پر بیان کرتے ہوئے سنا، وہ کہہ رہے تھے: ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رمضان کے مہینے میں تیئسویں رات کو تہائی رات تک قیام کیا، پھر پچسویں رات کو آدھی رات تک قیام کیا، پھر ستائیسویں رات کو ہم نے آپ کے ساتھ قیام کیا یہاں تک کہ ہم نے گمان کیا کہ ہم فلاح نہیں پا سکیں گے، وہ لوگ سحری کو فلاح کا نام دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت نعیم بن زیاد سے روایت ہے کہ میں نے حضرت نعمان بن بشیر رضی اللہ عنہما کو حمص (شہر) کے منبر پر فرماتے سنا کہ ہم نے رمضان المبارک کی تیئسویں رات میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تہائی رات تک قیام کیا، پھر پچیسویں رات میں آپ کے ساتھ نصف رات تک قیام کیا، پھر ستائیسویں رات آپ کے ساتھ اتنی دیر تک قیام کیا کہ ہم نے سمجھا: ہم فلاح (سحری) نہیں کھاسکیں گے۔"}],[1607,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی سو جاتا ہے تو شیطان اس کے سر پر تین گرہیں لگا دیتا ہے، اور ہر گرہ پر تھپکی دے کر کہتا ہے: ابھی رات بہت لمبی ہے، پس سوئے رہ، تو اگر وہ بیدار ہو جاتا ہے، اور اللہ کا ذکر کرتا ہے تو ایک گرہ کھل جاتی ہے، پھر اگر وہ وضو بھی کر لے تو دوسری گرہ کھل جاتی ہے، پھر اگر اس نے نماز پڑھی تو تمام گرہیں کھل جاتی ہیں، اور وہ اس حال میں صبح کرتا ہے کہ وہ ہشاس بشاس اور خوش دل ہوتا ہے، ورنہ اس کی صبح اس حال میں ہوتی ہے کہ وہ بد دل اور سست ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص سوتا ہے تو شیطان اس کے سر پر تین گرہیں لگا دیتا ہے۔ اور ہر گرہ دیتے وقت یہ پڑھتا ہے: لمبی رات ہے، سوجا، پھر اگر وہ جاگ کر اللہ کا ذکر کرے تو ایک گرہ کھل جاتی ہے اگر وہ وضو کرے تو دوسری گرہ بھی کھل جاتی ہے اور اگر وہ نماز شروع کردے تو تیسرے گرہ بھی کھل جاتی ہے اور وہ خوش دل اور چست و چالاک ہوجاتا ہے ورنہ بددل اور سست رہتا ہے۔‘‘","f2":"’’تین گرہیں‘‘ جب انسان سوتا ہے تو وہ اپنے جسم، طہارت اور اللہ تعالیٰ کی یاد سے غافل ہوجاتا ہے۔ شیطان کی کوشش یہ ہوتی ہے کہ انسان غافل ہی رہے اگر اسے جاگ آبھی جائے تو شیطان وساوس کے ذریعے سے اٹھنے نہیں دیتا بلکہ دوبارہ سلا دیتا ہے۔ اگر انسان اللہ کا نام لے کر (ہمت سے) اٹھ بیٹھے تو جسم میں غفلت نہ رہی، وضو کرے تو طہارت حاصل ہوگئی اور نماز شروع کردے تو ذکر الٰہی کے اعلیٰ درجے میں مشغول ہوگیا، لہٰذا ہر قسم کی غفلت دور ہوگئی اور وہ کامل انسان بن گیا۔ جسم میں چستی بھی آگئی اور روح میں تازگی بھی اور اگر وہ سویا رہے یا بستر میں کسمساتا رہے، اٹھنے کی ہمت نہ کرے تو جسم میں چستی آتی ہے نہ روح میں تازگی۔ اس بات کو رسول اللہ صلی اللہ علیہ وسلم نے شیطان کے گرہیں لگانے اور ان کے کھلنے سے تعبیر فرمایا ہے۔ قربان جائیں آپ کی فصاحت و بلاغت پر۔ کیا ہی خوب انداز اختیار فرمایا۔ بعض اہل علم نے اس کلام کو ظاہر معنی پر محمول کیا ہے کہ واقعتاً شیطان گرہیں لگاتا ہے اور ان پر پڑھ کر پھونکتا ہے،پھر یہ کھلتی بھی ہیں مگر یہ سب کچھ ہمیں نظر نہیں آتا۔ بعض اہل علم نے اسے استعارے اور تشبیہ سے تعبیر کیا ہے۔ بہرحال اگر شیطان حقیقتاً گرہیں لگائے او وہ کھلیں تو یہ محال بھی نہیں، اس لیے حق یہ ہے کہ کسی قسم کی تاویل کے بغیر حدیث شریف کے صریح الفاظ کے مفہوم ہی کو تسلیم کیا جائے، یہی ایمان بالغیب کا تقاضا اور سلف اہل علم کا شیوہ ہے۔ واللہ اعلم۔"}],[1608,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک آدمی کا ذکر کیا گیا جو رات بھر سوتا رہا یہاں تک کہ صبح ہو گئی، تو آپ نے فرمایا:\"یہ ایسا آدمی ہے جس کے کانوں میں شیطان نے پیشاب کر دیا ہے\" ۱؎۔\n§وضاحت\n۱؎: بعض لوگوں نے کہا کہ کان میں شیطان کا پیشاب کرنا حقیقت ہے گرچہ ہمیں اس کا ادراک نہیں ہوتا، اور بعضوں کے نزدیک یہ کنایہ ہے اس بات سے کہ جو شخص سویا رہتا ہے اور رات کو اٹھ کر نماز نہیں پڑھتا تو شیطان اس کے لیے اللہ کی یاد میں رکاوٹ بن جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک آدمی کا ذکر کیا گیا جو ساری رات سوتا رہا حتی کہ صبح ہوگئی۔ آپ نے فرمایا: ’’اس شخص کے کانوں میں شیطان نے پیشاب کردیا تھا۔‘‘","f2":"ظاہر الفاظ سے معلوم ہوتا ہے کہ وہ آدمی فرض نمازوں عشاء و فجر سے بھی سوتا رہا تھا۔ تبھی آپ نے ملامت فرمائی، ورنہ اگر وہ عشاء پڑھ کر سویا اور فجر اٹھ کر پڑھ لی تو مذمت کی کوئی وجہ نہیں مگر امام نسائی رحمہ اللہ اس روایت کو قیام اللیل کے تحت لائے ہیں گویا کہ وہ شخص قیام اللیل سے سویا رہا۔ واللہ اعلم۔"}],[1609,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے عرض کیا: اللہ کے رسول! فلاں شخص کل کی رات نماز سے سویا رہا یہاں تک کہ صبح ہو گئی، تو آپ نے فرمایا: \"اس کے کانوں میں شیطان نے پیشاب کر دیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہما سے روایت ہے، ایک آدمی نے کہا: اے اللہ کے رسول! فلاں شخص رات سے سویا رہا حتی کہ روشنی ہوگئی۔ آپ نے فرمایا: ’’اس کے کانوں میں شیطان نے پیشاب کردیا تھا۔‘‘"}],[1610,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ رحم کرے اس آدمی پر جو رات کو اٹھے اور نماز پڑھے، پھر اپنی بیوی کو بیدار کرے، تو وہ(بھی) نماز پڑھے، اگر نہ اٹھے تو اس کے چہرے پر پانی کے چھینٹے مارے، اور اللہ رحم کرے اس عورت پر جو رات کو اٹھے اور تہجد پڑھے، پھر اپنے شوہر کو (بھی) بیدار کرے، تو وہ بھی تہجد پڑھے، اور اگر وہ نہ اٹھے تو اس کے چہرے پر پانی کے چھینٹے مارے\" ۱؎۔\n§وضاحت\n۱؎: کیونکہ پانی کے چھینٹے مارنے سے وہ جاگ جائے گا، اور نماز پڑھے گا تو وہ بھی اس کی مستحق ہو گی۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ اس آدمی پر رحم فرمائے جو رات کو اٹھا اور اس نے نماز(تہجد) پڑھی، پھر اس نے اپنی بیوی کو جگایا، اس نے بھی نماز(تہجد) پڑھی اور اگر وہ (اٹھنے سے) انکار کرے تو اس کے چہرے پر پانی کے چھینٹے مارے۔ اسی طرح اللہ تعالیٰ رحم فرمائے اس عورت پر جو رات کو اٹھی اور نماز پڑھی، پھر اپنے خاوند کو جگایا اور اس نے بھی نماز پڑھی اور اگر اس نے انکار کیا تو اس کے چہرے پر پانی کے چھینٹے مارے۔‘‘","f2":"(۱)یہ ایک آدھ رات کی بات نہیں بلکہ عادت کی بات ہے کہ وہ ایسے کرتے ہیں۔ کیا ہی خوب ہیں یہ میاں بیوی! رسول اللہ صلی اللہ علیہ وسلم کے ان الفاظ میں ان کے لیے دعا بھی ہے، تعریف بھی اور ترغیب بھی، اور یہ حقیقت بھی کہ وہ اللہ کی رحمت کے مستحق ہیں۔ وفقنا اللہ ایاہ۔ (۲)جس طرح میّت کے لیے رحمت کی دعا کی جاتی ہے، اسی طرح زندہ کے لیے بھی دعائے رحمت کرنا جائز ہے۔"}],[1611,"علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے انہیں اور فاطمہ کو (دروازہ کھٹکھٹا کر) بیدار کیا، اور فرمایا: \"کیا تم نماز نہیں پڑھو گے؟\" تو میں نے عرض کیا: اللہ کے رسول! ہماری جانیں تو اللہ کے ہاتھ میں ہیں، جب وہ انہیں اٹھانا چاہے گا اٹھا دے گا، جب میں نے آپ سے یہ کہا تو آپ صلی اللہ علیہ وسلم پلٹ پڑے، پھر میں نے آپ کو سنا، آپ پیٹھ پھیر کر جا رہے تھے اور اپنی ران پر (ہاتھ) مار کر فرما رہے تھے: «وكان الإنسان أكثر شىء جدلا»\"انسان بہت حجتی ہے\"۔","الألباني: صحيح"],[1612,"علی بن ابی طالب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات میں میرے اور فاطمہ کے پاس آئے، اور آپ نے ہمیں نماز کے لیے بیدار کیا، پھر آپ اپنے گھر لوٹ گئے، اور جا کر دیر رات تک نماز پڑھتے رہے، جب آپ نے ہماری کوئی آہٹ نہیں سنی تو آپ دوبارہ ہمارے پاس آئے، اور ہمیں بیدار کیا، اور فرمایا:\"تم دونوں اٹھو، اور نماز پڑھو\"، تو میں اٹھ کر بیٹھ گیا، میں اپنی آنکھ مل رہا تھا اور کہہ رہا تھا: \"قسم اللہ کی، ہم اتنی ہی پڑھیں گے جو اللہ تعالی نے ہمارے لیے لکھ دی ہے، ہماری جانیں اللہ کے ہاتھ میں ہیں، اگر وہ ہمیں بیدار کرنا چاہے گا تو بیدار کر دے گا\" تو یہ سنا تو رسول اللہ صلی اللہ علیہ وسلم پیٹھ پھیر کر جانے لگے، آپ اپنے ہاتھ سے اپنی ران پر مار رہے تھے، اور کہہ رہے تھے: \"ہم اتنی ہی پڑھیں گے جو اللہ تعالی نے ہمارے لیے لکھ دی ہے، ۱؎ انسان بہت ہی حجتی ہے\"۔\n§وضاحت\n۱؎: یہ علی رضی اللہ عنہ کی بات تھی جسے آپ بطور تعجب دہرا رہے تھے۔","الألباني: صحيح"],[1613,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان کے مہینے کے بعد سب سے افضل روزے اللہ کے مہینے محرم کے روزے ہیں ۱؎، اور فرض نماز کے بعد سب سے افضل نماز قیام اللیل (تہجد) ہے\"۔\n§وضاحت\n۱؎: اللہ کی طرف اس مہینے کی نسبت شرف و فضل کی علامت کے طور پر ہے، جیسے بیت اللہ اور ناقۃ اللہ وغیرہ تراکیب ہیں، محرم حرمت والے چار مہینوں میں سے ایک ہے، اسی مہینے سے ہجری سن کا آغاز ہوتا ہے۔","الألباني: صحيح"],[1614,"حمید بن عبدالرحمٰن کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"فرض نماز کے بعد سب سے افضل نماز قیام اللیل (تہجد) ہے، اور رمضان کے بعد سب سے افضل روزے محرم کے روزے ہیں\"۔ شعبہ بن حجاج نے اسے مرسلاً روایت کیا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت حمید بن عبدالرحمن سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’فرض نماز کے بعد افضل نماز رات کی نماز (تہجد) ہے اور رمضان المبارک کے بعد افضل روزے محرم کے ہیں۔‘‘\nشعبہ بن حجاج نے اس روایت کو مرسل بیان کیا ہے۔","f2":"حدیث نمبر:۱۶۱۴ اور ۱۶۱۵ایک ہی ہیں۔ فرق صر ف یہ ہے کہ حدیث نمبر ۱۶۱۴ میں سند متصل ہے جبکہ حدیث نمبر ۱۶۱۵ میں صحابی (حضرت ابوہریرہ رضی اللہ عنہ) کا ذکر نہیں ہے۔ اصولِ حدیث میں ایسی روایت کو مرسل کہتے ہیں۔ اس حدیث کے راوی حضرت شعبہ بن حجاج ہیں۔"}],[1615,"ابوذر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تین شخص سے اللہ تعالی محبت رکھتا ہے: ایک وہ شخص جو کسی قوم کے پاس آیا، اور اس نے ان سے اللہ کا واسطہ دے کر مانگا، آپ سی قرابت کا واسطہ دے کر نہیں مانگا، تو انہوں نے اسے نہیں دیا، پھر انہی میں سے ایک آدمی ان کے پیچھے سے آیا، اور چھپا کر چپکے سے اسے دیا، اور اس کے اس صدقہ دینے کو سوائے اللہ تعالی کے اور اس شخص کے جس کو اس نے دیا ہے کوئی نہیں جانتا، اور دوسرا آدمی وہ ہے جس کے ساتھ کے لوگ رات بھر چلتے رہے یہاں تک کہ جب نیند انہیں بھلی معلوم ہونے لگی تو وہ اترے اور سو رہے، لیکن وہ خود کھڑا ہو کر اللہ کے سامنے عاجزی کرتا رہا، اور اس کی آیتیں تلاوت کرتا رہا، اور تیسرا وہ شخص ہے جو ایک لشکر میں تھا، دشمن سے ان کی مڈبھیڑ ہوئی، تو وہ ہار گئے (جس کی وجہ سے بھاگنے لگے) لیکن وہ سینہ سپر رہا یہاں تک کہ وہ مارا جائے، یا اللہ اسے فتح دے\"۔","الألباني: ضعيف",{"u2":"حضرت ابوذر رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تین (قسم کے) آدمی وہ ہیں جن سے اللہ تعالیٰ کو محبت ہے: ایک وہ آدمی جو کسی قوم کے پاس آیا اور ان سے اللہ تعالیٰ کے نام پر سوال کیا۔ اپنی کسی رشتے داری کی بنا پر سوال نہیں کیا لیکن کسی نے اسے کچھ نہ دیا مگر ایک آدمی ان سب لوگوں کو پیچھے چھوڑ کر آگے چلا گیا اور اس (سائل) کو پوشیدہ طور پر مال دیا۔ اس کے اس عطیے کا کسی کو علم نہ ہوا، سوائے اللہ تعالیٰ کے اور اس شخص کے جس کو اس نے دیا۔ اورایک وہ شخص کہ کچھ لوگ ساری رات چلتے رہے حتی کہ جب نیند ان کو ہر چیز سے زیادہ پیاری لگنے لگی تو وہ اترے اور سوگئے مگر وہ شخص کھڑاہوکر میرے سامنے گڑگڑانے لگا اور (نماز میں) میری آیات پڑھنے لگا اور ایک وہ شخص جو ایک لشکر میں شامل تھا۔ اس لشکر کا دشمن سے مقابلہ ہوا۔ سب شکست کھاگئے مگر وہ سینہ تان کر آگے بڑھا حتی کہ وہ مارا گیا یا اسے فتح مل گئی۔‘‘","f2":"(۱)تین آدمی، یعنی تین قسم کے آدمی، خواہ وہ ہزاروں لاکھوں ہوں۔ (۲)’’پہلا وہ آدمی‘‘ یعنی عطیہ دینے والا، نہ کہ مانگنے والا۔ (۳)مخفی صدقہ کرنے کی فضیلت معلوم ہوئی۔ (۴)اللہ تعالیٰ کی صفت محبت ثابت ہوئی، جیسے اس کی شان کے لائق ہے۔"}],[1616,"مسروق کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم کو سب سے زیادہ محبوب کون سا عمل تھا؟ تو انہوں نے کہا: جس عمل پر مداومت ہو، میں نے پوچھا: رات میں آپ کب اٹھتے تھے؟ تو انہوں نے کہا: جب مرغ کی بانگ سنتے ۱؎۔\n§وضاحت\n۱؎: یہ عام معمول کی بات ہو گی، ورنہ خود عائشہ رضی اللہ عنہا سے مروی ہے کہ آپ رات کے ہر حصے میں سوتے یا نماز پڑھتے پائے گئے۔","الألباني: صحيح",{"u2":"حضرت مسروق سے روایت ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم کو کون سا عمل زیادہ پسند تھا؟ انھوں نے فرمایا: جو ہمیشہ کیا جائے (خواہ کم ہی ہو) میں نے کہا: آپ رات کو کس وقت تہجد کے لیے اٹھتے تھے؟ انھوں نے فرمایا: جب مرغ کی (پہلی) آواز سنتے۔","f2":"(۱)مرغ عموماً آدھی رات کے بعد آواز نکالتا ہے۔ بعض دوسری روایات میں ہے کہ نبی صلی اللہ علیہ وسلم نصف رات تک سوتے، پھر تہائی رات جاگتے (نمازپڑھتے) اور، پھر آخری سدس (چھٹا حصہ) سوتے۔ دیکھیے: (صحیح البخاری، التھجد، حدیث:۱۱۳۱، وصحیح مسلم، الصیام، حدیث:۱۱۵۹) یہ تقسیم عشاء کے بعد سے فجر کی اذان تک کی ہے کیونکہ مسلمانوں کی یہی رات ہے۔ باقی تو جاگنے، یعنی نمازوں کے اوقات ہیں۔ (۲)چونکہ مرغ کی آواز سن کر نیک لوگ نماز کے لیے جاگتے ہیں، لہٰذا اس کی آواز کو لوگ اذان کہہ دیتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے بھی فرمایا: مرغ فرشتے دیکھ کر آواز نکالتا ہے، لہٰذا تم مرغ کی آواز سن کر یہ کہا کرو: (اللھم انی اسئلک من فضلک) صحیح البخاری، بدءالخلق، حدیث:۳۳۰۳ و صحیح مسلم، الذکر والدعاء، حدیث:۲۷۲۹) واہ رے مرغ تیری قسمت! نفلی عبادت میں میانہ روی اختیار کرنی چاہیے، تعمق سے کام نہیں لینا چاہیے۔ ورنہ آدمی اکتا جاتا ہے اور اس عمل کو جاری نہیں رکھ سکتا۔"}],[1617,"عاصم بن حمید کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم رات کے قیام کی شروعات کس سے کرتے تھے؟ تو وہ کہنے لگیں، تو نے مجھ سے ایک ایسی چیز پوچھی ہے جو تم سے پہلے کسی نے نہیں پوچھی، رسول اللہ صلی اللہ علیہ وسلم دس بار «اللہ اکبر»، دس بار «الحمد للہ»، دس بار «سبحان اللہ» اور دس بار «لا الٰہ الا اللہ» اور دس بار «استغفر اللہ» کہتے تھے، اور «اللہم اغفر لي واهدني وارزقني وعافني أعوذ باللہ من ضيق المقام يوم القيامة» \"اے اللہ! مجھے بخش دے، مجھے راہ دکھا، مجھے رزق عطا فرما، اور میری حفاظت فرما، میں اللہ کی پناہ چاہتا ہوں قیامت کے روز جگہ کی تنگی سے\" کہتے تھے۔","الألباني: حسن صحيح",{"u2":"حضرت عاصم بن حمید بیان کرتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: نبی صلی اللہ علیہ وسلم کن الفاظ سے قیام اللیل کا افتتاح کیا کرتے تھے؟ انھوں نے فرمایا: تم نے مجھ سے وہ چیز پوچھی ہے جو تم سے پہلے کسی نے نہیں پوچھی۔ رسول اللہ صلی اللہ علیہ وسلم دس دفعہ اللہ اکبر، دس دفعہ الحمدللہ، دس دفعہ سبحان اللہ، دس دفعہ (لاالٰہ الااللہ) اور دس دفعہ استغفراللہ کہتے تھے، پھر فرماتے: ’’اے اللہ! مجھے معاف فرما، مجھے ہدایت دے، مجھے رزق عطا فرما اور مجھے عافیت وصحت دے۔ اور میں قیامت کے دن اللہ تعالیٰ کے سامنے کھڑا ہونے کی تنگی سے اللہ تعالیٰ کی پناہ چاہتا ہوں۔‘‘","f2":"قیام اللیل کے آغاز سے مراد یہ ہے کہ جب نبی صلی اللہ علیہ وسلم تہجد کے لیے اٹھتے تو نماز تہجد سے پہلے یہ دعائیں پڑھا کرتے تھے۔ ان (گزشتہ اور آئندہ) دعاؤں میں بہت سی ایسی دعائیں ہیں جن کو ظاہر آپ کو ضروری نہیں مگر آپ نے اپنی امت کی تعلیم کے لیے وہ دعائیں پڑھیں کیونکہ امتیوں کو تو بہرصورت ان کی ضرورت ہے۔ کہا جاسکتا ہے کہ آپ کی دعائیں دراصل آپ کی امت کے لیے ہیں۔ (علاوہ ان دعاؤں کے جو آپ کے ساتھ مخصوص ہیں۔)"}],[1618,"ربیعہ بن کعب الاسلمی رضی اللہ عنہ کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے کمرے کے پاس رات گزارتا تھا، تو میں آپ کو سنتا جب آپ رات میں اٹھتے، تو دیر تک «سبحان اللہ رب العالمين» کہتے، پھر «سبحان اللہ وبحمده» دیر تک کہتے۔","الألباني: صحيح",{"u2":"حضرت ربیعہ بن کعب اسلمی رضی اللہ عنہ سے روایت ہے، وہ بیان کرتے ہیں کہ میں نبی صلی اللہ علیہ وسلم کے حجرے کے قریب سوتا تھا۔ جب آپ رات کو (تہجد کے لیے) اٹھتے تو میں سنتا کہ آپ دیر تک (سبحان اللہ رب العالمین) ’’پاک ہے اللہ جو جہانوں کا رب ہے‘‘ پڑھتے رہتے، پھر دیر تک (سبحان اللہ وبحمدہ) ’’اللہ تعالیٰ تمام عیوب و نقائص سے پاک ہے اور تمام تعریفوں والا ہے۔‘‘ پڑھتے۔"}],[1619,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب رات کو تہجد پڑھنے کے لیے اٹھتے تو کہتے: «اللہم لك الحمد أنت نور السموات والأرض ومن فيهن ولك الحمد أنت قيام السموات والأرض ومن فيهن ولك الحمد أنت ملك السموات والأرض ومن فيهن ولك الحمد أنت حق ووعدك حق والجنة حق والنار حق والساعة حق والنبيون حق ومحمد حق لك أسلمت وعليك توكلت وبك آمنت» \"اے اللہ! تیرے ہی لیے تمام تعریفیں ہیں، تو آسمانوں اور زمین کا اور جو ان میں ہیں سب کا روشن کرنے والا ہے، تیرے ہی لیے تمام تعریفیں ہیں، تو آسمانوں اور زمین کا اور جو ان میں ہیں سب کا قائم و برقرار رکھنے والا ہے، تیرے ہی لیے تمام تعریفیں ہیں، تو آسمانوں اور زمین اور جوان میں ہیں سب کا بادشاہ ہے، تیرے ہی لیے تمام تعریفیں ہیں، تو حق ہے، تیرا وعدہ حق ہے، جنت حق ہے، جہنم حق ہے، قیامت حق ہے، انبیاء حق ہیں، اور محمد حق ہیں، میں نے تیری ہی فرمانبرداری کی، اور تجھی پر میں نے بھروسہ کیا، اور تجھی پر ایمان لایا\"، پھر قتیبہ نے ایک بات ذکر کی اس کا مفہوم ہے (کہ آپ یہ بھی کہتے:) «وبك خاصمت وإليك حاكمت اغفر لي ما قدمت وما أخرت وما أعلنت أنت المقدم وأنت المؤخر لا إله إلا أنت ولا حول ولا قوة إلا باللہ»\"اور تیرے ہی لیے میں نے جھگڑا کیا، تیری ہی طرف میں فیصلہ کے لیے آیا، بخش دے میرے اگلے پچھلے، چھپے اور کھلے گناہ، تو ہی آگے اور پیچھے کرنے والا ہے، نہیں ہے کوئی حقیقی معبود مگر تو ہی، اور نہ ہی کسی میں زور و طاقت ہے سوائے اللہ کے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب رات کو تہجد کے لیے اٹھتے تو یہ دعا پڑھتے: (اللھم لک الحمد۔۔۔ولاقوۃ الا باللہ) ’’اے اللہ! تیرے ہی لیے سب تعریف ہے۔ تو آسمانوں اور زمینوں کا نور ہے۔ اور ان لوگوں کا نور ہے جو ان میں ہیں، اور تیرے ہی لیے سب تعریف ہے۔ تو آسمانوں وزمین اور ان کے مابین تمام لوگوں کو قائم رکھنے والا ہے۔ اور تیرے یہ لیے سب تعریف ہے۔ تو آسمانوں، زمینوں اور ان میں رہنے والوں کا بادشاہ ہے اور تیرے ہی لیے سب تعریف ہے۔ تو برحق ہے۔ تیرے وعدے برحق ہیں۔ جنت حق ہے اور جہنم حق ہے، اور قیامت حق ہے، اور تمام نبی حق ہیں اور محمد(صلی اللہ علیہ وسلم) بھی حق ہیں۔ میں تیرا ہی مطیع و فرماں بردار ہوا اور تجھی پر میں نے بھروسا کیا اور تجھی پر میں ایمان لایا اور تیری ہی مدد سے میں (کفار سے) جھگڑتا ہوں اور تیرے حضور ہی فیصلہ پیش کرتا ہوں۔ مجھے معاف فرما، وہ گناہ جو میں نے کرلیے ہیں اور جو ابھی نہیں کیے اور جو میں نے خفیہ کیے ہیں اور جو علانیہ کیے ہیں۔ تو ہی کسی کو آگے کرنے والا ہے اور تو ہی پیچھے کرنے والا ہے۔ تیرے سوا کوئی معبود نہیں اور اللہ تعالیٰ کی مدد کے بغیر نہ نقصان سے بچنے کا حیلہ ہے اور نہ فائدہ حاصل کرنے کی طاقت۔‘‘","f2":"(۱)’’نور ہے‘‘ یعنی آسمانوں اور زمینوں میں نور پیدا کرنے والا ہے۔ یا تو بے عیب ہے یا تو آسمانوں اور زمینوں کی زینت ہے۔ (۲)’’تو برحق ہے‘‘ یعنی صرف تیرا وجود حقیقی ہے، باقی تو کالعدم (بت) ہیں یا تیرا وجود اور توحیدحقیقت ہے۔ (۳)’’جو ابھی نہیں کیے‘‘ مگر بعد میں ہوں گے،بعد میں ہونے والے گناہوں کی معافی مانگنے میں کوئی استحالہ نہیں کیونکہ ان کا ہونا طبعی بات ہے۔ (۴)’’نہ فائدہ حاصل کرنے کی طاقت‘‘ اس میں ہر نقصان اور فائدہ داخل ہے، مثلاً: گناہ، نیکی اور دیگر دنیوی و اخروی نقصانات و فوائد۔ (۵)’’آگے پیچھے کرنے والا‘‘ یعنی مرتبہ اور شان بڑھانے اور گھٹانے والا ہے یا موت و حیات کے لحاظ سے یا عزت و ذلت کے لحاظ سے یا ہدایت اور گمراہی کے لحاظ سے۔ یہ معنی بھی کیے گئے ہیں کہ تو سب سے اول اور سب سے آخر ہے۔ (۶)اللہ تعالیٰ کی صفات کے بارے میں یہ حدیث انتہائی جامع ہے کہ اللہ تعالیٰ کا کوئی وصف بھی ان اوصاف سے خارج نہیں۔"}],[1620,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ انہوں نے ام المؤمنین میمونہ رضی اللہ عنہا کے پاس رات گزاری (وہ ان کی خالہ تھیں) تو وہ تکیہ کے چوڑان میں لیٹے اور رسول اللہ صلی اللہ علیہ وسلم اور آپ کی اہلیہ دونوں اس کی لمبان میں، رسول اللہ صلی اللہ علیہ وسلم سوئے رہے یہاں تک کہ جب آدھی رات ہوئی، یا اس سے کچھ پہلے، یا اس کے کچھ بعد تو رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے، چہرہ سے نیند بھگانے کے لیے اپنے ہاتھ سے آنکھ ملتے ہوئے اٹھ کر بیٹھ گئے، پھر آپ نے سورۃ \"آل عمران\" کی آخری دس آیتیں پڑھیں، پھر آپ ایک لٹکے ہوئے مشکیزے کی طرف بڑھے، اور اس سے وضو کیا تو خوب اچھی طرح سے وضو کیا، پھر آپ نماز پڑھنے کے لیے کھڑے ہوئے۔ عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں: میں بھی اٹھا، اور میں نے بھی ویسے ہی کیا جیسے آپ نے کیا، پھر میں گیا، اور آپ کے پہلو میں جا کر کھڑا ہو گیا تو آپ صلی اللہ علیہ وسلم نے اپنا دایاں ہاتھ میرے سر پر رکھا اور میرا داہنا کان پکڑ کر اسے ملنے لگے، آپ نے دو رکعتیں پڑھیں، پھر دو رکعتیں، پھر دو رکعتیں، پھر دو رکعتیں، پھر دو رکعتیں، پھر دو رکعتیں، پھر آپ نے وتر پڑھی ۱؎ پھر آپ لیٹے یہاں تک کہ آپ کے پاس مؤذن آیا تو آپ نے پھر ہلکی دو رکعتیں پڑھیں۔\n§وضاحت\n۱؎: یعنی ایک رکعت وتر پڑھی، اگر تین رکعتیں پڑھی ہوتیں تو پھر یہ کل پندرہ رکعتیں ہو جائیں گی، اور آپ کی تہجد کی نماز کے سلسلے میں یہ کسی کے نزدیک ثابت نہیں ہے، صحیح بخاری کی ایک روایت میں \"تیرہ رکعتوں\" کی صراحت موجود ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما نے بتایا کہ ایک رات میں ام المومنین حضرت میمونہ رضی اللہ عنہا کے ہاں سویا جو میری خالہ تھیں۔ میں بستر کے عرض میں لیٹ گیا جبکہ رسول اللہ صلی اللہ علیہ وسلم اور آپ کی زوجۂ محترمہ بستر کے ملول میں لیٹ گئے۔ رسول اللہ صلی اللہ علیہ وسلم سوگئے حتی کہ جب رات نصف ہوگئی یا معمولی کم و بیش، تو رسول اللہ صلی اللہ علیہ وسلم جاگ اٹھے۔ آپ اپنے ہاتھوں سے اپنا چہرہ ملتے ہوئے اٹھ بیٹھے، پھر آپ نے سورۂ آل عمران کی آخری دس آیات تلاوت فرمائیں، پھر ایک لٹکے ہوئے مشکیزے کی طرف اٹھے اور اس سے وضو فرمایا اور بہترین وضو فرمایا، پھر نماز پڑھنے لگے۔ حضرت عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں بھی اٹھا اور میں نے اسی طرح کیا جس طرح آپ نے کیا تھا، پھر میں گیا اور آپ کے پہلو میں کھڑا ہوگیا۔ رسول اللہ صلی اللہ علیہ وسلم نے اپنا دایاں ہاتھ میرے سر پر رکھا اور میرا دایاں کان پکڑ کر مروڑا۔ آپ نے دو رکعتیں پڑھیں، پھر دو، پھر دو، پھر دو، پھر دو، پھردو، پھر ایک رکعت پڑھی، پھر لیٹ گئے حتی کہ مؤذن آپ کو جماعت کی اطلاع دینے آیا تو آپ نے دوہلکی رکعتیں پڑھیں۔","f2":"(۱)حضرت ابن عباس رضی اللہ عنہما نے حضرت میمونہ رضی اللہ عنہا کے توسط سے رسول اللہ صلی اللہ علیہ وسلم سے باقاعدہ رات گزارنے کی اجازت لی تھی۔ حضرت میمونہ رضی اللہ عنہما ان دنوں حیض کی حالت میں تھیں۔ حضرت ابن عباس رضی اللہ عنہما کا مقصد رسول اللہ صلی اللہ علیہ وسلم کی تہجد کی کیفیت کو جاننا تھا۔ (۲)’’کان مروڑا‘‘ حضرت ابن عباس رضی اللہ عنہما رسول اللہ صلی اللہ علیہ وسلم کی بائیں جانب کھڑے ہوگئے تھے۔ ان کو اپنی دائیں جانب کھڑا کرنے کے لیے ان کے کان سے پکڑ کر اپنی دائیں جانب کھڑا کیا۔ (۳) آپ کبھی کبھار تیرہ رکعت بھی پڑھ لیتے تھے اگرچہ اکثر معمول گیارہ کا تھا۔ بعض نے پہلی دو رکعتوں کو تحیۃ الوضوع یا افتتاح تہجد سمجھا ہے۔ گویا اصل تہجد گیارہ رکعت ہی تھیں۔ (۴)’’دوہلکی رکعتیں‘‘ مراد فجر کی سنتیں ہیں۔ (۵)اہل خانہ سے معاشرت اور چھوٹے بچوں پر شفقت اور نرمی سے پیش آنا چاہیے۔ (۶)چھوٹے بچے کی نماز صحیح ہے۔ (۷) وضو اچھے طریقے سے کرنا چاہیے لیکن کوشش کرنی چاہیے کہ پانی کم سے کم استعمال ہو۔ (۸)ایک باقاعدہ مؤذن مسجد میں مقرر کرنا چاہیے۔ (۹)نفلی نماز کی جماعت مشروع ہے۔ (۱۰)جس آدمی نے شروع نماز میں امامت کی نیت نہ کی ہو اس کی اقتدا میں بھی نماز پڑھنا جائز ہے۔\nباب۱۰:جب رات کو تہجد کے لیے اٹھے تو مسواک کرے"}],[1621,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب رات میں اٹھتے تو مسواک سے اپنا منہ ملتے تھے۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب رات کواٹھتے تھے تو اپنے منہ کو مسواک کے ساتھ صاف کرتے تھے۔\nحضرت حذیفہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم جب رات کواٹھتے تھے تو اپنے منہ کو مسواک کے ساتھ صاف کرتے تھے۔"}],[1622,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب رات میں اٹھتے تو مسواک سے اپنا منہ ملتے تھے۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو تہجد پڑھنے اٹھتے تو اپنے دہن مبارک کو مسواک کے ساتھ صاف فرماتے۔"}],[1623,"ابوسنان ابوحصین سے وہ ابووائل شقیق بن سلمہ سے روایت کرتے ہیں کہ حذیفہ رضی اللہ عنہ نے کہا: جب ہم رات میں بیدار ہوتے تو ہمیں مسواک کرنے کا حکم دیا جاتا تھا۔\n§وضاحت\n۱؎: اس میں اختلاف ہے کہ اوروں نے اس کو نبی اکرم صلی اللہ علیہ وسلم کے عمل کے طور پر روایت کیا ہے، جب کہ ابوحصین عثمان نے اس کو اس سند سے جو حکماً مرفوع ہے قول رسول کے طور پر روایت کیا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں حکم دیا جاتا تھا کہ جب ہم رات کو اٹھیں تو مسواک کریں۔"}],[1624,"اسرائیل ابوحصین سے روایت کرتے ہیں کہ ابووائل شقیق نے کہا: جب ہم رات کو بیدار ہوتے تھے تو ہمیں مسواک سے اپنا منہ ملنے کا حکم دیا جاتا تھا۔","الألباني: صحيح الإسناد",{"u2":"حضرت شقیق بیان کرتے ہیں کہ ہمیں حکم دیا جاتا تھا کہ جب ہم رات کو اٹھیں تو اپنے منہ مسواک سے صاف کریں۔","f2":"امام صاحب رحمہ اللہ کا مقصد یہ بتانا ہے کہ مسواک کرنا نبی صلی اللہ علیہ وسلم کا فعل بھی ہے اور حکم بھی، پھر یہ روایت مرفوع بھی ہے، موقوف اور مقطوع بھی۔"}],[1625,"ابوسلمہ بن عبدالرحمٰن کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا کہ نبی اکرم صلی اللہ علیہ وسلم اپنی نماز کی شروعات کس چیز سے کرتے تھے؟ تو انہوں نے کہا: آپ جب رات میں اٹھ کر اپنی نماز شروع کرتے تو کہتے: «اللہم رب جبريل وميكائيل وإسرافيل فاطر السموات والأرض عالم الغيب والشهادة أنت تحكم بين عبادك فيما كانوا فيه يختلفون اللہم اهدني لما اختلف فيه من الحق إنك تهدي من تشاء إلى صراط مستقيم» \"اے اللہ! اے جبرائیل و میکائیل و اسرافیل کے رب، آسمانوں اور زمین کے پیدا کرنے والے، غائب اور حاضر کے جاننے والے! تو ہی اپنے بندوں کے درمیان فیصلہ کرے گا جس میں وہ جھگڑتے تھے، اے اللہ! جس میں اختلاف کیا گیا ہے اس میں تو میری رہنمائی فرما، تو جس کی چاہتا ہے سیدھی راہ کی طرف رہنمائی فرماتا ہے\"۔","الألباني: حسن",{"u2":"حضرت ابوسلمہ بن عبدالرحمن رضی اللہ عنہ بیان کرتے ہیں کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا کہ نبی صلی اللہ علیہ وسلم کس دعا سے اپنی نماز (تہجد) شروع فرماتے تھے؟ انھوں نے فرمایا: آپ جب رات کو نماز کے لیے اٹھتے تو یہ دعا پڑھتے: (اللھم رب جبریل۔۔۔ الی صراط مستقیم) ’’اے اللہ! جبرائیل،میکائیل اور اسرافیل ے رب! آسمانوں اور زمینوں کو پیدا کرنے والے! ہر غیب و حاضر کو جاننے والے! تو اپنے بندوں میں ان چیزوں کا فیصلہ کرے گا جن میں وہ اختلاف کرتے ہیں۔ اے اللہ! مجھے اس حق کی طرف راہنمائی فرما جس میں اختلاف کیا گیا ہے۔ یقیناً تو جس کو چاہتا ہے سیدھے راستے پر چلا دیتا ہے۔‘‘"}],[1626,"حمید بن عبدالرحمٰن بن عوف سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم کے اصحاب میں سے ایک شخص کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک سفر میں تھا، میں نے اپنے جی میں کہا کہ اللہ کی قسم! میں نماز کے لیے رسول اللہ صلی اللہ علیہ وسلم کا انتظار کروں گا یہاں تک کہ آپ کے عمل کو دیکھ لوں، تو جب آپ نے عشاء کی نماز پڑھی، اور یہی عتمہ تھی، تو بڑی رات تک سوئے رہے، پھر آپ بیدار ہوئے توافق کی جانب نگاہ اٹھائی، اور فرمایا: «ربنا ما خلقت هذا باطلا» \"اے ہمارے رب! تو نے اسے بیکار پیدا نہیں کیا ہے\" (آل عمران: ۱۹۱) یہاں تک کہ آپ «إنك لا تخلف الميعاد» \"بلاشبہ تو وعدہ خلافی نہیں کرتا\" (آل عمران: ۱۹۴) تک پہنچے، پھر آپ اپنے بچھونے کی طرف جھکے، اور آپ نے اس میں سے ایک مسواک نکالی، پھر ڈول سے جو آپ کے پاس تھا ایک پیالے میں پانی انڈیلا، اور مسواک کی، پھر آپ کھڑے ہوئے، اور نماز پڑھی یہاں تک کہ میں نے (اپنے دل میں) کہا: آپ جتنی دیر تک سوئے تھے اتنی ہی دیر تک آپ نے نماز پڑھی ہے، پھر آپ لیٹ گئے یہاں تک کہ میں نے (اپنے دل میں) کہا: آپ اتنی ہی دیر تک سوئے ہیں جتنی دیر تک آپ نے نماز پڑھی تھی، پھر آپ بیدار ہوئے تو آپ نے اسی طرح کیا جس طرح آپ نے پہلی مرتبہ کیا تھا، اور اسی طرح کہا جس طرح پہلے کہا تھا، تو رسول اللہ صلی اللہ علیہ وسلم نے فجر سے پہلے تین مرتبہ (اسی طرح) کیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت حمید بن عبدالرحمن بن عوف سے روایت ہے کہ اصحاب نبی صلی اللہ علیہ وسلم میں سے ایک صحابی نے کہا: میں ایک سفر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ تھا۔ میں نے (دل میں) کہا: اللہ کی قسم! میں (رات کی) نماز کے وقت بغور رسول اللہ صلی اللہ علیہ وسلم کو دیکھوں گا تاکہ مجھے پتا چلے کہ آپ کیا کرتے ہیں۔ جب آپ نے عشاء کی نماز پڑھ لی تو آپ کافی رات تک لیٹے رہے، پھر آپ جاگے اور افق میں دیکھا، پھر آپ نے یہ آیت پڑھی: (ربنا ما خلقت ھذا باطلا) حتی کہ آپ نے (انک لا تخلف المیعاد) تک پڑھا، پھر رسول اللہ صلی اللہ علیہ وسلم اپنے بستر کی طرف جھکے اور اس میں سے مسواک نکالی، پھر آپ نے اپنے پاس پڑے ہوئے چمڑے کے برتن سے ایک پیالے میں کچھ پانی ڈالا اور مسواک فرمائی۔ (اور وضو کیا۔) پھر آپ نے نماز شروع فرمائی۔ میرا خیال ہے آپ جتنی دیر سوئے تھے، اتنی دیر آپ نے نماز پڑھی، پھر آپ لیٹ گئے حتی کہ میرا خیال ہے کہ آپ اتنی دیر سوئے جتنی دیر نماز پڑھی تھی، پھر جاگے اور اسی طرح کیا جس طرح پہلے کیا تھا۔ اور وہی کچھ پڑھا جو پہلی دفعہ پڑھا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے فجر سے پہلے تین بار ایسے کیا۔","f2":"(۱)اس طرز کا باب پہلے بھی گزر چکا ہے۔ وہاں بھی کچھ دعائیں بیان ہوئی ہیں۔ کوئی بھی دعا لی جائے، کافی و وافی ہے۔ (۲)صحابۂ کرام رضی اللہ عنہم عبادات میں اور غیرعبادات میں بھی نبی صلی اللہ علیہ وسلم کے افعال کی پیروی میں بہت حریص تھے۔"}],[1627,"انس رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کو رات میں نماز (تہجد) پڑھتے ہوئے دیکھنا چاہتے تو دیکھ لیتے، اور آپ کو سوتے ہوئے دیکھنا چاہتے تو دیکھ لیتے تھے ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ آپ رات میں سوتے بھی تھے، اور نماز بھی پڑھتے تھے، نہ ساری رات جاگتے ہی تھے، اور نہ ساری رات سوتے ہی تھے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ اگر ہم چاہتے کہ رسول اللہ صلی اللہ علیہ وسلم کو رات میں نماز پڑھتے ہوئے دیکھ لیتے۔ اور اگر ہم چاہتے کہ رسول اللہ صلی اللہ علیہ وسلم کو سویا ہوا دیکھیں تو یہ بھی دیکھ لیتے۔"}],[1628,"یعلی بن مملک سے روایت ہے کہ انہوں نے ام المؤمنین ام سلمہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں سوال کیا، تو انہوں نے کہا: آپ عتمہ (عشاء کی نماز) پڑھتے تھے پھر سنتیں پڑھتے، پھر اس کے بعد رات میں جتنا اللہ چاہتا پڑھتے، پھر آپ واپس جا کر جتنی دیر تک آپ نے نماز پڑھی تھی اسی کے بقدر سوتے، پھر آپ اپنی اس نیند سے بیدار ہوتے تو جتنی دیر تک سوئے تھے اسی کے بقدر نماز پڑھتے، اور آپ کی یہ دوسری مرتبہ والی نماز صبح (فجر) تک جاری رہتی۔","الألباني: ضعيف",{"u2":"ابن ابی ملیکہ بیان کرتے ہیں کہ حضرت یعلی بن مملک نے ام المومنین ام سلمہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے متعلق دریافت کیا تو انہوں نے فرمایا: آپ عشاء کی نماز پڑھتے تھے پھر سنتیں پڑھتے تھے، پھر اس کے بعد جتنی رات تک اللہ چاہتا آپ نماز پڑھا کرتے، پھر سورہتے اتنی دیر تک جتنی دیر نماز پڑھی تھی۔ پھر جاگتے اور نماز پڑھتے اتنی دیر تک جتنی دیر تک سوئے اور یہ اخیر کی نماز فجر تک ہوتی۔","f2":"یعنی آپ رات کو سوتے بھی اور نماز بھی پڑھتے۔ نہ ساری رات جاگتے نہ ساری رات سوتے۔"}],[1629,"یعلی بن مملک سے روایت ہے کہ انہوں نے ام المؤمنین ام سلمہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی قرآت اور آپ کی نماز کے متعلق سوال کیا، تو انہوں نے کہا: تمہیں آپ کی نماز سے کیا سروکار؟ ۱؎ آپ نماز پڑھتے تھے، پھر جتنی دیر تک آپ نے نماز پڑھی تھی اسی کے بقدر آپ سوتے، پھر جتنی دیر تک سوئے تھے اسی کے بقدر آپ اٹھ کر نماز پڑھتے، پھر جتنی دیر تک نماز پڑھی تھی اسی کے بقدر آپ سوتے یہاں تک کہ آپ صبح کرتے، پھر انہوں نے ان سے آپ کی قرآت کی کیفیت بیان کی، تو وہ ایک ایک حرف واضح کر کے بیان کر رہی تھیں۔\n§وضاحت\n۱؎: یعنی تمہارا اسے پوچھنا بےسود ہے کیونکہ تم ویسی نماز نہیں پڑھ سکتے۔","الألباني: ضعيف",{"u2":"حضرت یعلی بن مملک بیان کرتے ہیں کہ انہوں نے ام سلمہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی قرات کے بارے میں پوچھا (یعنی آپ کلام اللہ کیونکر پڑھتے تھے) اور آپ کی نماز کے بارے میں پوچھا تو انہوں نے کہا: تمہیں آپ کی نماز سے کیا سروکار (یعنی تمہارا پوچھنا بے فائدہ ہے۔ کیونکہ تم ویسی نماز نہیں پڑھ سکتے) آپ نماز پڑھتے تھے پھر سو رہتے جتنی دیر نماز پڑھی پھر نماز پرھتے جتنی دیر سوئے تھے پھر سوتے جتنی دیر نماز پڑھی ہوتی تھی حتی کہ صبح ہوجاتی،پھرانھوں (ام سلمہ) نے آپ کی قراءت بیان فرمائی تو ایسی قراءت بیان فرمائی جس کا ہر حرف الگ الگ سمجھ میں آتا تھا۔","f2":"باربار اٹھنا اور نماز پڑھنا کافی مشکل کام ہے جبکہ نماز اور نیند کا عرصہ بھی برابر ہو، اس لیے فرمایا کہ تم نبی اکرم صلی اللہ علیہ وسلم جیسی نماز نہیں پڑھ سکتے۔ صلی اللہ علیہ وسلم۔"}],[1630,"عبداللہ بن عمرو بن العاص رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے نزدیک سب سے محبوب روزے داود علیہ السلام کے روزے ہیں، وہ ایک دن روزہ رکھتے تھے اور ایک دن افطار کرتے تھے، اور اللہ تعالی کے نزدیک بہترین نماز داود علیہ السلام کی نماز ہے، وہ آدھی رات تک سوتے تھے، پھر تہائی رات تک نماز پڑھتے، پھر چھٹے حصہ میں سو جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ عزوجل کو سب سے پیارہ روزہ داود علیہ السلام کا روزہ ہے۔ وہ ایک دن روزہ رکھتے تھے اور ایک دن چھوڑتے تھے۔ اور اللہ تعالیٰ کو سب سے زیادہ محبوب نماز داود علیہ السلام کی نماز ہے۔ وہ نصف رات سوتے تھے، تہائی رات نماز پڑھتے تھے اور پھر رات کا چھٹا حصہ سوتے تھے۔‘‘","f2":"(۱)حدیث نمبر ۱۶۱۷ کا فائدہ نمبر ۱ دیکھیے۔ (۲)قیام اللیل پر دوام مستحب امر ہے۔ (۳)افضل طریقہ نبی اکرم صلی اللہ علیہ وسلم کا طریقہ ہے۔ اس سے افضل کوئی اور طریقہ نہیں ہوسکتا اگرچہ وہ مقدار میں مسنون طریقے سے زیادہ مشقت میں اس سے کراں ہی کیوں نہ ہو۔"}],[1631,"حماد بن سلمہ سلیمان تیمی سے، سلیمان تیمی ثابت سے اور ثابت انس بن مالک رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس رات مجھے معراج ہوئی میں موسی علیہ السلام کے پاس سرخ ٹیلے کے پاس آیا، اور وہ کھڑے اپنی قبر میں نماز پڑھ رہے تھے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس رات مجھے معراج کروائی گئی، میں ایک سرخ ٹیلے کے قریب موسیٰ علیہ السلام کے پاس سے گزرا۔ وہ کھڑے اپنی قبر میں نماز پڑھ رہے تھے۔‘‘","f2":"ایک اور روایت ہے کہ حضرت موسیٰ علیہ السلام کی قبر سرخ ٹیلے کے قریب ہے۔ (صحیح البخاری، الجنائر، حدیث:۱۳۳۹، وصحیح مسلم، الفضائل، حدیث:۲۳۷۲) حضرت موسیٰ علیہ السلام کا اپنی قبر میں نماز پڑھنا عالم برزخ کی چیز ہے جو رسول اللہ صلی اللہ علیہ وسلم پر منکشف کی گئی۔ اگر یہ روح کے علاوہ جسم کے ساتھ بھی ہو تو وہ جسم بھی برزخی ہی ہوگا، لہٰذا اس سے انبیاء علیہم السلام کی دنیوی زندگی ثابت نہیں ہوسکتی۔ برزخی زندگی کا انکار نہیں۔"}],[1632,"سلیمان تیمی اور ثابت دونوں انس رضی اللہ عنہ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا کہ میں «الكثيب الأحمر» \"سرخ ٹیلے\" کے پاس موسی علیہ السلام کے پاس آیا اور وہ کھڑے نماز پڑھ رہے تھے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ ۱؎ ہمارے نزدیک معاذ بن خالد کی حدیث سے زیادہ درست ہے، واللہ اعلم۔\n§وضاحت\n۱؎: یعنی اس سند کا «عن سلیمان وثابت» حرف عطف کے ساتھ ہونا «عن سلیمان عن ثابت» ہونے کے مقابلہ میں زیادہ صحیح ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں سرخ ٹیلے کے قریب موسیٰ علیہ السلام کے پاس سے گزرا جبکہ وہ کھڑے نماز پڑھ رہے تھے۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ہمارے نزدیک یہ روایت معاذ بن خالد کی روایت سے زیادہ درست ہے۔ واللہ تعالیٰ اعلم۔","f2":"معاذ بن خالد کی روایت میں حضرت سلیمان تیمی کو حضرت ثابت کا شاگرد ظاہر کیا گیا ہے جبکہ درست بات یہ ہے کہ یہ دونوں ساتھی ہیں اور دونوں حضرت انس رضی اللہ عنہ سے یہ حدیث بیان کررہے ہیں جیسا کہ حدیث نمبر ۱۶۳۳ سے واضح ہورہا ہے۔"}],[1633,"حماد بن سلمہ کہتے ہیں ہمیں ثابت اور سلیمان تیمی نے خبر دی ہے وہ دونوں انس رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میں موسی علیہ السلام کی قبر پر سے گزرا اور وہ اپنی قبر میں نماز پڑھ رہے تھے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میں موسیٰ علیہ السلام کی قبر کے پاس سے گزرا جبکہ وہ اپنی قبر میں نماز پڑھ رہے تھے۔‘‘"}],[1634,"سلیمان تیمی روایت کرتے ہیں انس بن مالک رضی اللہ عنہ سے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں معراج کی رات میں موسی وضاحت پر سے گزرا اور وہ اپنی قبر میں نماز پڑھ رہے تھے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس رات مجھے معراج کروائی گئی، میں موسیٰ علیہ السلام کے پاس سے گزرا جبکہ وہ اپنی قبر میں نماز پڑھ رہے تھے۔‘‘"}],[1635,"معتمر بن سلیمان اپنے والد سے اور ان کے والد انس رضی اللہ عنہ سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم معراج کی رات موسی علیہ السلام پر سے گزرے اور وہ اپنی قبر میں نماز پڑھ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ جس رات نبی صلی اللہ علیہ وسلم کو معراج کروائی گئی، آپ موسیٰ علیہ السلام کے پاس سے گزرے جبکہ وہ اپنی قبر میں نماز پڑھ رہے تھے۔"}],[1636,"معتمر بن سلیمان کہتے ہیں کہ میں نے اپنے والد کو سنا وہ کہہ رہے تھے کہ میں نے انس رضی اللہ عنہ کو کہتے سنا ہے کہ مجھے نبی اکرم صلی اللہ علیہ وسلم کے بعض اصحاب نے بتایا کہ نبی اکرم صلی اللہ علیہ وسلم معراج کی رات میں موسی علیہ السلام پر سے گزرے، اور وہ اپنی قبر میں نماز پڑھ رہے تھے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ مجھے نبی صلی اللہ علیہ وسلم کے صحابہ میں سے ایک صحابی نے خبر دی کہ جس رات نبی صلی اللہ علیہ وسلم کو معراج کروائی گئی، آپ موسیٰ علیہ السلام کے پاس سے گزرے تھے جبکہ وہ اپنی قبر میں نماز پڑھ رہے تھے۔"}],[1637,"سلیمان انس رضی اللہ عنہ سے اور وہ نبی اکرم صلی اللہ علیہ وسلم کے بعض اصحاب سے روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"معراج کی رات میں میں موسی کے پاس سے گزرا اور وہ اپنی قبر میں نماز پڑھ رہے تھے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کے کسی صحابی سے روایت کی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس رات مجھے معراج کروائی گئی، میں موسیٰ علیہ السلام کے پاس سے گزرا جبکہ وہ اپنی قبر میں نماز پڑھ رہے تھے۔‘‘","f2":"امام نسائی رحمہ اللہ نے ایک ہی روایت کو مختلف لفظوں سے بیان کیا ہے۔ دراصل ان کا مقصود حضرت انس رضی اللہ عنہ کے شاگرد سلیمان تیمی (جن پر اس روایت کا مدار ہے) کے شاگردوں کا اختلاف واضح کرتا ہے کہ کسی نے یہ روایت مرفوع متصل اور کسی نے مرسل بیان کی ہے۔ کسی نے حضرت انس رضی اللہ عنہ اور رسول اللہ صلی اللہ علیہ وسلم کے درمیان کسی اور صحابی کا واسطہ بیان کیا ہے لیکن اس میں اختلاف کی وجہ سے روایت کی صحت پر کوئی اثر نہیں پڑتا کیونکہ مندرجہ بلا صورتوں میں سے کوئی صورت بھی عیب والی نہیں۔ مزید مذکورہ باب کے تحت مندرج وضاحت ملاحظہ فرمائی جائے۔"}],[1638,"خباب بن ارت رضی اللہ عنہ سے روایت ہے (وہ بدر میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حاضر تھے) کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو پوری رات نماز پڑھتے دیکھا یہاں تک کہ فجر ہو گئی، جب رسول اللہ صلی اللہ علیہ وسلم نے اپنی نماز سے سلام پھیرا، تو خباب رضی اللہ عنہ آپ کے پاس آئے، اور عرض کیا: اللہ کے رسول! میرے ماں باپ آپ پر فدا ہوں، آپ نے آج رات ایسی نماز پڑھی کہ اس طرح میں نے آپ کو پڑھتے ہوئے کبھی نہیں دیکھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں یہ رغبت اور خوف کی نماز تھی، میں نے اپنے رب سے اس میں تین باتوں کی درخواست کی، تو اس نے دو مجھے دے دیں اور ایک نہیں دی، میں نے اپنے رب سے درخواست کی کہ وہ ہمیں اس چیز کے ذریعہ ہلاک نہ کرے جس کے ذریعہ اس نے ہم سے پہلے کی امتوں کو ہلاک کیا، تو اس نے یہ مجھے دے دی، اور میں نے اپنے رب سے درخواست کی کہ وہ کسی دشمن کو جو ہم میں سے نہ ہو ہم پر غالب نہ کرے، تو اسے بھی اس نے مجھے دے دیا، اور میں نے اپنے رب سے درخواست کی کہ وہ ہم میں پھوٹ نہ ڈالے، اور ہم گروہ در گروہ نہ ہوں، تو اس نے میری یہ درخواست قبول نہیں کی\"۔","الألباني: صحيح"],[1639,"مسروق کہتے ہیں کہ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب (رمضان کا آخری) عشرہ ہوتا تو رسول اللہ صلی اللہ علیہ وسلم شب بیداری فرماتے، اور اپنے اہل و عیال کو بیدار کرتے، اور (عبادت کے لیے) کمر بستہ ہو جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ جب رمضان المبارک کا آخری دہاکا (دس دن) شروع ہوتا تو رسول اللہ صلی اللہ علیہ وسلم ساری رات جاگتے (عبادت کرتے) اور اپنے گھر والوں کو بھی جگاتے اور اپنا تہ بند کس لیتے۔","f2":"(۱)’’تہ بند کس لیتے‘‘ یہ کنایہ ہے۔ مقصد یہ ہے کہ عبادت کی پوری تیاری فرمالیتے کیونکہ لمبا اور سخت کام کرنے والا شخص پانے تہ بند کو اچھی طرح کس لیتا ہے تاکہ درمیان میں یہ ڈھیلا نہ ہو۔ (۲)اللہ رب العزت نے آپ صلی اللہ علیہ وسلم کے اگلے پچھلے تمام گناہ معاف کدیے تھے، اس کے باوجود آپ صلی اللہ علیہ وسلم نفلی نماز میں اس قدر محنت و مشقت سے کام لیتے تھے۔ ہمیں بھی نفلی عبادت میں بڑھ چڑھ کر حصہ لینا چاہیے۔ (۳)رمضان المبارک کی آخری دس راتیں باقی راتوں سے زیادہ افضل ہیں۔ (۴)عبادت کےلیے گھر والوں کو بھی جگانا مستحب امر ہے۔"}],[1640,"ابواسحاق سبیعی کہتے ہیں کہ میں اسود بن یزید کے پاس آیا، وہ میرے بھائی اور دوست تھے، تو میں نے کہا: اے ابوعمرو! مجھ سے وہ باتیں بیان کریں جن کو ام المؤمنین نے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے متعلق بیان کیا ہے، تو انہوں نے کہا: وہ کہتی ہیں کہ آپ شروع رات میں سوتے تھے، اور اس کے آخر کو زندہ رکھتے تھے۱؎۔\n§وضاحت\n۱؎: یعنی رات کے آخری حصہ میں جاگ کر عبادت کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابواسحاق بیان کرتے ہیں کہ میں حضرت اسود بن یزید کے پاس آیا اور عرض کیا۔۔۔ وہ میرے بھائی اور دوست تھے۔۔۔: اے ابوعمرو! مجھے وہ حدیث بیان کیجیے جو آپ کو ام المومنین (حضرت عائشہ رضی اللہ عنہا) نے رسول اللہ صلی اللہ علیہ وسلم کی (رات کی) نماز کے بارے می بیان کی ہے۔ انھوں نے کہا: حضرت عائشہ رضی اللہ عنہا نے فرمایا تھا کہ رسول اللہ صلی اللہ علیہ وسلم رات کے شروع میں (عشاء کی نماز کے بعد) سوجاتے تھے اور رات کا آخری حصہ جاگتے (عبادت کرتے) تھے۔"}],[1641,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نہیں جانتی کہ رسول اللہ صلی اللہ علیہ وسلم نے پورا قرآن ایک رات میں پڑھا ہو، یا رات بھر صبح تک عبادت کی ہو، یا پورے مہینے روزے رکھے ہوں، سوائے رمضان کے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نہیں جانتی کہ رسول اللہ صلی اللہ علیہ وسلم نے کبھی ایک رات میں سارا قرآن پڑھا ہو یا صبح تک ساری رات نماز پڑھی ہو یا رمضان المبارک کے علاوہ کبھی پورے مہینے کے روزے رکھے ہوں۔","f2":"’’ساری رات نماز پڑھی ہو‘‘ اوپر گزرا ہے کہ رمضان المبارک کے آخری عشرے میں ساری ساری رات نماز پڑھتے تھے۔ گویا یہ روایت آخری عشرے کے علاوہ باقی مہینوں اور دنوں کی ہے، لہٰذا ان میں کوئی اختلاف نہیں کیونکہ عام معمول یہی تھا کہ سوتے بھی تھے اور نماز بھی پڑھتے تھے۔ آخری عشرے میں بھی ممکن ہے کچھ سوتے رہے ہوں اور بیشتر رات کو پوری رات کہہ دیا گیا ہو۔ واللہ اعلم۔"}],[1642,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آئے، اور ان کے پاس ایک عورت (بیٹھی ہوئی) تھی تو آپ نے پوچھا:\"یہ کون ہے؟\" انہوں نے کہا: فلاں (عورت) ہے جو سوتی نہیں ہے، پھر انہوں نے اس کی نماز کا ذکر کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"چپ رہو، تم اتنا ہی کرو جتنے کی تمہیں طاقت ہو، قسم اللہ کی، اللہ نہیں تھکتا ہے یہاں تک کہ تم تھک جاؤ، پسندیدہ دین (عمل) اس کے نزدیک وہی ہے جس پر آدمی مداومت کرے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک دفعہ نبی صلی اللہ علیہ وسلم ان کے پاس تشریف لائے جبکہ ان کے پاس ایک عورت بیٹھی تھی۔ آپ نے فرمایا: ’’یہ کون ہے؟‘‘ میں نے عرض کیا: فلاں عورت ہے جو رات کو سوتی نہیں۔ میں نے اس کی نماز کا ذکر کیا۔ آپ نے فرمایا: ’’رہنے دو۔ اتنا کام اختیار کرو جس کی تم (ہمیشہ) طاقت رکھ سکتی و۔ اللہ کی قسم! اللہ تعالیٰ (ثواب دینے سے) نہیں اکتائے گا۔ تم ہی (نیکی کرنے سے) اکتا جاؤ گے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم کو وہ دینی کام زیادہ اچھا لگتا تھا جس پر اس کام والا ہمیشگی کرے۔","f2":"(۱)’’رہنے دو‘‘ ممکن ہے خطاب حضرت عائشہ رضی اللہ عنہا کو ہو، یعنی زیادہ تعریف نہ کرو کیونکہ ہمیشہ ساری رات جاگنا افضل نہیں اور ممکن ہے خطاب اس عورت کو ہو کہ اتنی عبادت نہ کیا کرو۔ ایسا نہ ہو کہ طبیعت تھک کر، پھر عبادت سے اکتا جائے۔ (۲)’’ہمیشگی کرے‘‘ کسی نفل کام پر دوام ہوسکتا ہے، البتہ اسے فرض سمجھتے ہوئے نہیں، مستحب سمجھتے ہوئے دوام کرے تو کوئی حرج نہیں۔ (۳)اللہ تعالیٰ بندے سے وہی معاملہ کرتا ہے جو بندہ اللہ سے کرتا ہے۔ اگر بندہ اللہ کی طرف ہمیشہ متوجہ رہے تو اللہ رب العزت بھی بندے پر مسلسل نظررحمت رکھتا ہےا ور اگر بندہ اعراض کرے تو اللہ تعالیٰ بھی اعراض فرماتا ہے۔"}],[1643,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے، آپ نے دو ستونوں کے درمیان میں ایک لمبی رسی دیکھی، تو آپ نے پوچھا: \"یہ رسی کیسی ہے؟\" تو لوگوں نے عرض کیا: زینب (زینب بنت جحش) کی ہے وہ نماز پڑھتی ہیں، جب کھڑے کھڑے تھک جاتی ہیں تو اس سے لٹک جاتی ہیں، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کھولو اسے، تم میں سے کوئی بھی ہو جب تک اس کا دل لگے نماز پڑھے، اور جب تھک جائے تو بیٹھ جائے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم مسجد میں داخل ہوئے تو ایک رسی دوستونوں کے درمیان بندھی ہوئی دیکھی۔ آپ نے پوچھا: ’’یہ رسی کیسی ہے؟‘‘ لوگوں نے کہا: (ام المومنین) حضرت زینب بنت جحش رضی اللہ عنہا کی ہے۔ وہ نماز پڑھتی ہیں۔ جب تھک جاتی ہیں تو اس کا سہارا لیتی ہیں۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اسے کھول دو۔ تم میں سے ہر شخص اس وقت تک نماز پڑھے جب تک اس میں چستی باقی رہے۔ جب وہ سست پڑجائے تو نماز چھوڑ کر بیٹھ رہے۔‘‘","f2":"(۱)سستی کی حالت میں نماز کے دوران میں خشوع و خضوع باقی نہیں رہتا۔ اور نماز نام ہی خشوع و خضوع کا ہے، اس لیے منع فرمایا، نیز ممکن ہے سستی اور تھکاوٹ کی حالت میں نمازی کہنا کچھ چاہے، زبان سے نکل کچھ جائے۔ علاوہ ازیں ایسی حالت میں اکتاہٹ بھی پیدا ہوسکتی ہے جو ترک کومستلزم ہے، لہٰذا سستی، تھکاوٹ اور نیند کی حالت میں نماز چھوڑ کر آرام کرنا چاہیے تاکہ دوبارہ چستی پیدا ہو۔ (۲)منکر کا ازالہ کرنا چاہیے، ہاتھ زبان سے یا جیسے بھی ممکن ہو۔ (۳)عورت مسجد میں نماز پڑھ سکتی ہے، اس میں کوئی کراہت نہیں۔"}],[1644,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم (نماز میں) کھڑے رہتے یہاں تک کہ آپ کے دونوں پیر سوج جاتے، تو آپ سے عرض کیا گیا: اللہ تعالی نے آپ کے اگلے اور پچھلے گناہ بخش دیئے ہیں (پھر آپ اتنی عبادت کیوں کرتے ہیں) تو آپ نے فرمایا: \"کیا میں شکر گزار بندہ نہ بنوں\"۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم (نفل) نماز اتنی لمبی پڑھتے تھے کہ آپ کے قدم مبارک سوج جاتے تھے۔ آپ سے گزارش کی گئی کہ اللہ تعالیٰ نے تو آپ کے اگلے پچھلے سب قصور معاف فرما دیے ہیں (پھر آپ اتنی عبادت کیوں کرتے ہیں؟) آپ نے فرمایا: ’’کیا میں اللہ تعالیٰ کا شکرگزار بندہ نہ بنو؟‘‘","f2":"(۱)رسول اللہ صلی اللہ علیہ وسلم کے قدموں کا سوج جانا سستی کومستلزم نہیں کیونکہ سستی اور چستی کا تعلق دل اور دماغ کے ساتھ ہے۔ (۲)’’اگلے پچھلے گناہ‘‘ یہ ایک فرضی چیز ہے۔ کہا گیا ہے نبوت سے قبل اگر کوئی کوتاہی ہوئی ہو۔ بعض نے اس سے ترک اولیٰ مراد لیا ہے جو آپ اپنی امت کی مصلحت کی خاطر کیا کرتے تھے، مثلاً: جنگ بدر کے قیدیوں کو فدیہ لے کر چھوڑ دینا یا عبداللہ بن ابی کا جنازہ پڑھنا وغیرہ۔ اسے اجتہادی خطا سے بھی تعبیر کیا گیا ہے۔ (۳)’’شکرگزار بندہ‘‘ یعنی اگر اللہ تعالیٰ نے مجھ سے پوچھ گچھ موقوف کردی ہے تو میرا بھی فرض ہے کہ میں ہر دم اسی کو یاد کروں۔ رسول اللہ صلی اللہ علیہ وسلم کی انھی اداؤں نے آپ کو سیدالاولین والآخرین بنایا ہے۔ اللہ تعالیٰ کی حمد ہی کی وجہ سے آپ مقام محمود پر فائز ہوں گے۔ (فداہ نفسی و روحی صلی اللہ علیہ وسلم) (۴)شکر جیسے زبان سے ادا ہوتا ہے عمل سے بھی ہوتا ہے۔"}],[1645,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نماز پڑھتے تھے یہاں تک کہ آپ کے دونوں پاؤں پھٹ جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اس قدر لمبی نماز پڑھتے تھے کہ آپ کے قدم مبارک پھٹ جاتے تھے۔","f2":"سوچنے کے بعد پھٹنے کا مقام، یعنی آخر آنا ہی تھا، مگر نبی صلی اللہ علیہ وسلم میں سستی کا احساس راہ نہیں پاتا تھا۔"}],[1646,"بدیل اور ایوب دونوں عبداللہ بن شفیق سے روایت کرتے ہیں، اور وہ ام المؤمنین عائشہ رضی اللہ عنہا سے کہ رسول اللہ صلی اللہ علیہ وسلم رات میں کافی دیر تک نماز پڑھتے، تو جب آپ کھڑے ہو کر نماز پڑھتے تو کھڑے کھڑے ہی رکوع کرتے، اور جب بیٹھ کر پڑھتے تو بیٹھ کر رکوع کرتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو بہت دیر تک نماز پڑھتے رہتے۔ جب آپ کھڑے ہوکر نماز شروع فرماتے تو رکوع بھی کھڑے ہوکر ہی فرماتے اور جب بیٹھ کر نماز شروع فرماتے تو رکوع بھی بیٹھ کر ہی فرماتے۔"}],[1647,"ابن سیرین عبداللہ بن شفیق سے اور عبداللہ بن شقیق ام المؤمنین عائشہ رضی اللہ عنہا سے روایت کرتے ہیں، وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کبھی کھڑے ہو کر اور کبھی بیٹھ کر نماز پڑھتے، تو جب آپ کھڑے ہو کر نماز شروع کرتے تو کھڑے کھڑے رکوع کرتے، اور جب بیٹھ کر شروع کرتے تو بیٹھے بیٹھے ہی رکوع کرتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم کبھی کھڑے ہوکر نفل نماز پرھتے تھے اور کبھی بیٹھ کر۔ جب کھڑے ہوکر نماز شروع فرماتے تو رکوع بھی کھڑے ہوکر فرماتے اورجب بیٹھ کر نماز شروع فرماتے تو رکوع بھی بیٹھ کر فرماتے۔"}],[1648,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں نبی اکرم صلی اللہ علیہ وسلم نماز پڑھتے اور بیٹھے ہوتے، اور قرآت کرتے اور بیٹھے ہوتے، پھر جب آپ کی قرآت میں تیس یا چالیس آیتوں کے بقدر باقی رہ جاتی تو کھڑے ہو جاتے، اور کھڑے ہو کر قرآت کرتے، پھر رکوع کرتے، پھر سجدہ کرتے، پھر دوسری رکعت میں (بھی) ایسے ہی کرتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم بیٹھ کر نماز شروع فرماتے تو بیٹھے بیٹھے ہی قراءت فرماتے۔ جب آپ کی قراءت سے تیس یا چالیس آیات باقی رہ جاتیں تو آپ کھڑے ہوجاتے اور وہ آیات کھڑے ہوکر تلاوت فرماتے، پھر رکوع فرماتے، پھر سجدہ فرماتے، پھر دوسری رکعت میں بھی ایسے ہی کرتے۔"}],[1649,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں میں نے رسول اللہ صلی اللہ علیہ وسلم کو نہیں دیکھا کہ آپ نے بیٹھ کر نماز پڑھی ہو یہاں تک کہ آپ بوڑھے ہو گئے، تو (جب آپ بوڑھے ہو گئے) تو آپ بیٹھ کر نماز پڑھتے اور بیٹھ کر قرآت کرتے، پھر جب سورۃ میں سے تیس یا چالیس آیتیں باقی رہ جاتیں تو ان کی قرآت کھڑے ہو کر کرتے، پھر رکوع کرتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ میں نے کبھی رسول اللہ صلی اللہ علیہ وسلم کو بیٹھ کر نماز پڑھتے نہیں دیکھا حتی کہ آپ بڑھاپے میں داخل ہوگئے، پھر آپ بیٹھ کر نماز شروع فرماتے اور قراءت کرتے۔ جب اس سورت کی تیس چالیس آیات رہ جاتیں تو کھڑے ہوکر انھیں پڑھتے، پھر رکوع فرماتے۔","f2":"بعض کا قول ہے کہ ان دو روایات میں جو طریقہ بیان کیا گیا ہے، وہ بڑھاپے کے دور کا ہے جیسا کہ دوسری حدیث میں صراحت ہے۔ پہلی دواحادیث میں بڑھاپے سے قبل کا طریقہ بیان کیا گیا ہے، لہٰذا یہ حقیقتاً اختلاف نہیں اگرچہ ظاہراً اختلاف ہے، نیز اسے تعدد احوال پر بھی محمول کیا جاسکتا ہے، یعنی رسول اللہ صلی اللہ علیہ وسلم کبھی کھڑے ہوکر اور کبھی بیٹھ کر نماز پڑھ لیتے تھے۔ اس طرح دونوں قسم کی احادیث میں ظاہری تعارض رفع ہوجاتا ہے۔"}],[1650,"عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم قرآت کرتے اور بیٹھے ہوتے، تو جب آپ رکوع کرنا چاہتے تو آدمی کے چالیس آیتیں پڑھنے کے بقدر(باقی رہنے پر) کھڑے ہو جاتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (کبھی) قراءت بیٹھ کر کرتے۔ جب رکوع کا ارادہ فرماتے تو اتنی دیر پہلے کھڑے ہوجاتے جتنی دیر میں انسان چالیس آیات پڑھ سکتا ہے۔"}],[1651,"سعد بن ہشام بن عامر کہتے ہیں میں مدینہ آیا تو ام المؤمنین عائشہ رضی اللہ عنہا کے پاس آیا، انہوں نے پوچھا: تم کون ہو؟ میں نے کہا: میں سعد بن ہشام بن عامر ہوں، انہوں نے کہا: اللہ تمہارے باپ پر رحم کرے، میں نے کہا: مجھے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے متعلق کچھ بتائیے، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایسا ایسا کرتے تھے، میں نے کہا: اچھا، انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم رات میں عشاء کی نماز پڑھتے تھے، پھر آپ اپنے بچھونے کی طرف آتے اور سو جاتے، پھر جب آدھی رات ہوتی، تو قضائے حاجت کے لیے اٹھتے اور وضو کے پانی کے پاس آتے، اور وضو کرتے، پھر مسجد آتے اور آٹھ رکعتیں پڑھتے، تو پھر ایسا محسوس ہوتا کہ ان میں قرآت، رکوع اور سجدے سب برابر برابر ہیں، اور ایک رکعت وتر پڑھتے، پھر بیٹھ کر دو رکعت پڑھتے، پھر آپ اپنے پہلو کے بل لیٹ جاتے، تو کبھی اس سے پہلے کہ آپ کی آنکھ لگے بلال رضی اللہ عنہ آپ کے پاس آتے، اور آپ کو نماز کی اطلاع دیتے، اور کبھی آپ کی آنکھ لگ جاتی، اور کبھی مجھے شک ہوتا کہ آپ سوئے یا نہیں سوئے یہاں تک کہ وہ آپ کو نماز کی خبر دیتے، تو یہ رسول اللہ صلی اللہ علیہ وسلم کی نماز تھی، یہاں تک کہ آپ عمردراز ہو گئے، اور جسم پر گوشت چڑھ گیا، پھر انہوں نے آپ کے جسم پر گوشت چڑھنے کا حال بیان کیا جو اللہ نے چاہا، وہ کہتی ہیں: نبی اکرم صلی اللہ علیہ وسلم لوگوں کو عشاء کی نماز پڑھاتے، پھر اپنے بچھونے کی طرف آتے، تو جب آدھی رات ہو جاتی تو آپ اپنی پاکی اور حاجت کے لیے اٹھ کر جاتے، پھر وضو کرتے، پھر مسجد آتے تو چھ رکعتیں پڑھتے، ایسا محسوس ہوتا کہ آپ ان میں قرآت، رکوع اور سجدے میں برابری رکھتے ہیں، پھر آپ ایک رکعت وتر پڑھتے، پھر دو رکعت بیٹھ کر پڑھتے، پھر اپنے پہلو کے بل لیٹتے تو کبھی بلال رضی اللہ عنہ آپ کی آنکھ لگنے سے پہلے ہی آ کر نماز کی اطلاع دیتے، اور کبھی آنکھ لگ جانے پر آتے، اور کبھی مجھے شک ہوتا کہ آپ کی آنکھ لگی یا نہیں یہاں تک کہ وہ آپ کو نماز کی خبر دیتے، وہ کہتی ہیں: تو برابر یہی رسول اللہ صلی اللہ علیہ وسلم کی نماز رہی۔","الألباني: صحيح",{"u2":"حضرت سعد بن ہشام بن عامر رضی اللہ عنہ سے روایت ہے کہ میں مدینہ منورہ اور حضرت عائشہ رضی اللہ عنہا کی خدمت میں حاضر ہوا۔ انھوں نے پوچھا؛ تو کون ہے؟ میں نے کہا: ہمشام بن عامر کا بیٹا سعد ہوں۔ فرمانے لگیں: اللہ تعالیٰ تیرے باپ پر رحم فرمائے۔ میں نے عرض کیا: مجھے رسول اللہ صلی اللہ علیہ وسلم کی (رات کی نفل) نماز کے بارے میں بتائیے۔ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم تو بہت بلندوبالا شخصیت تھے۔ میں نے کہا: یقیناً ایسا ہی ہے۔ فرمانے لگیں: رسول اللہ صلی اللہ علیہ وسلم رات کو عشاء کی نماز پڑھتے، پھر اپنے بستر پر لیٹ کر سو جاتے۔ جب آدھی رات گزر جاتی تو اٹھ کر قضائے حاجت کرتے اور پانی لے کر وضو کرتے، پھر (اپنے گھر کی) مسجد میں داخل ہوجاتے اور آٹھ رکعات پڑھتے۔ مجھے یوں محسوس ہوتا تھا کہ آپ ان میں قراءت، رکوع اور سجدے برابر کرتے تھے، پھر ایک رکعت پڑھتے اور اس کے بعد بیٹھ کر دو رکعت پڑھتے، پھر لیٹ جاتے، پھر کبھی تو بلال رضی اللہ عنہ آپ کے سونے سے پہلے ہی آکر نماز کی اطلاع کرتے اور کبھی آپ ہلکی سی نیند لے لیتے تھے اور کبھی مجھے شک سا ہوتا کہ آپ سوئے ہوئے ہیں یا نہیں حتی کہ بلال آکر ااپ کو نماز کی اطلاع کرتے۔ تو یہ تھی رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز حتی کہ آپ کی عمر بڑھ گئی اور آپ فربہ ہوگئے۔ حضرت عائشہ رضی اللہ عنہا نے آپ کے موٹاپے کے بارے میں چند باتیں ذکر کیں، پھر انھوں نے فرمایا: (اس عمر میں) نبی صلی اللہ علیہ وسلم لوگوں کو عشاء کی نماز پڑھاتے، پھر اپنے بستر پر لیٹ جاتے۔ جب نصف رات گزر جاتی تو اٹھتے اور قضائے حاجت کرتے اور وضو کا پانی لے کر وضو فرماتے، پھر مسجد (گھر میں نماز کے لیے مخصوص جگہ) میں داخل ہوجاتے اور چھ رکعات پڑھتے۔ مجھے یوں محسوس ہوتا تھا کہ آپ ان میں قراءت، رکوع اور سجدہ ایک جیسا کرتے تھے، پھر ایک رکعت پڑھتے، پھر بیٹھ کر دو رکعات پڑھتے، پھر لیٹ جاتے۔ کبھی تو بلال آپ کے سونے سے پہلے ہی آکر نماز کی اطلاع کرتے۔ کبھی آپ ہلکی سی نیند لے لیتے تھے اور کبھی مجھے شک رہتا کہ آپ سوگئے ہیں یا نہیں، حتی کہ بلال آکر آپ کو نماز کی اطلاع کرتے۔ (وفات تک) رسول اللہ صلی اللہ علیہ وسلم کی (رات کی) نماز یہی رہی۔","f2":"وتر کے بعد بیٹھ کر دو رکعات پڑھنا نبی صلی اللہ علیہ وسلم کا دائمی معمول نہ تھا۔ بہت سی روایات میں ان کا ذکر نہیں۔ معلوم ہوتا ہے کہ آپ کبھی یہ رکعات پڑھتے، کبھی نہیں۔ اسی طرح ضروری نہیں کہ ان کو بیٹھ کر ہی پڑھا جائے۔ ممکن ہے آپ تہجد کی لمبی لمبی رکعات میں تھک جانے کی وجہ سے یہ دو رکعات بیٹھ کر پڑھتے ہوں۔ ویسے بھی آپ کو بیٹھ کر نوافل پڑھنے کا ثواب، کھڑے ہوکر پڑھنے کے برابر ملتا تھا۔ دیکھیے: (صحیح مسلم، صلاۃ المسافرین، حدیث:۷۳۵) ہمیں پورے ثواب کے لیے نوافل کھڑے ہوکر پڑھنے چاہییں، اگرچہ بیٹھ کر پڑھنا بھی جائز ہے۔ امام ابن تیمیہ رحمہ اللہ کے نزدیک یہ دو رکعات وتر کا تتمہ ہیں، مغرب کی دو سنتوں کی طرح۔ ورنہ آپ نے وتر کو آخر میں پڑھنے کا حکم دیا ہے۔ گویا ان کے باوجود وتر آخر ہی میں رہتے ہیں کیونکہ یہ وتر کے تابع ہیں۔ یا امر استحباب کے لیے ہے اور فعل جواز پر دلالت کرتا ہے۔ واللہ اعلم۔"}],[1652,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے کی حالت میں میرے چہرے سے نہیں بچتے تھے ۱؎ اور آپ کی وفات نہیں ہوئی یہاں تک کہ آپ کی بیشتر نمازیں بیٹھ کر ہونے لگیں، سوائے فرض نماز کے، اور سب سے زیادہ پسندیدہ عمل آپ کے نزدیک وہ تھا جس پر آدمی مداومت کرے اگرچہ وہ تھوڑا ہی ہو۔ یونس نے عمر بن ابی زائدہ کی مخالفت کی ہے یونس نے اسے ابواسحاق سے اور ابواسحاق نے اسود سے اور اسود نے ام سلمہ رضی اللہ عنہا سے روایت کی ہے۔\n§وضاحت\n۱؎: یعنی روزے کی حالت میں بوسہ وغیرہ لینے سے پرہیز نہیں کرتے تھے۔","الألباني: صحيح لغيره",{"u2":"حضرت عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم روزے کی حالت میں میرے چہرے (کے بوسے) سے پرہیز نہیں فرماتے تھے اور جب آپ قریب الوفات تھے تو فرض نماز کے علاوہ آپ کی اکثر نماز بیٹھ کر ہوتی تھی۔ اور آپ صلی اللہ علیہ وسلم کے نزدیک زیادہ پسندیدہ عمل وہ ہوتا تھا جس پر انسان ہمیشگی کرے چاہے وہ تھوڑا ہی ہو۔\nیونس نے اس روایت کو ابواسحاق سے بیان کرتے ہوئے عمر بن ابی زائدہ کی مخالفت کی ہے اور یہ روایت عن ابی اسحاق عن الاسود عن ام سلمہ کی سند سے بیان کی ہے۔","f2":"(۱)یہاں سے آگے چند روایات میں امام نسائی رحمہ اللہ ابواسحاق کے شاگردوں کا اختلاف بیان کررہے ہیں۔ ابواسحٰق شاگردوں میں سے عمر بن ابی زائدہ کے نزدیک یہ روایت حضرت عائشہ رضی اللہ عنہا کی ہے جبکہ یونس کے نزدیک یہ روایت حضرت ام سلمہ رضی اللہ عنہا کی ہے۔ (۲)نفل نماز بیٹھ کر بھی پڑھی جاسکتی ہے اگر بلا عذر ہو تو نصف ثواب ہوگا۔ اور اگر کوئی عذر (مرض، بڑھاپا وغیرہ) ہو تو پورا ثواب ملے گا بشرطیکہ وہ صحت اور جوانی میں کھڑا ہوکر پڑھتا رہا ہو، البتہ فرض نماز عذر کے بغیر بیٹھ کر نہیں پڑھی جاسکتی۔ عذر کے ساتھ بیٹھ کر جائز ہے۔ ثواب بھی پورا ہوگا۔ (۳)روزے کی حالت میں جماع منع ہے۔ مطلق شہوت اور بوسہ وغیرہ (جماع وانزال کے بغیر) روزے کے منافی نہیں۔ اس سے ثواب میں بھی کوئی فرق نہیں پڑتا الایہ کہ ان سے جماع کا خطرہ ہو یا انزال کا، پھر منع ہیں، اسی لیے نبی صلی اللہ علیہ وسلم نے ایک نوجوان کو بوسے کی اجازت نہیں دی تھی اور ایک بوڑھے کو اجازت دے دی تھی کیونکہ اس سے جماع کا خطرہ نہیں تھا بخلاف نوجوان کے۔"}],[1653,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ کی بیشتر نمازیں بیٹھ کر ہونے لگیں سوائے فرض نماز کے۔ شعبہ اور سفیان نے یونس بن شریک کی مخالفت کی ہے، ان دونوں نے اسے ابواسحاق سے اور ابواسحاق نے ابوسلمہ سے اور ابوسلمہ نے ام سلمہ سے روایت کی۔","الألباني: صحيح لغيره",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے مروی ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم اپنی وفات کے قریب فرض نماز کے علاوہ نماز اکثر بیٹھ کر پڑھا کرتے تھے۔\nشعبہ اور سفیان نے یونس کی مخالفت کی ہے، انھوں نے یہ روایت عن ابی اسحاق عن ابی سلمۃ عن ام سلمۃ کی سند سے بیان کی ہے۔","f2":"عمر بن زائدہ اور یونس نے ابواسحاق کا استاد اسود بتایا تھا جبکہ شعبہ اور سفیان نے ابواسحاق کا استاد ابوسلمہ بتایا ہے، البتہ یہ روایت ام سلمہ رضی اللہ عنہا ہی کی بتائی ہوئی ہے۔"}],[1654,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں رسول اللہ صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ کی اکثر و بیشتر نمازیں بیٹھ کر ہونے لگیں، سوائے فرض نماز کے اور آپ کے نزدیک سب سے زیادہ پسندیدہ عمل وہ تھا جس کو ہمیشہ کیا جائے خواہ وہ تھوڑا ہی ہو۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وفات کے قریب فرض نماز کے علاوہ باقی نماز اکثر بیٹھ کر پڑھا کرتے تھے۔ اور آپ کے نزدیک زیادہ پسندیدہ عمل وہ تھا جس پر ہمیشگی کی جائے اگرچہ وہ کم ہو۔"}],[1655,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ قسم ہے اس ذات کی جس کے ہاتھ میں میری جان ہے، رسول اللہ صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ کی بیشتر نمازیں بیٹھ کر ہونے لگیں سوائے فرض نماز کے، اور آپ کے نزدیک سب سے زیادہ پسندیدہ عمل وہ تھا جس پر مداومت کی جائے اگرچہ وہ تھوڑا ہی ہو۔ عثمان بن ابی سلیمان نے ابواسحاق کی مخالفت کی ہے انہوں نے اسے ابوسلمہ سے اور ابوسلمہ نے عائشہ رضی اللہ عنہا سے روایت کی ہے ۱؎۔\n§وضاحت\n۱؎: مخالفت اس طرح ہے کہ عثمان نے ام سلمہ کی جگہ عائشہ کا ذکر کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وفات کے قریب فرض نماز کے علاوہ باقی نماز اکثر بیٹھ کر پڑھا کرت تھے۔ اور آپ کے نزدیک پسندیدہ عمل وہ تھا جس پر ہمیشگی کی جائے اگرچہ وہ کم ہو۔ عثمان بن ابوسلیمان نے ان کی مخالفت کی ہے انہوں نے یہ روایت عن ابی سلمۃ عن عائشہ کی سند سے بیان کی ہے"}],[1656,"ابن جریج سے روایت ہے کہ مجھے عثمان بن ابی سلیمان نے خبر دی ہے وہ کہتے ہیں کہ ابوسلمہ نے انہیں خبر دی ہے وہ کہتے ہیں کہ عائشہ رضی اللہ عنہا نے انہیں خبر دی ہے کہ نبی اکرم صلی اللہ علیہ وسلم کا انتقال نہیں ہوا یہاں تک کہ آپ اپنی بیشتر نمازیں بیٹھ کر پڑھنے لگے تھے۔","الألباني: صحيح",{"u2":"عثمان بن ابوسلیمان سے مروی ہے کہ ابو سلمہ نے ان سے کہا کہ عائشہ رضی اللہ عنہا نے ان سے بیان فرمایا کہ وفات سے پہلے نبی صلی اللہ علیہ وسلم اپنی اکثر نمازوں کو بیٹھ کر پڑھتے تھے۔"}],[1657,"عبداللہ بن شفیق کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم بیٹھ کر نماز پڑھتے تھے؟ تو انہوں نے کہا: ہاں، اس کے بعد کہ لوگوں نے آپ پر ذمہ داریوں کا بوجھ ڈال کر آپ کو کمزور کر دیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن شقیق سے مروی ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے پوچھا: کیا رسول اللہ صلی اللہ علیہ وسلم (نفل) نماز بیٹھ کر پڑھتے تھے؟ انھوں نے فرمایا: ہاں، جب لوگوں (کی فکر اور ان کے کاموں کے بوجھ) نے آپ کو بوڑھا کردیا تھا۔","f2":"امام نسائی رحمہ اللہ کا اس روایت کو باربار (چھ بار) ذکر کرنے سے مقصود یہ بتانا ہے کہ بعض راویوں نے یہ روایت حضرت عائشہ رضی اللہ عنہا کے نام سے بیان کی ہے اور بعض نے حضرت ام سلمہ رضی اللہ عنہا سے۔ بادی النظر میں یہ کسی راوی کی غلطی لگتی ہے اور یہ بھی ممکن ہے کہ یہ روایت دونوں سے منقول ہو اور مؤخرالذکر یہی بات ہی درست ہے۔ واللہ اعلم۔ نیچے سند میں بھی اختلاف ہے جو سند کو بغور دیکھنے سے سمجھ میں آسکتا ہے اور حل بھی ہوسکتا ہے۔"}],[1658,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کبھی بیٹھ کر نفل پڑھتے نہیں دیکھا یہاں تک کہ اپنی وفات سے ایک سال قبل آپ بیٹھ کر نماز پڑھنے لگے تھے، آپ سورت پڑھتے تو اتنا ٹھہر ٹھہر کر پڑھتے کہ وہ طویل سے طویل تر ہو جاتی۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے منقول ہے، فرماتی ہیں: میں نے کبھی رسول اللہ صلی اللہ علیہ وسلم کو بیٹھ کر نفل نماز پڑھتے نہیں دیکھا تھا حتی کہ آپ کی وفات سے ایک سال قبل ایسا ہوا کہ آپ بیٹھ کر نماز پڑھنے لگے، مگر آپ سورت کو اتنا ٹھہرٹھہر کر سکون سے پڑھتے تھے کہ وہ اپنے سے لمبی سورت سے بھی لمبی بن جاتی تھی۔"}],[1659,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو بیٹھ کر نماز پڑھتے دیکھا تو میں نے عرض کیا کہ مجھ سے بیان کیا گیا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا ہے کہ بیٹھ کر پڑھنے والے کی نماز کھڑے ہو کر پڑھنے والے کی نماز کے آدھی ہوتی ہے، اور آپ خود بیٹھ کر پڑھ رہے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں لیکن میں تم لوگوں کی طرح نہیں ہوں\" ۱؎۔\n§وضاحت\n۱؎: میرا معاملہ تم لوگوں سے جداگانہ ہے، میں خواہ بیٹھ کر پڑھوں یا کھڑے ہو کر میری نماز میں کوئی کمی نہیں رہتی، بیٹھ کر پڑھنے میں بھی مجھے پورا ثواب ملتا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہا سے روایت ہے کہ میں نے نبی صلی اللہ علیہ وسلم کو بیٹھ کر نماز پڑھتے دیکھا تو میں نے کہاُ: مجھ سے یہ تو بیان کیا گیا ہے کہ آپ نے فرمایا ہے: ’’بیٹھ کر نماز پڑھنے والے کو کھڑے ہوکر نماز پڑھنے والے سے نصف ثواب ملتا ہے۔‘‘ اب آپ بیٹھ کر نماز پڑھ رہے ہیں؟ آپ نے فرمایا: ’’بات صحیح ہے، مگر میں تم جیسا نہیں۔‘‘","f2":"(۱)’’میں تم جیسا نہیں‘‘ یعنی مجھے بیٹھ کر بھی پورا ثواب ہی ملتا ہے اور یہ رسول اللہ صلی اللہ علیہ وسلم کی خصوصی شان ہے۔ یہ مفہوم بھی مراد ہوسکتا ہے کہ میں عذر کی بنا پر بیٹھ کر پڑھتا ہوں اور نصف ثواب اس کو ہے جو بلاعذر بیٹھ کر نوافل پڑھے، نیز آپ جوانی میں کھڑے ہوکر ہی نوافل پڑھا کرتے تھے۔ جو شخص جوانی میں ایک نیکی کرتا تھا مگر بڑھاپے کی بنا پر اسے نہ کرسکا تو اسے اللہ تعالیٰ اپنی رحمت کی وجہ سے پورا اجر دیتا ہے۔ (۲)کھڑے ہوکر نماز پڑھنے کی قدرت ہونے کے باوجود نفلی نماز بیٹھ کر جائز ہے لیکن یاد رہے ثواب نصف ملے گا۔"}],[1660,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے بیٹھ کر نماز پڑھنے والے شخص کے بارے میں پوچھا: تو آپ نے فرمایا: \"جس نے کھڑے ہو کر نماز پڑھی وہ سب سے افضل ہے، اور جس نے بیٹھ کر نماز پڑھی تو اسے کھڑے ہو کر پڑھنے والے کی نماز کا آدھا ثواب ملے گا، اور جس نے لیٹ کر نماز پڑھی تو اسے بیٹھ کر پڑھنے والے کے آدھا ملے گا\" ۱؎۔\n§وضاحت\n۱؎: اس سے تندرست آدمی نہیں بلکہ مریض مراد ہے کیونکہ انس رضی اللہ عنہ کا بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم کچھ لوگوں کے پاس آئے جو بیماری کی وجہ سے بیٹھ کر نماز پڑھ رہے تھے تو آپ نے فرمایا: \" بیٹھ کر نماز پڑھنے والے کا ثواب کھڑے ہو کر پڑھنے والے کے آدھا ہے \"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم سے بیٹھ کر (نفل) نماز پڑھنے والے کے بارے میں پوچھا۔ آپ نے فرمایا: ’’جو کھڑا ہوکر نفل نماز پڑھے تو وہ افضل (زیادہ ثواب والا) ہے اور جو بیٹھ کر پڑھے، اس کو کھڑے ہوکر پڑھنے والے سے نصف ثواب ملے گا اور جو لیٹ کر پڑھے، اسے بیٹھ کر پڑھنے والے سے بھی نصف ثواب ملے گا۔‘‘","f2":"مذکورہ حدیث سے معلوم ہوتا ہے کہ نفل نماز بیٹھ کر اور لیٹ کر بلاعذر پڑھی جاسکتی ہے۔ لیکن جو بیٹھ کر پڑھے اسے کھڑے ہوکر پڑھنے والے سے نصف ثواب ملے گا اور جو لیٹ کر پڑھے اسے بیٹھ کر پڑھنے والے سے بھی نصف ثواب ملے گا، تاہم عذر کی بنا پر پورا ثواب ملے گا۔"}],[1661,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کو پالتی مار کر بیٹھ کر نماز پڑھتے دیکھا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: مجھے نہیں معلوم کہ ابوداؤد حفری کے علاوہ کسی اور نے بھی یہ حدیث روایت کی ہے، اور ابوداؤد ثقہ ہیں اس کے باوجود میں اس حدیث کو غلط ہی سمجھتا ہوں، واللہ اعلم ۱؎۔\n§وضاحت\n۱؎: علم حدیث کے قواعد کے مطابق اس کے صحیح ہونے میں کوئی چیز مانع نہیں، امام ابن خزیمہ نے بھی اسے اپنی صحیح میں روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے، فرماتی ہیں: میں نے نبی صلی اللہ علیہ وسلم کو چارزانو بیٹھ کر نماز پڑھتے ہوئے دیکھا۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ میں نہیں جانتا کہ اس حدیث کو ابوداود (حفری) (مشہور محدث نہیں) کے علاوہ کسی اور نے بیان کیا ہے۔ وہ اگرچہ ثقہ راوی ہے مگر میں سمجھتا ہوں، یہ حدیث خطا ہے۔ واللہ تعالیٰ اعلم۔","f2":"(۱)امام نسائی رحمہ اللہ نے مذکورہ حدیث کو ابوداود حفری کی غلطی قرار دیا ہے لیکن ثقہ راوی کو صرف گمان کی بنیاد پر خطاکار قرار نہیں دیا جاسکتا جیسا کہ شیخ البانی رحمہ اللہ نے فرمایا ہے۔ یہ حدیث ان کے نزدیک صحیح ہے، نیز حافظ ابن حجر رحمہ اللہ نے بھی امام نسائی کے کلام کو محل نظر سمجھا ہے اور اسے بوداود حفری کی خطا نہیں کہا۔ غرض یہ حدیث صحیح ہے اور عذر پر محمول ہوگی جیسا کہ محقق کتاب نے بھی اس طرف اشارہ کیا ہے کہ اگر اسے صحیح سمجھا جائے تو یہ عذر پر محمول ہوگی۔ واللہ اعلم۔ تفصیل کے لیے دیکھیے: (اصل صفۃ صلاۃ النبی:۱؍۱۰۲ وذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۵۔۷) (۲)کس طرح بیٹھ کر نماز پڑھی جائے؟ اس مسئلے میں اختلاف ہے، اگرچہ جواز میں کوئی اختلاف نہیں کہ جس طرح چاہے بیٹھ جائے مگر افضیلت کے بارے میں اختلاف ہے۔ امام ابوحنیفہ، امام مالک، امام احمد رحمہ اللہ علیہم اور ایک قول کے مطابق امام شافعی رحمہ اللہ بھی چارزانو بیٹھ کر نماز پڑھنے کو افضل سمجھتے ہیں کیونکہ اس میں سہولت ہے۔ امام شافعی رحمہ اللہ کا دوسرا قول یہ ہے کہ جس طرح دو سجدوں کے درمیان بیٹھا جاتا ہے اسی طرح بیٹھا جائے کیونکہ نماز میں اس طرح بیٹھنا قطعاً صحیح ہے اور تواتر سے منقول ہے۔ بعض سے تورک بھی منقول ہے۔ مزید دیکھیے: (اصل صفۃ صلاۃ النبی للالبانی:۱؍۱۰۷)"}],[1662,"عبداللہ بن ابی قیس کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: رسول اللہ صلی اللہ علیہ وسلم رات میں کس طرح قرآت کرتے تھے، جہری یا سری؟ تو انہوں نے کہا: آپ ہر طرح سے پڑھتے، کبھی جہراً پڑھتے، اور کبھی سرّاً پڑھتے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ابی قیس سے منقول ہے، فرماتے ہیں: میں نے ام المومنین حضرت عائشہ رضی اللہ عنہا سے پوچھا کہ رات کی نفل نماز میں رسول اللہ صلی اللہ علیہ وسلم کی قراءت کیسے ہوتی تھی؟ بلند آواز سے یا آہستہ؟ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ آپ دونوں طرح قراءت فرمایا کرتے تھے، کبھی بلند آواز سے کبھی آہستہ۔"}],[1663,"عقبہ بن عامر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو جہر سے قرآن پڑھتا ہے وہ اس شخص کی طرح ہے جو اعلان کر کے صدقہ کرتا ہے، اور جو آہستہ قرآن پڑھتا ہے وہ اس شخص کی طرح ہے جو چھپا کر چپکے سے صدقہ کرتا ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ صرف نفلی نماز ہے، ورنہ مغرب، عشاء، فجر اور جمعہ کی نماز میں جہر کرنا واجب ہے، جس طرح فرض و نفل صدقہ کا معاملہ ہے۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ اپنے شاگردوں کو بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص بلند آواز سے قرآن پڑھتا ہے، وہ اس شخص کی طرح ہے جو اعلانیہ صدقہ کرتا ہے اور جو شخص آہستہ قرآن پڑھتا ہے وہ اس شخص کی طرح ہے جو چھپا کر صدقہ کرتا ہے۔‘‘","f2":"ظاہراً حدیث سے معلوم ہوتا ہے کہ قرآن مجید آہستہ پڑھنا افضل ہے کیونکہ چھپا کر صدقہ کرنا قطعاً افضل ہے۔ (وان تخفوھا وتوتوھا الفقراء فھوا خیرلکم) (البقرہ۲:۲۷۱) مگر رسول اللہ صلی اللہ علیہ وسلم نے حضرت ابوبکر رضی اللہ عنہ کو تہجد میں آہستہ قراءت کرتے ہوئے دیکھا تو حکم دیا تھا کہ ’’کچھ اونچا پڑھا کرو۔‘‘ اور حضرت عمر رضی اللہ عنہ کو بہت اونچا پڑھتے ہوئے سنا تو فرمایا تھا: ’’کچھ آہستہ پڑھا کرو۔‘‘ نیز اللہ تعالیٰ نے نبی اکرم صلی اللہ علیہ وسلم کو نماز میں قراءت کے متعلق فرمایا: (ولاتجہر بصلاتک ولا تخافت بھا وابتغ بین ذلک سبیلا) (بنی اسرائیل۱۷: ۱۱۰) ’’اپنی نماز کی قراءت سے نہ تو بہت (بلند) آواز سے کریں اور نہ بالکل آہستہ، بلکہ ان دونوں کے مابین کی راہ اختیار کریں۔‘‘ اس سے معلوم ہوتا ہے کہ درمیانی آواز سے پڑھنا افضل ہے اور یہی بات درست ہے۔ باب والی حدیث میں بلند آواز سے مراد بہت زیادہ بلند آواز ہوگی جس میں ریاکاری کا بھی احتمال ہے اور وہ دوسرے نمازیوں، آرام کرنے والوں اور مریضوں کے لیے بھی تکلیف و تشویش کا باعث ہوگی یا جب جہر میں ریاکا خطرہ ہو تو اس وقت آہستہ افضل ہے۔"}],[1664,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم کے ساتھ ایک رات نماز پڑھی تو آپ نے سورۃ البقرہ شروع کر دی، میں نے اپنے جی میں کہا کہ آپ سو آیت پر رکوع کریں گے لیکن آپ بڑھ گئے تو میں نے اپنے جی میں کہا کہ آپ دو سو آیت پر رکوع کریں گے لیکن آپ اس سے بھی آگے بڑھ گئے، تو میں نے اپنے جی میں کہا: آپ ایک ہی رکعت میں پوری سورۃ پڑھ ڈالیں گے، لیکن اس سے بھی آگے بڑھ گئے اور سورۃ نساء شروع کر دی، اور اسے پڑھ چکنے کے بعد سورۃ آل عمران شروع کر دی، اور پوری پڑھ ڈالی، آپ نے یہ پوری قرآت آہستہ آہستہ ٹھہر ٹھہر کر کی، اس طرح کہ جب آپ کسی ایسی آیت سے گزرتے جس میں اللہ تعالی کی تسبیح (پاکی) کا ذکر ہوتا تو آپ اس کی پاکی بیان کرتے، اور جب کسی سوال کی آیت سے گزرتے تو اللہ تعالی سے سوال کرتے، اور جب کسی پناہ کی آیت سے گزرتے تو اللہ تعالی کی پناہ مانگتے، پھر آپ نے رکوع کیا، اور « سبحان ربي العظيم» \"پاک ہے میرا رب جو عظیم ہے\" کہا، آپ کا رکوع تقریباً آپ کے قیام کے برابر تھا، پھر آپ نے اپنا سر اٹھایا، اور «سمع اللہ لمن حمده» کہا، آپ کا قیام تقریباً آپ کے رکوع کے برابر تھا، پھر آپ نے سجدہ کیا، اور سجدہ میں «سبحان ربي الأعلى» \"پاک ہے میرا رب جو اعلی ہے\" پڑھ رہے تھے، اور آپ کا سجدہ تقریباً آپ کے رکوع کے برابر تھا۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے ایک رات نبی صلی اللہ علیہ وسلم کے ساتھ (رات کی نفل) نماز پڑھی۔ آپ نے سورۂ بقرہ شروع کی۔ میں نے سوچا کہ آپ سو آیتیں پڑھ کر رکوع فرمائیں گے لیکن آپ آگے بڑھ گئے۔ میں نے سوچا کہ آپ دو سوآیتیں پڑھ کر رکوع فرمائیں گے لیکن آپ آگے گزر گئے۔ میں نے سوچا، پوری سورت ایک رکعت میں پڑھیں گے لیکن آپ پڑھتے گئے اور سورۂ نساء شروع کردی اور پوری پڑھ ڈالی، پھر آل عمران شروع کردی اور ختم کرڈالی۔ پڑھتے بھی ٹھہرٹھہر کر تھے۔ جب کسی ایسی آیت پر آتے جس میں تسبیح کا ذکر ہوتا تو تسبیح پڑھتے اور جب کوئی سوال والی آیت پڑھتے تو رک کر اللہ تعالیٰ سے وہ چیز مانگتے اور جب کوئی ایسی آیت پڑھتے جس میں پناہ والی چیز کا ذکر ہوتا ہے تو اس چیز سے اللہ تعالیٰ کی پناہ طلب کرتے، پھر رکوع فرمایا اور [سبحان اللہ لمن حمدہ] آپ کا یہ قومہ بھی تقریباً رکوع کے برابر تھا، پھر سجدہ فرمایا اور [سبحان ربی الاعلی] پڑھتے رہے تو آپ کا سجدہ آپ کے رکوع کے قریب تھا۔"}],[1665,"حذیفہ رضی اللہ عنہ سے روایت ہے کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ رمضان میں نماز پڑھی، تو آپ صلی اللہ علیہ وسلم نے رکوع کیا، اور یہ اتنا ہی لمبا تھا جتنا آپ کا قیام تھا، آپ نے اپنے رکوع میں «سبحان ربي العظيم» کہا، پھر آپ اتنی ہی دیر بیٹھے جتنی دیر کھڑے تھے، اور «رب اغفر لي رب اغفر لي» کہتے رہے، پھر آپ صلی اللہ علیہ وسلم نے اتنی دیر تک سجدہ کیا جتنی دیر تک آپ کھڑے تھے، اور «سبحان ربي الأعلى» کہتے رہے تو آپ نے صرف چار رکعتیں پڑھیں یہاں تک کہ بلال رضی اللہ عنہ صبح کی نماز کے لیے بلانے آ گئے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ حدیث میرے نزدیک مرسل (منقطع)ہے، میں نہیں جانتا کہ طلحہ بن یزید نے حذیفہ رضی اللہ عنہ سے کچھ سنا ہے، علاء بن مسیب کے علاوہ دوسرے لوگوں نے اس حدیث میں یوں کہا: «عن طلحۃ، عن رجل، عن حذیفۃ»۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے روایت ہے کہ میں نے رمضان المبارک میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (تہجد کی) نماز پڑھی۔ آپ نے رکوع فرمایا اور رکوع میں اتنی دیر [سبحان ربی العظیم] پڑھتے رہے جتنی دیر قیام فرمایا تھا، پھر (سجدے کے بعد) بیٹھے، اتنی دیر [رب اغفرلی! رب اغفرلی] ’’اے میرے رب! مجھے معاف فرما، اے میرے رب! مجھے معاف فرما۔‘‘کہتے رہے، جتنی دیر قیام فرمایا تھا، پھر سجدہ فرمایا تو اتنی دیر [سبحان ربی الاعلیٰ] کہتے رہے، جتنی دیر کھڑے رہے تھے۔ اس طرح آپ نے صرف چار رکعات پڑھیں کہ حضرت بلال رضی اللہ عنہ صبح کی نماز کی اطلاع دینے آگئے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث میرے نزدیک مرسل ہے۔ میں نہیں جانتا کہ طلحہ بن یزید نے حضرت حذیفہ رضی اللہ عنہ سے کوئی روایت سنی ہو۔ علاء بن مسیب کے علاوہ دوسرے راویوں نے طلحہ اور حضرت حذیفہ کے درمیان ایک آدمی کا واسطہ ذکر کیا ہے۔","f2":"(۱)یہاں مرسل سے منقطع مراد ہے۔ اصطلاحی معنی مراد نہیں۔ علم حدیث میں مرسل کے اصطلاحی معنی یہ ہے کہ تابعی براہ راست رسول اللہ صلی اللہ علیہ وسلم کا قول و فعل بیان کرے۔ مذکورہ روایت میں تو وہ براہ راست بیان نہیں کررہے بلکہ صحابی کا ذکر موجود ہے۔ (۲)معلوم ہوا نماز میں دوران قراءت، دعاواستغفار وغیرہ کیا جاسکتا ہے بلکہ کرنا چاہیے، نہ کہ خالی قراءت کرتا رہے۔ جس طرح سجدے کی آیت پڑھ کر سجدہ کرنا مستحب ہے ایسے ہی موقع محل کے لحاظ سے تسبیح، دعا اور تعوذ بھی ہونا چاہیے، نیز ایک ہی آیت یا تسبیح یا دعا کو نماز میں با ربار دہرایا جاسکتا ہے۔ اس کے لیے کسی خصوصی نقل کی ضرورت نہیں ہے۔ نبی صلی اللہ علیہ وسلم نے ایک رات قیام میں صرف ایک آیت (ان تعذبھم فانھم عبادک۔۔۔) پر اکتفا کیا اور اسے ہی بار بار دہراتے رہے۔"}],[1666,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رات اور دن کی نماز دو دو رکعت ہے\" ۱؎۔ ابوعبدالرحمٰن نسائی کہتے ہیں: میرے خیال میں اس حدیث میں غلطی ہوئی ہے ۲؎ واللہ اعلم۔\n§وضاحت\n۱؎: اس حدیث سے معلوم ہوا کہ نوافل دن ہو یا رات دو دو کر کے پڑھنا زیادہ بہتر ہے۔ ۲؎: اس سے ان کی مراد «والنہار» کی زیادتی میں غلطی ہے، کچھ لوگوں نے اس زیادتی کو ضعیف قرار دیا ہے کیونکہ یہ زیادتی علی البارقی الازدی کے طریق سے مروی ہے، اور یہ ابن معین کے نزدیک ضعیف ہیں، لیکن ابن خزیمہ، ابن حبان اور حاکم نے اسے صحیح قرار دیا ہے، اور کہا ہے کہ اس کے رواۃ ثقہ ہیں اور مسلم نے علی البارقی سے حجت پکڑی ہے، اور ثقہ کی زیادتی مقبول ہوتی ہے، علامہ البانی نے بھی سلسلۃ الصحیحۃ میں اس کی تصحیح کی ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’دن اور رات کی (نفل) نماز دو دو رکعت کرکے پڑھنی چاہیے۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں میرے نزدیک یہ حدیث خطا ہے۔ واللہ اعلم۔","f2":"امام نسائی رحمہ اللہ کا عندی خطا کے ساتھ لفظ ’’دن‘‘ کی طرف اشارہ ہے۔ کثیر روایات میں صرف رات کی نماز کا ذکر ہے، نیز بعض علماء کے نزدیک ابن عمر رضی اللہ عنہما کا صرف ایک شاگرد ’’دن اور رات‘‘ دونوں کا ذکر کرتا ہے جس کا نام علی الازدی ہے اور یہ ثقہ ہے، اس لیے یہ کہنا کہ دن کی نماز بھی دورکعت پڑھنا افضل اور مستحب ہے، درست نہیں لیکن اکثر محققین کے نزدیک روایت میں مذکور ’’دن‘‘ کا اضافہ بھی صحیح ہے کیونکہ حدیث کے ابن عمر رضی اللہ عنہما سے دیگر طرق بھی منقول ہیں جن میں مذکورہ اضافے کا ذکر ملتا ہے، نیز کچھ شواہد سے بھی اس کی تائید ہوتی ےہ، اس لیے یہ حدیث لفظ [النھار] کے اضافے کے ساتھ صحیح ہے، اسے امام بخاری، احمد، ابن خزیمہ، ابن حبان، بیہقی اور علامہ خطابی رحم اللہ علیہم نے صحیح قرار دیا ہے، اس لیے امام نسائی رحمہ اللہ کا لفظ نھار کو خطا کہنا محل نظر ہے۔ تفصیل کے لیے ملاحظہ فرمائیے: (صحیح سنن ابی داود (مفصل) للالبانی، رقم الحدیث:۱۱۷۶، و جامع الترمذی بتحقیق الشیخ احمد شاکر:۲؍۴۹۲، حدیث:۵۹۷) بنابریں معلوم ہوا کہ دن کے وقت بھی نفل نماز دو دو کرکے پڑھنا افضل ہے اگرچہ اکٹھی چار پڑھنا بھی جائز ہے۔ یا ان سنن اور نوافل کو چار پڑھنا افضل اور مستحب ہے جو رسول اللہ صلی اللہ علیہ وسلم نے دن کے وقت چار پڑھے ہیں باقی کو دو دو کرکے یا اکٹھے چار پڑھنا بھی جائز ہے۔ واللہ اعلم۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۱۴۔۲۰)"}],[1667,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا، تو آپ نے فرمایا: \"دو دو رکعت ہے، اور جب تمہیں خدشہ ہو تو ایک رکعت پڑھ لو\" ۱؎۔\n§وضاحت\n۱؎: تاکہ سب وتر یعنی طاق ہو جائیں۔","الألباني: صحيح",{"u2":"حضرت طاؤس حضرت ابن عمر رضی اللہ عنہما سے بیان فرماتے ہیں کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کا طریقہ پوچھا تو آپ نے فرمایا: ’’دودو کرکے پڑھتے جاؤ۔ جب تجھے صبح کا خطرہ ہو تو ایک رکعت پڑھ لو۔","f2":"(۱)یہ مشہور روایت ہے جس میں صرف رات کی نماز کا ذکر ہے۔ (۲)’’دودو کرکے‘‘ مگر اس طرح واجب نہیں افضل ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے اکٹھے تین یا اکٹھے پانچ یا اکٹھے سات اور اکٹھے نو وتر (قیام اللیل) کا بھی ذکر ہے۔ دیکھیے: (صحیح مسلم، صلاۃ المسافرین، حدیث:۷۵۲) اور اسے معمول بنایا جاسکتا ہے لیکن تنوع افضل ہے۔ (۴)رسول اللہ صلی اللہ علیہ وسلم کا اکثر و بیشتر معمول گیارہ رکعت ہی تھا۔ اگر وقت کم ہو تو کم بھی پڑھے جاسکتے ہیں کیونکہ کم پڑھنا بھی صحیح احادیث سے ثابت ہے۔"}],[1668,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رات کی نماز دو دو رکعت ہے، اور جب تجھے صبح ہو جانے کا خطرہ لاحق ہو تو ایک رکعت پڑھ کر وتر یعنی طاق کر لو\"۔","الألباني: صحيح",{"u2":"حضرت سالم اپنے والد (ابن عمررضی اللہ عنہما) سے بیان فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دو دو رکعت ہے۔ جب تجھے صبح کے طلوع ہونے کا خطرہ ہو تو (صبح طلوع ہونے سے پہلے) ایک رکعت پڑھ لے۔‘"}],[1669,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو میں نے منبر پر فرماتے سنا: آپ سے رات کی صلاۃ کے بارے میں پوچھا جا رہا تھا تو آپ نے فرمایا: \"وہ دو دو رکعت ہے، لیکن جب تمہیں صبح ہو جانے کا خطرہ لاحق ہو تو ایک رکعت سے وتر کر لو\"۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ حضرت ابن عمر رضی اللہ عنہما سے بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر یہ فرماتے سنا جبکہ آپ سے رات کی نماز کے بارے میں پوچھا گیاتھا۔ (آپ نے فرمایا:) ’’دودوکرکے پڑھو۔ جب صبح کا خطرہ ہوتو ایک رکعت پڑھ لو۔‘‘"}],[1670,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا تو آپ نے فرمایا: \"دو دو رکعت ہے، لیکن اگر تم میں سے کوئی صبح ہو جانے کا خطرہ محسوس کرے، تو ایک رکعت پڑھ کر وتر کر لے\"۔","الألباني: صحيح",{"u2":"حضرت نافع بیان کرتے ہیں کہ حضرت ابن عمر رضی اللہ عنہما نے ہم کو بتایا کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا تو آپ نے فرمایا: ’’دو دو کرکے پڑھی جائے۔ جب کسی کو صبح کے طلوع ہونے کا ڈر ہو تو ایک رکعت پڑھ لے۔‘‘"}],[1671,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"رات کی نماز دو دو رکعت ہے، اور جب تمہیں صبح ہو جانے کا اندیشہ ہو تو ایک رکعت پڑھ کر وتر کر لو\"۔","الألباني: صحيح",{"u2":"حضرت نافع حضرت ابن عمر رضی اللہ عنہما سے بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دودورکعت ہے۔ جب تجھے صبح کا خدشہ ہو تو ایک رکعت پڑھ لے۔‘‘"}],[1672,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ مسلمانوں میں سے ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: رات کی نماز کیسے پڑھی جائے؟ تو آپ نے فرمایا:\"رات کی نماز دو دو رکعت ہے، پس جب تمہیں صبح ہو جانے کا خطرہ ہو تو ایک رکعت پڑھ کر وتر کر لو\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت سالم حضرت ابن عمر رضی اللہ عنہما سے بیان کرتے ہیں کہ مسلمانوں میں سے ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے پوچھا: رات کی نماز کیسے پڑھی جائے؟ تو آپ نے فرمایا: ’’رات کی نماز دو دو رکعت پڑھی جائے۔ جب تجھے صبح کے طلوع کا قرب محسوس ہو تو ایک رکعت پڑھ لے۔‘‘"}],[1673,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"رات کی نماز دو دو رکعت ہے، اور جب تمہیں صبح کا ہو جانے کا خدشہ ہو تو ایک رکعت پڑھ کر وتر کر لو\"۔","الألباني: صحيح",{"u2":"حضرت حمید بن عبدالرحمن بیان کرتے ہیں کہ مجھے حضرت ابن عمر رضی اللہ عنہما نے بتایا کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز (تہجد) کے بارے میں پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دو دورکعت ہے۔ جب تجھے صبح طلوع ہونے کا خطرہ ہو تو ایک رکعت پڑھ لے۔‘‘"}],[1674,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ ایک شخص نے کھڑے ہو کر پوچھا: اللہ کے رسول! رات کی نماز کیسے پڑھی جائے؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"رات کی نماز دو دو رکعت ہے، اور جب تمہیں صبح ہو جانے کا خدشہ ہو تو ایک رکعت پڑھ کر وتر کر لو\"۔","الألباني: صحيح",{"u2":"حضرت سالم اور حمید دونوں نے حضرت ابن عمر رضی اللہ عنہما سے بیان کیا کہ ایک آدمی نے اٹھ کر کہا: اے اللہ کے رسول! رات کی نماز (پڑھنے کا طریقہ) کیا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دو دو کرکے پڑھو۔ جب صبح کا ڈر ہو تو ایک رکعت پڑھ لو۔‘‘","f2":"اتنی کثیر سندوں سے اس مشہور حدیث کے ہوتے ہوئے احناف کا آخر میں ایک رکعت پڑھنے کو جائز نہ سمجھنا، یا بلادلیل منسوخ کہنا دلائل سے انحراف کے مترادف ہے جبکہ اس کے علاوہ بھی کئی روایات میں خود رسول اللہ صلی اللہ علیہ وسلم کا طرزعمل یہی بیان کیا گیا ہے۔ جمہور اہل علم کا یہی مسلک ہے، ہاں! ایک اسلام کے ساتھ، درمیان میں تشہد کیے بغیر، تین اکٹھے پڑھنا بھی جائز ہے خصوصاً جب وہ عشاء کی نماز کے فوراً بعد ہوں تو بہتر ہے کہ تین اکٹھے پڑھے جائیں، البتہ تراویح یا تہجد میں ایک رکعت کو الگ پڑھا جائے، نبی صلی اللہ علیہ وسلم کا عمومی عمل یہی تھا، نیز دونوں قسم کی روایات میں تطبیق کی یہ بھی ایک صورت ہے۔"}],[1675,"علی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے وتر پڑھی، پھر فرمایا: \"اے اہل قرآن! وتر پڑھو ۱؎ کیونکہ اللہ تعالی وتر ہے، اور وتر کو محبوب رکھتا ہے\"۲؎۔\n§وضاحت\n۱؎: اس حدیث میں صحابہ رضی اللہ عنہم کو اہل قرآن کہا گیا ہے، یہ مطلب نہیں کہ وہ حدیث کو نہیں مانتے تھے بلکہ یہاں اہل قرآن کا مطلب شریعت اسلامیہ کے پیروکار ہیں، اور شریعت قرآن و حدیث دونوں کے مجموعہ کا نام ہے نہ کہ حدیث کے بغیر صرف قرآن کا۔ ۲؎: طیبی کہتے ہیں کہ اس حدیث میں وتر سے مراد قیام اللیل ہے، کیونکہ وتر کا اطلاق قیام اللیل پر بھی ہوتا ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے نماز وتر پڑھی، پھر آپ نے فرمایا: ’’اے قرآن والو! وتر پڑھا کرو کیونکہ اللہ تعالیٰ وتر (اکیلا) ہے اور وتر کو پسند فرماتا ہے۔‘‘","f2":"(۱)مذکورہ روایت کو محقق کتاب نے سنداً ضعیف کہا ہے جبکہ دیگر محققین نے اسے شواہد کی بنا پر صحیح قرار دیا ہے اوریہی رائے اقرب الی الصلوۃ معلوم ہوتی ہے کہ مذکورہ روایت شواہد کی بنا پر صحیح ہے۔ تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الامام احمد: ۲ ؍۴۱۳، وصحیح سنن ابی داود (مفصل) للالبانی: ۵؍۱۵۹، رقم الحدیث: ۱۲۷۴، وذخیرۃ العقبٰی شرح سنن النسائی ۱۸؍۲۸۔۳۳) (۲)وتر عربی میں طاق عدد کو کہتے ہیں جو دو پر تقسیم نہ ہو۔ اصطلاح میں رات کی نماز کو کہا جاتا ہے کیونکہ اس کے بارے میں حکم ہے کہ اسے مجموعی طور پر طاق عدد میں پڑھا جائے۔ تین یا پانچ یا سات یا نو یا گیارہ۔ (۳)رات کی نماز فرض نہیں بلکہ نفل ہے، اس لیے وتر فرض ہے نہ واجب بلکہ نفل مؤکد ہے، نیز رسول اللہ صلی اللہ علیہ وسلم سواری پر بھی وتر پڑھ لیا کرتے تھے جبکہ فرائض یا واجبات کی ادائیگی کے لیے نیچے اترجاتے، اس سے بھی معلوم ہوا کہ وتر واجب نہیں۔ باقی رہا حکم تو حکم ہر جگہ وجوب کے لیے نہیں ہوتا۔ بعض جگہ تاکید یا استحباب کے لیے بھی ہوتا ہے بلکہ جواز کے لیے بھی آجاتا ہے، مثلاً: (واذا حللتم فاصطادوا) (المائدہ۵:۲) ’’جب تم احرام کھول لو تو شکار کرو۔‘‘ یعنی شکار کرسکتے ہو۔ کیونکہ کسی فقیہ اور محدث کے نزدیک بھی احرام کے بعد شکار کرنا ضروری بلکہ مستحب بھی نہیں، نیز اسی حدیث کے آخری الفاظ ’’پسند فرمات ہے‘‘ بھی وتر کے استحباب وتاکید پر دلالت کرتے ہیں۔ یہ بحث پیچھے گزر چکی ہے۔ (۴)’’اے قرآن والو!‘‘ مراد مسلمان ہیں کہ ان کی کتاب قرآن ہے۔ یا قرآن کے حفاظ مراد ہیں، یعنی حفاظ کو رات کی نماز پڑھنی چاہیے کیونکہ یہ حفظ قرآن کا حق ہے، ورنہ حفظ کا اور کیا فائدہ ہے؟ نیز اس طرح حفظ قائم رہے گا ورنہ بھول جانے کا خدشہ ہے۔ اس صورت میں وتر سے مراد نماز تہجد ہوگی جو تعداد میں زیادہ اور قراءت میں طویل ہوتی ہے اور یہ حفاظ کے لائق ہے۔ باقی رہے کم از کم وتر تو وہ سب مسلمانوں کے لیے مؤکد ہیں۔ ان کی تعداد تین یا ایک ہے۔ (۵)’’اللہ تعالیٰ وتر (ایک) ہے‘‘ یعنی یکتا ہے جس میں کسی لحاظ سے تجزی، دوئی یا شراکت نہیں، نہ وہ قابل تقسیم ہے، اس لیے رات کی نماز کو زیادہ محبوب رکھتا ہے کیونکہ وہ بھی تو دوئی کو قبول نہیں کرتی۔ (۶)اللہ تعالیٰ کی محبت کو بعض لوگوں نے ثواب کے معنی میں لیا ہے مگر اس تکلف کی کوئی ضرورت نہیں۔ محبت اللہ تعالیٰ کی ایک صفت ہے لیکن اللہ تعالیٰ کی صفات انسانوں یا کسی بھی مخلوق کی صفات جیسی نہیں کہ ان کے مشابہ قرار دیا جاسکے، بلکہ وہ اللہ تعالیٰ کی طرح بے مثال ہیں۔ (۷)وتر پڑھنے والے سے اللہ تعالیٰ خصوصی محبت فرماتا ہے۔"}],[1676,"علی رضی اللہ عنہ کہتے ہیں کہ وتر فرض نماز کی طرح کوئی حتمی و واجبی چیز نہیں ہے، البتہ وہ رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے ۱؎۔\n§وضاحت\n۱؎: یہ روایت اس بات کی دلیل ہے کہ وتر واجب نہیں جیسا کہ جمہور کا مذہب ہے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ فرماتے ہیں کہ وتر کی نماز فرض نماز کی طرح واجب نہیں بلکہ یہ سنت (مؤکدہ) ہے جسے رسول اللہ صلی اللہ علیہ وسلم نے تمھارے لیے جاری فرمایا ہے۔","f2":"چونکہ وتر رسول اللہ صلی اللہ علیہ وسلم کی سنت ہے جسے آپ نے کبھی ترک نہیں کیا، لہٰذا اسے بلاعذر ترک کرنا درست نہیں۔"}],[1677,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میرے خلیل صلی اللہ علیہ وسلم نے مجھے تین باتوں کی وصیت کی ہے: وتر پڑھ کر سونے کی، ہر مہینہ تین دن کے روزے رکھنے کی، اور چاشت کی دونوں رکعتیں پڑھنے کی۔\n§وضاحت\n۱؎: یعنی تیرھویں چودھویں اور پندرھویں تاریخ کو۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ میرے دلی محبوب رسول اللہ صلی اللہ علیہ وسلم نے مجھے تین باتوں کی نصیحت تاکید کے ساتھ کی ہے: میں وتر پڑھ کر سوؤں، ہر مہینے میں تین روزے رکھوں اور فجر (یا ضحیٰ) کی دو رکعتوں کی پابندی کروں۔","f2":"(۱)خلیلی، خلیل وہ ہوتا ہے جس کے ساتھ دلی لگاؤ اور محبت سب سے بڑھ کر ہو۔ صحابۂ کرام رضی اللہ عنہم کو رسول اللہ صلی اللہ علیہ وسلم سے بڑھ کر کس سے محبت ہوسکتی ہے؟ لہٰذا مراد رسول اللہ صلی اللہ علیہ وسلم ہی ہیں۔ نبی اکرم صلی اللہ علیہ وسلم نے اللہ تعالیٰ کے سوا کسی کو خلیل نہیں بنایا مگر اللہ کے رسول کو صحابہ کرام رضی اللہ عنہم تو خلیل بناسکتے ہیں۔ (۲)’’وترپڑھ کر‘‘ کیونکہ ابوہریرہ رضی اللہ عنہ طالب علم تھے۔ طالب علموں کی، شغل علم وغیرہ کی بنا پر، صبح جلدی آنکھ نہیں کھلتی، لہٰذا وہ وتر پڑھ کر سوئیں تاکہ وتر ضائع نہ ہوجائیں، البتہ جو شخص تہجد کا عادی ہے اوراسے فجر سے قبل جاگنے میں کوئی دقت نہیں، اس کے لیے وتر آخر رات ہی میں مناسب ہیں۔"}],[1678,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میرے خلیل صلی اللہ علیہ وسلم نے مجھے تین باتوں کی نصیحت کی: شروع رات میں وتر پڑھنے کی، فجر کی رکعت سنت پڑھنے کی ۱؎، اور ہر مہینہ تین دن کے روزے رکھنے کی۔\n§وضاحت\n۱؎: صحاح کی اکثر روایات میں چاشت کی رکعتیں ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ مجھے میرے دلی محبوب صلی اللہ علیہ وسلم نے تین باتوں کی تاکید فرمائی کہ شروع رات میں وتر پڑھ لیا کروں، فجر کی سنتوں کی پابندی کروں اور ہر مہینے میں تین نفلی روزے رکھوں۔"}],[1679,"قیس بن طلق کہتے ہیں ہمارے والد طلق بن علی رضی اللہ عنہ نے رمضان میں ایک دن ہماری زیارت کی اور ہمارے ساتھ انہوں نے رات گزاری، ہمارے ساتھ اس رات نماز تہجد ادا کی، اور وتر بھی پڑھی، پھر وہ ایک مسجد میں گئے، اور اس مسجد والوں کو انہوں نے نماز پڑھائی یہاں تک کہ وتر باقی رہ گئی، تو انہوں نے ایک شخص کو آگے بڑھایا، اور اس سے کہا: انہیں وتر پڑھاؤ، میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"ایک رات میں دو وتر نہیں\"۔","الألباني: صحيح",{"u2":"حضرت قیس بن طلق سے روایت ہے کہ میرے والد محترم حضرت طلق بن علی رضی اللہ عنہ رمضان المبارک میں ایک دن ہم سے ملنے کے لیے تشریف لائے۔ انھیں شام ہوگئی۔ اس رات انھوں نے ہمیں نماز پڑھائی اور وتر پڑھائے، پھر مسجد تشریف لے گئے اور اپنے دوسرے ساتھیوں کو نماز پڑھائی، حتی کہ جب وتر باقی رہ گئے تو ایک آدمی کو اپنی جگہ آگے کیا اور فرمایا: تم انھیں وتر پڑھا دو (کیونکہ میں پڑھ چکا ہوں۔) میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے کہ ایک رات میں دو دفعہ وتر نہیں پڑھے جاسکتے۔","f2":"جمہور اہل علم کے نزدیک یہی بات صحیح ہے کہ اگر شروع رات میں وتر پڑھ چکا ہو اور دوبارہ موقع مل جائے تو دو دو رکعت پڑھتا رہے، دوبارہ وتر پڑھنے کی ضرورت نہیں، البتہ حضرت عبداللہ بن عمر رضی اللہ عنہما سے حسن سند کے ساتھ منقول ہے کہ اس صورت میں تہجد شروع کرنے سے پہلے ایک رکعت پڑھ کر رات کی طاق نماز کو جفت کرلے، پھر آخر میں ایک رکعت پڑھ لے۔ اس طرح نماز مجموعی طور پر طاق بن جائے گی اور وتر بھی آخر میں ہو جائے گا۔ حضرت عبداللہ بن عمر رضی اللہ عنہما کا اپنا عمل اسی طرح تھا۔ دیکھیے: (مسند احمد:۲؍۱۳۵) یہ ابن عمر رضی اللہ عنہما کی رائے اور ذاتی عمل ہے لیکن اس طرح باب کی حدیث میں ذکر کردہ طریقے سے وتر درمیان میں آجائے گا جبکہ آپ نے وتر رات کی نماز کے آخر میں پڑھنے کا حکم دیا ہے۔ جمہور نے یہ جواب دیا ہے کہ وتر آخر میں پڑھنا مستحب ہے، واجب نہیں کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے وتر کے بعد بھی دو رکعتیں پڑھنا ثابت ہے، نیز اول رات تو وتر آخر ہی میں پڑھا گیا تھا اگر صبح کے وقت پڑھا جاتا تو آخر ہی میں پڑھا جاتا۔ جمہور اہل علم کی بات زیادہ قوی ہے ورنہ وتر تین دفعہ پڑھا جائے گا اور آپ نے تو دودفعہ وتر پڑھنے سے بھی روکا ہے، تین دفعہ کیسے جائز ہوگا؟ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سن النسائی:۱۸؍۳۹۔۴۲)"}],[1680,"اسود بن یزید کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے بارے میں پوچھا، تو انہوں نے کہا: آپ شروع رات میں سو جاتے، پھر اٹھتے اگر سحر (صبح) ہونے کو ہوتی تو وتر پڑھتے، پھر اپنے بستر پر آتے، اور اگر آپ کو خواہش ہوتی تو اپنی بیوی کے پاس آتے، پھر جب اذان سنتے تو جھٹ سے اٹھ کر کھڑے ہو جاتے، اگر جنبی ہوتے تو (اپنے اوپر پانی ڈالتے) یعنی غسل فرماتے، ورنہ وضو کرتے پھر نماز کو چلے جاتے۔","الألباني: صحيح",{"u2":"حضرت اسود بن یزید سے منقول ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی (رات کی) نماز کے متعلق پوچھا تو انھوں نے فرمایا: آپ شروع رات (یعنی نماز عشاء کے بعد) سوجاتے تھے، پھر جاگتے (اور نماز پڑھتے)، پھر صبح قریب ہوتی تو وتر پڑھتے، پھر اپنے بستر پر تشریف لے آتے۔ اگر آپ کو ضرورت محسوس ہوتی تو اپنی بیوی سے جماع کرتے، پھر جب اذان سنتے تو فوراً اٹھ کھڑے ہوتے۔ اگر جنبی ہوتے تو غسل فرماتے وگرنہ وضو کرتے۔ (سنتیں پڑھتے) اور نماز کے لیے مسجد میں چلے جاتے۔"}],[1681,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شروع، اخیر اور بیچ رات سب میں وتر کی نماز پڑھی ہے، اور آخری عمر میں آپ کا وتر سحر(صبح) تک پہنچ گیا تھا ۱؎۔\n§وضاحت\n۱؎: یعنی نبی اکرم صلی اللہ علیہ وسلم آخری عمر میں وتر رات کے آخری حصہ میں پڑھنے لگے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے وتر اول رات میں بھی پڑھے، درمیان رات میں بھی اور آخر رات میں بھی۔ آخری عمر میں آپ کے وتر آخر رات میں (فجر سے پہلے) ہوتے تھے۔"}],[1682,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ جو رات کو نماز پڑھے تو وہ اپنی آخری نماز وتر کو بنائے، اس لیے کہ رسول اللہ صلی اللہ علیہ وسلم اسی کا حکم دیتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما بیان کرتے ہیں کہ جو شخص رات کو نفل نماز پڑھے تو وہ وتر آخر میں پڑھے کیونکہ رسول اللہ صلی اللہ علیہ وسلم اس کا حکم دیتے تھے۔","f2":"ان روایات سے معلوم ہوا کہ وتر عشاء کی نماز کے بعد طلوع فجر تک پڑھے جاسکتے ہیں، البتہ جسے تراویح وتہجد پڑھنی ہو تو وہ وتر کو اپنی نفل نماز کے آخر میں پڑھے، ابتدا یا درمیان میں نہ پڑھے۔ واللہ اعلم۔"}],[1683,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے وتر کے بارے میں پوچھا گیا، تو آپ نے فرمایا: \"وتر صبح ہونے (فجر نکلنے) سے پہلے پڑھو\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے وتر کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’صبح سے پہلے وتر پڑھ لو۔‘‘"}],[1684,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وتر فجر نکلنے سے پہلے پڑھ لو\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید خدری رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’فجرطلوع ہونے سے پہلے وتر پڑھ لیا کرو۔‘‘"}],[1685,"محمد بن منتشر کہتے ہیں کہ وہ عمرو بن شرحبیل کی مسجد میں تھے، کہ اتنے میں اقامت ہو گئی، تو لوگ ان کا انتظار کرنے لگے، وہ آئے اور کہا: میں وتر پڑھ رہا تھا، اور کہا: عبداللہ بن مسعود رضی اللہ عنہم سے پوچھا گیا: کیا اذان کے بعد وتر ہے، تو کہا: ہاں، اور اقامت کے بعد بھی ہے، اور انہوں نے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نماز سے سوئے رہ گئے یہاں تک کہ سورج نکل آیا، پھر آپ نے (اٹھ کر) نماز پڑھی۔","الألباني: صحيح الإسناد",{"u2":"حضرت محمد بن منتشر سے مروی ہے کہ میں حضرت عمروبن شرحبیل کی مسجد میں تھا، نماز کی تکبیر ہوگئی (مگر وہ نہ آئے۔) لوگ ان کا انتظار کرنے لگے، پھر وہ آئے تو انھوں نے کہا: میں وتر پڑھ رہا تھا، نیز انھوں نے کہا: حضرت عبداللہ بن مسعود رضی اللہ عنہ سے پوچھا گیا: کیا صبح کی اذان کے بعد وتر پڑھے جاسکتے ہیں؟ انھوں نے فرمایا: ہاں، بلکہ اقامت کے بعد بھی، پھر انھوں نے نبی صلی اللہ علیہ وسلم کا واقعہ بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم کی نماز فجر سوتے میں رہ گئی تھی حتی کہ سورج طلوع ہوگیا تو آپ نے اس وقت نماز پڑھی۔","f2":"(۱)حضرت ابن مسعود رضی اللہ عنہ کا مقصد یہ ہے کہ فوت شدہ نماز وقت کے بعد بھی پڑھی جائے گی۔ اسی طرح وتر رہ جائیں تو وہ بھی پڑھے جائیں گے، وقت کوئی بھی ہو۔ یہی بات درست ہے۔ رسول اللہ صلی اللہ علیہ وسلم کی دیگر احادیث س بھی،جو وتر سے متعلق ہیں، اس کی تائید ہوتی ہے۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جو اپنے وتر سے سویا رہ گیا (اور نہ پڑھ سکا) یا اسے بھول گیا تو جب بھی یاد آئے (یا جاگ آئے) پڑھ لے۔‘‘ (سنن ابی داود، الوتر، حدیث: ۱۴۳۱) اس سے وتر کے وجوب اور فرضیت پر استدلال نہیں ہوسکے گا کیونکہ جیسے فرائض و واجبات کی ادائیگی ہوتی ہے ایسے ہی نوافل اور ہر مؤکد عمل کی بھی ہوسکتی ہے، جیسے رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی سنتوں کی قضا عص کے بعد ادا کی۔ صبح کی سنتیں سورج طلوع ہونے کے بعد پڑھیں۔ ظاہر ہے ظہر اور فجر کی سنتیں واجب نہیں مؤکد ہی ہیں۔ اسی طرح وتر باوجود واجب نہ ہونے کے اس کی قضا دی جاسکتی ہے۔ (۲)بعض علماء کی رائے یہ ہے کہ جس کے وتر رہ جائیں تووہ سورج نکلنے کے بعد اس کی قضا جفت کی شکل میں دے، یعنی ایک وتر کی جگہ دو رکعت، تین وتر کی جگہ چار رکعات پڑھے لیکن ہمارے خیال میں ایسا اس شخص کے لیے ضروری ہوگا جو قیام اللیل (نمازتہجد) کا عادی ہو، عام شخص کے لیے وتروں کی قضا، وتر ہی کی شکل میں مناسب معلوم ہوتی ہے۔ واللہ اعلم۔"}],[1686,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سواری پر وتر پڑھ لیتے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم سواری پر وتر پڑھ لیا کرتے تھے۔","f2":"سواری پر قیام، رکوع اور سجدہ اصل طریقے پر نہیں ہوتے، لہٰذا فرض نماز سواری پر پڑھنے کی اجازت الایہ کہ کوئی شرعی عذر ہو، مگر نفل نماز میں وسعت ہے، وہ سواری پر پڑھی جاسکتی ہے۔ وتر بھی نفل ہیں، لہٰذا سواری پر پڑھے جاسکتے ہیں۔"}],[1687,"نافع سے روایت ہے کہ ابن عمر رضی اللہ عنہم اپنے اونٹ پر وتر پڑھتے تھے، اور ذکر کرتے تھے کہ نبی اکرم صلی اللہ علیہ وسلم ایسا ہی کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت نافع سے روایت ہے کہ حضرت ابن عمر رضی اللہ عنہما اپنے اونٹ پر وتر پڑھ لیا کرتے تھے اور وہ بیان فرماتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم بھی ایسے کیا کرتے تھے۔"}],[1688,"سعید بن یسار کہتے ہیں کہ ابن عمر رضی اللہ عنہم نے مجھ سے کہا کہ رسول اللہ صلی اللہ علیہ وسلم اونٹ پر وتر پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت سعید بن یسار نے کہا کہ مجھے حضرت ابن عمر رضی اللہ عنہما نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم اونٹ پر وتر پڑھ لیا کرتے تھے۔","f2":"احناف وتر کو واجب سمجھتے ہیں، لہٰذا اسے سواری پر پڑھنے کے قائل نہیں مگر یہ صحیح اور صریح احادیث کی مکمل مخالفت ہے۔"}],[1689,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وتر رات کے آخری حصہ میں ایک رکعت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وتر آخر رات میں ایک رکعت ہے۔‘‘"}],[1690,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وتر رات کے آخری حصہ میں ایک رکعت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وتر آخر رات میں ایک رکعت پڑھا جائے۔‘‘"}],[1691,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ دیہات والوں میں سے ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا: تو آپ نے فرمایا: \"دو دو رکعت ہے، اور وتر رات کے آخری حصہ میں ایک رکعت ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے کہ ایک بدوی شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا تو آپ نے فرمایا: ’’دو دورکعت کرکے پڑھتے جاؤ اور آخر رات میں ایک رکعت وتر پڑھ لو۔‘‘","f2":"(۱)اصل وتر ایک رکعت ہے مگر اس سے پہلے کچھ نہ کچھ نوافل پڑھنے چاہییں یہ ایک رکعت ان سب کو وتر (طاق) بنادے گی۔ باب کی پہلی دو روایات مجمل ہیں۔ تیسری روایت ان کا مطلب واضح کرتی ہے کہ بہتر یہ ہے کہ ایک رکعت پڑھنے سے پہلے کم از کم دو رکعت ضرور پڑھے۔ اگر صرف ایک رکعت ہی پر اکتفا کرتا ہے تو یہ بھی جائز ہے کیونکہ صحیح احادیث سے یہ بھی ثابت ہے۔ (۲)احناف نے وتر کو تین رکعت ہی مقرر کرلیا ہے۔ نہ کم، نہ زیادہ مگر اس کی کوئی دلیل نہیں بلکہ یہ تحدید صریح روایات کے خلاف ہے، پھر ان کے نزدیک چونکہ یہ واجب ہے، لہٰذا تین رکعات ایک ہی سلام سے ہوں گی، حالانکہ صریح روایات ایک رکعت الگ پڑھنے کو جائز بلکہ مستحب قرار دیتی ہے۔ یہ بحث پیچھے گزر چکی ہے۔"}],[1692,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رات کی نماز دو دو رکعت ہے، پھر جب تم ختم کرنے کا ارادہ کرو تو ایک رکعت اور پڑھ لو، یہ جو تم نے پڑھی ہے سب کو (طاق) کر دے گی\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دو دو رکعت کرکے پڑھو۔ جب تمھارا ارادہ نماز ختم کرنے کا ہو تو ایک رکعت پڑھ لو۔ یہ رکعت تمھاری پڑھی ہوئی پوری نماز کو وتر بنادے گی۔‘‘"}],[1693,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رات کی نماز دو دو رکعت ہے، اور وتر ایک رکعت ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دودورکعت ہے۔ اور وتر (آخر میں) ایک رکعت ہے۔‘‘"}],[1694,"عبداللہ بن عمر رضی اللہ عنہم سے روایت ہے کہ ایک شخص نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز (تہجد) کے بارے میں پوچھا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"رات کی نماز (تہجد) دو دو رکعت ہے، اور تم میں سے کسی کو جب صبح ہو جانے کا خدشہ ہو تو وہ ایک رکعت اور پڑھ لے یہ جو اس نے پڑھی ہے سب کو وتر(طاق) کر دے گی\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے منقول ہے کہ ایک آدمی نے رسول اللہ صلی اللہ علیہ وسلم سے رات کی نماز کے بارے میں پوچھا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رات کی نماز دودورکعت ہے۔ جب تم میں سے کسی کو صبح کے طلوع ہونے کا خدشہ ہو تو ایک رکعت پڑھ لے۔ یہ اس کی ساری نماز کو وتر بنادے گی۔‘‘"}],[1695,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ انہوں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا: \"رات کی نماز (تہجد) دو دو رکعت ہے، تو جب تمہیں صبح ہو جانے کا ڈر ہو تو ایک رکعت پڑھ کر اسے وتر کر لو\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے منقول ہے کہ میں نے نبی صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے: ’’رات کی نماز دودورکعت ہے۔ جب تمھیں طلوع صبح کا خطرہ ہو تو ایک رکعت وتر پڑھ لو۔‘‘"}],[1696,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رات کو گیارہ رکعت پڑھتے تھے، ان میں سے ایک رکعت وتر کی ہوتی تھی، پھر اپنے دائیں پہلو پر لیٹ جاتے تھے۔","الألباني: صحيح ق لكن ذكر الاضطجاع بعد الوتر شاذ والمحفوظ بعد سنة الفجر",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم رات کو گیارہ رکعات پڑھتے تھے۔ ان میں سے ایک رکعت الگ وتر پڑھتے، پھر اپنے دائیں پہلو پر لیٹ جاتے۔","f2":"مذکورہ اور آئندہ آنے والی روایات سے صاف معلوم ہوتا ہے کہ رات کی نماز ہی کو وتر کہا جاتا ہے، وہ جتنی بھی ہو۔ جب آخر میں ایک رکعت پڑھی جائے گی تو ساری نماز ہی وتر (طاق) بن جائے گی۔"}],[1697,"ابوسلمہ بن عبدالرحمٰن سے روایت ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے پوچھا: رمضان میں رسول اللہ صلی اللہ علیہ وسلم کی نماز کیسی ہوتی تھی؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم رمضان میں اور غیر رمضان میں کسی میں گیارہ رکعت سے زیادہ نہیں پڑھتے تھے، آپ چار رکعت پڑھتے تو ان کا حسن اور ان کی طوالت نہ پوچھو ۱؎، پھر چار رکعت پڑھتے تو تم ان کا (بھی) حسن اور ان کی طوالت نہ پوچھو، پھر تین رکعت پڑھتے۔ عائشہ رضی اللہ عنہا کہتی ہیں: میں نے عرض کیا: اللہ کے رسول! کیا آپ وتر پڑھنے سے پہلے سوتے ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"عائشہ! میری آنکھیں سوتی ہیں، لیکن میرا دل نہیں سوتا\" ۲؎۔\n§وضاحت\n۱؎: یہاں نہی مقصود نہیں بلکہ مقصود نماز کی تعریف کرنا ہے۔ ۲؎: یعنی میرا دل اللہ تعالی کی طرف متوجہ رہتا ہے، اس وجہ سے سونے سے مجھے کوئی ضرر نہیں پہنچتا، میرا وضو اس سے نہیں ٹوٹتا، واضح رہے کہ یہ بات آپ کی خصوصیات میں سے تھی۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ بن عبدالرحمن سے منقول ہے، انھوں نے ام المومنین حضرت عائشہ رضی اللہ عنہا سے پوچھا کہ رمضان المبارک میں رسول اللہ صلی اللہ علیہ وسلم کی (رات کی) نماز کیسے ہوتی تھی؟ تو انھوں نے فرمایا: آپ رمضان یا غیررمضان میں (عموماً) گیارہ رکعات سے زائد نہیں پڑھتے تھے۔ چار رکعات پڑھتے ایسی خوب صورت اور طویل کہ کچھ نہ پوچھ، پھر چار پڑھتے ایسی خوب صورت اور طویل کہ کچھ نہ پوچھ، پھر تین رکعات پڑھتے۔ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں میں نے عرض کیا: اے اللہ کے رسول! کیا آپ وتر (تین رکعات) پڑھنے سے پہلے سوجاتے ہیں؟ آپ نے فرمایا: ’’اے عائشہ! میری آنکھیں سوتی ہیں، دل نہیں سوتا۔‘‘","f2":"(۱)ظاہر الفاظ سے معلوم ہوتا ہے کہ رسول اللہ صلی اللہ علیہ وسلم چار رکعات ایک سلام سے پڑھتے تھے، پھر چار ایک سلام سے، پھر تین ایک سلام سے۔ یہ طریقہ بھی درست ہے، اسی لیے مصنف رحمہ اللہ نے تین وتر کا باب باندھا ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم سے نماز تہجد کے متعلق مختلف طریقے منقول ہیں۔ صحیح احادیث کی روشنی میں ان میں سے کوئی سا طریقہ بھی اختیار کیا جاسکتا ہے۔ افضل یہ ہے کہ عمل میں تنوع ہو، کبھی یہ، کبھی وہ، اصل اتباع سنت یہی ہے۔ عموماً رسول اللہ صلی اللہ علیہ وسلم سے نماز تہجد گیارہ رکعات، دودوکرکے اور آخر میں وتر ایک رکعت کی صورت میں منقول ہے، اور یہ طریقہ افضل ہے۔ لیکن کبھی آپ صلی اللہ علیہ وسلم نے نو رکعات اکٹھی اور بعد میں دورکعات، کبھی سات اور کبھی تیرہ رکعات، آٹھ دو دو کرکے اور پانچ وتر اکٹھے بھی پڑھے ہیں، لہٰذا دودورکعات والی عام روایات کی روشنی میں ان میں تاویل کی گنجائش نہیں۔ اسی طرح چار چار رکعات نماز تہجد میں بھی کوئی حرج نہیں، نہ یہ ممنوع ہیں بلکہ مذکورہ بالاحدیث اس کی مشروعیت کے لیے کافی ہے۔ بعض کا یہ کہنا کہ چار چار س اکٹھی چار چار مراد نہیں بلکہ دیگر احادیث کی روشنی میں دودورکعات ہی مراد ہیں لیکن یہ موقف محل نظر ہے کیونکہ جب احادیث میں ایک ہی نہیں بلکہ کچھ اور طریقے بھی منقول ہیں تو انہیں تسلیم کرنے سے اس طریقے کو بھی ماننے یا عمل میں لانے میں کون سی چیز مانع ہے؟ نمازتہجد کے متعددطریقوں کے لیے دیکھیے: (صلاۃ التراویح، للالبانی، ص:۸۶۔۹۳) (۲)’’زائد نہیں پڑھتے تھے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم کا عام معمول گیارہ رکعات ہی تھا۔ گیارہ سے کم بھی پڑھی جاسکتی ہیں کیونکہ کم پڑھنا بھی صحیح احادیث سے ثابت ہے۔ (۳)’’دل نہیں سوتا‘‘ اور یہ تمام انبیاء و رسل علیہم السلام کی خصوصیت ہے۔ یہی وجہ ہے کہ انبیاء علیہم السلام کے خواب سچے اور وحی ہوتے ہیں۔ رسول اللہ صلی اللہ علیہ وسلم کا دل حالت نیند میں بھی چونکہ بیدار ہوتا تھا، اس لیے آپ کو حدث (بے وضو ہونا) وغیرہ کا پتا چل جاتا تھا۔ گویا نیند صرف خروج ریح کے خطرے کی بنا پر ناقض وضو ہے۔"}],[1698,"عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی دو رکعتوں کے بعد سلام نہیں پھیرتے تھے ۱؎۔\n§وضاحت\n۱؎: یعنی تینوں رکعتیں پڑھ کر سلام پھیرتے تھے۔","الألباني: شاذ",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی دو رکعتوں کے بعد سلام نہیں پھیرتے تھے۔","f2":"مذکورہ روایت سنداً ضعیف ہے، نیز شیخ البانی رحمہ اللہ نے اسے شاذ قرار دیا ہے جبکہ علامہ ایتوبی رحمہ اللہ (شارح سنن نسائی) نے امام محمد بن نصر رحمہ اللہ سے درج ذیل مطلب نقل کرکے اس کی تحسین کی ہے۔ وہ فرماتے ہیں: اس کا مطلب یہ ہے کہ آپ دورکعتوں کے بعد سلام نہیں پھیرتے بلکہ سات یا نورکعات کے بعد سلام نہیں پھیرتے تھے، تین رکعات کے بعد پھیرتے تھے، یہ ثابت نہیں بلکہ اس کے خلاف ثابت ہے۔ شارح نسائی علامہ ایتوبی رحمہ اللہ نے امام محمد بن نصر مروزی سے یہ مطلب نقل کرکے اس کی تحسین کی ہے۔ دیکھیے: (ذخیرۃ العقبٰی، شرح سنن النسائی: ۱۸؍۶۳، ۶۴، وارواء الغلیل، رقم:۴۲۱)"}],[1699,"ابی بن کعب رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم وتر تین رکعت پڑھتے تھے، پہلی رکعت میں «سبح اسم ربك الأعلى» دوسری رکعت میں«قل يا أيها الكافرون» اور تیسری میں «قل هو اللہ أحد» پڑھتے، اور دعائے قنوت رکوع سے پہلے پڑھتے، پھر جب (وتر سے) فارغ ہو جاتے تو فراغت کے وقت تین بار: «سبحان الملك القدوس» کہتے، اور ان کے آخر میں کھینچتے۔","الألباني: صحيح",{"u2":"حضرت ابی بن کعب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم تین رکعات وتر پڑھتے۔ پہلی رکعت میں سورہ (سبح اسم ربک الاعلی) دوسری میں (قل یایھا الکفرون) اور تیسری میں (قل ہوا للہ احد) پڑھتے تھے۔ اور رکوع سے پہلے قنوت پڑھتے تھے، پھر جب فارغ ہوتے تو فراغت کے وقت تین دفعہ (سبحان الملک القدوس) ’’پاک ہے بادشاہ نہایت‘‘ پڑھتے۔ آخری مرتبہ لمبا کرکے پڑھتے تھے۔"}],[1700,"ابی بن کعب رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم وتر کی پہلی رکعت میں «سبح اسم ربك الأعلى» دوسری رکعت میں «قل يا أيها الكافرون» اور تیسری میں «قل هو اللہ أحد» پڑھتے۔","الألباني: صحيح",{"u2":"حضرت ابی بن کعب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی پہلی رکعت میں (سبح اسم ربک الاعلی) دوسری میں (قل یایھا الکفرون) اور تیسری میں (قل ہواللہ احد) پڑھتے تھے۔"}],[1701,"ابی بن کعب رضی اللہ عنہ کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم وتر میں (پہلی رکعت میں) «سبح اسم ربك الأعلى» دوسری رکعت میں «قل يا أيها الكافرون» اور تیسری میں «قل هو اللہ أحد» پڑھتے، اور ان کے بالکل آخر ہی میں سلام پھیرتے، اور تین بار: «سبحان الملك القدوس» کہتے(یعنی سلام پھیرنے کے بعد)۔","الألباني: صحيح",{"u2":"حضرت ابی بن کعب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر (کی پہلی رکعت) میں (سبح اسم ربک الاعلی) دوسری میں (قل یایھا الکفرون) اور تیسری میں (قل ہواللہ احد) پڑھا کرتے تھے اور سلام آخر ہی میں پھیرتے تھے۔ اور سلام کے بعد تین دفعہ (سبحان الملک القدوس) پڑھتے۔","f2":"(۱)مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر صحیح روایات سے حدیث میں مذکور مفہوم کی تائید ہوتی ہے، نیز دیگر محققین نے اس روایت کو صحیح بھی قرار دیا ہے۔ بنابریں مذکورہ روایت سنداً ضعیف اور معناً صحیح اور قابل عمل ہے۔ دیکھیے: (صحیح سنن النسائی، رقم: ۱۷۰۰، وذخیرۃ العقبیٰ شرح سنن النسائی:۱۸؍۷۲) (۲)وتر پڑھنے کا ایک طریقہ یہ بھی ہے کہ تین وتر ایک سلام سے پڑھے جائیں۔ (مزید دیکھیے، حدیث:۱۶۹۹)"}],[1702,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم تین رکعت وتر پڑھتے، پہلی میں «سبح اسم ربك الأعلى» دوسری میں «قل يا أيها الكافرون» اور تیسری میں «قل هو اللہ أحد» پڑھتے۔ زہیر نے اسے موقوفاً روایت کیا ہے، (ان کی روایت اس کے بعد آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تین وتر پڑھتے تھے۔ پہلی رکعت میں (سبح اسم ربک الاعلی) دوسری میں (قل یایھا الکفرون) اور تیسری میں (قل ھواللہ احد) پڑھتے تھے۔\nزہیر (بن معاویہ) نے اسے موقوف بیان کیا ہے۔"}],[1703,"عبداللہ بن عباس رضی اللہ عنہم سے روایت ہے کہ وہ وتر کی تینوں رکعتوں میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت سعید بن جبیر سے روایت ہے کہ حضرت ابن عباس رضی اللہ عنہما تین وتر پڑھا کرتے تھے اور ان میں (سبح اسم ربک الاعلی)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھتے تھے۔","f2":"دونوں میں اختلاف یہ ہے کہ پہلی روایت میں تین وتر اللہ کے رسول صلی اللہ علیہ وسلم کا فعل بتلایا گیا ہے اور دوسری حدیث میں ابن عباس رضی اللہ عنہما کا اپنا فعل۔ اختلاف سے مصنف رحمہ اللہ کی مراد یہی ہے۔ واللہ اعلم۔"}],[1704,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم رات کو اٹھے اور مسواک کی، پھر دو رکعت نماز پڑھی، پھر سو گئے، (دوبارہ) آپ پھر اٹھے، اور مسواک کی، پھر وضو کیا، اور دو رکعت نماز پڑھی یہاں تک کہ آپ نے چھ رکعتیں پڑھیں، پھر تین رکعتیں وتر کی اور دو رکعتیں (فجر کی) پڑھیں۔","الألباني: صحيح",{"u2":"محمد بن علی اپنے باپ علی سے اور وہ اپنے دادا حضرت عبداللہ بن عباس رضی اللہ عنہما سے بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم رات کو (تہجد کے لیے) اٹھے اور مسواک کی، پھر (وضو کے بعد) دورکعتیں پڑھیں، پھر سوگئے، پھر اٹھے، مسواک کی، وضو فرمایا اور دورکعتیں پڑھیں، حتی کہ (اس طرح) چھ رکعتیں پڑھیں، پھر تین وتر پڑھے اور پھر دورکعتیں پڑھیں۔"}],[1705,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ میں نبی اکرم صلی اللہ علیہ وسلم کے پاس تھا، آپ نیند سے بیدار ہوئے، آپ نے وضو کیا، مسواک کی، آپ یہ آیت پڑھ رہے تھے: «إن في خلق السموات والأرض واختلاف الليل والنهار لآيات لأولي الألباب» \"آسمانوں اور زمین کی پیدائش میں اور رات دن کے ہیر پھیر میں یقیناً عقل مندوں کے لیے نشانیاں ہیں\" (آل عمران: ۱۹۰) یہاں تک کہ آپ اس سے فارغ ہوئے، پھر آپ نے دو رکعتیں پڑھیں، پھر آپ واپس آئے، اور سو گئے یہاں تک کہ میں نے آپ کے خراٹے کی آواز سنی، پھر آپ اٹھے، اور وضو کیا، مسواک کی، پھر دو رکعت نماز پڑھی، اور تین رکعت وتر پڑھی۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما بیان کرتے ہیں کہ میں (ایک رات) نبی صلی اللہ علیہ وسلم کے ہاں ٹھہرا ہوا تھا۔ آپ اٹھے، وضو کیا اور مسواک فرمائی اور آپ یہ آیت پڑھ رہے تھے: (ان فی خلق السموت والارض واختلف الیل والنھار لایت لاولی البب) ’’یقیناً آسمانوں اور زمین کی تخلیق اور رات اور دن کے ادل بدل میں عقل مند لوگوں کے لیے نشانیاں ہیں۔‘‘ حتی کہ آپ ان آیات سے فارغ ہوئے، پھر آپ نے دورکعتیں پڑھیں، پھر دوبارہ سوگئے، حتی کہ میں نے آپ کے خراٹے سنے، پھر اٹھے اور مسواک ووضو فرمایا، پھر دو رکعتیں پڑھیں، پھر سوگئے، پھر اٹھے۔ وضو کیا، مسواک فرمائی اور دورکعتیں پڑھیں، پھر تین وتر پڑھے۔"}],[1706,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم بیدار ہوئے تو آپ نے مسواک کی، پھر راوی نے پوری حدیث بیان کی۔","الألباني: سكت عنه الشيخ",{"u2":"محمد بن علی حضرت ابن عباس رضی اللہ عنہما سے بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جاگے اور مسواک کی، پھر راوی نے پوری حدیث بیان کی۔","f2":"اس روایت میں محمد بن علی اپنے باپ کے واسطے کے بغیر ابن عباس رضی اللہ عنہما سے بیان کرتے ہیں جبکہ پہلی روایات میں واسطہ تھا اور اختلاف حبیب بن ابی ثابت کے شاگردوں میں ہے۔"}],[1707,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو آٹھ رکعتیں پڑھتے، اور تین رکعت وتر پڑھتے، اور دو رکعت فجر کی نماز سے پہلے پڑھتے۔ عمرو بن مرہ نے حبیب کی مخالفت کی ہے، انہوں نے اسے یحیی بن الجزار سے اور یحیی جزار نے ام سلمہ رضی اللہ عنہا سے، اور ام سلمہ رضی اللہ عنہا نے رسول صلی اللہ علیہ وسلم سے روایت کی ہے، (یعنی اس کو مسند ابن عباس رضی اللہ عنہم کے بجائے مسند ام سلمہ رضی اللہ عنہا میں سے قرار دیا ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم رات کو آٹھ رکعتیں پڑھتے اور تین وتر پڑھتے، پھر فجر کی نماز سے پہلے (فجر کی سنتیں) دو رکعت پڑھتے۔\nعمرو بن مرہ نے حبیب بن ابی ثابت کی مخالفت کی ہے اور عن یحیی بن الحزار عن ام سلمۃ رضی اللہ عنہا کہا ہے۔ (جبکہ حبیب بن ابی ثابت نے عن ام سلمۃ کے بجائے عن ابن عباس کہا تھا۔)"}],[1708,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تیرہ رکعت وتر پڑھتے تھے، پھر جب آپ بوڑھے اور کمزور ہو گئے تو آپ نو رکعت وتر پڑھنے لگے۔ عمارہ بن عمیر نے عمرو کی مخالفت کی ہے، انہوں نے اسے یحیی بن جزار سے اور یحیی بن جزار نے عائشہ رضی اللہ عنہا سے روایت کی ہے۔ (یعنی عمارہ بن عمیر نے اس کو مسند ام سلمہ کی بجائے مسند عائشہ رضی اللہ عنہا میں سے قرار دیا ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو تیرہ رکعت پڑھتے تھے، پھر جب آپ بوڑھے اور کمزور ہوگئے تو نو پڑھنے لگے۔\nعمارہ بن عمیر نے (عمرو بن مرہ کی) مخالفت کی ہے اور یہ روایت عن یحییٰ بن الحزار عن عائشۃ کی سند سے بیان کی ہے۔ (جبکہ عمرو بن مرہ نے عن عائشۃ کے بجائے عن ام سلمہ کہا تھا۔)"}],[1709,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو نو رکعتیں پڑھتے تھے، جب آپ بوڑھے اور (گوشت چڑھ جانے کی وجہ سے) بھاری بھر کم ہو گئے تو (صرف) سات رکعتیں پڑھنے لگے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو نو رکعت پڑھتے تھے۔ جب آپ بوڑھے اور بوجھل ہوگئے تو سات پڑھنے لگے۔","f2":"(۱)رسول اللہ صلی اللہ علیہ وسلم کا اکثر معمول گیارہ کا تھا۔ جن روایات میں تیر ہ رکعات کا ذکر ہے ان میں عشاء یا فجر کی دو سنتیں یا قیام اللیل سے قبل کی افتتاحی دورکعتیں شامل ہیں۔ جب آپ کچھ بوڑھے ہوئے تو نو شروع کردیں۔ مزید بوڑھے ہوئے تو سات پڑھنے لگے۔ اس طرح کوئی اختلاف نہیں۔ (۲)ان تینوں روایتوں (۱۷۰۸، ۱۷۰۹ اور ۱۷۱۰) کا راوی ایک ہے یحییٰ بن حزار ان کے کسی شاگرد نے ابن عباس رضی اللہ عنہما ذکر کیا، کسی نے ام سلمہ کا اور کسی نے عائشہ کا۔ یہ اختلاف بتانا مقصود ہے۔"}],[1710,"دوید بن نافع نے زہری سے، اور زہری نے عطاء بن یزید سے اور عطاء بن یزید نے ابوایوب رضی اللہ عنہ سے روایت کی ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا:\"وتر حق ہے، جو چاہے سات رکعت پڑھے، جو چاہے پانچ پڑھے، جو چاہے تین پڑھے، اور جو چاہے ایک پڑھے\"۔","الألباني: صحيح",{"u2":"حضرت ابوایوب رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وتر حق ہے جو چاہے سات پڑھ لے، جو چاہے پانچ پڑھ لے، جو چاہے تین پڑھ لے اور جو چاہے ایک پڑھ لے۔‘‘"}],[1711,"اوزاعی نے زہری سے اور زہری نے عطاء بن یزید سے اور عطاء نے ابوایوب رضی اللہ عنہ سے روایت کی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وتر حق ہے، جو چاہے پانچ پڑھے، جو چاہے تین پڑھے اور جو چاہے ایک پڑھے\"۔","الألباني: صحيح",{"u2":"حضرت ابوایوب رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وتر حق ہے جو شخص پانچ پڑھنا چاہے، پانچ پڑھ لے، جو تین پڑھنا چاہے تین پڑھ لے اور جو ایک پڑھنا چاہے ایک پڑھ لے۔‘‘"}],[1712,"ابومعید نے زہری سے اور زہری نے عطاء بن یزید سے روایت کی ہے کہ انہوں نے ابوایوب انصاری رضی اللہ عنہ کو کہتے سنا: وتر حق ہے، جو پانچ رکعت پڑھنا چاہے وہ پانچ پڑھے، جو تین پڑھنا چاہے وہ تین پڑھے، اور جو ایک پڑھنا چاہے ایک پڑھے۔","الألباني: صحيح",{"u2":"حضرت ابوایوب رضی اللہ عنہ بیان کرتے ہیں کہ وتر حق ہے۔ جو شخص پانچ پڑھنا چاہے، پانچ پڑھ لے، جو تین پڑھنا چاہے تین پڑھ لے اور جو ایک پڑھنا چاہے ایک پڑھ لے۔"}],[1713,"سفیان زھری سے روایت کرتے ہیں، اور زہری عطاء بن یزید سے، اور عطاء ابوایوب سے، ابوایوب رضی اللہ عنہ کہتے ہیں جو چاہے وتر سات رکعت پڑھے، جو چاہے پانچ پڑھے، جو چاہے تین پڑھے، اور جو چاہے ایک پڑھے، اور جو اشارے سے پڑھنا چاہے اشارے سے پڑھے (یعنی بیمار آدمی)۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوایوب رضی اللہ عنہ فرماتے ہیں کہ جو شخص چاہے سات وتر پڑھ لے، جو شخص چاہے پانچ وتر پڑھ لے، جو شخص چاہے تین وتر پڑھ لے ور جو شخص چاہے ایک وتر پڑھ لے۔ اور جو شخص چاہے (یعنی مجبور ہو) وہ اشارے سے پڑھ لے۔","f2":"(۱)اختلاف یہ ہے کہ پہلی دو روایات میں مذکورہ الفاظ نبی صلی اللہ علیہ وسلم کی طرف منسوب ہیں اور آخری دو روایات میں حضرت ابوایوب رضی اللہ عنہ کی طرف۔ حضرت ابوایوب انصاری رضی اللہ عنہ نے اسے نبی اکرم صلی اللہ علیہ وسلم سے روایت کیا اور پھر سائلین کو حدیث کے مطابق فتویٰ دیا، لہٰذا ان میں کوئی تعارض نہیں۔ اس طرح حدیث موقوفاً اور مرفوعاً دونوں طرح صحیح ہے۔ (۲)’’وتر حق ہے‘‘ احناف اس لفظ سے وتر کے وجوب پر استدلال کرتے ہیں جبکہ حق کے معنی مؤکد بھی ہوتے ہیں اور یہاں یہی معنی مناسب ہیں تاک دوسری احادیث کے خلاف نہ پڑیں جو پیچھے گزر چکی ہیں، نیز لطیفہ یہ ہے کہ اسی روایت میں وتر کے ایک ہونے کا بھی صریح جواز ہے مگر احناف اس کے قائل نہیں۔ متحمل الفاظ سے استدلال اور صریح الفاظ سے اعراض حق پسندی نہیں۔ (۳)’’اشارے سے پڑھ لے‘‘ ایک نسخے میں [من شاء] کے بجائے [من غلب] کے لفظ ہیں، یعنی جو قیام و قعود سے مغلوب ہو، وہ اشارے سے پڑھ لے۔ جمہور علماء اسےمریض پر محمول کرتے ہیں کہ جو کھڑا ہونے اور بیٹھنے کی طاقت نہ رکھت ہو۔ واللہ اعلم۔ مزید دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۸۶)"}],[1714,"منصور روایت کرتے ہیں حکم سے، اور وہ مقسم سے اور مقسم ام المؤمنین ام سلمہ رضی اللہ عنہا سے وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم پانچ یا سات رکعت وتر پڑھتے، اور ان کے درمیان آپ سلام کے ذریعہ فصل نہیں کرتے تھے اور نہ کلام کے ذریعہ۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم پانچ یا سات وتر پڑھتے تو درمیان میں نہ سلام پھیرتے تھے اور نہ کلام فرماتے تھے۔"}],[1715,"منصور حکم سے روایت کرتے ہیں، اور وہ مقسم سے اور مقسم ابن عباس رضی اللہ عنہم سے اور ابن عباس رضی اللہ عنہم ام سلمہ رضی اللہ عنہا سے وہ کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سات یا پانچ رکعت وتر پڑھتے تھے، اور ان کے درمیان سلام کے ذریعہ فصل نہیں کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے منقول ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم سات یا پانچ وتر پڑھتے تو درمیان میں سلام نہیں پھیرتے تھے"}],[1716,"سفیان بن الحسین حکم سے روایت کرتے ہیں، اور وہ مقسم سے، مقسم کہتے ہیں کہ وتر سات رکعت ہے اور پانچ سے کم نہیں، میں نے یہ بات ابراہیم سے ذکر کی، تو انہوں نے کہا: انہوں نے اسے کس کے واسطہ سے ذکر کیا ہے؟ تو میں نے کہا: مجھے نہیں معلوم، حکم کہتے ہیں: پھر میں حج کو گیا تو میں نے مقسم سے ملاقات کی، اور ان سے پوچھا کہ یہ بات آپ نے کس سے سنی ہے؟ تو انہوں نے کہا: ایک ثقہ شخص سے ۱؎، اور اس نے عائشہ رضی اللہ عنہا اور میمونہ رضی اللہ عنہا سے سنی ہے۔\n§وضاحت\n۱؎: غالباً ثقہ شخص سے مراد ابن عباس رضی اللہ عنہم ہیں کیونکہ مقسم برابر انہیں سے چمٹے رہتے تھے، اور انہوں نے ولاء کی نسبت بھی انہیں کی طرف کی ہے، یا عن عائشہ وعن میمونہ \"عن الثقۃ \" سے بدل ہے ایسی صورت میں ترجمہ ہو گا ثقہ سے سنی ہے یعنی عائشہ اور میمونہ سے سنی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت حکم حضرت مقسم سے روایت کرتے ہیں، انھوں نے کہا: وتر سات ہیں اور پانچ کم تو قطعاً نہیں۔ میں نے یہ بات حضرت ابراہیم نخعی سے ذکر کی تو انھوں نے کہا: مقسم نے یہ بات کس سے نقل کی ہے؟ میں نے کہا: مجھے تو علم نہیں۔ حکم کہتے ہیں: میں حج کے لیے گیا تو مقسم سے ملا اور ان سے پوچھا کہ وہ روایت آپ کس سے بیان کرتے ہیں؟ وہ کہنے لگے: ثقہ اور معتبر اشخاص سے۔ حضرت عائشہ اور حضرت میمونہ رضی اللہ عنہما سے۔","f2":"حضرت مقسم نے دراسل حضرت عائشہ اور حضرت میمونہ رضی اللہ عنہما کی روایات سے یہ مسئلہ استنباط کیا ہے نہ کہ ان سے صراحتاً منقول ہے۔ حضر ت عائشہ رضی اللہ عنہا کی روایات تین اور ایک وتر کی پیچھے گزر چکی ہیں، نیز یہ کسی بھی فقیہ یا محدث کا مسلک نہیں۔ علاوہ ازیں یہ روایت سنداً ضعیف بھی ہے۔ مزید دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۸۸۔۹۱)"}],[1717,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم پانچ رکعت وتر پڑھتے تھے، اور ان کے آخر ہی میں بیٹھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم بوڑھے اور فربہ ہوگئے تو آپ سات وتر پڑھتے تھے۔ آخری کے سوا کسی رکعت میں (تشہد کے لیے) نہ بیٹھتے تھے۔","f2":"باب کی روایات سے معلوم ہوا کہ اگر پانچ رکعت وتر اکٹھے پڑھے جائیں تو آخری رکعت کے سوا کسی میں تشہد کے لیے نہ بیٹھے۔"}],[1718,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم بوڑھے ہو گئے، اور بدن پر گوشت چڑھ گیا، تو آپ سات رکعت پڑھنے لگے، اور صرف ان کے آخر میں قعدہ کرتے تھے، پھر سلام پھیرنے کے بعد بیٹھ کر دو رکعت اور پڑھتے تو میرے بیٹے یہ نو رکعتیں ہوئیں، اور رسول اللہ صلی اللہ علیہ وسلم جب کوئی صلاۃ پڑھتے تو چاہتے کہ اس پر مداومت کریں، (یہ حدیث مختصر ہے)۔ ہشام دستوائی نے شعبہ کی مخالفت کی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم بوڑھے اور فربہ ہوگئے تو آپ سات وتر پڑھتے تھے۔ آخری کے سوا کسی رکعت میں (تشہد کے لیے) نہ بیٹھتے تھے۔ اور سلام پھیرنے کے بعد بیٹھ کر وہ رکعات پڑھتے تھے۔ تو یہ نو رکعات ہوگئیں اے بیٹا! اور رسول اللہ صلی اللہ علیہ وسلم جب کوئی نفل نماز شروع کرلیتے تھے تو اس پر ہمیشگی کو پسند فرماتے تھے۔ یہ روایت مختصر ہے۔\nہشام دستوائی نے اس روایت میں شعبہ کی مخالفت کی ہے۔","f2":"متن میں مخالفت مراد ہے۔ شعبہ کی روایت (نمبر۱۷۱۹) میں سات وتر کی ادائیگی کے وقت صرف آخری رکعت میں بیٹھنے کا ذکر ہے جبکہ ہشام دستوائی نے چھٹی رکعت میں بھی بیٹھنے کا ذکر کیا ہے۔ تطبیق نیچے فائدے میں ہے۔"}],[1719,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب نو رکعت وتر پڑھتے تو صرف آٹھویں رکعت میں قعدہ کرتے، اللہ کی حمد کرتے، اس کا ذکر کرتے اور دعا کرتے، پھر کھڑے ہو جاتے، اور سلام نہیں پھیرتے، پھر نویں رکعت پڑھتے، پھر بیٹھتے تو اللہ عزوجل کا ذکر کرتے، دعا کرتے، پھر ایک سلام پھیرتے جو ہمیں سناتے، پھر بیٹھ کر دو رکعت پڑھتے، پھر جب آپ بوڑھے اور کمزور ہو گئے تو سات رکعت وتر پڑھنے لگے، صرف چھٹی میں قعدہ کرتے، پھر بغیر سلام پھیرے کھڑے ہو جاتے، اور ساتویں رکعت پڑھتے، پھر ایک سلام پھیرتے، پھر بیٹھے بیٹھے دو رکعت پڑھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب نو رکعت وتر پڑھتے تو (تشہد کے لیے) آٹھویں رکعت سے پہلے کسی رکعت میں نہ بیٹھتے تھے۔ آٹھویں میں بیٹھ کر اللہ تعالیٰ کی حمدا ور س کا ذکر فرماتے اور دعائیں کرتے (یعنی تشہد پڑھتے) پھر سلام پھیرے بغیر اٹھ کھڑے ہوتے، پھر نویں رکعت پڑھ کر بیٹھتے اور اللہ تعالیٰ کا ذکر فرماتے اور دعائیں کرتے، پھر اتنی آواز سے سلام پھیرتے کہ ہمیں سنائی دیتا تھا، پھر بیٹھ کر دو رکعات پڑھتے، پھر جب بوڑھے اور کمزور ہوگئے تو سات رکعات پڑھتے تھے اور چھٹی کے سوا کسی رکعت میں (تشہد کے لیے) نہ بیٹھتے پھر (چھٹی میں بیٹھ کر) اٹھ کھڑے ہوتے اور سلام نہ پھیرتے، پھر ساتویں پڑھ کر بیٹھتے، پھر سلام پھیرتے، پھر بیٹھ کر دو رکعت پڑھتے۔","f2":"(۱)معلوم ہوا سات وتر پڑھنے کے دو طریقے ہیں۔ ہر رکعت کے بعد بغیر بیٹھے کھڑا ہوتا رہے، صرف ساتویں میں بیٹھے یا چھٹی اور ساتویں دونوں میں بیٹھے مگر سلام ساتویں ہی پر پھیرے۔ دونوں طریقے جائز ہیں اور یہی ان دو روایتوں میں تطبیق ہے کہ کبھی رسول اللہ صلی اللہ علیہ وسلم پہلا طریقہ اختیار فرماتے، کبھی دوسرا۔ (۲)وتر کے بعد دو رکعت کا مسئلہ دیکھیے حدیث نمبر: ۱۶۵۲ اور اس کا فائدہ۔"}],[1720,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے مسواک اور وضو کا پانی تیار کر کے رکھ دیا کرتے تھے، پھر جب اللہ تعالی کو جگانا منظور ہوتا تورات میں آپ کو جگا دیتا، آپ مسواک کرتے (پھر) وضو کرتے اور نو رکعتیں پڑھتے، ان میں صرف آٹھویں رکعت پر بیٹھتے، اور اللہ کی حمد کرتے، اور اس کے نبی کریم صلی اللہ علیہ وسلم پر نماز (درود و رحمت) بھیجتے، اور ان کے درمیان دعائیں کرتے، اور کوئی سلام نہ پھیرتے، پھر نویں رکعات پڑھتے اور قعدہ کرتے، راوی نے اس طرح کی کوئی بات ذکر کی کہ آپ اللہ کی حمد کرتے، اس کے نبی کریم صلی اللہ علیہ وسلم پر نماز (درود و رحمت) بھیجتے، اور دعا کرتے، پھر سلام پھیرتے جسے ہمیں سناتے، پھر بیٹھے بیٹھے دو رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے لیے آپ کی مسواک اور وضو کا پانی تیار رکھتے تھے، پھر جب اللہ تعالیٰ پسند فرماتا، رات میں آپ کو اٹھا دیتا۔ آپ (اٹھ کر) مسواک اور وضو فرماتے اور نو رکعات اس طرح پڑھتے کہ ان میں سے کسی کے آخر میں نہ بیٹھتے مگر آٹھویں رکعت پر بیٹھتے۔ اللہ کی حمد کرتے اور نبی صلی اللہ علیہ وسلم پر درود پڑھتے اور دعائیں رکتے مگر سلام نہ پھیرتے، پھر نویں (رکعت) پڑھ کر بیٹھتے اور اللہ کی حمدوثنا فرماتے اور نبی صلی اللہ علیہ وسلم پر درود پڑھتے اور دعائیں کرتے پھر اتنی آواز سے سلام کہتے کہ ہمیں سنائی دیتا، پھر بیٹھ کر دو رکعتیں پڑھتے۔","f2":"اس میں پہلے تشہد میں بھی درودشریف پڑھنے کا ذکر ہے، یہ اگرچہ نفلی نماز کا واقعہ ہے لیکن اسے فرضوں میں بھی پڑھا جاسکتا ہے بلکہ مستحب ہے جیسا کہ پہلے بھی اس کی تفصیل گزر چکی ہے۔"}],[1721,"سعد بن ہشام بن عامر کہتے ہیں کہ وہ ابن عباس رضی اللہ عنہم کے پاس آئے، اور ان سے رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں سوال کیا، تو انہوں نے کہا: کیا میں تمہیں اس ہستی کو نہ بتاؤں یا اس ہستی کی خبر نہ دوں جو رسول اللہ صلی اللہ علیہ وسلم کے وتر کو زمین والوں میں سب سے زیادہ جانتی ہے؟ میں نے پوچھا: وہ کون ہے؟ انہوں نے کہا: وہ ام المؤمنین عائشہ رضی اللہ عنہا ہیں، تو ہم ان کے پاس آئے، اور ہم نے انہیں سلام کیا، اور ہم اندر گئے، اور اس بارے میں میں نے ان سے پوچھا، میں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے وتر کے بارے میں بتائیے تو انہوں نے کہا: ہم آپ کے لیے آپ کی مسواک اور آپ کے وضو کا پانی تیار کر کے رکھ دیتے، پھر رات کو جب اللہ تعالی کو جگانا منظور ہوتا آپ کو جگا دیتا، آپ مسواک کرتے اور وضو کرتے، پھر نو رکعتیں پڑھتے، سوائے آٹھویں کے ان میں سے کسی میں قعدہ نہیں کرتے، اللہ کی حمد کرتے اس کا ذکر کرتے، اور دعا مانگتے، پھر بغیر سلام پھیرے کھڑے ہو جاتے، پھر نویں رکعت پڑھتے، پھر بیٹھتے تو اللہ کی حمد اور اس کا ذکر کرتے اور دعا کرتے، پھر سلام پھیرتے جسے آپ ہمیں سناتے، پھر بیٹھے بیٹھے دو رکعتیں پڑھتے، میرے بیٹے! اس طرح یہ گیارہ رکعتیں ہوتی تھیں، لیکن جب آپ بوڑھے ہو گئے اور آپ کے جسم پر گوشت چڑھ گیا تو آپ وتر سات رکعت پڑھنے لگے، پھر سلام پھیرنے کے بعد بیٹھے بیٹھے دو رکعتیں پڑھتے، اس طرح میرے بیٹے! یہ کل نو رکعتیں ہوتی تھیں، اور رسول اللہ صلی اللہ علیہ وسلم جب کوئی نماز پڑھتے تو چاہتے کہ اس پر مداومت کریں۔","الألباني: صحيح",{"u2":"حضرت زرارہ بن ادنیٰ سے منقول ہے، فرماتے ہیں: جب حضرت سعد بن ہشام بن عامر ہمارے پاس آئے تو انھوں نے ہمیں بتایا: میں حضرت عبداللہ بن عباس رضی اللہ عنہما کے پاس گیا اور ان سے رسول اللہ صلی اللہ علیہ وسلم کی وتر نماز کے بارے میں پوچھا۔ وہ فرمانے لگے: کیا میں تمھیں ایسی شخصیت نہ بتاؤں جو رسول اللہ صلی اللہ علیہ وسلم کی وتر نماز کو روئے ارض پر بسنے والے تمام لوگوں سے زیادہ جانتی ہیں؟ میں نے کہا: کون؟ فرمایا: حضرت عائشہ رضی اللہ عنہا (کیونکہ وہ آپ کی بیوی تھیں اور آپ کی خلوت کی ساتھی تھیں۔) ہم وہاں گئے، انھیں سلام کہا، ان (حضرت عائشہ رضی اللہ عنہا) کی خدمت میں حاضر ہوئے اور ان سے سوال کیا۔ میں نے کہا: ہمیں رسول اللہ صلی اللہ علیہ وسلم کی وتر کی نماز کے بارے میں بتائیے۔ فرمانے لگیں: ہم نبی صلی اللہ علیہ وسلم کے لیے آپ کی مسواک اور وضو کا پانی تیار رکھتے تھے۔ رات کو جس وقت اللہ تعالیٰ چاہتا، آپ کو جگا دیتا۔ آپ مسواک اور وضو فرماتے، پھر نو رکعتیں اس طرح پڑھتے کہ آٹھویں رکعت کے علاوہ کسی رکعت میں تشہد کے لیے نہ بیٹھتے۔ (آٹھویں رکعت میں بیٹھ کر) اللہ تعالیٰ کی حمدوذکر فرماتے اور دعائیں پڑھتے، پھر بغیر سلام کے اٹھ کھڑے ہوتے اور نویں رکعت پڑھ کر بیٹھتے اور اللہ تعالیٰ کی حمدوذکر فرماتے اور دعائیں پڑھتے، پھر اتنی آواز سے سلام پھیرتے کہ ہمیں سنائی دیتا، پھر بیٹھ کر دو رکعت پڑھتے۔ تو یہ گیارہ رکعات ہوگئیں، اے بیٹے! پھر جب رسول اللہ صلی اللہ علیہ وسلم بوڑھے ہوگئے اور آپ کو گوشت نے پکڑ لیا (آپ فربہ ہوگئے) تو سات رکعات پڑھ کر سلام پھیرتے اور بیٹھ کر دو رکعات پڑھتے۔ تو اے بیٹا! یہ نو ہوگئیں۔ اور نبی صلی اللہ علیہ وسلم جب کوئی نماز شروع فرمالیتے تو اس پر ہمیشگی اور پابندی کو پسند فرماتے تھے۔","f2":"(۱)معلوم ہوا نو رکعت وتر اکٹھے پڑھنے کا ایک ہی طریقہ ہے کہ تشہد صرف آٹھویں میں بیٹھے، پھر اٹھ کر نویں رکعت پڑھے، پھر بیٹھ کر سلام پھیردے۔ (۲)پچھلی حدیث میں آٹھویں رکعت والے تشہد میں درود کا بھی ذکر ہے۔ گویا نفل نماز میں درمیانی تشہد میں بھی درود پڑھا جاسکتا ہے اور فرضوں میں بھی۔ تفصیل پیچھے گزر چکی ہے۔"}],[1722,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نو رکعت وتر پڑھتے تھے، پھر دو رکعت بیٹھ کر پڑھتے، تو جب آپ کمزور ہو گئے تو سات رکعت وتر پڑھنے لگے، پھر دو رکعت بیٹھ کر پڑھتے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ہشام سے روایت ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا کو فرماتے سنا: تحقیق رسول اللہ صلی اللہ علیہ وسلم نو رکعات وتر پڑھ کر، پھر بیٹھے بیٹھے دو رکعت پڑھتے۔ اور جب کمزور ہوگئے تو سات رکعات وتر پڑھتے، پھر بیٹھے بیٹھے دورکعت پڑھتے۔"}],[1723,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نو رکعت وتر پڑھتے تھے، اور دو رکعت بیٹھ کر پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، فرماتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نو رکعات وتر پڑھتے، پھر بیٹھ کر دو رکعات پڑھتے۔"}],[1724,"سعد بن ہشام سے روایت ہے کہ وہ ام المؤمنین عائشہ رضی اللہ عنہا کے پاس آئے، اور انہوں نے ان سے رسول اللہ صلی اللہ علیہ وسلم کی نماز کے متعلق پوچھا، تو انہوں نے بتایا: آپ رات کو آٹھ رکعتیں پڑھتے، اور نویں رکعت کے ذریعہ اسے وتر کر لیتے، پھر آپ بیٹھ کر دو رکعت پڑھتے۔","الألباني: صحيح",{"u2":"حضرت سعد بن ہشام سے منقول ہے کہ میں ام المومنین حضرت عائشہ رضی اللہ عنہا کے پاس گیا اور ان سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں پوچھا تو انھوں نے فرمایا: آپ رات کو آٹھ رکعات پڑھتے، پھر نویں رکعت وتر پڑھتے اور بیٹھ کر دو رکعتیں پڑھتے۔ یہ روایت مختصر ہے۔"}],[1725,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو نو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات کو (نفل نماز) نو رکعت پڑھا کرتے تھے۔"}],[1726,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم رات کو گیارہ رکعت پڑھتے، اور آپ ایک کے ذریعہ اسے وتر کر لیتے، پھر آپ اپنے داہنے پہلو پر لیٹ جاتے۔","الألباني: صحيح لكن ذكر الاضطجاع بعد الوتر شاذ",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم رات کو گیارہ رکعت پڑھتے تھے اور ان میں سے ایک رکعت (الگ) وتر پڑھتے، پھر اپنے دائیں پہلو پر لیٹ جاتے۔","f2":"(۱)گیارہ وتر (نماز تہجد مع وتر) پڑھنے کا طریقہ یہ ہے کہ دو دو کرکے پڑھتے جائیں۔ آخر میں ایک رکعت پڑھ لیں۔ سب وتر بن جائے گی۔ (۲)’’پھر اپنے دائیں پہلو پر لیٹ جاتے۔‘‘ شیخ البانی رحمہ اللہ اس کی بابت لکھتے ہیں کہ وتر کے بعد لیٹنے کا ذکر شاذ ہے۔ صحیح بات یہ ہے کہ یہ لیٹنا فجر کی دو سنتوں کے بعد تھا۔ صحیح روایات سے یہی ثابت ہے۔ (جس کی تفصیل حدیث:۱۷۶۳ کے فوائد میں دیکھی جاسکتی ہے۔) اس لیٹنے کی بابت اہل علم میں اختلاف ہے۔ اہل علم کی ایک جماعت نے فجر کی دو سنتوں کے بعد اس کو جائز اور درست قرار دیا ہے جبکہ بعض اہل علم اس کو درست نہیں سمجھتے اور اس کی مختلف تاویلیں کرتے ہیں۔ دلائل کی رو سے اقرب الی الصواب یہی رائے معلوم ہوتی ہے کہ سنتوں کے بعد لیٹنا مستحب اور افضل ہے کیونکہ اس کے متعلق رسول اللہ صلی اللہ علیہ وسلم کا حکم بھی ہے اور آپ کا اپنا ذاتی عمل بھی۔ صحیحین میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی دو رکعت پڑھ کر اپنے دائیں پہلو پر لیٹا کرتے تھے۔ (صحیح البخاری، الاذان، حدیث:۲۲۶، وصحیح مسلم، صلاۃ المسافرین، حدیث:۷۳۶) نیز صحیح احادیث میں رسول اللہ صلی اللہ علیہ وسلم کا ارشاد گرامی ہے: [اذا صلی احدکم الرکعتین قبل الصبح فلیضطحع علی بمینہ] ’’جب تم سے کوئی شخص نماز صبح سے پہلے دو رکعت (سنت) پڑھ لے تو اپنے دائیں پہلو پر لیٹ جائے۔‘‘ (سنن ابی داود، النطوع، حدیث:۱۲۶۱) بعض اہل علم کہتے ہیں: اگر کوئی شخص گھر میں سنتیں پڑھےتو لیٹ جائے۔ اگر مسجد میں پڑھے تو نہ لیٹے۔ یہ بات محل نظر ہے۔ اس مسئلے کے بارے میں فضیۃ الشیخ صفی الرحمن مبارکپوری رحمہ اللہ صحیح مسلم کی شرح منۃ المنعم میں رقمطراز ہیں کہ فجر کی سنتوں کے بعد رسول اللہ صلی اللہ علیہ وسلم کا دائیں پہلو پر لیٹنا اس کے مستحب ہونے کی دلیل ہے۔سنتیں گھر میں پڑھی جائیں یا مسجد میں، اس سے کوئی فرق نہیںپڑتا۔ آگے فرماتے ہیں: فجر کی سنتوں کے بعد دائیں پہلو پر لیٹنے کا حکم مطلق ہے، جہاں سنتیں پڑھے، گھر میں ہو یا مسجد میں، وہیں لیٹے کیونکہ اس (حکم اضطحاع) کے مطلق ہونے کی وجہ سے گھر اور مسجدہر دو جگہ میں لیٹنا مستحب ہے۔ دیکھیے: (منۃ المنعم فی شرح صحیح مسلم، صلاۃ المسافرین:۱؍۴۶۴، شرح حدیث: (۱۲۲)۔۷۳۴)"}],[1727,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تیرہ رکعت وتر پڑھتے تھے، پھر جب آپ بوڑھے اور ضعیف ہو گئے تو نو رکعت پڑھنے لگے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ام سلمہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم تیرہ رکعت وتر پڑھتے تھے۔ جب بوڑھے اور کمزور ہوگئے تو نو رکعات وتر پڑھنے لگے۔","f2":"قوائد کے لیے دیکھیے‘حدیث نمبر 1709 اور 1710"}],[1728,"ابومجلز سے روایت ہے کہ ابوموسی اشعری مکہ اور مدینے کے درمیان تھے، کہ انہوں نے عشاء کی نماز دو رکعت پڑھی، پھر وہ کھڑے ہوئے اور انہوں نے ایک رکعت وتر پڑھی، اس میں انہوں نے سورۃ نساء کی سو آیتیں پڑھیں، پھر کہا: میں نے اپنے دونوں قدموں کو اس جگہ رکھنے میں جہاں رسول اللہ صلی اللہ علیہ وسلم نے رکھے تھے، اور ان آیتوں کے پڑھنے میں جنہیں رسول اللہ صلی اللہ علیہ وسلم نے پڑھی تھی کوئی کوتاہی نہیں کی۔","الألباني: صحيح",{"u2":"حضرت ابومجلز سے منقول ہے کہ حضرت ابوموسیٰ اشعری رضی اللہ عنہ (سفر کے دورن میں) مکہ اور مدینہ کے درمیان تھے تو انھوں نے عشاء کی نماز دو رکعت پڑھی، پھر کھڑے ہوئے اور ایک رکعت وتر پڑھا اور اس میں سورۂ نسا کی سو آیات پڑھیں، پھر فرمایا: میں نے اس بات میں ذرہ بھر کوتاہی نہیں کی کہ وہاں پاؤں رکھوں جہاں رسول اللہ صلی اللہ علیہ وسلم نے اپنے قدم مبارک رکھے اور وہی کچھ پڑھوں جو رسول اللہ صلی اللہ علیہ وسلم نے پڑھا۔","f2":"مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے اسے صحیح قرار دیا ہے۔ محققین کی تفصیلی بحث سے تصحیح حدیث والی رائے ہی اقرب الی الصواب معلوم ہوتی ہے۔ واللہ اعلم۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۹۸۔۱۰۰)"}],[1729,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» اور «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے، پھر جب آپ سلام پھیرتے تو تین بار «سبحان الملك القدوس» کہتے۔","الألباني: صحيح",{"u2":"حضرت ابی بن کعب رضی اللہ عنہ سے روایت ہے، فرمایا: رسول اللہ صلی اللہ علیہ وسلم وتر کی نماز میں (سبح اسم ربک الاعلی)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے اور جب سلام پھیرتے تھے تو تین دفعہ [سبحان الملک القدوس] پڑھتے۔"}],[1730,"ابی بن کعب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» اور «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے۔ ان دونوں کی یعنی زبید اور طلحہ کی حصین نے مخالفت کی ہے، انہوں نے اسے ذر سے، ذر نے ابن عبدالرحمٰن بن ابزی سے انہوں نے اپنے والد عبدالرحمٰن بن ابزی رضی اللہ عنہ سے اور انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے۔","الألباني: صحيح",{"u2":"حضرت ابی بن کعب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتروں میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) (سورتیں) پڑھا کرتے تھے۔\nحصین نے زبید اور طلحہ کی مخالفت کی ہے اور اس روایت کو [عن ذر عن ابن عبدالرحمن بن ابزی عن ابیہ عن النبی صلی اللہ علیہ وسلم] کی سند سے بیان کیا ہے۔","f2":"مخالفت سند میں ہے اور وہ اس طرح کہ حصین نے سند میں حضرت ابی بن کعب کا ذکر نہیں کیا جبکہ زبید اور طلحہ نے ان کا ذکر کیا ہے، یعنی زبید اور طلحہ اسے حضرت ابی بن کعب کی سند سے بناتے ہیں جبکہ حصین عبدالرحمن بن ابزیٰ کی۔ لیکن یہ کوئی تعارض نہیں، ممکن ہے عبدالرحمن بن ابزیٰ رضی اللہ عنہ نے پہلے ابی بن کعب رضی اللہ عنہ کے واسطے سے حدیث لی ہو، پھر براہ راست رسوکل اللہ صلی اللہ علیہ وسلم سے بھی سن لی ہو، اور دونوں طریقوں سے بیان کردی، غرض اس قسم کے ظاہری اخلاف سے صحت حدیث متاثر نہیں ہوتی۔"}],[1731,"عبدالرحمٰن بن ابزی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» اور «قل يا أيها الكافرون» اور«قل هو اللہ أحد» پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے۔"}],[1732,"عبدالرحمٰن بن ابزی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» اور «قل يا أيها الكافرون» اور«قل هو اللہ أحد» پڑھتے تھے، اور جب سلام پھیرتے تھے، تو «سبحان الملك القدوس» تین بار کہتے، اور تیسری بار اپنی آواز بلند کرتے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھاالکفرون) اور (قل ھواللہ احد) (سورتیں) پڑھا کرتے تھے اور جب سلام پھیرتے تو تین دفعہ [سبحان الملک القدوس] کہتے اور تیسری دفعہ اپنی آواز کو مزید اونچا کردیتے تھے۔","f2":"ویسے تو تینوں دفعہ اونچی آواز سے پڑھتے تھے تبھی تو صحابہ کو پتا چلتا تھا کہ تین دفعہ پڑھا ہے مگر تیسری دفعہ اپنی صدائے حیات بخش کو مزید اونچا اور لمبا فرما دیتے تھے۔ (دیکھیے حدیث نمبر:۱۷۰۰، ۱۷۵۱)"}],[1733,"عبدالرحمٰن بن ابزی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» اور «قل يا أيها الكافرون» اور«قل هو اللہ أحد» پڑھتے تھے، اور جب سلام پھیرتے، تو «سبحان الملك القدوس» کہتے، اور تیسری بار «سبحان الملك القدوس» کہتے وقت اپنی آواز بلند کرتے تھے۔ منصور نے اسے سلمہ بن کہیل سے روایت کیا ہے، اور اس میں انہوں نے ذر کا ذکر نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتروں میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے، پھر جب سلام پھیرتے تو (تین دفعہ) [سبحان الملک القدوس] فرماتے اور تیسری دفعہ [سبحان الملک القدوس] مزید بلند آواز سے ادا فرماتے۔ اس روایت کو منصور نے سلمہ بن کہیل سے بیان کیا ہے اور (راویٔ حدیث) ذر کا ذکر نہیں کیا۔"}],[1734,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور جب سلام پھیر کر فارغ ہو جاتے تو تین بار «سبحان الملك القدوس» کہتے، اور تیسری بار کھینچ کر کہتے تھے۔ نیز اسے عبدالملک بن ابی سلیمان نے زبید سے روایت کیا ہے، اور انہوں نے بھی ذر کا ذکر نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے اور جب جب سلام پھیر کر فارغ ہوتے تو تین دفعہ [سبحان الملک القدوس] فرماتے اور تیسری دفعہ آواز لمبی کردیتے۔\nاس روایت کو عبدالملک بن ابوسلیمان نے زبید سے بیان کیا ہے۔ انھوں نے بھی (راویٔ حدیث) ذرّ کا ذکر نہیں کیا۔"}],[1735,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے۔ نیز محمد بن جحادہ نے اسے زبید سے روایت کیا ہے، اور انہوں نے بھی ذر کا ذکر نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے۔\nاس روایت کو محمد بن حجادہ نے بھی زبید سے بیان کیا ہے۔ انھوں نے بھی (راویٔ حدیث) ذرّ کا ذکر نہیں کیا۔"}],[1736,"عبدالرحمٰن بن ابزی کہتے ہیں کہ رسول اللہ وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے، اور جب نماز سے فارغ ہو جاتے تو تین بار «سبحان الملك القدوس» کہتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتروں میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھتے تھے اور جب نماز سے فارغ ہوتے تو تین دفعہ [سبحان الملک القدوس] پڑھتے۔","f2":"مالک بن مغول سے اس روایت کو بیان کرنے والے شعیب بن حرب اور یحییٰ بن آدم ہیں۔ یحییٰ بن آدم نے زبید اور ابن ابزیٰ کے درمیان ذرّ کا واسطہ ذکر کیا ہے جبکہ شعیب بن حرب نے یہ واسطہ ذکر نہیں کیا، نیز یحییٰ بن آدم نے اس روایت کو مرسل بیان کیا ہے، یعنی صحابی عبدالرحمن بن ابزیٰ رضی اللہ عنہ کا ذکر نہیں کیا جبکہ شعیب نے ان کا ذکر کیا ہے۔"}],[1737,"عبدالرحمٰن بن ابزی کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد»پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھتے تھے۔"}],[1738,"اس سند سے (سعید بن عبدالرحمٰن) بن ابزی نے یہ حدیث مرسلاً (یعنی سند میں انقطاع کے ساتھ) روایت کی ہے، لیکن اسے عطا بن سائب نے سعید بن عبدالرحمٰن بن ابزی رضی اللہ عنہ کے واسطے سے عبدالرحمٰن بن ابزی سے متصلاً روایت کی ہے۔","الألباني: صحيح",{"u2":"یہ روایت عبدالرحمن بن ابزیٰ کے بیٹے سے ان کے واسطے کے بغیر یعنی مرسل بھی آئی ہے۔ اور عطاء بن سائب نے سعید بن عبدالرحمن بن ابزیٰ سے اور انھوں نے اپنے باپ (عبدالرحمن) سے یہ روایت بیان کی ہے۔"}],[1739,"عبدالرحمٰن بن ابزی سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم وتر میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھتے تھے۔"}],[1740,"سعید بن عبدالرحمٰن بن ابزی اپنے باپ سے روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے پھر جب فارغ ہو جاتے تو تین بار «سبحان الملك القدوس» کہتے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم (سبح اسم ربک الاعلیٰ)، (قل یایھاالکفرون) اور (قل ھواللہ احد) کے ساتھ وتر پڑھا کرتے تھے، پھر جب فارغ ہوتے تو تین دفعہ [سبحان الملک القدوس] پڑھتے۔"}],[1741,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور جب فارغ ہو جاتے تو تین بار «سبحان الملك القدوس» کہتے، اور تیسری مرتبہ کھینچ کر کہتے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے بارے میں بیان فرماتے ہیں کہ آپ (سبح اسم ربک الاعلیٰ)، (قل یایھاالکفرون) اور (قل ھواللہ احد) کے ساتھ وتر پڑھا کرتے تھے، پھر جب فارغ ہوتے تو تین دفعہ [سبحان الملک القدوس] پڑھتے اور تیسری دفعہ آواز کھینچتے (لمبی کرتے) تھے۔"}],[1742,"عبدالرحمٰن بن ابزی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى» پڑھتے تھے۔ شبابہ نے ان دونوں کی یعنی محمد کی اور ابوداؤد کی مخالفت کی ہے ۱؎ انہوں نے اسے شعبہ سے، شعبہ نے قتادہ سے، قتادہ نے زرارہ بن اوفی سے، اور زرارہ نے عمران بن حصین رضی اللہ عنہما سے روایت کیا ہے۔\n§وضاحت\n۱؎: شبابہ نے عبدالرحمٰن بن ابزی کی جگہ عمران بن حصین رضی اللہ عنہما کا ذکر کیا ہے، ان کی روایت آگے آ رہی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے بیان ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں سورۂ (سبح اسم ربک الاعلیٰ) پڑھتے تھے۔\n(شعبہ کے شاگرد) شبابہ نے دونوں (ابوداود اور محمد) کی مخالفت کی ہے اور اس روایت کو شعبۃ عن قتادۃ عن زرارۃ بن اوفی عن عمران بن حصین کی سند سے ذکر کیا ہے۔","f2":"شبابہ نے صحابی کا نام عبدالرحمن بن ابزیٰ کے بجائے عمران بن حصین کہا ہے، لیکن امام نسائی رحمہ اللہ نے فرمایا کہ یہ شبابہ کی غلطی ہے۔"}],[1743,"عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے وتر میں «سبح اسم ربك الأعلى» پڑھی۔ ابوعبدالرحمٰن نسائی کہتے ہیں: مجھے نہیں معلوم کہ کسی نے اس حدیث میں شبابہ کی متابعت کی ہے، یحیی بن سعید نے ان کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یہ مخالفت متن حدیث میں ہے جیسا کہ اگلی روایت سے ظاہر ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے سورۂ (سبح اسم ربک الاعلیٰ) کے ساتھ وتر پڑھا۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ میں نہیں جانتا کہ کسی راوی نے اس روایت میں شبابہ کی موافقت کی ہو۔ یحییٰ بن سعید نے شبابہ کی مخالفت کی ہے۔","f2":"(۱)یحییٰ اور شبابہ کا اختلاف متن کے الفاظ میں ہے۔ شبابہ نے اس روایت میں وتر کا ذکر کیا ہے جبکہ درحقیقت عمران بن حصین رضی اللہ عنہما کی روایت ظہر کے بارے میں ہے نہ کہ وتر کے بارے میں جیسا کہ یحییٰ بن سعید نے آئندہ حدیث میں بیان کیا ہے۔ اس کی تفصیل اس طرح ہے کہ شبابہ کو دووہم ہوئے ہیں: ایک یہ کہ انھوں نے عبدالرحمن بن ابزیٰ کی روایت کو عمران بن حصین کی روایت اقرار دیا ہے اور دوسرا یہ کہ عمران بن حصین کی روایت کو صحیح بیان کیا ہے۔ عمران بن حصین کی روایت وتر کے بارے میں نہیں بلکہ ظہر کے بارے میں ہے جیسا کہ یحییٰ بن سعید نے بیان کیا ہے۔ واللہ اعلم۔ (۲)مؤلف رحمہ اللہ اس روایت کو باربار (۱۵بار) سند کے معمولی اختلافات بیان کرنے کے لیے لائے ہیں۔ ان روایات کی اسانید کو بغور دیکھنے سے وہ اختلاف واضح ہوجاتا ہے، مثلاً: یہ روایت بعض راویوں نے ابی بن کعب رضی اللہ عنہ سے، بعض نے عبدالرحمن بن ابزیٰ رحمہ اللہ سے اور بعض نے عمران بن حصین رضی اللہ عنہما سے بیان کی ہے۔ وقف علی ھذا متن میں بھی اختلاف ہے۔ آخری دو روایتوں میں صرف ایک وتر کا ذکر ہے جبکہ باقی تمام میں تین وتر کا۔ (۳)بعض روایات میں تین دفعہ [سبحان الملک القدوس] کہنے کے بعد [رب الملائکۃ والروح] کا اضافہ بھی منقول ہے۔ دیکھیے: (سنن الدار قطنیٰ الوتر، باب مایقرأ فی رکعات الوتر والقنوت فیہ، حدیث:۱۶۴۴)"}],[1744,"عمران بن حصین رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھی، تو ایک شخص نے سورۃ «سبح اسم ربك الأعلى» پڑھی، تو جب آپ نماز پڑھ چکے تو آپ نے پوچھا: \" «سبح اسم ربك الأعلى» کس نے پڑھی ہے؟\" تو ایک شخص نے عرض کیا: میں نے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے ایسا لگا کہ تم میں سے کسی نے مجھے خلجان میں ڈال دیا ہے\" ۱؎۔\n§وضاحت\n۱؎: یہ دونوں الگ الگ حدیثیں ہیں گو دونوں کی سند ایک ہے، اس طرح کی مخالفت ضرر رساں نہیں واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر کی نماز پڑھائی۔ (آپ کے پیچھے) ایک آدمی نے سورۂ (سبح اسم ربک الاعلیٰ) (ہلکی سی آواز کے ساتھ) پڑھی۔ جب آپ نماز سے فارغ ہوئے تو فرمایا: ’’سورۂ (سبح اسم ربک الاعلیٰ) کس نے پڑھی؟ ایک آدمی نے کہا: میں نے۔ آپ نے فرمایا: ’’مجھے معلوم ہورہا تھا کہ کوئی شخص مجھے اشتباہ میں ڈال رہا ہے۔‘‘","f2":"جہری نماز میں اثنائے قراءت امام کے پیچھے فاتحہ کے سوا قراءت کرنا منع ہے۔ سری نماز میں زائد قراءت کی جاسکتی ہے مگر وہ کسی کو سنائی نہ دے ورنہ شور ہوسکتا ہے، نیز ایک آدمی کے اونچا پڑھنے سے امام یا ساتھیوں کو غلجان و اشتباہ ہوسکتا ہے اور دوسروں کو پریشان کرنا قطعاً جائز نہیں۔ قراءت کے علاوہ دیگر اور دوتسبیحات بھی دوسروں کو سنائی نہیں دینی چاہییں، البتہ نمازی اکیلا ہو تو مناسب آواز سے پڑھ سکتا ہے۔ فرض ہوں یا نفل، نماز سری ہو یا جہری اور قراءت ہو یا تسبیحات واوراد۔ واللہ اعلم۔"}],[1745,"حسن رضی اللہ عنہ کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے کچھ کلمات سکھائے جنہیں میں وتر کی کی قنوت میں کہتا ہوں، وہ یہ ہیں: «اللہم اهدني فيمن هديت وعافني فيمن عافيت وتولني فيمن توليت وبارك لي فيما أعطيت وقني شر ما قضيت إنك تقضي ولا يقضى عليك وإنه لا يذل من واليت تباركت ربنا وتعاليت» \"اے اللہ! مجھے ہدایت دے، ان لوگوں میں شامل کر کے جنہیں تو نے ہدایت دی ہے، عافیت دے ان لوگوں میں شامل کر کے جنہیں تو نے عافیت دی ہے، میری نگہبانی فرمان لوگوں میں شامل کر کے جن کی تو نے نگہبانی فرمائی، اور جو تو نے دیا ہے اس میں میرے لیے برکت عطا فرما، اور جس کا تو نے فیصلہ فرما دیا ہے اس کی برائی سے مجھے بچا، اس لیے کہ تو ہی فیصلہ کرتا ہے، اور تیرے خلاف کوئی فیصلہ نہیں کیا جا سکتا، اور تو جس سے دوستی کرے وہ ذلیل نہیں ہو سکتا، اے ہمارے رب! تو برکت والا اور بلند و بالا ہے\"۔","الألباني: صحيح",{"u2":"حضرت حسن رضی اللہ عنہ فرماتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے کچھ کلمات سکھلائے جنھیں میں قنوت وتر میں پڑھا کرتا ہوں، [اللھم اھدنی فیمن ہدیت۔۔۔ تبارکت ربنا وتعالیت] ’’اے اللہ! مجھے ہدایت دے ان لوگوں میں شامل فرما کر جن کو تونے عافیت دی ہے۔ میرا ولی بن جا ان لوگوں میں شامل فرما کر جن کا تو ولی بنا۔ اور میرے لیے ان چیزوں میں برکت فرما جو تونے عطا فرمائیں۔ اور مجھے اس فیصلے کے شر سے بچا جو تو نے فرما رکھا ہے۔ یقیناً تو فیصلے کرتا ہے اور تیرے خلاف فیصلہ نہیں کیا جاسکتا۔ اور یقیناً وہ شخص ذلیل ہوسکتا جس کا تو ولی ہو۔ اے ہمارے رب! تو بڑا بابرکت اور بلندوبالا ہے۔‘‘"}],[1746,"حسن بن علی رضی اللہ عنہم کہتے ہیں کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے وتر کے یہ کلمات سکھائے، آپ نے فرمایا: کہو: «اللہم اهدني فيمن هديت وبارك لي فيما أعطيت وتولني فيمن توليت وقني شر ما قضيت فإنك تقضي ولا يقضى عليك وإنه لا يذل من واليت تباركت ربنا وتعاليت وصلى اللہ على النبي محمد»۔","الألباني: ضعيف",{"u2":"حضرت حسن بن علی رضی اللہ عنہما سے روایت ہے کہ مجھے رسول اللہ صلی اللہ علیہ وسلم نے یہ کلمات وتر میں پڑھنے کے لیے سکھائے۔ فرمایا: کہہ [اللھم! اھدنی فیمن ھدیت۔۔۔ وصلی اللہ علی النبی محمد] اے اللہ! مجھے راہ راست پر چلا ان لوگوں میں شامل فرما کر جن کو تونے راہ راست پر چلایا اور رکھا۔ اور مجھے عافیت عطا فرما ان لوگوں میں شامل فرما جن کو تونے عافیت دی۔ اور میرا ولی ہو ان لوگوں میں شامل فرما کر جن کا تو ولی ہوا۔ اور میرے لیے ان چیزوں میں برکت فرما جو تونے عطا فرمائیں۔ اور مجھے اس فیصلے کے شراور نقصان سے بچا جو تونے فرمایاکیونکہ تو (جوچاہے) فیصلے فرماتا ہے لیکن میرے خلاف فیصلہ نہیں کیا جاسکتا۔ اور بلاشبہ وہ شخص ذلیل نہیں ہوسکتا جس کا تو ولی ہو۔ اے ہمارے رب! تو بابرکت اور بلندوبالا ہے۔ اور اللہ تعالیٰ نبی کریم حضرت محمد صلی اللہ علیہ وسلم پر رحمتیں فرمائے۔‘‘","f2":"(۱)یہ دوروایتیں ایک ہی حدیث ہیں، لہٰذا الفاظ کی کمی بیشی کا تدارک ایک دوسرے سے ہو سکتا ہے۔ اسی طرح اس روایت کی اور اسانید بھی ہیں جن میں کچھ مزید الفاظ بھی ہیں، لہٰذا ان میں سے جو الفاظ صحیح سند کے ساتھ مروی ہیں وہ بھی قبول کیے جائیں گے۔ (۲)مستدرک حاکم میں صراحت ہے کہ آپ نے فرمایا: کہ میں وتر کی آخری رکعت میں رکوع سے سر اٹھانے کے بعد یہ دعا پڑھوں۔ دیکھیے: (المستدرک الحاکم: ۳؍۱۷۲) لیکن ان الفاظ کے ساتھ یہ روایت ضعیف ہے۔ تفصیل کے لیے ملاحظہ فرمائیے: (اصل صفۃ صلاۃ النبی صلی اللہ علیہ وسلم للالبانی:۳؍۹۷۱، ۹۷۲) اس روایت کی بنیاد پر بعض علماء قنوتِ وتر کو رکوع کے بعد پڑھنا راجح سمجھتے ہیں جبکہ صحیح بخاری اور صحیح مسلم کی متفق علیہ روایت میں صراحت ہے کہ آپ نے صرف قنوتِ نازلہ رکوع کے بعد پڑھی ہے اور قنوتِ وتر قبل از رکوع، اس لیے دوسروں کے نزدیک قنوت وتر کا رکوع سے پہلے پڑھنا راجح ہے۔ یہی بات زیادہ صحیح ہے۔ دیکھیے: (صحیح البخاری، الوتر، حدیث:۱۰۰۲، وصحیح مسلم، المساجد، حدیث:۶۷۷) (۳)دعائے قنوت میں نستغفرک ونتوب الیک کے الفاظ بھی مشہور ہیں، لیکن یہ الفاظ حدیث کی کسی کتاب میں نہیں ملتے۔ تفصیل کے لیے دیکھیے: (القول المقبول فی شرح و تعلیق صلاۃ الرسول، حدیث:۵۸۶) اس لیے ان کا پڑھنا صحیح نہیں۔ یہ الفاظ صرف ’’حصن حصین‘‘ میں ہیں جو حدیث کی کتاب نہیں ہے۔ (۴) وصلی اللہ علی النبی محمد کے الفاظ کے علاوہ باقی تمام الفاظ اوپر والی روایت (۱۷۴۶) میں مووجد ہیں جو کہ سنداً صحیح ہے۔ وصلی اللہ علی النبی محمد کے الفاظ مرفوعاً ضعیف ہیں، البتہ ابی بن کعب رضی اللہ انہ سے موقوفاً قنوت وتر میں ان کا پڑھنا صحیح سند سے ثابت ہے۔ (صحیح ابن خزیمہ، حدیث:۱۱۰۰) نیز دوسرے صحابی رسول ابوحلیمہ انصاری رضی اللہ عنہ سے بھی موقوفاً ان کا ثبوت ملتا ہے۔ (فضل الصلاۃ علی النبی صلی اللہ علیہ وسلم، رقم:۱۰۷) لہٰذا ان الفاظ کے پڑھنے میں کوئی حرج نہیں۔ واللہ اعلم۔ مزید تفصیل کے لیے دیکھیے: (صفۃ صلاۃ النبی صلی اللہ علیہ وسلم للالبانی، ص:۱۸۰)"}],[1747,"علی بن ابی طالب رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اپنی وتر کے آخر میں یہ کلمات کہتے تھے: «اللہم إني أعوذ برضاك من سخطك وبمعافاتك من عقوبتك وأعوذ بك منك لا أحصي ثناء عليك أنت كما أثنيت على نفسك» \"اے اللہ! میں تیری خوشی کی تیرے غصے سے پناہ مانگتا ہوں، تیرے بچاؤ کی تیری پکڑ سے پناہ مانگتا ہوں، اور میں تیری پناہ مانگتا ہوں تجھ سے، میں تیری تعریف نہیں کر سکتا تو ویسے ہی ہے جیسے تو نے خود اپنی تعریف کی ہے\"۔","الألباني: صحيح",{"u2":"حضرت علی ابن ابی طالب رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم اپنی وتر نماز کے آخر میں یہ الفاظ پڑھتے تھے:[اللھم انی اعوذ برضاک من سخطک۔۔۔ انت کما اثنیت علی نفسک] ’’اے اللہ! میں تیرے غصے سے بچنے کے لیے تیری رضامندی کی پناہ چاہتا ہوں اور تیری سزا سے بچنے کے لیے تیری معافی اور عافیت کی پناہ چاہتا ہوں اور میں تجھ سے ڈرتے ہوئے تیری ہی پناہ چاہتا ہوں۔ میں تیری مکمل تعریف نہیں کرسکتا۔ تو اسی طرح ہے جس طرح تو نے خود اپنی تعریف کی ہے۔‘‘","f2":"(۱)مذکورہ حدیث میں یہ صراحت نہیں کہ اس دعا کا مقام کیا ہے؟ تشہد کے آخر میں یا سلام کے بعد۔ مؤخر الذکر مفہوم زیادہ مناسب معلوم ہوتا ہے۔ ایک روایت میں آپ سے یہ الفاظ بستر پر لیٹنے وقت پڑھنے بھی منقول ہیں۔ پیچھے حدیث نمبر ۱۱۰۱ میں یہ الفاظ تہجد کے سجدے کے دوران میں بھی آپ سے پڑھنے منقول ہیں۔ امام نسائی رحمہ اللہ کے انداز سے معلوم ہوتا ہے کہ وہ اس دعا کو قنوت وتر میں سمجھتے ہیں۔ [اخروترہ] کے یہ معنی بھی ممکن ہیں۔ لیکن ابن قیم رحمہ اللہ کی تحقیق میں افی اخر وترہ سے مراد سلام کے بعد ان کلمات کا پڑھنا ہے۔ ان کے بقول سنن نسائی کی ایک روایت میں نماز سے فراغت کی تصریح ملتی ہے۔ دیکھیے: (زادالمیعاد:۱؍۳۳۶) (۲)قنوت وتر سارا سال ہی جائز ہے۔ رسول اللہ صلی اللہ علیہ وسلم سے اس موضوع سے متعلقہ عام روایات میں دعائے وتر کا ذکر نہیں ملتا۔ اگر آپ سے اس دعا کے پڑھنے کا بدستور ثبوت ملتا ہوتا تو یقیناً منقول بھی ہوتا، اس سے پتا چلتا ہے کہ دعائے وتر کبھی رہ جائے یا اسے چھوڑ بھی دیا جائے تو جائز ہے سجدۂ سہو کی ضرورت نہیں کیونکہ اس دعا کی حیثیت وجوب کی نہیں۔ شیخ البانی رحمہ اللہ کی تحقیق کے مطابق رسول اللہ صلی اللہ علیہ وسلم سے قنوت وتر کا ثبوت کبھی کبھار ملتا ہے۔ تفصیلی بحث کے لیے ملاحظہ فرمائیے: (اصل صفۃ صلاۃ النبی صلی اللہ علیہ وسلم: ۳؍۹۶۸)"}],[1748,"انس رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم اپنے دونوں ہاتھ استسقاء کے علاوہ کسی دعا میں نہیں اٹھاتے تھے۔ شعبہ کہتے ہیں: میں نے ثابت سے پوچھا: آپ نے اسے انس رضی اللہ عنہ سے سنا ہے؟ تو انہوں نے کہا: سبحان اللہ، میں نے کہا: آپ نے اسے سنا ہے؟ انہوں نے کہا: سبحان اللہ ۱؎۔\n§وضاحت\n۱؎: یہ کہنا ان کا بطور تعجب تھا، مطلب یہ ہے کہ سنا کیوں نہیں ہے اگر نہیں سنا ہوتا تو بیان کیسے کرتا، اور یہ مؤلف کا قیاسی استنباط ہے، یہاں نہ اٹھانے سے مراد یہ ہے کہ اٹھانے میں مبالغہ نہیں کرتے تھے، نہ یہ کہ سرے سے اٹھاتے ہی نہیں تھے کیونکہ قنوت میں اور دوسرے موقعوں پر بھی آپ کا ہاتھ اٹھانا صحیح حدیثوں سے ثابت ہے۔","الألباني: صحيح ق دون قوله قال شعبة",{"u2":"حضرت انس رضی اللہ عنہ فرماتے ہیں کہ نبی صلی اللہ علیہ وسلم استسقاء (بارش کی دعا) کے علاوہ کسی بھی دعا میں ہاتھ نہیں اٹھاتے تھے۔ (راویٔ حدیث) شعبہ نے کہا کہ میں نے (اپنے استاد) ثابت (بنانی) سے کہا: کیا آپ نے یہ روایت خود حضرت انس رضی اللہ عنہ سے سنی ہے؟ انھوں نے کہا: سبحان اللہ! میں نے پھر کہا: آپ نے سنی ہے؟ انھوں نے پھر کہا: سبحان اللہ (یعنی کیا بغیر سنے بیان کررہا ہوں؟)","f2":"(۱)مذکورہ بالا حدیث سے استدلال درست نہیں کیونکہ اس حدیث کا صحیح مفہوم یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم کسی اور دعا میں اتنے بلند ہاتھ نہیں اٹھاتے تھے جتنے استسقا ء میں اٹھاتے تھے۔ اس میں آپ نے ہاتھ سر سے بھی اونچے کرلیے تھے جبکہ عام دعا میں ہاتھ سینے کے برابر ہوتے ہیں۔ احادیث میں آپ کا عام دعاؤں میں بھی ہاتھ اٹھانا ثابت ہے۔ (۲)قنوت وتر میں ہاتھ اٹھانا نبی اکرم صلی اللہ علیہ وسلم سے ثابت نہیں، اس لیے افضل اور اولیٰ یہی ہے کہ قنوت وتر بغیر ہاتھ اٹھائے رکوع سے قبل کی جائے جیسا کہ سنن نسائی کی حدیث (۱۷۰۰) میں ہے، تاہم بعض علماء بعض آثار کے پیش نظر اور قنوت نازلہ پر قیاس کرتے ہوئے قنوت وتر میں بھی ہاتھ اٹھانے کے جواز کے قائل ہیں کیونکہ قنوت نازلہ میں نبی اکرم صلی اللہ علیہ وسلم سے دعا کے لیے ہاتھ اٹھانا ثابت ہیں۔ واللہ اعلم۔ (۳)یہاں ہاتھ اٹھانے سے مراد دعا کے لیے ہاتھ اٹھانا ہے نہ کہ معروف رفع الیدین جو نماز کے شروع میں کیا جاتا ہے، مگر احناف اسی رفع الیدین کے قائل ہیں۔ اور قنوت میں عملاً رفع الیدین کرتے بھی ہیں۔ تعجب کی بات ہے کہ احناف رکوع جاتے اور اٹھتے وقت رفع الیدین کے قائل نہیں (بلکہ اس سے منع کرتے اور نماز کے سکون کے منافی خیال کرتے ہیں) حالانکہ وہ صحیح ترین کثیر احادیث سے ثابت ہے اور وتر کی دعا کے آغاز میں رفع الیدین کے قائل ہیں جو رسول اللہ صلی اللہ علیہ وسلم سے ثابت نہیں۔ کیا یہ رفع الیدین نماز کے سکون کے منافی نہیں؟"}],[1749,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم رات میں عشاء کی نماز سے فارغ ہونے سے لے کر فجر ہونے تک فجر کی دو رکعتوں کے علاوہ گیارہ رکعتیں پڑھتے تھے، اور اتنا لمبا سجدہ کرتے کہ تم میں سے کوئی پچاس آیتوں کے بقدر پڑھ لے۔\n§وضاحت\nمؤلف نے اس سجدہ سے تہجد :(مع وتر ) کے سجدوں کے علاوہ سلام کے بعد ایک مستقل سجدہ سمجھا ہے، حالانکہ اس سے مراد تہجد کے سجدے ہیں، آپ یہ سجدے پچاس آیتیں پڑھنے کے بقدر لمبا کرتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم عشاء کی نماز سے فارغ ہونے کے بعد فجر تک رات میں، فجر کی دو سنتوں کے علاوہ، گیارہ رکعت پڑھا کرتے تھے اور آپ اتنا لمبا سجدہ کرتے تھے کہ تم میں سے ایک شخص پچاس آیات پڑھ سکتا تھا۔","f2":"حدیث میں یہ صراحت نہیں کہ یہ سجدہ وتر سے فراغت کے بعد ہوتا تھا جیسا کہ مصنف رحمہ اللہ نے سمجھا ہے بلکہ حقیقت یہ ہے کہ یہ رات کی نماز میں کیے جانے والے سجدوں کی طوالت کا ذکر ہے۔ صحیح بخاری میں یہ روایت تفصیل سے آئی ہے۔ اس میں یہ وضاحت ہے کہ یہ قیام اللیل کے سجدوں کی بات ہے نہ کہ وتر کے بعد کی۔ اس کے الفاظ یہ ہیں: [کان یصلی احدی عشرۃ رکعا، کانت تلک صلاتہ، یسجد السجدۃ من ذلک قدر مایقرا احدکم خمسین آی قبل ان یرفع راسہ۔۔۔] ’’نبی اکرم صلی اللہ علیہ وسلم (رات کے وقت) گیارہ رکعتیں پڑھتے تھے۔ آپ کی (رات کی) نماز یہی تھی۔ آپ اس نماز میں سجدہ اتنا (طویل) کرتے کہ آپ کے سرمبارک اٹھانے سے پہلے تم میں سے کوئی پچاس آیات پڑھ لے۔‘‘ (صحیح البخاری، التہجد، حدیث: ۱۱۲۳) اسی لیے امام بخاری رحمہ اللہ نے اس حدیث پر [باب طول السجود فی قیام اللیل] کے نام سے عنوان قائم کیا ہے۔"}],[1750,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور سلام پھیرنے کے بعد «سبحان الملك القدوس» تین بار کہتے، اور اس کے ساتھ اپنی آواز بلند کرتے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم وتر کی نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے اور سلام پھیرنے کے بعد تین دفعہ بلند آواز سے [سبحان الملک القدوس] پڑھتے تھے۔"}],[1751,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور سلام پھیرنے کے بعد «سبحان الملك القدوس» تین بار کہتے، اور اس کے ذریعہ اپنی آواز بلند کرتے۔ ابونعیم نے ان دونوں کی یعنی قاسم اور محمد بن عبید کی مخالفت کی ہے، چنانچہ انہوں نے اسے سفیان سے، اور سفیان نے زبید سے، زبید نے ذر سے، اور ذر نے سعید بن عبدالرحمٰن ابزی سے روایت کیا ہے، (یعنی سند میں ایک راوی \"ذر\" کا اضافہ کیا ہے)۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم (سبح اسم ربک الاعلیٰ)، (قل یایھاالکفرون) اور (قل ھواللہ احد) کے ساتھ وتر پڑھتے تھے اور سلام کے بعد تین دفعہ بلند آواز سے [سبحان الملک القدوس] فرماتے تھے۔\nابونعیم نے ان دونوں (قاسم اور محمد بن عبید) کی مخالفت کی ہے اور اس روایت کو عن سفیان عن زبید عن ذر عن سعید کی سند سے بیان کیا ہے۔","f2":"مذکورہ دونوں احادیث (۱۷۵۱ اور ۱۷۵۲) میں سفیان ثوری کے شاگرد بالترتیب قاسم اور محمد بن عبید ہیں۔ ان دونوں نے زبید اور سعید کے درمیان ذرّ کا واسطہ ذکر نہیں کیا، مگر آئندہ حدیث میں ابونعیم نے یہ واسطہ ذکر کیا ہے۔ ابونعیم بھی سفیان کے شاگرد ہیں"}],[1752,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور جب واپس ہونے کا ارادہ کرتے تو «سبحان الملك القدوس» تین مرتبہ کہتے، اور اس کے ذریعہ اپنی آواز بلند کرتے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: ابونعیم ہمارے نزدیک محمد بن عبید اور قاسم بن یزید سے زیادہ ثقہ ہیں، اور ہمارے نزدیک سفیان ثوری کے تلامذہ میں سب سے زیادہ معتبر یحیی بن سعید قطان ہیں، پھر عبداللہ بن مبارک، پھر وکیع بن جراح، پھر عبدالرحمٰن بن مہدی، پھر ابونعیم، پھر اسود ہیں، واللہ اعلم، نیز اسے جریر بن حازم نے زبید سے روایت کیا، تو انہوں نے کہا کہ آپ تیسری بار میں اپنی آواز کھینچتے اور بلند کرتے تھے، (جریر کی روایت آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم وتروں میں سورۂ (سبح اسم ربک الاعلیٰ)، سورۂ (قل یایھاالکفرون) اور سورۂ (قل ھواللہ احد) پڑھتے تھے، پھر جب سلام پھیرنے کے بعد اٹھنے کا ارادہ فرماتے تو تین دفعہ بلند آواز سے [سبحان الملک القدوس] پڑھتے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ہمارے نزدیک ابونعیم، محمد بن عبید اور امام قاسم بن یزید سے زیادہ ثقہ اور معتبر ہیں۔ ہمارے نزدیک سفیان ثوری کے شاگرد اس حدیث میں ثقاہت کے لحاظ سے یہ ترتیب رکھتے ہیں۔ یحییٰ بن سعید قطان، عبداللہ بن مبارک، وکیع بن جراح، عبدالرحمن بن مہدی، ابونعیم اور اسود۔ واللہ اعلم۔\nجریربن حازم نے بھی اس حدیث کو زبید سے بیان کیا ہے۔ انھوں نے یوں کہا ہے: تیسری دفعہ آپ صلی اللہ علیہ وسلم نے اپنی آواز کو لمبا بھی کیا اور بلند بھی۔"}],[1753,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور جب سلام پھیرتے تو تین بار «سبحان الملك القدوس» کہتے، اور تیسری بار میں آواز کھینچتے اور بلند کرتے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھاالکفرون) اور (قل ھواللہ احد) پڑھتے تھے۔ اور جب سلام پھیرتے تو تین دفعہ [سبحان الملک القدوس] فرماتے اور تیسری دفعہ اپنی آواز کو کھینچتے تھے اور مزید بلند فرماتے تھے۔"}],[1754,"عبدالرحمٰن بن ابزی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم وتر میں «سبح اسم ربك الأعلى»، «قل يا أيها الكافرون» اور «قل هو اللہ أحد» پڑھتے تھے، اور جب فارغ ہوتے تو «سبحان الملك القدوس» کہتے۔ ہشام نے اسے مرسلاً روایت کیا، ان کی روایت آگے آ رہی ہے ۱؎۔\n§وضاحت\n۱؎: یعنی انہوں نے «عن أبیہ» کا ذکر نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابزیٰ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم وتر کی نماز میں (سبح اسم ربک الاعلیٰ)، (قل یایھا الکفرون) اور (قل ھواللہ احد) پڑھا کرتے تھے اور جب فارغ ہوتے تو [سبحان الملک القدوس] کہتے۔ (قتادہ کے شاگرد) ہشام نے اس روایت کو مرسل بیان کیا ہے (یعنی براہ راست رسول اللہ صلی اللہ علیہ وسلم سے روایت کیا ہے۔ اس میں صحابی عبدالرحمن بن ابزیٰ کا ذکر نہیں کیا۔)"}],[1755,"سعید بن عبدالرحمٰن بن ابزی سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم وتر پڑھتے تھے، پھر راوی نے پوری حدیث بیان کی۔","",{"u2":"حضرت سعید بن عبدالرحمن بن ابزیٰ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم وتر (میں یہ تین سورتیں) پڑھتے تھے۔۔۔ پھر راوی نے پوری حدیث بیان کی۔","f2":"امام نسائی رحمہ اللہ نے سندوں کا اختلاف ظاہر کرنے کے لیے اس حدیث کو چھ دفعہ ذکر کیا جس کی تفصیل سندیں دیکھ کر ہی معلوم ہوسکتی ہے، مثلاً: آخری سند میں صحابی کا واسطہ نہیں جبکہ باقی سندوں میں صحابی کا واسطہ ہے، وغیرہ۔"}],[1756,"یحیی بن ابی کثیر کہتے ہیں کہ مجھے ابوسلمہ بن عبدالرحمٰن نے خبر دی ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں پوچھا، تو انہوں نے کہا: آپ صلی اللہ علیہ وسلم تیرہ رکعت پڑھتے تھے، نو رکعت کھڑے ہو کر، اس میں وتر بھی ہوتی اور دو رکعت بیٹھ کر، تو جب آپ رکوع کرنے کا ارادہ کرتے تو کھڑے ہو جاتے، اور رکوع اور سجدہ کرتے، اور ایسا آپ وتر کے بعد کرتے تھے، پھر جب آپ فجر کی اذان سنتے تو کھڑے ہوتے، اور دو ہلکی ہلکی رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ بن عبدالرحمن سے روایت ہے کہ انھوں نے حضرت عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں پوچھا تو انھوں نے فرمایا: آپ کل تیرہ رکعات پڑھتے تھے۔ نو رکعتیں کھڑے ہوکر جن میں ایک رکعت وتر ہوتی تھی۔ دو رکعتیں بیٹھ کر۔ جب رکوع کا ارادہ فرماتے تو کھڑے ہوجاتے اور رکوع اور سجدے کرتے۔ ایسا آپ وتر کے بعد کرتے تھے، پھر جب صبح کی اذان سنتے تو اٹھتے اور دو دو ہلکی رکعتیں پڑھتے۔","f2":"وتر کے بعد دورکعات کا مسئلہ پیچھے گزر چکا ہے۔ تفصیل کے لیے دیکھیے، حدیث:۱۶۵۲"}],[1757,"ام المؤمنین عائشہ رضی اللہ عنہم سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم ظہر سے پہلے کی چار رکعتیں اور فجر سے پہلے کی دو رکعتیں نہیں چھوڑتے تھے۔ شعبہ کے جن تلامذہ نے اس حدیث کو روایت کیا ہے ان میں سے اکثر نے عثمان بن عمر کی مخالفت کی ہے، ان لوگوں نے مسروق کا ذکر نہیں کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم ظہر سے قبل چار رکعت (سنت مؤکدہ) اور فجر سے قبل دو رکعت سنت نہیں چھوڑتے تھے۔\nیہ حدیث بیان کرنے والے شعبہ کے دوسرے شاگردوں نے عثمان بن عمر کی مخالفت کی ہے، یعنی انھوں نے (محمد بن منتشر اور حضرت عائشہ رضی اللہ عنہا کے درمیان) مسروق کا ذکر نہیں کیا۔","f2":"امام ابوجعفر طبری بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کا اکثر عمل ظہر سے پہلے چار رکعت کا تھا۔ کبھی کبھار آپ دو رکعت بھی پڑھ لیتے تھے۔ مزید دیکھیے: (فتح الباری، تحت شرح الحدیث:۱۱۸۲)"}],[1758,"ابراہیم بن محمد سے روایت ہے کہ انہوں نے اپنے والد کو بیان کرتے سنا کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے سنا ہے کہ رسول اللہ صلی اللہ علیہ وسلم ظہر سے پہلے کی چار رکعتیں، اور فجر سے پہلے کی دو رکعتیں نہیں چھوڑتے تھے۔ ابو عبدالرحمٰن (نسائی) کہتے ہیں: ہمارے نزدیک صحیح یہی ہے، اور عثمان بن عمر کی(پچھلی) روایت غلط ہے، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ظہر سے پہلے چار رکعت اور فجر سے پہلے دو رکعت (سنت) نہیں چھوڑتے تھے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ہمارے نزدیک یہ روایت درست ہے اور عثمان بن عمر کی روایت غلط ہے۔ واللہ اعلم۔ (اس کی وضاحت پہلے ہوچکی ہے کہ اس روایت میں مسروق کا ذکر درست نہیں۔)","f2":"اس اختلاف کی مزید تفصیل کے لیے فتح الباری:۳؍۵۹، حدیث:۱۱۸۲ ملاحظہ کی جاسکتی ہے۔"}],[1759,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فجر کی دونوں رکعتیں دنیا ومافیہا سے بہتر ہیں\"۔\n§وضاحت\n۱؎: اس سے مراد فجر کی دونوں سنتیں ہیں کیونکہ عام طور پر اس لفظ سے یہی مراد لیا جاتا ہے، اور یہ ممکن ہے کہ یہاں مراد فرض ہو کیونکہ لفظ اس کا بھی محتمل ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’فجر کی دو سنتیں دنیا اور اس کی ہر چیز سے بہتر ہیں۔‘‘","f2":"دنیا فانی ہے اور آخرت کا ثواب باقی، لہٰذا ان کا کوئی مقابلہ ہی نہیں، یعنی فجر کی دو سنتوں کا ثواب اس بات سے بہتر ہے کہ اسے ساری دنیا دے دی جائے، لہٰذا انھیں سفر میں بھی نہ چھوڑا جائے۔"}],[1760,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ جب صبح کی نماز کی اذان دی جاتی تو رسول اللہ صلی اللہ علیہ وسلم اس سے پہلے کہ نماز کھڑی ہو ہلکی ہلکی دو رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے روایت ہے کہ جب صبح کی اذان ہوتی تو رسول اللہ صلی اللہ علیہ وسلم فرض نماز کے لیے جانے سے پہلے دوہلکی رکعتیں پڑھا کرتے تھے۔","f2":"اصل وقت یہی ہے، البتہ اگر کسی وجہ سے رہ جائیں تو فرض نماز پڑھنے کے بعد بھی پڑھی جاسکتی ہیں۔"}],[1761,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ مجھے ام المؤمنین حفصہ رضی اللہ عنہا نے خبر دی ہے کہ نبی اکرم صلی اللہ علیہ وسلم جب فجر روشن ہو جاتی تو دو رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے منقول ہے کہ جب فجر اچھی طرح روشن ہوجاتی تو نبی صلی اللہ علیہ وسلم دورکعتیں پڑھا کرتے تھے۔"}],[1762,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب مؤذن فجر کی پہلی اذان کہہ کر خاموش ہو جاتا تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوتے، اور فجر نمودار ہونے کے بعد فجر کی نماز سے پہلے ہلکی ہلکی دو رکعتیں پڑھتے، پھر اپنے داہنے پہلو پر لیٹ جاتے ۱؎۔\n§وضاحت\n۱؎: اس حدیث میں نبی اکرم صلی اللہ علیہ وسلم کا عمل بیان کیا گیا ہے، اور ابوداؤد اور ترمذی کی ایک روایت میں جو صحیح سندوں سے مروی ہے اس کا حکم بھی آیا ہے جس سے مخالفین کی تاویل باطل ہو جاتی ہے، اور اس کے سنت ہونے میں کوئی کلام نہیں رہ جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ جب مؤذن فجر کی نماز کی اذان سے فارغ ہوتا تو فجر واضح اور روشن ہونے کے بعد رسول اللہ صلی اللہ علیہ وسلم اٹھتے اور فجر کی فرض نماز سے پہلے دو ہلکی رکعتیں پڑھتے، پھر اپنے دائیں پہلو پر لیٹ جاتے","f2":"اس حدیث سے معلوم ہوا کہ فجر کی سنتیں پڑھ کر لیٹنا نبی صلی اللہ علیہ وسلم کا معمول تھا۔ اسے بڑھاپے کی وجہ سے محض آرام کرلینا، قرار نہیں دیا جاسکتا جیسا کہ بعض لوگ کہتے ہیں۔ اس کی تفصیل حدیث: ۱۷۲۷ کے فوائد میں گزر چکی ہے۔"}],[1763,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ مجھ سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"فلاں کی طرح مت ہو جانا، وہ رات میں قیام کرتا تھا (تہجد پڑھتا تھا)، پھر اس نے رات کا قیام چھوڑ دیا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’توفلاں شخص کی طرح نہ ہوجانا جو پہلے رات کو (نفل) نماز پڑھا کرتا تھا پھر اس نے اسے چھوڑ دیا۔‘‘","f2":"(۱)حضرت عبداللہ بن عمرو رضی اللہ عنہما ساری ساری رات قیام کرتے تھے۔ اس میں خطرہ تھا کہ جسم کمزور ہوجائے گا اور دوسرے سے عبادت خصوصاً رات کی نماز کے قابل نہ رہے گا، اس لیے فرمایا کہ رات کو سونے کے بعد کچھ دیر کے لیے تہجد پڑھا کرو تاکہ جسم کمزور نہ پڑے۔ اس طرح رات کا قیام جاری رہے گا اور ترک کی نوبت نہ آئے گی۔ نیکی شروع کرکے پھر چھوڑ دینا ناپسندیدہ بات ہے۔ اس سے بہتر ہے کہ نفل نیکی تھوڑی مقدار میں کی جائے جس پر پابندی اور ہمیشگی آسان ہو۔ (۲)لوگوں کو کسی عیب یا کمزوری سے بچنے کا درس دینے کے لیے کسی معین شخص کا ذکر نہ کیا جائے جس میں وہ عیب پایا جاتا ہو۔ (۳)نیکی کے کام کو چھوڑ دینا مناسب نہیں، اگرچہ وہ وجوب کا درجہ نہ بھی رکھتا ہو۔"}],[1764,"عبداللہ بن عمرو رضی اللہ عنہم کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے عبداللہ! فلاں کی طرح مت ہو جانا، پہلے وہ قیام اللیل کرتا تھا (تہجد پڑھتا تھا)، پھر اس نے چھوڑ دیا\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے عبداللہ! فلاں شخص کی طرح نہ ہوجانا جو رات کا قیام (نفل نماز) پڑھا کرتا تھا، پھر اس نے قیام اللیل چھوڑ دیا۔‘‘"}],[1765,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم فجر کی دو ہلکی رکعتیں پڑھتے تھے۔\n§وضاحت\n۱؎: ہلکی پڑھنے کا مطلب ہے کہ آپ فجر کی ان دونوں سنتوں میں قیام و قرأت اور رکوع و سجود وغیرہ میں اختصار سے کام لیتے تھے کیونکہ اس کے بعد آپ کو فجر کی نماز پڑھانی ہوتی تھی جس میں قرات لمبی کی جاتی ہے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم فجر کی دو ہلکی رکعتیں پڑھتے تھے۔"}],[1766,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ مجھ سے ام المؤمنین حفصہ رضی اللہ عنہا نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نماز فجر کی اذان اور اقامت کے درمیان ہلکی ہلکی دو رکعتیں پڑھتے تھے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: دونوں حدیثیں ہمارے نزدیک غلط ہیں ۱؎ واللہ اعلم۔\n§وضاحت\n۱؎: پہلی روایت «نافع عن صفیۃ عن حفصہ» کے طریق سے مروی ہے، صحیح «عن نافع عن ابن عمر عن حفصہ» ہے، اور دوسری روایت کی سند میں «انبأنا شعیب قال حدثنا الاوزاعی» ہے، صحیح «انبأنا یحیی قال حدثنا الاوزاعی» ہے، یہ بات اس صورت میں ہے جب ترجمۃ الباب میں «علی» کو «فی» کے معنی میں لیا جائے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی اذان اور اقامت کے درمیان دو ہلکی رکعتیں پڑھتے تھے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ہمارے نزدیک یہ دونوں روایتیں غلط ہیں۔ واللہ اعلم۔","f2":"دونوں روایتوں سے مراد روایت ۱۷۶۶ اور ۱۷۶۷ ہیں۔ پہلی روایت میں غلطی یہ ہے کہ نافع اور حفصہ رضی اللہ عنہما کے درمیان صفیہ کی بجائے حضرت ابن عمر رضی اللہ عنہما کا واسطہ چاہیے جیسا کہ روایت نمبر ۱۷۶۷ اور مابعد روایات میں ہے، یعنی نافع کے شاگردان میں سے صرف عبدالحمید بن جعفر، نافع عن صفیۃ عن حفصۃ کے طریق سے روایت کرتا ہے۔ باقی تمام تلامذہ، جن کی تعداد تقریباً نو ہے، یہ سب نافع اور حفصہ رضی اللہ عنہما کے درمیان ابن عمر رضی اللہ عنہما کا واسطہ ذکر کرتے ہیں، ہاں عن صفیۃ عن حفصۃ کے بیان میں حضرت سالم بن عبداللہ نافع کی متابعت کرتے ہیں۔ واللہ اعلم۔ (ذخیرۃ العقبٰی شرح سنن النسائی:۱۸؍۱۵۴) اور دوسری روایت:۱۷۶۷ میں غلطی یہ ہے کہ اس میں اوزاعی کے شاگرد شعیب کے بجائے یحییٰ (بن حمزہ) درست ہیں جیسا کہ آئندہ روایت میں مذکور ہے۔ واللہ اعلم۔ تاہم جہاں تک مسئلے کا تعلق ہے، وہ صحیح ہے۔"}],[1767,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اذان اور نماز کے درمیان ہلکی ہلکی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی اذان اور نماز کے درمیان دو ہلکی رکعتیں پڑھتے تھے۔‘‘"}],[1768,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اذان اور اقامت کے درمیان ہلکی ہلکی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم اذان اور اقامت کے درمیان فجر کی دو ہلکی رکعتیں پڑھتے تھے۔"}],[1769,"عبداللہ بن عمر رضی اللہ عنہم کا بیان ہے کہ ام المؤمنین حفصہ رضی اللہ عنہا نے ان سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم اذان اور اقامت کے درمیان ہلکی ہلکی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز کی اذان اور اقامت کے درمیان دو ہلکی رکعتیں پڑھتے تھے"}],[1770,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ مجھے ام المؤمنین حفصہ رضی اللہ عنہا نے خبر دی ہے کہ رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز سے پہلے دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم صبح (کی نماز) سے پہلے دو رکعتیں پڑھتے تھے"}],[1771,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ جب فجر کی اذان کہہ دی جاتی تو رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز سے پہلے دو سجدے کرتے ۱؎۔\n§وضاحت\n۱؎: یعنی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا بتاتی ہیں کہ جب صبح کی نماز کی اذان ہوتی تو رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز سے پہلے دو رکعتیں پڑھا کرتے تھے۔"}],[1772,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب مؤذن خاموش ہو جاتا تو دو ہلکی رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"ام المومنین حضرت حفصہ رضی اللہ عنہا بیان کرتی ہیں کہ جب مؤذن (اذان کہہ کر) خاموش ہوتا تو رسول اللہ صلی اللہ علیہ وسلم دو ہلکی رکعتیں پڑھتے تھے۔"}],[1773,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب مؤذن صبح کی نماز کی اذان کہہ کر خاموش ہو جاتا، اور صبح نمودار ہو جاتی، تو نماز کھڑی ہونے سے پہلے ہلکی ہلکی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"مومنوں کی ماں حضرت حفصہ رضی اللہ عنہا نے بتلایا: جب مؤذن صبح کی اذان کہہ کر خاموش ہوتا اور صبح ظاہر ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم صبح کی نماز کی اقامت سے پہلے دو ہلکی رکعتیں پڑھتے تھے۔"}],[1774,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ مجھ سے میری بہن حفصہ رضی اللہ عنہا نے بیان کیا کہ آپ فجر سے پہلے دو ہلکی رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما فرماتے ہیں کہ مجھ سے میری بہن حضرت حفصہ رضی اللہ عنہا نے بیان کیا کہ آپ صلی اللہ علیہ وسلم فجر کی نماز سے پہلے دو ہلکی رکعتیں پڑھا کرتے تھے۔"}],[1775,"ام المؤمنین حفصہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب فجر طلوع ہو جاتی تو دو رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے روایت ہے کہ جب فجر طلوع ہوتی تو رسول اللہ صلی اللہ علیہ وسلم دو رکعتیں پڑھتے تھے۔"}],[1776,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ جب فجر طلوع ہو جاتی تو رسول اللہ صلی اللہ علیہ وسلم سوائے دو ہلکی رکعتوں کے کچھ اور نہیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے منقول ہے کہ جب فجر طلوع ہوتی تو رسول اللہ صلی اللہ علیہ وسلم صرف دو ہلکی رکعتیں پڑھتے تھے۔","f2":"فجر طلوع ہونے کے بعد عام نوافل سورج بلند ہونے تک منع ہیں۔ صرف صبح کی دو سنتیں ہی مشروع ہیں۔ فرض نماز سے قبل، وہ اگر رہ جائیں تو نماز کے بعد بھی پڑھی جاسکتی ہیں اور کوئی نفل نماز جائز نہیں۔"}],[1777,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب فجر کی اذان دے دی جاتی تو نماز کے لیے کھڑے ہونے سے پہلے ہلکی ہلکی دو رکعتیں پڑھتے۔ اور سالم نے بھی ابن عمر رضی اللہ عنہم سے، اور انہوں نے حفصہ رضی اللہ عنہا سے روایت کی ہے، (ان کی روایت آگے آ رہی ہے)۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا سے مروی ہے کہ جب صبح کی نماز کی اذان ہوتی تو رسول اللہ صلی اللہ علیہ وسلم فرض نماز کو جانے سے پہلے دو ہلکی رکعتیں پڑھتے تھے۔\nیہ روایت حضرت سالم نے بھی (حضرت نافع کے بجائے) ابن عمر عن حفصۃ کی سند سے بیان کی ہے۔","f2":"اب تک یہ روایت حضرت نافع کے واسطے سے ذکر کی گئی ہے، لیکن یہ روایت حضرت نافع کے ساتھی حضرت سالم بھی اسی سند سے بیان کرتے ہیں اب ان کی روایت ذکر کی جارہی ہے۔"}],[1778,"عبداللہ بن عمر رضی اللہ عنہم کہتے ہیں کہ ام المؤمنین حفصہ رضی اللہ عنہا نے مجھے خبر دی ہے کہ رسول اللہ صلی اللہ علیہ وسلم فجر سے پہلے دو رکعتیں پڑھتے تھے اور یہ فجر طلوع ہو جانے کے بعد پڑھتے۔","الألباني: صحيح",{"u2":"حضرت حفصہ رضی اللہ عنہا نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی نماز سے پہلے دو رکعتیں پڑھا کرتے تھے۔ اور یہ (فعل) فجر طلوع ہونے کے بعد ہوتا تھا۔ (یعنی دو رکعتوں کی ادائیگی۔)"}],[1779,"ام المؤمنین حفصہ رضی اللہ عنہا کہتی ہیں کہ جب فجر روشن ہو جاتی تو رسول اللہ صلی اللہ علیہ وسلم دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضر ت حفصہ رضی اللہ عنہا نے بتایا کہ جب فجر روشن ہوجاتی تو رسول اللہ صلی اللہ علیہ وسلم دو رکعتیں پڑھتے تھے۔","f2":"(۱)حضر ت حفصہ رضی اللہ عنہا کی روایت کا یہ صبر آزما تکرار (۱۵دفعہ) سند کے کچھ اختلافات ظاہر کرنے کے لیے ہے۔ محدثین کے لیے یہ چیز بہت اہم اور معلومات افزا ہوتی ہے اگرچہ عام آدمی اسے بے فائدہ سمجھتا ہے۔ سند کے اختلافات سندیں دیکھ کر معلوم ہوسکتے ہیں۔یاد رہے اس اختلاف سے حدیث کی حیثیت مجروح نہیں ہوتی کیونکہ حدیث صحیح سند سے محفوظ ہوتی ہے۔ تکرار کا مقصد یہ ہوتا ہے کہ بعض دوسرے ضعیف راویوں نے سند کے بیان میں جو غلطیاں کی ہیں، وہ واضح ہوجائیں۔ ان کی غلطی سے اصل اور صحیح سند مجروح نہیں ہوتی، لہٰذا عوام الناس کو یہ اختلاف دیکھ کر پریشان نہیں ہونا چاہیے۔ ہر تکرار میں یہ چیز مدنظر رہے۔ (۲)یہ باب اور مسئلہ چند ابواب قبل گزر چکا ہے۔ یہاں دوبارہ اس باب کا ذکر صرف مذکورہ حدیث کی سند کا اختلاف ظاہر کرنے کے لیے ہے۔"}],[1780,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی اذان اور اقامت کے درمیان ہلکی ہلکی دو رکعتیں پڑھتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فجر کی نماز کی اذان اور اقامت کے درمیان دو ہلکی رکعتیں پڑھا کرتے تھے۔","f2":"تہجد کی لمبی لمبی رکعتوں کے بعد تو یہ رکعتیں واقعتاً ہلکی ہی معلوم ہوتی ہیں۔ اگرچہ رسول اللہ صلی اللہ علیہ وسلم انھیں بھی سکون و اطمینان سے ٹھہر ٹھہر کر ہی پڑھتے تھے مگر آپ قراءت ہلکی کرتے تھے، مثلاً: (قل یایھا الکفرون) اور (قل ھواللہ احد)"}],[1781,"ابوسلمہ سے روایت ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں پوچھا؟ تو انہوں نے کہا: آپ تیرہ رکعتیں پڑھتے، پہلے آٹھ رکعتیں پڑھتے، پھر (ایک رکعت) وتر پڑھتے، پھر دو رکعت بیٹھ کر پڑھتے، اور جب رکوع کرنا چاہتے تو کھڑے ہو جاتے، اور رکوع کرتے، اور دو رکعتیں صبح کی نماز کی اذان اور اقامت کے درمیان پڑھتے۔\n§وضاحت\n۱؎: ابوسلمہ سے مراد ابوسلمہ بن عبدالرحمٰن ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ سے روایت ہے، انھوں نے حضرت عائشہ رضی اللہ عنہا سے رسول اللہ صلی اللہ علیہ وسلم کی رات کی نماز کے بارے میں پوچھا تو انھوں نے فرمایا: آپ صلی اللہ علیہ وسلم تیرہ رکعات پڑھتے تھے۔ پہلے آٹھ رکعات پڑھتے، پھر وتر (ایک رکعت) پڑھتے، پھر بیٹھ کر دو پڑھتے لیکن جب رکوع کا ارادہ فرماتے تو کھڑے ہوکر رکوع فرماتے اور دو رکعتیں صبح کی اذان اور اقامت کے درمیان پڑھتے تھے۔"}],[1782,"عبداللہ بن عباس رضی اللہ عنہم کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم جب اذان سنتے تو فجر کی دو رکعتیں پڑھتے، اور انہیں ہلکی پڑھتے تھے۔ ابوعبدالرحمٰن نسائی کہتے ہیں: یہ حدیث منکر ہے ۱؎۔\n§وضاحت\n۱؎: نکارت کی وجہ یہ بیان کی گئی ہے کہ یہ اس مشہور روایت کے مخالف ہے جس میں ہے کہ آپ جب مؤذن اذان سے فارغ ہو جاتا اور صبح نمودار ہو جاتی تو دو ہلکی رکعتیں پڑھتے، لیکن بہتر یہ ہے کہ اسے منکر کے بجائے شاذ کہا جائے، اور اس کی وجہ یہ ہے کہ یہ متن ابن عباس رضی اللہ عنہم سے محفوظ نہیں ہے کیونکہ اسے مسلم نے اپنی صحیح میں «عروۃ عن عائشہ» کے طریق سے روایت کی ہے، اس میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب اذان سن لیتے تو فجر کی دو رکعتیں پڑھتے، اور انہیں ہلکی پڑھتے، اور احتمال اس کا بھی ہے کہ مؤلف کی مراد یہ ہو کہ ابن عباس رضی اللہ عنہم سے جو محفوظ روایت ہے وہ اس متن کے علاوہ ہے، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما فرماتے ہیں کہ نبی صلی اللہ علیہ وسلم جب صبح کی اذان سنتے تو فجر کی دو سنتیں پڑھتے اور انھیں ہلکا پڑھتے تھے۔\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث منکر ہے۔","f2":"امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ یہ حدیث ابن عباس رضی اللہ عنہما سے درست نہیں بلکہ یہ حضرت عائشہ اور حضرت حفصہ رضی اللہ عنہا سے مروی ہے چونکہ اس کی سند میں حبیب بن ابی ثابت مدلس ہیں اور مذکورہ روایت عن سے بیان کرتے ہیں۔ اس وجہ سے یہ قوی اندیشہ ہے کہ سند میں کوئی گڑ بڑ ہوئی ہے۔ یا اس سند کے ساتھ حضرت ابن عباس رضی اللہ عنہما سے یہ حدیث نہیں آتی، کوئی اور آتی ہے۔ (دونوں توجیہات کے فرق کو غور سے سمجھا جائے۔)"}],[1783,"سائب بن یزید رضی اللہ عنہ کہتے ہیں کہ شریح حضرمی کا ذکر رسول اللہ صلی اللہ علیہ وسلم کے پاس کیا گیا تو آپ نے فرمایا: \"وہ قرآن کو تکیہ نہیں بناتے\"۔\n§وضاحت\n۱؎: قرآن کو تکیہ بنانے کے دو معنی ہیں، ایک تو یہ کہ وہ رات کو سوتے نہیں بلکہ رات بھر عبادت کرتے ہیں، دوسرا معنی یہ ہے کہ وہ قرآن کو یاد نہیں رکھتے، اور اس کی قرات پر مداومت نہیں کرتے، پہلے معنی میں شریح کی تعریف ہے، اور دوسرے میں ان کی مذمت ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت سائب بن یزید سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس حضرت شریح حضرمی رضی اللہ عنہ کا ذکر کیا گیا تو آپ نے فرمایا: ’’وہ قرآن کو سرہانہ نہیں بناتا۔‘‘","f2":"(۱) یہ الفاظ مدح بھی بن سکتے ہیں اور مذمت بھی۔ مدح اس طرح کہ وہ قرآن کی توہین نہیں کرتا کہ اسے سرہانے کی طرح نیچے پھینک دے یا اس پر سر رکھ لے بلکہ وہ اس کی تعظیم و توقیر کرتا ہے۔ اور مذمت اس طرح کہ وہ قرآن کو سرہانے کی طرح لازم نہیں پکڑتا، یعنی پابندی اور ہمیشگی سے اس کی دلجمعی سے تلاوت نہیں کرتا۔ (۲) [لایتوسد القران] کا ایک ترجمہ یہ بھی کیا گیا ہے کہ قرآن اس کے ساتھ سرہانہ نہیں بنتا۔ (اس صورت میں قرآن فاعل ہوگا) اس معنی کو بھی تعریف اور مذمت دونوں پر محمول کیا جا سکتا ہے۔ تعریف اور مدح اس طرح کہ قرپن حفظ کرنے کے بعد وہ سویا نہیں رہتا کہ قرآن سرہانہ، یعنی نیند کا ذریعہ بن جائے بلکہوہ قرآن کے ساتھ جاگتا ہے، یعنی اسے پڑھتا ہے اور اسے یاد رکھتا ہے۔ اور مذمت اس طرح کہ اسے قرآن حفظ نہیں اور وہ اسے پڑھتا نہیں کہ جب وہ سوئے تو سرہانے کی طرح قرآن بھی اس کے ساتھ ہو۔ (۳) اس روایت کا باب، یعنی فجر کی سنتوں کے وقت سے کوئی تعلق نہیں، البتہ رات کی نماز سے تعلق ہے کہ وہ قابل تعریف چیز ہے اور رات کی نماز سے سوئے رہنا قابل مذمت ہے۔ رات کی نماز تمام گزشتہ نیک لوگوں کا دستور اور معمول رہا ہے۔"}],[1784,"سعید بن جبیر ایک ایسے شخص سے روایت کرتے ہیں جو ان کے نزدیک پسندیدہ ہے اس نے انہیں خبر دی کہ ام المؤمنین عائشہ رضی اللہ عنہا نے انہیں خبر دی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو بھی آدمی رات کو تہجد پڑھا کرتا ہو، پھر کسی دن نیند کی وجہ سے وہ نہ پڑھ سکے تو اللہ تعالی اس کے لیے اس کی نماز کا اجر لکھ دیتا ہے، اور اس کی نیند اس پر صدقہ ہوتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت سعید بن جبیر سے روایت ہے کہ انھیں ان کے نزدیک پسندیدہ شخص نے بتایا کہ ان کو حضرت عائشہ رضی اللہ عنہا نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس شخص کو رات کو نفل نماز پڑھنے کی عادت ہو، پھر کسی دن اس پر نیند غالب آ جائے (اوروہ نفل نماز نہ پڑھ سکے) تو اللہ تعالیٰ (اس دن بھی) اس (معمول کی) نماز کا اجر اس کے لیے لکھ دیتا ہے اور اس کی نیند اس کے لیے (اللہ تعالیٰ کی طرف سے) صدقہ بن جاتی ہے۔‘‘","f2":"سند میں مذکور ’’پسندیدہ شخص‘‘ حضرت اسود بن یزید ہیں۔ آئندہ حدیث کی سند میں اس کی صراحت ہے۔"}],[1785,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی رات میں کسی نماز کا عادی ہو، اور کسی رات وہ نیند کی وجہ سے اسے نہ پڑھ سکے، تو یہ اس پر اللہ کی طرف سے کیا ہوا صدقہ ہو گا، اور وہ اس کے لیے اس کی نماز کا اجر لکھے گا\" ۱؎۔\n§وضاحت\n۱؎: اس روایت کی سند میں غور کرنے سے معلوم ہوا کہ گذشتہ سند میں سعید بن جبیر کے نزدیک پسندیدہ شخص کا نام اسود بن یزید ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس آدمی کی کوئی مقرر شدہ نماز ہو جسے وہ لازماً رات کو پڑھتا ہو لیکن کسی دن (اتفاقاً) وہ سویا رہا (اور اسے نہ پڑھ سکا) تو نیند اس کے لیے صدقہ ہوگی جو اللہ تعالیٰ نے اس پر کیا ہے اور وہ اس کے لیے اس کی (مقررہ) نماز کا ثواب لکھے گا۔‘‘","f2":"سابقہ حدیث کی سند میں حضرت سعید بن جبیر اورحضرت عائشہ رضی اللہ عنہا کے درمیان ایک شخص کا واسطہ تھا جس کا نام ذکر کرنے کے بجائے صرف ’’پسندیدہ شخص‘‘ کہا گیا، مذکورہ حدیث میں اس کا نام مذکور ہے، اوروہ ہے اسود بن یزید، لہٰذا یہ عنوان قائم کیا۔"}],[1786,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: پھر انہوں نے اسی طرح کی حدیث ذکر کی۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابو جعفر رازی حدیث میں قوی نہیں ہیں، (اسی لیے سند میں سے ایک راوی \"اسود\" کو ساقط کر دیا ہے)۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: پھر اسی طرح بیان کیا جیسے پہلے بیان ہوا ہے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ اس حدیث کی سند میں ایک راوی ابوجعفر رازی ہے جو علم حدیث میں قوی اور معتبر نہیں۔","f2":"امام نسائی رحمہ اللہ گویا ابوجعفر راوی کے واسطے سے منقول اس طریق کی تضعیف فرما رہے ہیں، لیکن اس سے صحت حدیث متاثر نہیں ہوتی کیونکہ اس کے شواہد ملتے ہیں۔ واللہ أعلم۔"}],[1787,"ابو الدرداء رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو بستر پر آئے، اور وہ رات میں قیام کی نیت رکھتا ہو، پھر اس کی دونوں آنکھیں اس پر غالب آ جائیں یہاں تک کہ صبح ہو جائے تو اس کے لیے اس کی نیت کا ثواب لکھا جائے گا، اور اس کی نیند اس کے رب عزوجل کی جانب سے اس پر صدقہ ہو گی\"۔ سفیان ثوری نے حبیب بن ابی ثابت کی مخالفت کی ہے۔","الألباني: صحيح",{"u2":"حضرت ابودرداء رضی اللہ عنہ سے روایت ہے اور وہ اسے نبی صلی اللہ علیہ وسلم تک پہنچاتے تھے، آپ نے فرمایا: ’’جو آدمی بستر پر لیٹتے وقت نیت رکھتا ہو کہ رات کو (نماز تہجد کے لیے) اٹھے گا لیکن اسےگہری نیند آگئی اور وہ صبح تک سویا رہا تو اس کے لیے اس نماز کا ثواب لکھا جائے گا جس کی اس نے نیت کی اور اس کی نیند اس کے رب عزوجل کی طرف سے اس پر نوازش ہوگی۔‘‘\nسفیان نے اس روایت میں حبیب بن ابی ثابت کی مخالفت کی ہے۔","f2":"حبیب نے یہ روایت مرفوع (فرمانِ رسول اللہ صلی اللہ علیہ وسلم) بیان کی تھی جبکہ سفیان اسے موقوف (صحابی کا فرمان) بیان کرتے ہیں۔ دوسرے سفیان یہ روایت شک کے ساتھ بیان کرتے ہیں، نیز سنن نسائی کے تمام نسخوں میں عن أبي ذر و أبي الدرداء ہے۔ یہ سند میں تصحیف ہے۔ درست بجائے واو کے او ہے، یعنی شک کے ساتھ، جیسا کہ السنن الکبریٰ للنسائی میں ہے: (۴۵۷/۱) سنن کبریٰ میں سفیان ثوری کے ساتھ سفیان بن عیینہ بھی ہیں، گویا دونوں ہی حبیب بن ابی ثابت کی مذکورہ مخالفات میں شریک ہیں۔ تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۱۷۱/۱۸، ۱۷۲) یہ وضاحت تو سندی اختلاف کی تھی۔ رہی صحت حدیث تو بلاشک متن حدیث قابل حجت ہے۔ شیخ البانی رحمہ اللہ کی تحقیق کے مطابق یہ روایت موقوفاً أصح ہے، لیکن چونکہ اس میں راوی کے اجتہاد اور رائے کا دخل نہیں، اس لیے حکماً مرفوع ہے، نیز اس کے شواہد بھی ملتے ہیں۔ اس کی تفصیل کے لیے ملاحظہ فرمائیے: (إرواء الغلیل الألبانی، رقم الحدیث: ۴۵۴)"}],[1788,"اور سفیان ثوری (کی حبیب بن ابی ثابت سے مخالفت یہ ہے کہ انہوں) نے اس سند سے یہ حدیث ابوذر اور ابو الدرداء رضی اللہ عنہم سے موقوفاً روایت کی ہے۔","الألباني: صحيح",{"u2":"سفیان ثوری نے اس روایت کو حضرت ابوذر اور حضرت ابودرداء رضی اللہ عنہما کا اپنا قول (یعنی موقوف) بیان کیا ہے۔"}],[1789,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو نماز نہیں پڑھ پاتے خواہ نیند نے آپ کو اس سے روکا ہو یا کسی تکلیف نے تو دن کو آپ بارہ رکعتیں پڑھتے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب رات کو نفل نماز نہ پڑھ سکتے، یعنی نیند یا تکلیف کا غلبہ ہو جاتا تو دن کو بارہ رکعات پڑھتے۔","f2":"رسول اللہ صلی اللہ علیہ وسلم عموماً گیارہ رکعات پڑھتے تھے، لیکن جب کبھی مذکورہ وجوہات کی بنا پر رات کی یہ نماز نہ پڑھ سکتے تو دن کے وقت گیارہ کی بجائے ایک رکعت کا اضافہ فرما کر ان کو جفت بنا لیتے اور بارہ رکعات پڑھ لیتے۔ اگر گیارہ کی بجائے دس پڑھتے تو نوافل میں کمی رہ جاتی لیکن آپ نے کمی کو پسند نہیں فرمایا۔"}],[1790,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کوئی رات کو اپنے وظیفہ سے، یا اس کی کسی چیز سے سو جائے، پھر وہ اسے فجر سے لے کر ظہر تک کے درمیان پڑھ لے، تو اس کے لیے یہی لکھا جائے گا کہ گویا اس نے اسے رات ہی میں پڑھا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص رات کو اپنی مقرر شدہ مکمل یا کچھ نماز سے یوا رہا (نہ پڑھ سکا) پھر وہ اسے فجر کی نماز (طلوع شمس) ہے نماز ظہر تک پڑھ لے تو اس کا ثواب یوں لکھا جائے گا گویا اس نے رات کو پڑھی۔‘‘","f2":"البتہ دو چیزیں ملحوظ رکھے۔ وقت نفل نماز کے لیے مکروہ نہ ہو اور طاق کی بجائے ایک رکعت زائد کر کے جفت پڑھے۔ یہ تب ہے جب رات کے نوافل کی ادائیگی کرنی ہو، لیکن اگر صرف وتر کی ادائیگی ہی مقصود ہے تو طاق وتر پڑھنے میں کوئی حرج نہیں۔ واللہ أعلم۔"}],[1791,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں جو کوئی رات کو اپنا وظیفہ پڑھے بغیر سو جائے، پھر وہ صبح سے ظہر تک کے درمیان کسی بھی وقت اسے پڑھ لے، تو گویا اس نے اسے رات ہی میں پڑھا ہے۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ فرماتے ہیں، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص رات کو اپنی معمول کی مکمل یا کچھ نفل نماز سے سویا رہا، پھر اس نے اسے صبح کی نماز (کا وقت ختم ہونے اور مکروہ وقت گزرنے کے بعد) سے ظہر کی نماز تک پڑھ لیا تو یوں سمجھو، اس نے رات ہی کو پڑھی۔‘‘","f2":"یعنی ثواب کے لحاظ سے۔ اور یہ الفہ تعالیٰ کرم نوازی ہے، نیز معلوم ہوا کہ رات کو نماز (نفل) پڑھنے کا ثواب دن کو پڑھنے سے بہت زیادہ ہے علاوہ معذور شخص کے۔"}],[1792,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں جس کا رات کا وظیفہ چھوٹ جائے، اور وہ سورج ڈھلنے سے لے کر نماز ظہر تک کسی بھی وقت اسے پڑھ لے، تو اس کا وظیفہ نہیں چھوٹا، یا گویا اس نے اپنا وظیفہ پا لیا۔ اسے حمید بن عبدالرحمٰن نے موقوفاً (یعنی: مقطوعا) روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ فرماتے ہیں کہ جس شخص سے رات کی مقررہ (نفل) نماز رہ گئی اور اس نے زوال شمس سے لے کر ظہر کی نماز تک پڑھ لی تو یوں سمجھو کہ وہ نماز اس سے نہیں رہی بلکہ گویا اس نے بروقت پڑھ لی۔\nحضرت عبدالرحمن بن عوف رضی اللہ عنہ کے بیٹے حمید نے اسے موقوف بیان کیا ہے۔","f2":"(۱) مقصود یہ ہے کہ آئندہ روایت میں یہی الفاظ حمید کی طرف منسو ب ہیں۔ حمید تابعی ہیں اور تابعی کے قول و فعل کو مقطوع کہا جاتا ہے، گویا یہاں موقوف سے مقطوع مراد ہے۔ (۲) ہمارے نسخے کے مطابق عبارت کا بظاہر وہی مفہوم ہے جو ذکر ہوا۔ ذخیرۃ العقبی شرح سنن النسائي: (۱۷۸/۱۸) کے نسخے میں حمید بن عبدالرحمٰن حضرت عمر رضی اللہ عنہ سے بیان کرتے ہیں، اگر یہ اضافہ درست ہے تو پھر موقوف اپنے اصطلاحی معنی میں مستعمل ہے۔ واللہ أعلم۔ (۳) ضروری نہیں نماز ہی مراد ہو بلکہ قرآن مجید یا ذکر و درود بھی مراد ہو سکتا ہے اور اس کا حکم بھی یہی ہے۔ (۴) اس روایت میں زوال شمس کا لفظ کسی راوی کی غلطی ہے، طوع شمس چاہیے جیسے پہلی روایات میں ہے۔ (۵) باب کے تحت ان تین رووایات میں فرق یہ ہے کہ پہلی ااور دوسری روایت رسول اللہ صلی اللہ علیہ وسلم کی طرف منسوب ہے اور آخرت حضرت عمر رضی اللہ عنہ کی طرف اور آئندہ روایت صحابی کی بجائے تابعی (حمید) کی طرف منسوب ہے۔ پہلی کو مرفوع دوسری کو موقوف اور تیسری کو مقطوع کہتے ہیں۔"}],[1793,"حمید بن عبدالرحمٰن کہتے ہیں جس کا رات کا وظیفہ چھوٹ جائے، تو اسے چاہیئے کہ وہ ظہر سے پہلے کسی نماز میں اسے پڑھ لے، کیونکہ یہ رات کی نماز کے برابر ہو گا۔","الألباني: صحيح مقطوع",{"u2":"حضرت حمید بن عبدالرحمن بیان کرتے ہیں کہ جس آدمی کا رات کا مقرر ورد (ذکر، قرپن یا نماز) رہ جائے تو وہ اسے ظہر کی نماز سے پہلے کسی (نفل) نماز میں پڑھ لے تو یہ نماز بھی رات کی نماز کے برابر ہی متصور ہوگی۔"}],[1794,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو دن رات میں بارہ رکعتوں پر مداومت کرے گا، وہ جنت میں داخل ہو گا: چار رکعتیں ظہر سے پہلے، دو رکعتیں اس کے بعد، دو رکعتیں مغرب کے بعد، دو رکعتیں عشاء کے بعد اور دو رکعتیں فجر سے پہلے\" ۱؎۔\n§وضاحت\n۱؎: فرض نماز سے پہلے یا اس کے بعد جو سنتیں پڑھی جاتی ہیں ان کی دو قسمیں ہیں، ایک قسم وہ ہے جس پر نبی اکرم صلی اللہ علیہ وسلم نے مداومت فرمائی ہے بعض روایتوں میں ان کی تعداد دس بیان کی گئی ہے، اور بعض میں بارہ، اور بعض میں چودہ، انہیں سنن مؤکدہ یا سنن رواتب کہا جاتا ہے، دوسری قسم وہ ہے جس پر آپ نے مداومت نہیں کی ہے انہیں نوافل یا غیر موکدہ کہا جاتا ہے، اللہ تعالی سے مزید تقرب کے لیے نوافل یا غیر مؤکدہ سنتوں کی بھی بڑی اہمیت ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دن اور رات میں بارہ رکعات (سنت) پر پابندی کرے گا، وہ جنت میںداخل ہوگا۔ (ان کی ترتیب یوں ہے:) ظہر سے پہلے چار اور بعد میں دو، مغرب کے بعد دو، عشاء کے بعد دو اور فجر (کی نماز) سے پہلے دو۔‘‘","f2":"فائدہ:\nانھیں سنن مؤکدہ کہا جاتا ہے کیونکہ نبی صلی اللہ علیہ وسلم نے انھیں پابندی سے پڑھا ہے۔ اگر کبھی کچھ رہ گئیں تو ان کی قضا دی ہے، لہٰذا ان میں سستی نہیں کرنی چاہیے۔ سنت مؤکدہ کو بلاعذر چھوڑ دینا قابل ملامت ہے۔ عذر سے مراد سفر، مرض یا شدید مصروفیت وغیرہ ہے۔"}],[1795,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص پابندی سے بارہ رکعتوں پر مداومت کرے گا، اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا: چار رکعتیں ظہر سے پہلے، دو رکعتیں اس کے بعد، دو رکعتیں مغرب کے بعد، دو رکعتیں عشاء کے بعد، اور دو رکعتیں فجر سے پہلے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص بارہ رکعات پر پابندی اور ہمیشگی کرے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔ (ان کی ترتیب یوں ہے:) ظہر سے پہلے چار اور بعد میں دو، مغرب کی نماز کے بعد دو، عشاء کے بعد دو اور فجر کی نماز سے پہلے دو۔‘‘"}],[1796,"ام المؤمنین ام حبیبہ بنت ابی سفیان رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے فرض کے علاوہ دن رات میں بارہ رکعتیں پڑھیں، اللہ تعالی اس کی وجہ سے اس کے لیے جنت میں ایک گھر بنائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ بنت ابوسفیان رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے ہوئے سنا ہے: ’’جو شخص دن اور رات میں فرض نمازوں کے علاوہ بارہ رکعات (سنت) پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔‘‘"}],[1797,"ابن جریج کہتے ہیں کہ میں نے عطا سے کہا: مجھے یہ بات پہنچی ہے کہ آپ جمعہ سے پہلے بارہ رکعتیں پڑھتے ہیں۔ اس سلسلے میں آپ کو کیا معلوم ہوا ہے؟ انہوں نے کہا: مجھے خبر دی گئی ہے کہ ام حبیبہ رضی اللہ عنہا نے عنبسہ بن ابی سفیان سے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا ہے: \"جس نے رات دن میں فرض کے علاوہ بارہ رکعتیں پڑھیں، تو اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ابن جریج بیان کرتے ہیں کہ میں نے حضرت عطاء سے کہا: مجھے یہ بات پہنچی ہے کہ آپ جمعے سے پہلے بارہ رکعات پڑھتے ہیں۔ اس سلسلے میں آپ کو کون سی روایت پہنچی ہے؟ انھوں نے فرمایا: مجھے بتایا گیا ہے کہ حضرت ام حبیبہ رضی اللہ عنہا نے حضرت عنبسہ بن ابوسفیان کو کہا کہ نبی صلی اللہ علیہ وسلم نے فرمای: ’’جو آدمی دن اور رات میں فرض نمازوں کے علاوہ بارہ رکعات (سنت) پڑھے گا، اللہ عزوجل اس کے لیے جنت میں گھر بنائے گا۔‘‘","f2":"ان بارہ رکعات سے رسول اللہ صلی اللہ علیہ وسلم کی مراد گزشتہ احادیث میں گزر چکی ہے۔ حضرت عطاء نے اسے عام سمجھا مگر یہ درست نہیں۔"}],[1798,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جس نے ایک دن میں بارہ رکعتیں پڑھیں، اللہ عزوجل اس کے لیے جنت میں ایک گھر بنائے گا\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں کہ عطا نے اسے عنبسہ سے نہیں سنا ہے (اس کی دلیل آگے آ رہی ہے)۔","الألباني: صحيح لغيره",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا فرماتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جو شخص ایک دن میں بارہ رکعات (سنن مؤکدہ) پڑھے گا، اللہ عزوجل اس کے لیے جنت میں گھر بنائے گا۔‘‘\nامام ابوعبدالرحمًن (نسائی) رحمہ اللہ فرماتے ہیں کہ حضرت عطاء نے عنبسہ سے نہیں سنا۔ (جیساا کہ آئندہ روایت سے صاف ظاہر ہو رہا ہے کہ درمیان میں حضرت یعلی بن امیہ کا واسطہ ہے۔)"}],[1799,"یعلی بن امیہ کہتے ہیں کہ میں طائف آیا، تو عنبسہ بن ابی سفیان کے پاس گیا، اور وہ مرنے کے قریب تھے، میں نے انہیں دیکھا کہ وہ گھبرائے ہوئے ہیں، میں نے کہا: آپ تو اچھے آدمی ہیں، اس پر انہوں نے کہا مجھے میری بہن ام حبیبہ رضی اللہ عنہا نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دن یا رات میں بارہ رکعتیں پڑھیں، تو اللہ تعالی اس کے لیے جنت میں گھر بنائے گا\"۔ ابویونس قشیری نے ان لوگوں کی جنہوں نے اسے عطا سے روایت کی ہے مخالفت کی ہے، (ان کی روایت آگے آ رہی ہے)۔","الألباني: صحيح الإسناد",{"u2":"حضرت یعلی بن امیہ فرماتے ہیں کہ میں طائف میں آیا تو حضرت عنبسہ بن ابوسفیان کے پاس گیا جبکہ وہ قریب الموت تھے۔ میں نے ان میں گھبراہٹ محسوس کی تو میں نے کہا: (مت گھبرائیں) آپ نیکی پر قائم ہیں (یا ان شاء اللہ آپ سے اچھا سلوک ہوگا)۔ انھوں نے فرمایا: مجھے میری ہمشیرہ محترمہ حضرت ام حبیبہ رضی اللہ عنہا نے خبر دی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دن رات میں بارہ رکعات (سنن مؤکدہ) پڑھے گا، الل عزوجل اس کے لیے جنت میں ایک گھر بنا دے گا۔‘‘\nابو یونس قشیری نے ان سب کی مخالفت کی ہے","f2":"(۱) ابو یونس قشیری حضرت عطاء کے شاگرد ہیں۔ انھوں نے حضرت عطاء بن ابی رباح کا استاد شہر بن حوشب ذکر کرکے حضرت عطاء کے دوسرے شاگردوں کی مخالفت کی ہے جن کی روایات ابھی گزری ہیں۔ دوسرا فرق یہ ہے کہ ابو یونس نے روایت میں رسول اللہ صلی اللہ علیہ وسلم کا ذکر نہیں کیا۔ گویا روایت مرفوع کے بجائے موقوف ذکر کی جبکہ دوسرے شاگرد اسے مرفوع بیان کرتے ہیں۔ (۲) یعنی و جنت میں داخل ہوگا ورنہ گھر کا کیا فائدہ؟ نیز امید ہے کہ اولیں طور پر داخل ہوگا ورنہ مطلق دخول تو محق ایمان کی بنا پر بھی ہے۔ واللہ أعلم۔"}],[1800,"ام المؤمنین ام حبیبہ بنت ابی سفیان رضی اللہ عنہم کہتی ہیں کہ جس نے ایک دن میں بارہ رکعتیں ظہر سے پہلے پڑھیں، تو اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا۔","الألباني: صحيح لغيره",{"u2":"حضرت ام حبیبہ بنت ابو سفیان رضی اللہ عنہا فرماتی ہیں کہ جو آدمی ایک دن میں بارہ رکعات پڑھے۔ ظہر سے پہلے (چار، بعد میں دو، مغرب کے بعد دو، عشاء کے بعد دو اور فجر سے پہلے دو) تو اللہ تعالیٰ اس کے لیے جنت میں ایک گھر بنائے گا۔","f2":"’’ظہر سے پہلے‘‘ یہ معنی اس حدیث کو دوسری حدیث کے مطابق کرنے کے لیے کیا گیا ہے۔"}],[1801,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بارہ رکعتیں ہیں، جو انہیں پڑھے گا، اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا: چار رکعتیں ظہر سے پہلے، دو رکعتیں ظہر کے بعد، دو رکعتیں عصر سے پہلے، دو رکعتیں مغرب کے بعد، اور دو رکعتیں نماز فجر سے پہلے\" ۱؎۔\n§وضاحت\n۱؎: اس روایت میں :(اور اس کے بعد دونوں روایتوں میں جو دراصل ایک ہی روایت ہے ) عشاء کے بعد دو رکعت کے بجائے عصر سے پہلے دو رکعت کا ذکر ہے، جو سنداً ضعیف ہے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بارہ رکعات ایسی ہیں کہ جو شخص انھیں (پابندی سے) پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنا دے گا۔ چار رکعات ظہر سے پہلے اور دو بعد میں، مغرب کی نماز کے بعد دو رکعات، عشاء کی نماز کے بعد دو رکعات اور فجر کی نماز سے پہلے دو رکعات۔‘‘"}],[1802,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے بارہ رکعتیں پڑھیں، اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا: چار رکعتیں ظہر سے پہلے، دو اس کے بعد، دو عصر سے پہلے، دو مغرب کے بعد اور دو صبح سے پہلے\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: فلیح بن سلیمان زیادہ قوی نہیں ہیں۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی بارہ رکعات (سنت) پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔ ظہر سے ہلے چار، بعد میں دو، عصر سے پہلے دو، مغرب کے بعد دو اور صبح کی نماز سے پہلے دو۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ (سند میں مذکور راوی) فلیح بن سلیمان قومی نہیں۔","f2":"یہ روایت سندا ضعیف ہے، اس روایت میں عشاء کے بعد دو کی بجائے عصر سے پہلے دو کا ذکر راوی کی غلطی ہے اوروہ فلیح بن سلیمان ہے جو ضعیف ہے۔ امام نسائی رحمہ اللہ نے اسے [لیس بالقوي] ’’وہ قوی نہیں‘‘ کہا ہے، امام بخاری رحمہ اللہ نے اپنی صحیح میں اسے متابعات میں قبول کیا ہے۔"}],[1803,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں کہ جس نے دن اور رات میں فرض کے علاوہ بارہ رکعتیں پڑھیں تو اس کے لیے جنت میں ایک گھر بنایا جائے گا: چار ظہر سے پہلے، اور دو رکعتیں اس کے بعد، دو عصر سے پہلے، دو مغرب کے بعد، اور دو فجر سے پہلے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا فرماتی ہیں کہ جو شخص دن اور رات میں فرض نماز کے علاوہ بارہ رکعات (سنن مؤکدہ) پڑھے گا، اس کے لیے جنت میں گھر بنا دیا جائے گا: ظہر سے پہلے چار، بعد میں دو، عصر سے پہلے دو، مغرب کے بعد دو اور صبح سے پہلے دو۔‘‘"}],[1804,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دن اور رات میں بارہ رکعتیں پڑھیں، اس کے لیے جنت میں ایک گھر بنایا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دن اور رات میں بارہ رکعات پڑھے گا، اس کے لیے جنت میں گھر بنایا جائے گا۔‘‘","f2":"اسماعیل کے شاگرد یزید بن ہارون نے اس روایت کو مرفوع بیان کیا ہے جبکہ یعلی اور عبداللہ نے اسے موقوف بیان کیا ہے جیسا کہ آئنندہ تین روایات سے صاف ظاہر ہے۔"}],[1805,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں جس نے رات اور دن میں فرض کے علاوہ بارہ رکعتیں پڑھیں، اس کے لیے جنت میں ایک گھر بنایا جائے گا۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا فرماتی ہیں کہ جو شخص رات اور دن میں فرضوں کے علاوہ بارہ رکعات پڑھے گا، اس کے لیے جنت میں گھر بنایا جائے گا۔"}],[1806,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں جس نے دن اور رات میں فرض کے علاوہ بارہ رکعتیں پڑھیں، تو اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا۔ حصین نے اسے مرفوع نہیں کیا ہے، اور عنبسہ اور مسیب کے درمیان انہوں نے ذکوان کو داخل کر دیا ہے۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا فرماتی ہیں کہ جو شخص دن اور رات میں فرضوں کے علاوہ بارہ رکعات (سنن مؤکدہ) پڑھے گا، اللہ عزوجل اس کے لیے جنت کے اندر گھر بنائے گا۔ حصین نے اس حدیث کو مرفوع بیان نہیں کیا، نیز اس نے عنبسہ اور مسیب کے درمیان ذکوان کا واسطہ بیان کیا ہے۔"}],[1807,"ابوصالح ذکوان کہتے ہیں کہ عنبسہ بن ابی سفیان نے مجھ سے بیان کیا کہ ام حبیبہ رضی اللہ عنہا نے ان سے بیان کیا ہے: جس نے ایک دن میں بارہ رکعتیں پڑھیں، اس کے لیے جنت میں ایک گھر بنایا جائے گا۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا بیان کرتی ہیں کہ جو شخص ایک دن میں بارہ رکعات پڑھے گا، اس کے لیے جنت میں گھر بنایا جائے گا۔"}],[1808,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ایک دن میں فرض کے علاوہ بارہ رکعتیں پڑھیں اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا، یا اس کے لیے جنت میں ایک گھر بنایا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی ایک دن میں فرض نمازوں کے علاوہ بارہرکعات پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔‘‘ یا (فرمایا:) ’’اس کے لیے جنت میں گھر بنا دیا جائے گا۔‘‘"}],[1809,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے دن اور رات میں بارہ رکعتیں پڑھیں، تو اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ایک دن رات میں بارہ رکعات پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔‘‘"}],[1810,"ام المؤمنین ام حبیبہ رضی اللہ عنہا کہتی ہیں جس نے ایک دن میں بارہ رکعتیں پڑھیں، اس کے لیے جنت میں ایک گھر بنایا جائے گا۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا فرماتی ہیں کہ جو آدمی دن میں بارہ رکعات پڑھے گا، اس کے لیے جنت میں گھر بنایا جائے گا۔"}],[1811,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ایک دن میں بارہ رکعتیں فرض کے علاوہ پڑھیں، تو اللہ تعالی اس کے لیے جنت میں ایک گھر بنائے گا\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ غلط ہے، محمد بن سلیمان ضعیف ہیں، وہ اصبہانی کے بیٹے ہیں، نیز یہ حدیث اس سند کے علاوہ سے بھی ان الفاظ کے علاوہ کے ساتھ جن کا ذکر اوپر ہوا ہے روایت کی گئی ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص دن میں فرضوں کے علاوہ بارہ رکعات پڑھے گا، اللہ تعالیٰ اس کے لیے جنت میں گھر بنائے گا۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ فرماتے ہیں کہ یہ روایت درست نہیں (یعنی اس میں حضرت ابوہریرہ رضی اللہ عنہ کا ذکر صحیح نہیں ہے بلکہ ام المومنین سیدہ ام حبیبہ رضی اللہ عنہا کا ذکر صحیح ہے۔ اور اس حدیث کا ایک راوی) محمد بن سلیمان ضعیف ہے۔ وہ ابن الاصبہانی ہے۔ یہ روایت اس سند (مذکورہ) کے علاوہ کئی سندوں سے بیان کی گئی ہے مگر ان میں مذکورہ الفاظ نہیں ہیں۔"}],[1812,"حسان بن عطیہ کہتے ہیں کہ جب عنبسہ کی موت کا وقت آیا تو وہ تکلیف سے پیچ و تاب کھانے لگے تو ان سے کچھ پوچھا گیا، تو انہوں نے کہا: سنو! میں نے ام المؤمنین ام حبیبہ رضی اللہ عنہا کو سنا وہ نبی اکرم صلی اللہ علیہ وسلم کے واسطہ سے بیان کر رہی تھیں کہ آپ نے فرمایا ہے: \"جس نے ظہر سے پہلے چار رکعتیں، اور اس کے بعد چار رکعتیں پڑھیں، تو اللہ تعالی اس کا گوشت جہنم کی آگ پر حرام کر دے گا، تو جب سے میں نے انہیں سنا ہے میں نے انہیں چھوڑا نہیں\"۔","الألباني: صحيح",{"u2":"حضرت حسان بن عطیہ سے منقول ہے کہ جب حضرت عنبسہ بن ابوسفیان کی وفات قریب ہوئی تو وہ تڑپنے لگے۔ ان سے کہا گیا (یعنی ان کو تسکین دی گئی) تو انھوں نے فرمایا: میں نے نبی صلی اللہ علیہ وسلم کی زوجۂ محترمہ حضرت ام حبیبہ رضی اللہ عنہا کو نبی صلی اللہ علیہ وسلم سے یہ بیان فرماتے ہوئے سنا ہے: ’’جس شخص نے ظہر سے پہلے چار رکعات اور ظہر کے بعد چار رکعات پڑھیں، اللہ تعالیٰ اس کا گوشت آگ پر حرام کر دے گا۔‘‘ جب سے میں نے یہ روایت سنی ہے، میں نے یہ رکعات نہیں چھوڑیں۔"}],[1813,"عنبسہ بن ابی سفیان کہتے ہیں کہ میری بہن ام المؤمنین ام حبیبہ رضی اللہ عنہا نے مجھے بتایا کہ ان کے محبوب ابوالقاسم صلی اللہ علیہ وسلم نے انہیں بتایا: جو بھی مومن بندہ ظہر کے بعد چار رکعتیں پڑھے گا، تو جہنم کی آگ اس کے چہرے کو کبھی نہیں چھوئے گی، اگر اللہ عزوجل نے چاہا۔","الألباني: صحيح لغيره",{"u2":"حضرت عنبسہ بن ابوسفیان بیان کرتے ہیں کہ مجھے نبی صلی اللہ علیہ وسلم کی زوجۂ محترمہ اور میری ہمشیرہ حضرت ام حبیبہ رضی اللہ عنہا نے بیان کیا کہ میرے محبوب ابوالقاسم صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’جو بھی مومن شخص ظہر کے بعد چار رکعات پڑھتا ہے تو ان شاء اللہ کبھی بھی اس کے چہرے کو آگ نہیں چھوئے گی۔‘‘"}],[1814,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرماتے تھے: \"جس نے ظہر سے پہلے چار رکعتیں پڑھیں، اور اس کے بعد چار رکعتیں پڑھیں، تو اللہ تعالی اسے جہنم پر حرام کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم فرمایا کرتے تھے: ’’جوشخص ظہر سے پہلے چار رکعات اور ظہر کے بعد چار رکعات (پابندی سے) پڑھے گا تو اللہ تعالیٰ اسے آگ پر حرام فرما دے گا۔‘‘"}],[1815,"ام المؤمنین ام حبیبہ رضی اللہ عنہا سے روایت ہے، مروان بن محمد کہتے ہیں: اور سعید بن عبدالعزیز پر جب پڑھا گیا کہ ام حبیبہ نبی اکرم صلی اللہ علیہ وسلم سے روایت کرتی ہیں تو انہوں نے اس کا اقرار کیا، اور انکار نہیں کیا حالانکہ جب انہوں نے اسے ہم سے بیان کیا تو انہوں نے اسے مرفوع نہیں کیا، وہ کہتی ہیں: جس نے ظہر سے پہلے چار رکعتیں، اور اس کے بعد چار رکعتیں پڑھیں تو اللہ تعالی اسے جہنم پر حرام کر دے گا۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: مکحول نے عنبسہ سے کچھ نہیں سنا ہے۔","الألباني: صحيح",{"u2":"حضرت مروان نے کہا کہ جب یہ روایت [عنبسۃ عن ام حبیبۃ عن النبی صلی اللہ علیہ وسلم] ہمارے استاد سعید بن عبدالعزیز پر پڑھی جاتی تھی تو وہ اس کا انکار نہیں کرتے تھے بلکہ اسے برقرار رکھتے تھے۔ لیکن جب وہ خود یہ روایت بیان فرماتے تھے تو رسول اللہ صلی اللہ علیہ وسلم کا ذکر فرماتے تھے بلکہ کہتے تھے کہ حضرت ام حبیبہ رضی اللہ عنہا نے فرمایا: جو شخص ظہر سے پہلے چار رکعات اور ظہر کے بعد چار رکعات پڑھے، اللہ تعالیٰ اسے آگ پر حرام فرما دے گا۔\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ حضرت مکحول نے حضرت عنبسہ سے کچھ نہیں سنا۔ (یعنی یہ روایت منقطع ہے۔)"}],[1816,"محمد بن ابی سفیان کہتے ہیں کہ جب ان کی موت کا وقت قریب ہوا تو ان کی حالت شدید ہو گئی تو انہوں نے کہا: مجھ سے میری بہن ام حبیبہ بنت ابی سفیان رضی اللہ عنہم نے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے ظہر سے پہلے کی چار رکعتوں، اور اس کے بعد کی چار رکعتوں کی محافظت کی، تو اللہ تعالی اسے جہنم پر حرام کر دے گا\"۔","الألباني: صحيح",{"u2":"حضرت سلیمان بن موسیٰ بیان کرتے ہیں کہ جب حضرت محمد بن اسوسفیان کو موت آنے لگی تو انھیں بڑی گھبراہٹ اور بے قراری لاحق ہوگئی۔ انھوں نے فرمایا: مجھے میری ہمشیرہ محترمہ حضرت ام حبیبہ بنت ابوسفیان رضی اللہ عنہا نے بیان فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ظہر سے پہلے چار رکعات اور ظہر کے بعد چار رکعات پر پابندی کرے، اللہ تعالیٰ اسے آگ پر حرام فرما دیتا ہے۔‘‘"}],[1817,"ام المؤمنین ام حبیبہ رضی اللہ عنہا روایت کرتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: جس نے ظہر سے پہلے چار رکعتیں اور اس کے بعد چار پڑھیں، اسے آگ نہیں چھوئے گی۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ غلط ہے ۱؎، صحیح مروان کی حدیث ہے ۲؎۔\nكتاب الجنائز\n§وضاحت\n۱؎: اشارہ اس سے پہلے والی حدیث کی طرف ہے اس لیے بہتر یہ تھا کہ امام نسائی کا یہ قول حدیث رقم: ۱۸۱۷ کے بعد ذکر کیا جاتا، نیز یہ بھی احتمال ہے کہ مراد عبداللہ شعیشی کے طریق سے وارد حدیث ہو ایسی صورت میں یہ کلام اپنے محل ہی میں ہو گا۔ ۲؎: یعنی حدیث رقم: ۱۸۱۶، جسے وہ سعید بن عبدالعزیز سے روایت کر رہے ہیں، اس میں عنبسہ بن ابی سفیان ہیں جب کہ اس میں محمد بن ابی سفیان ہیں جو غلط ہے۔","الألباني: صحيح",{"u2":"حضرت ام حبیبہ رضی اللہ عنہا سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ظہر سے پہلے چار اورظہر کے بعد چار رکعات (پابندی سے) پڑھے گا، اسے آگ نہ چھوئے گی۔‘‘\nامام ابو عبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ حدیث غلط ہے۔ صحیح حدیث مروان کی ہے جو وہ سعید بن عبدالعزیز سے بیان کرتے ہیں۔","f2":"(۱) بعض محققین نے کہا ہے کہ یہ الفاظ حدیث نمبر ۱۸۱۷ کے بعد ہونے چاہیں، یعنی حدیث نمبر ۱۸۱۷ میں محمد بن ابوسفیان کا ذکر درست نہیں ہے، ان کے بجائے عنبسہ بن ابی سفیان درست ہے جیسا کہ مروان کی حدیث (نمبر ۱۸۱۵، ۱۸۱۶) میں ہے۔ اگر یہ الفاظ یہیں درست ہوں (یعنی حدیث نمبر ۱۸۱۸ کے بعد) تو، پھر یہ مطلب ہو سکتا ہے کہ اس حدیث کی مذکورہ سند (عبداللہ شعیثی عن عنبسہ) کے بجائے مروان والی حدیث کی سند (مکحول عن عنبسہ) ذکر ہونی چاہیے۔ واللہ أعلم۔ (۲) امام نسائی رحمہ اللہ نے حضرت ام حبیبہ رضی اللہ عنہا کی روایت کی مختلف (۲۴) سندیں ذکر کی ہیں۔ بعض راویوں کی غلطیاں ظاہر کرنے کے لیے ان کو یہ طویل تکرار کرنی پڑی، مثلاً: بعض راویوں نے اسے بجائے حضرت ام حبیبہ رضی اللہ عنہا کے حضرت عائشہ رضی اللہ عنہا سے بیان کردیا، بعض نے حرت ابوہریرہ رضی اللہ عنہ کا ذکر کر دیا۔ لیکن یہ ان کی غلطی ہے۔ یہ روایت حضرت ام حبیبہ رضی اللہ عنہا سے ہے۔ اسی طرح صحیح یہ ہے ککہ یہ روایت مرفوع ہے، یعنی نبی صلی اللہ علیہ وسلم کا فرمان ہے۔ بعض راویوں نے اسے حضرت ام حبیبہ رضی اللہ عنہا کا اپنا قول بیان کردیا۔ اس کے علاوہ بھی سندوں میں کچھ اختلافات ہیں جو تمام اسانید کو بغور دیکھنے سے سمجھ میں آسکتے ہیں۔ اس سلسلے میں فائدہ حدیث نمبر ۱۷۸۰ مدنظر رکھا جائے تاکہ کچھ غلط فہمیوں سے بچاؤ ہوسکے۔ (۳) سنن مؤکدہ کی پابندی کے ساتھ ادائیگی سے جنت کا دخول اولیں یا آگ کی حرمت مشروط ہے کہ اس نے کوئی ایسا گناہ نہ کیا ہو جو ناقابل معافی ہو، مثلاً: شرک۔ اسی طرح حقوق العباد کی ادائیگی کے بعد بھی اتنی نیکیاں بچ جائیں جو اولیں طور پر جنت میں لے جائیں، نیز یہ ثواب اس کام کا انفرادی ثواب ہے، جب ساتھ گناہ بھی ہوں تو ظاہر ہے ان کی مقررہ سزا سے بھی مفر نہیں۔ مجموعی طور پر ثواب غالب آ جائے یا عذاب، یہ الگ باتہوگی۔ بعض گناہ ایسے ہیں جن پر اللہ تعالی ٰنے قسم کھا رکھی ہے کہ ضرور جہنم میں لے جائیں گے، لہٰذا آخری فیصلہ تمام نیکیوں اور برائیوں کی جزا و سزا کو ملانے ہی سے ہوگا، نیز کسی ایک حدیث کو باقی احادیث پر غالب نہیں کیا جا سکتا ببلکہ تمام احادیث کو ملا کر ہی نتیجہ اخذ کیا جا سکتا ہے۔ (۴) آخری احادیث میں صرف ظہر سے پہلے چار رکعات اور ظہر کے بعد چار رکعات ہی کا ذکر کیا گیا ہے۔ گویا یہ حدیث پہلی احادیث سے مختلف ہے جن میں بارہ رکعات کا ذکر ہے۔ بارہ رکعات سنن پڑھنے پر دخول جنت کی ضمانت دی گئی ہے اور ظہر کی نماز سے پہلے اور بعد چار رکعات پڑھنے پر آگ کی حرمت کا ذکر کیا گیا ہے اور یہ دونوں الگ الگ معانی ہیں۔ (۵) عشاء اور عصر کی نمازوں سے قبل چار، چار رکعات کا ذکر بھی بعض روایات میں ہے اور ان کی فضیلت بھی وارد ہے جبکہ عشاء سے قبل چار رکعات سنت کی روایت ضعیف ہے۔ عصر سے قبل چار رکعات کی ادائیگی پر رسول اللہ صلی اللہ علیہ وسلم کی خصوصی دعا ہے۔ غرض یہ چار رکعات ضروری یا مؤکد نہیں صرف مستحب ہیں۔ واللہ أعلم۔ (۶) امام نسائی رحمہ اللہ نے تو بارہ رکعات والی روایات ہی ذکر فرمائی ہیں۔ بعض روایات میں بارہ کے بجائے دس رکعات پر یہی ثواب بیان کیا گیا ہے۔ ان میں ظہر سے پہلے چار کے بجائے دو رکعات کا ذکر ہے۔ گویا کبھی کبھار اگر دو ہی پر اکتفا کر لیا جائے تو بھی کوئی حرج نہیں، مگر معمول چار رکعات ہی ہونا چاہیے۔"}],[1818,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کوئی (بھی) ہرگز موت کی آرزو و تمنا نہ کرے، (کیونکہ) یا تو وہ نیک ہو گا تو ہو سکتا ہے زیادہ نیکی کرے، یا برا ہو گا تو ہو سکتا ہے وہ برائی سے توبہ کر لے\" ۱؎۔\n§وضاحت\n۱؎: اس لیے زندہ رہنا ہی اس کے لیے بہتر ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی شخص موت کی تمنا نہ کرے (کیونکہ) اگر وہ نیک ہے تو ہوسکتا ہے وہ اور نیکیاں کرے اور اگروہ گناہ گار ہے تو شاید وہ اپنے اللہ کو راضی کرلے۔‘‘"}],[1819,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں کا کوئی (بھی) ہرگز موت کی آرزو و تمنا نہ کرے (کیونکہ) اگر وہ نیک ہے تو شاید زندہ رہے (اور) زیادہ نیکی کرے، اور یہ اس کے لیے بہتر ہے، اور اگر گناہ گار ہے تو ہو سکتا ہے گنا ہوں سے توبہ کر لے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کئوی شخص موت کی خواہش نہ کرے۔ اگر وہ نیک ہے تو شاید مزید زندہ رہ کر اور نیکیاں کرے اور یہ اس کے لیے بہتر ہے۔ اور اگر وہ برا ہے تو شاید وہ اپنے اللہ کو راضی کرلے۔‘‘","f2":"موت اللہ تعالیٰ کے اختیار میں ہے۔ کسی کے مانگنے یا روکنے سے موت آگے پیچھے نہیں ہوسکتی تو پھر کیا فائدہ ایسی چیز مانگنے کا جو مانگنے سے مل نہیں سکتی بلکہ اس کا وقت مقرر ہے۔ اس کے بجائے وہ میسر زندگی کو نیکی کے اضافے اور توبہ و مغفرت کے لیے استعمال کرے کیونکہ یہ چیزیں اس کے اختیار میں ہیں۔ انسان اپنی اختیاری چیزوں کی فکر کرے، غیراختیاری چیزوں کو اللہ تعالیٰ پر چھوڑ دے۔"}],[1820,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں کا کوئی (بھی) ہرگز مصیبت کی وجہ سے جو اسے دنیا میں پہنچتی ہے موت کی تمنا نہ کرے ۱؎، بلکہ یہ کہے: «اللہم أحيني ما كانت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي» \"اے اللہ! اس وقت تک مجھے زندہ رکھ جب تک زندگی میرے لیے بہتر ہو، اور اس وقت موت دیدے جب موت میرے لیے بہتر ہو\"۔\n§وضاحت\n۱؎: کیونکہ زندگی کا جو حصہ باقی ہے اس کے دین و دنیا کے لیے بہتر ہو، اس لیے موت کی آرزو کرنا منع ہے، شہادت کی یا مقدس جگہ مرنے کی آرزو کرنا جائز ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی شخص دنیا میں پیش آنے والی کسی مصیبت اور تکلیف کی بنا پر موت کی تمنا اور دعا نہ کرے بلکہ یوں کہے: [اللھم! أحینی ……… خیرالی] ’’اے اللہ! جب تک میرے لیے زندگی بہتر ہے، مجھے زندہ رکھ اور جب میرے لیے موت بہتر ہو تو مجھے موت دے دے۔‘‘","f2":"اس حدیث سے بعض نے یہ استباط کیا ہے کہ کسی دینی مصیبت یا دین کے نقصان کے خدشے کے پیش نظر موت کی دعا کی جا سکتی ہے (کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے دنیا کی قید لگائی ہے۔) جیسے حضرت عمر فارووق رضی اللہ عنہا خلیفۂ ثانی اور حضرت امام بخاری رحمہ اللہ سے موت کی دعا منقول ہے کیونکہ انھیں دین کا خطرہ تھا۔ دیکھیے: (ذخیرۃ العقبی شرح سنن النسائی: ۲۱۳-۲۱۱/۱۸)"}],[1821,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سنو! تم میں کا کوئی (بھی) ہرگز موت کی آرزو نہ کرے، اس مصیبت کی وجہ سے جو اسے پہنچی ہے، اگر موت کی آرزو کرنا ضروری ہو تو یہ کہے: «اللہم أحيني ما كانت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي» \"اے اللہ! اس وقت تک مجھے زندہ رکھ جب تک زندگی میرے لیے بہتر ہو، اور اس وقت موت دیدے جب موت میرے لیے بہتر ہو\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’دبخردار! تم میں سے کوئی شخص پیش آنے والی تکلیف کی بنا پر موت کی خواہش نہ کرے۔ اگر اسے لازماً موت کی خواہش کرنی ہے تو یوں کہے: [اللھم! احینی ……… خیرالی] ’’اے اللہ! جب تک زندہ رہنا میرے لیے بہتر ہے، مجھے زندہ رکھ اور جب موت میرے لیے بہتر ہو تو مجھے موت دے دے۔‘‘"}],[1822,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم موت کی دعا نہ کرو، اور نہ ہی اس کی تمنا (مگر) جسے دعا کرنا ضروری ہو وہ کہے: «اللہم أحيني ما كانت الحياة خيرا لي وتوفني إذا كانت الوفاة خيرا لي» \"اے اللہ! مجھے زندہ رکھ جب تک میرے لیے زندہ رہنا بہتر ہو اور موت دیدے جب میرے لیے موت بہتر ہو\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت انس رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’موت کی نہ دعا کرو اور نہ اس کی خواہش ہی کرو۔ جس شخص کو لازماً (اس قسم کی) دعا کرنی ہی ہو تو وہ یوں کہے: [اللھم! احینی ماکاتب الحیاۃ خیرالی] ’’اے اللہ! جب تک میرے لیے زندگی بہتر ہے، مجھے زندہ رکھ اور جب وفات میرے لیے بہتر ہو تو مجھے فوت کر دے۔‘‘"}],[1823,"قیس بن ابی حازم کہتے ہیں میں خباب رضی اللہ عنہ کے پاس آیا، انہوں نے اپنے پیٹ میں سات داغ لگوا رکھے تھے وہ کہنے لگے: اگر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں موت کی دعا سے نہ روکا ہوتا تو میں (شدت تکلیف سے) اس کی دعا کرتا۔","الألباني: صحيح",{"u2":"حضرت قیس بیان کرتے ہیں کہ میں حضرت خباب رضی اللہ عنہ کے پاس گیا (تو دیکھا کہ) انھوں نے اپنا پیٹ سات جگہ سے آگ سے داغا ہوا ہے۔ انھوں نے فرمایا: اگر رسول اللہ صلی اللہ علیہ وسلم نے ہمیں موت کی دعا کرنے سے روکا نہ ہوتا تو میں ضرور موت کی دعا کرتا۔","f2":"(۱) اس دور میں آگ کے ساتھ داغنا بھی بعض بیماریوں کا علاج سمجھا جاتا تھا مگر رسول اللہ صلی اللہ علیہ وسلم نے اسے اچھا نہیں سمجھا کیونکہ یہ انتہائی اذیت ناک ہے۔ انتہائی مجبوری کے وقت ہی جائز ہے۔ (۲) جس طرح موت کی خواہش، تمنا اور دعا جائز نہیں، اسی طرح موت کی کوشش، یعنی خودکشی بھی جائز نہیں ہے، اسے کبیرہ گناہوں میں شمار کیا گیا ہے کیونکہ انسان اپنی زندگی یا جسم و روح کا مالک نہیں بلکہ یہ تو اس کے پاس امانت ہے اور امانت کی حفاظت کی جاتی ہے، اسے ضائع نہیں کیا جاتا۔"}],[1824,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لذتوں کو کاٹنے والی ۱؎ کو خوب یاد کیا کرو \"۲؎۔ ابوعبدالرحمٰن کہتے ہیں: محمد بن ابراہیم ابوبکر بن ابی شیبہ کے والد ہیں۔\n§وضاحت\n۱؎: لذتوں کو کاٹنے والی سے مراد موت ہے۔ ۲؎: موت کو کثرت سے یاد کرنے کا فائدہ یہ ہے کہ انسان اس سے نیکیوں کی طرف راغب ہوتا ہے، اور برائیوں سے توبہ کرتا ہے۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لذتوں کو توڑ دینے والی (موت) کو خوب یاد کیا کرو۔‘‘\nامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ بیان کرتے ہیں: (سند میں مذکور) محمد بن ابراہیم ابوبکر بن ابی شیبہ کے والد ہیں۔"}],[1825,"ام المؤمنین ام سلمہ رضی اللہ عنہا کہتی ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم مریض کے پاس جاؤ تو اچھی باتیں کرو، کیونکہ تم جو کچھ کہتے ہو فرشتے اس پر آمین کہتے ہیں\"۔ چنانچہ جب ابوسلمہ مر گئے، تو میں نے پوچھا: اللہ کے رسول! میں کیا کہوں؟ تو آپ نے فرمایا ـ: \"تو کہو: «اللہم اغفر لنا وله وأعقبني منه عقبى حسنة» \"اے اللہ! ہماری اور ان کی مغفرت فرما، اور مجھے ان کا نعم البدل عطا فرما\" تو اللہ تعالی نے مجھے ان کے بعد محمد صلی اللہ علیہ وسلم کو عطا کیا ۱؎۔\n§وضاحت\n۱؎: ابوسلمہ کی وفات کے بعد ام سلمہ رضی اللہ عنہا کا نکاح رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہو گیا، اس طرح اللہ تعالی نے انہیں بدل ہی نہیں نعم البدل عطا فرما دیا۔","الألباني: صحيح",{"u2":"حضرت ام سلمہ رضی اللہ عنہا سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب تم میت کے ہاں جاؤ تو اچھی باتیں کرو کیونکہ فرشتے تمھاری باتوں پر آمین کہتے ہیں۔‘‘ جب (میرے پہلے خاوندض حضرت ابوسلمہ رضی اللہ عنہ فوت ہوگئے تو میں نے کہا: اے اللہ کے رسول! میں کیسے دعا کروں؟ آپ نے فرمایا: ’’تو کہہ: [اللھم! اغفرلنا ولہ و أعقینی منہ عقبی حسنۃ] ’’اے اللہ! ہمیں اور اسے معاف فرما اور مجھے اس کا اچھا بدل عطا فرما۔‘‘ تو اللہ تعالیٰ نے مجھے ان کے بعد حضرت محمد صلی اللہ علیہ وسلم عطا فرما دیے۔","f2":"(۱) یہاں حقیقتاً میت مراد ہے، یعنی جب تم کسی فوت شدہ شخص کے ہاں جاؤ تو نوحہ وغیرہ نہ کرو اور اپنے آپ کو بددعائیں نہ دو بلکہ اس کے لیے اچھی دعائیں کرو۔ (۲) کسی مصیبت کے وقت یہ دعا پڑھنا بھی مسنون ہے: [انا للہ و انا الیہ راجعون، اللھم! اجرنی فی مصیبتی و اخلف لی خیرا منھا] ’’ہم اللہ ہی کے ہیں اور اسی کی طرف لوٹ کر جانے والے ہیں۔ اے اللہ! مجھے مصیبت میں اجر عطا فرما اور اس کی جگہ بہتر بدل عطا فرما۔‘‘ حضرت ام سلمہ رضی اللہ عنہا نے حضرت ابو سلمہ رضی اللہ عنہ کی وفات پر یہ دعا بھی پڑھی تھی۔ (صحیح مسلم،الجنائز، حدیث: ۹۱۸)"}],[1826,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے قریب المرگ لوگوں کو «لا إله إلا اللہ» کی تلقین کرو\" ۱؎۔\n§وضاحت\n۱؎: بعض لوگوں کا خیال ہے کہ تلقین سے مراد تذکیر ہے یعنی ان کے پاس پڑھ کر انہیں اس کی یاد ہانی کرائی جائے تاکہ سن کر وہ بھی پڑھنے لگیں، ان سے پڑھنے کے لیے نہ کہا جائے کیونکہ موت کے شدت سے گھبراہٹ میں جھنجھلا کر وہ کہیں اس کلمہ کا انکار نہ کر دے، لیکن البانی صاحب رحمہ اللہ کے نزدیک تلقین کا مطلب یہی ہے کہ اس سے «لا إله إلا الله» پڑھنے کے لیے کہا جائے، تفصیل کے لیے دیکھئیے احکام الجنائز للالبانی۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنے قریب الموت اشخاص کو [لا إلا إلا اللہ] پڑھنے کی تلقین کرو۔‘‘","f2":"(۱) تلقین سے مراد یہ ہے کہ اسے کلمہ طیبہ پڑھنے کا کہا جائے، دھیمے لب و لہجے میں اس کی ترغیب دی جائے، یا صورت حال کی سنگینی کے پیش نظر کم از کم اس کے پاس بیٹھ کر کلمہ طیبہ پڑھا جائے تاکہ سن کر وہ بیھ پڑھے لیکن اسے اصرار کے ساتھ کلمہ پڑھنے کو نہ کہا جائے کہ کہیں وہ اکتاہٹ اور تکلیف و گھبراہٹ کی بنا پر انکار نہ کر دے اور جب وہ ایک دفعہ کلمہ طیبہ پڑھ لے تو پھر تلقین نہ کی جائے، ہاں اگر بعد میں وہ کوئی دنیوی کلام کرے تو پھر تلقین کی جائے۔ مقصد یہ ہے کہ موت سے پہلے آخری بات کلمہ طیبہ ہو۔ (۲) بعض لوگ میت کو دفنانے کے بعد قبر پر اسے تلقین کرتے ہیں تاکہ وہ فرشتوں کو کلمہ طیبہ کے ساتھ جواب دے سکے مگر یہ معنی درست نہیں، نہ یہ صحابہ کا معمول تھا۔ اس بارے میں ایک ضعیف روایت بھی وارد ہے۔ سلف کے عمل کے خلاف ضعیف روایت پر عمل جائز نہیں۔"}],[1827,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے قریب المرگ لوگوں کو «لا إله إلا اللہ» کی تلقین کرو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اپنے قریب مرگ اشخاص کو [لا إلہ إلا اللہ] کی تلقین کرو۔‘‘"}],[1828,"بریدہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن ایسی حالت میں مرتا ہے کہ اس کی پیشانی پسینہ آلود ہوتی ہے\" ۱؎۔\n§وضاحت\n۱؎: یعنی مومن موت کی شدت سے دوچار ہوتا ہے تاکہ اس کے گناہوں کی بخشش ہو جائے، یا موت اسے اچانک اس حال میں پا لیتی ہے کہ وہ رزق حلال اور ادائیگی فرض کے لیے اس قدر کوشاں رہتا ہے کہ اس کی پیشانی عرق آلود رہتی ہے۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مومن کی موت پیشانی کے پسینے کے ساتھ ہوتی ہے۔‘‘","f2":"’’پیشانی کا پسینہ‘‘ جبین عربی زبان میں پیشانی کے اطراف کو کہتے ہیں مگر یہاں پوری پیشانی مراد ہے کیونکہ پسینہ پیشانی پر زیادہ آتا ہے۔ اس حدیث میں مومن کی موت کی نشانی پیشانی کا پسینہ بتلایا گیا ہے۔ یا تو یہ پسینہ نزع روح کی شدت کی بنا پر ہوتا ہے تاکہ اس کے باقی گناہ بھی اس شدت کے بدلے میں معاف ہو جائیں اور وہ پاک صاف ہوکر فوت ہو۔ یا یہ پسینہ اس شرمندگی کا نتیجہ ہے جو مومن کو اللہ کی ملاقات کے تصور سے لاحق ہوتی ہیں کہ میں گناہوں کے ساتھ اللہ تعالیٰ کو کیسے ملوں گا؟ ظاہر ہے ایسا تصور مومن ہی کرسکتا ہے۔ منافق تو اس وقت بھی دنیا کے فکر و غم میں مدہوش ہوتا ہے۔ پسینے کی کوئی اور وجہ بھی ہوسکتی ہے جسے ہم نہیں سمجھ سکتے۔ بہرصورت یہ مومن کی نشانی ہے۔ بعض حضرات نے اسے شدت سے استعارہ قرار دیا ہے، یعنی مومن مشقت و محنت کرتا کرتا فوت ہوتا ہے۔ یا تو نیکی کے لیے یا رزق کے لیے، یعنی مومن آرام و راحت سے زندگی گزارتا بلکہ کام کرتا رہتا ہے۔ کبھی دین کا، کبھی دنیا کا۔ واللہ أعلم۔"}],[1829,"بریدہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے سنا: \"مومن ایسی حالت میں مرتا ہے کہ اس کی پیشانی پسینہ آلود رہتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’مومن ماتھے کے پسینے کے ساتھ مرتا ہے۔‘‘"}],[1830,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی وفات ہوئی، تو اس وقت آپ کا سر مبارک میری ہنسلی اور ٹھوڑی کے درمیان تھا، آپ صلی اللہ علیہ وسلم کو دیکھنے کے بعد کبھی کسی کی موت کی سختی مجھے ناگوار نہیں لگتی ۱؎۔\n§وضاحت\n۱؎: اس سے معلوم ہوا کہ موت کی سختی برے ہونے کی دلیل نہیں بلکہ یہ ترقی درجات، اور گناہوں کی مغفرت کا سبب بھی ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم میری آغوی میں فوت ہوئے اور رسول اللہ صلی اللہ علیہ وسلم کی وفات دیکھنے کے بعد میں کسی کے لیے موت کی سختی کو ناپسند نہیں کرتی۔","f2":"موت بذات خود سب سے زیادہ تکلیف دہ چیز ہے۔ اس کے مقابلے میں دیگر تکالیف ہیچ ہیں۔ مومن کی اس تکلیف کا بھی ثواب ملتا ہے اور اس سے گناہ معاف ہوتے ہیں، لہٰذا اس کے لیے موت کی سختی رحمت بن جاتی ہے جبکہ وہ کافر و منافق کے لیے عذاب ہے، لہٰذا موت کی سختی یا نرمی کسی کے ایمان و کفر یا نفاق و فسق کی نشانی نہیں، موت کی سختی یا تکلیف صرف متعلقہ شخص ہی جانتا ہے، دیکھنے والا صحیح اندازہ نہیں لگا سکتا۔ جب موت کا عمل (فرشتوں والا) شروع ہو جاتا ہے تو پھر اس شخص کو ہوش نہیں رہتا کہ وہ موت کی سختی بیان کر سکے۔ (استغفراللہ)"}],[1831,"انس رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کا آخری دیدار اس وقت کیا تھا (جب) آپ نے (حجرے کا) پردہ اٹھایا، اور لوگ ابوبکر رضی اللہ عنہ کے پیچھے صف باندھے (کھڑے تھے)، ابوبکر رضی اللہ عنہ نے پیچھے ہٹنا چاہا تو آپ نے اشارہ کیا کہ اپنی جگہ پر رہو، اور پردہ گرا دیا (پھر) آپ اسی دن کے آخری(حصہ میں) انتقال فرما گئے، اور یہ دوشنبہ کا دن تھا۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ (خادم خاص) بیان کرتے ہیں کہ آخری نگاہ جو میں نے رسول اللہ صلی اللہ علیہ وسلم پر ڈالی، یوں تھی کہ رسول اللہ صلی اللہ علیہ وسلم نے (دروازے کا) پردہ ہٹایا جبکہ لوگ (بح کی نماز میں) حضرت ابوبکر رضی اللہ عنہ کے پیچھے صفوں میں کھڑے تھے۔ حضرت ابوبکر نے پیچھے ہٹنے کا ارادہ کیا (کہ شاید آپ تشریف لانا چاہتے ہیں) تو آپ نے سب کو اشارہ کیا کہ اپنی اپن جگہ نماز پڑھتے رہو (کیونکہ سب آپ کی طرف دیکھنے لگے تھے) اور آپ نے پردہ گرا دیا اور پھر آپ اسی دن کے آخری میں فوت ہوگئے۔ یہ پیر کے دن کی بات ہے۔","f2":"(۱) محبوب رب کریم کے چہرۂ انور کی (حالت زندگی میں) آخری زیارت صحابۂ کرام ری اللہ عنہم کے لیے یادگار بن گئی جسے وہ محبت اور افسوس کے ملے جلے جذبات سے یاد کرتے رہے۔ کس قدر سعادت سے بہرہ ور تھے وہ لوگ جنھیں یہ نادر موقع نصیب ہوا۔ (۲) مومن کے لیے سواموار کی وفات کی خواہش اس کی نبی صلی اللہ علیہ وسلم سے عقیدت و محبت کی نشانی ہے۔ (۳) ضرورت کے تحت دروازوں پر پردے لٹکائے جا سکتے ہیں۔ (۴) حضرت ابوبکر صدیق رضی اللہ عنہ کا امامت کے لیے تقرر آپ کی فضیلت پر دلالت کرتا ہے، نیز رسول اللہ صلی اللہ علیہ وسلم کی وفات کے بعد حضرت ابوبکر رضی اللہ عنہ کی خلافت کی طرف اشارہ تھا۔"}],[1832,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ مدینے کا ایک آدمی جو وہیں پیدا ہونے والوں میں سے تھا مر گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے اس (کے جنازے) کی نماز پڑھائی، پھر فرمایا: \"کاش! (یہ شخص) اپنے پیدائش کی جگہ کے علاوہ کہیں اور مرا ہوتا\"، لوگوں نے عرض کیا: اللہ کے رسول! ایسا کیوں تو آپ نے فرمایا:\"آدمی جب اپنی جائے پیدائش کے علاوہ کہیں اور مرتا ہے، تو اسے جنت میں اس کی جائے پیدائش سے جائے موت تک جگہ دی جاتی ہے\" ۱؎۔\n§وضاحت\n۱؎: جنت میں یہ جگہ اس لیے ملتی ہے کہ وہ اجنبیت کی موت مرتا ہے، یا مراد یہ ہے کہ اس کی قبر اتنی کشادہ کر دی جاتی ہے جتنا اس کی جائے پیدائش اور جائے وفات میں فاصلہ ہوتا، اس سے مسافرت اور اجنبیت کی فضیلت ظاہر ہوتی ہے، جب کسی برے کام کے لیے نہ ہو۔","الألباني: حسن",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہ بیان کرتے ہیں کہ مدینہ منورہ میں ایک آدمی فوت ہوگیا جو پیدا بھی ویں ہوا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے اس کا جنازہ پڑھا، پھر فرمایا: ’’کاش کہ یہ اپنی پیدائش والی جگہ سے باہر فوت ہوتا۔‘‘ صحابۂ کرام رضی اللہ عنہم نے عرض کیا: اے اللہ کے رسول! کیوں؟ آپ نے فرمایا: ’’آدمی جب اپنی پیدائش کی جگہ سے دور فوت ہوتا ہے تو جنت میں اسے اس کی پیدائش گاہ سے موت کی جگہ تک کا فاصلہ ماپ کر جنت دی جاتی ہے۔","f2":"یہ عام بات ہے۔ باقی رہا مدینہ منورہ میں فوت ہونا تو یہ بہت بڑی سعادت ہے جو اس بیان شدہ فضیلت سے کہیں بڑھ کر ہے۔ رسول اللہ صلی اللہ علیہ وسلم کا یہ مطلب نہیں کہ یہ شخص مدینہ منورہ سے باہر فوت ہوتا بلکہ اس کا مطلب یہ ہے کہ کاش یہ مدینہ کا پیدائشی نہ ہوتا۔ کسی اور جگہ پیدا ہوکر یہاں ہجرت کرتا اور پھر مدینہ منورہ میں فوت ہوتا کیونکہ مدینے میں وفات کی فضیلت تو احادیث میں وارد ہے۔ دیکھیے: (سنن ابن ماجہ، المناسک، حدیث: ۳۱۱۲، و مسند أحمد: ۷۴/۲) اور یہ مومن کے لیے بڑی سعادت ہے۔ یاد رہے کہ ہر سعادت کے حصول کے لیے صحیح ایمان شرط ہے ورنہ ہر چیز بے کار ہے۔"}],[1833,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب مومن کی موت آتی ہے تو اس کے پاس رحمت کے فرشتے سفید ریشمی کپڑا لے کر آتے ہیں، اور (اس کی روح سے) کہتے ہیں: نکل، تو اللہ سے راضی ہے، اور اللہ تجھ سے راضی ہے، اللہ کی رحمت اور رزق کی طرف اور (اپنے) رب کی طرف جو ناراض نہیں ہے، تو وہ پاکیزہ خوشبودار مشک کی مانند نکل پڑتی، ہے یہاں تک کہ (فرشتے) اسے ہاتھوں ہاتھ لیتے ہیں، (جب) آسمان کے دروازے پر اسے لے کر آتے ہیں تو (دربان) کہتے ہیں: کیا خوب ہے یہ خوشبو جو زمین سے تمہارے پاس آئی ہے، (پھر) وہ اسے مومن کی روحوں کے پاس لے کر آتے ہیں، تو انہیں ایسی خوشی ہوتی ہے جو گمشدہ شخص کے لوٹ کر آ جانے سے بڑھ کر ہوتی ہے، وہ روحیں اس سے ان لوگوں کا حال پوچھتی ہیں جنہیں وہ دنیا میں چھوڑ گئے تھے: فلاں کیسے ہے، اور فلاں کیسے ہے؟ وہ کہتی ہیں: انہیں چھوڑو، یہ دنیا کے غم میں مبتلا تھے، تو جب وہ (نووارد روح) کہتی ہے: کیا وہ تمہارے پاس نہیں آیا؟ (وہ تو مر گیا تھا) تو وہ کہتی ہیں: اسے اس کے ٹھکانہ ہاویہ کی طرف لے جایا گیا ہو گا، اور جب کافر قریب المرگ ہوتا ہے تو عذاب کے فرشتے ایک ٹاٹ کا ٹکڑا لے کر آتے ہیں، (اور) کہتے ہیں: اللہ کے عذاب کی طرف نکل، تو اللہ سے ناراض ہے، اور اللہ تجھ سے ناراض ہے، تو وہ نکل پڑتی ہے جیسے سڑے مردار کی بدبو نکلتی ہے یہاں تک کہ اسے زمین کے دروازے پر لاتے ہیں (پھر) کہتے ہیں: کتنی خراب بدبو ہے یہاں تک کہ اسے کافروں کی روحوں میں لے جا کر (چھوڑ دیتے ہیں)\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمای: ’’جب مومن کو موت آنے لگتی ہے تو رحمت کے فرشتے سفید ریشمی لباس لے کر اس کے پاس آ جاتے ہیں اور کتے ہیں: اے مومن روح! نکل آ۔ تو اللہ تعالیٰ سے راضی، اللہ تعالیٰ تجھ سے راضی۔ اور چل اللہ کی رحمت و مہربانی کی طرف اور پہنچ ایسے رب کے پاس جو تجھ پر قطعا ناراض نہیں ہے۔ تو وہ انتہائی خوشبودار، پاکیزہ کستوری جیسی مہک کے ساتھ نکل آتی ہے حتی کہ فرشتے (خوشی اور سرور سے) اسے ایک دوسرے کو پکڑاتے (ہاتھوں ہاتھ لیتے) ہیں اور اسی طرح وہ اسے آسمان کے دروازے تک لے جاتے ہیں۔ آسمان والے فرشتے کہتے ہیں: کس قدر خوشبودار ہے یہ روح جو تم زمین سے لائے ہو!۔ پھر وہ اسے (پہلے سے فوت شدہ) مومنین کی روحوں کے پاس لے آتے ہیں۔ اللہ کی قسم! وہ اس کے آنے پراس قدر خوش ہوتے ہیں کہ تم اپنے کسی غائب شخص کے آنے پر اتنے خوش نہیں ہوتے، پھر وہ (پہلے مومن) اس سے پوچھتے ہیں: فلاں کا کیا حال ہے؟ فلاں کا کیا حال ہے؟ پھر وہ (آپس میں) کہتے ہیں: چھوڑو اسے وہ تو دنیا کے غم و فکر میں تھا۔ جب وہ روح کہتی ہے کہ کیا وہ تمھارے پاس نہیں آیا؟ (یعنی وہ تو کب کا مر چکا ہے) تو وہ کہتے ہیں: اوہو! اسے اس کے جہنمی ٹھکانے کی جانب سے لے جایا گیا ہے۔ (اس کے مقابلے میں) جب کافر کو موت آتی ہے تو عذاب کے فرشتے گندا بدبودار ٹاٹ لے کر اس کے پاس آ جاتے ہیں اور (غصے سے) کہتے ہیں: نکل ادھر، تو بھی ناراض اور تیرا اللہ بھی تجھ پر ناراض۔ چل اللہ عزوجل کے عذاب کی طرف۔ تو وہ انتہائی بدبودار مردار لاش کے بھبو کے ساتھ نکلتی ہے حتی کہ وہ اسے زمین کے دروازے پر لے جاتے ہیں اور کہتے ہیں: کس قدر بدبودار ہے یہ! حتی کہ وہ اسے (پہلے سے مرے ہوئے) کافروں کی روحوں میں لے جاتے ہیں۔‘‘","f2":"(۱) ’’ایک دوسرے کو پکڑاتے ہیں‘‘ جس طرح نومولود بچے کو اس کے رشتے دار بڑی خوشی کے ساتھ پکڑ پکڑ کر دیکھتے ہیں۔ معلوم ہوا روح ایک حقیقت ہے اور جسم سے الگ ایک چیز ہے۔ اس کا اپنا وجود ہے۔ یہ الگ بات ہے کہ وہ نظر نہیںآتی کیونکہ بہت لطیف ہے۔ اگر ہوا، باوجود اس جہان کی چیز ہونے کے نظر نہیں آتی مگر ایک حقیقت ہے تو روح کے نظر نہ آنےپرکیا تعجب ہے؟ (۲) ’’چھوڑو اس کو‘‘ اس سے مراد نئی روح بھی ہوسکتی ہے کہ تم اسے زیادہ سوال و جواب سے پریشان نہ کرو۔ ابھی وہ دنیا کے غم میں ہے۔ (۳) مومن آدمی کی موت کے وقت رحمت کے فرشتے حاضر ہوتے ہیں اور اسے بشارتیں سناتے ہیں۔"}],[1834,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ تعالی سے ملنا چاہے اللہ تعالی (بھی) اس سے ملنا چاہے گا، اور جو اللہ تعالی سے ملنا ناپسند کرے اللہ تعالی (بھی) اس سے ملنا ناپسند کرے گا\"۔ شریح کہتے ہیں: میں ام المؤمنین عائشہ رضی اللہ عنہا کے پاس آیا، اور میں نے کہا: ام المؤمنین! میں نے ابوہریرہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم کی ایک حدیث ذکر کرتے سنا ہے، اگر ایسا ہے تو ہم ہلاک ہو گئے، انہوں نے پوچھا: وہ کیا ہے؟ انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"جو اللہ سے ملنا چاہے اللہ (بھی) اس سے ملنا چاہے گا، اور جو اللہ تعالی سے ملنا ناپسند کرے اللہ تعالی (بھی) اس سے ملنا ناپسند کرے گا\" لیکن ہم میں سے کوئی (بھی) ایسا نہیں جو موت کو ناپسند نہ کرتا ہو۔ تو انہوں نے کہا: بیشک یہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے، لیکن اس کا یہ مطلب نہیں جو تم سمجھتے ہو بلکہ اس کا مطلب یہ ہے کہ جب نگاہ پتھرا جائے، سینہ میں دم گھٹنے لگے، اور رونگٹے کھڑے ہو جائیں، اس وقت جو اللہ تعالی سے ملنا چاہے اللہ تعالی (بھی) اس سے ملنا چاہے گا، اور جو اللہ تعالی سے ملنا ناپسند کرے اللہ تعالی (بھی) اس سے ملنا ناپسند کرے گا ۱؎۔\n§وضاحت\n۱؎: خود رسول اللہ صلی اللہ علیہ وسلم نے اس کی صراحت فرما دی ہے :(دیکھئیے حدیث رقم: ۱۸۳۹ ) مطلب یہ ہے کہ مومن کو موت کے وقت اللہ تعالی سے ملاقات کی خوشی ہوتی ہے، اور کافر کو گھبراہٹ ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی اللہ تعالیٰ کی ملاقات کو پسند کرتا ہے، اللہ تعالیٰ اس کی ملاقات کو پسند کرتا ہے اور جو شخص اللہ تعالیٰ کی ملاقات کو ناپسند کرتا ہے، اللہ تعالیٰ اس کی ملاقات کو ناپسند فرماتا ہے۔‘‘ (حضرت ابوہریرہ کے شاگرد) حضرت شریح نے کہا: میں حضرت عائشہ رضی اللہ عنہا کے پاس حاضر ہوا اور عرض کیا: اے ام المومنین! میں نے حضرت ابوہریرہ رضی اللہ عنہ کو رسول اللہ صلی اللہ علیہ وسلم سے ایک ایسی حدیث بیان کرتے سنا ہے اگر وہ صحیح ہے تو ہم تو مارے گئے۔ حضرت عائشہ رضی اللہ عنہ نے فرمایا: وہ کون سی حدیث ہے؟ (میں نے کہا:) وہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ کی ملاقات کو پسند کرتا ہے، اللہ تعالیٰ اس سے ملاقات کو پسند فرماتا ہے اور جو اللہ تعالیٰ کی ملاقات کو ناپسند کرتا ہے، اللہ تعالیٰ اس سے ملنا پسند نہیں فرماتا۔‘‘ جبکہ ہم میں سے ہر ایک موت کو ناپسند کرتا ہے؟ (اور موت کے بغیر اللہ تعالیٰ سے ملاقات ممکن نہیں؟) حضرت عائشہ رضی اللہ عنہا نے فرمایا: حقیقتاً یہ الفاظ رسول اللہ صلی اللہ علیہ وسلم نے فرمائے ہیں، لیکن اس کا وہ مطلب نہیں جو تم نے سمجھا ہے بلکہ یہ اس وقت ہے جب نظر اوپر اٹھ جائے اور سانس سینے میں اٹکنے لگے اور جسم کے رونگٹے کھڑے ہو جائیں اور وہ کانپنے لگے۔ (عین نزاع روح کا عمل شروع ہو جائے) اس وقت جو شخص اللہ تعالیٰ کی ملاقات کو پسند کرتا ہے، اللہ تعالیٰ اس کی ملاقات کو پسند فرماتا ہے اور جو شخص اس وقت اللہ تعالیٰ کی ملاقات کو ناپسند کرتا ہے، اللہ تعالیٰ بھی اس سے ملنا پسند نہیں فرماتا۔","f2":"(۱)جب موت کا وقت قریب آ جائے، فرشتے نظر آنے لگیں اور اپنا کام شروع کر دیں تو اس وقت مومن خوش ہوتا ہے کہ اللہ تعالیٰ سے ملاقات ہوگی [اللھم الرفیق الاعلی] اور کافر، منافق اس وقت اپنی سابقہ کارگزاری کی وجہ سے اللہ تعالیٰ کی ملاقات سے ھبراتا ہے کیونکہ اس وقت موت کا یقین ہوجاتا ہے۔ ورنہ زندگی میں تو ہر شخص ہی موت کو ناپسند کرتا ہے۔ (۲) اللہ تعالیٰ سے ملاقات کی محبت کا مطلب موت کی تمنا کرنا نہیں۔ موت کی تمنا کے بغیر بھی اللہ سے ملاقات کی محبت ممکن ہے۔ موت کی تمنا کا تعلق معمول کی زندگی سے ہے اور اللہ سے ملاقات کی محبت کا تعلق موت کے وقت سے ہے۔"}],[1835,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی فرماتا ہے: جب میرا بندہ مجھ سے ملنا چاہتا ہے تو میں (بھی) اس سے ملنا چاہتا ہوں، اور جب وہ مجھ سے ملنا ناپسند کرتا ہے تو میں (بھی) اس سے ملنا ناپسند کرتا ہوں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے منقول ے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ فرماتا ہے: جب میرا بندہ میری ملاقات کو پسند کرتا ہے تو میں بھی اس سے ملاقات کو پسند کرتا ہوں اور جب وہ میری ملاقات کو ناپسند کرتا ہے تو میں بھی اس سے ملاقات کو ناپسند کرتا ہوں۔‘‘"}],[1836,"عبادہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ تعالی سے ملنا چاہے، اللہ تعالی (بھی) اس سے ملنا چاہے گا، اور جو اللہ تعالی سے ملنا ناپسند کرے اللہ تعالی (بھی) اس سے ملنا ناپسند کرے گا\"۔","الألباني: صحيح",{"u2":"حضرت عباد (بن صامت) رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ سے ملنے کی خواہش کرتا ہے، اللہ تعالیٰ اس سے ملنے کی خواہش کرتا ہے اور جو شخص اللہ تعالیٰ سے ملنے کو ناپسند کرتا ہے، اللہ تعالیٰ اس سے ملنے کو ناپسند کرتا ہے۔‘‘"}],[1837,"عبادہ بن صامت رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ تعالی سے ملنا چاہتا ہے اللہ تعالی (بھی) اس سے ملنا چاہتا ہے، اور جو اللہ تعالی سے ملنا ناپسند کرتا ہے اللہ تعالی (بھی) اس سے ملنا ناپسند کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عباد بن صامت رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اللہ تعالیٰ سے ملنا چاہتا ہے، اللہ تعالیٰ بھی اس سے ملنا چاہتا ہے اور جو شخص اللہ تعالیٰ سے ملنا نہیں چاہتا اللہ تعالیٰ بھی اس سے ملنا نہیں چاہتا۔‘‘"}],[1838,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو اللہ تعالی سے ملنا چاہے گا اللہ تعالی (بھی) اس سے ملنا چاہے گا، اور جو اللہ سے ملنا ناپسند کرتا ہے اللہ تعالی (بھی) اس سے ملنا ناپسند کرے گا، (عمرو نے اپنی روایت میں اتنا اضافہ کیا ہے) اس پر اللہ کے رسول سے عرض کیا گیا: اللہ کے رسول!(اگر) اللہ تعالی سے ملنا ناپسند کرنا موت کو ناپسند کرنا ہے، تو ہم سب موت کو ناپسند کرتے ہیں۔ آپ نے فرمایا: \"یہ اس کے مرنے کے وقت کی بات ہے، جب اسے اللہ کی رحمت اور اس کی مغفرت کی خوشخبری دی جاتی ہے، تو وہ اللہ تعالی سے (جلد) ملنا چاہتا ہے اور اللہ تعالی (بھی) اس سے ملنا چاہتا ہے، اور جب اسے اللہ تعالی کے عذاب کی دھمکی دی جاتی ہے تو (ڈر کی وجہ سے) ملنا ناپسند کرتا ہے، اور وہ بھی اس سے ملنا ناپسند کرتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص (نزع کے وقت) اللہ تعالیٰ سے ملنا اچھا سمجھتا ہے، اللہ تعالیٰ بھی اس سے ملنا اچھا سمجھتا ہے اور جو شخص اللہ تعالیٰ سے ملنا برا سمجھتا ہے، اللہ تعالیٰ بھی اس سے ملنا برا سمجھتا ہے۔‘‘ کہا گیا: اے اللہ کے رسول! اللہ تعالیٰ سے ملنے کو ناپسند کرنے کا مطلب موت کو ناپسند کرنا ہے؟ ہم میں سے تو ہر شخص موت کو ناپسند کرتا ہے؟ آپ نے فرمایا: ’’یہ موت کے وقت کی بات ہے کہ جب مومن کو اللہ تعالیٰ کی رحمت و بخشش کی خوش خبری دی جاتی ہے تو وہ فوراً اللہ تعالیٰ سے ملنا چاہتا ہے اور اللہ تعالیٰ اس سے ملنا چاہتا ہے اور جب کافر کو اللہ کے عذاب کی اطلاع دی جاتی ہے تو وہ اللہ تعالیٰ سے ملنا ناپسند کرتا ہے اور اللہ تعالیٰ بھی اس سے ملنا ناپسند کرتا ہے۔‘‘","f2":"موت اگرچہ اذیت ناک چیز ہے مگر مومن کے لی اللہ تعالیٰ کے دیدار اور ملاقات کا شوق اور بخشش و رحمت کی بشارت موت کی سختی پر غالب آ جاتی ہے اور کافر کے لیے موت کی اذیت کے علاوہ عذاب و سزا کا تصور بڑا دہشت ناک بن جاتا ہے، لہٰذا وہ موت کے وقت بھی مرنا نہیں چاہتا۔"}],[1839,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ابوبکر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کی دونوں آنکھوں کے بیچ بوسہ لیا، اور آپ انتقال فرما چکے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ حضرت ابوبکر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کی وفات کے بعد آپ کی آنکھوں کے درمیان (پیشانی کو) بوسہ دیا۔"}],[1840,"عبداللہ بن عباس اور عائشہ رضی اللہ عنہم سے روایت ہے کہ ابوبکر رضی اللہ عنہ نے نبی اکرم صلی اللہ علیہ وسلم کا بوسہ لیا، اور آپ انتقال فرما چکے تھے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس اور حضرت عائشہ رضی اللہ عنھم سے منقول ہے کہ حضرت ابوبکر رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم کو بوسہ دیا جبکہ آپ فوت ہوچکے تھے۔"}],[1841,"ابوسلمہ کہتے ہیں کہ نے مجھے خبر دی ہے کہ ام المؤمنین عائشہ رضی اللہ عنہا نے انہیں بتایا ہے کہ ابوبکر \"سُنح\" میں واقع اپنے مکان سے ایک گھوڑے پر آئے، اور اتر کر (سیدھے) مسجد میں گئے، لوگوں سے کوئی بات نہیں کی یہاں تک کہ عائشہ رضی اللہ عنہا کے پاس (ان کے حجرے میں) آئے، رسول اللہ صلی اللہ علیہ وسلم کو دھاری دار چادر سے ڈھانپ دیا گیا تھا تو انہوں نے آپ صلی اللہ علیہ وسلم کا چہرہ مبارک کھولا، پھر وہ آپ پر جھکے اور آپ کا بوسہ لیا، اور رو پڑے، پھر کہا: میرے باپ آپ پر فدا ہوں، اللہ کی قسم! اللہ کبھی آپ پر دو موتیں اکٹھی نہیں کرے گا، رہی یہ موت جو اللہ تعالی نے آپ پر لکھ دی تھی تو یہ ہو چکی ۲؎۔\n§وضاحت\n۱؎: \"سُنح\" یہ عوالی مدینہ میں ایک جگہ کا نام ہے جہاں نبی حارث بن خزرج کے لوگ رہتے تھے، ابوبکر رضی اللہ عنہ نے انہیں میں شادی کی تھی، اور یہ رہائش گاہ ان کی اہلیہ کی تھی، رسول اللہ صلی اللہ علیہ وسلم نے انہیں وہاں جانے کی اجازت دی تھی۔ ۲؎: ابوبکر رضی اللہ عنہ نے یہ جملہ عمر رضی اللہ عنہ کی تردید میں کہا تھا جو کہہ رہے تھے کہ آپ پھر دنیا میں واپس آئیں گے۔","الألباني: صحيح",{"u2":"حضرت ابوسلمہ سے روایت ہے کہ حضرت عائشہ رضی اللہ عنہا نے مجھے خبر دی کہ (جب رسول اللہ صلی اللہ علیہ وسلم فوت ہوگئے تو) حضرت ابوبکر صدیق رضی اللہ عنہ سنح مقام پر واقع اپنے گھر سے گھوڑے پر آئے (تاکہ جلدی پہنچ سکیں) یہاں تک کہ وہ گھوڑے سے اترے اور مسجد میں داخل ہوئے اور کسی سے بات چیت نہیں کی حتی کہ حضرت عائشہ رضی اللہ عنہا کے پاس گئے۔ اس وقت رسول اللہ صلی اللہ علیہ وسلم کو ایک دھاری دار یمنی چادر سے ڈھانپ دیا گیا تھا۔ انھوں نے آپ کے چہرۂ مبارک سے کپڑا ہٹایا، پھر جھک کر آپ صلی اللہ علیہ وسلم کو بوسہ دیا اور رونے لگے، پھر کہا: میرا باپ آپ پر قربان! اللہ کی قسم! اللہ تعالیٰ آپ پر دو دفعہ موت طاری نہیں کرے گا۔ جو موت آپ کے لیے مقدر تھی، وہ آپ کو آچکی۔","f2":"(۱)ان الفاظ کا مقصد ان لوگوں کو تنبیہ کرنا تھا جو شدت غم کی وجہ سے سمجھتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم ابھی فوت نہیں ہوئے، بے ہوش ہیں۔ یا جو لوگ آپ کی وفات کو عارضی خیال کرتے تھے۔ ان دونوں صورتوں میں گویا آپ پر ایک اور موت آنی تھی۔ اور یہ ناممکن ہے کہ آپ دو دفعہ فوت ہوں۔ (۲) باب کا مقصد یہ ہے کہ مومن موت سے قلید نہیں ہو جاتا بلکہ پاک رہتا ہے، لہٰذا اسے بوسہ دینا اور چھونا جائز ہے جبکہ بعض فقہاء میت کو پلید کہتےہیں لیکن یہ درست نہیں حضرت ابن عباس رضی اللہ عنہما سے صحیح سند کے ساتھ مروی ہے کہ انھوں نے فرمایا: [المسلم لانجس حیا و الامیتا] ’’مومن زندہ ہو یا فوت شدہ، پلید نہیں ہوتا۔‘‘ (صحیح البخاري، الجنائز، باب غسل المیت ووضوئہ بالماء و السدر، بعد الحدیث: ۱۲۵۲، و مختصر صحیح البخاري، اللألباني، رقم الاثر: ۲۳۹) ہاں کافر مر جائیں تو پلید ہیں۔ (۳) میت پر رونا جائز ہے، واویلا، چیخ و پکار اور جاہلیت کی آہ و بکا درست نہیں۔"}],[1842,"جابر بن عبداللہ بن حرام رضی اللہ عنہما کہتے ہیں کہ غزوہ احد کے دن میرے والد کو اس حال میں لایا گیا کہ ان کا مثلہ کیا جا چکا تھا، انہیں رسول اللہ صلی اللہ علیہ وسلم کے سامنے رکھا گیا، اور ایک کپڑے سے ڈھانپ دیا گیا تھا، میں نے ان کے چہرہ سے کپڑا ہٹانا چاہا تو لوگوں نے مجھے روک دیا، (پھر) رسول اللہ صلی اللہ علیہ وسلم نے انہیں (اٹھانے) کا حکم دیا، انہیں اٹھایا گیا، تو جب وہ اٹھائے گئے تو آپ نے کسی رونے والے کی آواز سنی تو پوچھا: \"یہ کون ہے؟\" تو لوگوں نے کہا: یہ عمرو کی بیٹی یا بہن ہے، آپ نے فرمایا: \"مت روؤ\"، یا فرمایا: \"کیوں روتی ہو؟ جب تک انہیں اٹھایا نہیں گیا تھا فرشتے انہیں برابر سایہ کئے ہوئے تھے\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ جنگ احد کے دن میرے باپ کی میت اس حال میں لائی گئی کہ ان کا چہرہ بگاڑ دیا گیا تھا۔ (کافروں نے ان کے چہرے کے اعضاء کاٹ ڈالے تھے۔) تو ان کی میت رسول اللہ صلی اللہ علیہ وسلم کے سامنے رکھ دی گئی اور اسے ایک کپڑے سے ڈھانپ دیا گیا۔ میں منہ سے کپڑا ہٹانے کی کوشش کرتا تھا تو میری قوم کے لوگ مجھے روکتے تھے۔ آخر نبی صلی اللہ علیہ وسلم نے میت اٹھانے کا حکم دیا۔ جب میت اٹھائی گئی تو آپ نے ایک عورت کے رونے کی آواز سنی تو فرمایا: ’’یہ کون ہے؟‘‘ لوگوں نے کہا: یہ عمرو کی بیٹی یا عمرو کی بہن ہے۔ آپ نے فرمایا: ’’نہ رو‘‘ یا فرمایا: ’’کیوں روتی ہے؟ میت کے اٹھائے جانے تک فرشتوں نے اسے اپنے مبارک پروں سے سایہ کیے رکھا۔‘‘","f2":"(۱)’’عمرو کی بیٹی‘‘ اس صورت میں یہ جابر کے شہید والد کی بہن تھیں اور اگر وہ عمرو کی بہن تھیں تو جابر کے والد کی پھوپھی تھیں۔ پہلی بات صحیح ہے کہ وہ شہید کی بہن تھیں ……… رضی اللہ عنہا ……… دراصل یہ کسی راوی کو شک ہے کہ وہ عمرو کی بیٹی تھی یا عمرو کی بہن۔ (۲) ’’سایہ کیے رکھا‘‘ مطلب یہ ہے کہ اتنے شرف والی شہادت پر آہ و زاری مناسب نہیں، اگرچہ دل اور آنکھیں تو غم کرتے ہیں۔ (۳) وفات کے بعد میت کو کپڑے سے ڈھانپ دینا چاہیے تاکہ اگر موت کی وجہ سے اس کے چہرے وغیرہ میں کوئی تغیر آیا ہو تو نظر نہ آئے۔ غسل و تکفین کے بعد جب اسے صاف ستھرا کرکے حتی الامکان خوب صورت بنا دیا جاتا ہے، اس وقت اسے لوگوں کے سامنے چہرہ دیکھنے کے لیے رکھ جا سکتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کے چہرۂ انور میں کسی قسم کے تغیر کا امکان نہیں تھا، اس لیے حضرت ابوبکر صدیق رضی اللہ عنہ نے غسل و تکفین سے پہلے بھی آپ کو دیکھا اور بوسہ دیا ……… رضی اللہ عنہ ………۔"}],[1843,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک چھوٹی بچی کے مرنے کا وقت آیا تو آپ صلی اللہ علیہ وسلم نے اسے (اپنی گود میں)لے کر اپنے سینے سے چمٹا لیا، پھر اس پر اپنا ہاتھ رکھا، تو وہ آپ صلی اللہ علیہ وسلم کے سامنے ہی مر گئی، ام ایمن رضی اللہ عنہا رونے لگیں، تو رسول اللہ صلی اللہ علیہ وسلم نے ان سے فرمایا: \"ام ایمن! تم رو رہی ہو جبکہ اللہ کے رسول صلی اللہ علیہ وسلم تمہارے پاس موجود ہیں؟\" تو انہوں نے کہا: میں کیوں نہ روؤں جبکہ اللہ کے رسول صلی اللہ علیہ وسلم (خود) رو رہے ہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں رو نہیں رہا ہوں، البتہ یہ اللہ کی رحمت ہے\"، پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن ہر حال میں اچھا ہے، اس کی دونوں پسلیوں کے بیچ سے اس کی جان نکالی جاتی ہے، اور وہ اللہ تعالی کی حمد و ثنا کرتا رہتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک چھوٹی بیٹی کی وفات کا وقت آیا، رسول اللہ صلی اللہ علیہ وسلم نے اسے اٹھایا اور اپنے سینے سے لگایا، پھر اپنا دست مبارک اس پر رکھا۔ بالآخر وہ رسول اللہ صلی اللہ علیہ وسلم کے سامنے فوت ہوگئیں۔ حضرت ام ایمن رضی اللہ عنہا رونے لگیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اے ام ایمن! تم روتی ہو جبکہ رسول اللہ صلی اللہ علیہ وسلم تمھارے پاس ہیں؟‘‘ انھوں نے عرض کیا: میں کیوں نہ روؤں جبکہ رسول اللہ صلی اللہ علیہ وسلم رو رہے ہیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں (تمھاری طرح) نہیں رو رہا بلکہ میرا رونا تو اللہ تعالیٰ کی رحمت کی بنا پر ہے۔‘‘ پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مومن ہر حال میں بہتر رہتا ہے (حتی کہ) اس کی جان نکل رہی ہوتی ہے اور وہ اللہ تعالیٰ کی تعریفیں کرتا ہوتا ہے۔‘‘","f2":"دراصل رسول اللہ صلی اللہ علیہ وسلم صرف آنسوؤں سے رو رہے تھے اور حضرت ام ایمن رضی اللہ عنہا (آپ کی پرورش کنندہ) آواز کے ساتھ رو رہی تھیں، اس لیے آپ نے انھیں روکا۔ باقی رہا آنسوؤں سے رونا تو یہ تو صدمے کے موقع پر فطری امر ہے۔ انسان کو اتنا کٹھور دل نہیں ہونا چاہیے کہ صدمات خصوصاً موت سے بھی متاثر نہ ہو۔ آنسوؤں سے رونا اس رحمت کا نتیجہ ے جو اللہ تعالیٰ نے مخلوقات میں رکھی ہے۔ اس سے انکار فطرت انسانیہ کا انکار ہے، پھر اس میں شکایت کا پہلو بھی ہے اور مومن رب العالمین کی شکایت کا تصور بھی نہیں کرسکتا۔ وہ تو مرتے ہوئے بھی رب العالمین کی تعریف کرتا ہے۔ اللھم اجعلنا من المومنین حقا۔"}],[1844,"انس رضی اللہ عنہ سے روایت ہے کہ فاطمہ رضی اللہ عنہا رسول اللہ صلی اللہ علیہ وسلم کی وفات پر رونے لگیں، اور کہنے لگیں: ہائے، ابا جان! آپ اپنے رب سے کس قدر قریب ہو گئے، ہائے، ابا جان! مرنے کی خبر ہم جبرائیل علیہ السلام کو دے رہے ہیں، ہائے، ابا جان! آپ کا ٹھکانا جنت الفردوس ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم فوت ہوئے تو (آپ کے لخت جگر) حضرت فاطمہ رضی اللہ عنہا رونے لگیں۔ ساتھ ساتھ کہہ رہی تھیں: ہاے میرے ابا جان! جو اپنے رب سے کس قدر قریب تھے۔ ہائے میرے ابا جان! جن کی وفات کی اطلاع ہم حضرت جبریل علیہ السلام کو بھی دیتے ہیں۔ ہائے میرے ابا جان! جن کا ٹھکانا جنت الفردوس بن چکا۔","f2":"(۱)مصنوعی آواز کے ساتھ رونا اور ہے اور قدرتی آنسوؤں کے ساتھ روتے ہوئے نیک باتیں کرنا کہ میت میں حقیقتاً وہ پائی بھی جاتی ہوں تو یہ اور چیز ہے۔ پہلی بات منع ہے، دوسری جائز اور یہ خود رسول اللہ صلی اللہ علیہ وسلم سے ثابت ہے۔ حضرت فاطمہ رضی اللہ عنہا آنسوؤں سے روتے ہوئے رسول اللہ صلی اللہ علیہ وسلم، جبریل علیہ السلام اور رب تعالیٰ کا ذکر فرما رہی تھیں اور یہ ان کا حق تھا۔ (۲) جبریل علیہ السلام کو رسول اللہ صلی اللہ علیہ وسلم کی وفات کی اطلاع دینا اظہارِ غم ہی کا ایک طریقہ تھا کہ وہ آپ صلی اللہ علیہ وسلم کے بہت قریبی تھے حضر و سفر، لیل و نہار، عسر و یسر اور خوشی و غمی کے ساتھی تھے۔"}],[1845,"جابر بن عبداللہ بن حرام رضی اللہ عنہما سے روایت ہے کہ ان کے والد غزوہ احد کے دن قتل کر دیئے گئے، میں ان کے چہرہ سے کپڑا ہٹانے اور رونے لگا، لوگ مجھے روک رہے تھے، اور رسول اللہ صلی اللہ علیہ وسلم نہیں روک رہے تھے، میری پھوپھی (بھی) ان پر رونے لگیں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم ان پر مت روؤ، فرشتے ان پر برابر اپنے پروں سے سایہ کیے رہے یہاں تک کہ تم لوگوں نے اٹھایا\" ۱؎۔\n§وضاحت\n۱؎: ان احادیث سے میت پر رونے کا جواز ثابت ہو رہا ہے، رہیں وہ روایتیں جن میں رونے سے منع کیا گیا ہے تو وہ اس رونے پر محمول کی جائیں گی جس میں بین اور نوحہ ہو۔","الألباني: صحيح",{"u2":"حضرت جابر (بن عبداللہ) رضی اللہ عنہما سے منقول ہے کہ میرے والد محترم رضی اللہ عنہ احد کے دن شہید ہوئے۔ میں ان کے چہرے سے کپڑا ہٹاتا تھا اور روتا تھا، لوگ مجھے روکتے تھے جبکہ رسول اللہ صلی اللہ علیہ وسلم مجھے نہیں روکتے تھے۔ میری پھوپھی محترمہ (آواز سے) رونے لگی تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اس پر نہ رو۔ تمھارے اٹھانے تک فرشتوں نے برابر اس کو اپنے پروں کے ساتھ سایہ کیے رکھا۔‘‘ (رضی اللہ عنہ و أرضاہ)"}],[1846,"جابر بن عتیک انصاری رضی اللہ عنہ کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم عبداللہ بن ثابت رضی اللہ عنہ کی عیادت (بیمار پرسی) کرنے آئے تو دیکھا کہ بیماری ان پر غالب آ گئی ہے، تو آپ نے انہیں زور سے پکارا (لیکن) انہوں نے (کوئی) جواب نہیں دیا، تو رسول اللہ صلی اللہ علیہ وسلم نے «اناللہ وانا اليہ راجعون»پڑھا، اور فرمایا: \"اے ابو ربیع! ہم تم پر مغلوب ہو گئے\" (یہ سن کر) عورتیں چیخ پڑیں، اور رونے لگیں، ابن عتیک انہیں چپ کرانے لگے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں چھوڑ دو لیکن جب واجب ہو جائے تو ہرگز کوئی رونے والی نہ روئے\"۔ لوگوں نے پوچھا: اللہ کے رسول! (یہ) واجب ہونا کیا ہے؟ آپ نے فرمایا: \"مر جانا\"، ان کی بیٹی نے اپنے باپ کو مخاطب کر کے کہا: مجھے امید تھی کہ آپ شہید ہوں گے (کیونکہ) آپ نے اپنا سامان جہاد تیار کر لیا تھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یقیناً اللہ تعالی ان کی نیت کے حساب سے انہیں اجر و ثواب دے گا، تم لوگ شہادت سے کیا سمجھتے ہو؟\" لوگوں نے کہا: اللہ تعالی کے راستے میں مارا جانا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کے راستے میں مارے جانے کے علاوہ شہادت (کی) سات (قسمیں) ہیں، طاعون سے مرنے والا شہید ہے، پیٹ کی بیماری میں مرنے والا شہید ہے، ڈوب کر مرنے والا شہید ہے، عمارت سے دب کر مرنے والا شہید ہے، نمونیہ میں مرنے والا شہید ہے، جل کر مرنے والا شہید ہے، اور جو عورت جننے کے وقت یا جننے کے بعد مر جائے وہ شہید ہے\"۔\n§وضاحت\n۱؎: عبداللہ بن ثابت کی کنیت ہے مطلب یہ ہے کہ تقدیر ہمارے ارادے پر غالب آ گئی۔","الألباني: صحيح",{"u2":"حضرت جابر بن عتیک رضی اللہ عنہما نے بتایا کہ نبی صلی اللہ علیہ وسلم حضرت عبدالل بن ثابت رضی اللہ عنہ کی بیمار پرسی کےل یے تشریف لائے تو انھیں موت کی بے ہوشی میں پایا۔ آپ نے انھیں پکارا ماگر وہ جواب نہ دے سکے۔ رسول اللہ صلی اللہ علیہ وسلم نے [انا اللہ و انا الیہ راجعون] پڑھا اور فرمایا: ’’اے ابو الربیع! ہم تمھارے معاملے میں بے بس ہیں (ورنہ ہم تو تمھاری زندگی کے خواہش مند ہیں)۔‘‘ یہ سن کر عورتیں چیخ پکار کرنے لگیں۔ جابر بن عتیک انھیں چپ کرانے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’رہنے دو لیکن جب واجب ہو جائے تو پھر کوئی عورت (آواز سے) نہ روئے۔‘‘ لوگوں نے عرض کیا: اے اللہ کے رسول! واجب ہونا کیا ے؟ آپ نے فرمایا: ’’موت۔‘‘ ان کی بیٹی کہنے لگی: ابا جان! مجھے تو امید تھی کہ آپ شہید ہوں گے کیونکہ آپ نے اپنا سامانِ جہاد تیارکر رکھا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نےفرمایا: ’’یقیناً اللہ تعالیٰ نے ان کی نیت کے مطابق ان کا ثواب لکھ دیا ہے۔ (پھر حاضرین سے پوچھا:) تم شہادت کسے سمجھتےہو؟‘‘ انھوں نے کہا: اللہ تعالیٰ کے راستے میں مارا جانا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ’’اللہ عزوجل کے راستے میں مارے جانے کے علاوہ بھی شہادت کی سات صورتیں ہیں: طاعون سے مر جانے والا شہید ہے۔ پیٹ کی تکلیف سے مر جانے والا بھی شہید ہے۔ غرق ہوکر مرنے والا بھی شید ہے۔ دب کر مر جانے والا بھی شہید ہے۔ اندرونی پھوڑے (کینسر و سرطان وغیرہ) سے مر جانے والا بھی شہید ے۔ آگ میں جل کر مر جانے والا بھی شہید ہے اور زچگی کے دوران میں مر جانے والی عورت بھی شہید ہے۔‘‘","f2":"(۱)’’جب وہ مر جائے تو پھر کوئی نہ روئے‘‘ کیونکہ نوحہ و بین مرنے کے بعد ہوتے ہیں، پہلے نہیں، لہٰذا کسی کی موت سے پلے گھر والے رو سکتے ہیں کیونکہ رونا منع نہیں بلکہ نوحہ اور شکوہ شکایت منع ہے۔ جو موت کے بعدہی ہوتے ہیں۔ (۲) ’’شہادت فی سبیل اللہ‘‘ کے علاوہ شہادت کی سات صورتیں اور ہیں جن کی اس حدیث میں صراحت ہے۔ انھیں کس وجہ سے شہادت فی سبیل اللہ کے درجے میں رکھا گیا ہے؟ اللہ تعالیٰ ہی بہتر جانتا ہے۔ ہمیں بہرحال اس پر یقین رکھنا چاہیے کہ اللہ تعالیٰ حدیث میں مذکور افراد کو شہداء کے درجے سے سرفراز فرمائے گا۔ (۳) ’’سات صورتیں‘‘ بعض دیگر احادیث میں انفرادی طورپ ر شہادت کی اور بھی کئی صورتیں ذکر کی گئی ہیں۔ وہ اس روایت کے منافی نہیں کیونک سات میں زائد کی نفی نہیں۔ گویا بطور مثال یہ سات ذکر کی ہیں، ورنہ اور بھی ہیں۔ (۴) مریض کی عیادت کرنا ثواب کا کام ہے، نیز اس سے مریض کی دل جوئی ہوتی ہے۔ (۵) اعمال کا دارومدار نیتوں پر ہے، اس لیے اگر آدمی نے کسی کام کی نیت کی ہوئی ہو اور اس کے لیے تیاری مکمل ہے لیکن اسے کرنے کا موقع نہیں ملا، تو اسے اس کی نیت کے مطابق اس کام کے کرنے کا اجر مل جائے گا۔ (۶) عالم کو چاہیے ک مسئلہ سمجھانے کا ایسا انداز اپنائے کہ سامعین کے دل میں وہ راسخ ہو جائے، کسی قسم کا شبہ باقی نہ رہے۔ (۷) اللہ تعالیٰ کا اس امت پر فضل عظیم ہے کہ اس نے اس کے لیے شہادت کے کئی اسباب بنائے تاکہ یہ امت ان کی بنا پر بلند درجات حاصل کرسکے۔"}],[1847,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ جب زید بن حارثہ، جعفر بن ابی طالب اور عبداللہ بن رواحہ (رضی اللہ عنہم) کے مرنے کی خبر آئی تو رسول اللہ صلی اللہ علیہ وسلم بیٹھے (اور) آپ (کے چہرے) پر حزن و ملال نمایاں تھا، میں دروازے کے شگاف سے دیکھ رہی تھی (اتنے میں) ایک شخص آیا اور کہنے لگا: جعفر (کے گھر) کی عورتیں رو رہی ہیں، تو رسول اللہ صلی اللہ علیہ وسلم نے کہا: \"جاؤ انہیں منع کرو\"، چنانچہ وہ گیا (اور) پھر (لوٹ کر) آیا اور کہنے لگا: میں نے انہیں روکا(لیکن) وہ نہیں مانیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں منع کرو\" (پھر) وہ گیا (اور پھر لوٹ کر آیا، اور کہنے لگا: میں نے انہیں روکا (لیکن) وہ نہیں مان رہی ہیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"جاؤ ان کے منہ میں مٹی ڈال دو\"، عائشہ رضی اللہ عنہا نے کہا: میں نے کہا: اللہ تعالی اس شخص کی ناک خاک آلود کرے جو اللہ تعالی کی رحمت سے دور ہے، تو اللہ کی قسم! نہ تو رسول اللہ صلی اللہ علیہ وسلم کو پریشان کرنا چھوڑ رہا ہے، اور نہ تو یہی کر سکتا ہے (کہ انہیں سختی سے روک دے) ۱؎۔\n§وضاحت\n۱؎: مطلب یہ ہے کہ تو بار بار شکایات کر کے رسول اللہ صلی اللہ علیہ وسلم کو پریشان کرنے سے بھی باز نہیں آتا ہے، اور نہ یہی کرتا ہے کہ ڈانٹ ڈپٹ کر عورتوں کو رونے سے منع کر دے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی الل عنہا فرماتی ہیں کہ جب زید بن حارثہ، جعفر بن ابی طالب اور عبداللہ بن رواحہ رضی الل عنہم کی (غزوۂ موتہ میں) شہادت کی خبر آئی تو رسول اللہ صلی اللہ علیہ وسلم (مسجد میں) بیٹھ گئے۔ آپ کے چہرۂ مبارک پر غم کے آثار ہویدا تھے۔ میں دروازے کی جھری (درز) سے دیکھ رہی تھی کہ ایک آدمی آیا اور کہنے لگا: جعفر (کے گھر) کی عورتیں (اونچی اونچی) رو رہی ہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جا انھیں روک۔‘‘ وہ چلا گیا، پھر (کچھ دیر بعد) آگیا اور کہنے لگا: میں نے انھیںروکا ہے لیکن وہ رک نہیں رہیں۔ آپ نے فرمایا: ’’جا اور انھیں روک۔‘‘ وہ چلا گیا، پھر آگیا اور کہنے لگا: میں نے پھر روکا ہے مگر وہ پھر بھی باز نہیں آئیں۔ آپ نے فرمایا: ’’جا پھر ان کے منہ میں مٹی ڈال دے۔‘‘ حضرت عائشہ نے فرمایا: میں نے (غصے سے) کا: اللہ تجھے ذلیل کرے۔ اللہ کی قسم! نہ تو تو رسول اللہ صلی اللہ علیہ وسلم کو سکون سے بیٹھنے دیتا ہے اور نہ تو کچھ کرسکتا ہے۔","f2":"(۱)کسی قریبی کی موت پر انسان گھر سے باہر کسی کھلی جگہ غم کی حالت میں بیٹھ سکتا ہے کہ دوسرے لوگ بھی افسوس کے لیے آئیں اور اس کے پاس بیٹھیں اور تعزیت کریں۔ (۲) کسی کی شہادت پر بھی اظہار غم کیا جائے گا اگرچہ یہ اعلیٰ درجے کی موت ہے، مگر ہے تو موت ہی جو غم و اندوہ کا موجب ہے۔ (۳) ’’اللہ اس بے سمجھ کو ذلیل کرے‘‘ انسان کو اسی کام میں داخل دینا چاہیے جو اس کے بس میں ہو۔ ظاہر ہے عورتوں کو ان کا کوئی قریبی ہی چپ کرا سکتا ہے۔ یہ اجنبی کیا کرسکتا تھا؟ لہٰذا اسے اطلاع کرنے کے بعد آرام سے بیٹھ جانا چاہیے تھا تاکہ اللہ کے رسول صلی اللہ علیہ وسلم کسی متعلق شخص کو بھتیجے مگر اس نے خود آرام کیا نہ آپ کو آرام سے بیٹھنے دیا، حالانکہ یہ غم کا موقع تھا۔ ایسے موقع پر زیادہ شور و غل مناسب نہیں۔ بہرصورت وہ شخص نیک تھا۔ ثابت ہوا میت پر آواز کے ساتھ رونا جائز نہیں، تبھی آپ نے روکنے کا حکم دیا۔ یہ الگ بات ہے کہ وہ عمل درآمد نہ کراسکا۔ (۴) تاکید کے لیے قسم اٹھانا جائز ہے۔"}],[1848,"عمر رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"میت کو اس کے گھر والوں کے رونے کی وجہ سے عذاب دیا جاتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میت کو اس کے گھر والوں کے اس پر رونے سے عذاب دیا جاتا ہے۔‘‘"}],[1849,"محمد بن سیرین کہتے ہیں کہ عمران بن حصین رضی اللہ عنہما کے پاس ذکر کیا گیا کہ میت کو زندوں کے رونے کی وجہ سے عذاب دیا جاتا ہے، تو انہوں نے کہا: اسے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت محمد بن سیرین رحمہ اللہ فرماتے ہیں: حضرت عمران بن حصین رضی اللہ عنہما کے پاس یہ بات ذکر کی گئی کہ میت کو زندہ لوگوں کے رونے سے عذاب ہوتا ہے تو عمران رضی اللہ عنہ کہنے لگے: یہ بات رسول اللہ صلی اللہ علیہ وسلم نے ارشاد فرمائی ہے۔"}],[1850,"عمر رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میت کو اس کے گھر والوں کے رونے کی وجہ سے عذاب دیا جاتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میت کو اس کے گھر والوں کے اس پر رونے کی وجہ سے عذاب دیا جاتا ہے۔‘‘","f2":"مندرجہ بالا حدیث حضرت عائشہ رضی اللہ عنہا کو بیان کی گئی تو انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے ایسے نہیں فرمایا۔ حضرت عمر یا عبداللہ بن عمر رضی اللہ عنہا کو غلطی لگی۔ بات ی تھی کہ رسول اللہ صلی اللہ علیہ وسلم ایک مرنے والی یہودی عورت کے گھر کے پاس سے گزرے تھے، اس کے گھر والے اس پر رو رے تھے، آپ نے فرمایا: ’’ی رو رے ہیں، اس کو عذاب ہو رہا ہے۔‘‘ آپ کا مطلب تو یہ تھا کہ اس کو اس کے کفر کی وجہ سے عذاب ہو رہا ہے مگر حضرت عمر یا ابن عمر رضی اللہ عنہما کو غلطی لگی۔ انھوں نے سمجھا، رونے کی وجہ سے عذاب ہو رہا ہے، حالانکہ کسی کی غلطی اور گناہ سے دوسرے کو عذاب کیوں ہو؟ روتا کوئی ہے، عذاب میت کو۔ (لا تزر وازرہ وزر اخری) (بنی اسرآءیل ۱۵:۱۷)\nحضرت عائشہ رضی اللہ عنہا کی ی بات انتہائی معقول ہے مگر صورت حال یہ ہے کہ یہ روایت ایک دو سے نہیں بلکہ بہت سے صحابۂ کرام رضی اللہ عنہم سے مروی ے۔ کیا سب کو غلطی لگ گئی جبکہ حضرت عائشہ رضی الل عنہا تو موقع پر موجود بھی نہ تھیں؟ اور پھر حضرت عمر فاروق رضی اللہ عنہ جیسے مجتہد اور فقی صحابی بھی بات نہ سمجھ سکے؟ حضرت عائش رضی اللہ عنہا کا بیان کردہ واقعہ بھی صحیح ے مگر اس سے یہ لازم نہیں آتا کہ رسول اللہ صلی اللہ علیہ وسلم سے نے دوسرے الفاظ (یعذب المیت……… الخ) ارشاد نہ فرمائے ہوں۔ باقی رہی بات (لا تزر وازرۃ وزر اخری) ’’کوئی کسی کا بوجھ نہیں اٹھاتا۔‘‘ (بنی اسرآءیل ۱۵:۱۷) کی تو علماء نے اس کی توجیہ میں کہا ہے کہ عذاب اس میت کو ہوتا ے جو اپنے گھر والوں کو رونے کا حکم دے کر مرا ہو یا اس نے رونے سے منع نہ کیا ہو جبکہ رونے کا رواج ہو۔ یا جو اپنی زندگی میں ایسے رونے کو اچھا سمجھتا تھا اور اس کی حوصلہ افزائی کرتا تھا۔ اس اعتبار سے مرنے والے پر گھر والوں کے رونے کی وجہ سے عذاب کا ہونا آیت (لا تزر وازرۃ ……… الخ) کے خلاف نہیں ہے کیونکہ اس میں اس کا ایمایا پسندیدگی شامل ہے۔"}],[1851,"قیس بن عاصم رضی اللہ عنہ نے کہا تم میرے اوپر نوحہ مت کرنا کیونکہ رسول اللہ صلی اللہ علیہ وسلم پر نوحہ نہیں کیا گیا۔ یہ لمبی حدیث سے مختصر ہے۔\n§وضاحت\n۱؎: میت پر اس کے اوصاف بیان کر کے چلا چلا کر رونے کو نوحہ کہتے ہیں۔","الألباني: صحيح الإسناد",{"u2":"حضرت قیس بن عاصم رضی اللہ عنہ نے (اپنی وفات سے پہلے) فرمایا: مجھ پر نوحہ نہ کرنا کیونکہ رسول اللہ صلی اللہ علیہ وسلم پر نوحہ نہیں کیا گیا۔ یہ روایت مختصر ہے۔","f2":"نوحے سے مراد ہے میت کے (جھوٹے یا سچے) اوصاف ذکر کرکے اونچی اونچی آواز سے رونا، یہ منع ے کیونکہ عام طور پر اس موقع پر مبالغہ آرائی کی جاتی ے۔ عرب معاشرے میں تو باقاعدہ پیشہ ور نوحہ کرنے والوں کی خدمات حاصل کی جاتی تھیں جو اپنی طرف سے جوڑ جوڑ کر اوصاف ذکر کرتے حتی کہ وہ غم کے بجائے فخر و مباہات اور فصاحت وبلاغت کی مجلس بن جاتی۔ علاوہ ازیں آواز سے رونا بھی منع ے اور نوحہ بغیر آواز کے ہو ہی نہیں سکتا۔ میت کے مرثیے پڑھ پڑھ کر لوگوں کو لازنا بھی نوحے میں داخل اور حرام ہے۔"}],[1852,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جس وقت عورتوں سے بیعت لی تو ان سے یہ بھی عہد لیا کہ وہ نوحہ نہیں کریں گی، تو عورتوں نے کہا: اللہ کے رسول! کچھ عورتوں نے زمانہ جاہلیت میں (نوحہ کرنے میں) ہماری مدد کی ہے، تو کیا ہم ان کی مدد کریں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا:\"اسلام میں (نوحہ پر) کوئی مدد نہیں\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ے، رسول اللہ صلی اللہ علیہ وسلم نے مسلمان ہونے والی عورتوں سے (زبانی) بیعت لی تو ان سے عہد لیا کہ وہ نوحہ نہیں کریں گی۔ انھوں نے کہا: اے اللہ کے رسول! کچھ عورتوں نے دور جاہلیت میں نوحے میں ہماری مدد کی تھی تو کیا ہم ان کی مدد کرلیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اسلام میں ایسی مدد کرنا جائز نہیں۔‘‘","f2":"جاہلیت میں یہ تعاون عام تھا کہ غم کی بنا پر نہیں بلکہ اس بنا پر کی میت پر نوحہ کرنے جاتی تھیں کہ اس میت کی رشتے دار عورتوں نے ہماری ایک میت پر آکر نوحہ کیا تھا، حالانکہ یہ گناہ میں تعاون ے، لہٰذا اس میں بدل دینا بھی حرام ہے۔"}],[1853,"عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"میت کو اس کی قبر میں اس پر نوحہ کرنے کی وجہ سے عذاب دیا جاتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا ہے کہ میت پر نوحہ کرنے سے اس کو قبر میں عذاب دیا جاتا ہے۔"}],[1854,"عمران بن حصین رضی اللہ عنہ کہتے ہیں کہ انہوں نے کہا کہ میت کو اس کے گھر والوں کے نوحہ کرنے کی وجہ سے عذاب دیا جاتا ہے، اس پر ایک شخص نے ان سے کہا: مجھے بتائیے کہ ایک شخص خراسان میں مرے، اور اس کے گھر والے یہاں اس پر نوحہ کریں تو اس پر اس کے گھر والوں کے نوحہ کرنے کی وجہ سے عذاب دیا جائے گا،(یہ بات عقل میں آنے والی نہیں)؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا، اور تو جھوٹا ہے ۱؎۔\n§وضاحت\n۱؎: یہی جواب ہے اس شخص کا جو حدیث کے ہوتے ہوئے عقل اور قیاس کے گھوڑے دوڑائے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما فرماتے ہیں کہ میت کو گھر والوں کے نوحہ کرنے کی وجہ سے عذاب دیا جاتا ہے۔ ایک آدمی نے ان سے کہا: آپ بتائیں ایک آدمی خراسان میں مر گیا اور اس کے گھر والوں نے اس پر یہاں نوحہ کیا، تو کیا اسے وہاں گھر والوں کے نوحہ کرنے کی وجہ سے عذاب ہوگا؟ (یعنی ایسے نہیں ہو سکتا) حضرت عمران نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا ہے، تو ہی غلط کہتا ہے۔","f2":"تفصیل بحث دیکھیے حدیث نمبر ۱۸۵۱ اور اس کے فوائد و مسائل۔"}],[1855,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میت کو اس کے گھر والوں کے رونے کے سبب عذاب دیا جاتا ہے\"، اسے ام المؤمنین عائشہ رضی اللہ عنہا سے ذکر کیا گیا تو انہوں نے کہا: انہیں (ابن عمر کو) غلط فہمی ہوئی ہے (اصل واقعہ یوں ہے) رسول اللہ صلی اللہ علیہ وسلم ایک قبر کے پاس سے گزرے تو کہا: اس قبر والے کو عذاب دیا جا رہا ہے، اور اس کے گھر والے اس پر رو رہے ہیں، پھر انہوں نے یہ آیت پڑھی: «ولا تزر وازرة وزر أخرى» \"کوئی بوجھ اٹھانے والا کسی دوسرے کا بوجھ نہیں اٹھائے گا\" (فاطر: ۱۸)۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہا نے کہا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ میت کو اس کے گھر والوں کے رونے کی وجہ سے عذاب دیا جاتا ہے۔‘‘ یہ بات حضرت عائشہ رضی اللہ عنہا سے ذکر کی گئی تو فرمانے لگیں: ابن عمر کو غلطی لگ گئی۔ بات یہ تھی کہ نبی صلی اللہ علیہ وسلم ایک قبر کے پاس سے گزرے تھے۔ آپ نے فرمایا: ’’اس قبر والے کو (اپنے گناہوں کی وجہ سے) عذاب ہو رہا ہے اور اس کے گھر والے اس پر رو رہے ہیں۔‘‘ پھر حضرت عائشہ نے یہ آیت پڑھی: (لا تزر وازرۃ وزر اخری) ’’کوئی بوجھ اٹھانے والا کسی کا بوجھ نہیں اٹھائے گا۔‘‘ (دیکھیے، حدیث: ۱۸۵۱)"}],[1856,"عمرہ سے روایت ہے کہ انہوں نے ام المؤمنین عائشہ رضی اللہ عنہا سے سنا جب ان کے سامنے اس بات کا ذکر کیا گیا کہ عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں: میت کو زندوں کے رونے کی وجہ سے عذاب دیا جاتا ہے، تو عائشہ رضی اللہ عنہا نے کہا: اللہ تعالی ابوعبدالرحمٰن کی مغفرت کرے، سنو! انہوں نے جھوٹ اور غلط نہیں کہا ہے، بلکہ وہ بھول گئے انہیں غلط فہمی ہوئی ہے (اصل بات یہ ہے) رسول اللہ صلی اللہ علیہ وسلم ایک یہودیہ عورت (کی قبر) کے پاس سے گزرے جس پر (اس کے گھر والے) رو رہے تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ لوگ اس پر رو رہے ہیں اور اسے عذاب دیا جا رہا ہے\"۔","الألباني: صحيح",{"u2":"حضرت عمرہ رضی اللہ عنہا نے کہا کہ حضرت عائشہ رضی اللہ عنہا کے سامنے ذکر کیا گیا کہ حضرت ابن عمر رضی اللہ عنہا کہتے ہیں: بلاشبہ میت کو زندہ لوگوں کے اس پر رونے کی وجہ سے عذاب دیا جاتا ہے۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: اللہ تعالیٰ ابو عبدالرحمًن (ابن عمر رضی اللہ عنہما) کو معاف فرمائے، انھوں نے جھوٹ نہیں بولا لیکن وہ بھول گئے یا انھیں غلطی لگ گئی، حقیقت یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم ایک فوت شدہ یہودی عورت (کے گھر) کے پاس سے گزرے جس پر رویا جا رہا تھا تو آپ نے فرمایا: ’’یہ لوگ اس پر رو رہے ہیں جبکہ اسے (اپنے کفر اور گناہوں کی بنا پر) عذاب دیا جا رہا ہے۔‘‘"}],[1857,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی کافر کے عذاب کو اس پر اس کے گھر والوں کے رونے کی وجہ سے بڑھا دیتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے منقول ہے کہ حضرت عائشہ رضی اللہ عنہما نے فرمایا کہ رسول اللہ صلی اللہ علیہ وسلم نے تو یہ فرمایا تھا: ’’بیشک اللہ تعالیٰ کافر کے لیے اس کے گھر والوں کے اس پر بعض (مخصوص قسم کے) رونے کی وجہ سے عذاب میں اضافہ کر دیتا ہے۔‘‘"}],[1858,"ابن ابی ملیکہ کہتے ہیں کہ جب ام ابان مر گئیں تو میں (بھی) لوگوں کے ساتھ (تعزیت میں) آیا، اور عبداللہ بن عمر اور عبداللہ بن عباس رضی اللہ عنہم کے بیچ میں بیٹھ گیا، عورتیں رونے لگیں تو ابن عمر رضی اللہ عنہما نے کہا: کیا تم انہیں رونے سے روکو گے نہیں؟ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"میت کو اس کے گھر والوں کے رونے کے سبب عذاب دیا جاتا ہے\"، اس پر ابن عباس رضی اللہ عنہما نے کہا: عمر رضی اللہ عنہ بھی ایسا ہی کہتے تھے، (ایک بار) میں عمر رضی اللہ عنہ کے ساتھ نکلا یہاں تک کہ ہم بیداء پہنچے، تو انہوں نے ایک درخت کے نیچے کچھ سواروں کو دیکھا تو (مجھ سے) کہا: دیکھو (یہ) سوار کون ہیں؟ چنانچہ میں گیا تو میں نے دیکھا کہ وہ صہیب رضی اللہ عنہ اور ان کے گھر والے ہیں، لوٹ کر ان کے پاس آیا، اور ان سے کہا: امیر المؤمنین! وہ صہیب رضی اللہ عنہ اور ان کے گھر والے ہیں، تو انہوں نے کہا: صہیب رضی اللہ عنہ کو میرے پاس لاؤ، پھر جب ہم مدینہ آئے تو عمر رضی اللہ عنہ زخمی کر دئیے گئے، صہیب رضی اللہ عنہ ان کے پاس روتے ہوئے بیٹھے (اور) وہ کہہ رہے تھے: ہائے میرے بھائی! ہائے میرے بھائی! تو عمر رضی اللہ عنہ نے کہا: صہیب! روؤ مت، کیونکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"میت کو اس کے گھر والوں کے رونے کی وجہ سے عذاب دیا جاتا ہے\" (ابن عباس) کہتے ہیں: میں نے اس بات کا ذکر عائشہ رضی اللہ عنہا سے کیا تو انہوں نے کہا: سنو! اللہ کی قسم! تم یہ حدیث نہ جھوٹوں سے روایت کر رہے ہو، اور نہ ایسوں سے جنہیں جھٹلایا گیا ہو، البتہ سننے (میں) غلط فہمی ہوئی ہے، اور قرآن میں (ایسی بات موجود ہے) جس سے تمہیں تسکین ہو: «ألا تزر وازرة وزر أخرى» \"کوئی بوجھ اٹھانے والا دوسرے کا بوجھ نہیں اٹھائے گا\" البتہ رسول اللہ صلی اللہ علیہ وسلم نے (یوں) فرمایا تھا: \"اللہ کافر کا عذاب اس کے گھر والوں کے رونے کی وجہ سے بڑھا دیتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن ابی ملیکہ نے کہا: جب (حضرت عثمان رضی اللہ عنہ کی بیٹی) ام ابان فوت ہوئیں تو میں بھی لو گو ں کے ساتھ (ان کے گھر) گیا۔ مجھے حضرت عبداللہ بن عمر اور عبداللہ بن عباس رضی اللہ عنہ کے قریب بیٹھنے کا مو قع ملا۔ عورتیں رونے لگیں تو حضرت عبداللہ بن عمر رضی اللہ عنہ نے کہا:کیا آپ نے انھیں رونے سے نہیں روکتے؟ بلاشبہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فر ماتے سنا ہے: \" میت کو اس کے گھر و الوں کے اس پر بعض (مخصو ص قسم کے) رونے کی وجہ سے عذاب ہو تا ہے۔\" حضرت ابن عباس فرمانے لگے: حضرت عمر رضی اللہ عنہ بھی ایسی ہی بات کہتے تھے۔ میں ایک دفعہ حضرت عمر رضی اللہ عنہ کے ساتھ سفر میں نکلا حتی کہ جب ہم بیدا ر کے مقام پر پہنچے تو حضرت عمر رضی اللہ عنہ نے ایک درخت کے نیچے ایک قافلہ دیکھا تو فرمایا: جاو، دیکھو یہ قافلے والے کون ہیں؟ میں گیا رتو وہ حضرت صہیب رضی اللہ عنہ اور ان کے گھر والے تھے۔ میں نے واپس آکر بتا یا: امر المو منین! وہ صہیب رضی اللہ عنہ اور ان کے گھر والے ہیں۔ فرمایا: صہیب کو میرے پاس لاو، پھر ہم جب مدینہ منورہ آئے تو (چند دن بعد) حضرت عمر رضی اللہ عنہ پر قاتلانہ حملہ ہو گیا۔ حضرت صہیب رضی اللہ عنہ ان کے پاس بیٹھ کر رونے لگے اور کہنے لگے: ہائے میرے پیارے بھائی ْ! ہائے میرے پیا رے بھائی! حضرت عمر رضی اللہ عنہ نے فر ما یا: صہیب! نہ رو، کیو نکہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے:\" میت کو اس کے گھر والو ں کے اس پر بعض (مخصوص قسم کے) رونے کی بنا پر عذاب دیا جاتا ہے۔\"حضرت ابن عباس رضی اللہ عنہ نے کہا: میں نے یہ بات حضرت عائشہ رضی اللہ عنہا سے ذکر کی تو فرمانے لگیں: اللہ کی قسم! تم یہ حدیث کسی جھوٹے اور جھوٹ کی طرف منسوب اشخاص سے بیان نہیں کرتے لیکن سننے میں غلطی لگ جاتی ہے۔ تمھارے لیے قرآن مجید میں اس کا شافی حل موجو د ہے (لا تزر وازرۃ وزر اخری) کوئی بوجھ اٹھانے والا کسی دوسرے کابوجھ نہیں اٹھائے گا۔ \"لیکن رسو ل اللہ صلی اللہ علیہ وسلم نے یو ں فر مایا تھا:\" اللہ تعالیٰ کافر کے عذاب میں اس کے گھر والوں کے اس پر رونے کی وجہ سے اضافہ فرما تا ہے۔\"","f2":"تفصیلی بحث پیچھے حدیث نمبر ۱۸۵۱ میں گزر چکی ہے۔"}],[1859,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے خاندان میں کسی کا انتقال ہو گیا تو عورتیں اکٹھا ہوئیں (اور) میت پر رونے لگیں، تو عمر رضی اللہ عنہ کھڑے ہو کر انہیں روکنے اور بھگانے لگے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمر! انہیں چھوڑ دو کیونکہ آنکھوں میں آنسو ہے، دل غم میں ڈوبا ہوا ہے، اور موت کا وقت قریب ہے\"۔","الألباني: ضعيف",{"u2":"حضرت ابو ہر یرہ رضی اللہ عنہ بیان کر تے ہیں کہ رسو ل اللہ صلی اللہ علیہ وسلم کی آل میں سے ایک شخصیت فو ت ہو گئی تو عورتیں اکٹھی ہو کر رونے لگیں۔ حضرت عمڑ رضی اللہ عنہ اٹھ کر انھیں روکنے اور ان کومنتشر کر نے لگے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" عمر! رہنے دو۔ آنکھوں سے ا ٓنسو گراہی کر تے ہیں،دل میں صد مہ ہو تا ہی ہے اور ابھی وفات تازہ ہے۔\"","f2":"فائدہ: مذکو ر کو رہ روایت سند ا ضعیف ہے لیکن حدیث میں مذکور مسئلہ دیگر صحیح شواہد کی بنا پر صحیح ہے کہ صدمے کی وجہ سے فطری طور پر جو رونا ا ٓجاتا ہے، وہ جائز ہے، وہ ممنو ع ررونے کی قسم میں نہیں ا ٓتا۔ علامہ اتیو بی نے مذکورہ حدیث کی شرح کرتے ہوئے اس کے شواہد کا تذ رہ کیا ہے اور بہت ہی نفیس بحث کی ہے۔ تفصیل کے لیے ملاحظہ فرمائیں:(ذخيرة العقبيٰ شرح سنن النسائی:18/314۔320)"}],[1860,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ شخص ہم میں سے نہیں ۱؎ جو منہ پیٹے، گریباں پھاڑے، اور جاہلیت کی پکار پکارے (یعنی نوحہ کرے)\"۔ یہ الفاظ علی بن خشرم کے ہیں، اور حسن کی روایت «بدعا الجاہلیۃ» کی جگہ «بدعوی الجاہلیۃ» ہے۔\n§وضاحت\n۱؎: یعنی ہمارے طریقے پر نہیں ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص ہم میں سے نہیں جو (کسی مصیبت پر) رخساروں پر تھپڑ مارتا ہےے، گریبان پھاڑتا ہے یا دور جاہلیت کی پکار پکارتا (نوحہ کرتا) ہے۔‘‘\nیہ الفاظ (امام نسائی رحمہ اللہ کے استاد) علی (بن خشرم) نے بیان کیے ہیں جبکہ (امام صاحب کے دوسرے استاد حسن (بن اسماعیل بدعاء کی بجائے) بدعوی کے الفاظ بیان کرتے ہیں۔ (جبکہ معنی و مفہوم ایک ہی ہے، صرف الفاظ کا فرق ہے۔)","f2":"(۱)’’ہم میں سے نہیں‘‘ یعنی وہ ہمارے جاری کردہ طریقے پر نہیں بلکہ اس فعل میں کافروں جیسا ہے، نہ کہ وہ کافر ہو جاتا ہے۔ (۲) اللہ تعالیٰ کے فیصلے کو رضامندی سے تسلیم کرنا چاہیے۔ آہ و بکاناشکری کے زمرے میں آتی ہے۔"}],[1861,"صفوان بن محرز کہتے ہیں کہ ابوموسی اشعری پر بے ہوشی طاری ہو گئی، لوگ ان پر رونے لگے، تو انہوں نے کہا: میں تم سے اپنی برات کا اظہار کرتا ہوں جیسے رسول اللہ صلی اللہ علیہ وسلم نے ہم سے یہ کہہ کر برات کا اظہار کیا تھا کہ جو سر منڈائے کپڑے پھاڑے، واویلا کرے ہم میں سے نہیں۔\n§وضاحت\n۱؎: یعنی مصیبت کے موقع پر سر منڈائے جیسے ہندو منڈواتے ہیں۔","الألباني: صحيح",{"u2":"حضرت صفوان بن محرز بیان کرتے ہیں کہ حضرت ابو موسیٰ اشعری رضی اللہ عنہ بے ہوش ہوگئے تو گھر والے ان پر رونے لگ گئے۔ (ہوش میں آنے کے بعد) انھوں نے فرمایا: میں تمھارے اس فعل سے براءت کا اظہار کرتا ہوں جیسے رسول اللہ صلی اللہ علیہ وسلم نے ہمارے سامنے اس سے براءت فرمائی تھی: ’’وہ شخص ہم میں سے نہیں جو (مصیبت کے موقع پر) بال منڈوائے، کپڑے پھاڑے اور چیخ و پکار کرے۔‘‘","f2":"(۱)بعض حضرات نے سلق کے معنی رخسار پیٹنا بھی کیے ہیں۔ (۲) اگرچہ گھر والے حضرت ابو موسیٰ رضی اللہ عنہ کی بے ہوشی پر روئے تھے مگر انھیں خدشہ ہوا کہ یہ میری وفات پر بھی روئیں گے، اس لیے تنبیہ فرمائی ……… رضي اللہ عنہ وأرضاہ………"}],[1862,"عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو گال پیٹے، گریباں پھاڑے، اور جاہلیت کی پکار پکارے ہم میں سے نہیں\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص ہم میں سے نہیں جو (مصیبت کے وقت) رخسار پیٹے، گریبان پھاڑے اور جاہلت جیسی چیخ و پکار کرے۔‘‘"}],[1863,"عبدالرحمٰن بن یزید اور ابوبردہ رضی اللہ عنہما کہتے ہیں کہ جب ابوموسی اشعری (کی بیماری) سخت ہوئی، تو ان کی عورت چلاتی ہوئی آئی۔ (ان کی بیماری میں کچھ)افاقہ ہوا، تو انہوں نے کہا: کیا میں تجھے نہ بتاؤں کہ میں ان چیزوں سے بری ہوں جن سے رسول اللہ صلی اللہ علیہ وسلم بری تھے، ان دونوں نے ان کی بیوی سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے: \"میں اس شخص سے بری ہوں جو سر منڈائے، کپڑے پھاڑے اور واویلا کرے\"۔","الألباني: صحيح",{"u2":"حضرات عبدالرحمٰن بن یزید اور ابوبردہ فرماتے ہیں کہ: جب حضرت ابو موسیٰ اشعری رضی اللہ عنہ کی تکلیف (مرض الموت میں) بڑھ گئی تو ان کی بیوی روتی چلاتی ہوئی آئی، وہ ہوش میں آئے تو فرمانے لگے: کیا میں تجھے بتا نہ دوں کہ میں ہر شخص سے بری ہوں جس سے رسول اللہ صلی اللہ علیہ وسلم لاتعلق ہیں؟ حضرت ابو موسیٰ اپنی زوجۂ محترمہ کو یہ حدیث بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اس شخص سے لاتعلق ہوں جس نے (مصیبت کے موقع پر بطور سوگ) بال منڈوائے، کپڑے پھاڑے یا چیخ و پکار کی۔‘‘","f2":"جن بالوں کو منڈوناجائز ہے، مثلا: سر کے بال، سوگ کے طور پر انھیں مونڈنا بھی ناجائز ہے اور جن بالوں کو مونڈنا ناجائز ہے، مثلا: ڈاڑھی اور ابرو وغیرہ، انھیں سوگ سے مونڈنا تو بدرجۂ اولیٰ ناجائز ہوگا۔ دراصل شریعت کا منشا یہ ہے کہ انسان حوادث سے متاثر تو ہو مگر اس قدر نہیں کہ انسانی وقار مجروح یا ختم ہو جائے، انسانیت قائم رہنی چاہیے۔ مندرجہ بالا کام انسانی وقار کے خلاف ہیں، لہٰذا منع ہیں، البتہ بے اختیار آنکھوں سے آنسوؤں کا نکل آنا اور اسی طرح غم کا اظہار کرنا جائز ہے کیونکہ یہ فطری چیزیں ہیں بلکہ ایسے موقعوں پر ان فطری چیزوں کا بھی اظہار نہ ہو تو اس کا مطلب ہے کہ وہ شخص فطری رحمت سے عاری ہے اور فطرت سے بے نیازی (طبعاً ہو یا تکلفاً) انسانیت کے منافی ہے۔"}],[1864,"عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"وہ شخص ہم میں سے نہیں جو گال پیٹے، گریبان پھاڑے، اور جاہلیت کی پکار پکارے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مسعود رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص ہم میں سے نہیں جو (مصیبت کے وقت) رخسار پیٹے، گریبان پھاڑے اور جاہلیت کی پکار پکارے۔‘‘"}],[1865,"ابوموسی اشعری رضی اللہ عنہ سے روایت ہے کہ ان پر غشی طاری ہوئی، تو ان کی ام ولد رو پڑی، جب (کچھ) افاقہ ہوا تو انہوں نے اس سے کہا: کیا تجھے وہ بات نہیں پہنچی ہے جو رسول اللہ صلی اللہ علیہ وسلم نے فرمائی ہے؟ تو ہم نے اس سے پوچھا (آپ نے کیا فرمایا تھا؟) تو اس نے کہا: آپ نے فرمایا: \"وہ شخص ہم میں سے نہیں جو گال پیٹے، سر منڈائے، اور کپڑے پھاڑے\"۔","الألباني: صحيح",{"u2":"حضرت یزید بن اوس سے روایت ہے کہ حضرت ابو موسیٰ اشعری رضی اللہ عنہ بے ہوش ہوگئے تو ان کی ایک لونڈی (جو ان کے بچوں کی ماں بھی تھی) رونے لگی۔ جب وہ ہوش میں آئے تو اس سے فرمایا: کیا تجھے وہ بات نہیں پہنچی جو رسول اللہ صلی اللہ علیہ وسلم نے فرمائی ہے؟ (بعد میں) ہم نے اس لونڈی سے پوچھا تو اس نے بتایا کہ (انھوں نے فرمایا تھا) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص ہم میں سے نہیں جو (مصیبت کے موقع پر) چیے چلائے، بال مونڈے اور کپڑے پھاڑے۔‘‘"}],[1866,"ابوموسی اشعری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"وہ شخص ہم میں سے نہیں جو سر منڈائے، واویلا کرے اور کپڑے پھاڑے\"۔","الألباني: صحيح",{"u2":"حضرت ابو موسیٰ اشعری رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ شخص ہم میں سے نہیں جو (سوگ میں) بال مونڈے، چیخے چلائے یا کپڑے پھاڑے۔‘‘"}],[1867,"قرثع کہتے ہیں کہ جب ابوموسی اشعری رضی اللہ عنہ کی بیماری بڑھ گئی تو ان کی بیوی چیخ مار کر رونے لگی، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے جو فرمایا ہے کیا تجھے معلوم نہیں؟ اس نے کہا: کیوں، نہیں ضرور معلوم ہے، پھر وہ خاموش ہو گئی، تو اس سے اس کے بعد پوچھا گیا کہ رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ اس نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے (ہر اس شخص پر) لعنت فرمائی ہے جو سر منڈوائے، یا واویلا کرے، یا گریبان پھاڑے۔","الألباني: صحيح الإسناد",{"u2":"حضرت قرثع نے کہا: جب حضرت ابو موسیٰ رضی اللہ عنہ کو تکلیف زیادہ ہوگئی تو ان کی ایک زوجۂ محترمہ رونے لگیں، حضرت ابو موسیٰ نے فرمایا: کیا تجھے پتا نہیں کہ اس بارے میں رسول اللہ صلی اللہ علیہ وسلم نے کیا فرمایا ہے؟ وہ کہنے لگیں، کیوں نہیں؟ پھر وہ چپ ہوگئیں، بعد میں ان سے پوچھا گیا: اللہ کے رسول صلی اللہ علیہ وسلم کا وہ فرمان کیا تھا؟ وہ کہنے لگیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اس شخص پر لعنت کی ہے جو (سوگ کی بنا پر) بال مونڈے یا چیخے چلائے یا کپڑے پھاڑے۔"}],[1868,"اسامہ بن زید رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی بیٹی نے آپ کو صلی اللہ علیہ وسلم کہلا بھیجا کہ میرا بیٹا ۱؎ مرنے کو ہے آپ آ جائیں، تو آپ صلی اللہ علیہ وسلم نے کہلا بھیجا کہ آپ سلام کہتے ہیں، اور کہتے ہیں: اللہ تعالی ہی کے لیے ہے جو (کچھ) لے، اور اسی کے لیے ہے جو (کچھ) دے، اور اللہ کے نزدیک ہر چیز کا ایک وقت مقرر ہے، تو چاہیئے کہ تم صبر کرو، اور اللہ سے اجر طلب کرو، بیٹی نے (دوبارہ) قسم دے کے کہلا بھیجا کہ آپ صلی اللہ علیہ وسلم ضرور آ جائیں، چنانچہ آپ اٹھے، آپ کے ساتھ سعد بن عبادہ، معاذ بن جبل، ابی بن کعب، زید بن ثابت رضی اللہ عنہم اور کچھ اور لوگ تھے، (بچہ) رسول اللہ صلی اللہ علیہ وسلم کے پاس اٹھا کر اس حال میں لایا گیا کہ اس کی سانس ٹوٹ رہی تھی، تو آپ کی آنکھوں (سے) آنسو بہ پڑے، اس پر سعد رضی اللہ عنہ نے کہا: اللہ کے رسول! یہ کیا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"یہ رحمت ہے جو اللہ تعالی نے اپنے بندوں کے دلوں میں رکھ رکھا ہے، اور اللہ تعالی اپنے انہیں بندوں پر رحم کرتا ہے جو رحم دل ہوتے ہیں\"۔\n§وضاحت\n۱؎: اس سے مراد علی بن ابی العاص بن ربیع ہیں، اور ایک قول یہ ہے کہ بنت سے مراد فاطمہ رضی اللہ عنہا اور ابن سے مراد ان کے بیٹے محسن ہیں۔","الألباني: صحيح",{"u2":"حضرت اسامہ بن زید رضی اللہ عنہما بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کی بیٹی (حضرت زینب رضی اللہ عنہا) نے آپ کو پیغام بھیجا کہ میرا بیٹا قریب الوفات ہے، آپ تشریف لائیں، آپ نے جوابی پیغام بھیجا، سلام کہا اور فرمایا: ’’اللہ ہی کا ہے جو اس نے لے لیا اور اسی کا ہے جو اس نے دے رکھا تھا، اور اللہ تعالیٰ کے ہاں ہر چیز کی مدت مقرر ہے، لہٰذا اسے چاہیے کہ وہ صبر کرے اور (اگر کوئی مصیبت پہنچے تو) ثواب طلب کرنے کی نیت کرے۔‘‘ آپ کی بیٹی نے دوبارہ پیغام بھیجا اور آپ کو قسم دی کہ آپ ضرور تشریف لائیں۔ آپ اٹھے جبکہ آپ کے ساتھ حضرات سعد بن عبادہ، معاذ بن جبل، ابی بن کعب، زید بن ثابت اور بہت سے دوسرے صحابہ رضی اللہ عنھم بھی تھے۔ (جب آپ پہنچے تو) بچہ رسول اللہ صلی اللہ علیہ وسلم کو پکڑایا گیا۔ بچے کا سانس اکھڑ رہا تھا۔ آپ کی آنکھوں سے آنسو بہنے لگے۔ حضرت سعد نے کہا: اے اللہ کے رسول! یہ کیا ہے؟ آپ نے فرمایا: ’’یہ رحمت ہے جو اللہ تعالیٰ اپنے بندوں کے دلوں میں پیدا کرتا ہے اور اللہ تعالیٰ اپنے بندوں میں سے انھی پر رحم فرماتا ہے جو دوسروں پر رحم کرتے ہیں۔‘‘","f2":"(۱)’’صبر‘‘ سے مراد شریعت کے حکم کا پابند رہنا ہے، نہ یہ کہ افسوس نہ کرے یا آنسو نہ بہائے، یہ تو فطری چیزیں ہیں جو ممنوع یا ناپسندیدہ نہیں۔ (۲) بات کو پختہ کرنے کے لیے یا کسی سے مطالبہ منوانے کے لیے قسم ڈال دینا درست ہے۔ (۳) اگر کوئی اس طرح قسم ڈال دے تو اس کی قسم کو پورا کرنا چاہیے۔ (۴) پہلے سلام پھر کلام ہونا چاہیے۔ (۵) مریض کی عیادت کرنی چاہیے، خواہ وہ اپنے سے کم تر ہی ہو یا چھوٹا بچہ ہی کیوں نہ ہو، اس سے اس کی حوصلہ افزائی ہوگی۔ (۶) اہل فضل و صلاح کو مریض یا قریب الوفات شخص کے پاس دعا کے لیے دعوت دی جا سکتی ہے۔ (۷) آدمی اپنے امام سے کوئی نئی چیز دیکھے تو وضاحت پوچھ سکتا ہے۔ (۸) سوال میں حسن ادب ملحوظ خاطر رہنا چاہیے۔ (۹) اللہ کی مخلوق کے ساتھ نرمی اور شفقت سے پیش آنا چاہیے۔ (۱۰) آہ و بکا کے بغیر رونا جائز ہے۔"}],[1869,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"صبر وہی ہے جو صدمہ (غم) پہنچتے ہی ہو\" ۱؎۔\n§وضاحت\n۱؎: کیونکہ رو پیٹ کر تو صبر سبھی کو آ جاتا ہے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’صبر پہلی چوٹ کے وقت ہے۔‘‘","f2":"مقصد یہ ہے کہ سوگ اور جزع فزع ہمیشہ تو نہیں رہ سکتے، آخر کار وہ ختم ہ ہی جائیں گے، مگر اسے صبر نہیں کہتے، صبر تو یہ ہے کہ انسان مصیبت کے ابتدائی وقت میں اپنے آپ کو شرعی احکام اور انسانی وقار کا پابند رکھے، اور یہی مشکل کام ہے، ثواب بھی اسی صبر کا ہے، رو پیٹ کر صبر کیا تو وہ کیا صبر ہے؟ بالآخر تو صبر کرنا ہی پڑتا ہے، لیکن یہ شریعت والا صب نہیں ہے، یہ تو مجورب یہے کہ اس کے بغیر چارہ نہیں۔ اجر و ثواب صرف اسی صبر میں ہے جو آزمائش اور غم کے وقت کیا جائے، نہ کہ اس کے بعد والے صبر پر۔"}],[1870,"قرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اس کے ساتھ اس کا بیٹا (بھی) تھا، آپ نے اس سے پوچھا: \"کیا تم اس سے محبت کرتے ہو؟\" تو اس نے جواب دیا: اللہ آپ سے ایسے ہی محبت کرے جیسے میں اس سے کرتا ہوں، پھر وہ (لڑکا) مر گیا، تو آپ نے (کچھ دنوں سے) اسے نہیں دیکھا تو اس کے بارے میں (اس کے باپ سے) پوچھا (تو انہوں نے بتایا کہ وہ مر گیا ہے) آپ نے فرمایا: \"کیا تمہیں اس بات سے خوشی نہیں ہو گی کہ تم جنت کے جس دروازے پر جاؤ گے (اپنے بچے) کو اس کے پاس پاؤ گے، وہ تمہارے لیے دوڑ کر دروازہ کھولنے کی کوشش کرے گا\"۔","الألباني: صحيح",{"u2":"حضرت قرہ مزنی رضی اللہ عنہ سے مروی ہے کہ ایک آدمی نبی صلی اللہ علیہ وسلم کے پاس آیا، اس کے ساتھ اس کا ایک بیٹا تھا۔ آپ نے اس آدمی سے فرمایا: ’’کیا تو اس سے محبت کرتا ہے؟‘‘ اس نے کہا:اللہ تعالیٰ آپ سے ویسی ہی محبت فرمائےجیسی میں اس سے رکھتا ہوں (یعنی مجھے اس سے انتہا درجے کی محبت ہے۔) ہوا یوں کہ وہ بچہ فوت ہوگیا۔ آپ نے جب کئی دن اس شخص کو نہ دیکھا تو اس کے بارے میں پوچھا۔ (آپ کو بتایا گیا تو آپ نے اسے بلایا، وہ آیا تو) آپ نے فرمایا: ’’کیا تجھے یہ بات اچھی نہیں لگتی کہ تو (قیامت کے دن) جنت کے جس دروازے پر بھی جائے، وہاں اسے پائے، وہ بھاگتا ہوا تیرے لیے دروازہ کھولے؟‘‘","f2":"معلوم ہوتا ہے وہ بچہ نابالغ تھا۔ ایک دوسری حدیث کے مطابق نابالغ بچے پر صبر کا ثواب دخول جنت ہے کیونکہ نابالغ بچے سے پیار زیادہ ہوتا ہے، اس کی وفات کا صدمہ بھی زیادہ ہوتا ہے، نیز وہ معصوم اور بے گناہ ہونے کی وجہ سے اللہ کی رحمت کا زیادہ حق دار ہوتا ہے، اس کی سفارش رد نہیں ہوگی لیکن یہ سب کچھ تب ہے جب صبر کیا ہو اور ثواب کی نیت کی ہو۔"}],[1871,"عمرو بن شعیب نے عبداللہ بن عبدالرحمٰن بن ابی حسین کو ان کے بیٹے کی وفات پر تعزیت کا خط لکھا، اور اپنے خط میں ذکر کیا کہ انہوں نے اپنے والد کو بیان کرتے سنا وہ اپنے دادا عبداللہ بن عمرو بن عاص رضی اللہ عنہما سے روایت کر رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی اپنے مومن بندے کے لیے جب وہ زمین والوں میں سے اس کی سب سے محبوب چیز یعنی بیٹا کو لے لے، اور وہ اس پر صبر کرے، اور اجر چاہے، اور وہی کہے جس کا حکم دیا گیا ہے، جنت سے کم ثواب پر راضی نہیں ہوتا\"۔","الألباني: حسن",{"u2":"حضرت عمرو بن شعیب نے عبداللہ بن عبدالرحمٰن بن ابی حسین کو ان کے ایک فوت ہونے والے بیٹے کی تعزیت کرتے ہوئے (خط) لکھا کہ میں نے اپنے والد محترم (حضرت شعیب) کو اپنے دادا حضرت عبداللہ بن عمرو بن عاص رضی اللہ عنہما کی روایت سے یہ بیان فرماتے سنا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب اللہ تعالیٰ اپنے مومن بندے کے جگر گوشے کو اپنے پاس بلا لے، اور وہ اس پر صبر کرے اور اللہ تعالیٰ سے اس (مصیبت کےبدلے) ثواب طلب کرے اور وہی بات منہ سے نکالے جس کا اللہ تعالیٰ نے اسے حکم دیا ہے تو اللہ تعالیٰ جنت سے کم کوئی بدلہ اس کے لیے پسند نہیں فرماتا۔‘‘","f2":"ظاہر ہے اس سے گناہ معاف ہو جائیں گے کیونکہ جنت میں جانے سے پہلے گناہوں کی معافی ضروری ہے۔"}],[1872,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس شخص کی تین صلبی اولاد مر جائیں (اور) وہ اللہ تعالی سے اس کا اجر و ثواب چاہے، تو وہ جنت میں داخل ہو گا\" (اتنے میں) ایک عورت کھڑی ہوئی اور بولی: اور دو اولاد مرنے پر؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"دو اولاد کے مرنے پر بھی\"، اس عورت نے کہا: کاش! میں ایک ہی کہتی ۱؎۔\n§وضاحت\n۱؎: یعنی اگر میں ایک بچہ مرنے کی بات آپ سے پوچھتی تو قوی امید ہے کہ آپ ایک بچہ مرنے پر بھی یہی ثواب بتاتے۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص اپنی اولاد میں سے (فوت ہونے والے) تین بچوں کی وفات پر صبر کرے اور ثواب طلب کرے، وہ جنت میں جائے گا۔‘‘ ایک عورت کھڑ ہوکر کہنے لگی: اگر دو بچے ہوں تو؟ آپ نے فرمایا: ’’دو ہوں، تب بھی۔‘‘ (بعد میں) اس عورت نے کہا: کاش میں (ایک بچہ) بھی کہہ دیتی۔","f2":"(۱)ثواب تو دراصل صبر کا ہے، ایک بچے کی وفات پر ہو یا دو یا تین بچوں کی وفات پر۔ اگرچہ ثواب میں کمی بیشی تو ہوگی، بہرحال جنت میں جانے کے لیے ایک بچے کی وفات پر صبر کرنا اور ثواب طلب کرنا کافی ہے جیسا کہ روایت نمبر ۱۸۷۲ میں گزرا۔ (۲) صحابیات رضی اللہ عنھن بھی دین کے مسائل جاننے پر بہت حریص تھیں۔ وہ بڑے ذوق شوق سے مسائل کے بارے میں آگہی حاصل کرتیں۔ مسائل دریافت کرنے میں انھیں کوئی حجاب اور ہچکچاہٹ نہیں تھی۔ (۳) اہل اسلام کے سن بلوغت کو پہنچنے سے پہلے فوت ہونے والے بچے جنت میں جائیں گے۔"}],[1873,"انس رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس مسلمان کے بھی تین نابالغ بچے مر جائیں، تو اللہ تعالی اسے ان پر اپنی رحمت کے فضل سے جنت میں داخل کرے گا\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس مسلمان کے تین نابالغ بچے فوت ہو جائیں (پھر وہ ان پر صبر کرے) تو اللہ تعالیٰ ان (بچوں) پر اپنی رحمت زیادہ ہونے کے باعث اس (مسلمان) کو جنت میں داخل فرمائے گا۔‘‘","f2":"(۱)’’نابالغ‘‘ عربی الفاظہ ہیں [لم یبلغوا الحنث] حنث گناہ کو کہتے ہیں، یعنی وہ گناہ کی عمر، یعنی بلوغت کو نہ پہنچے ہوں کیونکہ بلوغت سے پہلے بچے کے گناہ لکھے نہیں جاتے۔ (۲) یہ ثواب نابالغ کے ساتھ خاص ہے۔ کیونکہ وہ بے گناہ ہوتا ہے، اس سے محبت بھی شددی ہوتی ہے اور اس کی وفات کا صدمہ بھی زیادہ ہوتا ہے جبکہ بالغ گناہ گار ہوتا ہے۔ اللہ تعالٰ کی رحمت اور ماں باپ کی محبت میں بھی فرق پڑ جاتا ہے کیونکہ ممکن ہے اس سے ماں باپ کے حقوق میں کمی ہو جاتی ہو۔ بعض حضرات نے بالغ کو درجۂ اولیٰ اس ثواب میں داخل کیا ہے کہ جب نابالغ کی وفات پر صبر کا ثواب یہ ہے جس سے والدین کو کوئی مفاد حاصل نہیں ہوتا بلکہ والدین کو خود اس پر خرچ کرناپ ڑتا ہے اور اس کی خدمت بھی کرنی پڑتی ہے تو بالغ کی وفات پر بدرجہ اولیٰ یہ ثواب ملے گا کیونکہ بالغ تو والدین کا سہارا ہوتا ہے، اس کی وفات کا صدمہ زیادہ ہوگا مگر یہ توجیہ حدیث کے ظاہر اور عرف انسانی کے خلاف ہے، پہلی بات ہی صریح تر ہے۔ واللہ أعلم۔"}],[1874,"صعصعہ بن معاویہ کہتے ہیں کہ میں ابوذر رضی اللہ عنہ سے ملا تو میں نے کہا: مجھ سے حدیث بیان کیجئے تو انہوں کہا: اچھا سنو، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا ہے:\"جس مسلمان ماں باپ کی بھی تین نابالغ اولاد مر جائیں تو اللہ تعالی ان کو ان پر اپنی رحمت کے فضل سے بخش دیتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت صعصعہ بن معاویہ نے کہا: میں حضرت ابوذر رضی اللہ عنہ سے ملا اور عرض کیا: مجھے کوئی حدیث بیان فرمائیں! فرمایا: اچھا، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو بھی دو مسلمان (ماں، باپ) ہوں اور ان کے تین نابالغ بچے فوت ہو جائیں تو اللہ تعالیٰ ان (بچوں) پر اپنی رحمت زیادہ ہونے کی وجہ سے ان دونوں (والدین) کے گناہ بھی معاف فرما دے گا۔‘‘"}],[1875,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں میں سے جس شخص کے بھی تین بچے مر جائیں، تو اسے جہنم کی آگ صرف قسم ۱؎ پوری کرنے ہی کے لیے چھوئے گی\"۔\n§وضاحت\n۱؎: وہ قسم یہ ہے کہ اللہ تعالی نے فرمایا ہے: «وإن منكم إلا واردها» :(مريم: 71 ) یعنی تم میں سے کوئی ایسا نہیں ہے جسے جہنم پر سے نہ آنا پڑے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس مسلمان شخص کے تین بچے فوت ہو جائیں (اور وہ ان پر صبر کرے) تو اسے آگ نہیں چھوئے گی مگر قسم پوری کرنے کے لیے۔‘‘","f2":"قسم سے مراد قرآن مجید میں اللہ تعالیٰ کا یہ فرمان ہے: (وان منکم الا واردھا کان علی ربک حتما مقضیا) (مریم ۷۱:۱۹) ’’اور تم میں سے ہر شخص جہنم میں جائے گا، یہ تیرے رب کے ذمے حتمی اور طے شدہ بات ہے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے اس کا مطلب یہ بیان فرمایا کہ ہر شخص کو صراط (پل صراط) پر سے گزرنا پڑے گا جو جہنم کے اوپر ہے تاکہ اس میں گناہو کے موجود اثرات جہنم کی تپش یا آگ سے ختم ہو جائیں اور وہ پاک صاف ہوکر جنت میں داخل ہو۔ چونکہ انسان طبعاً خطکار ہے، لہٰذا ہر انسان کا صراط پر سے گزرنا معقول ہے۔ یہ الگ بات ہے کہ معصوم انسان، مثلاً: انبیاء علیہم السلام بجلی کی طرح گزر جائیں گے۔"}],[1876,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس مسلمان ماں باپ کے تین نابالغ بچے مر جائیں، تو اللہ تعالی ان کو ان پر اپنی رحمت کے فضل سے جنت میں داخل کرے گا\"، آپ صلی اللہ علیہ وسلم فرماتے ہیں: \"ان سے کہا جائے گا: جنت میں داخل ہو جاؤ، تو وہ کہیں گے (ہم نہیں داخل ہو سکتے) جب تک کہ ہمارے والدین داخل نہ ہو جائیں، (پھر) کہا جائے گا: (جاؤ) اپنے والدین کے ساتھ جنت میں داخل ہو جاؤ\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جن مسلمان ماں باپ کے تین نابالغ بچے فوت ہو جائیں، اللہ تعالیٰ ان (بچوں) پر اپنی رحمت زیادہ ہونے کی وجہ سے ان کے ماں باپ کو بھی جنت میں داخل فرمائے گا۔ بچوں سے کہا جائے گا: تم جنت میں داخل ہو جاؤ۔ وہ کہیں گے: ہم تب جائیں گے جب ہمارے ماں باپ بھی جنت میں جائیں تو فرمایا جائے گا: تم اور تمھارے ماں باپ سب جنت میں داخل ہو جاؤ۔‘‘","f2":"اللہ تعالٰی یہ استحقاق جنت ان والدین کو عطا فرمائے گا جنھوں نے بچوں کی وفات پر صبر و رضا کے ثبوت کے ساتھ ساتھ ایمان و تقویٰ کی زندگی گزاری ہوگی۔ اللہ تعالیٰ ایسے اہل ایمان کے بارے میں ان بچوں کی سفارش قبول فرمائے گا اور انھیں پہلے مرحلے ہی میں جنت میں داخل فرما دے گا۔"}],[1877,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنا بیٹا لے کر آئی جو بیمار تھا، اور عرض کیا: اللہ کے رسول! میں ڈر رہی ہوں کہ یہ مر نہ جائے، اور (اس سے پہلے) تین بچوں کو بھیج چکی ہوں، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم نے جہنم کی آگ سے بچاؤ کے لیے زبردست ڈھال بنا لیا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس اپنے مریض بیٹے کو لے کر آئی اور کہنے لگی: اے اللہ کے رسول! مجھے اس (کی موت) کا خطرہ ہے جبکہ پہلے بھی میرے تین بچے مر چکے ہیں تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تو نے آگ سے (بچنے کے لیے) مضبوط رکاوٹ تیار کرلی ہے۔‘‘"}],[1878,"انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے زید اور جعفر کی موت کی اطلاع (کسی آدمی کے ذریعہ) ان کی (موت) کی خبر آنے سے پہلے دی، اس وقت آپ کی دونوں آنکھیں اشکبار تھیں۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت زید اور حضرت جعفر رضی اللہ عنہا کی وفات کی اطلاع ان کی خبر آنے سے پہلے ہی (بذریعۂ وحی) فرما دی تھی۔ جب آپ نے اطلاع فرمائی تو آپ کی آنکھوں سے آنسو بہہ رہے تھے۔","f2":"(۱)موت کی اطلاع دینا درست ہے۔ جبکہ ایک حدیث میں نعي سے روکا گیا ہے۔ دیکھیے: (مسند أحمد: ۳۸۵/۵) دراصل اس سے مراد جاہلیت کے دور کی طرح موت کا اعلان ہے جو صرف فخر و مباہات کے لیے بڑے بڑے جھوٹے سچے القابات کے ذریعے سے کیا جاتا تھا، اس کا مقصد اطلاع کے بجائے فخر تھا اور وہ باقاعدہ پیش ور حضرات کے ذریعے سے بڑے اہتمام اور خرچ کے ساتھ کیا جاتا تھا۔ (۲) یہ رسول اللہ صلی اللہ علیہ وسلم کا معجزہ تھا کہ صحابہ شام میں شہیدہوئے اور آپ نے مدینہ میں انکی خبر دے دی۔ شام سے ان کی شہادت کی خبر بعد میں آئی۔"}],[1879,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں حبشہ کے بادشاہ نجاشی کی موت کی خبر اسی دن دی جس دن وہ مرے، اور فرمایا:\"اپنے بھائی کے لیے مغفرت کی دعا کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے خبر دی کہ رسول اللہ صلی اللہ علیہ وسلم نے حبشہ کے بادشاہ نجاشی رحمہ اللہ کی وفات کی اطلاع (بذریعۂ وحی) اسی دن دے دی تھی جس دن وہ فوت ہوئے اور فرمایا: ’’اپنے بھائی کے لیے بخشش کی دعا کرو۔‘‘","f2":"نجاشی لقب تھا۔ نام ان کا اصحمہ تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے باقاعدہ صف بندی کے ساتھ ان کا جنازہ بھی پڑھایا تھا۔ تفصیل ان شاء اللہ آگے آئے گی۔"}],[1880,"عبداللہ بن عمرو رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلے جا رہے تھے کہ اچانک آپ کی نگاہ ایک عورت پہ پڑی، ہم یہی گمان کر رہے تھے کہ آپ نے اسے نہیں پہچانا ہے، تو جب بیچ راستے میں پہنچے تو آپ کھڑے ہو گئے یہاں تک کہ وہ (عورت) آپ کے پاس آ گئی، تو کیا دیکھتے ہیں کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی بیٹی فاطمہ رضی اللہ عنہا ہیں، آپ نے ان سے پوچھا: \"فاطمہ! تم اپنے گھر سے کیوں نکلی ہو؟\" انہوں نے جواب دیا: میں اس میت کے گھر والوں کے پاس آئی، میں نے ان کے لیے رحمت کی دعا کی، اور ان کی میت کی وجہ سے ان کی تعزیت کی، آپ نے فرمایا: \"شاید تم ان کے ساتھ کدی ۱؎ تک گئی تھیں؟\"انہوں نے کہا: اللہ کی پناہ! میں وہاں تک کیوں جاتی اس سلسلے میں آپ کو ان باتوں کا ذکر کرتے سن چکی ہوں جن کا آپ ذکر کرتے ہیں، تو آپ نے ان سے فرمایا: \"اگر تم ان کے ساتھ وہاں جاتی تو تم جنت نہ دیکھ پاتی یہاں تک کہ تمہارے باپ کے دادا (عبدالمطلب) اسے دیکھ لیں\" ۲؎۔ نسائی کہتے ہیں: ربیعہ ضعیف ہیں۔\n§وضاحت\n۱؎: «کُدَی کُدْیَۃ» کی جمع ہے جس کے معنی سخت زمین کے ہیں یہاں مراد قبرستان ہے۔ ۲؎: یہ جملہ «حتی یلج الجمل فی سم الخیاط»کے قبیل سے ہے، مراد یہ ہے کہ تم اسے کبھی نہیں دیکھ پاتی۔","الألباني: ضعيف",{"u2":"حضرت عبداللہ بن عمرو رضی اللہ عنہما بیان کرتے ہیں کہ: ایک دفعہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چلے جا رہے تھے کہ آپ نے ایک عورت کو دیکھا۔ وہ عورت یہ نہیں سمجھتی تھی کہ آپ نے اسے پہچان لیا ہے۔ جب آپ راستے کے درمیان میں پہنچے تو رک گئے حتی کہ وہ عورت آپ کے قریب پہنچ گئی تو پتا چلا کہ وہ رسول اللہ صلی اللہ علیہ وسلم کی بیٹی حضرت فاطمہ رضی اللہ عنہا ہیں۔ آپ نے ان سے کہا: ’’فاطمہ! گھر سے کیسے نکلی؟‘‘ انھوں نے کہا: میں فلاں میت کے گھر والوں کے پاس گئی تھی۔ میں نے ان سے اظہار افسوس کیا اور صبر کی تلقین کی اور تسلی دی۔ آپ نے فرمایا: ’’کہیں آپ ان کے ساتھ کدیٰ قبرستان میں تو نہی گئیں؟‘‘ انھوں نے کہا: اللہ کی پناہ کہ میں وہاں جاتی جبکہ میں نے آپ کو اس بارے میں بڑے سخت الفاظ فرماتے سنا ہے۔ آپ نے فرمایا: ’’اگر تو ان کے ساتھ قبرستان جاتی تو جنت کو دیکھ بھی نہ سکتی (داخل ہونا تو دور کی بات ہے) حتی کہ تیرے والد کے دادا (عبدالمطلب) اسے دیکھیں۔‘‘\nامام نسائی فرماتے ہیں ربیعہ ضعیف ہے۔","f2":"(۱)’’اس حدیث کے راوی ربیعہ کے ضعف کی صراحت کرکے امام نسائی رحمہ اللہ نے گویا اس روایت کے ضعیف ہونے کی طرف اشارہ فرمایا ہے۔ علمائے محققین نے مابین مذکورہ حدیث کی صحت و ضعف کی بابت اختلاف ہے۔ شیخ البانی رحمہ اللہ اور شارح سنن النسائی شیخ علی بن محمد اتیوبی نے اسے ضعیف قرار دیا ہے جبکہ محققین کتاب نے اس کی سند کو حسن کہا ہے، تاہم اگر مذکورہ روایت کو حسن بھی مان لیا جائے، پھر بھی اس روایت سے عورتوں کا قبرستان میں جانا ممنوع قرار نہیں پاتا کیونکہ یہ اس وقت کی بات ہے جب ابتدائے اسلام میں لوگوں کو قبرستان جانے سے روک دیا گیا تھا، پھر جب نبی صلی اللہ علیہ وسلم نے اس کی اجازت دے دی تو پھر مردوں کے ساتھ عورتوں کا بھی قبرستان جانے کا جواز نکل آیا کیونکہ اجازت کے الفاظ عام ہیں جن میں مرد اور عورت دونوں شامل ہیں، البتہ اس عموم سے وہ عورتیں خارج ہوں گی جو صبر و ضبط سے عاری اور غیرشرعی حرکتوں کی عادت ہوں۔ ایسی عورتوں کے لیے جانے کی اجازت نہیں ہوگی۔ واللہ أعلم۔ (۲) اس روایت میں کدیٰ سے مراد مکہ کا مقام کدیٰ نہیں بلکہ مدینہ منورہ کا قبرستان مراد ہے۔ (۳) عورت تعزیت کے لیے کسی کے گھر جاسکتی ہے۔"}],[1881,"ام عطیہ انصاریہ رضی اللہ عنہا کہتی ہیں کہ جس وقت رسول اللہ صلی اللہ علیہ وسلم کی بیٹی ۱؎ کی وفات ہوئی، آپ ہمارے پاس تشریف لائے اور فرمایا: \"اسے پانی اور بیر (کے پتوں) سے دو تین یا پانچ یا اس سے زیادہ بار اگر مناسب سمجھو غسل دو، اور آخری بار میں کچھ کافور یا کافور کی کچھ مقدار ملا لو (اور) جب تم (غسل سے)فارغ ہو تو مجھے خبر کرو\"۔ تو جب ہم فارغ ہوئے تو ہم نے آپ کو خبر دی تو آپ نے ہمیں اپنا تہبند دیا اور فرمایا: \"اسے ان کے بدن پر لپیٹ دو\" ۲؎۔\n§وضاحت\n۱؎: جمہور کے قول کے مطابق یہ زینب رضی اللہ عنہا تھیں، اور بعض اہل سیر کی رائے ہے کہ یہ ام کلثوم رضی اللہ عنہا تھیں، صحیح پہلا قول ہے۔ ۲؎: شعار اس کپڑے کو کہتے ہیں جو جسم سے ملا ہو، مطلب یہ ہے کہ اسے ان کے جسم پر لپیٹ دو پھر کفن پہناؤ۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ انصاریہ رضی اللہ عنہا سے روایت ہے، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم اپنی صاحبزادی کی وفات کے وقت ہمارے پاس تشریف لائے اور فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا اس سے زیادہ مرتبہ، اگر ضرورت ہوتو، پانی اور بیری کے پتوں سے غسل دو اور آخری مرتبہ کا فور ڈال دو یا تھوڑا سا کا فور شامل کر دو اور فارغ ہوکر مجھے اطلاع دینا۔‘‘ چنانچہ ہم نے فارغ ہوکر آپ کو اطلاع دی تو آپ نے ہمیں اپنا تہ بند دیا اور فرمایا: ’’اسے اس کے بدن پر لپیٹ دو۔‘‘","f2":"(۱)یہ آپ کی بیٹی حضرت زینب رضی اللہ عنہا تھیں۔ اگرچہ بعض نے حضرت ام کلثوم رضی اللہ عنہا بھی کہا ہے۔ (۲) بیری کے پتے صفائی اور نرمی وغیرہ کے لیے ڈالے جاتے تھے۔ یہی مقصد اگر کسی صابن سے پورا ہو جائے تو بیری کے پتے کوئی ضروری نہیں۔ اس وقت صابن وغیرہ نہ تھے۔ یہ چیزیں مقصود نہیں، ذرائع ہیں اور ذرائع بدلتے رہتے ہیں، تاہم بیری کے پتے استعمال کرلینے بہتر ہیں۔ (۳) آپ کا اپنا ازار (تہ بند) پہنانے کے لیے دینا بطور تبرک تھا۔ رسول اللہ صلی اللہ علیہ وسلم اور آپ سے متعلق اشیاء سے تبرک تو متفقہ مسئلہ ہے، البتہ دوسرے صالحین سے تبرک کے ثبوت کی کوئی دلیل نہیں۔ صحابہ نے ایسا نہیں کیا۔ (۴) میت کو طاق عدد میں غسل دینا چاہیے۔"}],[1882,"ام قیس رضی اللہ عنہا کہتی ہیں کہ میرا بیٹا مر گیا، تو میں اس پر رونے لگی اور اس شخص سے جو اسے غسل دے رہا تھا کہا: میرے بیٹے کو ٹھنڈے پانی سے غسل نہ دو کہ اس (مرے کو مزید) مارو، عکاشہ بن محصن رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گئے، اور آپ کو ان کی یہ بات بتائی تو آپ مسکرا پڑے، پھر فرمایا: \"کیا کہا اس نے؟ اس کی عمردراز ہو\"، (راوی کہتے ہیں) تو ہم نہیں جانتے کہ کسی عورت کو اتنی عمر ملی ہو جتنی انہیں ملی ۱؎۔\n§وضاحت\n۱؎: یہ رسول اللہ صلی اللہ علیہ وسلم کی دعا «طال عمرہا» کی برکت تھی۔","الألباني: ضعيف الإسناد",{"u2":"حضرت ام قیس رضی اللہ عنہا فرماتی ہیں کہ میرا بیٹا فوت ہوگیا۔ مجھے اس پر سخت صدمہ ہوا۔ میں نے غسل دینے والے سے کہا: میرے بیٹے کو ٹھنڈے پانی سے غسل نہ دینا کہ تو اسے مار دے۔ (میرا بھائی) حضرت عکاشہ بن محصن رضی اللہ عنہ رسول اللہ صلی اللہ علیہ وسلم کے پاس گیا اور میری یہ بات آپ کو بتائی، آپ مسکرائے اور فرمایا: ’’کیا کہا اس نے؟ اس کی عمر لمبی ہو۔‘‘ ہم کوئی اور عورت ایسی نہیں جانتے جسے اس جیسی عمر دی گئی ہو۔","f2":"’’کہ تو اسے مار دے‘‘ شدت محبت اور پھر شدت غم میں ایسی باتیں عموماً ہو جاتی ہیں۔ تعجب نہیں ہونا چاہیے لیکن یہ روایت ضعیف ہے۔"}],[1883,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ ان عورتوں نے نبی اکرم صلی اللہ علیہ وسلم کی بیٹی کے سر کی تین چوٹیاں بنائیں، میں نے پوچھا: اسے کھول کر انہوں نے تین چوٹیاں کر دیں، تو انہوں نے کہا: جی ہاں۔","الألباني: صحيح",{"u2":"حضرت حفصہ بنت سیرین بیان کرتی ہیں کہ ہمیں حضرت ام عطیہ رضی اللہ عنہا (آپ کے دور کی غاسلہ) نے بیان فرمایا: غسل دینے والی عورتوں نے نبی صلی اللہ علیہ وسلم کی بیٹی کے سر کی تین مینڈھیاں بنائی تھیں۔ میں نے پوچھا کہ بالوں کو کھول کر پھر تین مینڈھیاں بنائی تھیں؟ انھوں نے کہا: ہاں۔","f2":"احناف مینڈھیاں بنانے کے بجائے بالوں کے دو حصے کرنے کے قائل ہیں، پھر دونوں سینے پر دائیں بائیں رکھ دیے جائیں گمر احادیث میں تین منڈھیوں کا ذکر ہے۔"}],[1884,"ام عطیہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیٹی کے غسل کے سلسلہ میں فرمایا: \"ان کے داہنے اعضاء، اور وضو کے مقامات سے نہلانا شروع کرو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی بیٹی کے غسل کے موقع پر فرمایا: ’’اس کے داہنے اور وضو والے اعضاء سے غسل شروع کرنا۔‘‘"}],[1885,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی ایک بیٹی انتقال کر گئیں، تو آپ نے ہمیں بلا بھیجا اور فرمایا: \"اسے پانی اور بیر کے پتوں سے غسل دینا، اور طاق بار یعنی تین بار، یا پانچ بار غسل دینا، اگر ضرورت سمجھو تو سات بار دینا، اور آخری بار تھوڑا کافور ملا لینا (اور) جب تم فارغ ہو چکو تو مجھے خبر کرنا\"، تو جب ہم(نہلا کر) فارغ ہوئے تو ہم نے آپ کو خبر کیا، آپ صلی اللہ علیہ وسلم نے اپنا تہبند ہماری طرف پھینکا، اور فرمایا: \"اسے (ان کے جسم پہ) لپیٹ دو\"، (پھر) ہم نے ان کی تین چوٹیاں کیں، اور انہیں ان کے پیچھے ڈال دیا۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم کی ایک بیٹی فوت ہوگئیں۔ آپ نے ہمیں (غسل دینے کے لیے) بلا بھیجا، پھر فرمایا: ’’اسے پانی اور بیری کے پتوں سے غسل دینا اور اسے تین مرتبہ یا اگر ضرورت محسوس کرو تو پانچ مرتبہ یا سات مرتبہ طاق دفعہ غسل دینا اور آخری دفعہ کچھ کافور بھی ڈال لینا، پھر جب تم فارغ ہو جاؤ تو مجھے اطلاع کرنا۔‘‘ ہم جب فارغ ہوئے تو ہم نے آپ کو اطلاع کی۔ آپ نے ہماری طرف اپنا تہ بند پھینکا اور فرمایا: ’’(کفن سے پہلے) اس کو اس میں لپیٹ دینا۔‘‘ ہم نے ان کے بالوں کی تین منڈھیاں کنگھی سے بنائیں اور ان کو ان کے پیچھے ڈال دیا۔","f2":"’’پیچھے ڈال دیا‘‘ مگر احناف سینے پر ڈالنے کے قائل ہیں۔"}],[1886,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے اور ہم آپ کی بیٹی کو نہلا رہے تھے، آپ نے فرمایا: \"انہیں پانی اور بیر(کے پتوں) سے تین یا پانچ بار غسل دو، یا اگر مناسب سمجھو اس سے بھی زیادہ، اور آخری بار کافور یا کافور کی کچھ (مقدار) ملا لینا، اور جب تم فارغ ہو جاؤ تو مجھے خبر کرو\"۔ چنانچہ جب ہم فارغ ہوئے تو ہم نے آپ کو خبر کی تو آپ نے اپنا تہبند ہماری طرف پھینکا، اور فرمایا: \"اسے ان کے جسم سے لپیٹ دو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہ سے مروی ہے کہ جب ہم آپ کی بیٹی کو غسل دے رہی تھیں تو رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے اور فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا اس سے زائد مرتبہ، اگر ضرورت محسوس کرو، تو پانی اور بیری کے پتوں سے غسل دو اور آخری مرتبہ تھوڑا سا کافور بھی شامل کر دو، پھر جب تم فارغ ہو تو مجھے اطلاع کردینا۔‘‘ چنانچہ جب ہم نے فارغ ہوکر آپ کو اطلاع دی تو آپ نے اتنا تہ بند ہماری طرف پھینکا اور فرمایا: ’’اس کو اس میں لپیٹ کر پھر کفن دینا۔‘‘"}],[1887,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی ایک بیٹی کی وفات ہو گئی، تو آپ نے ہمیں بلوایا (اور) فرمایا: \"اسے پانی اور بیر (کے پتوں) سے تین یا پانچ بار غسل دو، یا اس سے زیادہ اگر مناسب سمجھو، اور آخری بار کچھ کافور یا کافور کی کچھ (مقدار) ملا لینا، اور جب فارغ ہو جاؤ تو مجھے خبر کرو\"۔ تو جب ہم فارغ ہوئے تو ہم نے آپ کو خبر کی، آپ نے ہماری طرف اپنا تہبند پھینکا اور فرمایا: \"اسے (اس کے جسم سے) لپیٹ دو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم کی ایک بیٹی فوت ہوگئیں۔ آپ نے ہمیں بلا بھیجا اور فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا اس سے زائد دفعہ، اگر ضرورت محسوس کرو، پانی اور بیری سے غسل دینا۔ اور آخر دفعہ کافور ڈال دینا یا تھوڑا سا کافور (پانی میں) ملا لینا، پھر جب تم فارغ ہو تو مجھے اطلاع کرنا۔‘‘ جب ہم فارغ ہوئیں تو ہم نے آپ کو اطلاع کی۔ آپ نے ہماری طرف اپنا تہ بند پھینکا اور فرمایا: ’’(کفن دینے سے پہلے) اس میں اس کو لپیٹ دینا۔‘‘"}],[1888,"اس سند سے بھی ام عطیہ رضی اللہ عنہا سے اسی جیسی حدیث مروی ہے، مگر (اس میں یہ الفاظ ہیں) آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں تین بار یا پانچ بار یا سات بار غسل دو، یا اس سے زیادہ اگر اس کی ضرورت سمجھو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا سے اس جیسی روایت آتی ہے مگر اس میں یہ الفاظ ہیں کہ آپ نے فرمایا: ’’تین مرتبہ یا پانچ مرتبہ یا سات مرتبہ یا اس سے زیادہ مرتبہ اگر تم ضرورت محسوس کرو تو غسل دو۔‘‘"}],[1889,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک بیٹی کی وفات ہو گئی، تو آپ نے مجھے انہیں نہلانے کا حکم دیا اور فرمایا: \"تین بار، یا پانچ بار، یا سات بار غسل دو، یا اس سے زیادہ اگر ضرورت سمجھو\"، تو میں نے کہا: طاق بار؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہاں، اور آخری مرتبہ کچھ کافور یا کافور کی کچھ مقدار ملا لو، (اور) جب فارغ ہو جاؤ تو مجھے باخبر کرنا\"، چنانچہ جب ہم فارغ ہوئے، ہم نے آپ کو خبر کی تو آپ نے ہمیں اپنا تہبند دیا، اور فرمایا: \"اسے (اس کے جسم سے) لپیٹ دو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کی ایک بیٹی فوت ہوگئیں تو آپ نے ہمیں انھیں غسل دینے کا حکم دیا اور فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا سات مرتبہ یا اس سے بھی زائد دفعہ، اگر ضرورت محسوس کرو تو غسل دینا۔‘‘ میں نے کہا: جی طاق؟ آپ نے فرمایا: ’’ہاں۔ اور آخری دفعہ کافور ڈال لینا۔ یا کچھ کافور (پانی میں) ملا لینا، پھر جب فارغ ہونا تو مجھے اطلاع کرنا۔‘‘ جب ہم (غسل سے) قارغ ہوگئیں تو ہم نے آپ کو اطلاع کی۔ آپ نے اپنا تہ بند ہمیں دیا اور فرمایا: ’’(سب سے پہلے) اسے اس میں لپیٹو۔‘‘"}],[1890,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، ہم آپ کی بیٹی کو غسل دے رہے تھے، آپ نے فرمایا: \"انہیں پانی اور بیر (کے پتوں) سے تین بار، یا پانچ بار، غسل دو\"، یا اس سے زیادہ، اور آخری بار کچھ کافور یا کافور کی مقدار ملا لو (اور) جب تم فارغ ہو جاؤ تو مجھے آگاہ کرو\"، تو جب ہم فارغ ہوئے تو آپ کو خبر کی، آپ نے ہماری طرف اپنا تہبند پھینکا اور فرمایا: \"اسے (اس کے جسم سے) لپیٹ دو\"، راوی کہتے ہیں یا حفصہ بنت سیرین کہتی ہیں: اسے تین، پانچ، یا سات بار غسل دو، راوی کہتے ہیں: ام عطیہ رضی اللہ عنہا کہتی ہیں: ہم نے ان کی تین چوٹیاں کیں۔","الألباني: صحيح"],[1891,"اس سند سے بھی ام عطیہ رضی اللہ عنہا کہتی ہیں کہ ہم نے ان کے سر کی تین چوٹیاں کیں۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا فرماتی ہیں کہ ہم نے ان کے سر کے بالوں کی تین مینڈھیاں بنا دیں۔"}],[1892,"اس سند سے بھی ام عطیہ رضی اللہ عنہا سے مروی ہے کہ ہم نے ان کے سر کی تین چوٹیاں کیں۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا سے روایت ہے کہ ہم نے ان کے سر (کے بالوں) کی تین منڈھیاں بنا دیں۔","f2":"ایک ہی باب کے تحت اور ایک ہی حدیث کا تکرار بعض اسنادی باریکیاں ظاہر کرنے کے لیے ہے جیسا کہ کئی دفعہ پیچھے گزرا۔ ان باریکیوں کو سمجھنے کے لیے اسانید کا بغور مطالعہ ضروری ہے۔"}],[1893,"محمد بن سیرین کہتے ہیں ام عطیہ رضی اللہ عنہا ایک انصاری عورت تھیں، وہ (بصرہ) آئیں، اپنے بیٹے سے جلد ملنا چاہ رہی تھیں لیکن وہ اسے نہیں پا سکیں، انہوں نے ہم سے حدیث بیان کی، کہ رسول اللہ صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے، ہم آپ کی بیٹی کو غسل دے رہے تھے، تو آپ صلی اللہ علیہ وسلم نے فرمایا:\"انہیں پانی اور بیر (کی پتیوں) سے تین بار، یا پانچ بار غسل دو، یا اس سے زیادہ بار اگر ضرورت سمجھو، اور آخر میں کافور یا کافور کی کچھ مقدار ملا لینا (اور) جب فارغ ہو جاؤ تو مجھے بتاؤ\"، تو جب ہم فارغ ہوئے تو آپ نے ہماری طرف اپنا تہبند پھینکا اور فرمایا: \"اسے ان کے بدن پر لپیٹ دو\"، اور اس سے زیادہ نہیں فرمایا۔ (ایوب نے)کہا: میں نہیں جانتا کہ یہ آپ کی کون سی بیٹی تھی ں، راوی کہتے ہیں: میں نے پوچھا \"اشعار\" سے کیا مراد ہے؟ کیا ازار (تہبند) پہنانا مقصود ہے؟ ایوب نے کہا: میں یہی سمجھتا ہوں کہ اس سے مراد یہ ہے کہ اسے ان کے جسم پر لپیٹ دو۔","الألباني: صحيح",{"u2":"حضرت ایوب بن ابی تمیمہ سے روایت ہے ہے کہ میں نے حضرت محمد بن سیرین کو کہتے ہوئے سنا کہ حضرت ام عطیہ رضی اللہ عنہا جو کہ انصار میں سے تھیں، اپنے ایک بیٹے کی خبر لینے کے لیے آئی تھیں مگر اسے (زندہ) نہ پایا۔ انھوں نے بیان فرمایا کہ نبی صلی اللہ علیہ وسلم ہمارے پاس تشریف لائے جبکہ ہم آپ کی بیٹی کو غسل دے رہی تھیں۔ آپ نے فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا اس سے زائد مرتبہ، اگر ضرورت سمجھو تو، پانی اور بیری کے پتوں سے غسل دو اور آخری مرتبہ کافور بھی ڈال دو یا تھوڑا سا کافور شامل کر دو۔ اور جب غسل سے فارغ ہو تو مجھے اطلاع کرنا۔‘‘ جب ہم فارغ ہوئیں (اور ہم نے آپ کو اطلاع کی) تو آپ نے ہماری طرف اپنا تہ بند پھینکا اور فرمایا: ’’اسے اس میں لپیٹ دو۔‘‘ اس سے زائد کچھ نہ فرمایا۔ (راویٔ حدیث) ایوب نے کہا: میں نہیں جانتا کہ یہ آپ کی کون سی بیٹی تھیں؟ (راویٔ حدیث) ابن جریج کہتے کہ میں نے (ایوب بن ابی تیمیہ سے) پوچھا: آپ کے فرمان [أشعرنھا إیاہ] کا مطلب کیا ہے؟ کیا اسے اس کا ازار بنایا جائے گا؟ انہوں نے فرمایا: میرا خیال ہے آپ کا مطلب یہ تھا کہ اسے اس میں لپیٹ دو۔","f2":"عورت کے کفن کے لیے بھی تین کپڑے ہی کافی ہیں۔ اس میں مرد اور عورت کی ترفیق کی کوئی صحیح حدیث نہیں۔ مزید دیکھیے: (کتاب الجنائز، للألباني، ص:۸۵)"}],[1894,"ام عطیہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کی بیٹیوں میں سے ایک بیٹی کی موت ہو گئی تو آپ نے فرمایا: \"انہیں تین یا پانچ بار غسل دو، یا اس سے زیادہ اگر ضرورت سمجھو، اور انہیں بیر (کے پتوں) اور پانی سے غسل دو، اور کچھ کافور ملا لو، اور جب فارغ ہو جاؤ تو مجھے خبر کرو\"، وہ کہتی ہیں: میں نے آپ کو خبر کیا، تو آپ نے ہماری طرف اپنی لنگی پھینکی اور فرمایا: \"اسے (ان کے جسم سے) لپیٹ دو\"۔","الألباني: صحيح",{"u2":"حضرت ام عطیہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم کی ایک بیٹی فوت ہوگئیں، آپ نے فرمایا: ’’اسے تین مرتبہ یا پانچ مرتبہ یا اس سے زائد مرتبہ، اگر ضرورت سمجھو تو، غسل دو۔ اور اسے پانی اور بیری (کے پتوں) سے غسل دو اور آخری مرتبہ کافور ڈال دو یا کچھ کافور ڈالو۔ جب تم فارغ ہو تو مجھے اطلاع کرنا۔‘‘ ہم نے آپ کو اطلاع کی تو آپ نے اپنا تہ بند ہماری طرف پھینکا اور فرمایا: ’’اس کے بدن پر اسے لپیٹ دو۔‘‘","f2":"’’پھینکا‘‘ گویا پکڑایا نہیں کیونکہ آپ کا ہاتھ ساری زندگی غیر محرم عورت کے ہاتھ کو نہیں لگا۔ یہ انتہا درجے کی احتیاط ہے جو آپ نے اپنی امت کو سمجھانے کے لیے فرمائی۔ (اس حدیث کے باقی مباحث کے لیے دیکھیے، حدیث: ۱۸۸۲)"}],[1895,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ دیا تو آپ نے اپنے صحابہ میں سے ایک شخص کا ذکر کیا جو مر گیا تھا، اور اسے رات ہی میں دفنا دیا گیا تھا، اور ایک گھٹیا کفن میں اس کی تکفین کی گئی تھی، رسول اللہ صلی اللہ علیہ وسلم نے سختی سے منع فرما دیا کہ کوئی آدمی رات میں دفنایا جائے سوائے اس کے کہ کوئی مجبوری ہو، نیز رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی اپنے بھائی (کے کفن دفن کا) ولی ہو تو اسے چاہیئے کہ اسے اچھا کفن دے\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ ارشاد فرمایا تو آپ نے اپنے ایک صحابی کا ذکر فرمایا جو فوت ہوگیا تھا اور اسے راتوں رات دفن کر دیا گیا تھا اور ناقص کفن پہنایا گیا تھا، چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے کسی میت کو رات کے وقت دفن کرنے سے منع فرما دیا مگر یہ کہ انتہائی مجبو ری و لاچاری ہو، نیز رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کسی پر اپنے کسی بھائی (رشتے دار) کے کفن دفن کی ذمہ داری آ پڑے تو وہ اس کے لیے اچھا کفن تیار کرے۔‘‘","f2":"(۱) کفن اچھا ہونے سے مراد یہ ہے کہ وہ نیا کپڑا ہو، مستعمل نہ ہو، سفید ہو، رنگ دار نہ ہو (تاکہ پرانے نئے کا اندازہ ہوسکے)، صاف ستھرا ہو، میلا کچیلا نہ ہو۔ درمیانی قیمت کا ہو جو دیکھنے میں نامناسب معلوم نہ ہو اور عوام الناس اسے استعمال کرتے ہوں۔ سادہ ہو، منقش نہ ہو۔ یہ مطلب نہیں کہ قیمتی اور مہنگا ہو کیونکہ بعض روایات میں مہنگے کفن سے صراحتاً روکا گیا ہے۔ (۲) مذکورہ حدیث سے اور اس موضوع کی دیگر تمام روایات جمع کرنے کے بعد معلوم ہوتا ہے کہ رات کے وقت مردوں کو دفن کرنا جائز نہیں الا یہ کہ کوئی مجبوری اور اشد ضرورت پیش آ جائے۔ رات کے وقت تدفین کی ممانعت ممکن ہے اس گمان کی وجہ سے ہو کہ نماز جنازہ میں لوگ کم تعداد میں شریک ہں گے، نیز کفن دفن میں کوتاہی ہوگی۔ لیکن اگر نماز جنازہ پڑھ لی گئی ہو تو عذر کے پیش نظر رات کو بھی دفن کرنا پڑے تو جائز ہے جیسا کہ حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے رات کے وقت میت کو قبر میں دفن کیا تھا۔ (جامع الترمذي، الجنائز، حدیث: ۱۰۵۷) نیز امام بخاری رحمہ اللہ نے تعلیقات بیان کیا ہے کہ حضرت ابوبکر رضی اللہ عنہ کو رات کے وقت دفن کیا گیا۔ (صحیح البخاري، الجنائز، قبل الحدیث: ۱۳۴۰) مسند احمد میں حضر عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو رات کے وقت دفن کیا گیا۔ (مسند أحمد: ۱۱۰،۶۲/۶) مصنف ابن ابی شیبہ میں حضرت فاطمہ رضی اللہ عنہا کی بابت مروی ہے کہ ان کو رات کے وقت دفن کیا گیا۔ (المصنف لابن أبي شیبۃ: ۳۱/۳) مذکورہ روایات اس بات کا واضح ثبوت ہیں کہ مجبوری اور عذر کے پیش نظر رات کے وقت دفن کرنا جائز ہے۔ واللہ أعلم۔"}],[1896,"سمرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم کپڑوں میں سے سفید کپڑے پہنا کرو کیونکہ وہ پاکیزہ اور عمدہ ہوتا ہے، نیز اپنے مردوں کو(بھی) اسی میں کفنایا کرو\"۔","الألباني: صحيح",{"u2":"حضرت سمرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’سفید کپڑے پہنا کرو کیونکہ یہ زیادہ صاف ستھرے اور عمدہ ہوتے ہیں اور اپنے فوت شدگان کو بھی انھی میں کفن دیا کرو۔‘‘","f2":"(۱) سفید کپڑے میں معمولی سا میل کچیل اور گندگی بھی ظاہر ہوتی ہے، لہٰذا اسے جلدی صاف کیا جاتا ہے اور وہ صاف ستھرا رہتا ہے، رنگ دار کپڑوں میں میل کچیل محسوس نہیں ہوتا، وہ دیر تک دھوئے نہیں جاتے، اس لیے بیماریوں کا سبب بن سکتے ہیں۔ ویسے بھی سفید کپڑے کی ایک شان ہوتی ہے۔ (۲) مجبوری نہ ہو تو کفن سفید ہی ہونا چاہیے۔ (۳) کفن پہنانا واجب ہے۔"}],[1897,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کو تین سفید یمنی کپڑوں میں کفنایا گیا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو (علاقۂ یمن کی) سحول بستی کے بنے ہوئے تین سفید کپڑوں میں کفن دیا گیا۔"}],[1898,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم تین سفید یمنی کپڑوں میں کفنائے گئے جن میں نہ تو قمیص تھی اور نہ عمامہ (پگڑی)۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو سحول بستی کے بنے ہوئے تین سفید کپڑوں میں کفن دیا گیا جن میں کوئی قمیص یا پگڑی نہ تھی۔"}],[1899,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو تین سفید یمنی سوتی کپڑوں میں کفنایا گیا جس میں نہ تو قمیص تھی، اور نہ عمامہ (پگڑی)، ام المؤمنین عائشہ رضی اللہ عنہا سے دو کپڑوں اور ایک یمنی چادر کے متعلق لوگوں کی گفتگو کا ذکر کیا گیا، تو انہوں نے کہا: چادر لائی گئی تھی لیکن لوگوں نے اسے لوٹا دیا، اور آپ کو اس میں نہیں کفنایا تھا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کو یمن کے بنے ہوئے تین سفید سوتی کپڑوں میں کفنایا گیا، ان میں کوئی قمیص یا پگڑی نہ تھی۔ حضرت عائشہ سے ذکر کیا گیا کہ بعض لوگ کہتے ہیں کہ دو کپڑے تھے اور تیسری دھاری دار چادر تھی۔ انھوں نے فرمایا: چادر (دھاری دار) لائی تو گئی تھی مگر غسل اور کفن دینے والوں نے واپس کر دی تھی، اس میں آپ کو کفن نہیں دیا۔","f2":"(۱) کفن کے لیے تین کپڑے مسنون ہیں، دو میں بھی گزارا ہوسکتا ہے، نہ ملیں تو مجبوری میں ایک بھی کافی ہے، جیسے جنگ احد کے بعض شہداء کے لیے صرف ایک چادر ہی ملی، نبی صلی اللہ علیہ وسلم نے اسی ایک چادر ہی میں دفن کر دیے۔ (۲) ’’قمیص اور پگڑی‘‘ کفن میں قمیص اور پگڑی نہیں ہونی چاہیے جیسا کہ اس حدیث میں صراحت ہے، جمہور اہل علم اسی کے قائل ہیں۔ احناف قمیص اور اہم شخصیت کے لیے پگڑی جائز سمجھتے ہیں۔ اس حدیث کے معنی کرتے ہیں کہ قمیص اور پگڑی ان تین کپڑوں میں شامل نہ تھے، ان کے علاوہ تھے، مگر یہ معنی ظاہر کے خلاف ہیں، البتہ بعض ضعیف احادیث میں پگڑی کا ذکر ہے لیکن ترجیح صحیح احادیث ہی کو ہوگی۔"}],[1900,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ جب عبداللہ بن ابی (منافق) مر گیا، تو اس کے بیٹے (عبداللہ رضی اللہ عنہ) نبی اکرم صلی اللہ علیہ وسلم کے پاس آئے،(اور) عرض کیا: (اللہ کے رسول!) آپ مجھے اپنی قمیص دے دیجئیے تاکہ میں اس میں انہیں کفنا دوں، اور آپ ان پر نماز (جنازہ) پڑھ دیجئیے، اور ان کے لیے مغفرت کی دعا بھی کر دیجئیے، تو آپ صلی اللہ علیہ وسلم نے اپنی قمیص انہیں دے دی، پھر فرمایا: \"جب تم فارغ ہو لو تو مجھے خبر کرو میں ان کی نماز (جنازہ) پڑھوں گا\" (اور جب نماز کے لیے کھڑے ہوئے) تو عمر رضی اللہ عنہ نے آپ کو کھینچا، اور کہا: اللہ تعالی نے آپ کو منافقین پر نماز (جنازہ) پڑھنے سے منع فرمایا ہے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"میں دو اختیارات کے درمیان ہوں (اللہ تعالی نے) فرمایا: «استغفر لهم أو لا تستغفر لهم» \"تم ان کے لیے مغفرت چاہو یا نہ چاہو دونوں برابر ہے\" (التوبہ: ۸۰) چنانچہ آپ نے اس کی نماز (جنازہ) پڑھی، تو اللہ تعالی نے (یہ آیت) نازل فرمائی: «ولا تصل على أحد منهم مات أبدا ولا تقم على قبره» \"تم ان (منافقین) میں سے کسی پر کبھی بھی نماز جنازہ نہ پڑھو، اور نہ ہی ان کی قبر پر کھڑے ہو\" (التوبہ: ۸۴) تو آپ نے ان کی نماز جنازہ پڑھنا چھوڑ دیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ جب عبداللہ بن ابی (منافقین کا سردار) مر گیا تو اس کے بیٹے (عبداللہ) نبی صلی اللہ علیہ وسلم کے پاس آئے اور گزارش کی کہ مجھے اپنی قمیص مبارک عطا فرمائیں تاکہ میں اپنے باپ کو اس میں کفن دوں۔ آپ اس کا جنازہ بھی پڑھیے اور اس کے لیے بخشش کی دعا بھی کیجیے۔ آپ نے انھیں قمیص دے دی اور فرمایا: ’’جب تم غسل اور کفن سے فارغ ہو تو مجھے اطلاع کرنا، میں اس کا جنازہ پڑھوں گا۔‘‘ (جب آپ جنازے پر پہنچے تو) حضرت عمر رضی اللہ عنہ نے آپ کو اپنی طرف متوجہ کیا اور گزارش کی کہ کیا اللہ تعالیٰ نے آپ کو منافقین کا جنازہ پڑھنے سے روکا نہیں؟ آپ نے فرمایا: ’’(نہیں) مجھے دو چیزوں میں اختیار دیا گیا ہے کہ ان (منافقین) کے لیے بخشش طلب کرو یا نہ کرو، اللہ انھیں معاف نہیں فرمائے گا۔‘‘ پھر آپ نے جنازہ پڑھ دیا۔ بعد میں اللہ تعالیٰ نے یہ آیت اتاری: (ولا تصل علی احد ………… ولا تقم علی قبرہ) ’’ان منافقین میں سے کوئی مر جائے تو کبھی بھی اس کا جنازہ نہ پڑھیں اور نہ اس کی قبر پر کھڑے ہوں۔‘‘ پھر آپ نے منافقین کا جنازہ پڑھنا چھوڑ دیا۔","f2":"(۱) عبداللہ بن ابی منافق کے بیٹے حضرت عبداللہ رضی اللہ عنہ انتہائی مخلص مسلمان تھے۔ ان کا رسول اللہ صلی اللہ علیہ وسلم کے پاس آکر مندرجہ بالا گزارشات کرنا فطری چیز ہے۔ ہر بیٹا خصوصاً نیک بیٹا ماں باپ کی بھلائی چاہتا ہے۔ چونکہ عبداللہ بن ابی ظاہراً کلمہ گو تھا، اس لیے وہ سمجھتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کی برکت سے شاید اس کی مغفرت ہو جائے، بالخصوص جبکہ ابھی منافقین کی نماز جنازہ پڑھنے یا نہ پڑھنے کی بابت کوئی واضح حکم بھی نہیں آیا تھا۔ اسی طرح نبی صلی اللہ علیہ وسلم کا ان کے مطالبات کو تسلیم فرما لینا دراصل اس مسلمان بیٹے کی دلداری کے علاوہ آپ کی رحمۃ للعالمینی کا بھی مظہر تھا۔ اس واقعے کے بعد اللہ تعالیٰ نے ممانعت کا حکم نازل فرما دیا۔ (۲) ’’قمیص دے دی‘‘ کہا گیا ے کہ یہ قمیص دراصل اس قمیص کے بدلے کے طور پر دی تھی جو قمیص عبداللہ بن ابی نے نبی صلی اللہ علیہ وسلم کے چچا حضرت عباس رضی اللہ عنہ کو بدر کی جنگ کے قیدی کی حیثیت میں دی تھی۔ (۳) ’’روکا نہیں؟‘‘ حضرت عمر رضی اللہ عنہ نے سمجھا کہ جب اس کی مغفرت ممکن نہیں تو مسلب یہی ہے کہ جنازہ نہ پڑھو مگر رسول اللہ صلی اللہ علیہ وسلم نے اللہ تعالیٰ کے انداز بیان میں امید کی کرن دیکھی کیونکہ صراحتاً حکم ممانعت نہ تھا، ہاں مشرک کے لیے استغفار سے صراحتاً روکا گیا تھا مگر عبداللہ بن ابی منافق تھا، مشرک نہ تھا، منافق کا حکم بعد میں اترا۔ (۴) امام نسائی رحمہ اللہ نے اس حدیث سے استدلال فرمایا ہے کہ قمیص بھی کفن میں شامل ہوسکتی ہے۔ لیکن دیگر دلائل و احادیث کی روشنی میں یہ استدلال محل نظر ہے کیونکہ ان میں خود آپ علیہ الصلوٰۃ و السلام کے لیے تین کپڑوں کا انتخاب ہوا اور یقیناً جو اللہ کے رسول صلی اللہ علیہ وسلم کے لیے تجویز ہوا وہی افضل ہے۔ رہی بات جواز کی تو صورتِ حال کا جائزہ لینے سے ہی معلوم ہوتا ہے کہ یہ ایک اتفاقی واقعہ تھا جو عام جواز کی دلیل نہیں بن سکتا، وہ اس طرح کہ حضرت عبداللہ رضی اللہ عنہ نے رسول اللہ صلی اللہ علیہ وسلم سے اس قمیص کا مطالبہ کیا تھا جو آپ علیہ الصلوٰۃ والسلام کے وجودِ مسعود پر تھی اور خاص کر آپ کی جلد کے ساتھ لگی تھی، آپ اس کا انکار نہ فرما سکے بلکہ تالیف قلب اور حضرت عبداللہ رضی اللہ عنہ کی حوصلہ افزائی کی خاطر آپ نے انھیں دے دی بلکہ عبداللہ بن ابی کو خود پہنا دی جیسا کہ صحیح بخاری (حدیث: ۱۲۷۰) میں ہے۔ بلکہ معلوم ہوتا ہے کہ یہ اس قمیص کا بدلہ تھا جو آپ کے چچا عباس رضی اللہ عنہ کو عبداللہ بن ابی نے دی تھی جبکہ وہ جنگ بدر کے بعد قیدی بنے کیونکہ ان کی قمیص پھٹی ہوئی تھی اور عام پیمائش کی قمیص انھیں پوری نہیں آئی تھی تب انھیں وہ قمیص مرحمت کی گئی عبداللہ بن ابی قدآور انسان تھا۔ بہرحال اس حدیث سے آپ صلی اللہ علیہ وسلم کے خلق عظیم کا پتا چلتا ہے کہ آآ کو اس کے منافق ہونے کا یقین تھا، نبیٔ اکرم صلی اللہ علیہ وسلم، اسلام اور دیگر مسلمانوں کے لیے اس کی ایذا بھی ڈھکی چھپی نہیں تھی، اس کے باوجود آپ نے اسے قمیص پہنائی اور اس کا جنازہ پڑھا۔ (۵) منافق پر اس کے ظاہر کو مدنظر رکھتے ہوئے دنیا میں اسلام والے احکام جاری ہوں گے۔ (۶) آدمی زندہ ہو یا مردہ، اس کی حقیقت کے بارے میں اظہار کیا جا سکتا ہے، جیسے حضرت عمر رضی اللہ عنہ نے عبداللہ بن ابی کے منافق ہونے کا اظہار کیا ہے، یہ لاتسبوا الاموات (مردوں کو برا بھلا نہ کہو) میں شامل نہیں۔ (۷) آدمی صاحب علم و فضل شخصیت کو کوئی ایسا کام کرتے دیکھے جسے وہ خلاف شرع سمجھتا ہے تو وہ استفسار کرسکتا ہے۔ (۸) صاحب فضل شخص کو اچھی طرح وضاحت کرکے اس آدمی کا اشکال دور کرنا چاہیے۔"}],[1901,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم عبداللہ بن ابی کی قبر پر آئے، اور اسے اس کی قبر میں رکھا جا چکا تھا، تو آپ اس پر کھڑے ہوئے، اور اس کے نکالنے کا حکم دیا تو اسے نکالا گیا، تو آپ نے اسے اپنے دونوں گھٹنوں پر رکھا، اور اپنی قمیص پہنائی اور اس پر تھو تھو کیا، واللہ تعالی اعلم۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم عبداللہ بن ابی کی قبر پر تشریف لائے جبکہ اسے لحد میں رکھا جا چکا تھا، آپ قبر پر کھڑے ہوئے اور اسے نکالنے کا حکم دیا۔ اسے (قبر سے) نکالا گیا، پھر آپ نے اسے اپنے گھٹنوں پر رکھا اور اسے اپنی قمیص پہنائی اور اس کے منہ میں (یا اس کے جسم پر) اپنا لعابِ مبارک ڈالا۔ اللہ تعالیٰ خوب جانتا ہے (حکمت کیا تھی؟)","f2":"یہ روایت مشہور روایا ت سے متعارض معلوم ہوتی ہے جن میں قمیص پہلے دینے، جنازہ پڑھنے اور پھر قبر پر جنازے کے ساتھ آنے کا ذکر ہے، حافظ ابن حجر رحمہ اللہ نے اس کا ایک حل یہ پیش کیا ہے کہ پہلی روایت میں دینے سے مراد دینے کا وعدہ ہے، وعدے پر عطیہ کا لفظ بول دیا گیا ہے۔ دوسرا حل اور تطبیق یہ ہے کہ ممکن ہے دو مرتبہ آپ نے قمیص دی ہو، ایک پہلے اور دوسری مرتبہ جب آپ قبر پر حاضر ہوئے۔ مزید دیکھیے: (فتح الباري الجنائز، باب الکفن في القمیص الذی یکف أولا یکف، حدیث: ۱۲۷۰) واللہ أعلم۔"}],[1902,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ عباس بن عبدالمطلب رضی اللہ عنہ مدینے میں تھے، تو انصار نے ایک کپڑا تلاش کیا جو انہیں پہنائیں، تو عبداللہ بن ابی کی قمیص کے سوا کوئی قمیص نہیں ملی جو ان پر فٹ آتی، تو انہوں نے انہیں وہی پہنا دیا ۱؎۔\n§وضاحت\n۱؎: اور اسی احسان کے بدلے کے طور پر آپ نے مرنے پر عبداللہ بن ابی کو اپنی قمیص دی۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے ہیں کہ حضرت عباس رضی اللہ عنہ مدینہ میں (قید) تھے تو (ان کی قمیص پھٹی ہوئی تھی، لہٰذا) انصار نے ان کے لیے کوئی کپڑا تلاش کیا جو انھیں پہنا سکیں مگر عبداللہ بن ابی کی قمیص کے علاوہ کوئی قمیص ان پر صحیح نہ آتی تھی (کیونکہ وہ قد آور تھے اور وہ بھی قد آور تھا) آخر انھوں نے وہی ان کو پہنا دی۔","f2":"یہ روایت ذکر کرنے سے امام صاحب کا مقصود یہ ہے کہ نبی صلی اللہ علیہ وسلم کا اس کی وفات کے موقع پر قمیص عطا فرمانا دراصل اس قمیص کا بدلہ تھا جو اس نے آپ کے چچا کو پہنائی تھی کیونکہ آپ احسان کا بدلہ ضرور دیتے تھے۔"}],[1903,"خباب رضی اللہ عنہ بیان کرتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہجرت کی، ہم اللہ تعالی کی رضا چاہ رہے تھے، اللہ تعالی پر ہمارا اجر ثابت ہو گیا، پھر ہم میں سے کچھ لوگ وہ ہیں جو مر گئے (اور) اس اجر میں سے (دنیا میں) کچھ بھی نہیں چکھا، انہیں میں سے مصعب بن عمیر رضی اللہ عنہ ہیں، جو جنگ احد میں قتل کئے گئے، تو ہم نے سوائے ایک (چھوٹی) دھاری دار چادر کے کوئی ایسی چیز نہیں پائی جس میں انہیں کفناتے، جب ہم ان کا سر ڈھکتے تو پیر کھل جاتا، اور جب پیر ڈھکتے تو سر کھل جاتا، تو رسول اللہ صلی اللہ علیہ وسلم نے ہمیں حکم دیا کہ ہم ان کا سر ڈھک دیں اور ان کے پیروں پہ اذخر نامی گھاس ڈال دیں، اور ہم میں سے کچھ لوگ وہ ہیں جن کے پھل پکے اور وہ اسے چن رہے ہیں (یہ الفاظ اسماعیل کے ہیں)۔","الألباني: صحيح",{"u2":"حضرت خباب رضی اللہ عنہ فرماتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ہجرت کی تو ہم صرف اللہ تعالیٰ کی رضا مندی کے طالب تھے، لہٰذا ہمارا ثواب اللہ تعالیٰ نے اپنے ذمے لے لیا۔ ہم میں سے کچھ تو اس حالت میں فوت ہوئے کہ انھوں نے اپنے اجر و ثواب کا کچھ بھی حصہ دنیا میں وصول نہ کیا تھا۔ ایسے مخلصین میں سے ایک حضرت مصعب بن عمیر رضی اللہ عنہ تھے جو جنگ احد میں شہید ہوئے۔ ہمیں ان کو کفن دینے کے لیے صرف ایک چادر ملی، وہ بھی اتنی (چھوٹی تھی) کہ جب ہم ان کا سر ڈھانپتے تو ان کے پاؤں ننگے ہو جاتے تھے اور جب ہم ان کے پاؤں ڈھانپتے تھے تو ان کا سر ننگا ہو جاتا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا کہ ہم اس سے ان کا سر ڈھانپ دیں اور پاؤں پر گھاس ڈال دیں۔ اور ہم میں سے کچھ ایسے لوگ بھی ہیں کہ جن کے لیے ان کے ثواب کا پھل اس دنیا میں بھی پک کر تیار ہوگیا۔ وہ اس کو توڑ توڑ کر کھا رہے ہیں۔\nحدیث کے یہ الفاظ اسماعیل بن مسعود راوی کے بیان کردہ ہیں۔","f2":"(۱) ان الفاظ کا یہ مطلب نہیں کہ انھیں آخرت میں ثواب نہیں ملے گا بلکہ مقصود یہ ہے کہ ان لوگوں کو ان کی ہجرت کے کچھ نتائج دنیا میں بھی حاصل ہوگئے، آخر میں تو ثواب بہرصورت ملے گا۔ مگر مصعب رضی اللہ عنہ جیسے ساتھیوں کا درجہ بہت اونچا ہوگا۔ (۲) اس روایت میں قمیص کا ذکر نہیں ہے۔ جس سے بلاقمیص کفن کی مشروعیت پر استدلال ہے، جبکہ آغاز باب میں عبداللہ بن ابی کی روایت سے اس کے جواز کا رجحان معلوم ہوتا ہے لیکن یہ اس وقت ہے جب کوئی اور چارۂ کار نہ ہو، نیز اسے مذکورہ عنوان کے تحت ذکر کرنے کا مقصد یہ بھی ہو سکتا ہے کہ ایک کپڑے میں بھی کفن جائز ہے جبکہ صورت حال اس قسم کی ہو۔ واللہ أعلم۔"}],[1904,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"محرم کو اس کے ان ہی دونوں کپڑوں میں غسل دو جن میں وہ احرام باندھے ہوئے تھا، اور اسے پانی اور بیر (کے پتوں) سے نہلاؤ، اور اسے اس کے دونوں کپڑوں ہی میں کفناؤ، نہ اسے خوشبو لگاؤ، اور نہ ہی اس کا سر ڈھکو، کیونکہ وہ قیامت کے دن احرام باندھے ہوئے اٹھے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلمنے فرمایا: ’’محرم کو اس کے انھی دو کپڑوں میں غسل دو جن میں اس نے احرام باندھا تھا۔ اور اسے پانی اور بیری (کے پتوں) سے غسل دو۔ اس کو انھی دو کپڑوں میں کفن دو اور اسے خوشبو نہ لگائو اور نہ اس کا سر ڈھانپو کیونکہ وہ قیامت کے دن احرام کی حالت میں اٹھایا جائے گا۔","f2":"اس حدیث سے صاف معلوم ہوتا ہے کہ محرم فوت بھی ہو جائے، تب بھی اس کا احرام قائم رکھا جائے، یعنی اسے خوشبو لگائی جائے نہ اس کا سر ڈھانپا جائے، مگر احناف نے اس خاص اور صریح روایت کو چھوڑ کر ایک عام روایت: ’’جب انسان مر جائے تو اس کا عمل منقطع ہو جاتا ہے۔‘‘ (صحیح مسلم، الوصیۃ، حدیث: ۱۶۳۱) سے استدلال کرتے ہوئے کہا ہے کہ محرم کو بھی عام انسان کی طرح غسل اور کفن دیا جائے، حالانکہ صحیح مسلم کی اس روایت سے کیسے معلوم ہوتا ہے کہ غسل اور کفن کے خصوصی احکام اس پر لاگو نہیں ہوسکتے؟ جبکہ شہید کے بارے میں خود احناف مانتے ہیں کہ شہید کو غسل نہیں دیا جائے گا، اسی خون آلود حالت میں اسے دفن کیا جائے گا تو کیا اعتراض ہے اگر محرم کو احرام کی حالت میں دفن کر دیا جائے؟ کیا سب احادیث پر عمل ضروری نہیں؟ اگر شہید کا خاص حکم ہوسکتا ہے تو محرم کا کیوں نہیں؟ جبکہ حدیث صریح اور واضح ہے۔ احناف کہتے ہیں یہ حدیث اس محرم کے ساتھ خاص ہے جس کے بارے میں آپ نے یہ بیان فرمائی تھی، مگر پوچھا جا سکتا ہے کہ حضرت والا! شہید کو غسل نہ دینے والی حدیث شہدائے احد کے ساتھ خاص کیوں نہیں؟ بہرحال واضح حدیث کی موجودگی میں قیاس اور رائے کی کوئی حیثیت نہیں۔"}],[1905,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"عمدہ ترین خوشبو مشک ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین خوشبو کستوری ہے۔‘‘","f2":"کستوری کے بارے میں اشکال یہ ہوسکتا ہے کہ کستوری تو دراصل ہرن کا خون ہے جس کا استعمال جائز نہیں، مگر کوئی چیز جب قدرتی طور پر تبدیل ہو جائے اور اس میں پہلے اثرات بالکل ختم ہو جائیں تو اس کا حکم بدل جائے گا۔ کستوری بھی کسی لحاظ سے خون کے اوصاف نہیں رکھتی، لہٰذا اس کا حکم خون سے مختلف ہوگا۔ خون بھی تو خوراک سے بنتا ہے مگر اسے خوراک کا حکم حاصل نہیں۔ اسی طرح غلہ جات اور سبزیاں بھی تو مٹی اور گوبر وغیرہ ہی سے بنتی ہیں مگر ان پر اصل کا حکم نہیں لگتا۔"}],[1906,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے بہترین خوشبوؤں میں سے مشک ہے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’کستوری تمھاری بہترین خوشبو ہے۔‘‘"}],[1907,"ابوامامہ بن سہل بن حنیف رضی اللہ عنہ کہتے ہیں کہ ایک مسکین عورت بیمار ہو گئی، رسول اللہ صلی اللہ علیہ وسلم کو اس کی بیماری کی خبر دی گئی (رسول اللہ صلی اللہ علیہ وسلم مسکینوں اور غریبوں کی بیمار پرسی کرتے اور ان کے بارے میں پوچھتے رہتے تھے) تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جب یہ مر جائے تو مجھے خبر کرنا\"، رات میں اس کا جنازہ لے جایا گیا (تو) لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو بیدار کرنا مناسب نہ جانا، جب رسول اللہ صلی اللہ علیہ وسلم نے صبح کی تو (رات میں) جو کچھ ہوا تھا آپ کو اس کی خبر دی گئی، آپ صلی اللہ علیہ وسلم نے فرمایا: \"کیا میں نے تمہیں حکم نہیں دیا تھا کہ مجھے اس کی خبر کرنا؟\" تو انہوں نے کہا: اللہ کے رسول! ہم نے آپ کو رات میں جگانا نا مناسب سمجھا، رسول اللہ صلی اللہ علیہ وسلم (اپنے صحابہ کے ساتھ) نکلے یہاں تک کہ اس کی قبر پہ لوگوں کی صف بندی ۱؎ کی اور چار تکبیریں کہیں۔\n§وضاحت\n۱؎: اس میں قبر پر دوبارہ نماز پڑھنے کے جواز کی دلیل ہے، جو لوگ اس کے قائل نہیں ہیں وہ اسے اسی عورت کے ساتھ خاص مانتے ہیں لیکن یہ دعوی محتاج دلیل ہے۔","الألباني: صحيح",{"u2":"حضرت ابوامامہ بن سہل بن حنیف رضی اللہ عنہ سے منقول ہے کہ ایک مسکین عورت بیمار ہوگئی تو رسول اللہ صلی اللہ علیہ وسلم کو اس کی بیماری کی خبر دی گئی۔ رسول اللہ صلی اللہ علیہ وسلم مسکین لوگوں کی بیمار پرسی اور خبر گیری فرمایا کرتے تھے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب یہ فوت ہو جائے تو مجھے اطلاع کرنا۔‘‘ اس کا جنازہ رات کو لے جایا گیا اور صحابہ نے پسند نہ کیا کہ رسول اللہ صلی اللہ علیہ وسلم کو جگائیں۔ جب صبح ہوئی تو رسول اللہ صلی اللہ علیہ وسلم کو اس واقعے کی خبر دی گئی۔ آپ نے فرمایا: ’’میں نے تمھیں کہا نہیں تھا کہ مجھے اس کی اطلاع دینا؟‘‘ صحابہ نے کہا: اے اللہ کے رسول! ہم نے رات کے وقت آپ کو جگانا مناسب نہ سمجھا، پھر رسول اللہ صلی اللہ علیہ وسلم قبرستان کی طرف چلے اور اس کی قبر پر لوگوں کی صفیں بنائیں اور چار تکبیریں کہیں۔ (یعنی جنازہ پڑھا۔)","f2":"(۱) باب کا مسئلہ ثابت ہونے کے ساتھ ہی بھی ثابت ہوا کہ دوبارہ قبر پر جنازہ پڑھا جا سکتا ہے۔ احناف دوبارہ یا قبر پر جنازہ پڑھنے کے قائل نہیں ہیں الا یہ کہ میت کو بغیر جنازہ پڑھے دفن کر دیا گیا ہو۔ وہ اس حدیث کو بلادلیل رسول اللہ صلی اللہ علیہ وسلم سے خاص سمجھتے ہیں۔ (۲) رسول اللہ صلی اللہ علیہ وسلم میں غایت درجے کی تواضع تھی کہ فقراء اور مساکین کی عیادت کے لیے ان کے گھر جاتے اور بیمار پرسی کرتے ……… صلی اللہ علیہ وسلم……… (۳) مرد عورت کی تیماری داری کرسکتا ہے، اسی طرح عورت بھی۔ (۴) ایسی حکم عدولی جس میں حکم دینے والے کی بھلائی اور تعظیم و تکریم مقصود ہو، گناہ شمار نہیں ہوگی۔ (۵) نبیٔ اکرم صلی اللہ علیہ وسلم غیب نہیں جانتے تھے۔ (۶) رات کو دفن کرنا جائز ہے۔"}],[1908,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب نیک بندہ اپنی چارپائی پہ رکھا جاتا ہے، تو وہ کہتا ہے: مجھے جلدی لے چلو، مجھے جلدی لے چلو، اور جب برا آدمی اپنی چارپائی پہ رکھا جاتا ہے، تو کہتا ہے: ہائے میری تباہی! تم مجھے کہاں لے جا رہے ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب نیک شخص چارپائی پر رکھا جاتا ہے تو وہ کہتا ہے: مجھے جلدی لے چلو، مجھے جلدی لے چلو۔ اور جب برا آدمی چار پائی پر رکھاجاتا ہے تو وہ کہتا ہے: افسوس! مجھے کہاں لے جا رہے ہو؟‘‘","f2":"مرنے کے بعد میت عالم برزخ میں داخل ہو جاتی ہے اور اس پر برزخی احکام لاگو ہو جاتے ہیں جو ہماری دنیا کے احکام سےمختلف ہیں، لہٰذا میت کا یہ کہنا برزخی امر ہے جو ہماری دنیا سے متعلق نہیں، اس لیے ہمیں سنائی بھی نہیں دیتا۔ ہوسکتا ہے روح کہتی ہو۔ بہرصورت عالم برزخ ہماری عقل سے بالا ہے۔ اس پر بغیر تفصیل جانے وایمان لانا واجب ہے۔"}],[1909,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب جنازہ (چارپائی پر) رکھا جاتا ہے (اور) لوگ اسے اپنے کندھوں پہ اٹھاتے ہیں، تو اگر وہ نیکوکار ہوتا ہے تو کہتا ہے: مجھے جلدی لے چلو، مجھے جلدی لے چلو، اور اگر برا ہوتا ہے تو کہتا ہے: ہائے اس کی ہلاکت! تم اسے کہاں لے جا رہے ہو، اس کی آواز ہر چیز سنتی ہے سوائے انسان کے، اگر انسان اسے سن لے تو بیہوش ہو جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید خدری رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب میت کو چارپائی پر رکھا جاتا ہے اور لوگ اسے اپنے کندھوں پر اٹھا لیتے ہیں تو اگر وہ نیک ہو تو کہتا ہے: مجھے جلدی لے چلو، مجھے جلدی لے چلو۔ اور اگر وہ نیک نہیں تو کہتا ہے: ہائے افسوس! مجھے کہاں لے جا رہے ہو؟ اس کی آواز کو انسان کے علاوہ ہر چیز سنتی ہے اگر انسان سن لے تو بے ہوش ہو جائے۔‘‘","f2":"(۱) یہ کوئی محال بات نہیں کہ جانور اس چیز کا ادراک کر لیں جس کا انسان کو ادراک نہیں کیونکہ اللہ تعالیٰ نے جانوروں میں بڑی بڑی صلاحیتیں ودیعت کر رکھی ہیں، مثلاً: کتے کی قوت شامہ (سونگھنے والی قوت) حیرت انگیز حد تک انسان سے زیادہ ہے۔ وہ کسی انسان کے خالی کپڑے سونگھ کر اس انسان تک پہنچ جاتا ہے۔ انسان میں یہ صلاحیت مفقود ہے، مثلاً: شکاری اور کھوجی کتے۔ (۲) ’’بے ہوش ہو جائے‘‘ یعنی اس برے انسان (میت) کی خوف ناک آواز سن کر۔ (۳) یہ اللہ تعالیٰ کا فضل ہے کہ اس کی آواز زندہ لوگوں کو نہیں سناتا۔ (۴) جنازہ اٹھانا مردوں کے لیے مشروع ہے، عورتیں نہیں اٹھائیں گی۔"}],[1910,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جنازے کو تیز لے چلو کیونکہ اگر وہ نیک ہے تو تم اسے نیکی کی طرف (جلد) لے جاؤ گے، اور اگر اس کے علاوہ ہے تو وہ ایک شر ہے جسے تم (جلد) اپنی گردنوں سے اتار پھینکو گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، اور وہ اس روایت کو نبی صلی اللہ علیہ وسلم تک پہنچاتے تھے، کہ آپ نے فرمایا: ’’جنازہ جلدی لے کر چلو۔ اگر وہ نیک ہے تو تم اسے خیر کی طرف لے جا رہے ہو اور اگروہ نیک نہیں تو تم ایک شر کو اپنی گردنوں سے اتار رہے ہو۔‘‘","f2":"جنازہ جلدی لے جانے کے دو مفہوم ہوسکتے ہیں: (۱) جنازہ زیادہ دیر تک گھر میں نہ رکھو بلکہ تکفین و تجہیز میں جلدی کرو۔ (۲) جنازہ اٹھانے کے بعد تیز تیز چلو۔ بوجھ اٹھانے والا شخص فطری طور پر تیز تیز چلتا ہے، مگر اتنا تیز نہ چلے کہ میت کو جھٹکے لگیں۔"}],[1911,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جنازے کو جلدی لے چلو، کیونکہ اگر وہ نیک ہے تو تم اسے خیر کی طرف جلد لے جاؤ گے، اور اگر بد ہے تو شر کو اپنی گردنوں سے (جلد) اتار پھینکو گے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’میت کو جلدی لے جاؤ کیونکہ اگر وہ نیک ہے تو تم اسے خیر کی طرف جلدی لے جا رہے ہو اور اگر وہ نیک نہیں تو تم ایک شرکو اپنی گردنوں سے اتار رہے ہو۔‘‘","f2":"’’گردنوں سے اتار رہے ہو‘‘ پہلے معنی کی رو سے اس کا مطلب ہے کہ تم اپنی ذمے داری سے فارغ ہو رہے ہو، دوسرا معنی ظاہر ہے۔"}],[1912,"عبدالرحمٰن بن جوشن کہتے ہیں میں عبدالرحمٰن بن سمرہ رضی اللہ عنہ کے جنازے میں موجود تھا، زیاد نکلے تو وہ چارپائی کے آگے چل رہے تھے، عبدالرحمٰن رضی اللہ عنہ کے گھر والوں میں سے کچھ لوگ اور ان کے غلام چارپائی کو سامنے کر کے اپنی ایڑیوں کے بل چلنے لگے، وہ کہہ رہے تھے: آہستہ چلو، آہستہ چلو، اللہ تمہیں برکت دے، تو وہ لوگ رینگنے کے انداز میں چلنے لگے، یہاں تک کہ جب ہم مربد کے راستے میں تھے تو ابوبکرہ رضی اللہ عنہ ہمیں ایک خچر پر (سوار) ملے، جب انہوں نے انہیں (ایسا) کرتے دیکھا، تو اپنے خچر پر (سوار) ان کے پاس گئے اور کوڑے سے ان کی طرف اشارہ کیا، اور کہا: قسم! اس ذات کی جس نے ابوالقاسم صلی اللہ علیہ وسلم کو عزت بخشی، میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنے آپ کو دیکھا کہ ہم جنازے کے ساتھ تقریباً دوڑتے ہوئے چلتے، تو لوگ (یہ سن کر) خوش ہوئے۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمٰن بن جوشن فرماتے ہیں کہ میں حضرت عبدالرحمن بن سمرہ کے جنازے میں حاضر ہوا۔ زیاد (گورنر بصرہ) چارپائی کے آگے آگے چلنے لگا۔ حضرت عبدالرحمن کے گھریلو رشتے دار اور ان کے غلام (چارپائی کے آگے) چارپائی کی طرف منہ کرکے الٹے پاؤں چلنے لگے۔ اور وہ (جنازہ اٹھانے والوں کو) کہتے تھے: آہستہ آہستہ چلو۔ اللہ تعالیٰ تمھاری نیکی میں برکت فرمائے۔ تو اس طرح وہ گویا رینگ رینگ کر (یعنی بہت آہستہ) چل رہے تھے حتی کہ جب ہم راستے میں مربد مقام پر پہنچے تو حضرت ابوبکرہ رضی اللہ عنہ خچر پر سوار پیچھے سے ہمیں آملے۔ جب انھوں نے ان لوگوں کو ایسا کرتے دیکھا تو ان کی طرف خچر کو دوڑایا اور ان کی طرف کوڑا لہرایا اور فرمایا: راستہ چھوڑ دو۔ (یعنی میت کے آگے سے ہٹ جاؤ) مجھے قسم ہے اس ذات کی جس نے ابو القاسم صلی اللہ علیہ وسلم کے چہرۂ انور کو عزت دی ہے! مجھے اچھی طرح یاد ہے کہ ہم تو رسول اللہ صلی اللہ علیہ وسلم کی موجودگی میں میت کو اٹھا کر تیز تیز چلتے تھے، پھر (یہ بات سن کر) سب لوگ مطمئن ہوگئے۔","f2":"’’مطمئن ہوگئے‘‘ یعنی اس وضاحت کے بعد سب لوگ اس بات پر مطمئن ہوگئے کہ جنازے کو اٹھا کر تیز تیز چلنا چاہیے۔"}],[1913,"ابوبکرہ رضی اللہ عنہ کہتے ہیں کہ میں نے (صحابہ کرام) کو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ اپنے آپ کو دیکھا ہم جنازے کے ساتھ تقریباً دوڑتے ہوئے چلتے۔ یہ الفاظ ہشیم کی روایت کے ہیں۔","الألباني: صحيح",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ فرماتے ہیں کہ اللہ کی قسم! مجھے خوب یاد ہے کہ ہم رسول اللہ صلی اللہ علیہ وسلم کی موجودگی میں میت کو لے کر تیز تیز چلتے تھے۔ حدیث کے مذکورہ الفاظ ہیثم کے ہیں (نہ کہ اسماعیل کے۔)","f2":"معلوم ہوا میت کو اٹھا کر تیز چلنا چاہیے جس طرح بوجھ اٹھانے والا طبعاً تیز چلتا ہے، یہاں بھاگنا مقصود نہیں۔"}],[1914,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تمہارے (سامنے) سے جنازہ گزرے تو کھڑے ہو جاؤ، (اور) جو(جنازے) کے ساتھ جائے وہ نہ بیٹھے یہاں تک کہ اسے رکھ دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابو سعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب جنازہ تمھارے پاس سے گزرے تو کھڑے ہو جاؤ، پھر جو شخص جنازے کے ساتھ جائے، وہ جنازہ (زمین پر) رکھے جانے تک نہ بیٹھے۔‘‘","f2":"(۱) یہ حدیث اگلے باب کے تحت ذکر ہونی چاہیے۔ پچھلے باب سے اس کا کوئی تعلق نہیں بنتا۔ واللہ أعلم۔ (۲) ’’کھڑے ہو جاؤ‘‘ ایک اور حدیث میں اس کی وجہ بھی بیان کی گئی ہے: [إن للموت فزعا] (مسند أحمد: ۳۵۴/۳) ’’موت گھبراہٹ کا باعث ہے۔‘‘ یعنی موت کو دیکھ کر یا سن کر انسان کو گھبرا جانا چاہیے۔ حوادث سے متاثر ہونا فطری چیز ہے۔ اور موت تو سب سے بڑا حادثہ ہے۔ ایک کی موت دوسروں کو بھی ان کی موت یاد دلاتی ہے، لہٰذا جنازہ دیکھیں تو اپنا کام چھوڑ کر کھڑے ہونا چاہیے۔ بعض روایات میں یہ وجہ بھی ذکر ہے کہ یہ قیام فرشتوں کے احترام کے طور پر ہے جو جنازے کے ساتھ ہوتے ہیں۔ ان دونوں صورتوں میں جنازہ عام ہوگا، مسلم کا ہو یا کافر کا۔ بعض کا خیال ہے کہ یہ کھڑے ہونا تعاون کے امکان کے لیے ہے۔ اس صورت میں یہ حکم صرف مسلم کے جنازے کے لیے ہوگا، یعنی جب تک جنازہ کندھوں پر ہے، ساتھیوں کے تعاون کی ضرورت پڑ سکتی ہے، لہٰذا جنازہ زمین پر رکھنے تک شرکاء مت بیٹھیں لیکن یہ توجیہ کمزور ہے۔ (قیام کی باقی بحث آئندہ باب میں ہے۔)"}],[1915,"عامر بن ربیعہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی جنازہ دیکھے (اور) اس کے ساتھ جا نہ رہا ہو تو وہ کھڑا رہے یہاں تک کہ (جنازہ) اس سے آگے نکل جائے یا آگے نکلنے سے پہلے رکھ دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت عامر بن ربیعہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی جنازہ (آتا ہوا) دیکھے اور اس نے جنازے کے ساتھ نہ جانا ہو تو (کم از کم) کھڑا ہو جائے حتی کہ جنازہ اس سے آگے گزر جائے یا گزرنے سے پہلے زمین پر رکھ دیا جائے۔‘‘"}],[1916,"عامر بن ربیعہ عدوی رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم جنازہ دیکھو تو کھڑے ہو جاؤ یہاں تک کہ وہ تم سے آگے نکل جائے، یا رکھ دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت عامر بن ربیعہ عدوی رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم جنازہ (آتا) دیکھو تو کھڑے ہو جاؤ حتی کہ جنازہ تم سے آگے گزر جائے یا (زمین پر) رکھ دیا جائے۔‘‘"}],[1917,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم جنازہ دیکھو تو کھڑے ہو جاؤ، (اور) جو اس کے پیچھے پیچھے جا رہا ہو جب تک جنازہ رکھ نہ دیا جائے وہ نہ بیٹھے\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم جنازہ (آتا) دیکھو تو کھڑے ہو جاؤ جو شخص جنازے کے ساتھ جائے وہ نہ بیٹھے حتی کہ جنازہ (زمین پر) رکھ دیا جائے۔‘‘"}],[1918,"ابوہریرہ اور ابو سعید خدری رضی اللہ عنہما کہتے ہیں کہ ہم نے رسول اللہ صلی اللہ علیہ وسلم کو کبھی نہیں دیکھا کہ آپ جنازے کے ساتھ ہوں، (اور) بیٹھ گئے ہوں یہاں تک کہ وہ رکھ دیا جائے۔","الألباني: حسن الإسناد",{"u2":"حضرت ابوہریرہ اور ابو سعید رضی اللہ عنہما دونوں نے فرمایا: ہم نے تو کبھی نہیں دیکھا کہ رسول اللہ صلی اللہ علیہ وسلم کسی جنازے کے ساتھ تشریف فرما ہوں اور جنازہ زمین پر رکھے جانے سے پہلے بیٹھ گئے ہوں۔"}],[1919,"ابو سعید خدری رضی اللہ عنہ سے روایت ہے کہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ (لے کر) گزرے، تو آپ کھڑے ہو گئے، اور عمرو بن علی کی روایت میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ کھڑے ہو گئے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے مروی ہے کہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے کر گزرے تو آپ کھڑے ہوگئے۔\nعمرو (بن علی کی روایت میں یوں ہے، انھوں) نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ کھڑے ہوگئے۔"}],[1920,"یزید بن ثابت رضی اللہ عنہ سے روایت ہے کہ وہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے ساتھ بیٹھے تھے (اتنے میں) ایک جنازہ نظر آیا تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو گئے، اور جو ان کے ساتھ تھے وہ بھی کھڑے ہو گئے، تو وہ لوگ برابر کھڑے رہے یہاں تک کہ وہ نکل گیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت یزید بن ثابت رضی اللہ عنہ سے منقول ہے کہ (ایک دفعہ) ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ بیٹھے تھے کہ ایک جنازہ آتا نظر آیا۔ رسول اللہ صلی اللہ علیہ وسلم اٹھ کھڑے ہوئے اور جو لوگ آپ کے پاس تھے وہ بھی اٹھ کھڑے ہوئے، پھر سب کھڑے رہے حتی کہ جنازہ آگے گزر گیا۔","f2":"مندرجہ بالا قولی اور فعلی، مرفوع اور موقوف روایات سے صراحتاً ثابت ہوتا ہے کہ جنازہ آتا دیکھ کر کھڑے ہو جانا چاہیے۔ فطرت اور عقل بھی اسی بات کا تقاضا کرتے ہیں اور یہی صحیح ہے۔ مگر حضرت علی اور ابن عباس رضی اللہ عنھم قیام کے قائل نہیں یا کہیے کہ اس ضروری نہیں مجھتے جیسا کہ آگے ایک باب میں احادیث آ رہی ہیں، مگر وہ ان کا استنباط معلوم ہوتا ہے، اس لیے وہ قیام کی روایات کا مقابلہ نہیں کرسکتا۔ زیادہ سے زیادہ ان روایات سے رسول اللہ صلی اللہ علیہ وسلم کا بیٹھنا ثابت ہوتا ہے، نیز تطبیق بھی ممکن ہے کہ کھڑے ہونے کا حکم استحباب پر دلالت کرتا ہے مگر بیٹھنا بھی جائز ہے اور یہ اچھی تطبیق ہے۔ (مزید بحث کے لیے دیکھیے، حدیث: ۱۹۱۵)"}],[1921,"عبدالرحمٰن بن ابی لیلی کہتے ہیں کہ سہل بن حنیف اور قیس بن سعد بن عبادہ رضی اللہ عنہ قادسیہ میں تھے۔ ان دونوں کے قریب سے ایک جنازہ لے جایا گیا، تو دونوں کھڑے ہو گئے تو ان سے کہا گیا: یہ تو ذمی ہے؟ تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے جایا گیا تو آپ کھڑے ہو گئے، تو آپ سے عرض کیا گیا یہ تو یہودی ہے؟ تو آپ صلی اللہ علیہ وسلم نے کہا: \"کیا یہ روح نہیں ہے؟\"۔","الألباني: صحيح",{"u2":"حضرت عبدالرحمن بن ابی الیلیٰ بیان کرتے ہیں کہ حضرات سہل بن حنیف اور قیس بن سعد بن عبادہ رضی اللہ عنہما قادسیہ مقام پر تھے کہ ایک جنازہ گزرا۔ وہ دونوں کھڑے ہوگئے۔ ان سے کہا یا: یہ جنازہ تو اس علاقے والوں (یعنی ذمی کافروں) کا ہے؟ تو ان دونوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ کھڑے ہوگئے۔ آپ سے کہا گیا: یہ تو ایک یہودی کا جنازہ ہے! آپ صلی اللہ علیہ وسلم نے فرمایا: ’’کیا یہ انسانی جان نہیں تھی؟‘‘","f2":"دین سے قطع نظر انسانیت کا بھی احترام ہونا چاہیے، نیز موت میں مسلم کافر سب برابر ہیں، پھر کافروں سے رواداری انھیں اسلام کے قریب لانے کا سبب بنے گی۔ اختلاف دین کی وجہ سے انسانی تقاضوں سے انحراف دین فطرت کے خلاف ہے۔ دین اسلام تو جانوروں تک سے ہمدردی رکھتا ہے۔ رسول اللہ صلی اللہ علیہ وسلم کی بہت سی احادیث اس پر دلالت کرتی ہیں۔"}],[1922,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ ایک جنازہ ہمارے پاس سے گزرا تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہو گئے، اور آپ کے ساتھ ہم بھی کھڑے ہو گئے، میں نے عرض کیا: اللہ کے رسول! یہ جنازہ (ایک) یہودی عورت کا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"موت ایک قسم کی ہیبت ہے، تو جب تم جنازہ دیکھو تو کھڑے ہو جاؤ\"، یہ الفاظ خالد کے ہیں۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما فرماتے ہیں کہ ہمارے پاس سے ایک جنازہ گزرا تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوگئے۔ ہم بھی آپ کے ساتھ کھڑے ہوگئے۔ (بعد میں) میں نے آپ سے کہا: اے اللہ کے رسول! یہ تو ایک یہودی عورت کا جنازہ تھا! آپ نے فرمایا: ’’موت گھبراہٹ والی چیز ہے لہٰذا جب تم کوئی جنازہ دیکھو تو کھڑے ہو جاؤ۔‘‘حدیث کے یہ الفاظ خالد راوی کے بیان کردہ ہیں۔","f2":"تفصیل کے لیے دیکھیے حدیث نمبر 1915۔"}],[1923,"ابومعمر کہتے ہیں کہ ہم علی رضی اللہ عنہ کے پاس تھے (اتنے میں) ایک جنازہ گزرا تو لوگ کھڑے ہو گئے، تو علی رضی اللہ عنہ نے کہا: یہ کیا ہے؟ لوگوں نے کہا: ابوموسی اشعری کا حکم ہے، تو انہوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم ایک یہودی عورت کے جنازے کے لیے کھڑے ہوئے تھے، (پھر) اس کے بعد آپ کبھی کھڑے نہیں ہوئے۔","الألباني: صحيح",{"u2":"حضرت ابو معمر بیان کرتے ہیں کہ ہم حضرت علی رضی اللہ عنہ کے پاس بیٹھے تھے کہ ایک جنازہ پاس سے گزرا۔ لوگ اس کی وجہ سے کھڑے ہوگئے۔ حضرت علی رضی اللہ عنہ نے فرمایا: یہ کیا ہے؟ (تم کیوں کھڑے ہوئے؟) لوگں نے کہا: یہ حضرت ابوموسیٰ رضی اللہ عنہ کی ہدایت ہے۔ انھوں نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم تو صرف ایک یہودی عورت کے جنازے کو دیکھ کر کھڑے ہوئے تھے، اس کے بعد کبھی کھڑے نہیں ہوئے۔","f2":"حضرت علی رضی اللہ عنہ اپنے علم و رؤیت کی بات کر رہے ہیں ورنہ صحابۂ کرام رضی اللہ عنھم سے رسول اللہ صلی اللہ علیہ وسلم کے کھڑے ہونے کی روایات صراحتاً آئی ہیں۔ قولی روایات اس کے علاوہ ہیں۔ جن میں ہر جنازے کا ذکر ہے۔ ان روایات کے مقابلے میں حضرت علی رضی اللہ عنہ کی یہ روایت اصول حدیث کی رو سے مرجوح ہے۔ عمل ان روایات ہی پر ہوگا۔ زیادہ سے زیادہ یہ کہا جا سکتا ہے کہ قیام واجب نہیں۔"}],[1924,"محمد بن سیرین سے روایت ہے کہ ایک جنازہ حسن بن علی اور ابن عباس رضی اللہ عنہم کے پاس سے گزرا، تو حسن رضی اللہ عنہ کھڑے ہو گئے، اور ابن عباس رضی اللہ عنہما نہیں کھڑے ہوئے، تو حسن رضی اللہ عنہ نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم ایک یہودی کا جنازہ (دیکھ کر) کھڑے نہیں ہوئے تھے؟ تو ابن عباس رضی اللہ عنہما نے کہا: ہاں، پھر بیٹھے رہنے لگے تھے ۱؎۔\n§وضاحت\n۱؎: یعنی پھر اس کے بعد کسی جنازے کو دیکھ کر کھڑے نہیں ہوئے۔","الألباني: صحيح الإسناد",{"u2":"حضرت محمد بن سیرین سے روایت ہے کہ حضرات حسن بن علی اور ابن عباس رضی اللہ عنھم کے پاس سے ایک جنازہ گزرا۔ حضرت حسن رضی اللہ عنہ کھڑے ہوگئے لیکن حضرت ابن عباس رضی اللہ عنہما کھڑے نہ ہوئے۔ حضرت حسن رضی اللہ عنہ کہنے لگے: کیا رسول اللہ صلی اللہ علیہ وسلم ایک یہودی کے جنازے کی وجہ سے کھڑے نہیں ہوئے تھے؟ حضرت ابن عباس رضی اللہ عنہما نے کہا: ٹھیک ہے مگر پھر بیٹھے بھی رہے۔","f2":"حضرت ابن عباس رضی اللہ عنہما کی بات کا مطلب یہ ہے کہ پھر ایسا ہی ہوا، کوئی جنازہ گزرا مگر آپ بیٹھے رہے، کھڑے نہیں ہوئے گویا بیٹھے رہنے کا جواز بھی ہے۔"}],[1925,"اس سند سے بھی ابن سیرین کہتے ہیں کہ حسن بن علی اور ابن عباس رضی اللہ عنہم کے قریب سے ایک جنازہ گزرا، تو حسن رضی اللہ عنہ کھڑے ہو گئے، اور ابن عباس رضی اللہ عنہما نہیں کھڑے ہوئے، تو حسن رضی اللہ عنہ نے ابن عباس سے کہا: کیا اس کے لیے رسول اللہ صلی اللہ علیہ وسلم کھڑے نہیں ہوئے تھے؟ تو ابن عباس رضی اللہ عنہما نے کہا: کھڑے ہوئے تھے پھر بیٹھے رہنے لگے تھے ۱؎۔\n§وضاحت\n۱؎: جمہور نے اس سے کھڑے ہونے والی روایت کے منسوخ ہونے پر استدلال کیا ہے، نیز یہ بھی ممکن ہے کہ آپ کا کھڑا نہ ہونا بیان جواز کے لیے رہا ہو، واللہ اعلم۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن سیرین رحمہ اللہ نے کہا کہ حضرات حسن بن علی اور ابن عباس رضی اللہ عنھم کے پاس سے ایک جنازہ گزرا۔ حضرت حسن رضی اللہ عنہ کھڑے ہوگئے اور حضرت ابن عباس رضی اللہ عنہما کھڑے نہ ہوئے۔ حضرت حسن رضی اللہ عنہ نے حضرت ابن عباس رضی اللہ عنہما سے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم جنازے کو دیکھ کر کھڑے نہیں ہوئے تھے؟ حضرت ابن عباس رضی اللہ عنہما نے کہا: کھڑے ہوئے تھے مگر پھر بیٹھے رہے۔"}],[1926,"اس سند سے بھی ابن عباس رضی اللہ عنہما اور حسن بن علی رضی اللہ عنہما سے روایت ہے کہ ان دونوں کے پاس سے ایک جنازہ گزرا تو ان میں سے ایک کھڑے ہو گئے، اور دوسرے بیٹھے رہے، تو جو کھڑے ہو گئے تھے انہوں نے کہا: سنو! اللہ کی قسم! مجھے یہی معلوم ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے تھے، تو جو بیٹھے رہ گئے تھے انہوں نے کہا: مجھے (یہ بھی) معلوم ہو کہ رسول اللہ صلی اللہ علیہ وسلم (بعد میں) بیٹھے رہنے لگے تھے۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابومجلز رحمہ اللہ سے مروی ہے کہ حضرات ابن عباس اور حسن رضی اللہ عنھم کے قریب سے ایک جنازہ گزرا۔ انمیں سے ایک کھڑے ہوگئے جبکہ دوسرے بیٹھے رہے۔ کھڑے ہونے والے نے کہا: اللہ کی قسم! میں یقیناً جانتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے تھے۔ بیٹھے رہنے والے نے ان سے کہا۔ اللہ کی قسم! میں بھی یقیناً جانتا ہوں کہ رسول اللہ صلی اللہ علیہ وسلم بیٹھے بھی رہے تھے۔"}],[1927,"محمد بن علی الباقر کہتے ہیں کہ حسن بن علی رضی اللہ عنہما بیٹھے تھے کہ ایک جنازہ گزرا تو لوگ کھڑے ہو گئے یہاں تک کہ جنازہ گزر گیا، تو حسن رضی اللہ عنہ نے کہا: ایک یہودی کا جنازہ گزرا، رسول اللہ صلی اللہ علیہ وسلم اسی راستے میں بیٹھے تھے تو آپ نے ناپسند کیا کہ ایک یہودی کا جنازہ آپ کے سر سے بلند ہو تو آپ کھڑے ہو گئے۱؎۔\n§وضاحت\n۱؎: یہ تاویل حسن رضی اللہ عنہ کی ہے جو ان کے ذہن میں آئی، لیکن احادیث سے جو بات سمجھ میں آئی ہے وہ یہ ہے کہ اس کی وجہ موت کی ہیبت اور اس کی سنگینی تھیں جیسا کہ «إن للموت فزعاً» والی روایت سے ظاہر ہے، نیز یہ بھی ممکن ہے کہ اس کی متعدد وجہیں رہی ہوں، ان میں سے ایک یہ بھی ہو کیونکہ ایک روایت میں ہے: ہم فرشتوں کی تکریم میں کھڑے ہوئے ہیں نہ کہ جنازہ کی۔","الألباني: صحيح",{"u2":"حضرت محمد باقر رحمہ اللہ سے منقول ہے کہ حضرت حسن بن علی رضی اللہ عنہما بیٹھے ہوئے تھے کہ ایک جنازہ گزرا۔ لوگ کھڑے ہوگئے حتی کہ جنازہ آگے چلا گیا۔ حضرت حسن رضی اللہ عنہ فرمانے لگے: بات اتنی تھی کہ ایک یہودی کا جنازہ گزرا اور رسول اللہ صلی اللہ علیہ وسلم جنازے کے راستے میں بیٹھے ہوئے تھے۔ آپ نے ناپسند فرمایا کہ ایک یہودی کا جنازہ آپ کے سر سے اونچا ہو، اس لیے آپ کھڑے ہوگئے۔","f2":"یہ روایت سابقہ روایات سے مختلف ہے۔ ان میں تو حضرت حسن رضی اللہ عنہ کھڑے ہونے کے قائل و فاعل ہیں، اور اس روایت میں اس کے خلاف ہیں۔ کثرت کی بنا پر ان روایات کو ترجیح ہوگی، نیز یہ حضرت حسن رضی اللہ عنہ کا اپنا خیال ہے کہ رسول اللہ صلی اللہ علیہ وسلم اس وجہ سے کھڑے ہئے تھے، ورنہ رسول اللہ صلی اللہ علیہ وسلم نے تو اور وجہ بتلائی ہے۔ حدیث: ۱۹۲۲ میں ألیس نفسا اور حدیث نمبر ۱۹۲۳ میں إن للموت فزعا فرمایا۔ اور حدیث: ۱۹۳۱ میں آ رہا ہے کہ ہم فرشتوں کی تعظیم کے لیے کھڑے ہوئے ہیں۔ ظاہر ہے رسول اللہ صلی اللہ علیہ وسلم کی بیان کردہ وجوہات معتبر ہیں نہ کہ حضرت حسن رضی اللہ عنہ کا اپنا خیال۔ بالفرض یہ وجہ بھی ہو تو مذکورہ بالا وجوہات تو پھر بھی قائم ہیں، لہٰذا صحیح یہی ہے کہ جنازہ آتا دیکھ کر کھڑے ہونا چاہیے، یہ افضل اور مستحب ہے، اگرچہ بیٹھے رہنے کی بھی گنجائش ہے۔ واللہ أعلم۔"}],[1928,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم ایک یہودی کے جنازہ کے لیے کھڑے ہوئے جو آپ کے پاس سے گزرا یہاں تک کہ وہ(نظروں سے) اوجھل ہو گیا۔\nاس سند سے بھی جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم اور آپ کے اصحاب ایک یہودی کے جنازے کے لیے سے کھڑے ہوئے یہاں تک کہ وہ (نظروں سے) اوجھل ہو گیا۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم اور آپ کے صحابہ رضی اللہ عنھم ایک یہودی کے جنازے کو دیکھ کر کھڑے ہوئے جو پاس سے گزرا تھا حتی کہ وہ نظروں سے اوجھل ہوگیا (پھر بیٹھے)۔"}],[1929,"انس رضی اللہ عنہ سے روایت ہے کہ ایک جنازہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا تو آپ کھڑے ہو گئے، آپ سے کہا گیا: یہ ایک یہودی کا جنازہ ہے تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ہم فرشتوں (کی تکریم میں) کھڑے ہوئے ہیں، (نہ کہ جنازہ کی)۔","الألباني: صحيح أيضاً",{"u2":"انس رضی اللہ عنہ سے روایت ہے کہ ایک جنازہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے گزرا تو آپ کھڑے ہوگئے۔","f2":"جنازہ آتا دیکھ کر کھڑےہونے کی تین وجوہات صحیح احادیث میں وارد ہیں۔ تفصیل کے لیے دیکھیے فائدہ حدیث نمبر ۱۹۲۸۔ یہ تینوں وجوہات اب بھی قائم ہیں، لہٰذا راجح موقف کے مطابق جنازہ آتا دیکھ کر کھڑا ہونا افضل اور مستحب ہے صرف وجوب منسوخ ہے۔ واللہ أعلم۔ نیز اس مسئلے کی تفصیلی بحث کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي للإتبوبي: ۹۲-۸۷/۱۹)"}],[1930,"ابوقتادہ بن ربعی رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے جایا گیا، تو آپ نے فرمایا: (یہ) «مستریح» ہے یا«مستراح منہ» ہے، تو لوگوں نے پوچھا: «مستریح» اور «مستراح منہ» سے کیا مراد ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"بندہ مومن (موت کے بعد) دنیا کی بلا اور تکلیف سے راحت پا لیتا ہے، اور فاجر ۱؎ بندہ مرتا ہے تو اس سے اللہ کے بندے، بستیاں، پیڑ پودے، اور چوپائے (سب) راحت پا لیتے ہیں\"۔\n§وضاحت\n۱؎: بعض لوگوں نے کہا ہے فاجر سے مراد کافر ہے کیونکہ یہاں مومن کے بالمقابل استعمال ہوا ہے، لیکن صحیح یہ ہے کہ اسے کافر اور فاجر دونوں کے لیے عام مانا جائے، کیونکہ کافر کی طرح فاجر مسلمان بھی بندگان اللہ کو اپنے مظالم کا شکار بناتے ہیں، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت ابو قتادہ بن ربعی رضی اللہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ گزرا تو آپ نے فرمایا: ’’اس نے آرام پا لیا یا لوگوں نے اس سے آرام پا لیا۔‘‘ صحابہ نے عرض کیا: اس کا کیا مطلب ہے؟ آپ نے فرمایا: ’’مومن شخص (موت کے ساتھ) دنیا کے رنج و تکلیف سے آرام پا جاتا ہے اور بدکار شخص (کی موت) سے لوگ، شہر، درخت اور جانور آرام پا جاتے ہیں۔‘‘","f2":"(۱) ’’مومن شخص‘‘ یہاں مومن سے متقی شخص مراد ہے جو لوگوں کو بھی ایذا نہیں پہنچاتا اور جانوروں پر بھی ظلم نہیں کرتا۔ اس کے ساتھ ساتھ حقوق اللہ کی پابندی کرتا ہے۔ ان کاموں میں سے اسے دنیا میں تکلیف وغیرہ پہنچے تو اس پر صبر کرتا ہے۔ دنیا میں معاش کے سلسلے میں اسے محنت و مشقت کرنی پڑتی ہے۔ دنیا میں بیماری اور پریشانیاں ’’دنیا کے رنجو غم‘‘ سب اس میں داخل ہیں۔ (۲) ’’بکار شخص‘‘ اس سے مراد صرف کافر ہی نہیں بلکہ وہ اشخاص بھی اس میں داخل ہیں جو لوگوں پر ظلم و ستم کرتے ہیں، جانوروں کو ایذا پہنچاتے ہیں، آبادیوں کو ویران کرتے ہیں اور اس کے ساتھ ساتھ حقوق اللہ کی بھی پروا نہیں کرتے۔ فسق و فجور میں بگ ٹٹ دوڑے جاتے ہیں، حتی کہ ان کے فسق و فجور کی وجہ سے بارش رک جاتی ہے اور ان کی نحوست سے قحط سالی آ پڑتی ہے۔ بے گناہ جانور اور درخت اپنی جان سے ہاتھ دھو بیٹھتے ہیں، البتہ وہ لوگ جن سے گناہ تو صادر ہوتے ہیں (کیونکہ ہر انسان خطاکار ہے) مگر وہ اللہ تعالیٰ کی طرف رجوع کرتے ہیں، معافی مانگتے ہیں تو وہ ’’فاجر‘‘ اور ’’بکار‘‘ کے تحت داخل نہیں کیونکہ معافی اور توبہ گناہ ک ختم کر دیتے ہیں، بلکہ توبہ کی برکت سے اللہ تعالیٰ رحمتیں فرماتا ہے، ارشاد باری تعالیٰ ہے: (استغفروا ربکم انہ کان غفارا o یرسل السمآء علیکم مدرارا) (نوح ۱۱،۱۰/۷۱) لہٰذا توبہ اور استغفار کرنے والا انسان، خواہ کتنا ہی گناہ گار ہو، لوگوں، شہروں، جانوروں اور درختوں کے لیے رحمت کا سبب ہے۔"}],[1931,"ابوقتادہ رضی اللہ عنہ کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ اتنے میں ایک جنازہ نظر آیا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ«مستریح» ہے یا «مستراح منہ» ہے، (کیونکہ) جب مومن مرتا ہے تو دنیا کی مصیبتوں، بلاؤں اور تکلیفوں سے نجات پا لیتا ہے، اور فاجر مرتا ہے تو اس سے(اللہ کے) بندے، ملک و شہر، پیڑ پودے، اور چوپائے (سب) راحت پا لیتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس بیٹھے تھے کہ ایک جنازہ نمودار ہوا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ آرام پانے والا ہے یا مخلوقات کو اس سے آرام ملا ہے۔ مومن فوت ہوتا ہے تو دنیا کی بیماریوں، تکالیف اور مصیبتوں سے نجات پا جاتا ہے۔ اور بدکار شخص مرتا ہے تو اس سے انسان، علاقے، درخت اور جانور نجات اور آرام پا جاتے ہیں۔‘‘","f2":"باب میں کافر کا لفظ ہے اور حدیث میں فاجر کا، اشارہ ہے کہ فاجر سے مراد کافر ہے یا کافروں جیسا۔ واللہ أعلم۔"}],[1932,"انس رضی اللہ عنہ کہتے ہیں کہ ایک جنازہ لے جایا گیا تو اس کی تعریف کی گئی، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"واجب ہو گئی\"، (پھر) ایک دوسرا جنازہ لے جایا گیا، تو اس کی مذمت کی گئی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"واجب ہو گئی\"، تو عمر رضی اللہ عنہ نے عرض کیا: میرے ماں باپ آپ پر فدا ہوں، ایک جنازہ لے جایا گیا تو اس کی تعریف کی گئی، تو آپ نے فرمایا: واجب ہو گئی پھر ایک دوسرا جنازہ لے جایا گیا تو اس کی مذمت کی گئی، تو آپ نے فرمایا: واجب ہو گئی؟، تو آپ نے فرمایا: \"تم لوگوں نے جس کی تعریف کی تھی اس کے لیے جنت واجب ہو گئی، اور جس کی مذمت کی تھی اس کے لیے جہنم واجب ہو گئی، تم ۱؎ روئے زمین پر اللہ کے گواہ ہو\"۔\n§وضاحت\n۱؎: بعض لوگوں نے کہا ہے یہ خطاب صحابہ کرام رضی اللہ عنہم کے ساتھ مخصوص ہے، اور ایک قول یہ ہے کہ اس خطاب میں صحابہ رضی اللہ عنہم کرام کے ساتھ وہ لوگ بھی شامل ہیں جو ان کے طریقہ پر کاربند ہوں۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ ایک جنازہ گزرا تو اس کی اچھی تعریف کی گئی، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’لازم ہوگئی۔‘‘ ایک اور جنازہ گزرا تو اس کی برائی بیان کی گئی، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’واجب ہوگئی۔‘‘ حضرت عمر رضی اللہ عنہ نے عرض کیا: میرے ماں باپ آپ پر قربان! ایک جنازہ گزرا، اس کی اچھی تعریف ہوئی تو آپ نے فرمایا: ’’لازم ہوگئی۔‘‘ پھر دوسرا جنازہ گزرا، اس کی برائی بیان کی گئی تو آپ نے پھر وہی فرمایا: ’’واجب ہوگئی۔‘‘ (کیا مطلب ہے؟) آپ نے فرمایا: ’’جس کی تم نے اچھی تعریف کی تھی اس کے لیے جنت لازم ہوگئی اور جس کی برائی بیان کی اس کے لیے آگے واجب ہوئی۔ تم زمین میں اللہ تعالیٰ کے گواہ ہو۔‘‘","f2":"(۱) ’’تم نے اچھی تعریف کی۔‘‘ تم سے مراد عام لوگ ہیں۔ جس شخص کو سب لوگ اچھا کہیں، وہ اچھا ہی ہوگا اور جس کو سب برا کہیں (موت کے بعد) وہ برا ہی ہوگا کیونکہ سب لوگ اسی کی تعریف کریں گے جو سب کے ساتھ اچھا رہا اور جس نے سب کو امن میں رکھا۔ جو شخص لوگوں کے حقوق میں کوتاہی نہیں رتا، وہ بالعموم اللہ تعالیٰ کے حقوق میں بھی کوتاہی نہیں کرے گا۔ اسی طرح برا کہنا ہے۔ لازماً وہ لوگوں سے بدسولکی کرنے والا ہے ورنہ سب برا نہ کہتے۔ اور جو لوگوں کے حقوق ادا نہیں کرتا، وہ اللہ تعالیٰ کے حقوق بھی ادا نہیں کرے گا۔ بعض اہل علم نے تم سے مراد صرف صحابۂ کرام رضی اللہ عنھم یا متقی حضرات لیے ہیں کیونکہ وہ اسی کی تعریف کریں گے جو حقیقتاً نیک ہوگا، اور اسی کو برا کہیں گے جو حقیقتاً برا ہوگا مگر یہ تخصیص بلادلیل ہے، صحیح توجیہ اوپر بیان ہوچکی ہے۔ (۲) ’’اللہ تعالیٰ کے گواہ‘‘ جس طرح عدالت میں فیصلہ گواہوں کے مطابق ہوتا ہے، اسی طرح اللہ تعالیٰ بھی لوگوں کی گواہی کے مطابق فیصلہ فرمائے گا۔ [إن خیرا فخیر و إن شرا فشر] کیونکہ انسان کے اخلاق کا علم معاملات سے ہوتا ہے۔ (۳) اس سے امت کی فضیلت بھی ظاہر ہوئی کہ یہ زمین پر اللہ کی گواہ ہے۔"}],[1933,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ لوگ نبی اکرم صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے کر گزرے، تو لوگوں نے اس کی تعریف کی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا \": واجب ہو گئی\"، پھر لوگ ایک دوسرا جنازہ لے کر گزرے، تو لوگوں نے اس کی مذمت کی تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"واجب ہو گئی\"، لوگوں نے پوچھا: اللہ کے رسول! آپ کے پہلی بار اور دوسری بار «وجبت» کہنے سے کیا مراد ہے؟ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"فرشتے آسمان پر اللہ کے گواہ ہیں، اور تم زمین پر اللہ کے گواہ ہو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ لوگ نبی صلی اللہ علیہ وسلم کے پاس سے ایک جنازہ لے کر گزرے۔ حاضرین نے اس کی اچھی تعریف کی۔ نبی صلی اللہ علیہ وسلمنے فرمایا: ’’واجب ہوگئی۔‘‘ پھر لوگ ایک اور جنازہ لے کر گزرے۔ حاضرین نے اس کی برائی بیان کی۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’واجب ہوگئی۔‘‘ لوگوں نے عرض کیا: اے اللہ کے رسول! آپ نے پہلے جنازے کے بارے میں بھی فرمایا: ’’واجب ہوگئی۔‘‘ اور دوسرے جنازے کے بارے میں بھی فرمایا: ’’واجب ہوگئی‘‘ (کیا مطلب ہے؟) نبی صلی اللہ علیہ وسلم نے فرمایا: ’’فرشتے آسمان میں اللہ تعالیٰ کے گواہ ہیں اور تم زمین میں اللہ تعالیٰ کے گواہ ہو۔‘‘","f2":"فرشتے تحریری نامۂ اعمال پیش کریں گے اور انسان اپنا تجربہ اور معاملہ بیان کریں گے، دونوں کی بنیاد پر فیصلہ ہوگا۔"}],[1934,"ابو اسود دیلی کہتے ہیں کہ میں مدینہ آیا تو عمر بن خطاب رضی اللہ عنہ کے پاس بیٹھا اتنے میں ایک جنازہ لے جایا گیا، تو اس کی تعریف کی گئی تو عمر رضی اللہ عنہ نے کہا: واجب ہو گئی، پھر ایک دوسرا جنازہ لے جایا گیا، تو اس کی (بھی) تعریف کی گئی، تو عمر رضی اللہ عنہ نے کہا: واجب ہو گئی، پھر ایک تیسرا جنازہ لے جایا گیا، تو اس کی مذمت کی گئی، تو عمر رضی اللہ عنہ نے کہا: واجب ہو گئی، تو میں نے پوچھا: امیر المؤمنین! کیا واجب ہو گئی؟ انہوں نے کہا: میں نے وہی بات کہی جو رسول اللہ صلی اللہ علیہ وسلم نے فرمائی: \"جس مسلمان کے لیے بھی چار لوگوں نے خیر کی گواہی دی تو اللہ اسے جنت میں داخل کرے گا\"، ہم نے پوچھا: (اگر) تین گواہی دیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تین ہی سہی\"، (پھر) ہم نے پوچھا: (اگر) دو گواہی دیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"دو ہی سہی\"۔","الألباني: صحيح",{"u2":"حضرت ابو الاسود دیلی رحمہ اللہ سے منقول ہے کہ میں مدینہ منورہ آیا اور مجھے حضرت عمر بن خطاب رضی اللہ عنہ کے پاس بیٹھنے کا اتفاق ہوا۔ ایک جنازہ گزرا اور اس کی اچھی تعریف کی گئی۔ حضرت عمر رضی اللہ عنہ نے فرمایا: واجب ہو گئی، پھر ایک اور جنازہ گزرا۔ اس کی بھی اچھی تعریف کی گئی۔ حضرت عمر رضی اللہ عنہ نے فرمایا: واجب ہوگئی، پھر تیسرا جنازہ گزرا تو اس کی برائی بیان کی گئی۔ حضرت عمر رضی اللہ عنہ نے فرمایا: واجب ہوگئی۔ میں نے عرض کیا: اے امیر المومنین! کیا واجب ہوگئی؟ انھوں نے فرمایا: میں نے تو اسی طرح کہا ہے جیسے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: ’’جس مسلمان کے لیے چار آدمی نیک ہونے کی گواہی دیں، اللہ تعالیٰ اسے جنت میں داخل فرمائے گا۔‘‘ ہم نے کہا: اور تین؟ فرمایا: ’’ہاں تین بھی۔‘‘ ہم نے کہا: اور دو؟ پ نے فرمایا: ’’ہاں دو بھی (یعنی دو کی گواہی بھی معتبر ہوگی)۔‘‘","f2":"گواہی کے لیے جو شرائط ضروری ہیں، وہ ان میں پائی جائیں، یعنی وہ عادل مسلمان ہوں۔ عادل سے مراد کہ وہ شرعی فرائض کے پابند اور کبیرہ گناہوں سے محفوظ ہوں۔ ظاہر ہے اس قسم کے گواہ ہی سچی گواہی دیں گے۔"}],[1935,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک مرے ہوئے شخص کا ذکر برائی سے کیا گیا، تو آپ نے فرمایا: \"تم اپنے مردوں کا ذکر صرف بھلائی کے ساتھ کیا کرو\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہما فرماتی ہیں کہ نبی صلی اللہ علیہ وسلم کے پاس کسی فوت شدہ شخص کی برائی بیان کی گئی تو آپ نے فرمایا: ’’اپنے فوت شدگان کا ذکر خیر ہی کیا کرو۔‘‘","f2":"کسی غائب شخص کی برائی ذکر کرنا تو زندگی میں بھی غیبت بن جاتی ہے جو سخت منع ہے، حالانکہ اس کی طرف سے دفاع ممکن ہے، تو ایک میت جو اپنا دفاع بھی نہیں کرسکتا اس کی برائی بیان کرنا کیونکر جائز ہوسکتا ہے، نیز گناہوں اور کوتاہیوں سے کون پاک ہے؟ لہٰذا فوت شدہ کی برائی بیان نہ کی جائے بلکہ درگزر کیا جائے تاکہ اللہ تعالیٰ ہم سے درگزر فرمائے، البتہ امت مسلمہ کے مفاد کے لیے ضرورت کی حد تک کسی زندہ یا فوت شدہ کی برائی بیان ہوسکتی ہے، جیسے رجالِ حدیث کا فن۔"}],[1936,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے مردوں کو برا بھلا نہ کہو کیونکہ انہوں نے جو کچھ آگے بھیجا تھا، اس تک پہنچ چکے ہیں\" ۱؎۔\n§وضاحت\n۱؎: یعنی انہیں اپنے اعمال کی جزا و سزا مل رہی ہے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہما سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مردوں کو برا نہ کہو کیونکہ وہ اپنے اعمال (کی جزا و سزا) کی طرف پہنچ چکے ہیں۔‘‘","f2":"فوت شدگان کے معاملے کو اللہ کے سپرد کر دیا جائے کیونکہ اللہ تعالیٰ کا فیصلہ ہی صحیح ہے۔ ہم کسی ایسے شخص کو برا کہیں جو اللہ تعالیٰ کے نزدیک اچھا ہو تو اس میں بہت گناہ ہے، لہٰذا خاموشی بہتر ہے، البتہ وہ کافر یا منافق یا فاجر جو علانیہ عوام الناس کے نزدیک ان اوصاف میں معروف اور بدنام ہیں، ان کی موت اگر انھی اوصاف پر ہوئی تو انھیں ان اوصاف کے ساتھ ذکر کیا جا سکتا ہے تاکہ لوگ ان کی اقتدا نہ کریں۔ اسی طرح ائمہ مضلین (اہل بدعت) کی گمراہیوں کی ضواحت کرنی بھی جائز بلکہ ضروری ہے۔"}],[1937,"انس بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مردے (کے ساتھ) تین چیزیں (قبرستان تک) جاتی ہیں: اس کے گھر والے، اس کا مال، اور اس کا عمل، (پھر) دو چیزیں یعنی اس کے گھر والے اور اس کا مال لوٹ آتے ہیں، اور ایک باقی رہ جاتا ہے اور وہ اس کا عمل ہے\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میت کے ساتھ تین چیزیں قبر کی طرف جاتی ہیں: اس کے رشتے دار، اس کا مال اور اس کا عمل۔ دو چیزیں، یعنی رشتے دار اور مال تو واپس آ جاتے ہیں اور ایک چیز، یعنی اس کا عمل اس کے پاس رہ جاتا ہے۔‘‘","f2":"(۱) ’’اس کا مال’’ مراد غلام وغیرہ ہیں۔ جاہلیت میں لوگ فخر کے لیے جنازے کے ساتھ اس کے گھوڑے اور اسلحہ وغیرہ بھی لے جاتے تھے۔ (۲) انسان کا عمل اس کے ساتھ رہے گا، اس لیے اعمال صالحہ کی زیادہ سے زیادہ کوشش کرنی چاہیے اور اہل اور مال میں مشغو ل ہوکر اعمال سے غافل نہیں ہونا چاہیے۔ (۳) اس حدیث کا باب سے کوئی ظاہری تعلق سمجھ میں نہیں آ رہا۔"}],[1938,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن کے مومن پر چھ حقوق ہیں: جب بیمار ہو تو وہ اس کی عیادت کرے، جب مر جائے تو اس کے جنازے میں شریک رہے، جب دعوت کرے تو اسے قبول کرے، جب وہ اس سے ملے تو اسے سلام کرے، جب چھینکے اور «الحمد للہ» کہے تو جواب میں «یرحمک اللہ» کہے، اور اس کی خیر خواہی کرے خواہ اس کے پیٹھ پیچھے ہو یا سامنے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مومن کے مومن پر چھ حق ہیں: جب وہ بیمار ہو جائے تو اس کی بیمار پرسی کرے، جب وہ فوت ہو جائے تو (اس کے کفن، دفن اور جنازے میں) شریک ہو، جب وہ دعوت دے تو قبول کرے، جب وہ اسے ملے تو سلام کہے، جب اسے چھینک آئے تو اسے دعا دے اور اس کی خیر خواہی کرے جب وہ غائب ہو یا موجود۔‘‘","f2":"(۱) یاد رہے کہ بعض حقوق تعلقات اور ضرورت کی حد تک ہیں، مثلاً: بیمار کی بیمارپرسی دنیا کے ہر مسلمان کا نہیں بلکہ اس کے تعلق داروں کا فرض ہے۔ اسی طرح کفن، دفن اور جنازے میں شرکت کرنا بھی اس کے تعلق داروں اور محلے کے افراد وغیرہ کا فرض ہے، ایسے فرائض کو فرض کفایہ کہتے ہیں، یعنی کوئی بیمار، بیمار پرسی کے بغیر نہ رہے اور کوئی میت تکفین و تجہیز اور جنازے سے محروم نہ رہے ورنہ مسلمان گناہ گار ہوں گے۔ ہر ایک کی شرکت فرض نہیں۔ (۲) سلام کا جواب اور چھینک پر دعا (بشرطیکہ وہ الحمدللہ کہے) صرف متعلقہ شخص پر ضروری ہے۔ دعوت کی قبولیت ہر شخص پر ضروری ہے۔ جماعت کی صورت میں چند (خواہ ایک ہی ہو) کی طرف سے ادائیگی کافی ہوگی۔"}],[1939,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سات چیزوں کا حکم دیا، اور سات باتوں سے منع فرمایا: ہمیں آپ نے مریض کی عیادت کرنے، چھینکنے والے کے جواب میں «یرحمک اللہ» کہنے، قسم پوری کرانے، مظلوم کی مدد کرنے، سلام کو عام کرنے، دعوت دینے والوں (کی دعوت)قبول کرنے، اور جنازے کے ساتھ جانے کا حکم دیا، اور ہمیں آپ نے سونے کی انگوٹھیاں پہننے سے، چاندی کے برتن (میں کھانے، پینے) سے، میاثر، قسّیہ، استبرق ۱؎، حریر اور دیباج نامی ریشمی کپڑوں سے منع فرمایا ہے۔\n§وضاحت\n۱؎: استبرق، حریر اور دیباج یہ تینوں ریشمی کپڑوں کی قسمیں ہیں۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما فرماتے ہیں رسول اللہ صلی اللہ علیہ وسلم نے ہمیں سات چیزوں کا حکم دیا اور سات چیزوں سے روکا۔ ہمیں بیمار کی بیمار پرستی کرنے، چھینکنے والے کو دعا دینے، قسم کھانے والے کی بات کو پورا کرنے (بشرطیکہ وہ جائز ہو)، مظلوم کی مدد کرنے، ہر ملنے والے کو سلام کہنے، بلانے والے کی دعوت قبول کرنے اور جنازے کے ساتھ جنازے کا حکم دیا۔ اور سونے کی انگوٹھی پہننے سے، چاندی کے برتن (میں کھانے پینے) سے، سرخ ریشمی گدیلوں، قس بستی کے بتے ہوئے ریشمی کپڑے اور موٹے یا باریک ہر قسم کے ریشم کے استعمال سے منع فرمایا ہے۔","f2":"’’اتباع‘‘ جنازے کے ساتھ نکلنے کے دو درجے ہیں: جب گھر سے جنازہ اٹھایا جائے تو اس کے پیچھے پیچھے رہے یہاں تک کہ نماز جنازہ سے فارغ ہو۔ گھر سے میت کے ساتھ نکلے، یعنی اس کی پیروی کرے یہاں تک کہ نماز جنازہ اور تدفین سے فراغت ہو، یہ دونوں عمل درست اور جائز ہیں لیکن دوسرا درجہ قابل فضیلت اور زیادہ ثواب کا حامل ہے کیونکہ اس صورت میں دو قیراط کے بقدر ثواب ملے گا۔ رسول اللہ صلی اللہ علیہ وسلم سے دونوں قسم کے عمل منقول ہیں۔ بہرحال راستے میں ملنے یا سیدھا قبرستان پہنچنے کی نسبت زیادہ ثواب کا حامل اور مسنون عمل یہ ہے کہ جہاں سے میت اٹھائی جائے وہاں سے چلنے کا اہتمام کیا جائے، احادیث میں بظاہر قیراط یا دو قیراط کا ثواب اسی قسم کی قیود کے ساتھ مشروط ہے جیسا کہ بخاری و مسلم وغیرہ کی احادیث میں بصراحت ذکر ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا [من خرج مع جنازۃ من بیتھا] ’’جو گھر سے جنازے کے ساتھ نکلا۔‘‘ تفصیل کے لیے ملاحظہ فرمائیں: (أحکام الجنائز للألبانی، ص۸۸)"}],[1940,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص جنازے کے ساتھ گیا، اور اس کے ساتھ رہا یہاں تک کہ اس پر جنازہ کی نماز پڑھی گئی اس کے لیے ایک قیراط کا ثواب ہے، اور جو شخص کسی جنازے کے ساتھ گیا، اور اس کے ساتھ رہا یہاں تک وہ دفن کر دیا گیا، تو اس کے لیے دو قیراط کا ثواب ہے، اور ایک قیراط احد (پہاڑ) کے مثل ہے\"۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہا سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص جنازے کے ساتھ جائے حتی کہ اس کا جنازہ پڑھا جائے تو اسے ایک قیراط ثواب ملے گا، اور جو شخص جنازے کے ساتھ جائے حتی کہ اسے دفن کیا جائے تو اسے دو قیراط ثواب ملے گا، اور قیراط احد پہاڑ کے برابر ہے۔‘‘","f2":"یہاں قیراط کی تخصیص کی ضرورت، اس لیے پڑی کہ مشہور وزن ’’قیراط‘‘ تو انتہائی معمولی ہوتا ہے۔"}],[1941,"عبداللہ بن مغفل رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص کسی جنازے کے ساتھ جائے، اور اس کے ساتھ رہے یہاں تک کہ اس سے فارغ ہو لیا جائے، تو اس کے لیے دو قیراط کا ثواب ہے، اور اگر لوٹ آئے قبل اس کے کہ اس سے فارغ ہوا جائے، تو اس کے لیے ایک قیراط کا ثواب ہے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن مغفل رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو آدمی جنازے کے ساتھ جائے اور (دفن سے) فراغت تک ساتھ رہے تو اسے دو قیراط ثواب ملے گا۔ اور جو شخص فراغت سے پہلے واسآ جائے تو اسے ایک قیراط ملے گا۔‘‘"}],[1942,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سوار جنازے کے پیچھے رہے، پیدل چلنے والا جہاں چاہے رہے، اور بچوں پہ نماز جنازہ پڑھی جائے گی\"۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سوار شخص جنازے کے پیچھے چلے اور پیدل چلنے والا جہاں چاہے چلے (آگے یا پیچھے یا برابر) اور بچے کا بھی جنازہ پڑھا جائے۔‘‘","f2":"(۱) سواری کی صورت میں جنازے کے آگے چلنے سے روکا ہے کیونکہ وہ جنازے کے لیے رکاوٹ بن سکتا ہے، مثلاً: جانور اڑ جائے، انجن بند ہو جائے وغیرہ۔ بنا بریں معلوم ہوا کہ جنازے کے ساتھ سوار ہوکر جانا جائز ہے، البتہ جنازے سے پیچھے رہنا چاہیے۔ (۲) ’’بچے کا جنازہ‘‘ امام احمد بن حنبل رحمہ اللہ نے اسے عام سمجھا ہے، خواہ بچہ زندہ پیدا ہو یا مردہ کیونکہ میت بھی تو پہلے زندہ ہی تھا الا یہ کہ مدت حمل چار ماہ سے کم ہو کیونکہ اس صورت میں وہ مکمل انسانی صورت میں نہ ہوگا اور اس میں روح نہیں پھونکی گئی ہوگی۔ جمہور اہل علم اس بچے کے جنازے کے قائل ہیں جو زندہ پیدا ہو، بعد میں مرے، خواہ اس میں زندگی کی کوئی بھی علامت پائی گئی ہو۔ لیکن امام احمد رحمہ اللہ وغیرہ کا موقف راجح ہے کیونکہ حدیث میں [السقط یصلی علیہ] کے الفاظ بھی آتے ہیں جیسا کہ سنن ابی داود (الجنائز، حدیث: ۳۱۸۰) میں ہے۔ یہ حدیث عام ہے۔ ناقص یا ناتمام پیدا ہونے والا بچہ چیخے، یعنی بوقت ولادت اس کے اندر زندگی کے آثار ہوں یا مردہ ہی ہو بشرطیکہ یہ نفخ روح کی مدت کے بعد ہو، تو اس کی نماز جنازہ پڑھنا جائز اور مشروع ہے۔ مزید دیکھیے: فوائد سنن ابی داود، حدیث: ۳۱۸۰۔"}],[1943,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سوار جنازے کے پیچھے رہے، پیدل چلنے والا (آگے پیچھے دائیں بائیں) جہاں چاہے رہے، اور بچوں پہ نماز جنازہ پڑھی جائے گی\"۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سوار جنازے کے پیچھے چلے اور پیدل جہاں چاہے چلے اور نومولود بچے کا جنازہ پڑھا جائے گا۔‘‘"}],[1944,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو اور ابوبکر و عمر رضی اللہ عنہما کو جنازے کے آگے دیکھا ہے۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت سالم کے والد محترم حضرت ابن عمر رضی اللہ عنہما سے منقول ہے کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم اور ابوبکر و عمر رضی اللہ عنہما کو جنازے کے آگے چلتے دیکھا ہے۔"}],[1945,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم، ابوبکر، عمر اور عثمان رضی اللہ عنہم کو جنازے کے آگے (پیدل) چلتے دیکھا ہے۔ صرف راوی بکر نے عثمان رضی اللہ عنہ کا ذکر نہیں کیا ہے۔ نسائی کہتے ہیں: اس حدیث کا موصول ہونا غلط ہے، اور درست مرسل ہونا ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما نے بیان فرمایا کہ انھوں نے نبی اور ابوبکر و عمر و عثمان رضی اللہ عنہم کو جنازے کے آگے آگے چلتے دیکھا ہے۔ روایت کے راویوں میں سے اکیلے بکر راوی نے حضرت عثمان رضی اللہ عنہ کا ذکر نہیں کیا۔روایت کے راویوں میں سے اکیلے بکر راوی نے حضرت عثمان رضی اللہ کا عنہ کا ذکر نہیں کیاامام ابو عبدالرحمٰن (نسائی) رحمہ اللہ نے کہا ہے کہ یہ روایت (موصول) غلط ہے اور مرسل صحیح ہے۔","f2":"احناف جنازے کے آگے چلنا درست نہیں سمجھتے۔ ان کی دلیل یہ حدیث ہے: [الجنازۃ متبوعۃ ولا تتبع لیس معھا من تقدمھا] اول تو یہ روایت ہی ضعیف ہے کیونکہ اس کی سند میں ابو ماجدہ ہے۔ امام ابوداود رحمہ اللہ نے اسے غیر معروف کہا ہے۔ (سنن أبي داود، حدیث: ۳۱۸۴) اور امام دارقطنی نے اسے مجہول کہا ہے۔ (ھدایۃ الرواۃ للألباني، حدیث: ۱۶۱۲) بالفرض اگر یہ صحیح بھی ہو تو اس کا مطلب یہ ہے کہ جنازے کے ساتھ جائیں تاکہ جنازہ اٹھانے میں ضرورت پڑے تو تعاون کرسکیں۔ جنازے سے پہلے علیحدہ ہی قبرستان نہ چلے جائیں ورنہ جنازے کے ساتھ جانے کا ثواب نہ ملے گا۔"}],[1946,"عمران بن حصین رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارا بھائی مر گیا ہے، اٹھو اس کی نماز جنازہ پڑھو\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے روایت ہے کہ (جب نجاشی رحمہ اللہ فوت ہوئے تو) رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمھارا (اسلامی) بھائی (حبشہ میں) فوت ہوگیا ہے، لہٰذا اٹھو اور اس کی نماز جنازہ پڑھو۔‘‘","f2":"امام صاحب کا مقصد یہ ہے کہ جنازہ پڑھنا فرض کفایہ ہے، یعنی ہر (مسلم) میت کا جنازہ ضرور ہونا چاہیے، تھوڑے لوگ پڑھیں یا زیادہ، ورنہ سب گناہ گار ہوں گے۔ اس حدیث سے بالتبع جنازۂ غائبانہ بھی ثابت ہوتا ہے، امام شافعی اور امام احمد رحمہ اللہ اس کے قائل ہیں جبکہ حنفی اور مالکی اس کے قائل نہیں۔ صحیح بات یہ ہے کہ غائبانہ نمازِ جنازہ پڑھنا جائز ہے اور مذکوورہ حدیث اس کی دلیل ہے۔"}],[1947,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ انصار کے بچوں میں سے ایک بچہ رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا، تو آپ نے اس کی جنازے کی نماز پڑھی، میں نے کہا: (یہ) خوش بخت جنت کی چڑیوں میں سے ایک چڑیا ہے، نہ تو اس نے کوئی برا کام کیا، اور نہ اس عمر رضی اللہ عنہ کو پہنچا، آپ صلی اللہ علیہ وسلم نے فرمایا: \"یا عائشہ! اس کے علاوہ کچھ اور معاملہ ہے اللہ تعالی نے جنت کی تخلیق فرمائی، اور اس کے لیے لوگ پیدا کئے، جبکہ اپنے باپوں کی پشت میں تھے، اور (اللہ) نے جہنم کی تخلیق کی، اور اس کے لیے لوگ پیدا کیے جبکہ وہ اپنے باپوں کی پشت میں تھے\" ۱؎۔\n§وضاحت\n۱؎: اور وہ توقف ہے، لیکن یہ پہلے کی بات ہے، بعد میں آپ نے یہ بتایا کہ مسلمانوں کے نابالغ بچے جنت میں جائیں گے، البتہ کفار و مشرکین کے بچوں کی بابت جمہور کا موقف یہی ہے کہ ان کے بارے میں توقف اختیار کیا جائے، دیکھئیے حدیث رقم: ۱۹۵۱، ۱۹۵۳۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ انصار کے بچوں میں سے ایک بچے کی میت رسول اللہ صلی اللہ علیہ وسلم کے پاس لائی گئی تو آپ نے اس کا جنازہ پڑھا۔ میں نے کہا: اسے مبارک ہو یہ تو جنت کی چڑیوں میں سے ایک چڑیا ہے۔ اس نے کوئی برائی کی نہ برائی کی عمر قائی۔ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’اے عائشہ! کیا پتہ کوئی اور بات ہو جائے؟ اللہ تعالیٰ نے جنت بنائی تو اس میں جانے والے بھی بنا دیے اور انھیں باپوں کی پشتوں میں پیدا کیا۔ اسی طرح آگ بنائی تو اس میں جانے والے بھی بنائے اور انھیں اپنے باپوں کی پشتوں میں پیدا کیا۔‘‘","f2":"(۱) اگر بچہ بلوغت سے پہلے بے گناہ ہوتا ہے مگر جنازہ مسلم میت کی سنت ہے، نیز بخشش اور دعائے رحمت بچے کے والدین کے لیے ہوگی، اس لیے بچے کا جنازہ بھی پڑھا جائے گا۔ (۲) اس حدیث سے معلوم ہوتا ہے کہ جنت یا جہنم میں جانے والوں کا قطعی علم اللہ تعالیٰ کے پاس ہے، کسی فرد واحد کو قطعیت کے ساتھ جنتی یا جہنمی نہیں کہا جا سکتا (جب تک وحی نہ آئے) خواہ وہ نابالغ بچہ ہی ہو، البتہ عمومی حکم یہی ہے کہ مسلمانوں کے بچے (بلوغت سے پہلے فوت ہونے والے) جنات میں جائیں گے۔ ایک دوسری تطبیق اس طرح ہوسکتی ہے کہ یہ اس وقت کی بات ہے جب بچوں کے بارے میں کوئی خصوصی حکم نازل نہیں ہوا تھا بعد میں بتا دیا گیا کہ مسلمانوں کے بچے جنت میں جائیں گے۔ کفار کے بچوں کے بارے میں اختلاف ہے۔\nبعض اہل علم کا موقف یہ ہے کہ جب کفار کے بچے سن تمیز سے پہلے فوت ہو جائیں اور ان کے والد کافر ہوں تو دنیا میں ان کا حکم کافروں کا ہوگا کہ نہ انھیں غسل دیا جائے گا نہ کفن دیا جائے گا نہ جنازہ پڑھا جائے گا اور نہ انھیںمسلمانوں کے ساتھ دفن کیا جائے گا کیونکہ وہ اپنے والدین کے ساتھ کافر ہی ہیں باقی رہا آخرت میں ان کا حال تو یہ اللہ تعالیٰ بہتر جانتا ہے کہ اگر وہ بڑے ہوتے تو دنیا میں کس طرح کے عمل کرتے؟ صحیح حدیث میں ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے جب مشرکوں کے بچوں کے بارے میں دریافت کیا گیا تو آپ نے فرمایا: ’’اللہ تعالیٰ زیادہ بہتر جانتا ہے کہ وہ کیا عمل کرنے والے تھے؟‘‘ (صحیح البخاري، القدر، حدیث: ۶۵۹۷) نیز بعض اہل علم کا ایک قول یہ بھی ہے کہ ان کے بارے میں اللہ تعالیٰ کا علم قیامت کے دن ظاہر ہوگا اور ان کا بھی اہل فترت کی طرح امتحان ہوگا اگر انھوں نے اللہ تعالیٰ کے حکم کی فرمانبرداری کی تو جنت میں داخل ہوں گے اور اگر نافرمانی کی تو جہنم رسید ہوں گے۔ صحیح احادیث سے ثابت ہے کہ اہل فترت کا قیامت کے دن امتحان ہوگا۔ اہل فترت سے مراد وہ لوگ ہیں جن کے پاس انبیاء کی دعوت نہیں پہنچی ہوگی۔ اسی طرح جو لوگ ان کے حکم میں ہوں گے، مثلاً: کفار اور مشرکین کے بچے، ان کا بھی امتحان ہوگا کیونکہ ارشاد باری تعالیٰ ہے: (وما کنا معذبین حتی نبعث رسولا) (بنی اسرآئیل ۱۵:۱۷) ’’اہل فترت کے بار میں سب سے زیادہ صحیح قول یہی ہے۔ شیخ الاسلام ابن تیمیہ، امام ابن قیم، فضیلۃ الشیخ ابن باز اور فضیلۃ الشیخ محمد بن صالح التثیمین رحمہم اللہ نے اسی کو اختیار کیا ہے جبکہ بعض اہل علم کے بقول وہ جنت میں جائیں گے کیونکہ وہ بے گناہ ہیں۔ مزید تفصیل کے لیے دیکھیے: (فتاویٰ ابن تیمیہ: ۳۷۲/۲۴، ۲۷۳، و ذخیرۃ العقبی شرح سنن النسائي: ۱۹۳/۱۹- ۱۹۶) (۳) جنت اور جہنم کا وجود ہے۔"}],[1948,"مغیرہ بن شعبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"سوار جنازے کے پیچھے رہے، پیدل چلنے والا اس کے (آگے پیچھے دائیں بائیں) جس طرف چاہے رہے، اور شیرخوار بچہ کی نماز جنازہ پڑھی جائے گی\"۔","الألباني: صحيح",{"u2":"حضرت مغیرہ بن شعبہ نے ذککر کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سوار جنازے کے پیچھے چلے، پیدل جہاں چاہے چلے اور نومولود کا جنازہ پڑھا جائے گا۔‘‘","f2":"تفصیل کے لیے دیکھیے، احادیث: ۱۹۴۴ و ۱۹۴۷۔"}],[1949,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکوں کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"جو کچھ وہ کرنے والے تھے اللہ تعالی اسے خوب جانتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا (کہ وہ کہاں جائے گی؟) تو آپ نے فرمایا: ’’اللہ ہی خوب جانتا ہے کہ انھوں نے کیا کام کرنے تھے۔‘‘","f2":"گویا اللہ تعالیٰ اپنے علم کے مطابق فیصلہ فرمائے گا۔ اس قسم کی احادیث کے پیش نظر بعض علماء اس مسئلے میں سکوت اور توقف کے قائل ہیں۔"}],[1950,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے پوچھا گیا تو آپ نے فرمایا: \"اللہ تعالی جو وہ کرنے والے تھے اسے خوب جانتا ہے\" ۱؎۔\n§وضاحت\n۱؎: وہ اپنے اسی علم کی بنیاد پر ان کے بارے میں فیصلہ فرمائے گا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’اللہ تعالیٰ خوب جانتا ہے کہ وہ کیا کرنے والے تھے۔‘‘"}],[1951,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"انہیں اللہ تعالی نے پیدا کیا(اور) جس وقت انہیں پیدا کیا وہ جانتا تھا (کہ آئندہ) وہ کیا کرنے والے ہیں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’جب اللہ تعالیٰ نے انھیں پیدا فرمایا تو اللہ تعالیٰ خوب جانتا تھا کہ وہ کیا کرنے والے تھے۔‘‘"}],[1952,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: \"اللہ تعالی اسے خوب جانتا ہے جو وہ کرنے والے تھے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ نبی صلی اللہ علیہ وسلم سے مشرکین کی اولاد کے بارے میں پوچھا گیا تو آپ نے فرمایا: ’’اللہ تعالیٰ ہی خوب جانتا ہے کہ (اگر وہ بلوغت کو پاتے) وہ کیا کرنے والے تھے؟‘‘"}],[1953,"شداد بن ہاد رضی اللہ عنہ سے روایت ہے کہ ایک بادیہ نشین نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ پر ایمان لے آیا، اور آپ کے ساتھ ہو گیا، پھر اس نے عرض کیا: میں آپ کے ساتھ ہجرت کروں گا، نبی اکرم صلی اللہ علیہ وسلم نے اپنے بعض اصحاب کو اس کا خیال رکھنے کی وصیت کی، جب ایک غزوہ ہوا تو نبی اکرم صلی اللہ علیہ وسلم مال غنیمت میں کچھ لونڈیاں ملیں، تو آپ نے انہیں تقسیم کیا، اور اس کا (بھی) حصہ لگایا، چنانچہ اس کا حصہ اپنے ان اصحاب کو دے دیا جن کے سپرد اسے کیا گیا تھا، وہ ان کی سواریاں چراتا تھا، جب وہ آیا تو انہوں نے (اس کا حصہ) اس کے حوالے کیا، اس نے پوچھا: یہ کیا ہے؟ تو انہوں نے کہا: یہ حصہ نبی اکرم صلی اللہ علیہ وسلم نے تمہارے لیے لگایا تھا، تو اس نے اسے لے لیا، (اور) نبی اکرم صلی اللہ علیہ وسلم کے پاس لے کر آیا، اور عرض کیا: (اللہ کے رسول!) یہ کیا ہے؟ آپ نے فرمایا: \"میں نے تمہارا حصہ دیا ہے\"، تو اس نے کہا: میں نے اس (حقیر بدلے) کے لیے آپ کی پیروی نہیں کی ہے، بلکہ میں نے اس بات پر آپ کی پیروی کی ہے کہ میں تیر سے یہاں مارا جاؤں، (اس نے اپنے حلق کی طرف اشارہ کیا) پھر میں مروں اور جنت میں داخل ہو جاؤں، تو آپ نے فرمایا: \"اگر تم سچے ہو تو اللہ تعالی بھی اپنا وعدہ سچ کر دکھائے گا\"، پھر وہ لوگ تھوڑی دیر ٹھہرے رہے، پھر دشمنوں سے لڑنے کے لیے اٹھے، تو انہیں (کچھ دیر کے بعد) نبی اکرم صلی اللہ علیہ وسلم کے پاس اٹھا کر لایا گیا، اور انہیں ایسی جگہ تیر لگا تھا جہاں انہوں نے اشارہ کیا تھا، نبی اکرم صلی اللہ علیہ وسلم نے پوچھا: \"کیا یہ وہی شخص ہے؟\" لوگوں نے جواب دیا: جی ہاں، آپ نے فرمایا: \"اس نے اللہ تعالی سے اپنا وعدہ سچ کر دکھایا تو (اللہ تعالی) نے (بھی) اپنا وعدہ اسے سچ کر دکھایا\" ۱؎ پھر نبی اکرم صلی اللہ علیہ وسلم نے اپنے جبّے(قمیص) میں اسے کفنایا، پھر اسے اپنے سامنے رکھا، اور اس کی جنازے کی نماز پڑھی ۲؎ آپ کی نماز میں سے جو چیز لوگوں کو سنائی دی وہ یہ دعا تھی: «اللہم هذا عبدك خرج مهاجرا في سبيلك فقتل شهيدا أنا شهيد على ذلك» \"اے اللہ! یہ تیرا بندہ ہے، یہ تیری راہ میں ہجرت کر کے نکلا، اور شہید ہو گیا، میں اس بات پر گواہ ہوں\"۔\n§وضاحت\n۱؎: یعنی اس کی مراد پوری کر دی۔ ۲؎: اس سے ثابت ہوتا ہے کہ شہداء پر نماز جنازہ پڑھی جائے۔","الألباني: صحيح",{"u2":"حضرت شداد بن ہاد سے روایت ہے کہ ایک اعرابی نبی صلی اللہ علیہ وسلم کے پاس آیا اور آپ پر ایمان لے آیا اور پ کا متبع بن گیا، پھر وہ کہنے لگا: میں تو آپ کے ساتھ مہاجر بن کر رہوں گا۔ نبی صلی اللہ علیہ وسلم نے اپنے ایک صحابی کو اس (کے پیام و طعام) کے خیال رکھنے کو کہا، پھر ایک جنگ ہوئی تو نبی صلی اللہ علیہ وسلم کو غنیمت میں قیدی ملے۔ آپ نے انھیں تقسیم کیا تو اس اعرابی کا حصہ بھی رکھا او ر اس کے ساتھیوں کو دے دیا۔ وہ ان کے سواری کے اونٹ چرایا کرتا تھا۔ جب وہ چرا کر واپس آیا تو انھوں نے اس کا حصہ اسے دیا۔ اس نے کہا: یہ کیا ہے؟ ساتھیوں نے کہا: نبی صلی اللہ علیہ وسلم نے تجھے (غنیمت سے) حصہ دیا ہے۔ اس نے اپنا حصہ لیا اور اسے لے کر نبی صلی اللہ علیہ وسلم کے پاس حاضر ہوا اور کہنے لگا: یہ کیا ہے؟ آپ نے فرمایا: ’’میں نے تجھے تیرا حصہ دیا ہے۔‘‘ وہ کہنے لگا: میں اس کی خاطر تو آپ کا پیروکار نہیں بنا تھا میں تو پ کا پیروکار، اس لیے بنا ہوں کہ مجھے یہاں تیر لگے، اور اس نے اپنے حلق کی طرف اشارہ کیا، اور میں مر کر جنت میں داخل ہو جاؤں۔ آپ نے فرمایا: ’’اگر تو یہ بات سچے دل سے کہتا ہے تو اللہ تعالیٰ تیری خواہش پوری فرمائے گا۔‘‘ تھوڑے عرصے کے بعد وہ (صحابہ) پھر دشمن سے لڑائی کے لیے گئے تو اسے نبی صلی اللہ علیہ وسلم کے پاس اس حال میں اٹھا کر لایا گیا کہ اسے اسی جگہ تیر لگا ہوا تھا جہاں اس نے اشارہ کیا تھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’کیا یہ وہی اعرابی ہے؟‘‘ لوگوں نے کہاا: جی ہاں، آپ نے فرمایا: ’’اس نے سچے دل سے اللہ تعالیٰ سے دعا کی تھی، اللہ تعالیٰ نے اس کی خواہش پوری فرما دی۔‘‘ پھر نبی صلی اللہ علیہ وسلم نے اسے اپنی قمیص میں کفن دیا، پھر اسے آگے رکھا اور اس پر نماز پڑھی۔ آپ کی دعا کے یہ الفاظ ظاہر ہوئے: ’’اے اللہ! یہ تیرا (سچا) بندہ ہے۔ تیرے راستے میں ہجرت کرتے ہوئے گھر سے نکلا اور شہید ہوگیا۔ میں ان باتوں کا عینی گواہ ہوں۔‘‘","f2":"(۱) زہے قسمت! کیا بلند مرتبہ ملا اس اعرابی کو کہ رسول اللہ صلی اللہ علیہ وسلم ان زوردار الفاظ سے اس کے حق میں گواہی دے رہے ہیں۔ رضی اللہ عنہ ہ ہر مدعی کے واسطے دارور سن کہاں؟ (۲) ’’نماز پڑھی‘‘ بعض اہل علم نے اس کے بجائے دعا کرنے کے معنی کیے ہیں کیونکہ یہاں صف بندی کا ذکر ہے نہ تکبیروں کا، صرف دعا کا ذکر ہے، لہٰذا ان کے نزدیک یہی معنی مناسب ہیں تاکہ ان صحیح ترین احادیث کی موافقت ہو جائے جن میں شہدائے احد کے جنازہ نہ پڑھنے کا ذکر ہے جبکہ اس حدیث میں مذکورہ اعمال کے عدم ذکر سے یہ لازم نہیں تھا کہ سرے سے ان امور کا وقوع ہی نہیں ہوا بلکہ یہ اختصار کے پیش نظر بھی ہوسکتا ہے۔ بعض نے اس روایت سے شہید کے جنازے پر استدلال کیا ہے۔ اگر ترجیح دی جائے تو ترجیح اصح روایات ہی کو ہے جن میں جنازہ نہ پڑھنے کا ذکر ہے۔ تطبیق دی جائے تو اس روایت میں دعا کے معنی کرلیے جائیں۔ یا امام احمد رحمہ اللہ کے مطابق کہا جائے کہ شہید کا جنازہ پڑھ سکتے ہیں، ضروری نہیں۔ یہی موقف درست اور اقرب الی الصواب ہے۔ حدیث کے ظاہر کا تقاضا بھی یہی ہے۔ باقی سب احتمالات ہیں، نیز غزوۂ احد کے شہداء پر ترک جنازہ سے یہ لازم نہیں آتا کہ شہداء کی نماز جنازہ درست نہیں، نہ اس سے یہ لازم آتا ہے کہ کسی اور شہید کی نماز جنازہ بھی نہ پڑھی جائے یا آپ علیہ الصلوۃ والسلام نے نہ پڑھی ہو، دونوں طرح جائز ہے، پڑھنا نہ پڑھنا بھی، لیکن چونکہ یہ دعا ہے اور بخشش اور رفع درجات کا ایک ذریعہ ہے جس کا ہر مسلمان، خواہ کتنے ہی بڑے درجے پر فائز کیوں نہ ہو، محتاج رہتا ہے، اس لیے شہید کی نماز جنازہ بجائے ترک کے پڑھ لینا اولی اور افضل ہے۔ واللہ أعلم۔ (۲) نبیٔ اکرم صلی اللہ علیہ وسلم اپنے صحابہ خاص کر غرباء کا بہت زیادہ خیال رکھتے تھے۔ (۳) شہید کو غسل نہیں دیا جائے گا۔ (۵) شہید کو کفن پہنایا جائے گا۔"}],[1954,"عقبہ رضی اللہ عنہ سے روایت ہے کہ ایک دن رسول اللہ صلی اللہ علیہ وسلم (مدینہ سے باہر) نکلے، اور غزوہ احد کے شہیدوں پر نماز (جنازہ) پڑھی ۱؎ جیسے میت کی نماز جنازہ پڑھتے تھے، پھر منبر کی طرف پلٹے اور فرمایا: \"میں (قیامت میں) تمہارا پیش رو ہوں، اور تم پر گواہ (بھی) ہوں\"۔\n§وضاحت\n۱؎: یہ نماز آپ نے جنگ احد کے آٹھ سال بعد آخری عمر میں پڑھی تھی، اور یہ شہداء احد ہی کے ساتھ خاص تھی۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم ایک دن (اپنی زندگی کے آخری دنوں میں) احد کی طرف گئے اور احد کے شہداء کے لیے اس طرح (آہ و زاری سے) دعائیں کیں جس طرح میت کے لیے کرتے تھے، پھر واپس آکر منبر پر چڑھے اور فرمایا: ’’میں تمھارا پیش رو ہوں۔ (تمھارا میر سامان ہوں) اور میں تمھارے حق میں (ایمان و نصرت کی) گواہی دوں گا۔‘‘","f2":"(۱) بعض اہل علم نے ترجمہ یوں بھی کیا ہے، ’’آپ نے احد والوں کا جنازہ پڑھا جیسے میت کا پڑھتے ہیں‘‘ مگر یہ معنی محل نظر ہیں۔ اولاً: اس لیے کہ یہ واقعہ ان کی شہادت سے آٹھویں سال کا ہے۔ دفن کے موقع پر جنازہ نہ پڑھنا، سات سال تک نہ پڑھنا پھر آٹھویں سال پڑھنا تعجب کی بات ہے، نیز کوئی بھی آٹھویں سال جنازے کے جواز کا قائل نہیں حتی کہ احناف جو اس روایت سے شہید کے جنازے پر استدلال کرتے ہیں، وہ بھی اتنی دیر بعد جنازے کے قائل نہیں، لہٰذا اس روایت سے شہید کی نماز جنازہ کا استدلال واضح نہیں۔ ثانیاً: اگر پ نے جنازہ پڑھا تھا تو یہ کہنے کی کیا ضرورت تھی ’’جیسے میت کا پڑھتے تھے‘‘ جنازے میں تو صورت ہی ایک ہے۔ کیا میت کے علاوہ بھی جنازہ ہوتا ہے؟ لہٰذا صحیح یہ معلوم ہوتا ہے کہ آپ نے بہت الحاح اور اگر یہ زاری سے دعائیں کیں، گویا کہ جنازہ پڑھ رہے ہیں۔ اس معنی میں کوئی اشکال بھی نہیں اور روایات میں تعارض بھی پیدا نہیں ہوتا۔ واللہ أعلم۔ (۲) ’’پیش رو‘‘ اس میں اپنے مقام عظیم کی طرف اشارہ ہے۔ ’’پیش رو‘‘ سے مراد ہے جو قافلے سے آگے آگے انتظامات کرنے، مثلاً: رہائش، پانی اور دیگر ضروریات پر مقرر ہوتا ہے۔ (۳) ’’گواہی‘‘ اللہ تعالیٰ ہر بات سے بذات خود واقف ہے مگر صحابہ کی تعظیم و تشریف کے لیے رسول اللہ صلی اللہ علیہ وسلم سے ان کے حق میں گواہی لی جائے گی جسے سب امتیں سنیں گی رضی اللہ عنہم اجمعین (۴) اس امت کی فضیلت ظاہر ہوتی ہے کہ ان کا نبی حوض کوثر پر ان کا انتظار کر رہا ہوگا۔ یہ اس امت کے لیے ایک بہت بڑی بشارت ہے۔"}],[1955,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم غزوہ احد کے مقتولین میں سے میں سے دو آدمیوں کو ایک کپڑے میں اکٹھا کرتے، پھر پوچھتے:\"ان دونوں میں کس کو قرآن زیادہ یاد تھا؟\" جب لوگ ان دونوں میں سے ایک کی طرف اشارہ کرتے تو آپ اسے قبر میں پہلے رکھتے، اور فرماتے: \"میں ان پر گواہ ہوں\"، آپ نے انہیں ان کے خون سمیت دفن کرنے کا حکم دیا، اور نہ ان کی نماز جنازہ پڑھی گئی ۱؎ اور نہ انہیں غسل دیا گیا۔\n§وضاحت\n۱؎: جو لوگ شہید کی نماز جنازہ پڑھی جانے کے قائل ہیں، وہ اس روایت کی یہ توجیہ کرتے ہیں کہ اس کا مطلب یہ ہے کہ آپ نے ان میں کسی پر اس طرح نماز نہیں پڑھی جیسے حمزہ رضی اللہ عنہ پر کئی بار پڑھی تھی۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما نے بتایا کہ رسول اللہ صلی اللہ علیہ وسلم (کپڑوں کی کمی کی وجہ سے) شہدائے احد میں سے دو دو اشخاص کو ایک ایک کپڑے میں اکٹھا رکھتے تھے، پھر فرماتے: ’’ان میں سے کس کو قرآن زیادہ یاد ہے؟‘‘ جب ان میں سے کسی ایک کی طرف اشارہ کیا جاتا تو آپ اسے لحد میں (قبلے کی طرف) آگے رکھتے۔ اور پ نے فرمایا: ’’میں ان کے حق میں گواہی دوں گا۔‘‘ اور آپ نے ان کو (کپڑوں اور جسموں پر) خون سمیت دفن کرنے کا حکم دیا۔ نہ ان کا جنازہ پڑھا اور نہ انھیں غسل دیا۔","f2":"(۱) ’’آگے رکھتے‘‘ تاکہ اس کی فضیلت ظاہر ہو۔ (۲) ’’خون سمیت‘‘ تاکہ ان کی مظلومیت قائم رہے اور قیامت کے دن ان کی فضیلت ظاہر ہو کیونکہ جس حال میں کوئی دفن ہوگا اسی حال میں قیامت کے دن اٹھایا جائے گا۔ (۳) شہید کو غسل اور جنازے کے بغیر دفن کرنا اس کی امتیازی شان ہے۔ شہید کے جنازے کی بحث سابقہ حدیث میں گزر چکی ہے۔"}],[1956,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ قبیلہ اسلم کے ایک شخص نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر زنا کا اعتراف کیا، تو آپ نے اس کی طرف سے(اپنا منہ) پھیر لیا، اس نے دوبارہ اعتراف کیا تو آپ نے (پھر) اپنا منہ پھیر لیا، اس نے پھر تیسری دفعہ اعتراف کیا، تو آپ نے (پھر) اپنا منہ پھیر لیا، یہاں تک کہ اس نے اپنے خلاف چار مرتبہ گواہیاں دیں، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"کیا تجھے جنون ہے؟\" اس نے کہا: نہیں، آپ نے پوچھا: \"کیا تو شادی شدہ ہے؟\"اس نے کہا: ہاں، تو نبی اکرم صلی اللہ علیہ وسلم نے حکم دیا تو اس کو رجم کر دیا گیا، جب اسے پتھر لگا تو بھاگ کھڑا ہوا، پھر وہ پکڑا گیا تو پتھروں سے مارا گیا، تو اور مر گیا، نبی اکرم صلی اللہ علیہ وسلم نے اس کے حق میں اچھی بات کہی، اور اس کی نماز جنازہ نہیں پڑھی ۱؎۔\n§وضاحت\n۱؎: رجم کئے جانے والے پر نماز جنازہ پڑھنے نہ پڑھنے کی بابت روایات مختلف ہیں، صحیح بات یہ ہے کہ رجم کے دن نہیں پڑھی دوسرے دن پڑھی، جیسا کہ سنن ابو قرہ میں ہے، نیز امام وقت کو یہ اختیار ہے، جس کے حالات جیسے ہوں اسی کے حساب پڑھے یا نہ پڑھے، ماعز اور غامدیہ رضی اللہ عنہما نے سچی توبہ کی تھی، تو ان کی نماز جنازہ پڑھی، اور جو بغیر توبہ کے گواہی کی وجہ سے رجم کیا جائے اس پر نہ پڑھنا ہی بہتر ہے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ بنو اسلم (قبیلے) کا ایک شخص نبی صلی اللہ علیہ وسلم کے پاس آیا اور اس نے زنا کرنے کا اعتراف کیا۔ آپ نے اس سے منہ موڑ لیا۔ اس نے پھر اعتراف کیا۔ آپ نے پھر منہ موڑ لیا۔ اس نے پھر اعتراف کیا۔ آپ نے پھر منہ موڑ لیا حتی کہ اس نے اپنے خلاف چار دفعہ گواہی دی (کہ میں نے زنا کیا ہے) تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تجھے جنون تو نہیں؟‘‘ اس نے کہا: نہیں۔ آپ نے فرمایا: ’’تو شادی شدہ ہے؟‘‘ اس نے کہا: جی ہاں۔ آپ نے اسے جم کرنے کا حکم دیا۔ اسے رجم کیا جانے لگا لیکن جب اسے پتھروں نے تکلیف پہنچائی تو وہ بھاگ اٹھا، مگر اسے پکڑ لیا گیا اور پتھر مارے گئے حتی کہ وہ مر گیا۔ نبی صلی اللہ علیہ وسلم نے اس کے بارے میں تعریفی کلمات فرمائے لیکن اس کا جنازہ نہیں پڑھا۔","f2":"(۱) یہ شخص حضرت ماعز اسلمی رضی اللہ عنہ تھے۔ (۲) ’’منہ موڑ لیا‘‘ اس میں اشارہ ہے کہ گناہ ہو جائے اور گواہ نہ ہوں تو اعتراف کے بجائے اللہ تعالیٰ سے معافی مانگ لی جائے اور توبہ کر لی جائے، توبہ بھی گناہ کو مٹا دیتی ہے، البتہ اگر وہ شخص قاضی کے سامنے زنا کا اعتراف کرلے یا اسے چار آدمی عین حالت زنا میں دیکھ لیں تو اس پر حد نافذ ہوگی۔ (۳) ’’جنون تو نہیں؟‘‘ معلوم ہوا مجنون پر حد نہیں ہے۔ (۴) ’’شادی شدہ ہے؟‘‘ شادی شدہ نہ ہو تو سزا کوڑے ہیں، رجم نہیں۔ (۵) ’’تعریفی کلمات کہے‘‘ کیونکہ اس نے سچی توبہ کرلی حتی کہ جان قربان کر دی۔ (۶) ’’جنازہ نہیں پڑھا‘‘ مگر دیگر روایات میں ہے کہ آپ نے جنازہ پڑھا۔ (صحیح البخاري، حدیث: ۶۸۲۰) دراصل اس وقت نہیں پڑھا تھا، دوسرے دن پڑھا تھا جیسا کہ حافظ ابن حجر رحمہ اللہ نے ابوقرہ کی سنن کے حوالے سے ذکر کیا ہے۔ تفصیل کے لیے ملاحظہ فرمائیے: (فتح الباري، حدیث: ۶۸۲۰-۱۳۱/۱۲) معلوم ہوا اس قسم کے شخص کا جنازہ پڑھا جائے گا مگر اہتمام کے ساتھ نہیں بلکہ چند لوگوں کے ساتھ پڑھ لیا جائے تاکہ مجرموں کی حوصلہ شکنی ہو اور میت جنازے سے محروم بھی نہ رہے۔ (۷) جب تک پوری طرح بات واضح نہ ہو جائے، حد قائم نہیں کی جائے گی۔ (۸) امام اپنی طرف سے کسی کو حد لگانے کی ذمہ داری سونپ سکتا ہے۔"}],[1957,"عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ قبیلہ جہینہ کی ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی، اور کہنے لگی: میں نے زنا کیا ہے، وہ حاملہ تھی، تو آپ نے اسے اس کے ولی کے سپرد کر دیا اور کہا: \"اسے اچھی طرح رکھو، اور جب بچہ جن دے تو میرے پاس لے کر آنا\"، چنانچہ جب اس نے بچہ جن دیا تو ولی اسے لے کر آیا، تو آپ نے اسے حکم دیا، اس کے کپڑے باندھ دیئے گئے، پھر آپ نے اسے رجم کیا، پھر اس کی نماز جنازہ پڑھی، اس پر عمر رضی اللہ عنہ نے آپ سے عرض کیا: آپ اس کی نماز جنازہ پڑھ رہے ہیں؟ حالانکہ وہ زنا کر چکی ہے، تو آپ نے فرمایا: \"اس نے ایسی توبہ کی ہے کہ اگر وہ اہل مدینہ کے ستر لوگوں کے درمیان تقسیم کر دی جائے تو ان سب کو کافی ہو جائے، اور اس سے بہتر توبہ اور کیا ہو گی کہ اس نے اللہ تعالی (کی شریعت کے پاس و لحاظ میں) اپنی جان (تک) قربان کر دی\"۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے منقول ہے کہ جہینہ (قبیلے) کی ایک عورت رسول اللہ صلی اللہ علیہ وسلم کے پاس آئی اور کہنے لگی: میں نے زنا کیا ہے۔ اور وہ حاملہ بھی تھی، لہٰذا آپ نے اس عورت کو اس کے ولی کے سپرد کر دیا اور فرمایا: ’’اس سے حسن سلوک کرنا۔ جب یہ بچہ جن لے تو اسے میرے پاس لے آنا۔‘‘ جب اس نے بچہ جن لیا تو وہ اسے لے کر آیا۔ آپ نے اس کےرجم کا حکم دیا۔ اس کے کپڑے اچھی طرح کس کر باندھ دیے گئے (تاکہ بے پردگی نہ ہو)، پھر اسے (آپ کے حکم سے) رجم کیا گیا، پھر آپ نے اس کا جنازہ پڑھا۔ حضرت عمر رضی اللہ عنہ نے عرض کیا: آپ اس کا جنازہ پڑھتے ہیں جبکہ اس نے توڑنا کیا ہے؟ آپ نے فرمایا: ’’اللہ کی قسم! اس نے ایسی توبہ کی ہے اگر وہ مدینے والوں میں سے ستر اشخاص پر تقسیم کر دی جائے تو ان سب کو پوری آجائے (ان کی نجات کے لیے کافی ہو) اور اس سے افضل توبہ کیا ہوگی کہ اس نے اللہ تعالیٰ کو راضی کرنے کے لیے اپنی جان قربان کر دی۔‘‘","f2":"(۱) ’’ولی کے سپرد کر دیا‘‘ کیونکہ حرام کاری سے پیدا ہونے والا بچہ تو بے قصور ہے، لہٰذا اسے ہلاک نہیں کیا جائے گا بلکہ اس کی حفاظت کی جائے گی، نیز یہ طریقہ زنا روکنے میں ممد ہوگا کیونکہ بچے کی صورت میں زانیوں کے لیے ابدی عار موجود رہے گی۔ (۲) ’’بچہ جن لیا‘‘ جننے کے فوراً بعد رجم نہیں کیا گیا بلکہ دیگر روایات میں ہے جب بچہ اس کے دودھ سے بے نیاز ہوگیا اور روٹی کھانے لگا۔ قربان جائیں ایسے شفیق و کریم نبی پر۔ صلی اللہ علیہ وسلم۔ (۳) شادی شدہ عورت اگر زنا کا ارتکاب کرے تو اس کو بھی رجم کیا جائے گا جس طرح مرد کو رجم کیا جاتا ہے۔ (۴) حاملہ عورت کو رجم نہیں کیا جائے گا جب تک وضع حمل نہ ہو جائے اور بچہ دودھ کے علاوہ کچھ کھانے پینے لگ جائے۔ (۵) کپڑے باندھ لینا مستحب ہے تاکہ بے پردگی نہ ہو۔ (۶) قاضی یا حاکم کا رجم میں شرکت کرنا ضروری نہیں۔ (۷) گناہ کیے ہوئے زیادہ عرصہ گزر جائے تو اس سے حد ساقط نہیں ہو جاتی بلکہ جب بھی عدالت میں کیس ثابت ہوگیا تو حد قائم کی جائے گی۔ (۸) حد لگنے کے بعد آدمی کو اس گناہ کا طعنہ نہیں دیا جا سکتا کیونکہ حد گناہ کو ختم کر دیتی ہے، اب وہ ایسے ہی ہے جیسے اس نے وہ گناہ کیا ہی نہیں۔"}],[1958,"عمران بن حصین رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے موت کے وقت اپنے چھ غلام آزاد کر دیئے، اس کے پاس ان کے علاوہ اور کوئی مال (مال و اسباب)نہ تھا، یہ بات نبی اکرم صلی اللہ علیہ وسلم کو معلوم ہوئی تو آپ اس سے ناراض ہوئے، اور فرمایا: \"میں نے ارادہ کیا کہ اس کی نماز جنازہ نہ پڑھوں\"، پھر آپ نے اس کے غلاموں کو بلایا، اور ان کے تین حصے کیے، پھر ان کے درمیان قرعہ اندازی کی، اور دو کو آزاد کر دیا، اور چار کو رہنے دیا۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہا سے روایت ہے کہ ایک آدمی نے مرتے وقت اپنے چھ غلام آزاد کر دیے۔ ان کے علاوہ اس کے پاس کوئی مال نہ تھا۔ یہ بات نبی صلی اللہ علیہ وسلم کو پہنچی تو آپ اس پر بہت ناراض ہوئے اور فرمایا: ’’میرا ارادہ ہوا کہ میں اس کا جنازہ نہ پڑھوں۔‘‘ پھر آپ نے اس کے غلام بلائے، ان کے تین حصے کیے، پھر ان میں قرعہ ڈالا۔ دو کو آزاد فرمایا اور چار کو غلام رکھا۔","f2":"(۱) اس قسم کے شخص کا جنازہ تو پڑھا جائے گا مگر اس کی وصیت کو شریعت کے مطابق درست کر دیا جائے گا۔ (۲) موت کے قریب کوئی شخص تہائی مال سے زائد میں تصرف کا اختیار نہیں رکھتا، یعنی وہ ایک تہائی مال سے زیادہ وصیت نہیں کرسکتا۔ (۲) ’’اس نبوی فیصلے کے برعکس، احناف کا خیال ہے کہ ’’سب غلام آزاد ہوں گے۔ ہر ایک کا تہائی حصہ وصیت کی بنا پر اور باقی دو تہائی حصے کی قیمت ہر غلام یت کے ورثاء کو کما کر ادا کرے گا۔‘‘ لیکن یہ رسول اللہ صلی اللہ علیہ وسلم کے فیصلے میں تصرف ہے اور کسی امتی کو اس کا قطعاً کوئی اختیار نہیں۔ (۴) غیر وارث قریبی رشتے دار کے علاوہ بھی کسی کو وصیت کی جا سکتی ہے۔"}],[1959,"زید بن خالد رضی اللہ عنہ کہتے ہیں کہ ایک شخص خیبر میں مر گیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ اپنے ساتھی کی نماز جنازہ پڑھ لو، اس نے اللہ کی راہ میں چوری کی ہے\"، تو (جب) ہم نے اس کے اسباب کی تلاشی لی تو ہمیں اس میں یہود کے نگینوں میں سے کچھ نگینے ملے، جو دو درہم کے برابر بھی نہیں تھے۔","الألباني: ضعيف",{"u2":"حضرت زید بن خالد رضی اللہ عنہ نے کہا: ایک آدمی غزوۂ خیبر میں فوت ہوگیا تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم اپنے ساتھی کا جنازہ پڑھ لو (میں نہیں پڑھوں گا) کیونکہ اس نے جہاد کے دوران میں خیانت کی ہے۔‘‘ ہم نے اس کے سامان کی تلاشی لی تو اس میں یہودیوں کے مونگوں میں سے کچھ مونگے پائے جو دو درہم قیمت بھی نہیں رکھتے تھے۔","f2":"گویا اس قسم کے لوگوں کا جنازہ چند لوگ پڑھیں، اہتمام نہ کیا جائے اور اہم شخصیات جنازہ نہ پڑھیں تاکہ ایسے مجرموں کی حوصلہ شکنی ہو اور انھیں خوف رہے۔"}],[1960,"ابوقتادہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس انصار کا ایک شخص لایا گیا تاکہ آپ اس کی نماز جنازہ پڑھ دیں، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ اپنے ساتھی کی نماز جنازہ پڑھ لو (میں نہیں پڑھتا) کیونکہ اس پر قرض ہے\"، ابوقتادہ رضی اللہ عنہ نے کہا: یہ میرے ذمہ ہے، نبی اکرم صلی اللہ علیہ وسلم نے پوچھا: \"تم اس کی ادائیگی کرو گے؟\" تو انہوں نے کہا: ہاں میں اس کی ادائیگی کروں گا، تب آپ نے اس کی نماز جنازہ پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابوقتادہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے پاس ایک انصاری شخص کی میت جنازے کے لیے لائی گئی تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم اپنے ساتھی کا جنازہ پڑھ لو (میں نہیں پڑھوں گا) اس پر تو قرض ہے۔‘‘ میں نے عرض کیا: وہ قرض میرے ذمے رہا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو یہ ذمے داری پوری بھی کرے گا؟‘‘ میں نے کہا: ضرور پوری کروں گا تو آپ نے اس کا جنازہ پڑھ دیا۔","f2":"(۱) پہلے پہل آپ کا معمول یہی تھا کہ مقروض میت جو ادائیگی کے لیے مال نہ چھوڑ کر فوت ہوتا، اس کا جنازہ نہیں پڑھتے تھے، البتہ کوئی شخص سچے دل سے قرض ادا کرنا چاہتا تھا مگر ادا نہ کرسکا تو ایسا مجبور شخص اللہ تعالیٰ کے نزدیک گناہ گار نہیں۔ بعد میں بیت المال میں وسعت ہوگئی تو آپ جنازہ پڑھ لیتے تھے اور ادائیگی بیت المال سے فرما دیتے تھے۔ جس کی تائید اس حدیث سے ہوتی ہے: [فمن توفي من المومنین فترک دینا فعلي قضاوہ، ومن ترک مالا فلورئتہ] (صحیح البخاري، الکفالۃ، حدیث: ۲۳۹۸، و صحیح مسلم، الفرائض، حدیث: ۱۶۱۹) بہرحال ہر گناہ گار میت کا جنازہ ضرور ہونا چاہیے۔ (۲) میت کے ذمے اگر قرض وغریہ ہوتو کوئی شخص اسے اپنے ذمے لے سکتا ہے، اور اس کی ذمہ داری قبول کی جا سکتی ہے، یہ ناجائز نہیں جیسے کہ بعض لوگوں کا خیال ہے۔"}],[1961,"سلمہ بن الاکوع رضی اللہ عنہ بیان کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم کے پاس ایک جنازہ لایا گیا تو لوگوں نے کہا: اللہ کے نبی! اس کی نماز جنازہ پڑھ دیجئیے، آپ نے پوچھا: \"کیا اس نے اپنے اوپر کچھ قرض چھوڑا ہے؟\" لوگوں نے کہا: جی ہاں، آپ نے پوچھا: \"کیا اس نے اس کی ادائیگی کے لیے کوئی چیز چھوڑی ہے؟\" لوگوں نے کہا: نہیں، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے ساتھی کی نماز جنازہ پڑھ لو\"، تو ابوقتادہ نامی ایک انصاری نے عرض کیا: آپ اس کی نماز (جنازہ) پڑھ دیجئیے، اس کا قرض میرے ذمہ ہے، تو آپ صلی اللہ علیہ وسلم نے اس کی نماز (جنازہ) پڑھی۔","الألباني: صحيح",{"u2":"حضرت سلمہ بن اکوع رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کے پاس ایک جنازہ لایا گیا۔ لوگوں نے کہا: اے اللہ کے نبی! اس کا جنازہ پڑھیے۔ آپ نے فرمایا: ’’اس پر کچھ قرض تو نہیں؟‘‘ لوگوں نے کہا: قرض ہے۔ آپ نے فرمایا: ’’یہ ادائیگی کے لیے کچھ مال چھوڑ گیا ہے؟‘‘ انھوں نے کہا: نہیں۔ آپ نے فرمایا: ’’پھر تم اپنے سااتھ کا جنازہ پڑھ لو۔‘‘ انصار میں سے ایک شخص جنھیں ابوقتادہ کہا جاتا تھا، نے کہا: آپ اس کا جنازہ پڑھیے، اس کا قرض میرے ذمے ہے تو آپ نے جنازہ پڑھ دیا۔"}],[1962,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم مقروض آدمی کی نماز جنازہ نہیں پڑھتے تھے، چنانچہ ایک جنازہ آپ کے پاس لایا گیا تو آپ نے پوچھا: \"کیا اس پر قرض ہے؟\" لوگوں نے جواب دیا: ہاں، اس پر دو دینار (کا قرض) ہے، آپ نے فرمایا: \"تم لوگ اپنے ساتھی پر نماز جنازہ پڑھ لو\"، ابوقتادہ رضی اللہ عنہ نے عرض کیا: اللہ کے رسول! یہ دونوں دینار میرے ذمہ ہیں، تو آپ نے اس کی نماز جنازہ پڑھی، پھر جب اللہ تعالی نے اپنے رسول کو فتح و نصرت عطا کی، تو آپ نے فرمایا: \"میں ہر مومن پر اس کی جان سے زیادہ حق رکھتا ہوں، جو قرض چھوڑ کر مرے (اس کی ادائیگی) مجھ پر ہے، اور جو مال چھوڑ کر مرے تو وہ اس کے وارثوں کا ہے\"۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم ایسے شخص کا جنازہ نہیں پڑھتے تھے جس پر قرض ہوتا تھا۔ ایک میت آپ کے پاس لائی گئی۔ آپ نے پوچھا: ’’کیا اس پر قرض ہے؟‘‘ لوگوں نے کہا: جی ہاں! اس پر دو دینار قرض ہے۔ آپ نے فرمایا: ’’پھر تم اپنے ساتھی کا جنازہ پڑھ لو۔‘‘ حضرت ابوقتادہ رضی اللہ عنہ نے عرض کیا: اے اللہ کے رسول! یہ دو دینار میرے ذمے ہیں۔ آپ نے جنازہ پڑھ دیا، پھر جب اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو فتوحات دیں تو آپ نے فرمایا: ’’میں ہر مومن کے لیے اس کے نفس سے بھی بڑھ کر قریبی ہوں، لہٰذا جو قرض چھوڑ جائے تو اس کی ادائیگی میرے (یعنی بیت المال کے) ذمے ہے اور جو مال چھوڑ جائے وہ اس کے وارثوں کو ملے گا۔‘‘"}],[1963,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ جب کوئی مومن مرتا اور اس پر قرض ہوتا ہے تو رسول اللہ صلی اللہ علیہ وسلم پوچھتے: \"کیا اس نے اپنے قرض کی ادائیگی کے لیے کچھ چھوڑا ہے؟\" اگر لوگ کہتے: جی ہاں، تو آپ اس کی نماز جنازہ پڑھتے، اور اگر کہتے: نہیں، تو آپ کہتے: \"تم اپنے ساتھی پر نماز (جنازہ) پڑھ لو\"۔ پھر جب اللہ تعالی نے اپنے رسول صلی اللہ علیہ وسلم پر فتح و نصرت کا دروازہ کھولا، تو آپ نے فرمایا: \"میں مومنوں پر ان کی جانوں سے زیادہ حق رکھتا ہوں، تو جو وفات پا جائے اور اس پر قرض ہو، تو (اس کی ادائیگی) مجھ پر ہے، اور اگر کوئی مال چھوڑ کر گیا تو وہ اس کے وارثوں کا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ جب کوئی مسلمان فوت ہوتا اور اس کے ذمے قرض ہوتا تو رسول اللہ صلی اللہ علیہ وسلم پوچھتے: ’’کیا یہ مرنے والا اپنے قرض کی ادائیگی کے لیے کچھ مال چھوڑ گیا ہے؟‘‘ اگر لوگ کہتے: جی ہاں، تو آپ اس کا جنازہ پڑھتے ورنہ آپ فرماتے: ’’تم اپنے ساتھی کا جنازہ پڑھ لو۔‘‘ پھر جب اللہ تعالیٰ نے اپنے رسول صلی اللہ علیہ وسلم کو فتوحات سے نوازا تو آپ نے فرمایا:’’میں مسلمانوں کے لیے ان کے نفوس سے بھی زیادہ قریبی ہوں، لہٰذا جو شخص مقروض فوت ہو جائے تو اس کے قرض کی ادائیگی میرے ذمے ہوگی اور جو شخص مال چھوڑ کر فوت ہو تو وہ مال اس کے ورثاء کو ملے گا۔‘‘","f2":"ابتدائی دور میں بھی صرف نبی صلی اللہ علیہ وسلم ہی مقروض کے جنازے سے انکار فرماتے تھے (تاکہ لوگ قرض کی ادائیگی میں سستی نہ کریں)، دوسرے لوگ جنازہ پڑھتے تھے۔ ایسی کوئی مثال نہیں کہ کویئ گناہ گار مسلمان بغیر جنازے کے دفن ہوا ہو۔"}],[1964,"ابن سمرہ رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے تیر کی انی سے خودکشی کر لی، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رہا میں تو میں اس کی نماز جنازہ نہیں پڑھ سکتا\"۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ سے روایت ہے کہ ایک آدمی نے تیروں سے خودکشی کرلی۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں اس کا جنازہ نہیں پڑھوں گا۔‘‘","f2":"رسول اللہ صلی اللہ علیہ وسلم نے جنازہ نہیں پڑھا مگر دوسروں کو روکا نہیں، یعنی دوسروں نے پڑھا۔ بلند مرتبہ لوگ نہ پڑھیں۔ اہتمام نہ کیا جائے۔ چند لوگ جنازہ پڑھ کر دفن کر دیں۔ جنازے کے بغیر نہ دفن کیا جائے کیونکہ خودکشی گناہ کبیرہ ہے، کفر نہیں۔"}],[1965,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص اپنے آپ کو کسی پہاڑ سے گرا کر مار ڈالے، تو وہ جہنم میں ہمیشہ ہمیش اپنے آپ کو اوپر سے نیچے گراتا رہے گا، اور جو زہر پی کر اپنے آپ کو مار ڈالے تو وہ زہر اس کے ہاتھ میں رہے گا اسے وہ ہمیشہ ہمیش جہنم میں پیتا رہے گا، اور جو شخص کسی دھار دار چیز سے اپنے آپ کو مار ڈالے (راوی کہتے ہیں: پھر کوئی چیز میرے سننے سے رہ گئی ۱؎، خالد کہہ رہے تھے:) تو اس کا لوہا اس کے ہاتھ میں ہو گا اسے وہ جہنم کی آگ میں اپنے پیٹ میں برابر گھونپتا رہے گا\"۔\n§وضاحت\n۱؎: یہ متن حدیث کا حصہ نہیں ہے بلکہ خالد سے روایت کرنے والے راوی کا کلام ہے یعنی خالد کہہ رہے تھے کہ «من قتل نفسہ بحدیدۃ» کے بعد کوئی لفظ رہ گیا ہے جسے میں سن نہیں سکا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو پہاڑ (یا کسی اور بلند مقام) سے گر کر خودکشی کرے، وہ جہنم کی آگ میں ہمیشہ ہمیشہ (جہنمی پہاڑ) سے گرتا رہے گا۔ اور جس شخص نے زہر پی کر خودکشی کی تو اس کا زہر اس کے ہاتھ میں دیا جائے گا اور وہ جہنم کی آگ میں ہمیشہ ہمیشہ اسے پیتا رہے گا۔ اور جو آدمی کسی تیز دھار آلے (تلوار، خنجر، چاقو یا چھری وغیرہ) سے خود کرے تو اس کا وہ ہتھیار اس کے ہاتھ میں دیا جائے گا اور وہ ہمیشہ ہمیشہ جہنم کی آگ میں اسے اپنے پیٹ میں گھونپتا رہے گا۔‘‘","f2":"(۱) انسان اپنے جسم و جان کا مالک نہیں ہے، لہٰذا وہ اپنے آپ کو نقصان پہنچائے تو اس نے اللہ تعالیٰ کی چیز کو نقصان پہنچایا۔ اپنے آپ کو قتل کرنا دوسروں کو قتل کرنے کی طرح جرم ہے، لہٰذا خودکشی حرام اور کبیرہ گناہ ہے۔ اللہ تعالیٰ پر راضی رہنا چاہیے۔ (۲) ’’ہمیشہ ہمیشہ‘‘ یعنی جب تک اپنے جرم کی سزا میں جہنم میں رہے گا، خودکشی والا فعل کرتا رہے گا، اذیت ہوگی، مگر مرے گا نہیں، اس کا یہ مطلب نہیں کہ ہمیشہ ہمیشہ کے لیے جہنم میں رہے گا کیونکہ خودکشی کفر نہیں۔ ہر مومن اپنے گناہوں کی معافی حاصل کرکے (الہ کے فضل سے یا کچھ سزا بھگت کر) آخر جنت میں ضرور جائے گا۔ اگر ظاہر الفاظ مراد ہوں تو اس روایت کو تغلیظ و مبالغہ پر محمول کیا جائے گا یا یہ سزا صرف اس جرم کی ہے۔ لیکن اس کے ساتھ اس کا کلمہ طیبہ پڑھنا جنت کو واجب کرتا ہے، لہٰذا جب نیکیاں اور گناہ ملائے جائیں گے تو انفرادی جزا و سزا کا اعتبار نہ ہوگا بلکہ مجموعی طور پر جو پلڑا بھاری ہوا، اس کے مطابق فیصلہ ہوگا۔ واللہ أعلم۔"}],[1966,"عمر بن خطاب رضی اللہ عنہ کہتے ہیں کہ جب عبداللہ بن ابی ابن سلول (منافقوں کا سردار) مر گیا، تو رسول اللہ صلی اللہ علیہ وسلم بلائے گئے، تاکہ آپ اس کی نماز جنازہ پڑھیں، جب رسول اللہ صلی اللہ علیہ وسلم (نماز پڑھنے کے لیے) کھڑے ہوئے تو میں تیزی سے آپ کی طرف بڑھا، اور عرض کیا: اللہ کے رسول! آپ ابن ابی پر نماز جنازہ پڑھیں گے؟ حالانکہ فلاں دن وہ ایسا ایسا کہہ رہا تھا، میں اس کی تمام باتیں آپ پر گنانے لگا، تو آپ مسکرائے، اور فرمایا: \"اے عمر! ان باتوں کو جانے دو\"۔ جب میں نے کافی اصرار کیا تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اختیار ہے (نماز پڑھوں یا نہ پڑھوں) تو میں نے پڑھنا پسند کیا، اگر میں یہ جانتا کہ ستر بار سے زیادہ مغفرت چاہنے پر اس کی مغفرت ہو جائے گی تو میں اس سے زیادہ مغفرت کرتا\" ۱؎ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے اس کی نماز جنازہ پڑھی، پھر لوٹے اور ابھی ذرا سا دم ہی لیا تھا کہ سورۃ برأت کی دونوں آیتیں نازل ہوئیں: «ولا تصل على أحد منهم مات أبدا ولا تقم على قبره إنهم كفروا باللہ ورسوله وماتوا وهم فاسقون» \"جب یہ مر جائیں تو تم ان میں سے کسی پر کبھی بھی نماز جنازہ نہ پڑھو، اور نہ اس کی قبر پہ کھڑے ہو، اس لیے کہ انہوں نے اللہ اور اس کے رسول کا انکار کیا ہے، اور گنہگار ہو کر مرے ہیں\"، بعد میں مجھے رسول اللہ صلی اللہ علیہ وسلم کے خلاف اپنی اس دن کی اس جرات پر حیرت ہوئی، اور اللہ اور اس کے رسول خوب جانتے ہیں کہ یہ جرات میں نے کیوں کی۔\n§وضاحت\n۱؎: یعنی ستر بار سے زیادہ اس کی مغفرت کے لیے دعا کرتا۔","الألباني: صحيح",{"u2":"حضرت عمر بن خطاب رضی اللہ عنہ سے روایت ہے کہ جب عبداللہ بن ابی ابن سلول (منافق) مر گیا تو رسول اللہ صلی اللہ علیہ وسلم کو اس کا جنازہ پڑھنے کے لیے بلایا گیا۔ جب رسول اللہ صلی اللہ علیہ وسلم (جنازہ پڑھنے کے لیے) کھڑے ہوگئے، میں جلدی سے آپ کے سامنے جا کھڑا ہوا اور عرض کیا: اے اللہ کے رسول! کیا آپ ابن ابی کا جنازہ پڑھتے ہیں، حالانکہ اس نے فلاں فلاں دن ایسی ایسی باتیں کیں؟ میں (اس کی شرارتیں) شمار کرنے لگا۔ رسول اللہ صلی اللہ علیہ وسلم مسکراتے رہے، آخر فرمایا: ’’عمر! ایک طرف ہٹ جاؤ۔‘‘ جب میں نے اپنی بات پر اصرار کیا تو آپ نے فرمایا: ’’مجھے اختیار دیا گیا ہے (کہ استغفار کرو یا نہ کرو، اللہ مغفرت نہ کرے گا) تو میں نے استغفار کو اختیار کیا ہے۔ اگر مجھے علم ہوتا کہ میں ستر دفعہ سے زائد استغفار کروں تو اسے معافی ہو جائے گی تو میں یقیناً ستر دفعہ سے زائد بھی استغفار کر دیا۔‘‘ چنانچہ رسول اللہ صلی اللہ علیہ وسلم نے جنازہ پڑھ دیا، پھر واپس تشریف لے گئے۔ ابھی تھوڑی ہی دیر گزری تھی کہ سورۂ براءت کی دو آیتیں اتریں: (ولا تصل علی احد………الأیۃ) ’’اے نبی! ان منافقوں میں سے کئوی مر جائے تو ہرگز اس کا جنازہ نہ پڑھیں اور نہ ان کی قبر پر (دعائے مغفرت کے لیے) جائیں کیونکہ انھوں نے اللہ اور اس کے رسول کا انکار کیا اور پھر اسی انکار و فسق کی حالت میں فوت ہوئے۔‘‘ بعد میں مجھے اپنی اس جرأت پر، جو میں نے رسول اللہ صلی اللہ علیہ وسلم کے سامنے کی، بہت تعجب ہوا کیونکہ اللہ تعالیٰ اور اس کے رسول صلی اللہ علیہ وسلم زیادہ علم رکھنے والے ہیں۔","f2":"(۱)اس حدیث کی تفہیم کے لیے مطالعہ فرمائیں فوائد حدیث: ۱۹۰۱۔ مزید باتیں درج ذیل ہیں۔ (۲) ’’سلول‘‘ اس کی ماں کا نام تھا۔ وہ معروف عورت تھی، اس لیے اس کی طرف بھی منسوب ہوتا تھا۔ (۳) ’’جنازہ نہ پڑھیں‘‘ یہاں منافق سے مراد وہ ہے جو اعتقادی منافق ہو، یعنی جو دل سے ایمان نہ لایا ہو، دل میں کفر ہو۔ صرف زبان سے (دھوکا دینے کے لیے) کلمہ پڑھا ہو۔ اور اس بات کا علم اللہ تعالیٰ کے سوا کسی کو نہیں ہوسکتا۔ الا یہ کہ اللہ تعالیٰ وحی نازل فرمائے اور یہ صرف رسول اللہ صلی اللہ علیہ وسلم کے دور میں ممکن تھا۔ آج ہم کسی کو منافق (اس معنی میں) نہیں کہہ سکتے۔ علامات نفاق پائے جانے سے کوئی آدمی اعتقادی منافق نہیں بن جاتا، عملی منافق بنتا ہے، یعنی دیکھنے میں منافقوں جیسا، حقیقت تو اللہ تعالیٰ ہی جانتا ہے، لہٰذا اب ہر کلمہ گو مسلمان کا جنازہ پڑھ لیا جائے گا۔ علامات نفاق تو کسی حد تک ہر ایک میں پائی جاتی ہیں۔ واللہ أعلم۔ (۴) ’’تعجب ہوا‘‘ درال یہ جرأت بھی انھیں اللہ تعالیٰ ہی نے بخشی تھی ورنہ حضرت عمر رضی اللہ عنہ تو رسول اللہ صلی اللہ علیہ وسلم کے سامنے اپنے طور پر چوں بھی نہ کرتے تھے۔ کئی واقعات اس پر دال ہیں۔ اور اس جرأت میں بھی اللہ تعالیٰ کی بہت سی حکمتیں پوشیدہ تھیں۔"}],[1967,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سہیل بن بیضاء رضی اللہ عنہ کی نماز جنازہ مسجد ہی میں پڑھی تھی ۱؎۔\n§وضاحت\n۱؎: اس سے مسجد میں جنازہ پڑھنے کا جواز ثابت ہوتا ہے، اگرچہ آپ کا معمول مسجد سے باہر پڑھنے کا تھا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت سہیل ابن بیضاء رضی اللہ عنہ کا جنازہ مسجد ہی میں پڑھا تھا۔","f2":"(۱) ’’سہیل ابن بیضاء‘‘ بیضاء ان کی والدہ کا نام تھا۔ یہ تین بھائی تھے۔ سہل، سہل اور صفوان۔ سہیل رضی اللہ عنہ ۹ ھ میں فوت ہوئے۔ (۲) ’’مسجد میں پڑھا‘‘ رسول اللہ صلی اللہ علیہ وسلم کا عام معمول تو مسجد سے باہر پڑھنے کا تھا مگر مسجد میں پڑھنا بھی ثابت ہے۔ بعد میں حضرت ابوبکر و عمر رضی اللہ عنہما کے جنازے بھی مسجد نبوی ہی میں پڑھے گئے۔ حضرت سعد رضی اللہ عنہ کا جنازہ حضرت عائشہ رضی اللہ عنہا نے حکماً مسجد میں پڑھوایا، لہٰذا ضرورت پڑے تو مسجد میں جنازہ پڑھا جا سکتا ہے۔ چونکہ دفن باہر کیا جاتا ہے، لہٰذا عموماً جنازہ باہر ہی پڑھا جاتا ہے۔ یہ وجہ نہیں کہ مسجد میں کراہت ہے، بلکہ ضرورت نہیں۔ ضرورت ہو تو مسجد میں بلا کراہت درست ہے۔ احناف سرے سے مسجد می جنازہ درست ہی نہیں سمجھتے کہ ابوداود کی ایک روایت ہے: ’’جس نے مسجد میں جنازہ پڑھا فلا شیی لہ ’’اس ثواب نہیں ملے گا۔‘‘ بعض نسخوں میں [فلا شیی علیہ] (سنن أبی داود، الحنائز، حدیث: ۳۱۹) غرض اس میں کوئی حرج نہیں‘‘ کے الفاظ بھی ہیں۔ لیکن پہلے الفاظ ہی درست ہیں جس کا مطلب یہ ہے کہ خاص اجر نہیں ملے گا جیسا کہ علامہ سندھی حنفی رحمہ اللہ نے تطبیق دی ہے صرف نماز جنازہ کا اجر ملے گا، مطلق اجر کی نفی اس لیے نہیں کی جا سکتی کہ صحیح حدیث سے خود رسول اللہ صلی اللہ علیہ وسلم کا نمز جنازہ مسجد میں پڑھنا ثابت ہے، اس لیے مسجد میں نماز جنازہ پڑھنے کو ناجائز نہیں کہا جا سکتا، البتہ مسجد سے باہر پڑھنا افضل قرار پائے گا۔ (فوائد سنن ابی داود، حدیث: ۳۱۹۱) ایسی محتمل روایت کی بنا پر نبی صلی اللہ علیہ وسلم اور صحابۂ کرام رضی اللہ عنہم کے صریح اور متفقہ فعل کی نفی کی جا رہی ہے۔ کوشش کرنی چاہیے کہ حتی الامکان ہر حدیث پر عمل ہو جائے۔ مزید تفصیل کے لیے دیکھیے: (اللہ الصحیحۃ: ۳۶۵/۵)"}],[1968,"ام المؤمنین عائشہ رضی اللہ عنہا بیان کرتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے سہیل بن بیضاء ۱؎ کی نماز جنازہ مسجد کے صحن ہی میں پڑھی تھی۔\n§وضاحت\n۱؎: بیضاء کے تین بیٹے تھے جن کے نام سہل، سہیل اور صفوان تھے اور ان کی ماں کا نام رعد تھا، بیضاء ان کا وصفی نام ہے، اور ان کے والد کا نام وہب بن ربیعہ قرشی فہری تھا۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے حضرت سہل بن بیضاء رضی اللہ عنہ کا جنازہ مسجد ہی میں پڑھایا تھا۔"}],[1969,"ابوامامہ بن سہل بن حنیف رضی اللہ عنہ بیان کرتے ہیں کہ عوالی مدینہ کی ایک غریب عورت ۱؎ بیمار پڑ گئی، نبی اکرم صلی اللہ علیہ وسلم اس کے بارے میں لوگوں سے پوچھتے رہتے تھے، اور کہہ رکھا تھا کہ \"اگر یہ مر جائے تو اسے دفن مت کرنا جب تک کہ میں اس کی نماز جنازہ نہ پڑھ لوں\"، چنانچہ وہ مر گئی، تو لوگ اسے عشاء کے بعد مدینہ لے کر آئے، ان لوگوں نے رسول اللہ صلی اللہ علیہ وسلم کو سویا ہوا پایا، تو آپ کو جگانا مناسب نہ سمجھا، چنانچہ ان لوگوں نے اس کی نماز جنازہ پڑھ لی، اور اسے لے جا کر مقبرہ بقیع میں دفن کر دیا، جب رسول اللہ صلی اللہ علیہ وسلم نے صبح کی تو لوگ آپ کے پاس آئے، آپ نے ان سے اس کے بارے میں پوچھا تو لوگوں نے کہا: اللہ کے رسول! وہ تو دفنائی جا چکی، (رات) ہم آپ کے پاس آئے (بھی) تھے، (لیکن) ہم نے آپ کو سویا ہوا پایا، تو آپ کو جگانا نامناسب سمجھا، آپ نے فرمایا:\"چلو!\" (اور) خود بھی چل پڑے، اور لوگ بھی آپ کے ساتھ گئے یہاں تک کہ ان لوگوں نے آپ کو اس کی قبر دکھائی، رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور لوگوں نے آپ کے پیچھے صف باندھا، آپ نے اس کی نماز (جنازہ) پڑھائی اور (اس میں) چار تکبیریں کہیں۔\n§وضاحت\n۱؎: اس عورت کا نام ام محجن تھا۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ بن سہل بن حنیف رضی اللہ عنہ نے کہا: ایک مسکین عورت (مدینے کے مضافات) عوالی میں بیمار ہوگئی تو نبی صلی اللہ علیہ وسلم لوگوں سے اس (کی صحت) کے بارے میں پوچھتے رہتے تھے، نیز آپ نے فرمایا: ’’اگر وہ فوت ہو جائے تو اسے دفن نہ کرنا یہاں تک کہ میں اس کا جنازہ پڑھوں۔‘‘ آخر وہ فوت ہوگئی تو لوگ اس کا جنازہ لے کر عشاء کے بعد مدینہ منورہ میں آئے لیکن انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو سوتے پایا۔ انھوں نے آپ کو بیدار کرنا مناسب نہ سمجھا، خود ہی جنازہ پڑھا اور اسے بقیع غرقد میں دفن کر دیا۔ جب صبح ہوئی تو وہ لوگ رسول اللہ صلی اللہ علیہ وسلم کے پاس آئے۔ آپ نے ان سے اس کے بارے میں پوچھا تو انھوں نے عرض کیا: اے اللہ کے رسول! وہ تو دفن بھی ہوچکی۔ ہم آپ کے پاس حاضر ہوئے تھے مگر ہم نے آپ کو سوتے پایا اور آپ کو جگانا مناسب نہ سمجھا۔ آپ نے فرمایا: ’’چلو۔‘‘ آپ چلے۔ وہ لوگ بھی آپ کے ساتھ چلے حتی کہ انھوں نے آپ کو اس کی قبر دکھائی۔ رسول اللہ صلی اللہ علیہ وسلم (قبر کے سامنے) کھڑے ہوئے۔ وہ لوگ (آپ کے حکم سے) آپ کے پیچھے صف میں کھڑے ہوگئے۔ آپ نے اس کا جنازہ پڑھایا اور چار تکبیریں کہیں۔","f2":"(۱) یہ عورت ام محجن رضی اللہ عنہا تھیں۔ مسجد کی صفائی سے خصوصی شغف رکھتی تھیں۔ ان کی تکریم میں رسول اللہ صلی اللہ علیہ وسلم نے مندرجہ بالا ارشاد فرمایا تھا۔ (۲) ’’دفن کر دیا‘‘ اس سے اندازہ کیا جا سکتا ہے کہ صحابہ کے دلوں میں رسول اللہ صلی اللہ علیہ وسلم کا احترام کس قدر تھا کہ آپ کو جگانا بھی ناپسند یا اسے سوء ادب خیال کرتے تھے۔ باقی رہا آپ کا فرمان تو اسے انھوں نے معمول پر محمول کیا، نہ کہ خصوصی ح کم پر تبھی تو آپ نے بعد میں ان پر ناراضی کا اظہار نہ فرمایا۔ (۳) ’’چار تکبیریں کہیں‘‘ اس کا منشا یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے باقاعدہ جنازہ پڑھا نہ کہ صرف دعا کی ورنہ صلی کے معنی دعا بھی ہوسکتے ہیں۔ (۴) اس حدیث سے امام نسائی رحمہ اللہ کا مقصود یہ ہے کہ صحابہ رضی اللہ عنہم نے اس کا جنازہ رات کو پڑھا اور نبی صلی اللہ علیہ وسلم نے اس پر انکار بھی نہیں فرمایا۔ (۵) اس حدیث سے معلوم ہوا کہ قبر پر جنازہ پڑھا جا سکتا ہے اگرچہ میت کو جنازہ پڑھ کر دفن کیا گیا ہو، نیز دوسرے جنازے میں پہلے جنازے والے لوگ بھی شریک ہوسکتے ہیں ورنہ صحابہ الگ کھڑے رہتے۔ معلوم ہوا دوبارہ جنازہ نبی صلی اللہ علیہ وسلم کا خاصا نہیں۔"}],[1970,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے بھائی نجاشی کی موت ہو گئی ہے، تو تم لوگ اٹھو اور ان کی نماز جنازہ پڑھو\"، (پھر) آپ نے ہماری صف بندی کی جیسے جنازہ پر صف بندی کی جاتی ہے، اور ان کی نماز جنازہ پڑھی۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ ہنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمھارا (اسلامی) بھائی نجاشی فوت ہو گیا ہے۔ اٹھو، اس کا جنازہ پڑھو۔‘‘ آپ کھڑے ہوئے اور ہماری صف بندی فرمائی جیسے جنازے میں صف بندی کی جاتی ہے، پھر اس کا جنازہ پڑھا۔","f2":"’’صف بندی فرمائی‘‘ یعنی باقاعدہ جنازہ پڑھا، نہ کہ صرف دعا کی۔ غائبانہ نماز جنازہ کی بحث حدیث نمبر ۱۹۴۸ میں گزر چکی ہے، ملاحظہ فرمائیں۔"}],[1971,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے لوگوں کو نجاشی کی موت کی خبر اسی دن دی جس دن وہ مرے، پھر آپ لوگوں کو لے کر صلاۃ گاہ کی طرف نکلے، اور ان کی صف بندی کی، (پھر) آپ نے ان کی نماز (جنازہ) پڑھائی، اور چار تکبیریں کہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے لوگوں کو حضرت نجاشی رحمہ اللہ کی وفات کی اطلاع ان کی وفات ہی کے دن فرمائی تھی، پھر پ لوگوں کو ساتھ لے کر جنازہ گاہ میں گئے۔ ان کی صف بندی کی اور ان کا جنازہ پڑھایا۔ اور چار تکبیریں کہیں۔"}],[1972,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ میں اپنے صحابہ کو نجاشی کی موت کی خبر دی، تو انہوں نے آپ کے پیچھے صف بندی کی، آپ نے ان کی نماز (جنازہ) پڑھائی، اور چار تکبیریں کہیں۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: ابن مسیب کا نام جیسا میں سننا چاہتا تھا نہیں سن سکا۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مدینہ منورہ میں اپنے صحابہ کو نجاشی رحمہ اللہ کی وفات کی خبر دی۔ انھوں نے آپ کے پیچھے صفیں بنائیں۔ آپ نے جنازہ پڑھایا اور چار تکبیریں کہیں۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ ابن مسیب کا لفظ میں اپنی منشا کے مطابق سمجھ نہیں سکا۔","f2":"اس روایت میں امام زہری کے استاد دو ہیں: ابن مسیب اور ابو سلمہ۔ امام صاحب کا مقصود یہ لگتا ہے کہ مجھے سند میں ابو سلمہ کا ذکر تو صحیح طور پر یاد ہے مگر ابن مسیب کے بارے میں شک ہے کہ اس روایت میں وہ مذکور ہیں یا نہیں، اگرچہ دیگر روایات میں ان کا یقیناً ذکر ہے۔ ممکن ہے جب امام نسائی رحمہ اللہ کے استاد محمد بن رافع نے یہ حدیث بیان کی ہو تو امام صاحب رحمہ اللہ لوگوں کی کثرت یا استاد کی دھیمی آواز کی وجہ سے اچھی طرح نہ سن سکے ہوں۔ واللہ أعلم۔"}],[1973,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: \"تمہارے بھائی (نجاشی) مر گئے ہیں تو تم لوگ اٹھو، اور ان کی نماز جنازہ پڑھو\"تو ہم نے ان پر دو صفیں باندھیں۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمھارا بھائی فوت ہوگیا ہے۔ اٹھو! اس کا جنازہ پڑھو۔‘‘ تو ہم نے اس کے جنازے میں دو صفیں بنائیں۔"}],[1974,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ جس دن رسول اللہ صلی اللہ علیہ وسلم نے نجاشی کی نماز (جنازہ) پڑھی تھی میں دوسری صف میں تھا۔","الألباني: صحيح الإسناد",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ جس دن رسول اللہ صلی اللہ علیہ وسلم نے حضرت نجاشی رحمہ اللہ کا جنازہ پڑھایا، میں دوسری صف میں تھا۔"}],[1975,"عمران بن حصین رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہم سے فرمایا: \"تمہارے بھائی نجاشی انتقال کر گئے ہیں تو تم اٹھو اور ان کی نماز جنازہ پڑھو\"، تو ہم کھڑے ہوئے (اور) ہم نے ان پر اسی طرح صف بندی کی جس طرح میت پر کی جاتی ہے، اور ہم نے ان کی نماز (جنازہ) اسی طرح پڑھی جس طرح میت کی پڑھی جاتی ہے۔","الألباني: صحيح",{"u2":"حضرت عمران بن حصین رضی اللہ عنہما سے روایت ہے، ہم سے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمھارا (اسلامی) بھائی نجاشی فوت ہوگیا ہے، اٹھو اس کا جنازہ پڑھو۔‘‘ ہم کھڑے ہوئے اور صف بندی کی جیسے میت پر کی جاتی ہے۔ اور اس کا جنازہ پڑھا جیسے میت کا جنازہ پڑھا جاتا ہے۔","f2":"’’جیسے میت پر کی جاتی ہے‘‘ گویا جنازے میں صف بندی ایک مشہور اور غیر متنازعہ بات ہے۔ ویسے بھی جنازے کے لیے لفظ نماز کا استعمال دلالت کرتا ہے کہ جنازے کے خصوصی احکام کے علاوہ نماز کے تمام احکام اس پر لاگو ہوں گے، مثلاً: قبلے کی طرف منہ کرنا، وضو کرنا، صفیں درست کرنا اور فاتحہ کی قراءت وغیرہ۔"}],[1976,"سمرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ام کعب رضی اللہ عنہا کی نماز (جنازہ) پڑھی، جو اپنی زچگی میں مر گئیں تھیں، تو رسول اللہ صلی اللہ علیہ وسلم نماز میں ان کی کمر کے پاس کھڑے ہوئے۔","الألباني: صحيح",{"u2":"حضرت سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ حضرت ام کعب رضی اللہ عنہا کا جنازہ پڑھا جو بچے کی پیدائش کے وقت فوت ہوگئی تھیں، تو رسول اللہ صلی اللہ علیہ وسلم ان کی کمر کے برابر کھڑے ہوئے۔","f2":"(۱) ضمناً یہ معلوم ہوا کہ عورت کے جنازے میں امام کمر کے برابر کھڑا ہوگا۔ ابو داود کی ایک روایت جو حضرت انس رضی اللہ عنہ سے مروی ہے، کے مطابق مرد کے جنازے میں امام سر کے برابر کھڑا ہوگا۔ (سنن أبي داود، حدیث: ۳۱۹۳) احناف دونوں صورتوں میں سینے کے برابر کھڑا ہونے کے قائل ہیں۔ وہ اس روایت کو نفاس والی عورت سے خاص کرتے ہیں کہ آپ اسے پردہ کرنے کے لیے پیٹ کے سامنے کھڑے ہوئے تھے، مگر کسی روایت میں یہ وجہ بیان نہیں کی گئی، نہ عقل اس توجیہ کی تائید کرتی ہے کیونکہ امام کے پیٹ کے سامنے کھڑا ہونے سے پوری صف سے پردہ ممکن نہیں۔ صرف دو چار آدمیوں سے پردہ ہوسکتا ہے اور وہ کسی بھی جگہ کھڑے ہونے سے حاصل ہوسکتا ہے نہ کہ صرف پیٹ کے سامنے کھڑا ہونے سے۔ ویسے بھی پورا جنازہ کفن میں لپیٹا ہوا ہوتا ہے، پھر امام کے ذریعے سے پردہ کیسا ہوگا؟ اور اس پردے کی ضرورت کیوں ہے؟ پھر مفصل روایات یا حضرت سمرہ کی اس حدیث کا مکمل جائزہ لیا جائے تو نفاس والی عورت سے اس کی تخصیص بے معنی ٹھہرتی ہے ہر عورت کی میت پر کھڑا ہونے کا یہی طریقہ مسنون ہے۔ علی کل حال۔ جب رسول اللہ صلی اللہ علیہ وسلم کی صحیح حدیث یا آپ کا واضح عمل موجود ہو تو محتمل ادھر ادھر کے دلائل یا قیاس آرائیوں سے اسے ٹالنا نہیں چاہیے۔(۲) باب والا مسئلہ ظاہر الفاظ سے ثابت ہو رہا ہے کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے۔ گویا یہ آپ کا معمول تھا۔"}],[1977,"عمار رضی اللہ عنہ کہتے ہیں ایک بچہ اور ایک عورت کا جنازہ آیا، تو بچہ لوگوں سے متصل رکھا گیا، اور عورت اس کے پیچھے (قبلہ کی طرف) رکھی گئی، پھر ان دونوں کی نماز جنازہ پڑھی گئی، لوگوں میں ابو سعید خدری، ابن عباس، ابوقتادہ اور ابوہریرہ رضی اللہ عنہم (بھی) تھے، تو میں نے ان (لوگوں) سے اس کے متعلق سوال کیا، تو سبھوں نے کہا: یہی سنت (نبی کا طریقہ) ہے۔","الألباني: صحيح",{"u2":"حضرت عطاء بن ابی رباح سے منقول ہے کہ ایک عورت اور ایک بچے کے جنازے اکٹھے ہوگئے تو حضرت عمار رضی اللہ عنہ نے بچے کی میت کو لوگوں کی طرف آگے رکھا اور عورت کو اس کے پیچھے (یعنی قبلے کی طرف) رکھا اور دونوں کا جنازہ (بیک وقت) پڑھا۔ حاضرین میں حضرت ابو سعید خدری، ابن عباس، ابو قتادہ اور ابوہریرہ رضی اللہ عنہم بھی تھے۔ میں نے ان سے اس بارے میں پوچھا تو ان سب نے کہا کہ یہی مسنون طریقہ ہے۔","f2":"میت ایک سے زائد ہو تو ان کا جنازہ بیک وقت پڑھا جا سکتا ہے، خواہ وہ ایک صنف سے تعلق رکھتے ہوں یا مختلف اصناف سے، بچے ہوں یا بڑے، البتہ مردوں کو امام کے قریب رکھا جائے گا اور عورتوں کو مردوں سے پیچھے رکھا جائے گا۔ دعا عام میت والی پڑھ دی جائے تو سب کو کفایت کر جائے گی۔"}],[1978,"نافع کہتے ہیں کہ ابن عمر رضی اللہ عنہما نے نو جنازوں کی ایک ساتھ نماز پڑھی، تو مرد امام سے قریب رکھے گئے، اور عورتیں قبلہ سے قریب، ان سب عورتوں کی ایک صف بنائی، اور علی رضی اللہ عنہ کی بیٹی اور عمر بن خطاب رضی اللہ عنہ کی بیوی ام کلثوم، اور ان کے بیٹے زید دونوں کا جنازہ ایک ساتھ رکھا گیا، امام اس دن سعید بن العاص تھے، اور لوگوں میں ابن عمر، ابوہریرہ، ابوسعید اور ابوقتادہ رضی اللہ عنہم (بھی موجود) تھے، بچہ امام سے قریب رکھا گیا، تو ایک شخص نے کہا: مجھے یہ چیز ناگوار لگی، تو میں نے ابن عباس، ابوہریرہ، ابوسعید اور ابوقتادہ (رضی اللہ عنہم) کی طرف (حیرت سے) دیکھا، اور پوچھا: یہ کیا ہے؟ تو انہوں نے کہا: یہی سنت (نبی کا طریقہ) ہے۔","الألباني: صحيح",{"u2":"حضرت نافع سے روایت ہے کہ حضرت ابن عمر رضی اللہ عنہما نے نو میتوں کا اکٹھا جنازہ پڑھا۔ مردوں کو امام کی جانب رکھا اور عورتوں کو قبلے کی جانب اور ان سب کو ایک سیدھ میں رکھا۔ اور (اسی طرح) حضرت عمر بن خطاب رضی اللہ عنہ کی بیوی حضرت ام کلثوم بنت علی اور ان کے بیٹے جن کا نام زید تھا، کو اکٹھا رکھا گیا۔ اس وقت امام سعید بن عاص رضی اللہ عنہ تھے۔ حاضرین میں ابن عمر، ابوہریرہ، ابو سعید اور ابو قتادہ رضی اللہ عنہم شامل تھے۔ بچے کو امام کی جانب رکھا گیا۔ ایک آدمی نے کہا کہ میں نے اس کو درست نہ سمجھا تو میں نے حضرات ابن عباس، ابوہریرہ، ابو سعید اور ابوقتادہ رضی اللہ عنہم کی طرف دیکھا اور کہا: یہ کیا ہے؟ ان سب نے کہا: یہی مسنون طریقہ ہے۔","f2":"جب صحابی کسی کام کو سنت یا مسنون کہے تو اس سے مراد نبی صلی اللہ علیہ وسلم کی سنت ہی ہوتی ہے۔"}],[1979,"سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فلاں کی ماں کی نماز جنازہ پڑھی جو اپنی زچگی میں مر گئیں تھیں، تو آپ ان کے بیچ میں یعنی کمر کے پاس کھڑے ہوئے۔","الألباني: صحيح",{"u2":"حضرت سمرہ بن جندب رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے ام فلاں (ام کعب رضی اللہ عنہا) کا جنازہ پڑھا جو بچے کی پیدائش کے وقت فوت ہوگئی تھیں تو آپ ان کے درمیان میں (یعنی کمر کے برابر) کھڑے ہوئے۔","f2":"حدیث کا باب سے بظاہر کوئی تعلق معلوم نہیں ہوتا۔ واللہ أعلم۔"}],[1980,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو نجاشی کی موت کی خبر دی، اور آپ ان کے ساتھ نکلے تو ان کی صف بندی کی،(اور) چار تکبیریں کہیں۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے لوگوں کو حضرت نجاشی رحمہ اللہ کی وفات کی اطلاع دی۔ انھیں لے کر (باہر) نکلے۔ ان کی صف بندی کی اور جنازے میں چار تکبیریں کہیں۔","f2":"بعض روایات میں جنازے کی تکبیرات چار سے زائد، یعنی نو تک بھی منقول ہیں۔ نبی صلی اللہ علیہ وسلم کی وفات کے بعد بھی بعض صحابہ سے چار سے زائد تکبیریں کہنا ثابت ہے، لہٰذا عمل میں تنوع بہتر ہے، لیکن اگر مذکورہ طریقوں میں سے کسی ایک پر التزام کرنا ہے تو چار پر عمل بہتر اور افضل ہے کیونکہ نبی صلی اللہ علیہ وسلم کا عام معمول یہی تھا۔ تفصیل و تحقیق کے لیے شیخ البانی رحمہ اللہ کی احکام الجنائز، ص: ۱۴۶-۱۴۱ ملاحظہ کی جا سکتی ہے۔"}],[1981,"ابوامامہ بن سہل رضی اللہ عنہ کہتے ہیں کہ عوالی والوں ۱؎ میں سے ایک عورت بیمار ہوئی، اور نبی اکرم صلی اللہ علیہ وسلم بیمار کی بیمار پرسی سب سے زیادہ کرتے تھے، تو آپ نے فرمایا: \"جب یہ مر جائے تو مجھے خبر کرنا\" تو وہ رات میں مر گئی، اور لوگوں نے اسے دفنا دیا اور نبی اکرم صلی اللہ علیہ وسلم کو خبر نہیں کیا، جب آپ نے صبح کی تو اس کے بارے میں پوچھا، تو لوگوں نے کہا: اللہ کے رسول! ہم نے آپ کو بیدار کرنا مناسب نہیں سمجھا، آپ اس کی قبر پر آئے، اور اس پر نماز جنازہ پڑھی اور (اس میں) چار تکبیریں کہیں۔\n§وضاحت\n۱؎: عوالی مدینہ سے جنوب میں بلندی پر واقع ہے۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ بن سہل رضی اللہ عنہ بیان کرتے ہیں کہ علاقۂ عوالی میں ایک عورت بیمار ہوگئی اور نبی صلی اللہ علیہ وسلم بیمار کی بیمار پرسی اور عیادت بہت زیادہ فرمایا کرتے تھے۔ آپ نے (اس عورت کی عیادت کے موقع پر) فرمایا: ’’جب یہ فوت ہو جائے تو مجھے اطلاع کرنا۔‘‘ وہ رات کو فوت ہوئی تو انھوں نے (خود ہی جنازہ پڑھ کر) اسے دفن کر دیا اور نبی صلی اللہ علیہ وسلم کو اطلاع نہ کی۔ صبح ہوئی تو نبی صلی اللہ علیہ وسلم نے اس کے بارے میں پوچھا تو انھوں نے (پوری صورت گوش گزار کی اور) کہا کہ ہم نے آپ کو بیدار کرنا مناسب نہ سمجھا، پھر آپ اس کی قبر پر آئے، اس کا جنازہ پڑھا اور چار تکبیریں کہیں۔","f2":"’’جب یہ فوت ہو جائے‘‘ گویا آپ کو وحی سے یا اس کی حالت سے اس کی وفات کا یقین ہو چلا تھا، اسی لیے آپ نے ’’اگر‘‘ کی بجائے ’’جب‘‘ کا لفظ استعمال کیا جو یقین پر دلالت کرتا ہے۔ اس حدیث کی مزید تفصیلات قریب ہی حدیث نمبر ۱۹۷۱ میں گزر چکی ہیں۔"}],[1982,"ابن ابی لیلی سے روایت ہے کہ زید بن ارقم رضی اللہ عنہ نے ایک میت کی نماز جنازہ پڑھائی تو (اس میں) پانچ تکبیریں کہیں، اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے بھی اتنی ہی تکبیریں کہیں تھیں۔","الألباني: صحيح",{"u2":"حضرت ابن ابی لیلیٰ سے منقول ہے کہ حضرت زید بن ارقم رضی اللہ عنہ نے ایک میت کا جنازہ پڑھا تو اس پر پانچ تکبیریں کہیں، پھر فرمایا: رسول اللہ صلی اللہ علیہ وسلم نے (بعض اوقات) پانچ تکبیریں بھی کہی ہیں۔","f2":"تفصیل کے لیے دیکھیے، فائدہ حدیث: ۱۹۸۲۔"}],[1983,"عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو سنا کہ آپ ایک جنازے کی نماز میں کہہ رہے تھے: «اللہم اغفر له وارحمه واعف عنه وعافه وأكرم نزله ووسع مدخله واغسله بماء وثلج وبرد ونقه من الخطايا كما ينقى الثوب الأبيض من الدنس وأبدله دارا خيرا من داره وأهلا خيرا من أهله وزوجا خيرا من زوجه وقه عذاب القبر وعذاب النار» \"اے اللہ! اس کی مغفرت فرما، اس پر رحم کر، اسے معاف کر دے، اسے عافیت دے، اس کی (بہترین) مہمان نوازی فرما، اس کی (قبر) کشادہ کر دے، اسے پانی برف اور اولے سے دھو دے، اسے گناہوں سے اس طرح صاف کر دے جیسے سفید کپڑا میل کچیل سے صاف کیا جاتا ہے، اس کو بدلے میں اس کے گھر سے اچھا گھر، اس کے گھر والوں سے بہتر گھر والے، اور اس کی بیوی سے اچھی بیوی عطا کر، اور اسے عذاب قبر اور عذاب جہنم سے بچا\"۔ عوف رضی اللہ عنہ کہتے ہیں کہ اس میت کے لیے رسول اللہ صلی اللہ علیہ وسلم کی یہ دعا (سن کر) میں نے آرزو کی: کاش! اس کی جگہ میں ہوتا۔","الألباني: صحيح",{"u2":"حضرت عوف بن مالک رضی اللہ عنہ نے فرمایا کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک میت کا جنازہ پڑھتے ہوئے یہ کہتے سنا: [اللھم! اغفرلہ و ارحمہ……… وقہ عذاب القبر و عذاب النار] ’’اے اللہ! اس کے گناہ بخش دے اور اس پر رحم فرما۔ اس سے درگزر فرما اور اسے خیریت سے رکھ۔ اس کی اچھی مہمان نوازی فرما اور اس کا ٹھکانا وسیع فرما۔ اور اسے پانی، برف اور اولوں کے ساتھ دھو دے اور اسے غلطیوں سے اس طرح صاف فرما دے جس طرح سفید کپڑے کو میل کچیل سے صاف کیا جاتا ہے۔ اور اسے اس کے (دنیوی) گھر سے بہتر گھر عطا فرما۔ اور اس کے (دنیوی) گھر والوں سے بہتر گھر والے عطا فرما۔ اور اس کے جوڑے سے بہتر جوڑا عطا فرما۔ اور اسے قبر کے عذاب اور آگ کے عذاب سے بچا۔‘‘ حضرت عوف رضی اللہ عنہ فرماتے ہیں: اس میت کے لیے یہ (جامع) دعائیں سن کر مجھے خواہش ہوئی کہ کاش میں یہ میت ہوتا۔","f2":"(۱) ’’سنا‘‘ معلوم ہوا رسول اللہ صلی اللہ علیہ وسلم جنازہ بلند آواز سے پڑھ رہے تھے، لہٰذا جنازے میں جہر جائز ہے۔ ظاہر یہی ہے کہ مکمل جنازہ جہراً تھا، مگر کہا جا سکتا ہے کہ اس حدیث سے صرف دعا کا جہر ثابت ہوتا ہے، البتہ یہ بات بعید معلوم ہوتی ہے کہ قراءت آہستہ ہو مگر دعا جہر کے ساتھ، جبکہ نماز میں تو دعا آہستہ ہونے کے باوجود بعض صورتوں میں قراءت جہراً ہوتی ہے، نیز درود بھی تو دعا ہی ہے، لہٰذا دعا کا جہر قراءت اور درود کے جہر کو بھی مستلزم ہے۔ (۲) ’’سفید کپڑا‘‘ کیونکہ سفید کپڑا اچھی طرح صاف کیا جاتا ہے ورنہ اس پر داغ دھبے نمایاں ہوں گے۔ اس تمثیل سے مراد معافی میں مبالغہ ہے۔ (۳) ’’جوڑے‘‘ یہ معنی اس لیے کیا گیا ہے کہ مرد اور عورت دونوں کے لیے استعمال ہوسکے۔ مرد کے لیے بیوی جوڑا ہے اور عورت کے لیے خاوند۔ بعض اہل علم کا خیال ہے کہ عورت کے جنازے میں یہ لفظ: [وزوجا خیرا من زوجھا] نہ کہا جائے کیونکہ ہوسکتا ہے، اس کا دنیوی خاوند ہی آخرت میں بھی اس کا خاوند ہو اور خاوند ایک سے زائد نہیں ہوسکتے جبکہ بیویاں ایک سے زائد ہوں گی مگر یہ غیر ضروری تکلف ہے کیونکہ جنتی خاوند، خواہ سابقہ ہی ہو، دنیوی خاوند سے رتبے اور درجے میں بہرصورت بہتر ہوگا ورنہ دنیوی بیوی بھی جنت میں بیوی نہ بن سکے گی۔ جبکہ احادیث میں نیک دنیوی بیوی کے آخرت میں اسی شخص کی بیوی ہونے کی صراحت ہے۔ (۴) جمہور اہل علم کے نزدیک پہلی تکبیر کے بعد ثنا، سورۂ فاتحہ اور قراءت، دوسری کے بعد درود، تیسری کے بعد دعا اور چوتھی کے بعد سلام ہوگا۔ پہلی تکبیر کے بعد ثنا پڑھنے کے متعلق اس کتاب کا ابتدائیہ ملاحظہ فرما لیا جائے۔ (۵) بعض اہل علم عید کی زائد تکبیرات کی طرح جنازے کی چاروں تکبیروں کو بھی شروع میں اکٹھا کہنے کے قائل ہیں، یعنی چاروں تکبیرات کہنے کے بعد مسلسل ثنا، سورۂ فاتحہ، قراءت، درود اور دعا و سلام ہوں گے مگر اس طریقے سے نماز جنازہ نماز عید کے مشابہ ہو جائے گی اور نماز جنازہ کا امتیاز ختم ہو جائے گا، لہٰذا پہلا طریقہ ہی راجح معلوم ہوتا ہے۔ واللہ أعلم۔"}],[1984,"عوف بن مالک رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک میت پر صلاۃ پڑھتے سنا، تو میں نے سنا کہ آپ اس کے لیے دعا میں یہ کہہ رہے تھے: «اللہم اغفر له وارحمه وعافه واعف عنه وأكرم نزله ووسع مدخله واغسله بالماء والثلج والبرد ونقه من الخطايا كما نقيت الثوب الأبيض من الدنس وأبدله دارا خيرا من داره وأهلا خيرا من أهله وزوجا خيرا من زوجه وأدخله الجنة ونجه من النار - أو قال - وأعذه من عذاب القبر» \"اے اللہ! اس کی مغفرت فرما، اس پر رحم کر، اسے عافیت دے، اسے معاف کر دے، اس کی (بہترین)مہمان نوازی فرما، اس کی (قبر) کشادہ کر دے، اسے پانی، برف اور اولے سے دھو دے، اسے گناہوں سے اس طرح صاف کر دے جیسے سفید کپڑا میل کچیل سے صاف کیا جاتا ہے، اس کو بدلے میں اس کے گھر سے اچھا گھر، اس کے گھر والوں سے بہتر گھر والے، اور اس کی بیوی سے اچھی بیوی عطا کر، اور اسے جنت میں داخل کر، اور جہنم کے عذاب سے نجات دے، یا فرمایا اسے عذاب قبر سے بچا\"۔","الألباني: صحيح",{"u2":"حضرت عوف بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو ایک میت کا جنازہ پڑھتے سنا۔ میں نے سنا، پ دعا میں یوں فرما رہے تھے: [اللھم! اغفرلہ ……… ونحہ من النار] ’’اے اللہ! اس (کے گناہوں) کو بخش دے اور اس پر رحم فرما۔ اسے خیریت کے ساتھ رکھ اور اس سے درگزر فرما۔ اس کی مہمان نوازی اچھی طفرما اور اس کی قبر کو کھلا کر دے اور اسے پانی، برف اور اولوں سے دھو ڈال۔ اور اسے غلطیوں (کے اثرات) سے اس طرح پاک و صاف فرما دے جس طرح تو نے سفید کپڑے کو میل کچیل سے صاف رکھا ہے۔ اور اسے اس کے گھر سے بہتر گھر، اس کے گھر والوں سے بہتر گھر والے اور اس کے ساتھی سے بہتر ساتھی عطا فرما۔ اسے جنت میں داخل فرما اور آگ سے دور رکھ۔‘‘ یا آپ نے فرمایا: [وأعدہ من عذاب القبر] ’’اسے عذاب قبر سے بچا۔‘‘","f2":"(۱) ’’تو نے سفید کپڑے کو‘‘ کیونکہ کپڑے کا سفید مادہ تو اللہ تعالیٰ ہی نے پیدا فرمایا ہے جو ہر قسم کے داغ دھبے سے محفوظ ہوتا ہے۔ اگر اللہ تعالیٰ بے داغ مادہ پیدا نہ فرماتا تو انسان خالص سفید رنگ کہاں سے حاصل کرتا؟ (۲) ’’ساتھی‘‘ زوج کے یہ معنی بھی ہوسکتے ہیں جس میں خاوند بیوی بدرجہ اولیٰ شامل ہیں۔ (احشروا الذین ظلموا وازواجھم) (الصفت ۲۲:۳۷) اس معنی کے لحاظ سے یہ دعا غیرشادی شدہ مرد اور عورت کے جنازے پر بھی پڑھی جا سکتی ہے۔"}],[1985,"عبید بن خالد سلمی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے دو آدمیوں کے درمیان بھائی چارہ کرایا، ان میں سے ایک قتل کر دیا گیا، اور دوسرا(بھی) اس کے بعد مر گیا، ہم نے اس کی نماز جنازہ پڑھی، تو نبی اکرم صلی اللہ علیہ وسلم نے پوچھا: \"تم لوگوں نے کیا دعا کی؟\"، تو ان لوگوں نے کہا: ہم نے اس کے لیے یہ دعا کی: «اللہم اغفر له اللہم ارحمه اللہم ألحقه بصاحبه» \"اے اللہ! اس کی مغفرت فرما، اے اللہ اس پر رحم فرما، اے اللہ! اسے اپنے ساتھی سے ملا دے\" تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اس کی صلاۃ اس کی صلاۃ کے بعد کہاں جائے گی؟ اور اس کا عمل اس کے عمل کے بعد کہاں جائے گا؟ ان دونوں کے درمیان وہی دوری ہے جو آسمان و زمین کے درمیان ہے\"۔ عمرو بن میمون کہتے ہیں: مجھے خوشی ہوئی کیونکہ عبداللہ بن ربیعہ سلمی رضی اللہ عنہ نے (اس حدیث کو) میرے لیے مسند کر دیا۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ربیعہ سلمی رضی اللہ عنہ جو کہ صحابیٔ رسول صلی اللہ علیہ وسلم ہیں، نے حضرت عبید بن خالد سلمی رضی اللہ عنہ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے دو آدمیوں کو آپس میں بھائی بنا دیا۔ ان میں سے ایک شہید ہوگیا اور دوسرا اس کے کچھ بعد فوت ہوا۔ ہم نے اس کا جنازہ پڑھا۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم نے (جنازے میں) اس کے لیے کیا دعا کی؟‘‘ صحابہ نے عرض کیا: ہم نے اس کے لیے یہ دعا کی: [اللھم! اغفرلہ ……… الحقہ بصاحبہ] ’’اے اللہ! اسے معاف فرما۔ اس پر رحم فرما اور اسے اس کے ساتھی (بھائی) کے ساتھ ملا دے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تو اس کے بعد اس کی نمازیں اور دوسرے نیک اعمال کدھر گئے؟ اللہ کی قسم! ان کے درمیان تو زمین و آسمان کے مابین جیسا فاصلہ ہے۔‘‘ عمرو بن میمون نے کہا: یہ روایت مجھے بہت اچھی لگی کیونکہ انھوں (استاد محترم) نے یہ روایت (بغیر واسطہ گرائے) مجھے بیان کی۔","f2":"(۱)اس روایت میں حضرت عمرو بن میمون کے استاد صحابی ہیں۔ اوروہ ایک دوسرے صحابی سے بیان کر رہے ہیں۔ ایک صحابی اگر دوسرے صحابی کا واسطہ ذکر نہ بھی کرے تو روایت کی اسنادی حیثیت کمزور نہیں ہوتی، البتہ واسطے کا ذکر بہتر ہے، اسی لیے حضرت عمرو بن میمون نے اس روایت پر اپنی خوشی کا اظہار فرمایا۔ (۲) گویا جنازے میں مطلق مغفرت اور رفع درجات کی دعا کی جائے۔ کسی شخصیت کا حوالہ یا اس کی طرف نسبت مناسب نہیں کیونکہ ہر شخص کا حقیقی مرتبہ اللہ تعالیٰ ہی جانتا ہے، البتہ صفات کا حوالہ دیا جا سکتا ہے۔ جیسے ’’اے اللہ! اس کو شہداء و صالحین کے ساتھ ملا دے۔‘‘ وغیرہ۔ (۳) اعمال صالحہ والی لمبی زندگی مسلمان آدمی کے لیے غنیمت ہے۔ (۴) خشوع و خضوع، اخلاص اور تقویٰ کی زیادتی کی بنا پر بسا اوقات آدمی بستر پر فوت ہوکر بھی شہید کے برابر یا اس سے بلند درجہ حاصل کر لیتا ہے۔"}],[1986,"ابوابراہیم انصاری اشہلی اپنے والد سے روایت کرتے ہیں کہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم کو میت پر نماز جنازہ میں کہتے سنا: «اللہم اغفر لحينا وميتنا وشاهدنا وغائبنا وذكرنا وأنثانا وصغيرنا وكبيرنا» \"اے اللہ! ہمارے زندہ اور مردہ کو، ہمارے حاضر اور غائب، ہمارے نر اور مادہ، ہمارے چھوٹے اور بڑے سب کو بخش دے\"۔","الألباني: صحيح",{"u2":"حضرت ابو ابراہیم انصاری اپنے والد محترم سے بیان کرتے ہیں انھوں نے نبی صلی اللہ علیہ وسلم کو ایک میت کے جنازے میں یوں دعا کرتے سنا: [اللھم! اغفر لحینا …… وکبیرنا] ’’اے اللہ! معاف فرما دے ہمارے فوت شدہ اور زندہ کو اور حاضر و غائب کو اور مذکر و مؤنث کو اور چھوٹے اور بڑے کو۔‘‘","f2":"(۱) حاضر و غائب سے مراد جنازے کے وقت حاضر و غائب بھی ہوسکتا ہے، یعنی جو جنازے میں موجود ہیں یا غائب ہیں۔ اور غائب سے مراد فوت شدہ بھی ہوسکتا ہے۔ اس صورت میں حاضر سے مراد زندہ ہوگا۔ غائب سے مراد وہ افراد بھی ہوسکتے ہیں جو ابھی پیدا نہیں ہوئے۔ اس صورت میں حاضر سے مراد زندہ اور پیدا شدہ لوگ ہوں گے۔ حاضر سے مراد موجود جنازہ بھی ہوسکتا ہے اور غائب سے مراد وہ ہوگا جو وہاں موجود نہیں ہے۔ اس سے جنازۂ غائبانہ کی مشروعیت بھی استنباط کی جا سکتی ہے۔ (۲) صغیر سے مراد نابالغ نہیں کہ وہ تو ویسے ہی مغفورلہ ہے بلکہ جو کسی دوسرے کے مقابلے میں چھوٹا ہے، خواہ بالغ ہی ہو۔ اسی طرح کبیر سے مراد ہر وہ شخص ہے جو کسی دوسرے کے مقابلے میں بڑا ہو۔ ویسے بھی اس قسم کے الفاظ سے ظاہر معانی کے بجائے تعمیم مقصود ہوتی ہے، یعنی لائق مغفرت شخص کو بخش دے۔ یا بچے کے لیے رفع درجات کی دعا ہے کیونکہ اس کے گناہ تو ہوتے نہیں۔"}],[1987,"طلحہ بن عبداللہ بن عوف کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کے پیچھے جنازہ کی نماز پڑھی، تو انہوں نے سورۃ فاتحہ اور کوئی ایک سورت پڑھی، اور جہر کیا یہاں تک کہ آپ نے ہمیں سنا دیا، جب فارغ ہوئے تو میں نے ان کا ہاتھ پکڑا اور پوچھا: (یہ کیا؟) تو انہوں نے کہا: (یہی) سنت (نبی کا طریقہ) ہے، اور (یہی) حق ہے۔","الألباني: صحيح",{"u2":"حضرت طلحہ بن عبداللہ بن عوف بیان کرتے ہیں کہ میں نے حضرت ابن عباس رضی اللہ عنہما کے پیچھے ایک میت کا جنازہ پڑھا۔ انھوں نے سورۂ فاتحہ اور ایک اور سورت پڑھی اور (دونوں) بلند آواز سے پڑھیں حتی کہ ہمیں سنائی دیں۔ جب وہ فارغ ہوئے تو میں نے ان کا ہاتھ پکڑا اور ان سے اس بارے میں پوچھا تو انھوں نے فرمایا: یہ سنت اور حق ہے۔","f2":"ثابت ہوا کہ جنازے می بھی قراءتِ فاتحہ ضروری ہے۔ سنت سے مراد نبی صلی اللہ علیہ وسلم کا مقرر کردہ طریقہ ہے۔ یہاں سنت وجوب کے مقابلے میں نہیں جیسا کہ لفظ ’’حق‘‘ سے صاف ظاہر ہے۔ [لا صلاۃ لمن لم یقرأ بفاتحۃ الکتاب] (صحیح البخاري، الأذان، حدیث: ۷۵۶، و صحیح مسلم، الصلاۃ، حدیث: ۳۹۴) کا عموم بھی قراءتِ فاتحہ کو واجب کرتا ہے۔ جمہور اہل علم اسی کے قائل ہیں۔ احناف بلاوجہ قراءت کے مخالف ہیں۔ اس حدیث کے جواب میں وہ کہتے ہیں کہ حضرت ابن عباس رضی اللہ عنہما نے سورۂ فاتحہ اور دوسری سو رت قراءت کی نیت سے نہیں بلکہ دعا کی نیت سے پڑھی ہوں گی۔ مگر اس ’’ہوں گی‘‘ کی کوئی دلیل بھی تو ہونی چاہیے۔ آخر قراءتِ فاتحہ سے مانع کیا ہے؟ کیا جنازے کا دعا ہونا قراءت کی ضد ہے؟ عام نمازوں میں بھی قراءتِ فاتحہ ہوتی ہے، دعائیں بھی، یہ کون سا جمع بین النقیصین ہے؟"}],[1988,"طلحہ بن عبداللہ کہتے ہیں کہ میں نے ابن عباس رضی اللہ عنہما کے پیچھے ایک جنازے کی نماز پڑھی، تو میں نے انہیں سورۃ فاتحہ پڑھتے سنا، تو جب وہ سلام پھیر چکے تو میں نے ان کا ہاتھ پکڑا، اور پوچھا: آپ (نماز جنازہ میں) قرآن پڑھتے ہیں؟ تو انہوں نے کہا: جی ہاں، (یہی) حق اور سنت ہے۔","الألباني: صحيح",{"u2":"حضرت طلحہ بن عبداللہ سے روایت ہے کہ میں نے حضرت ابن عباس رضی اللہ عنہما کے پیچھے ایک جنازہ پڑھا۔ میں نے انھیں سورۂ فاتحہ پڑھتے سنا۔ جب وہ جنازے سے فارغ ہوئے تو میں نے ان کا ہاتھ پکڑ لیا اور ان سے پوچھا کہ کیا آپ (جنازے میں) قراءت کرتے ہیں؟ انھوں نے فرمایا: ہاں، یہ حق ہے اور نبی (صلی اللہ علیہ وسلم) کی سنت ہے۔"}],[1989,"ابوامامہ اسعد بن سہل بن حنیف رضی اللہ عنہ کہتے ہیں نماز جنازہ میں سنت یہ ہے کہ پہلی تکبیر کے بعد سورۃ فاتحہ آہستہ پڑھی جائے، پھر تین تکبیریں کہی جائیں، اور آخر میں سلام پھیرا جائے ۱؎۔\n§وضاحت\n۱؎: ابوامامہ یہ کنیت سے مشہور ہیں، ان کا نام اسعد یا سعد ہے، ابن سعد بن حنیف الانصاری، ان کا شمار صحابہ مںْ ہے، انہوں نے نبی کریم صلی اللہ علیہ وسلم کو دیکھنے کا شرف حاصل کیا ہے، لیکن آپ سے احادیث نہیں سنی ہیں، اس لیے یہ حدیث مراسیل صحابہ میں سے ہے، اور یہ قابلِ استناد ہے، اس لیے کہ صحابی نے صحابی سے سنا ہے، اور دوسرے صحابی نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی ہے، بیچ کا واسطہ ثقہ راوی یعنی صحابی ہے، اس لیے کوئی حرج نہیں، دوسرے طرق میں واسطہ کا ذکر ثابت ہے، جیسا کہ آگے کی حدیث میں یہ روایت ضحاک بن قیس رضی اللہ عنہ سے آ رہی ہے :(مزید تفصیل کے لیے ملاحظہ ہو: أحکام الجنائز للألبانی: فقرہ نمبر ۷۴، حدیث نمبر۵ ) امام زہری نے اس حدیث کی روایت ابوامامہ سے کی جس کی تصحیح أئمہ نے کی ہے امام طحاوی نے اس حدیث کی تخریج میں یہ اضافہ کیا ہے کہ زہری نے محمد بن سوید فہری سے ابوامامہ کی اس حدیث کا تذکرہ کیا، تو اس پر ابن سوید نے کہا کہ میں نے اسے ضحاک بن قیس رضی اللہ عنہ سے سنا ہے، جسے وہ حبیب بن مسلمہ سے نماز جنازہ کے بارے روایت کرتے ہیں، اور یہ اسی حدیث کی طرح ہے جسے ابوامامہ نے تم سے روایت کی ہے۔ :(طحاوی ۱/۲۸۸ ) آگے صحیح سند سے نسائی نے اسے مرفوعاً ضحاک سے روایت کی ہے، اور طحاوی کے یہاں ضحاک نے اسے حبیب بن مسلمہ سے روایت کی ہے، واضح رہے کہ یہ دونوں کمسن صحابہ میں ہیں۔","الألباني: صحيح",{"u2":"حضرت ابو امامہ رضی اللہ عنہ سے روایت ہے کہ نماز جنازہ میں سنت یہ ہے کہ پہلی تکبیر کے بعد سورۂ فاتحہ آہستہ پڑھے، پھر تین تکبیریں کہے اور آخری تکبیر کے بعد سلام پھیر دے۔","f2":"(۱) راویٔ حدیث حضرت ابوامامہ رضی اللہ عنہ معروف صحابیٔ رسول، ابو امامہ باہلی نہیں ہیں بلکہ یہ اور صحابی ہیں جو انھی کی کنیت سے معروف ہیں انھیں رسول اللہ صلی اللہ علیہ وسلم کا شرف رویت نصیب ہے، اگرچہ براہ راست انھوں نے رسول اللہ صلی اللہ علیہ وسلم سے کوئی حدیث نہیں سنی، یہ روایت بھی انھوں نے کسی اور صحابی کے واسطے سے لی ہے لیکن بلاواسطہ بیان فرما دی۔ محدثین کے نزدیک اسے مرسل صحابی کہتے ہیں، اور یہ قابل حجت ہوتی ہے۔ اسے مرفوع روایت ہی کا حکم ملتا ہے۔ مزید دیکھیے: (تعلیق أحکام الجنائز للألباني، ص:۱۴۱) (۲) ’’سورۂ فاتحہ آہستہ پڑھے‘‘ جبکہ پیچھے حدیث نمبر ۱۹۸۹ میں صراحتاً جہر کا ذکر ہے، لہٰذا دونوں طرح جائز ہے۔ آہستہ پڑھے یا بلند آواز سے۔ (۳) ’’پھر تین تکبیریں کہے‘‘ روایت مختصر ہے، یعنی تین تکبیریں اکٹھی نہیں کہی جائیں گی بلکہ تمام مل کر تین ہوں گی، یعنی الگ الگ۔ دوسری کے بعد درود، تیسری کے بعد دعا اور چوتھی کے بعد سلام جیسا کہ تفصیل حدیث: ۱۹۸۵ فائدہ، ۴ میں گزر چکی ہے۔"}],[1990,"ضحاک بن قیس دمشقی رضی اللہ عنہ سے اسی جیسی حدیث مروی ہے۔","",{"u2":"حضرت ضحاک بن قیس دمشقی سے بھی اسی قسم کی (اس کے ہم معنی) روایت آتی ہے۔"}],[1991,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جس میت پر بھی مسلمانوں کی ایک جماعت نماز جنازہ پڑھے (جن کی تعداد) سو تک پہنچتی ہو، (اور) وہ (اللہ کے پاس) شفاعت (سفارش) کریں تو اس کے حق میں (ان کی) شفاعت قبول کی جائے گی\"۔ سلام کہتے ہیں: میں نے اس حدیث کو شعیب بن حبحاب سے بیان کیا تو انہوں نے کہا: مجھ سے اسے انس بن مالک رضی اللہ عنہ نے بیان کیا ہے، وہ اسے نبی اکرم صلی اللہ علیہ وسلم سے روایت کر رہے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جس میت پر مسلمانوں کی ایک جماعت جنازہ پڑھے جو سو تک پہنچتے ہوں اور وہ اس کی (بخشش) کی سفارش کریں تو لازماً اس میت کے حق میں ان کی سفارش قبول کی جاتی ہے۔‘‘\nراویٔ حدیث سلام بن ابو مطیع بیان کرتے ہیں کہ میں نے یہ روایت حضرت شعیب بن حبحاب کو بیان کی تو وہ کہنے لگے: مجھے یہی روایت حضرت انس بن مالک رضی اللہ عنہ نے نبی صلی اللہ علیہ وسلم سے بیان کی ہے۔","f2":"(۱) گویا یہ روایت حضرت عائشہ رضی اللہ عنہا سے بھی مروی ہے اور حضرت انس رضی اللہ عنہ سے بھی۔ (۲) ’’سفارش قبول کی جاتی ہے‘‘ بشرطیکہ وہ انسان قابل مغفرت ہو۔ یہ قید ہر ایسی روایت میں ملحوظ رہنی چاہیے"}],[1992,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مسلمانوں میں سے جو بھی اس طرح مرتا ہو کہ لوگوں کی ایک ایسی جماعت اس کی نماز جنازہ پڑھتی ہو، جو سو تک پہنچ جاتی ہو، تو وہ شفاعت کرتے ہیں، تو ان کی شفاعت قبول کی جاتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جو مسلمان فوت ہو جائے، پھر اس پر مسلمانوں کی ایک جماعت جنازہ پڑھے جو ایک سو تک پہنچتے ہوں اور وہ اس کے لیے سفارش کریں تو لازماً ان کی سفارش اس کے حق میں قبول کی جاتی ہے۔‘‘"}],[1993,"ابوبکار حکم بن فروخ کہتے ہیں ہمیں ابوملیح نے ایک جنازے کی نماز پڑھائی تو ہم نے سمجھا کہ وہ تکبیر (تکبیر اولی) کہہ چکے (پھر کیا دیکھتا ہوں کہ) وہ ہماری طرف متوجہ ہوئے، اور کہا: تم اپنی صفیں درست کرو تاکہ تمہاری سفارش کارگر ہو۔ ابوملیح کہتے ہیں: مجھ سے عبداللہ بن سلیط نے بیان کیا، انہوں نے امہات المؤمنین میں سے ایک سے روایت کی، اور وہ ام المؤمنین میمونہ رضی اللہ عنہا ہیں، وہ کہتی ہیں: مجھے نبی اکرم صلی اللہ علیہ وسلم نے خبر دی، آپ نے فرمایا: \"جس میت کی بھی لوگوں کی ایک جماعت نماز جنازہ پڑھتی ہے تو اس کے حق میں (ان کی) شفاعت قبول کر لی جاتی ہے\"، تو میں نے ابوملیح سے جماعت (کی تعداد) کے متعلق پوچھا تو انہوں نے کہا: چالیس افراد پر مشتمل گروہ امت (جماعت) ہے۔","الألباني: حسن صحيح",{"u2":"ابو بکار حکم بن فروخ سے روایت ہے کہ حضرت ابو ملیح نے ہمیں ایک میت کا جنازہ پڑھایا۔ ہم نے سمجھا کہ انھوں نے اللہ اکبر کہہ دیا ہے لیکن (اچانک) انھوں نے ہماری طرف متوجہ ہوکر فرمایا: اپنی صفیں درست اور سیدھی کرو۔ اور تمھاری سفارش بہترین ہونی چاہیے (کیونکہ) مجھے حضرت عبداللہ بن سلیط نے امہات المومنین میں سے نبی صلی اللہ علیہ وسلم کی ایک زوجۂ محترمہ حضرت میمونہ رضی اللہ عنہا سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھ سے فرمایا: ’’جس میت پر مسلمانوں کی ایک جماعت جنازہ پڑھ دے، اس کے حق میں ان کی سفارش ضرور قبول ہوگی۔‘‘ میں نے حضرت ابو ملیح سے پوچھا کہ وہ جماعت کتنی ہو؟ انھوں نے کہا: چالیس افراد۔","f2":"بعض روایات میں رسول اللہ صلی اللہ علیہ وسلم سے صراحتاً چالیس افراد کا ذکر آتا ہے۔ دیکھیے: (صحیح مسلم، الجنائز، حدیث: ۹۴۸) اس لیے حضرت ابو ملیح نے اس روایت میں بھی ’’امت یعنی جماعت‘‘ کی تفسیر چالیس افراد سے فرما دی۔ رحمہ اللہ۔"}],[1994,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جس نے کسی کی نماز جنازہ پڑھی، تو اسے ایک قیراط ملے گا، اور جس نے اسے قبر میں رکھے جانے تک انتظار کیا، تو اسے دو قیراط ملے گا، اور دو قیراط دو بڑے پہاڑوں کے مثل ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص کسی میت کا جنازہ پڑھے، اس کے لیے ایک قیراط ثواب ہے اور جو شخص (جنازے کے بعد) انتظار کرتا رہے حتی کہ اسے لحد میں رکھ دیا جائے تو اس کے لیے دو قیراط (ثواب) ہے اور دو قیراط دو عظیم پہاڑوں کی طرح ہیں۔‘‘","f2":"دیکھیے، حدیث: ۱۹۴۲۔"}],[1995,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی جنازے میں شریک رہے یہاں تک کہ اس پر نماز جنازہ پڑھی جائے، تو اسے ایک قیراط ثواب ملے گا، اور جو دفنائے جانے تک رہے تو اسے دو قیراط ملے گا\"، پوچھا گیا: اللہ کے رسول! یہ دو قیراط کیا ہے؟ آپ نے فرمایا: \"یہ دو بڑے پہاڑوں کے برابر ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص جنازے میں حاضر ہو اور جنازہ پڑھے جانے تک رہے تو اس کے لیے ایک قیراط (ثواب) ہے اور جو دفن کیے جانے تک رہے تو اس کے لیے دو قیراط (ثواب) ہے۔‘‘ پوچھا گیا: اے اللہ کے رسول! وہ قیراط کیسے ہوں گے؟ آپ نے فرمایا: ’’وہ عظیم پہاڑوں جیسے۔‘‘"}],[1996,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو شخص طلب ثواب کے لیے کسی مسلمان کے جنازے کے ساتھ جائے، اور اس کی نماز جنازہ پڑھے، اور اسے دفنائے تو اس کے لیے دو قیراط (کا ثواب) ہے، اور جو (صرف) نماز جنازہ پڑھے اور دفنانے جانے سے پہلے لوٹ آئے، تو وہ ایک قیراط(ثواب) لے کر لوٹتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص ثواب کی نیت سے کسی مسلمان کے جنازے کے ساتھ جائے، اس کا جنازہ پڑھے اور اسے دفن کرے تو اس کے لیے دو قیراط ہیں۔ اور جو شخص جنازہ پڑھ کر دفن سے پہلے واپس آ جائے تو وہ ایک قیراط (ثواب) کے ساتھ پلٹتا ہے۔‘‘"}],[1997,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جو کسی جنازے کے ساتھ جائے (اور) اس پر نماز جنازہ پڑھے پھر لوٹ آئے، تو اسے ایک قیراط کا ثواب ہے، اور جو (جنازہ میں) شریک ہو، (اور) اس پر نماز جنازہ پڑھے پھر بیٹھا رہے یہاں تک کہ اسے دفنا کر فارغ ہو لیا جائے، تو اس کا اجر دو قیراط ہے، ان میں سے ہر ایک قیراط احد (پہاڑ) سے زیادہ بڑا ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص جنازے کے ساتھ جائے، اس کا جنازہ پڑھے، پھر واپس آ جائے تو اس کے لیے ایک قیراط اجر ہے اور جو ساتھ جائے، جنازہ پڑھے، پھر بیٹھا رہے حتی کہ تدفین سے فراغت ہو تو اس کے لیے دو قیراط اجر ہے۔ ہر قیراط احد (پہاڑ) سے بڑا ہوگا۔‘‘","f2":"’’بیٹھا رہے‘‘ مراد ٹھہرنا ہے، خواہ بیٹھے یا کھڑا رہے۔"}],[1998,"ابو سعید خدری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم جنازہ دیکھو تو کھڑے ہو جاؤ، اور جو اس کے ساتھ جائے وہ بھی کھڑا رہے یہاں تک کہ اسے رکھ دیا جائے\"۔","الألباني: صحيح",{"u2":"حضرت ابوسعید رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم جنازہ دیکھو تو کھڑے ہو جاؤ۔ اور جو شخص جنازے کے ساتھ جائے، وہ نہ بیٹھے حتی کہ جنازہ (زمین پر) رکھ دیا جائے۔‘‘","f2":"تفصیل کے لیے دیکھیے، فوائد حدیث: ۱۹۱۵ تا ۱۹۳۱۔"}],[1999,"علی رضی اللہ عنہ سے روایت ہے کہ ان سے جنازے کے لیے جب تک رکھ نہ دیا جائے کھڑے رہنے کا ذکر کیا گیا، تو علی رضی اللہ عنہ نے کہا: رسول اللہ صلی اللہ علیہ وسلم (پہلے) کھڑے رہتے تھے پھر بیٹھنے لگے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ کے سامنے جنازہ (زمین پر) رکھے جانے تک کھڑے رہنے کا ذکر کیا گیا تو حضرت علی بن ابی طالب رضی اللہ عنہ نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم (پہلے) کھڑے رہتے تھے، مگر بعد میں بیٹھے رہتے تھے۔","f2":"یہ بحث پیچھے گزر چکی ہے۔ دیکھیے حدیث نمبر: ۱۹۲۴ و مابعد۔"}],[2000,"علی رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کھڑے دیکھا آپ کھڑے ہوئے تو ہم (بھی) کھڑے ہوئے، اور بیٹھتے دیکھا تو ہم (بھی) بیٹھنے لگے۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کھڑے ہوتے دیکھا تو ہم بھی کھڑے رہے، پھر ہم نے آپ کو بیٹھے دیکھا تو ہم بھی بیٹھے رہے۔"}],[2001,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک جنازے میں نکلے، جب ہم قبر کے پاس پہنچے تو وہ تیار نہیں ہوئی تھی، چنانچہ آپ بیٹھ گئے تو ہم بھی آپ کے اردگرد بیٹھ گئے، گویا ہمارے سر پر پرندے بیٹھے ہوئے تھے۔","الألباني: صحيح",{"u2":"حضرت براء رضی اللہ عنہ فرماتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک جنازے میں گئے۔ جب ہم قبر کے پاس پہنچے تو (دیکھا کہ) قبر تیار نہیں ہوئی تھی۔ آپ بیٹھ گئے اور ہم آپ کے ارد گرد بیٹھ گئے (بغیر کسی حرکت و آواز کے) گویا کہ ہمارے سروں پر پرندے بیٹھے ہیں۔","f2":"(۱) ’’بیٹھ گئے‘‘ گویا دفن کرنے سے پہلے بیٹھا جا سکتا ہے بشرطیکہ میت کو زمین پر رکھ دیا گیا ہو۔ (۲) ’’پرندے بیٹھے ہیں۔‘‘ یہ سکون اور خاموشی رسول اللہ صلی اللہ علیہ وسلم کے احترام کے ساتھ ساتھ موقع و محل کی مناسبت سے تھی کہ قبر بنائی جا رہی ہے، میت پاس رکھی ہے اور قبر کے کنارے بیٹھے ہیں۔"}],[2002,"عبداللہ بن ثعلبہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے شہدائے احد کے بارے میں فرمایا: \"انہیں ان کے خون کے ساتھ کپڑوں میں لپیٹ دو کیونکہ جو بھی زخم اللہ کی راہ میں لگا ہو گا وہ قیامت کے روز بہتا ہوا آئے گا، اس کا رنگ خون کا رنگ ہو گا، اور اس کی خوشبو مشک کی خوشبو ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن ثعلبہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے جنگ احد کے شہداء کے بارے میں فرمایا تھا: ’’انھیں ان کے خون آلود جسموں اور کپڑوں سمیت کفن دو کیونکہ جو زخم بھی اللہ تعالیٰ کے راستے میں لگا ہو، قیامت کے دن اس کی یہ حالت ہوگی کہ رنگ تو خون جیسا ہی ہوگا مگر خوشبو کستوری جیسی ہوگی۔‘‘","f2":"(۱) یہ بات متفق علیہ ہے کہ شہید کو غسل نہیں دیا جائے گا بلکہ اسی خون آلود حالت میں مناسب کپڑے میں کفن دے کر دفن کر دیا جائے گا تاکہ اس پر مظلومیت کے نشان باقی رہیں، نیز قیامت کے دن اس کا امتیاز قائم رہے اور سب حاضرین کے سامنے اس کی فضیلت ظاہر ہو کیونکہ قیامت کے دن ہر میت کو اس حال میں اٹھایا جائے گا جس پر وہ فوت اور دفن ہوا، البتہ احناف نے اس کے لیے چند شرطیں لگائی ہیں، مثلاً: اس نے زخمی ہونے کے بعد نہ کچھ کھایا پیا ہو، نہ سایہ حاصل کیا ہو، نہ اس کا علاج کیا گیا ہو حتی کہ نہ اس نے وصیت کی ہو مگر یہ تمام شرطیں بلا دلیل بلکہ باطل ہیں بلکہ شہادت کے ساتھ مذاق اور شہید پر ظلم ہے۔ گویا اسے دھوپ میں پیاسا رکھ کر تڑپا تڑپا کر مارا جائے یا مرنے دیا جائے۔ لطف تو یہ ہے کہ اسے بات کرنے کی بھی اجازت نہ دی جائے۔ استغفراللہ۔ (۲) شہید کے جنازے کے بارے میں اختلاف ہے اور یہ بحث تفصیل کے ساتھ احادیث: ۱۹۵۵ تا ۱۹۵۷ میں گزر چکی ہے۔"}],[2003,"عبیداللہ بن معیہ نامی ایک شخص کہتے ہیں کہ غزوہ طائف کے دن دو مسلمان مارے گئے، تو وہ رسول اللہ صلی اللہ علیہ وسلم کے پاس اٹھا کر لائے گئے، تو آپ نے انہیں(اسی جگہ) دفنانے کا حکم دیا جہاں وہ مارے گئے تھے۔ اس حدیث کے راوی ابن معیہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں پیدا ہوئے تھے۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عبید اللہ بن معیہ سے روایت ہے انھوں نے فرمایا: طائف کے دوران میں دو مسلمان شہید ہوئے تو ان کو اٹھا کر رسول اللہ صلی اللہ علیہ وسلم کے پاس لایا گیا۔ آپ نے حکم دیا کہ انھیں وہیں دفن کیا جائے جہاں یہ شہید ہوئے۔ (راویٔ حدیث) حضرت ابن معیہ رسول اللہ صلی اللہ علیہ وسلم کے زمانے میں پیدا ہوئے تھے۔","f2":"(۱) راویٔ حدیث عبید اللہ بن معیہ کے لیے رسول اللہ صلی اللہ علیہ وسلم کا دیدار ثابت نہیں، لہٰذا انھیں صحابی نہیں کہا جائے گا۔ بلکہ وہ جلیل القدر تابعی تھے۔ جب تابعی براہ راست رسول اللہ صلی اللہ علیہ وسلم سے روایت کرے تو اس روایت کو مرسل کہتے ہیں اور مرسل روایت ضعیف ہوتی ہے، لیکن چونکہ مابعد کی حدیث جابر اس کی تائید کرتی ہے، یعنی اس کا شاہد ہے، اس لیے صححی ہے۔ (۲) یہ ضروری نہیں کہ میت کو عین اسی جگہ دفن کیا جائے جہاں وہ شہید ہو بلکہ اوقات یہ ممکن بھی نہیں ہوتا، مثلاً: جب اس جگہ دشمن کا قبضہ ہو، لہٰذا شہید کو کسی قریبی جگہ بھی دفن کیا جا سکتا ہے جیسا کہ شہدائے احد اکٹھے ایک جگہ دفن ہیں مگر ضروری نہیں کہ وہ سب کے سب اسی جگہ بلکہ اپنے اپنے مدفن میں ہی شہید ہوئے ہوں، البتہ یہ مناسب ہے کہ انھیں میدان شہادت یا اس سے قریب دفن کر دیا جائے۔ عام آبادی میں نہ لے جایا جائے۔ (۳) عمومی طور پر بھی اسلام میت کی منتقلی کی حوصلہ افزائی نہیں کرتا، ہاں اشد ضرورت اور مجبوری ہو تو وفات کی جگہ سے منتقل ہو بھی سکتی ہے۔"}],[2004,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے غزوہ احد کے مقتولین کے بارے حکم دیا کہ انہیں ان کے پچھاڑے جانے کی جگ ہوں پر لوٹا دیا جائے، حالانکہ وہ مدینہ لے آئے گئے تھے۔","الألباني: صحيح",{"u2":"حضرت جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے حکم دیا تھا کہ شدائے احد کو ان کی شہادت کے میدان میں واپس لایا جائے کیونکہ ان (میں سے بعض) کو مدینہ منورہ لے جایا گیا تھا"}],[2005,"جابر بن عبداللہ رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"مقتولین کو ان کے گرنے کی جگ ہوں میں دفن کرو\" ۱؎۔\n§وضاحت\n۱؎: یعنی وہ مارے گئے ہیں اور جس جگہ ان کی لاش گری تھی وہیں دفن کرو۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے منقول ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا تھا: ’’شہداء (ااحد) کو ان کی شہادت گاہ ہی میں دفن کیا جائے۔‘‘","f2":"(۱) اس حکم کی توجیہ حدیث نمبر ۲۰۰۵ کے تحت بیان ہوچکی ہے۔ (۲) جنگ احد میں حضرت جابر رضی اللہ عنہ کے والد محترم حضرت عبداللہ رضی اللہ بھی شہید ہوئے تھے، اس لیے حضرت جابر رضی اللہ عنہ کا اس فرمان سے خصوصی تتعلق تھا۔ (۳) رسول اللہ صلی اللہ علیہ وسلم کو اطلاع ملی تھی کہ کچھ لوگ اپنے قریبی شہداء کی لاشیں مدینہ لے گئے ہیں، جیسا کہ حدیث: ۲۰۰۶ میں ہے، مزید لاشیں لے جانے کا امکان بھی تھا، اس لیے آپ نے یہ حکم جاری فرمایا۔"}],[2006,"علی رضی اللہ عنہ کہتے ہیں کہ میں نے نبی اکرم صلی اللہ علیہ وسلم سے پوچھا: آپ کے بوڑھے گم کردہ راہ چچا (ابوطالب) مر گئے ہیں، انہیں کون دفن کرے؟ آپ نے فرمایا: \"تم جاؤ اور اپنے باپ کو دفن کر دو اور کوئی نئی چیز نہ کرنا جب تک میرے پاس لوٹ نہ آنا\"، چنانچہ میں انہیں دفن کر آیا، تو آپ نے میرے لیے (نہانے کا) حکم دیا، میں نے غسل کیا، اور آپ نے مجھے دعا دی۔ راوی ناجیہ بن کعب کہتے ہیں: اور علی رضی اللہ عنہ نے ایک ایسی دعا کا ذکر کیا جسے میں یاد نہیں رکھ سکا۔","الألباني: صحيح",{"u2":"حضرت علی رضی اللہ عنہ سے منقول ہے کہ (جب میرے والد ابو طالب فوت ہوئے تو) میں نے نبی صلی اللہ علیہ وسلم سے گزارش کی کہ آپ کے گم کردہ راہ چچچا فوت ہوگئے ہیں۔ اب انھیں کون (زمین میں) چھپائے (دفن کرے) گا؟ آپ نے فرمایا: ’’جاؤ، اپنے والد کو (زمین یمں) چھپاؤ (دفن کرو)۔ اور میرے پاس واپس آنے سے پہلے کوئی اور کام نہ کرنا۔‘‘ میں ان کو دفنانے کے بعد آپ کے پاس حاضر ہوا تو آپ نے مجھے غسل کرنے کا حکم دیا۔ میں نے غسل کیا تو آپ نے میرے لیے (صبر و تحمل کی) دعا کی لیکن وہ دعا مجھے یاد نہیں۔","f2":"(۱) آپ کے چچا ابوطالب باوجود آپ کی کوششوں کے اسلام قبول کیے بغیر ہی فوت ہوگئے۔ اس بات کا آپ کو اور حضرت علی کو بہت صدمہ تھا۔ جس کا اظہار مندرجہ بالا الفاظ سے ہو رہا ہے۔ ویسے وہ آپ کا بھرپور ساتھ دیتے رہے اور کفار کے سامنے ڈھال بنے رہے۔ یہی وجہ ہے کہ اللہ تعالیٰ بھی ان سے عذاب میں تخفیف فرمائے گا۔ (۲) ’’دفن کرو‘‘ کافر رشتہ دار کو بھی دفن کیا جائے گا،،صوصاً جبکہ وہ والد ہو تو پھر احترام کے ساتھ دفن کرنا ہوگا۔ (وصاحبھما فی الدنیا معروفا) (لقمان ۱۵:۳۱) البتہ مسنون تکفین و تدفین صرف مسلمان کے لیے ہوگی، نیز کافر کی قبر مسلمانوں کی قبروں سے الگ جگہ ہونی چاہیے۔"}],[2007,"سعد بن ابی وقاص رضی اللہ عنہ کہتے ہیں کہ میرے لیے بغلی قبر کھودنا، اور (اینٹیں) کھڑی کرنا جیسے رسول اللہ صلی اللہ علیہ وسلم کے لیے کی گئی تھی۔","الألباني: صحيح",{"u2":"حضرت سعد رضی اللہ نہ (وصیت کے طور پر) فرمایا: میرے لیے لحد بنانا اور پھر اینٹیں لگا دینا جیسا کہ اللہ کے رسول صلی اللہ علیہ وسلم کے لیے کیا گیا تھا۔","f2":"’’لحد‘‘ بغلی قبر جس میں میت کو رکھنے کی جگہ قبلے کی دیوار میں بنائی جاتی ہے۔ اور ’’شق‘‘ سیدھی قبر جس میں میت کو رکھنے کی جگہ قبر کے درمیان میں کھودی جاتی ہے۔ دونوں طریقے جائز ہیں مگر لحد بہتر ہے کیونکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لحد ہمارے لیے ہے اور شق دوسروں کے لیے۔‘‘ (سنن أبي داود، الجنائز، حدیث: ۳۲۰۸) تفصیل متعلقہ حدیث میں آئے گی۔ إن شاء اللہ۔"}],[2008,"عامر بن سعد بن ابی وقاص سے روایت ہے کہ سعد رضی اللہ عنہ کی جب وفات ہونے لگی تو انہوں نے کہا: میرے لیے بغلی قبر کھدوانا، اور اینٹیں کھڑی کرنا جیسے رسول اللہ صلی اللہ علیہ وسلم علیہ السلام کے لیے کی گئی تھی۔","الألباني: صحيح",{"u2":"حضرت عامر بن سعد سے روایت ہے کہ جب (والد محترم) حضرت سعد رضی اللہ عنہ کی وفات کا وقت قریب آیا تو انھوں نے فرمایا: میرے لیے لحد بنانا اور پھر اینٹیں لگا دینا جیسا کہ رسول اللہ صلی اللہ علیہ وسلم کے لیے کیا گیا۔","f2":"’’اینٹیں لگا دینا‘‘ یعنی لحد کا منہ بند کرنے کے لیے۔ اور یہ سستا طریقہ ہے جبکہ شق کو ڈھانپنا مہنگا ہے۔"}],[2009,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بغلی قبر ہم (مسلمانوں) کے لیے ہے، اور صندوقی قبر دوسروں کے لیے ہے\"۱؎۔\n§وضاحت\n۱؎: یعنی اہل کتاب کے لیے ہے، مقصود یہ ہے کہ بغلی قبر افضل ہے، اور ایک قول یہ ہے کہ «اللحد لنا» کا مطلب «اللحد لي» ہے، یعنی بغلی قبر میرے لیے ہے، جمع کا صیغہ تعظیم کے لیے ہے، یا «اللحدلنا» کا مطلب «اللحد اختیارنا» ہے، یعنی بغلی قبر ہماری پسندیدہ قبر ہے، اس کا یہ مطلب نہیں کی صندوقی مسلمانوں کے لیے ہے، کیونکہ یہ بات ثابت ہے کہ رسول اللہ صلی اللہ علیہ وسلم کے عہد میں مدینہ میں قبر کھودنے والے دو شخص تھے ایک بغلی بنانے والا دوسرا شخص صندوقی بنانے والا، اگر صندوقی ناجائز ہوتی تو انہیں اس سے روک دیا جاتا۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’لحد ہمارے لیے ہے اور شق دوسروں کے لیے۔‘‘","f2":"(۱) یہ روایت اگرچہ اس سند سے ضعیف ہے لیکن دیگر شواہد کی وجہ سے بعض حضرات کے نزدیک صحیح ہے اور یہی بات درست ہے۔ امام ترمذی رحمہ اللہ نے جامع ترمذی میں ان شواہد کی تصریح فرمائی ہے۔ دیکھیے: (جامع الترمذي، حدیث: ۱۰۴۵) (۲) ’’دوسروں کے لیے‘‘ مسند احمد میں جریر بن عبداللہ رضی اللہ عنہ کی حدیث میں ہے اور ’’شق اہل کتاب کے لیے ہے۔‘‘ (مسسند أحمد: ۳۶۳/۴) لیکن اس سے یہ مراد نہیں کہ مسلمانوں کے لیے شق جائز نہیں کیونکہ بعض علاقوں میں لحد ممکن ہی نہیں، شق ہی بنانی پڑتی ہے۔ ممکن ہے نبی صلی اللہ علیہ وسلم کا مطلب بھی یہ ہو کہ بقیع الغرقد (جنت البقیع) کی زمین سخت ہے، لحد بن سکتی ہے، لہٰذا ہمارے لیے لحد بہتر ہے، ورنہ رسول اللہ صلی اللہ علیہ وسلم کی قبر مبارک کے لیے بھی دونوں آدمیوں (لحد اور شق والے) کو پیغام بھیجا گیا تھا۔ اتفاقاً لحد بنانے والے صحابی پہلے آگئے، اس لیے باتفاق صحابہ لحد بنائی گئی۔ (سنن ابن ماجہ، الجنائز، حدیث: ۱۵۵۷) ممکن ہے اہل کتاب کے ہاں شق کا رواج ہو۔ آپ نے امتیاز کے لیے مسلمانوں کو لحد بنانے کا مشورہ دیا ہو۔ (نیز دیکھیے، فوائد حدیث: ۲۰۰۹،۲۰۱۰)"}],[2010,"ہشام بن عامر انصاری رضی اللہ عنہ کہتے ہیں کہ ہم نے (غزوہ) احد کے دن رسول اللہ صلی اللہ علیہ وسلم سے شکایت کی، ہم نے عرض کیا: اللہ کے رسول! ہر ایک آدمی کے لیے (الگ الگ) قبر کھودنا ہمارے لیے دشوار ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"کھودو اور گہرا کھودو اچھی طرح کھودو، اور دو دو تین تین (افراد) کو ایک ہی قبر میں دفن کر دو\"، تو لوگوں نے پوچھا: اللہ کے رسول! پہلے ہم کسے رکھیں؟ آپ نے فرمایا: \"پہلے انہیں رکھو جنہیں قرآن زیادہ یاد ہو\"۔ ہشام رضی اللہ عنہ کہتے ہیں: ایک ہی قبر میں رکھے جانے والے تین افراد میں سے میرے والد تیسرے فرد تھے۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ سے روایت ہے کہ ہم نے جنگ احد کے دن رسول اللہ صلی اللہ علیہ وسلم سے شکایت کی اور کہا کہ ہر میت کے لیے الگ الگ قبر کھودنا ہمارے لیے بہت مشکل ہے تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قبریں کھودو، گہری کھودو اور اچھی طرح کھودو۔ اور دو دو، تین تین آدمیوں کو ایک قبر میں دین کر دو۔‘‘ لوگوں نے پوچھا: اے اللہ کے رسول! ہم آگے کس میت کو رکھیں؟ آپ نے فرمایا: ’’جو زیادہ قرآن پڑھا ہوا ہو۔‘‘ راویٔ حدیث حضرت ہشام نے کہا کہ میرے والد سمیت تین آدمی ایک قبر میں دفن کیے گئے۔ (رضی اللہ عنہم)","f2":"(۱) ’’بہت مشکل ہے‘‘ کیونکہ شہدائ زیادہ تھے، باقی ماندہ لوگ زخموں سے چور اور اس عظیم نقصان سے دل برداشتہ تھے۔ ایسی حالت میں ایک دن میں ستر قبریں نکالنا نہایت مشکل تھا۔ امن کی حالت میں بھی اتنی قبریں بنانا بہت مشکل کام ہے۔ (۲) ’’گہری کھودو‘‘ کیونکہ اس طرح میت جانوروں اور بارش وغیرہ سے بہت محفوظ رہے گی، نیز لحد گرنے کا خطرہ نہیں رہے گا۔ (۳) ضرورت پڑنے پر ایک سے زائد آدمی بھی ایک قبر میں دفن کیے جا سکتے ہیں مگر کفن الگ الگ ہونا ضروری ہے، البتہ عورت کو غیر محرم کے ساتھ دفن نہ کیا جائے، ہاں ماں بچے کو اکٹھا دفن کرنے میں کوئی حرج نہیں۔"}],[2011,"ہشام بن عامر انصاری رضی اللہ عنہ کہتے ہیں کہ جس دن احد کی لڑائی ہوئی تو جن مسلمانوں کو مارا جانا تھا مارے گئے، اور جسے زخمی ہونا تھا زخمی ہوئے، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(قبریں) کھودو اور چوڑی کھودو، اور ایک ہی قبر میں دو دو تین تین لوگوں کو دفنا دو، اور جنہیں قرآن زیادہ یاد ہو انہیں (قبر میں) پہلے رکھو\"۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ جنگ احد کے دن بہت زیادہ مسلمان شہید ہوگئے۔ (باقی ماندہ) لوگوں کو بہت زخم لگے تو رسول اللہ صلی اللہ علیہ وسلم نے (از راہ شفقت) فرمایا: ’’کھودو اور کشادہ کھودو اور دو دو، تین تین شہداء کو ایک ایک قبر میں دفن کر دو اور جس نے قرآن مجید زیادہ پڑھا ہو، اسے آگے رکھو۔‘‘","f2":"وسیع قبر میں دفن کرنا آسان ہوگا اور قبر گرنے سے محفوظ رہے گی، اس لیے یہ مستحب ہے۔"}],[2012,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جس وقت دفنائے گئے آپ کے نیچے ایک سرخ چادر رکھی گئی ۱؎۔\n§وضاحت\n۱؎: مشہور یہ ہے کہ اسے نبی اکرم صلی اللہ علیہ وسلم کے بعض غلاموں نے صحابہ کرام رضی اللہ عنہم کو بتائے بغیر بچھایا تھا، ابن سعد نے طبقات :(۲/۲۹۹ ) میں وکیع کا قول نقل کیا ہے کہ یہ نبی اکرم صلی اللہ علیہ وسلم کے لیے خاص ہے، اور حسن بصری سے ایک روایت ہے کہ زمین گیلی تھی اس لیے ایک سرخ چادر بچھائی گئی جسے آپ اوڑھتے تھے، اور حسن بصری ہی سے ایک دوسری روایت ہے جس میں ہے «قال رسول اللہ صلی اللہ علیہ وسلم افرشوا لي قطیفتي في لحدي، فإن الأرض لم تسلط علی أجساد الأنبیائ»۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ جب رسول اللہ صلی اللہ علیہ وسلم کو دفن کیا گیا تو آپ کے نیچے سرخ رنگ کی ایک چادر بچھائی گئی۔","f2":"مسنون کفن تین کپڑے ہی ہیں۔ آج کل عمل بھی اسی پر ہے، البتہ اگر نیچے زائد چادر بچھا لی جائے تو اس حدیث کی رو سے جائز ہے۔ مزید تفصیل کے لیے دیکھیے: (ذخیرۃ العقبی شرح سنن النسائي: ۳۶۴/۱۹- ۳۶۹)"}],[2013,"عقبہ بن عامر جہنی رضی اللہ عنہ کہتے ہیں کہ تین اوقات ایسے ہیں جن میں رسول اللہ صلی اللہ علیہ وسلم ہمیں نماز پڑھنے (اور) اپنے مردوں کو قبر میں دفنانے سے منع فرماتے تھے: ایک جس وقت سورج نکل رہا ہو یہاں تک کہ بلند ہو جائے، اور دوسرے جس وقت ٹھیک دوپہر ہو یہاں تک کہ سورج ڈھل جائے، اور (تیسرے جس وقت سورج ڈوبنے کے لیے مائل ہو رہا ہو۔","الألباني: صحيح",{"u2":"حضرت عقبہ بن عامر جہنی رضی اللہ عنہ بیان کرتے ہیں کہ تین اوقات ایسے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ان میں نماز پڑھنے اور میت کے دفن کرنے سے منع فرمایا: جب سورج طلوع ہو رہا ہو حتی کہ کچھ اونچا ہو جائے اور جب سورج نصف النہار پر ہو حتی کہ ڈھل جائے۔ اور جب سورج غروب ہونے کے عین قریب ہو۔","f2":"(۱) حدیث کے ظاہر الفاظ سے ان تین اوقات میں نماز پڑھنے اور میت کو دفن کرنے کی ممانعت ثابت ہوتی ہے۔ بعض علماء نے اگرچہ اس کا مطلب یہ بیان کیا ہے کہ ان اوقات میں نماز جنازہ پڑھنا منع ہے، دفن کیا جا سکتا ہے لیکن یہ تاویل بعید ہے، اس لیے بات وہی صحیح ہے جو حدیث کے ظاہر الفاظ سے معلوم ہوتی ہے۔ اگر کوئی مجبوری ہو تو پھر ان اوقات میں دفنانے کی گنجائش ہے جیسا کہ آئندہ حدیث میں آ رہا ہے۔ (۲) اس روایت سے متعلقہ دوسرے مباحث حدیث نمبر ۵۶۱ اور ۱۸۹۶ میں گزر چکے ہیں۔"}],[2014,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ (ایک بار) رسول اللہ صلی اللہ علیہ وسلم نے خطاب فرمایا (آپ نے اس میں) اپنے اصحاب میں سے ایک شخص کا ذکر کیا جو مر گیا تھا، اسے رات ہی میں دفنا دیا گیا، اور ایک گھٹیا کفن میں کفنایا گیا، تو رسول اللہ صلی اللہ علیہ وسلم نے سختی سے منع فرما دیا کہ کوئی رات میں دفنایا جائے، سوائے اس کے کہ وہ اس کے لیے مجبور کر دیا جائے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے خطبہ ارشاد فرمایا اور اپنے صحابہ میں سے ایک شخص کا ذکر کیا جو (رات کو) فوت ہوگیا تھا اور اسے رات ہی کو ناقص اور غیر مناسب کفن میں دفن کر دیا گیا تھا، لہٰذا رسول اللہ صلی اللہ علیہ وسلم نے کسی میت کو رات کے وقت دفن کرنے سے منع فرما دیا الا یہ کہ اشد مجبوری ہو۔","f2":"(۱) یہ حدیث صحیح مسلم (۹۴۳) میں بھی ہے، اس میں یہ اضافہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے رات کے وقت میت کو دفن کرنے پر ڈانٹا سوائے اس صورت کے کہ اس کی نماز جنازہ پڑھ لی گئی ہو۔ اس سے بظاہر یہ معلوم ہوتا ہے کہ انھوں نے اس صحابی کی نماز جنازہ نہیں پڑھی تھی لیکن ایسا ہونا بعید ازقیاس ہے، اس لیے شیخ البانی رحمہ اللہ نے اس کے معنی یہ کیے ہیں: اگر نماز جنازہ دن کے وقت پڑھ لی گئی ہو تو پھر رات کے وقت دفنانا جائز ہے کیونکہ آپ کے فرمان ’’سوائے مجبوری کے‘‘ کا یہ مفہوم نہیں ہے کہ مجبوری کے وقت نماز جنازہ ترک کر دی جائے، بلکہ اس کا مطلب ہے کہ مجبوری کے وقت رات کو دفن کرنا جائز ہے۔ (۲) رات کے وقت نماز جنازہ جائز ہے یا نہیں؟ اس میں راجح بات یہ ہے کہ افضل تو یہی ہے کہ دن کے وقت نماز جنازہ ادا کی جائے تاکہ زیادہ لوگ شامل ہوسکیں کیونکہ یہ شرعاً مطلوب ہے، البتہ بوقت ضرورت رات کے وقت بھی نماز جنازہ ادا کی جا سکتی ہے جیسا کہ صحیح روایات سے ثابت ہے۔"}],[2015,"ہشام بن عامر انصاری رضی اللہ عنہ کہتے ہیں کہ جب (غزوہ) احد کا دن آیا، تو لوگوں کو سخت پریشانی ہوئی، نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"قبریں کھودو اور اسے چوڑی کھودو، اور ایک ہی قبر میں دو دو تین تین دفنا دو\"، تو لوگوں نے عرض کیا: اللہ کے رسول! پہلے کسے رکھیں؟ آپ نے فرمایا: \"پہلے اسے رکھو جسے قرآن زیادہ یاد ہو\"۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ جنگ احد کے دن لوگوں کو سخت تکلیف پہنچی تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’قبریں کھودو، کشادہ کھودو اور دو دو، تین تین شہداء کو ایک ایک قبر میں دفن کرو۔‘‘ انھوں نے کہا: اے اللہ کے رسول! ہم کس کو آگے (قبلے کی طرف) رکھیں؟ آپ نے فرمایا: ’’جو ان میں سے زیادہ قرآن پڑھا ہوا ہو۔‘‘","f2":"تفصیل کے لیے دیکھیے، حدیث: ۲۰۱۲۔"}],[2016,"ہشام بن عامر انصاری رضی اللہ عنہ کہتے ہیں کہ (غزوہ) احد کے دن (لوگ) شدید زخمی ہوئے (اور جاں بحق ہو گئے) تو رسول اللہ صلی اللہ علیہ وسلم سے اس کی شکایت کی گئی ۱؎، آپ نے فرمایا: \"(قبریں) کھودو، انہیں کشادہ اور اچھی بناؤ، اور ایک (ہی) قبر میں دو دو تین تین کو دفن کرو، اور جسے قرآن زیادہ یاد ہوا سے آگے رکھو\"۔\n§وضاحت\n۱؎: یعنی آپ سے اس پریشانی کا ذکر کیا گیا کہ اتنے لوگوں کے لیے قبریں کھودنا بہت مشکل امر ہے، انہیں کیسے دفنایا جائے۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ سے روایت ہے کہ جنگ احد میں لوگوں کو زخموں کی سخت تکلیف تھی۔ اس بات کی شکایت رسول اللہ صلی اللہ علیہ وسلم سے کی گئی۔ آپ نے فرمایا: ’’قبریں کھودو، کشادہ کھودو اور اچھی طرح کھودو اور دو دو، تین تین کو ایک ایک قبر میں دفن کرو۔ اور جو شخص زیادہ قرآن پڑھا ہوا ہو، اسے آگے رکھو۔‘‘"}],[2017,"ہشام بن عامر انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"(قبریں) کھودو، اور انہیں خوبصورت بناؤ، اور دو دو تین تین کو دفن کرو، اور جسے قرآن زیادہ یاد ہو انہیں پہلے رکھو\"۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’دقبریں کھودو اور اچھی طرح کھودو اور دو دو، تین تین کو (اکٹھا) دفن کرو۔ اور جو شخص قرآن مجید زیادہ پڑھا ہوا ہو، اسے آگے رکھو۔‘‘"}],[2018,"ہشام بن عامر انصاری رضی اللہ عنہ کہتے ہیں کہ (غزوہ) احد کے دن میرے والد قتل کئے گئے، تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"(قبریں) کھودو اور انہیں کشادہ اور اچھی بناؤ، اور (ایک ہی) قبر میں دو دو تین تین کو دفنا دو، اور جنہیں قرآن زیادہ یاد ہو انہیں پہلے رکھو\"، چنانچہ میرے والد تین میں کے تیسرے تھے، اور انہیں قرآن زیادہ یاد تھا تو وہ پہلے رکھے گئے۔","الألباني: صحيح",{"u2":"حضرت ہشام بن عامر رضی اللہ عنہ بیان کرتے ہیں کہ جنگ احد کے دن میرے والد شہید ہوگئے۔ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’قبریں کھودو کشادہ کھودو، اور اچھی طرح کھودو۔ اور دو دو، تین تین کو ایک ایک قبر میں دفن کرو اور جس نے قرآن مجید زیادہ پڑھا ہو، اسے آگے رکھو۔‘‘ میرے والد تین میں سے ایک تھے (جو ایک ہی قبر میں دفن کیے گئے، یعنی ان کے ساتھ دو اور آدمی دفن کیے گئے۔) چونکہ وہ (میرے والد) قرآن مجید زیادہ پڑھے ہوئے تھے، لہٰذا انھیں (قبلے کی طرف) آگے رکھا گیا۔","f2":"علم انسان کا خاصہ ہے، لہٰذا انسانوں میں فضیلت کی بنیاد علم ہے۔ اور قرآن مجید اصل علم ہے، اس لیے نبی صلی اللہ علیہ وسلم نے اسے معیار فضیلت بنایا۔"}],[2019,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم عبداللہ بن ابی کو قبر میں داخل کر دئیے جانے کے بعد آئے، تو آپ نے اسے (نکالنے کا) حکم دیا، چنانچہ وہ نکالا گیا، آپ نے اسے اپنے دونوں گھٹنوں پر بٹھایا، اور اس پر تھو تھو کیا، اور اسے اپنی قمیص پہنائی، واللہ اعلم ۱؎۔\n§وضاحت\n۱؎: اس پر تھو تھو کرنے اور اسے اپنی قمیص پہنانے میں کیا مصلحت پنہا تھی اسے اللہ تعالی ہی جانتا ہے، بعض لوگوں نے کہا: چونکہ اس نے آپ صلی اللہ علیہ وسلم کے چچا عباس رضی اللہ عنہ کو اپنی قمیص پہنائی تھی اس لیے آپ نے بدلے میں ایسا کیا، اور ایک قول یہ ہے کہ اس کے بیٹے کی دلجوئی کے لیے آپ نے ایسا کیا تھا۔ واللہ اعلم","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ فرماتے ہیں کہ عبداللہ بن ابی کو قبر میں رکھے جانے کے بعد نبی صلی اللہ علیہ وسلم تشریف لائے اور اسے باہر نکالنے کا حکم دیا، پھر آپ نے اسے اپنے گھٹنوں پر رکھا اور کسی قدر اپنا لعاب دہن اس پر ڈالا۔ اور اسے اپنی قمیص پہنائی۔ اللہ تعالیٰ ہی (اس کی مصلحت) جانتا ہے۔"}],[2020,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے عبداللہ بن ابی کو اس کی قبر سے نکلوایا، پھر اس کا سر اپنے دونوں گھٹنوں پر رکھا، اور اس پر تھو تھو کیا، اور اسے اپنی قمیص پہنائی۔ اور اس کی نماز (جنازہ) پڑھی، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے حکم دیا تو عبداللہ بن ابی کو اس کی قبر سے نکالا گیا، پھر آپ نے اس کا سر اپنے گھٹنوں پر رکھا۔ اور اس کے منہ میں اپنا لعاب دہن تھوکا۔ اسے اپنی قمیص پہنائی اور اس کا جنازہ پڑھا۔ (ان کاموں کی مصلحت) اللہ تعالیٰ ہی جانتا ہے۔","f2":"تفصیل کے لیے دیکھیے حدیث: ۱۹۰۱، ۱۹۰۲ - ۱۹۶۸۔"}],[2021,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ میرے والد کے ساتھ قبر میں ایک شخص اور دفن کیا گیا تھا، میرا دل خوش نہیں ہوا یہاں تک کہ میں نے اسے نکالا، اور انہیں علاحدہ دفن کیا۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ بیان کرتے ہیں کہ میرے والد (شہید احد) کے ساتھ قبر میں ایک اور شہید بھی دفنائے گئے تھے مگر میرے دل کو یہ اچھا نہ لگا حتی کہ میں نے ان کو نکال کر علیحدہ دفن کیا۔","f2":"یہ دفنانے سے چھ ماہ بعد کی بات ہے، اور ان کی میت بالکل اسی طح تھی جس طرح رکھی گئی تھی۔ رضی اللہ عنہ و أرضاہ۔ ثابت ہوا کہ اشد ضرورت ہو تو قبر کشائی کی جا سکتی ہے ورنہ اس سے بچنا بہتر ہے۔"}],[2022,"یزید بن ثابت رضی اللہ عنہ سے روایت ہے کہ وہ لوگ ایک دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ نکلے، تو آپ نے ایک نئی قبر دیکھی تو فرمایا: \"یہ کیا ہے؟\"لوگوں نے کہا: یہ فلاں قبیلے کی لونڈی (کی قبر) ہے، تو رسول اللہ صلی اللہ علیہ وسلم نے اسے پہچان لیا، وہ دوپہر میں مری تھی، اور آپ قیلولہ فرما رہے تھے، تو ہم نے آپ کو اس کی وجہ سے جگانا پسند نہیں کیا، تو رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اور اپنے پیچھے لوگوں کی صف بندی کی، اور آپ نے چار تکبیریں کہیں، پھر فرمایا: \"جب تک میں تمہارے درمیان ہوں جو بھی تم میں سے مرے اس کی خبر مجھے ضرور دو، کیونکہ میری نماز اس کے لیے رحمت ہے\"۔","الألباني: صحيح",{"u2":"حضرت یزید بن ثابت رضی اللہ عنہ سے مروی ہے کہ ایک دن ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ (بقیع کی طرف) نکلے تو آپ نے ایک تازہ قبر دیکھی۔ آپ نے فرمایا: ’’یہ قبر کیسی ہے؟‘‘ لوگوں نے کہا: اے اللہ کے رسول! یہ فلاں قبیلے کی فلاں لونڈی کی قبر ہے، پ نے اسے پہچان لیا، یہ ظہر کے وقت فوت ہوئی تھی۔ آپ اس وقت روزے کی حالت میں دوپہر کے وقت آرام فرما رہے تھے۔ ہم نے اس کی خاطر آپ کو جگانا مناسب نہ سمجھا۔ اللہ کے رسول صلی اللہ علیہ وسلم (قبر کے رخ) کھڑے ہوئے، اور اپنے پیچھے لوگوں کی صف بنائی اور آپ نے چار تکبیریں کہیں (یعنی مکمل جنازہ پڑھا۔) پھر فرمایا: ’’جب تک میں تم میں موجود ہوں، کوئی شخص بھی فوت ہو مجھے ضرور اطلاع کیا کرو کیونکہ میرا جنازہ پڑھنا اس کے لیے رحمت کا سبب ہے۔‘‘","f2":"کوئی میت بغیر جنازے کے دفن کر دی جائے تو اس صورت میں قبر پر جنازہ پڑھنا متفقہ مسئلہ ہے، البتہ نماز جنازہ کے ساتھ دفن کی جانے والی میت کا قبر پر جنازہ پڑھنا اختلافی مسئلہ ہے۔ یہ حدیث جواز کی دلیل ہے۔ عدم جواز کے قائلین اسے نبی صلی اللہ علیہ وسلم کا خاصہ بناتے ہیں مگر آپ کا ہر عمل اس کے مشروع عام ہونے کی دلیل ہوتا ہے جب تک کہ تخصیص کی دلیل نہ ہو اور یہاں تخصیص کی دلیل نہیں۔ علاوہ ازیں صحابہ کا ساتھ کھڑا ہونا تخصیص کے خلاف جاتا ہے، اگرچہ کہا جا سکتا ہے کہ صحابہ بالتبع کھڑے ہوئے تھے، بہرصورت جواز تو ثابت ہوتا ہے۔ مزید دیکھیے حدیث: ۱۹۷۱۔"}],[2023,"عامر بن شراحیل شعبی کہتے ہیں مجھے اس شخص نے خبر دی ہے جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک ایسی قبر کے پاس سے گزرا، جو الگ تھلگ تھی، تو آپ نے ان کی امامت کی، اور اپنے پیچھے ان کی صف بندی کی۔ سلیمان کہتے ہیں میں نے (شعبی) پوچھا: ابوعمرو! یہ کون تھے؟ انہوں نے کہا: ابن عباس رضی اللہ عنہما تھے۔","الألباني: صحيح",{"u2":"حضرت شعبی سے روایت ہے کہ مجھے اس صحابی نے بتایا جو رسول اللہ صلی اللہ علیہ وسلم کے ساتھ ایک علیحدہ بنی ہوئی قبر کے پاس سے گزرے تھے، آپ نے امامت فرمائی اور انھوں (ابن عباس اور دوسرے لوگوں) نے آپ کے پیچھے صف بندی کی۔ شعبی سے پوچھا گیا: وہ کون سے صحابی ہیں؟ انھوں نے کہا: حضرت ابن عباس رضی اللہ عنہما۔"}],[2024,"عامر بن شراحیل شعبی کہتے ہیں مجھے اس شخص نے خبر دی ہے جس نے نبی اکرم صلی اللہ علیہ وسلم کو دیکھا کہ آپ ایک الگ تھلگ قبر کے پاس سے گزرے، تو آپ نے اس کی نماز جنازہ پڑھی، اور اپنے پیچھے اپنے اصحاب کی صف بندی کی، پوچھا گیا: آپ سے کس نے بیان کیا ہے؟ تو انہوں نے کہا: ابن عباس رضی اللہ عنہما نے۔","الألباني: صحيح",{"u2":"حضرت شعبی رحمہ اللہ بیان کرتے ہیں کہ مجھے اس صحابی نے خبر دی جنھوں نے خود دیکھا تھا کہ رسول اللہ صلی اللہ علیہ وسلم ایک علیحدہ بنی ہوئی قبر کے قریب سے گزرے تو آپ نے اپنے صحابہ کی اپنے پیچھے صف بنائی اور جنازہ پڑھایا۔ (شعبی سے) پوچھا گیا: آپ کو کس صحابی نے بیان فرمایا؟ انھوں نے کہا: حضرت ابن عباس رضی اللہ عنہما نے۔"}],[2025,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں نبی اکرم صلی اللہ علیہ وسلم نے ایک عورت کی قبر پر اسے دفن کر دئیے جانے کے بعد نماز جنازہ پڑھی۔","الألباني: صحيح بما قبله",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم نے ایک عورت کی قبر پر اس کے دفن کیے جانے کے بعد جنازہ پڑھا۔"}],[2026,"جابر بن سمرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم ابودحداح رضی اللہ عنہ کے جنازے میں (شرکت کے لیے) نکلے، تو جب آپ لوٹنے لگے تو(آپ کے لیے) بغیر زین کے ننگی پیٹھ والا ایک گھوڑا لایا گیا، آپ (اس پر) سوار ہو گئے، اور ہم آپ کے ہمراہ پیدل چلنے لگے۔","الألباني: صحيح",{"u2":"حضرت جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم حضرت ابن وحداح رضی اللہ عنہ کے جنازے کے لیے نکلے (پیدل تشریف لے گئے)۔ جب واپس ہوئے تو آپ کے پاس بغیر کاٹھی کے گھوڑا لایا گیا۔ آپ سوار ہوگئے۔ ہم آپ کے ساتھ ساتھ پیدل چلتے رہے۔","f2":"جنازہ پڑھنے کے بعد واپسی پر سوار ہوکر آنا جائز ہے۔ اس میں کوئی اختلاف نہیں۔ جاتے وقت بھی سوار ہوکر جایا جا سکتا ہے۔ تفصیل کے لیے دیکھیے، حدیث: ۱۹۴۴ کے فوائد و مسائل۔"}],[2027,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا ہے کہ قبر پر قبہ بنایا جائے یا اس کو اونچا کیا جائے، یا اس کو پختہ بنایا جائے، سلیمان بن موسی کی روایت میں \"یا اس پر لکھا جائے\" کا اضافہ ہے ۱؎۔\n§وضاحت\n۱؎: یہ نہی مطلق ہے، اس میں میت کا نام اور اس کی تاریخ وفات تبرک کے لیے قرآن کی آیتیں، اور اسماء حسنٰی وغیرہ لکھنا سبھی داخل ہیں اور یہ سب کچھ منع ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے منع فرمایا کہ قبر پر کوئی عمارت بنائی جائے یا قبر پر اضافہ کیا جائے یا قبر کو پختہ بنایا جائے۔ راوی سلیمان بن موسیٰ نے یہ الفاظ زیادہ بیان کیے ہیں: یا اس پر کچھ لکھا جائے۔","f2":"(۱) ’’عمارت‘‘ یعنی قبر کو عمارت کی طرح اونچا بنانا یا قبر کے ارد گرد عمارت بنانا، خواہ قبر کی حفاظت کے لیے ہو یا زائرین کی سہولت کے لیے، بہرصورت منع ہے کیونکہ اس طرح قبر دیر تک باقی رہے گی۔ بعد میں آنے والوں کو تنگی ہوگی، نیز یہ قبر کی پوجا پاٹ کا سبب ہے۔ آج کل ایسی قبریں مجرموں اور نشیٔ لوگوں کا اڈہ بنی ہوئی ہیں۔ (۲) ’’اضافہ‘‘ قبر سے نکلنے والی مٹی کے علاوہ اور مٹی ڈالنا منع ہے کیونکہ اس طرح قبر شرعی حد سے بلند ہو جائے گی اور اسے ختم ہونے میں دیر لگے گی۔ یا اس سے مراد ضرورت سے زیادہ لمبی چوڑی قبر بنانا ہے، یہ بھی منع ہے کیونکہ اس سے جگہ تنگ ہوگی اور دوسرے لوگوں کے لیے مشکلات پیدا ہوں گی، نیز بے مقصد جگہ ضائع ہوگی۔ (۳) تحصیص، یعنی چونے وغیرہ سے پختہ کرنا کیونکہ اس سے مضبوطی اور پائیداری ہوتی ہے جبکہ شریعت کا منشا یہ ہے کہ قبر کچھ دیر کے لیے رہے، پھر ختم ہو جائے تاکہ آنے والوں کے لیے جگہ خالی ہو۔ بعض علماء نے می کے ساتھ قبر لیپنے کی اجازت دی ہے مگر اس حدیث سے معلوم ہوتا ہے کہ وہ مٹی قبر کی مٹی کے علاوہ نہ ہو بلکہ قبر ہی کی مٹی پر پانی ڈال کر ہاتھ پھیر دیا جائے، البتہ اگر کوئی قبر بیٹھ کر گڑھا بن جائے تو اسے الگ مٹی سے پر کیا جا سکتا ہے کیونکہ یہ مجبوری ہے۔ (۴) ’’لکھا جائے‘‘ مثلاً: نام و نسب اور پتہ وغیرہ یا تاریخ وفات یا قبرآن مجید کی آیات یا احادیث وغیرہ، گویا کچھ بھی لکھنا منع ہے کیونکہ یہ چیز قبر کو عرصۂ دراز تک باقی رکھنے کا سبب بنے گی۔ قرآن مجید وغیرہ لکھنا، اس لیے بھی منع ہے کہ قبر میں ٹوٹ پھوٹ ہوتی رہتی ہے اور یہ الفاظ مقدسہ کی بے حرمتی کا سبب بنے گی، نیز متعلقین کو تو قبر بغیر کتابت کے بھی معلوم ہوتی ہے اور عوام الناس کو اس اعلان کا کوئی فائدہ نہیں، لہٰذا لکھنا فضول ہے بلکہ ریا کاری ہے۔ (۵) عوام الناس میں کسی چیز کا رائج ہو جانا اس کے جواز کی دلیل نہیں جبکہ وہ صریح فرمانِ رسول صلی اللہ علیہ وسلم کے خلاف ہو جیسے مندرجہ بالا چیزیں۔ شرک بھی تو ہر دور میں محبوب عوام رہا ہے۔"}],[2028,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبروں کو پختہ بنانے ۱؎ یا اس پر عمارت بنانے ۲؎ یا اس پر کسی کے بیٹھنے ۳؎ سے منع فرمایا ہے۔\n§وضاحت\n۱؎: کیونکہ یہ فضول خرچی ہے اس سے کوئی فائدہ مردے کو نہیں ہوتا، دوسرے اس میں مردوں کی ایسی تعظیم ہے جو انسان کو شرک کی طرف لے جاتی ہے۔ ۲؎: قبہ اور گنبد وغیرہ بنانے کا بھی یہی معاملہ ہے۔ ۳؎: یعنی قضائے حاجت کے ارادے سے بیٹھنے یا بطور سوگ بیٹھنے سے منع فرمایا، یا یہ ممانعت میت کی توقیر و تکریم کی خاطر ہے کیونکہ اس سے میت کی تذلیل و توہین ہوتی ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قبروں کو پختہ کرنے یا ان پر عمارت بنانے یا ان پر بیٹھنے سے منع فرمایا ہے۔","f2":"’’بیٹھنے سے منع فرمایا‘‘ کیونکہ اس میں صاحب قبر کی بے حرمتی ہے یا بطور سوگ بیٹھنے سے روکا ہے یا مجاور بن کر بیٹھنا مراد ہے۔ بعض نے اس سے قضائے حاجت کے لیے بیٹھنا مراد لیا ہے۔ صحیح بات یہ ہے کہ مندرجہ بالا تمام صورتیں منع ہیں۔ اسی طرح قبر پر ٹیک لگانا بھی منع ہے کیونکہ اس میں بھی صاحب قبر کی بے حرمتی ہے۔"}],[2029,"جابر بن عبداللہ رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبروں کو پختہ کرنے سے منع فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت جابر رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے قبروں کو چونا گچ کرنے سے منع فرمایا ہے۔","f2":"اس زمانے میں جو کام چونے سے لیا جاتا تھا، آج کل وہ کام سیمنٹ سے لیا جاتا ہے، لہٰذا سیمنٹ کا استعمال بھی قبر پر منع ے۔ (مزید تفصیل کے لیے دیکھیے، حدیث: ۲۰۲۹)"}],[2030,"ثمامہ بن شفی کہتے ہیں کہ ہم فضالہ بن عبید رضی اللہ عنہ کے ساتھ سر زمین روم میں تھے کہ ہمارا ایک ساتھی وفات پا گیا، تو فضالہ رضی اللہ عنہ نے اس کی قبر (زمین کے برابر کرنے کا) حکم دیا، تو وہ برابر کر دی گئی ۱؎ پھر انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس کے برابر کرنے کا حکم دیتے سنا ہے۔\n§وضاحت\n۱؎: یعنی کوہان کی طرح بنائی جانے کے بجائے مسطح بنائی گئی، گو وہ زمین سے کچھ اونچی ہو، واللہ اعلم۔","الألباني: صحيح",{"u2":"حضرت ثمامہ بن شفی بیان کرتے ہیں کہ ہم حضرت فضالہ بن عبید رضی اللہ عنہ کے ساتھ رومیوں کے علاقے میں تھے کہ ہمارا ایک ساتھی فوت ہوگیا۔ تو حضرت فضالہ نے حکم دیا اور اس کی قبر ہموار کر دی گئی، پھر فرمانے لگے: میں نے رسول اللہ صلی اللہ علیہ وسلم سے سنا آپ قبروں کو ہموار کرنے کا حکم دیتے تھے۔","f2":"اس حدیث کا یہ مطلب نہیں کہ قبر کو زمین کے بالکل ہموار بنایا جائے کیونکہ اس طرح تو قبر اور غیر قبر کا پتا ہی نہیں چلے گا، بلکہ اس کا مطلب یہ ہے کہ قبر زیادہ اونچی نہ ہو بلکہ قبر کی اپنی مٹی کو ہموار کر دیا جائے، مزید مٹی نہ ڈالی جائے۔ یا اس حدیث کا مطلب یہ ہے کہ قبر کو زمین کی طرح ہموار، یعنی چپٹی (مسطح) بنایا جائے، ٹیلے کی طرح نہ بنائی جائے تاکہ قبر اور ٹیلے میں امتیاز ہوسکے اور اس کے آداب ملحوظ رکھے جا سکیں۔ اور اگر ظاہر معنی مراد ہو (یعنی قبر کو زمین کے بالکل ہموار کر دیا جائے) تو یہ اس قبر کی اصلاح ہوگی جسے بہت اونچی بنا دیا گیا ہو یا جہاں شرک کا اندیشہ ہو، تاکہ اس پر غیرشرعی کام نہ ہوسکیں۔ اس کا نام و نشان مٹا دیا جائے۔ کفار و مشرکین کی قبروں کا نام و نشان مٹایا جا سکتا ہے، جس طرح رسول اللہ صلی اللہ علیہ وسلم نے مسجد نبوی کے احاطے کی قبروں کو اکھاڑ دیا تھا۔"}],[2031,"ابوہیاج (حیان بن حصین اسدی) کہتے ہیں کہ علی رضی اللہ عنہ نے کہا: کیا میں تمہیں اس کام پر نہ بھیجوں جس پر رسول اللہ صلی اللہ علیہ وسلم نے مجھے بھیجا تھا: تم کوئی بھی اونچی قبر نہ چھوڑنا مگر اسے برابر کر دینا، اور نہ کسی گھر میں کوئی مجسمہ (تصویر) چھوڑنا مگر اسے مٹا دینا۔","الألباني: صحيح",{"u2":"حضرت ابو ہیاج سے منقول ہے، حضرت علی رضی اللہ عنہ نے مجھ سے فرمایا: کیا میں تجھے اس کام پر نہ بھیجو جس پر مجھے رسول اللہ صلی اللہ علیہ وسلم نے بھیجا تھا کہ تو کوئی بلند قبر نہ چھوڑ مگر اسے ہموار کر دے اور نہ کسی گھر میں کوئی بت یا تصویر چھوڑ مگر اسے توڑ پھوڑ دے۔","f2":"(۱)\n’’بلند قبر‘‘ جو خود عمارت کی طرح اونچی ہو یا جس پر عمارت ہو، ورنہ جائز حد تک، یعنی ایک بالشت زمین سے اونچی قبر کو قائم رکھا جائے گا تاکہ اس پر قبر کے احکام و آداب لاگو ہوں کیونکہ قبر اور عام زمین میں امتیاز تو ضروری ہے۔ اس سلسلے میں حدیث: ۲۰۳۲ کا فائدہ ملحوظ خاطر رہے۔ (۲) ’’تصویر‘‘ یعنی کسی بھی جان دار کی تصویر یا مجسمہ جو پتھر وغیرہ سے بنایا گیا ہو (تبھی اس کے معنی بت کیے گئے ہیں) خواہ اس کی پوجا ہوتی ہو یا نہ۔ اسے بھی اس حد تک توڑ پھوڑ دیا جائے کہ اس کا سرچہرہ وغیرہ قائم نہ رہے بلکہ ایک عام پتھر کی طرح رہ جائے۔ یاد رہے یہاں ذی روح کا مجسمہ مراد ہے، انسان ہو یا حیوان کیونکہ حیوانات کی بھی تو پوجا کی جاتی رہی ہے۔"}],[2032,"بریدہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"میں نے تمہیں قبروں کی زیارت سے منع کیا تھا تو اب تم اس کی زیارت کیا کرو ۱؎، اور میں نے قربانی کے گوشت کو تین دن سے زیادہ رکھنے سے منع کیا تھا تو اب جب تک جی چاہے رکھو، اور میں نے تمہیں مشک کے علاوہ کسی اور برتن میں نبیذ (پینے) سے منع کیا تھا، تو سارے برتنوں میں پیو (مگر) کسی نشہ آور چیز کو مت پینا\"۔\n§وضاحت\n۱؎: قبروں کی زیارت کی ممانعت ابتدائے اسلام میں تھی تاکہ یہ چیز قبر پرستی اور مردوں سے مدد مانگنے اور فریاد کرنے کا ذریعہ نہ بن جائے پھر جب توحید کی تعلیم دلوں میں بیٹھ گئی، تو آپ صلی اللہ علیہ وسلم نے اس کی اجازت دے دی۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’میں نے تمھیں قبروں کی زیارت سے روکا تھا، اب تمھیں قبروں کی زیارت کرنے (قبرستان میں جانے) کی اجازت ہے۔ (اسی طرح) میں نے تمھیں تین دن سے زیادہ قربانی کا گوشت رکھنے سے منع کیا تھا، اب تم رکھ سکتے ہو، جب تک تمھارا دل چاہے۔ (اسی طرح) می نے تمھیں مشکیزے کے علاوہ کسی اور برتن میں نبیذ بنانے سے روکا تھا، اب تم ہر قسم کے برتن میں نبیذ بنا سکتے ہو، البتہ نشے والا نبیذ نہ پینا۔‘‘","f2":"(۱) بعض کام ہمیشہ کے لیے حرام ہوتے ہیں۔ ان کے جواز کا تصور بھی نہیں کیا جا سکتا، مگر کچھ کام بذات خود جائز ہوتے ہیں لیکن کسی وقتی مصلحت کی خاطر انھیں ممنوع قرار دے دیا جاتا ہے۔ مصلحت گزر جانے کے بعد وہ اپنے اصلی حکم پر آ جاتے ہیں۔ حدیث میں مذکور تینوں کام اسی نوعیت کے ہیں۔ قبروں پر جانا، تین دن سے اوپر قربانی کا گوشت کھانا اور نبیذ پینا جائز کام ہیں، مگر بعض نقصانات سے بچنے کے لیے ان سے روکا کیا جب نقصان کا خطرہ نہ رہا تو جواز کا اعلان فرما دیا گیا۔ (۲) رسول اکرم صلی اللہ علیہ وسلم کی بعثت کے ابتدائی دور میں شرک عام تھا۔ بتوں اور قبروں کی پوجا کھلے عام تھی، اس لیے رسول اللہ صلی اللہ علیہ وسلم نے مسلمانوں کو قبروں پر جانے سے روک دیا تاکہ شرک کی طرف ذہن متوجہ ہی نہ ہو۔ جب توحید عام ہوگئی اور ذہن پختہ ہوگئے، شرک کا امکان نہ رہا تو آپ صلی اللہ علیہ وسلم نے قبروں پر جانے کی اجازت دے دی تاکہ موت یاد رہے۔ افسوس کا مقام ہے کہ اب پھر قبروں پر دعا و پکار ہوتی ہے۔ موت کی یاد کی بجائے شرک کی یاد تازہ ہوتی ہے، لہٰذا اس حدیث کی روشنی میں ایسی قبروں پر جانا منع ہے جن کی پوجا ہوتی ہے اور جنھیں آج کی اصطلاحم یں ’’مزار‘‘ کہا جاتا ہے۔ (۳) ’’قربانی کا گوشت‘‘ ابتدا میں اکثر صحابہ فقیر تھے۔ خال خال لوگ قربانی کرسکتے تھے، زیادہ تر مسلمان غریب اور مسکین تھے، اس لیے آپ نے تین دن سے اوپر قربانی کا گوشت رکھنے سے روک دیا تھا، پھر جب غنائم کی کثرت ہوگئی اور قربانیاں عام ہوگئیں اور لوگوں کو حاجت نہ رہی تو آپ نے اصلی حکم بحال فرما دیا کہ جب تک چاہو، کھاؤ، البتہ کسی سائل کو محروم نہ رکھا جائے اور نہ پڑوسی ہی محروم رہے۔ (۴) ’’نبیذ‘‘ ابتدائی دور میں لوگ مے نوشی کے عادی تھے۔ تھوڑا بہت نشہ تو انھیں محسوس ہی نہ ہوتا تھا، اس لیے جب شراب حرام ہوئی تو آپ نے ان برتنوں میں نبیذ بنانے سے روک دیا جو شراب بنانے کے لیے استعمال ہوتے تھے کیونکہ ان کی ساخت ایسی تھی کہ ان میں جلد نشہ پیدا ہوتا تھا، امکان تھا کہ اگر ان برتنوں میں نبیذ کی اجازت دی گئی تو اولاً شراب کی یاد باقی رہے گی، ثانیاً نبیذ میں نشہ پیدا ہو جائے گا اور انھیں پتا نہیں چلے گا، اس لیے شراب کے برتنوں سے مستقل روک دیا گیا لیکن جب شراب ذہنوں سے محو ہوگئی اور طبائع میں نشے کی اثرات نہ رہے تو رسول اللہ صلی اللہ علیہ وسلم نے اصلی حکم بحال فرما دیا کہ کسی بھی برتن میں نبیذ بنائی جا سکتی ہے کیونکہ برتن کسی چیز کو حرام نہیں کرتا۔ حرام کرنے والی چیز تو نشہ ہے، اگر نشہ پیدا نہ ہو تو کسی بھی برتن میں نبیذ بنانے میں کوئی حرج نہیں۔ (۵) اس حدیث سے معلوم ہوا کہ حاکم وقت یا مفتی اور قاضی کسی چیز کو جائز ہونے کے باوجود وقتی طور پر ممنوع کرسکتے ہیں جب کسی مفسدے اور خرابی کا حقیقی خطرہ ہو، مگر یہ پابندی عارضی ہوگی۔ جوں ہی خرابی کا خطرہ ختم ہو تو وہ چیز دوبارہ جائز ہو جائے گی۔ شرعاً جائز امر کو مستقل طور پر ممنوع قرار نہیں دیا جا سکتا، ہاں جزوی یا عارضی طور پر پابندی ممکن ہے بشرطیکہ کوی ٹھوس وجہ موجود ہو۔"}],[2033,"بریدہ رضی اللہ عنہ سے روایت ہے کہ وہ ایک مجلس میں تھے جس میں رسول اللہ صلی اللہ علیہ وسلم (موجود) تھے، تو آپ نے فرمایا: \"میں نے تمہیں قربانی کا گوشت تین دن سے زیادہ کھانے سے منع کیا تھا (تو اب تم) کھاؤ، کھلاؤ اور جب تک جی چاہے رکھ چھوڑو، اور میں نے تم سے ذکر کیا تھا کہ کدو کی تمبی، تار کول ملے ہوئے، اور لکڑی کے اور سبز اونچے گھڑے کے برتنوں میں نبیذ نہ بناؤ، (مگر اب) جس میں مناسب سمجھو بناؤ، اور ہر نشہ آور چیز سے پرہیز کرو، اور میں نے تمہیں قبروں کی زیارت سے روکا تھا (تو اب) جو بھی زیارت کرنا چاہے کرے، البتہ تم زبان سے بری بات نہ کہو\"۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ بیان کرتے ہیں کہ میں ایک ایسی مجلس میں تھا جس میں رسول اللہ صلی اللہ علیہ وسلم بھی تشریف فرما تھے۔ آپ نے فرمایا: ’’میں نے تمھیں تین دن سے زائد قربانی کا گوشت کھانے سے منع کیا تھا لیکن اب تم کھاؤ، دوسروں کو کھلاؤ اور جب تک چاہو، رکھو۔ (اسی طرح) میں نے تمھیں کہا تھا کہ ان برتنوں میں نبیذ نہ بناؤ، یعنی کدو کا برتن، تارکول ملا ہوا برتن، کھجور کی جڑ کا برتن اور مسام بند مٹکا، لیکن اب جس برتن میں چاہو نبیذ بناؤ، البتہ ہر نشے والی چیز سے بچو۔ (اسی طرح) میں نے تمھیں قبروں کی زیارت سے روکا تھا لیکن اب جو قبر کی زیارت کے لیے جانا چاہے، جائے مگر (وہاں جاکر) کوئی غلط بات نہ کہو۔‘‘","f2":"’’غلط بات‘‘ مثلاً: ششرکیہ بات، نوحہ، رونا دھونا وغیرہ۔ عورتیں اتنا ضبط نہیں رکھتیں، لہٰذا وہ کبھی کبھار ہی جا سکتی ہیں، تاہم جن عورتوں سے یہ خطرہ نہ ہو، ان کے لیے قبرستان جانے کی اجازت ہے۔"}],[2034,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے اپنی ماں کی قبر کی زیارت کی، تو آپ خود رو پڑے اور جو آپ کے اردگرد تھے انہیں بھی رلا دیا، اور فرمایا: \"میں نے اپنے رب سے اجازت چاہی کہ میں ان کے لیے مغفرت طلب کروں تو مجھے اجازت نہیں ملی، (تو پھر) میں نے ان کی قبر کی زیارت کرنے کی اجازت مانگی تو مجھے اجازت دے دی گئی، تم لوگ قبروں کی زیارت کیا کرو کیونکہ یہ تمہیں موت کی یاد دلاتی ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم اپنی والدہ کی قبر دیکھنے گئے تو خود بھی روئے اور ساتھیوں کو بھی رلایا اور فرمایا: ’’میں نے اپنے رب تعالیٰ سے اجازت طلب کی تھی کہ میں اپنی والدہ کے لیے بخشش کی دعا کروں لیکن مجھے اجازت نہیں دی گئی، پھر میں نے اجازت طلب کی کہ ان کی قبر دیکھنے جاؤں تو مجھے اجازت دے دی گئی۔ تم بھی قبروں کی زیارت کیا کرو کیونکہ وہ موت کو یاد دلاتی ہیں۔‘‘","f2":"(۱) امام صاحب رحمہ اللہ نے استغفار کی اجازت نہ ملنے سے یہ نتیجہ اخذ کیا کہ آپ کی والدہ اسلام سے قبل فوت ہوگئی تھیں اور ایسے لوگوں کے لیے دعائے مغفرت کی ممانعت ہے۔ (۲) رسول اللہ صلی اللہ علیہ وسلم ابھی بچپن کی عمر میں تھے جب آپ کی والدہ کی وفات ہوگئی تھی۔ ماں، باپ کی قبر کی زیارت کی خواہش ایک فطری امر ہے جس پر شرعاً بھی کوئی پابندی نہیں۔ قبر کی زیارت کے موقع پر رونا بھی فطری چیز ہے، خصوصاً جبکہ آپ نے عالم ہوش میں پہلی دفعہ اپنی والدہ کی قبر دیکھی تھی۔ اللہ جانے! کس قسم کے جذبات محبت و پیار آپ کےدل میں امنڈ آئے ہوں گے، ممتا کوئی معمولی چیز نہیں۔ (۳) والدین کے ساتھ حسن سلوک سے پیش آنے کے لیے ان کا مسلمان ہونا ضروری نہیں، وہ مسلمان ہوں یا کافر و مشرک ان کے ساتھ حسن سلوک سے پیش آنا اولاد کا فرض ہے۔"}],[2035,"مسیب بن حزن رضی اللہ عنہما کہتے ہیں کہ جب ابوطالب کی وفات کا وقت آیا تو نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آئے، اور ابوجہل اور عبداللہ بن ابی امیہ دونوں ان کے پاس (پہلے سے موجود) تھے، تو آپ نے فرمایا: \"چچا جان! آپ «لا إله إلا اللہ» کا کلمہ کہہ دیجئیے، میں اس کے ذریعہ آپ کے لیے اللہ عزوجل کے پاس جھگڑوں گا\"، تو ابوجہل اور عبداللہ بن ابی امیہ دونوں نے ان سے کہا: ابوطالب! کیا آپ عبدالمطلب کے دین سے منہ موڑ لو گے؟ پھر وہ دونوں ان سے باتیں کرتے رہے یہاں تک کہ آخری بات جو عبدالمطلب نے ان سے کی وہ یہ تھی کہ (میں) عبدالمطلب کے دین پر ہوں، تو نبی اکرم صلی اللہ علیہ وسلم نے ان سے کہا: \"میں آپ کے لیے مغفرت طلب کرتا رہوں گا جب تک مجھے روک نہ دیا جائے\"، تو یہ آیت اتری ۱؎: «ما كان للنبي والذين آمنوا أن يستغفروا للمشركين»\"نبی اور اہل ایمان کے لیے یہ جائز نہیں کہ مشرکین کے لیے مغفرت طلب کریں\" (التوبہ: ۱۱۳) نیز یہ آیت اتری: «إنك لا تهدي من أحببت» \"آپ جسے چاہیں ہدایت کے راستہ پر نہیں لا سکتے\" (القص: ۵۶)۔\n§وضاحت\n۱؎: یہاں ایک مشکل یہ ہے کہ ابوطالب کی موت ہجرت سے پہلے ہوئی ہے، اور سورۃ برأت جس کی یہ آیت ہے ان سورتوں میں سے جو مدنی دور کے اخیر میں نازل ہوئی ہیں، اس اشکال کا جواب یہ ہے کہ یہاں یہ مراد نہیں کہ آیت کا نزول آپ کے «لأستغفرن لك ما لم أنه عنك» کہنے کے بعد فوراً ہوا، بلکہ مراد یہ ہے کہ یہ نزول کا سبب ہے «فنزلت» میں «فاء» سبب بیان کرنے کے لیے ہے نہیں کہ بلکہ «تعقیب» یعنی بعد میں واقع ہونے کی خبر کے لیے ہے۔","الألباني: صحيح",{"u2":"حضرت مسیب رضی اللہ عنہ فرماتے ہیں کہ جب ابو طالب کی وفات کا وقت آیا تو نبی صلی اللہ علیہ وسلم اس کے پاس تشریف لے گئے۔ اس کے پاس (اس وقت) ابو جہل اور عبداللہ بن ابی امیہ تھے۔ آپ نے فرمایا: ’’اے چچا کلمہ لا إلہ إلا اللہ پڑھ لے، میں اسے اللہ تعالیٰ کے پاس تیرے لیے بطور حجت پیش کروں گا۔‘‘ ابوجہل اور عبداللہ بن ابی امیہ اسے کہنے لگے: اے ابوطالب! کیا تو عبدالمطلب کے دین کو چھوڑ دے گا؟ وہ دونوں اس سے اس قسم کی باتیں کرتے رہے حتی کہ پخری بات جو ابوطالب نے ان سے کی، وہ یہ تھی کہ میں عبدالمطلب کے دین پر ہوں۔ تو نبی صلی اللہ علیہ وسلم نے اس سے فرمایا: ’’میں تیرے لیے استفغار کرتا رہوں گا بشرطیکہ مجھے روکا نہ گیا۔‘‘ پھر یہ آیت اتری: (ما کان للنبی والذین امنوآ ان یستغفروا للمشرکین) ’’نبی اور ایمان والوں کے لیے جائز نہیں کہ مشرکین کے لیے استغفار کریں۔‘‘ اور یہ آیت بھی اتری: (انک لا تھدی من احببت) ’’آپ جسے چاہیں راہ راست پر نہیں لاسکتے۔‘‘","f2":"(۱) ثابت ہوا کہ ابوطالب نے اسلام قبول نہیں کیا بلکہ کفر ہی پر فوت ہوا۔ یہ الگ بات ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی وجہ سے اس کو سب سے ہلکا عذاب ہوگا۔ چونکہ شرک ناقابل معافی جرم ہے، اس لیے مشرک کے لیے استغفار ناجائز ہے۔ ابوطالب کو معذورین میں شامل کرنا بھی مشکل ہے کیونکہ اسے تو دین حق پہنچ گیا تھا مگر وہ بوجوہ قبول نہ کرسکا۔ واللہ أعلم۔ (۲) انسان کو قیامت کے دن اس کا عمل کام دے گا، حسب و نسب کام نہ آسکے گا۔"}],[2036,"علی رضی اللہ عنہ کہتے ہیں میں نے ایک شخص کو اپنے ماں باپ کے لیے مغفرت طلب کرتے ہوئے سنا حالانکہ وہ دونوں مشرک تھے، تو میں نے کہا: کیا تو ان دونوں کے لیے مغفرت طلب کرتا ہے؟ حالانکہ وہ دونوں مشرک تھے، تو اس نے کہا: کیا ابراہیم (علیہ السلام) نے اپنے باپ کے لیے مغفرت طلب نہیں کی تھی؟ تو میں نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا، اور آپ سے اس بات کا تذکرہ کیا، تو (یہ آیت) اتری: «وما كان استغفار إبراهيم لأبيه إلا عن موعدة وعدها إياه» \"ابراہیم کا اپنے باپ کے لیے مغفرت طلب کرنا ایک وعدہ کی وجہ سے تھا\" (التوبہ: ۱۱۴)۔","الألباني: حسن",{"u2":"حضرت علی رضی اللہ عنہ بیان کرتے ہیں کہ میں نے ایک شخص کو سنا جو اپنے مشرک والدین کے لیے استغفار کر رہا تھا تو میں نے کہا: کیا تو ان کے لیے استغفار کرتا ہے، حالانکہ وہ مشرک تھے؟ اس نے کہا: کیا حضرت ابراہیم علیہ السلام نے اپنے والد کے لیے استغفار نہیں کی تھی؟ میں نبی صلی اللہ علیہ وسلم کے پاس آیا اور یہ بات آپ سے ذکر کی تو یہ آیت اتری: (وما کان استغفار ابراھیم لابیہ الا عن موعدۃ و عدھا ایاہ) ’’ابراہیم (علیہ السلام) کا اپنے والد کے لیے استغفار کرنا اس وعدے کی بنا پر تھا جو انھوں نے اس سے کیا تھا۔‘‘","f2":"(۱) محقق کتاب نے مذکورہ روایت کو سنداً ضعیف قرار دیا ہے اور مزید لکھا ہے کہ اس حدیث کے بعض حصے کے شواہد مستدرک حاکم وغیرہ میں ہیں جنھیں امام حاکم نے صحیح کہا ہے اور امام ذہبی نے موافقت کی ہے لیکن محقق کتاب نے ان شواہد پر خود کوئی حکم نہیں لگایا جبکہ دیگر محققین نے مذکورہ روایت کو غالباً انھی شواہد کی بنا پر حسن قرار دیا ہے اور دلائل کی رو سے انھی کی رائے اقرب الی الصواب معلوم ہوتی ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (صحیح سنن النسائي للألباني: ۶۸/۲، رقم: ۲۰۳۵، وذخیرۃ العقبی شرح سنن النسائي: ۵۴،۴۳/۲۰) (۲) حضرت ابراہیم علیہ السلام کو جب پتا چل گیا کہ میرا والد کفر ہی پر فوت ہوا ہے تو انھوں نے اس کے لیے استغفار ترک فرما دیا۔ زندگی میں تو مشرک کے لیے مغفرت اور ہدایت کی دعا کی جا سکتی ہے، مگر شرک پر مرجانے کے بعد نہیں۔"}],[2037,"محمد بن قیس بن مخرمہ کہتے ہیں کہ میں نے ام المؤمنین عائشہ رضی اللہ عنہا کو بیان کرتے ہوئے سنا وہ کہہ رہی تھیں: کیا میں تمہیں اپنے اور نبی اکرم صلی اللہ علیہ وسلم کے بارے میں نہ بتاؤں؟ ہم نے کہا کیوں نہیں ضرور بتائیے، تو وہ کہنے لگیں، جب وہ رات آئی جس میں وہ یعنی نبی اکرم صلی اللہ علیہ وسلم میرے پاس تھے تو آپ(عشاء) سے پلٹے، اپنے جوتے اپنے پائتانے رکھے، اور اپنے تہبند کا کنارہ اپنے بستر پر بچھایا، آپ صرف اتنی ہی مقدار ٹھہرے جس میں آپ نے محسوس کیا کہ میں سو گئی ہوں، پھر آہستہ سے آپ نے جوتا پہنا اور آہستہ ہی سے اپنی چادر لی، پھر دھیرے سے دروازہ کھولا، اور دھیرے سے نکلے، میں نے بھی اپنا کرتا، اپنے سر میں ڈالا اور اپنی اوڑھنی اوڑھی، اور اپنی تہبند پہنی، اور آپ کے پیچھے چل پڑی، یہاں تک کہ آپ مقبرہ بقیع آئے، اور اپنے ہاتھوں کو تین بار اٹھایا، اور بڑی دیر تک اٹھائے رکھا، پھر آپ پلٹے تو میں بھی پلٹ پڑی، آپ تیز چلنے لگے تو میں بھی تیز چلنے لگی، پھر آپ دوڑنے لگے تو میں بھی دوڑنے لگی، پھر آپ اور تیز دوڑے تو میں بھی اور تیز دوڑی، اور میں آپ سے پہلے آ گئی، اور گھر میں داخل ہو گئی، اور ابھی لیٹی ہی تھی کہ آپ بھی اندر داخل ہو گئے، آپ نے پوچھا: \"عائشہ! تجھے کیا ہو گیا، یہ سانس اور پیٹ کیوں پھول رہے ہیں؟\" میں نے کہا: کچھ تو نہیں ہے، آپ نے فرمایا: \"تو مجھے بتا دے ورنہ وہ ذات جو باریک بین اور ہر چیز کی خبر رکھنے والی ہے مجھے ضرور بتا دے گی\"، میں نے عرض کیا: اللہ کے رسول! میرے ماں باپ آپ پر فدا ہوں، پھر میں نے اصل بات بتا دی تو آپ نے فرمایا: \"وہ سایہ جو میں اپنے آگے دیکھ رہا تھا تو ہی تھی\"، میں نے عرض کیا: جی ہاں، میں ہی تھی، آپ نے میرے سینہ پر ایک مکا مارا جس سے مجھے تکلیف ہوئی، پھر آپ نے فرمایا: \"کیا تو یہ سمجھتی ہے کہ اللہ اور اس کے رسول صلی اللہ علیہ وسلم تجھ پر ظلم کریں گے\"، میں نے کہا: جو بھی لوگ چھپائیں اللہ تعالی تو اس سے واقف ہی ہے، (وہ آپ کو بتا دے گا) آپ صلی اللہ علیہ وسلم نے فرمایا:\"جبرائیل میرے پاس آئے جس وقت تو نے دیکھا، مگر وہ میرے پاس اندر نہیں آئے کیونکہ تو اپنے کپڑے اتار چکی تھی، انہوں نے مجھے آواز دی اور انہوں نے تجھ سے چھپایا، میں نے انہیں جواب دیا، اور میں نے بھی اسے تجھ سے چھپایا، پھر میں نے سمجھا کہ تو سو گئی ہے، اور مجھے اچھا نہ لگا کہ میں تجھے جگاؤں، اور میں ڈرا کہ تو اکیلی پریشان نہ ہو، خیر انہوں نے مجھے حکم دیا کہ میں مقبرہ بقیع آؤں، اور وہاں کے لوگوں کے لیے اللہ سے مغفرت کی دعا کروں\"، میں نے پوچھا: اللہ کے رسول! میں کیا کہوں (جب بقیع میں جاؤں)، آپ صلی اللہ علیہ وسلم نے فرمایا: کہو «السلام على أهل الديار من المؤمنين والمسلمين يرحم اللہ المستقدمين منا والمستأخرين وإنا إن شاء اللہ بكم لاحقون» \"سلامتی ہو ان گھروں کے مومنوں اور مسلمانوں پر، اللہ تعالی ہم میں سے اگلے اور پچھلے(دونوں) پر رحم فرمائے، اور اگر اللہ تعالی نے چاہا تو ہم تم سے ملنے (ہی) والے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت محمد بن قیس بن مخرمہ سے روایت ہے کہ میں نے حضرت عائشہ رضی اللہ عنہا کو یہ فرماتے سنا: کیا میں تم کو اپنے اور نبی صلی اللہ علیہ وسلم کے بارے میں ایک واقعہ بیان نہ کروں؟ ہم نے کہا: ہاں ضرور۔ انھوں نے فرمایا: ایک مرتبہ میری رات کی باری تھی جس میں آپ میرے ہاں تھے۔ آپ (عشاء کی نماز پڑھ کر) لوٹے تو اپنے جوتے اپنے پاؤں کے پاس اتار کر رکھ لیے اور اپنی چادر کا کنارہ اپنے بستر پر بچھا لیا۔ تھوڑی دیر کے بعد جب آپ نے یہ خیال کیا کہ میں سو گئی ہوں (آپ اٹھے) آہستگی سے جوتے پہنے، چپکے سے چادر پکڑی، پھر ہولے سے دروازہ کھولا اور بغیر آواز کیے نکل گئے۔ میں نے فوراً قمیص پہنی، اوڑھنی اوڑھی، تہ بند باندھا اور آپ کے پیچھے چل پڑی حتی کہ آپ بقیع (قبرستان) میں پہنچ گئے اور تین دفعہ ہاتھ اٹھا اٹھا کر لمبی دعائیں کیں، پھر آپ واپس مڑے تو میں بھی مڑی۔ آپ تیز ہوئے تو میں بھی تیز ہوگئی۔ آپ بھاگنے لگے تو میں بھی بھاگنے لگی۔ آپ نے دوڑ لگا دی تو میں نے بھی دوڑ لگا دی لیکن میں آپ سے (آگے تھی، لہٰذا) پہلے پہنچ گئی اور گھر میں داخل ہو گئی۔ ابھی میں لیٹی ہی تھی کہ آپ تشریف لے آئے اور آپ نے پوچھا: ’’عائشہ! تجھے کیا ہوا؟ تتیرا سانس چڑھا ہوا ہے۔ پیٹ پھولا ہوا ہےڈ‘‘ میں نے کہا: جی! کچھ بھی نہیں۔ آپ نے فرمایا: ’’مجھے سچ سچ بتا دے ورنہ مجھے باریک بین اور خبردار ذات بتا دے گی۔‘‘ میں نے عرض کیا: اے اللہ کے رسول! میرے ماں باپ آپ پر قربان! پھر میں نے پوری بات بتا دی۔ آپ نے فرمایا: ’’تیرا ہی وہ وجود تھا جو میں نے آگے آگے دیکھا تھا؟‘‘ میں نے کہا: جی ہاں۔ آپ نے میرے سینے میں اس زور سے مکا مارا کہ مجھے سخت تکلیف ہوئی، پھر فرمایا: ’’کیا تو سمجھتی تھی کہ اللہ تعالیٰ اور اس کا رسول تجھ پر ظلم کریں گے؟‘‘ میں نے (دل میں) کہا: لوگوں سے جتنا بھی چھپایا جائے، اللہ تعالیٰ تو اسے جانتا ہی ہے۔ آپ نے فرمایا: ’’جب تو نے مجھے اٹھتے دیکھا تھا تو جبریل میرے پاس آئے تھے لیکن وہ اندر داخل نہیں ہوئے کیونکہ تو کپڑے اتار چکی تھی۔ انھوں نے مجھے (ہلکے سے) بلایا کہ تجھے پتا نہیں چلنے دیا۔ میں نے بھی (ہولے سے) جواب دیا کہ تجھے پتا نہیں چل سکا۔ میرا خیال تھا کہ تو سو چکی ہے، اس لیے میں نے تجھے جگانا مناسب نہ سمجھا۔ مجھے خطرہ تھا کہ تو ڈرنے لگے گی۔ تو جبریل علیہ السلام نے مجھ سے کہا کہ میں بقیع جاؤں اور ان کے لیے بخشش کی دعا کروں۔‘‘ میں نے کہا: اے اللہ کے رسول! (مجھے قبرستان جانے کا موقع ملے تو) میں کیسے دعا کروں؟ آپ نے فرمایا: ’’تو کہہ: طالسلام علی اھل الدیار ……… وانا ان شاء اللہ بکم لاحقون] اس قبرستان کے مومنین اور مسلمانوں پر سلامتی ہو۔ اور اللہ تعالیٰ ہم میں سے پہلے آنے والوں اور پیچھے رہنے والوں سب پر رحم فرمائے اور اگر اللہ تعالیٰ نے چاہا تو ہم بھی تمھیں ملنے والے ہیں۔","f2":"(۱) واقعے کی تفصیلات تو حدیث سے واضح ہیں۔ حضرت عائشہ رضی اللہ عنہا کا خیال تھا کہ آپ میری باری کی رات کسی اور بیوی کے گھر گئے ہیں، حالانکہ آپ جیسی عادل شخصیت کے لیے یہ ممکن نہ تھا کیونکہ یہ تو ظلم ہے اور نبی کی شخصیت اس سے پاک ہوتی ہے۔ غیرت کے جذبات کی وجہ سے حضرت عائشہ رضی اللہ عنہا کا دھیان اس حقیقت کی طرف نہ جاسکا۔ تبھی آپ نے ان کے سینے پر مکا مار کر انھیں حقیقت کی طرف توجہ دلائی۔ چونکہ آپ اللہ تعالیٰ کے حکم کے بغیر قدم نہیں اٹھاتے تھے، اس لیے اپنے ساتھ اللہ تعالیٰ کا بھی ذکر فرمایا: [ان یحیف اللہ علیک و رسولہ] کہ اللہ اور اس کا رسول تجھ پر ظلم کریں گے؟ (۲) اس سے استدلال کیا گیا ہ کہ آپ پر بیویوں کے درمیان باری مقرر کرنا واجب تھا، ورنہ باری کی خلاف ورزی ظلم نہ ہوتا مگر اس تکلف کی ضرورت نہیں کیونکہ نبی صلی اللہ علیہ وسلم جیسی عاادل شخصیت وجوب کے بغیر بھی کسی کا دل نہیں دکھا سکتی تھی۔ آپ کے اخلاق کریمانہ سے بعید تھا کہ آپ کسی کی دل آزاری کرتے۔ (۳) معلوم ہوا کہ دعا کے قصد سے قبرستان جانا چاہیے اور لمبی دعا کرنی چاہیے۔ [السلام علی اھل الدیار………] کے علاوہ بھی مزید دعا کرنی جائز ہے۔ علاوہ ازیں ہاتھ اٹھا کر کی جائے یا ویسے ہی کر لی جائے، دونوں طرح جائز ہے۔ (۴) حضرت عائشہ رضی اللہ عنہا کے سوال اور نبی صلی اللہ علیہ وسلم کے جواب سے معلوم ہوا کہ عورت بھی زیارتِ قبر کے لیے جاسکتی ہے۔ واللہ أعلم۔"}],[2038,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں ایک رات رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے، اپنا کپڑا پہنا پھر (باہر) نکل گئے، تو میں نے اپنی لونڈی بریرہ کو حکم دیا کہ وہ پیچھے پیچھے جائے، چنانچہ وہ آپ کے پیچھے پیچھے گئی یہاں تک کہ آپ مقبرہ بقیع پہنچے، تو اس کے قریب کھڑے رہے جتنی دیر اللہ تعالی نے کھڑا رکھنا چاہا، پھر آپ پلٹے تو بریرہ آپ سے پہلے پلٹ کر آ گئی، اور اس نے مجھے بتایا، لیکن میں نے آپ سے اس کا کوئی ذکر نہیں کیا یہاں تک کہ صبح کیا، تو میں نے آپ کو ساری باتیں بتائیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"مجھے اہل بقیع کی طرف بھیجا گیا تھا تاکہ میں ان کے حق میں دعا کروں\"۔","الألباني: ضعيف الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: ایک رات رسول اللہ صلی اللہ علیہ وسلم اٹھے، اپنے کپڑے پہنے اور پھر نکل گئے۔ میں نے اپنی لونڈی بریرہ رضی اللہ عنہا سے کہا کہ وہ آپ کا پیچھا کرے۔ اس نے آپ کا پیچھا کیا حتی کہ آپ بقیع (جنت البقیع) میں پہنچ گئے اور اس کے ابتدائی حصے میں کھڑے (دعا کرتے) رہے۔ جب تک اللہ تعالیٰ نے چاہا، پھر واپس چل پڑے۔ بریرہ آپ سے پہلے پہنچ گئی اور مجھے سب کچھ بتا دیا۔ (آپ تشریف لائے تو) میں نے آپ سے کچھ نہ کہا حتی کہ جب صبح ہوئی تو پھر میں نے اس بات کا تذکرہ آپ سے کیا۔ آپ نے فرمایا: ’’مجھے (اللہ تعالیٰ کی طرف سے حکماً) کہا گیا تھا کہ میں بقیع میں مدفون لوگوں کے لیے دعائے رحمت و مغفرت کروں۔‘‘","f2":"(۱) یہ واقعہ سابقہ حدیث والے واقعے سے الگ ہے جیسا کہ اس سے اور مابعد والی حدیث سے صاف معلوم ہو رہا ہے۔ (۲) فوت شدگان خود تو دعا کر نہیں سکتے کہ ان کے لیے دعا کا وقت ختم ہوچکا ہے، اس لیے زندہ متعلقین کے لیے ضروری ہے کہ انھیں دعاؤں میں یاد رکھیں۔"}],[2039,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں جب جب رسول اللہ صلی اللہ علیہ وسلم کی باری ان کے یہاں ہوتی تو رات کے آخری (حصے) میں مقبرہ بقیع کی طرف نکل جاتے، (اور) کہتے: «السلام عليكم دار قوم مؤمنين وإنا وإياكم متواعدون غدا أو مواكلون وإنا إن شاء اللہ بكم لاحقون اللہم اغفر لأهل بقيع الغرقد» \"اے مومن گھر (قبرستان) والو! تم پر سلامتی ہو، ہم اور تم آپس میں ایک دوسرے سے کل کی حاضری کا وعدہ کرنے والے ہیں، اور آپس میں ایک دوسرے پر بھروسہ کرنے والے ہیں، اور اگر اللہ تعالی نے چاہا تو ہم تم سے ملنے والے ہیں، اے اللہ! بقیع غرقد والوں کی مغفرت فرما\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ جب بھی رسول اللہ صلی اللہ علیہ وسلم کی جانب سے میری باری والی رات ہوتی تو آپ رات کے آخری حصے میں بقیع (قبرستان) تشریف لے جاتے اور یوں فرماتے: [السلام علیکم دار قوم مومنین ……… اللھم الاھل بقیع الغرقد] ’’اے مومنین قبرستان! تم پر سلامتی ہو۔ ہم اور تم کل کو وقت مقررہ پر اللہ تعالیٰ کے سامنے پیش ہونے والے ہیں اور شفاعت وغیرہ میں ایک دوسرے کا سہارا بننے والے ہیں اور یقیناً جب اللہ تعالیٰ نے چاہا تو ہم بھی تم سے ملنے والے ہیں۔ اے اللہ! بقیع الغرقد میں مدفون مسلمانوں کو معاف فرما۔‘‘","f2":"’’سہارا‘‘ کیونکہ قیامت کے دن انبیاء، شہیداء، علماء اور صلحاء سفارش کریں گے، نیز ایک دوسرے کے حق میں سچی گواہی بھی دیں گے، ورنہ سہارا تو اللہ تعالیٰ کی رحمت ہی کا ہے کیونکہ اللہ تعالیٰ کی اجازت کے بغیر سفارش ہے، نہ شہادت۔"}],[2040,"بریدہ رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب قبرستان آتے تو فرماتے: «السلام عليكم أهل الديار من المؤمنين والمسلمين وإنا إن شاء اللہ بكم لاحقون أنتم لنا فرط ونحن لكم تبع أسأل اللہ العافية لنا ولكم» \"اے مومن اور مسلمان گھر والو! تم پر سلامتی ہو، اور اگر اللہ تعالی نے چاہا تو ہم (عنقریب) تم سے ملنے والے ہیں، تم ہمارے پیش رو ہو، اور ہم تمہارے بعد آنے والے ہیں۔ میں اللہ سے اپنے اور تمہارے لیے عافیت کی درخواست کرتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت بریدہ رضی اللہ عنہ سے منقول ہے کہ رسول اللہ صلی اللہ علیہ وسلم جب قبرستان جاتے تو فرماتے: [السلام علیکم اھل الدیار من المومنین ……… أسال اللہ العافیۃ لنا ولکم] ’’اے اس قبرستان کے مسلمان اور مومن باسیو! تم پر سلامتی ہو۔ یقیناً ہم بھی، اللہ نے چاہا تو، تم سے ملنے والے ہیں۔ تم ہم سے پہلے آگئے ہو۔ ہم تمھارے پیچھے آ رہے ہیں۔ میں اپنے لیے اور تمھارے لیے اللہ تعالیٰ سے خیریت و سلامتی کی دعا کرتا ہوں۔‘‘","f2":"فوت شدگان سے خطاب صرف اپنے ذہن میں ان کی یاد تازہ ہونے کے لحاظ سے ہے ورنہ انھیں سنانا مقصود ہے نہ جواب لینا کیونکہ یہ دونوں چیزیں ناممکن ہیں۔ خصوصاً اس حدیث میں تو صرف ان کے لیے دعا کی جا رہی ہے، جس میں خطاب مقصود ہی نہیں۔ انسانی زندگی میں اس کی مثالیں عام مل جاتی ہیں۔ بسا اوقات انسان خودکلامی کے انداز میں خطاب کرتا ہے، حالانکہ وہاں کوئی بھی مخاطب موجود نہیں ہوتا، صرف اپنے جذبات کا اظہار مقصود ہوتا ہے۔"}],[2041,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ جب نجاشی (شاہ حبشہ) کا انتقال ہوا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ ان کی بخشش کی دعا کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے کہ جب حضرت نجاشی رحمہ اللہ فوت ہوئے تو نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ان کے لیے بخشش کی دعا کرو۔‘‘","f2":"معلوم ہوا کسی کی وفات کی اطلاع ملنے پر (انا للہ و انا الیہ راجعون) پڑھنے کے ساتھ اس کے لیے بخشش کی دعا بھی کرنی چاہیے تاکہ اللہ تعالیٰ ہمیں بھی معاف فرمائے۔"}],[2042,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے انہیں شاہ حبشہ نجاشی کی موت کی خبر اسی دن دی جس دن وہ مرے، آپ صلی اللہ علیہ وسلم نے فرمایا: \"تم اپنے بھائی کے لیے مغفرت طلب کرو\"۔","",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ جس دن حبشہ کے بادشاہ نجاشی رحمہ اللہ فوت ہوئے، رسول اللہ صلی اللہ علیہ وسلم نے اسی دن ان کی وفات کی اطلاع ہمیں دی اور فرمایا: ’’اپنے (اسلامی) بھائی کے لیے استغفار کرو۔‘‘"}],[2043,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبروں کی زیارت کرنے والیوں پر، اور انہیں سجدہ گاہ بنانے اور ان پر چراغاں کرنے والوں پر لعنت فرمائی ہے۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے قبرستان جانے والی عورتوں اور قبروں پر عبادت گاہیں بنانے والوں اور چراغ جلانے والوں پر لعنت کی ہے۔‘‘","f2":"(۱) محقق کتاب نے مذکورہ روایت کو سنداً ضعیف قرار دیا ہے جبکہ دیگر محققین نے آخری لفظ [والسرج] ’’چراغ‘‘ کے علاوہ باقی روایت کو شواہد کی بنا پر حسن قرار دیا ہے۔ اور دلائل کی رو سے انھی کی رائے اقرب الی الصواب معلوم ہوتی ہے۔ واللہ أعلم۔ نیز زائرات القبور کی بجائے زوارات القبور کے الفاظ صحیح ثابت ہیں، یعنی رسول اللہ صلی اللہ علیہ وسلم نے ان عورتوں پر لعنت فرمائی ہے جو کثرت سے قبرستان جاتی ہیں۔ بنا بریں عورتوں کے لیے بھی زیارت قبور ویسے ہی مستحب ہے جیسے مردو کے لیے۔ عورتوں کا خصوصی ذکر اس لیے کہ ان میں صبر اور حوصلے کی کمی ہوتی ہے۔ جزع فزع زیادہ ہوتی ہے، لہٰذا کبھی کبھار ہی جائیں مزید تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الإمام أحمد: ۳۶۵-۳۶۳/۴، و سلسلۃ الأحادیث الضعیفۃ: ۳۹۶-۳۹۳/۱، رقم: ۲۲۵، و أحکام الجنائز للألبانی، ص:۲۳۷-۲۳۶) (۲) قبروں پر عبادت گاہ بنانے کا مطلب یہ ہے کہ وہاں نماز وغیرہ پڑھے جس میں قبر کی طرف نماز پڑھے جانے کا بھی امکان ہو۔ قبر پر مکان بنا ہو تو اس کا حکم بھی قبر جیسا ہے، یعنی اس کی طرف بھی نماز پڑھنا منع ہے۔ قبر کے قریب مسجد بنانا بھی کراہت سے خالی نہیں۔ یہ ایسے ہے جیسے نجاست کے قریب نماز پڑھی جائے کہ نماز تو ہو جائے گی مگر قبیح چیز ہے۔ قبر، مساجد بلکہ آبادی سے الگ اور دور بنانی چاہیے۔ قبر کے اوپر عمارت، خواہ وہ قبر کی حفاظت کے لیے ہو یا زائر کی سہولت کے لیے، منع ہے۔ اگر قبر پہلے سے ہو تو عمارت ڈھا دینی چاہیے اور اگر عمارت پہلے تھی تو قبر کو اکھاڑ دینا چاہیے۔ نبی صلی اللہ علیہ وسلم کی قبر مبارک پر جو عمارت بنی ہوئی ہے، وہ صدیوں بعد سلاطین کی تعمیر کردہ ہے، ورنہ صحابہ و تابعین کے دور میں ایسا نہیں تھا، اس لیے اس سے قبروں پر عمارتیں بنانے پر استدلال کرنا صحیح نہیں ہے۔ واللہ أعلم۔ (۳) حدیث کے آخری جملے [والسراج] یعنی نبی صلی اللہ علیہ وسلم نے چراغ جلانے والوں پر لعنت کی ہے۔‘‘ کی تصعیف سے یہ ثابت نہیں ہوتا کہ اس کی ممانعت ثابت نہیں بلکہ عمومی دلائل سے اس کی ممانعت ثابت ہوتی ہے، مثلاً: کل بدعۃ ضلالۃ و کل ضلالۃ فی النار کہ ہر بدعت گمراہی ہے اور ہر گمراہی جہنم میں لے جانے والی ہے، نیز قبر پر چراغ جلانا یا تو قبر کی تعظی کے لیے ہوگا تو ایسی تعظیم منع ہے بلکہ یہ تو قبر پر چڑھاوے کی طرح ہے، یا بے فائدہ ہوگا۔ قبروں پر روشنی کی ضرورت نہیں، ان کے اندر روشنی کی ضرورت ہے اور وہ اعمال صالحہ کے ساتھ ہے۔ اگر آنے جانے والوں کے لیے روشنی کرنا مقصود ہو تو قبر کے بجائے کسی اور چیز پر روشنی کا انتظام کیا جائے تاکہ تعظیم کا وہم نہ ہو۔ واللہ أعلم۔"}],[2044,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم میں سے کسی کا انگارے پر بیٹھنا یہاں تک کہ اس کے کپڑے جل جائیں اس کے لیے بہتر ہے اس بات سے کہ وہ کسی قبر پر بیٹھے\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کسی شخص کا انگارے پر بیٹھنا جس سے اس کے کپڑے جل جائیں، قبر پر بیٹھنے سے بہتر ہے۔‘‘","f2":"تفصیل کے لیے دیکھیے، حدیث: ۲۰۳۰۔"}],[2045,"عمرو بن حزم رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ قبروں پر نہ بیٹھو\"۔","الألباني: صحيح لغيره",{"u2":"حضرت عمرو بن حزم رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قبروں پر مت بیٹھو۔‘‘"}],[2046,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے ان لوگوں پر لعنت فرمائی ہے جنہوں نے اپنے انبیاء کی قبروں کو مسجد بنا لیا\"۔","",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ ان لوگوں (یہود و نصاری) پر لعنت فرمائے جنھوں نے اپنے انبیاء کی قبروں کو عبادت گاہ بنایا۔‘‘","f2":"یعنی ان کی طرف نماز پڑھی یا ان پر عبادت گاہ بنائی کیونکہ یہ یا تو قبر کی عبادت ہے یا قبر کی عبادت کرنے والوں کے ساتھ مشابہت ہے اور ممکن ہے کہ اس طرح آہستہ آہستہ قبر ہی کی پجا شروع ہو جائے جیسے آج کل قبور صالحین کے ساتھ ہو رہا ہے۔ (مزید دیکھیے، حدیث: ۲۰۴۵)"}],[2047,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی نے یہود و نصاری پر لعنت فرمائی ہے (کیونکہ) ان لوگوں نے اپنے انبیاء کی قبروں کو مسجد بنا لیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ تعالیٰ ان یہودیوں اور عیسائیوں پ لعنت فرمائے جنھوں نے اپنے انبیاء کی قبروں کو عبادت گاہ بنایا۔‘‘"}],[2048,"بشیر بن خصاصیہ رضی اللہ عنہ کہتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا کہ آپ مسلمانوں کی قبروں کے پاس سے گزرے تو فرمایا: \"یہ لوگ بڑے شر و فساد سے (بچ) کر آگے نکل گئے\"، پھر آپ مشرکوں کی قبروں کے پاس سے گزرے تو فرمایا: \"یہ لوگ بڑے خیر سے (محروم) ہو کر آگے نکل گئے\"، پھر آپ متوجہ ہوئے تو دیکھا کہ ایک شخص اپنی دونوں جوتیوں میں قبروں کے درمیان چل رہا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے سبتی جوتوں والو! انہیں اتار دو\"۔","الألباني: حسن",{"u2":"حضرت بشیر بن خصاصیہ رضی اللہ عنہ بیان کرتے ہیں کہ میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ چل رہا تھا، آپ چند مسلمانوں کی قبروں کے پاس سے گزرے تو فرمایا: ’’یہ لوگ (وفات کی وجہ سے) بہت زیادہ شر سے بچ گئے ہیں۔‘‘ پھر آپ کچھ مشرکین کی قبروں کے پاس سے گزرے تو فرمایا: ’’یہ لوگ (اپنی موت کی وجہ سے) بہت زیادہ خیر سے محروم رہے۔‘‘ اچانک آپ نے توجہ فرمائی تو ایک شخص کو قبرستان میں جوتوں سمیت چلتے دیکھا تو فرمایا: ’’اوصاف رنگے ہوئے (رنگ کر صاف کیے ہوئے) چمڑے کے جوتے پہننے والے! انھیں اتار دے۔‘‘","f2":"اس حدیث سے ظاہراً معلوم ہوتا ہے کہ قبرستان میں جوتوں سمیت نہیں چلنا چاہیے تاکہ قبروں کا احترام قائم رہے، آئندہ دو روایات سے امام صاحب رحمہ اللہ نے قبرستان میں جوتوں سمیت چلنے کا جواز نکالا ہے، اس لیے وہ ظاہر الفاظ کی رعایت سے یہ تطبیق دے رہے ہیں کہ رنگ کر صاف کیے ہوئے چمڑے کے جوتے پہن کر چلنا منع ہے، سادہ جوتے پہن کر چل سکتا ہے مگر یہ تطبیق دل کو نہیں لگتی۔ آئندہ حدیث کے الفاظ یہ ہیں: ’’جب میت کو قبر میں رکھ دیا جاتا ہے اور دفنانے والے واپس آ جاتے ہیں تو وہ ان کے جوتوں کی آواز سنتا ہے۔‘‘ اس سے یہ ثابت نہیں ہوتا کہ قبرستان میں جوتوں سمیت جانا اور قبروں کے درمیان پھر ناجائز ہے کیونکہ اس کی کوئی صراحت نہیں۔ قبرستان میں داخل ہوتے وقت جوتے اتار دیے جائیں اور واپسی پر پہن لیے جائیں۔ یہ مفہوم اس حدیث کے مخالف نہیں بلکہ عین موافق ہے، اس لیے راجح بات یہی ہے کہ قبرستان میں جوتے پہن کر نہ جایا جائے، اگر کوئی ایسا عذر ہے کہ جوتوں کے بغیر اندر جانا ممکن نہیں، مثلاً کانٹے یا کنکریاں وغیرہ ہیں یا زمین بہت گرم ہے تو پھر مجبوری کے تحت پہنے جا سکتے ہیں۔ (وقد فصل لکم ما حرم علیکم الا ما اضطررتم الیہ) اور (لایکلف اللہ نفسا الا و سعھا) کا تقاضا یہی ہے۔ واللہ أعلم۔"}],[2049,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بندہ جب اپنی قبر میں رکھا جاتا ہے، اور اس کے ساتھی لوٹتے ہیں، تو وہ ان کی جوتیوں کی آواز سنتا ہے\" ۱؎۔\n§وضاحت\n۱؎: اس سے مؤلف نے اس بات پر استدلال ہے کہ سبتی جوتیوں کے علاوہ دوسری جوتیاں پہن کر قبروں کے درمیان چلنا جائز ہے کیونکہ جوتیوں کی آواز اسی وقت سنی جا سکتی ہے جب انہیں پہن کر ان میں چلا جائے، واضح رہے کہ سبتی جوتیوں کے علاوہ کی قید مؤلف نے دونوں روایتوں میں تطبیق پیدا کرنے کے لیے لگائی ہے، یہ بھی کہا جا سکتا ہے کہ سبتی جوتوں کی بات اتفاقی ہے، وہ شخص اس وقت سبتی جوتے پہنے تھا، اگر ان کے سوا کوئی اور جوتے بھی ہوتے تو آپ یہی فرماتے، اور اس حدیث میں بات بیان جواز کی ہے یا قبروں سے بچ بچ کر جوتوں میں چل سکتے ہیں۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میت کو جب قبر میں رکھ دیا جاتا ہے اور اس کے ساتھی اسے دفن کرنے کے بعد واپس آ جاتے ہیں تو وہ ان کے جوتوں کی آواز سن رہا ہوتا ہے۔‘‘","f2":"(۱) اس حدیث سے امام نسائی رحمہ اللہ نے استدلال کیا ہے کہ قبرستان میں جوتوں سمیت چلنا جائز ہے لیکن یہ استدلال قوی نہیں۔ تفصیل کے لیے دیکھیے، حدیث: ۲۰۵۰ کا فائدہ۔ (۲) ’’سن رہا ہوتا ہے۔‘‘ اس سے بعض اہل علم نے سماع موتیٰ پر استدلال کیا ہے۔ دیگر اہل علم قرآن مجید کی صریح آیت: (ان اللہ یسمع من یشآء، ومآ انت بمسمع من فی القبور) (فاطر ۲۲:۳۵) ’’یقینا اللہ تعالیٰ جس کو چاہتا ہے سنا دیتا ہے، اور آپ ان کو نہیں سنا سکتے جو قبروں میں ہیں۔‘‘ سے استدلال کرتے ہیں کہ فوت شدگانہ نہیں سنتے مگر یہ کہ اللہ تعالیٰ کوئی خاص چیز سنا دے۔ اس طرح ارشاد باری تعالیٰ ہے: (انک لا تسمع الموتی) (النمل ۸:۲۷) ’’یقینا آپ مردوں کو سنا نہیں سکتے۔‘‘ غرض وہ اس قسم کی احادیث کو خصوصی حالت پر محمول کرتے ہیں اور یہی مسلک زیادہ محتاط اور تمام آیات و احادیث کے موافق ہے۔ واللہ أعلم۔"}],[2050,"انس بن مالک رضی اللہ عنہ نے بیان کیا کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بندہ جب اپنی قبر میں رکھ دیا جاتا ہے اور اس کے ساتھی لوٹتے ہیں تو وہ ان کے جوتیوں کی آواز سنتا ہے، (پھر) اس کے پاس دو فرشتے آتے ہیں، اور اسے بٹھاتے ہیں، (اور) اس سے پوچھتے ہیں: تم اس شخص (محمد) کے بارے میں کیا کہتے ہو؟ رہا مومن تو وہ کہتا ہے: میں گواہی دیتا ہوں کہ وہ اللہ کے بندے اور اس کے رسول ہیں، تو اس سے کہا جائے گا کہ تم جہنم میں اپنے ٹھکانے کو دیکھ لو، اللہ تعالی نے اس کے بدلے تمہیں جنت میں ٹھکانا دیا ہے\"، نبی اکرم صلی اللہ علیہ وسلم فرماتے ہیں: \"تو وہ ان دونوں (جنت و جہنم) کو ایک ساتھ دیکھے گا\"۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، اللہ تعالیٰ کے نبی صلی اللہ علیہ وسلم نے فرمایا: ’’میت کو جب قبر میں رکھ دیا جاتا ہے اور اس کے ساتھی اسے دفن کرکے واپس آ جاتے ہیں تو ابھی وہ ان کے جوتوں کی آواز سن رہا ہوتا ہے کہ اس کے پاس دو فرشتے آ جاتے ہیں۔ وہ اسے بٹھا لیتے ہیں اور کہتے ہیں: تو اس آدمی کے بارے میں کیا کہتا تھا؟ مومن شخص تو کہتا ہے: میں گواہی دیتا ہوں کہ وہ اللہ کے بندے اور اس کے رسول ہیں۔ اسے کہا جاتا ہے: تو اپنے جہنمی ٹھکانے کو دیکھ۔ اللہ تعالیٰ نے تجھے اس کے بجائے جنتی ٹھکانا دے دیا ہے۔‘‘ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’وہ دونوں ٹھکانوں کو دیکھتا ہے۔‘‘","f2":"(۱) فرشتوں کا آنا، اسے بٹھانا اور پھر سوال و جواب کرنا اور دیگر باتیں برزخی احوال ہیں۔ اس کا دنیوی زندگی سے کوئی تعلق نہیں۔ برزخی زندگی کی حقیقت تو بیان نہیں کی جا سکتی کہ وہ ہماری عقل و حواص سے ماوراء ہے، البتہ اس کی مثال خواب سے دی جا سکتی ہے کہ خواب دیکھنے والا آدمی اپنے خواب میں بولتا بھی ہے، سنتا بھی ہے، چلتا پھرتا بھی ہے، روتا ہنستا، کھاتا پیتا اور دوڑتا بھاگتا بھی ہے لیکن اس کا جسم بالکل ساکن ہوتا ہے۔ اس کے جسم کو دیکھ کر کوئی شخص یہ نہیں سمجھ سکتا کہ وہ خواب کی دنیا میں اتنا کچھ کر رہا ہے۔ میت کا حال بھی ایسا ہی ہوتا ہے۔ (۲) ’’اس آدمی‘‘ سے مراد حضرت محمد صلی اللہ علیہ وسلم ہیں۔ گویا یہ ذہنی اشارہ ہے۔ بعض لوگوں کا خیال ہے کہ میت کو رسول اللہ صلی اللہ علیہ وسلم دکھائے جاتے ہیں مگر اس کا کوئی ثبوت نہیں۔ بالفرض ایسا ہو تو وہ آپ کا تصور ہوگا جو اس کے ذہن میں ڈالا جائے گا نہ کہ آپ کا حقیقی وجود، جیسے ٹی وی وغیرہ میں ہوتا ہے، یعنی اس سے آپ حاضر و ناظر ثابت نہ ہوسکیں گے۔ (۳) ’’دونوں کو دیکھتا ہے‘‘ صحیح حدیث ہے کہ ہر شخص کا جنت میں بھی ٹھکانا ہے اور جہنم میں بھی لیکن جہنم میں جانے والے چونکہ جنت میں جانے کا استحقاق کھو بیٹھتا ہے، اس لیے وہ جنتی ٹھکانے سے محروم ہو جاتا ہے اور جنت میں جانے والا اپنے عمل کی وجہ سے جہنم سے بچ جاتا ہے تو وہ جہنمی ٹھکانے سے محفوظ ہو جاتا ہے۔ جعلنا اللہ منھم۔"}],[2051,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"بندہ جب اپنی قبر میں رکھ دیا جاتا ہے، اور اس کے ساتھی لوٹتے ہیں تو وہ ان کی جوتیوں کی آواز سنتا ہے، (پھر) دو فرشتے آتے ہیں، (اور) اسے بٹھاتے ہیں (پھر) اس سے پوچھتے ہیں: تم اس شخص محمد صلی اللہ علیہ وسلم کے بارے میں کیا کہتے ہو؟ رہا مومن تو وہ کہتا ہے: میں گواہی دیتا ہوں کہ وہ اللہ کے بندے اور اس کے رسول ہیں، (پھر) اس سے کہا جاتا ہے تم جہنم میں اپنے ٹھکانے کو دیکھ لو اللہ تعالی نے تمہیں اس کے بدلے ایک اچھا ٹھکانا دیا ہے۔ رسول اللہ صلی اللہ علیہ وسلم فرماتے ہیں: وہ ان دونوں (جنت و جہنم) کو ایک ساتھ دیکھتا ہے، اور رہا کافر یا منافق تو اس سے پوچھا جاتا ہے: اس شخص (محمد) کے بارے میں تم کیا کہتے ہو؟، تو وہ کہتا ہے: میں نہیں جانتا، میں وہی کہتا تھا جو لوگ کہتے تھے، تو اس سے کہا جائے گا: نہ تم نے خود جاننے کی کوشش کی، اور نہ جانکار لوگوں کی پیروی کی، پھر اس کے دونوں کانوں کے بیچ ایک ایسی مار ماری جاتی ہے کہ وہ ایسے زور کی چیخ مارتا ہے جسے انسان اور جنات کے علاوہ جو بھی اس کے قریب ہوتے ہیں سبھی سنتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب میت کو قبر میں دفن کر دیا جاتا ہے اور اس کے ساتھی اس سے لوٹ کر جاتے ہیں تو ابھی وہ ان کے جوتوں کی آواز سن رہا ہوتا ہے کہ اس کے پاس دو فرشتے آ جاتے ہیں۔ وہ اسے بٹھا لیتے ہیں اور اس سے کہتے ہیں: تو اس شخص (محمد صلی اللہ علیہ وسلم) کے بارے میں کیا کہا کرتا تھا؟ مومن کہتا ہے: میں گواہی دیتا ہوں کہ وہ اللہ تعالیٰ کے بندے اور اس کے رسول ہیں۔ تو اسے کہا جاتا ہے: تو اپنے جہنمی ٹھکاانے کو دیکھ۔ اللہ تعالیٰ نے تجھے اس کے بجائے اچھا ٹھکانا دے دیا ہے۔‘‘ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’وہ دونوں ٹھکانوں کو دیکھتا ہے۔ لیکن کافر یا منافق سے کہا جاتا ہے: تو اس شخص کے بارے می کیا کہتا تھا؟ تو وہ کہتا ہے: میں کچھ نہیں جانتا۔ جس طرح لوگ کہتے تھے، میں بھی کہتا تھا۔ اسے (فرشتوں کی طرف سے) کہا جاتا ہے: نہ تو نے جاننے کی کوشش کی اور نہ تو نے قرآن پڑھا، پھر اس کے کانوں کے درمیان (یعنی اس کے چہرے پر) سخت ضرب لگائی جاتی ہے تو وہ اس قدر چیختا ہے کہ انسان و جن کے علاوہ ہر قریبی مخلوق اس کی آہ و بکا سنتی ہے۔‘‘","f2":"(۱) ’’جس طرح لوگ کہتے تھے‘‘ گویا اس کا اپنا ایمان نہیں تھا۔ ایمان کا اثر ہی باقی رہتا ہے۔ زبانی باتیں تو ہوا میں اڑ جاتی ہیں، لہٰذا اس کی سمجھ میں کچھ نہ آئے گا۔ (۲) ’’انسان و جن کے علاوہ‘‘ ورنہ اس کی زندگی برباد ہو جائے اور معاش بگڑ جائے۔ دوسری مخلوقات کا عذاب قبر کو سننا کوئی بعید بات نہیں۔ اللہ تعالیٰ نے بہت سے حیوانات کو بعض صلاحیتیں انسان سے بڑھ کر دی ہیں، جیسے کتے وغیرہ کی سونگھنے کی قوت انسان سے بہت بڑھ کر ہے۔ (ذلک تقدیر العزیز العلیم) (یس ۳۸:۳۶) (۳) دینی مسائل میں تقلید مذموم چیز ہے، ہر مکلف پر اتباع ضروری ہے۔"}],[2052,"عبداللہ بن یسار کہتے ہیں کہ میں بیٹھا ہوا تھا اور (وہیں) سلیمان بن صرد اور خالد بن عرفطہٰ رضی اللہ عنہما (بھی) موجود تھے تو لوگوں نے ذکر کیا کہ ایک آدمی اپنے پیٹ کے عارضہ میں وفات پا گیا ہے، تو ان دونوں نے تمنا کی کہ وہ اس کے جنازے میں شریک ہوں، تو ان میں سے ایک نے دوسرے سے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے نہیں کہا ہے کہ \"جو پیٹ کے عارضہ میں مرے اسے قبر میں عذاب نہیں دیا جائے گا\"، تو دوسرے نے کہا: کیوں نہیں، آپ نے ایسا فرمایا ہے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن یسار بیان کرتے ہیں کہ میں سلیمان بن صرد اور خالد بن عرفطہ رضی اللہ عنہما کے پاس بیٹھا تھا کہ لوگوں نے ایک شخص کا ذکر کیا جو پیٹ کی تکلیف سے فوت ہوگیا تھا۔ ان دونوں میں سے ہر ایک بزرگ نے خواہش ظاہر کی کہ اس کے جنازے میں شریک ہوں۔ ان میں سے ایک نے دوسرے سے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے یہ نہیں فرمایا تھا: ’’جو آدمی پیٹ کی تکلیف سے مر جائے، اسے عذاب قبر نہیں ہوگا؟‘‘ تو دوسرے نے کہا: کیوں نہیں! (آپ نے ضرور فرمایا تھا)۔","f2":"پیٹ کی تکلیف سے مراد پیٹ سے متعلقہ بیماری کی کوئی بھی نوعیت ہوسکتی ہے، مثلاً: اسہال یا ہیضہ یا آنتوں کا سرطان وغیرہ۔ حادثاتی موت کو شہادت فرمایا گیا اور پیٹ کی بیماری سے موت کو عذاب قبر سے مانع بتایا گیا۔ چونکہ اس قسم کی اموات زیادہ صدمے اور تکلیف کا موجب ہوتی ہیں، لہٰذا ان کا ثواب و اجر بھی زیادہ ہوتا ہے۔ بعض نے پیٹ کی تکلیف سے استسقاء کی بیماری مراد لی ہے جس میں مریض کو انتہائی پیاس محسوس ہوتی ہے۔ وہ خوب پانی پیتا ہے مگر سیر نہیں ہوتا، نتیجتاً پیٹ پھول جاتا ہے اور خراب ہو جاتا ہے۔ آخر مریض اللہ کو پیارا ہو جاتا ہے۔ اعادنا اللہ من سیء الاسقام و میتۃ السوء۔"}],[2053,"ایک صحابی رضی اللہ عنہ سے روایت ہے کہ ایک شخص نے عرض کیا: اللہ کے رسول! کیا بات ہے؟ سبھی اہل ایمان اپنی قبروں میں آزمائے جاتے ہیں، سوائے شہید کے؟ آپ نے فرمایا: \"اس کے سروں پر چمکتی تلوار کی آزمائش کافی ہے\"۔","الألباني: صحيح",{"u2":"حضرت راشد بن سعد نبی صلی اللہ علیہ وسلم کے ایک صحابی سے بیان کرتے ہیں کہ ایک آدمی نے کہا: اے اللہ کے رسول! کیا وجہ ہے کہ اہل ایمان کا ان کی قبروں میں امتحان لیا جاتا ہے مگر شہید کا نہیں؟ آپ نے فرمایا: ’’اس کے سر پر چمکتی تلواریں اس کے لیے امتحان سے کافی ہوگئیں۔‘‘","f2":"(۱) گویا جہاد اور شہادت کا ثواب اس قدر زیادہ ہے کہ سب گناہ معاف ہو جاتے ہیں۔ جب گناہ ہی نہ رہے تو امتحان کا ہے کا؟ شہید کا تلواروں کے نیچے قائم رہنا بلکہ بے جگری سے لڑنا، جنگ سے نہ بھاگنا، جان کی پروا تک نہ کرنا حتی کہ جان قربان کر دینا اس کے ایمان کی واضح دلیل ہے۔ اس سے بڑی دلیل کیا ہوگی؟ لہٰذا سوال و جواب کی ضرورت نہ رہی۔ (۲) مذکورہ حدیث سے یہ بھی استدلال کیا گیا ہے کہ صدیقین سے بھی سوال و جواب نہیں ہوگا کیونکہ ان کا مرتبہ شہداء سے بلند ہے۔ انبیاء علیہم السلام تو ذاتی طور پر اس سے مستثنیٰ ہیں۔"}],[2054,"صفوان بن امیہ رضی اللہ عنہ کہتے ہیں طاعون سے مرنے والا، پیٹ کے مرض میں مرنے والا، ڈوب کر مرنے والا، اور زچگی کی وجہ سے مرنے والی عورت شہید ہے۔ وہ (تیمی) کہتے ہیں: ہم سے ابوعثمان نے بارہا بیان کیا، ایک مرتبہ انہوں نے نبی اکرم صلی اللہ علیہ وسلم سے اسے مرفوع بیان کیا۔","الألباني: صحيح",{"u2":"حضرت صفوان بن امیہ رضی اللہ عنہ فرماتے ہیں: طاعون، پیٹ کی تکلیف، غرق اور دروزہ سے آنے والی موت شہادت ہے۔ (راویٔ حدیث سلیمان تیمی نے) کہا: ہم سے یہ حدیث ابوعثمان نے کئی بار بیان کی۔ اور ایک بار اس کو (مرفوع) نبی صلی اللہ علیہ وسلم کا فرمان بیان کیا۔","f2":"اس قسم کی تکلیف دہ موت قتل سے ملتی جلتی موت ہے، اس لیے اسے بھی شہادت کے ساتھ ملحق کر دیا گیا ہے اور اسے شہادت کے مرتبے پر فائز سمجھا جائے گا، البتہ اس پر شہید کے باقی احکام لاگو نہیں ہوں گے، جیسے انھی خون آلود کپڑوں میں دفنانا اور غسل نہ دینا وغیرہ۔"}],[2055,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہی وہ شخص ہے جس کے لیے عرش الٰہی ہل گیا، آسمان کے دروازے کھول دئیے گئے، اور ستر ہزار فرشتے اس کے جنازے میں شریک ہوئے، (پھر بھی قبر میں) اسے ایک بار بھینچا گیا، پھر (یہ عذاب) اس سے جاتا رہا\" ۱؎۔\n§وضاحت\n۱؎: اس سے مراد سعد بن معاذ رضی اللہ عنہ ہیں۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے (حضرت سعد بن معاذ رضی اللہ عنہ کے دفن کے وقت) فرمایا: ’’یہ شخص جس کے لیے عرش جھوم گیا، اس (کی روح) کے لیے آسمان کے تمام دروازے کھول دیے گئے اور اس کے جنازے پر ستر ہزار فرشتے حاضر ہوئے، وہ بھی بھینچ دیا گیا مگر پھر اسے چھوڑ دیا گیا۔‘‘","f2":"(۱) ’’جھوم گیا‘‘ یعنی ان کے استقبال کی خوشی میں۔ یہ معنی ان کی عظمت و شان پر دلالت کرتے ہیں۔ (۲) ’’بھینچا گیا‘‘ کیونکہ ہر انسان میں کوئی نہ کوئی کمی ہوتی ہے (علاوہ انبیاء علیہم السلام کے کہ وہ معصوم ہوتے ہیں۔) اس بھینچنے سے وہ اس کمی کے اثر سے نجات پا لیتا ہے بشرطیکہ وہ مومن ہو۔ مومن کو صرف ایک دفعہ بھینچا جاتا ہے، پھر چھوڑ دیا جاتا ہے مگر کچھ عجب نہیں کہ کافر پر یہ عذاب بار بار ہوتا ہو۔ حدیث میں آتا ہے کہ قبر ہر ایک کو بھینچتی ہے، اگر اس سے کوئی محفوظ رہتا تو یقیناً حضرت سعد بن معاذ رضی اللہ عنہ محفوظ رہتے۔ (الموسوعۃ الحدیثیۃ مسند الامام أحمد: ۳۲۷/۴۰، رقم: ۲۴۲۸۳، والصحیحۃ: ۲۶۸/۴، رقم: ۱۶۹۵) (۲) اس کی توجیہ میں یہ بات بھی کہی گئی ہے کہ ’’قبر‘‘ انسان کے لیے ماں کی طرح ہے کیونکہ وہ اسی مٹی سے بنایا گیا تھا۔ عرصۂ دراز کے بعد ملنے والے بیٹے کو ماں خوب زور سے اپنے جسم کے ساتھ بھینچتی ہے، چاہے اسے اس سے تکلیف ہی ہو۔ قبر کا معاملہ بھی ایسا ہی ہے، البتہ نیک شخص کو وہ محبت سے بھینچتی ہے اور برے شخص کو غصے اور ناراضی سے۔ نیک کے لیے اس میں سرور ہے اور برے کے لیے عذاب۔ واللہ أعلم۔"}],[2056,"براء بن عازب رضی اللہ عنہما کہتے ہیں آیت کریمہ «يثبت اللہ الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة» \"اللہ ایمان والوں کو دنیا اور آخرت میں ٹھیک بات پر قائم رکھے گا\" (ابراہیم: ۲۷)۔ عذاب قبر کے سلسلے میں نازل ہوئی تھی۔","الألباني: صحيح",{"u2":"حضرت براء رضی اللہ عنہ بیان کرتے ہیں کہ یہ آیت عذاب قبر کے بارے میں اتری ہے: (یثبت اللہ الذین امنوا ……… وفی الاخرۃ) ’’اللہ تعالیٰ مومنین کو دنیا اور آخرت (قبر) میں صحیح بات پر قائم رکھتا ہے۔‘‘","f2":"عذاب قبر سے دو مختلف معانی مراد ہیں: (۱) قبر میں سوال و جواب، اسے فتنہ قبر بھی کہا جاتا ہے۔ (۲) گناہوں کی وجہ سے قبر میں پہنچنے والی تکالیف، کسی حدیث میں پہلے معنی مراد ہوتے ہیں کسی میں دوسرے۔ مندرجہ بالا آیت میں قبر کا سوال و جواب مراد ہے۔ اسی طرح شہید، طاعون، ہیضہ اور حادثاتی موت وغیرہ سے مرنے والوں سے عذاب قبر کی نفی سے مراد بھی سوال و جواب کی نفی ہے جبکہ حضرت سعد رضی اللہ عنہ والی روایت میں دوسرے معنی مراد ہیں اور یہ بھینچے جانے کی حد تک تو سب کو ہوتا ہے (علاوہ انبیاء علیہم السلام کے۔) اس سے زائد اپنے اپنے گناہوں کے مطابق حتی کہ بعض کو قیامت تک ہوگا۔"}],[2057,"براء بن عازب رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"آیت کریمہ «يثبت اللہ الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة» \"اللہ ایمان والوں کو دنیا اور آخرت (دونوں میں) ٹھیک بات پر قائم رکھے گا\"۔ عذاب قبر کے سلسلے میں اتری ہے۔ میت سے پوچھا جائے گا: تیرا رب کون ہے؟ تو وہ کہے گا: میرا رب اللہ ہے، میرا دین محمد صلی اللہ علیہ وسلم کا دین ہے۔ اللہ کے قول: «يثبت اللہ الذين آمنوا بالقول الثابت في الحياة الدنيا وفي الآخرة» سے یہی مراد ہے\"۔","الألباني: صحيح",{"u2":"حضرت براء بن عازب رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’یہ آیت عذاب قبر کے بارے میں نازل ہوئی ہے: (یثبت اللہ الذین امنوا ……… وفی الاخرۃ) ’’اللہ تعالیٰ ایمان والوں کو دنیا و آخرت (قبرر) میں درست بات پر قائم رکھتا ہے۔‘‘ میت سے پوچھا جاتا ہے: تیرا رب کون ہے؟ مومن کہتا ہے: میرا رب اللہ ہے۔ اور میرے نبی حضرت محمد صلی اللہ علیہ وسلم ہیں۔ یہ مطلب ہے اس فرمان الٰہی کا: (یثبت اللہ الذین امنوا ………… وفی الاخرۃ) ’’اللہ تعالیٰ ایمان والوں کو دنیا و پخرت (قبر) میں صحیح بات پر قائم رکھتا ہے۔‘‘"}],[2058,"انس رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے کسی قبر سے ایک آواز سنی تو پوچھا: \"یہ کب مرا ہے؟\" لوگوں نے کہا: زمانہ جاہلیت میں مرا ہے، آپ اس بات سے خوش ہوئے، اور فرمایا: \"اگر یہ ڈر نہ ہوتا کہ تم ایک دوسرے کو دفن کرنا چھوڑ دو گے، تو میں اللہ تعالی سے دعا کرتا کہ وہ تمہیں عذاب قبر سنا دے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے ایک قبر سے آواز سنی تو فرمایا: ’’یہ کب فوت ہوا؟‘‘ لوگوں نے بتایا کہ یہ دور جاہلیت میں فوت ہوا تھا۔ تو آپ کو خوشی ہوئی، پھر فرمایا: ’’اگر یہ خطرہ نہ ہو کہ تم مردوں کو دفن نہیں کر و گے تو میں اللہ تعالیٰ سے دعا کرتا کہ وہ تمھیں عذاب قبر سنا دے۔‘‘","f2":"(۱) اس روایت میں عذاب قبر سے مراد دوسرے معنی ہیں، یعنی گناہوں کے سلسلے میں پہنچنے والا عذاب۔ (۲) ’’خوشی ہوئی‘‘ کہ یہ مدفون شخص مسلمان نہیں تھا۔ مسلمان کو عذاب ہونے سے رسول اللہ صلی اللہ علیہ وسلم کو تکلیف ہوتی۔ خوشی ہونے سے مراد تکلیف کا نہ ہونا اور فکر مندی کا ختم ہونا ہے، ورنہ نبیٔ کریم و رؤف و رحیم صلی اللہ علیہ وسلم کو عذاب پر کیسے خوشی ہوسکتی ہے؟ (۳) ’’دفن نہیں کرو گے‘‘ عذاب قبر کے ڈر سے معلوم ہوتا ہے کہ دفن سے پہلے عذاب قبر شروع نہیں ہوتا، البتہ جو لوگ دفن نہیں کرتے، ان کا عذاب مرتے ہی شروع ہو جاتا ہے۔ اور ان کی قبر سے مراد وہ ٹھکانا ہے جو ان کے جسم یا روح کو مرنے کے بعد دنیا و آرت (برزخ) میں ملتا ہے۔ واللہ علیم قدیر۔ (عذاب قبر کی تفصیل کے لیے دیکھیے، حدیث: ۲۰۵۲)"}],[2059,"ابوایوب انصاری رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سورج ڈوبنے کے بعد نکلے، تو ایک آواز سنی، آپ نے فرمایا: \"یہود اپنی قبروں میں عذاب دیئے جا رہے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابو ایوب رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم غروب شمس کے بعد باہر تشریف لے گئے۔ آپ نے ایک آواز سنی تو فرمایا: ’’یہودیوں کو ان کی قبروں میں عذاب ہو رہا ہے۔‘‘","f2":"عذاب قبر سب کو ہوتا ہے۔ کسی کو سوال و جواب کی حد تک، کسی کو اس سے بڑھ کر بھینچنے کی حد تک، کسی کو کچھ دیر کے لیے، کسی کو ہمیشہ کے لیے (قیامت تک)۔ غالباً وہاں قریب ہی یہودیوں کا قبرستان تھا۔ یہ نبیٔ اکرم صلی اللہ علیہ وسلم کا معجزہ تھا۔"}],[2060,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دعا کرتے تھے: «اللہم إني أعوذ بك من عذاب القبر وأعوذ بك من عذاب النار وأعوذ بك من فتنة المحيا والممات وأعوذ بك من فتنة المسيح الدجال» \"اے اللہ! میں عذاب قبر سے تیری پناہ مانگتا ہوں، جہنم کے عذاب سے تیری پناہ مانگتا ہوں، زندگی اور موت کی آزمائش سے تیری پناہ مانگتا ہوں، اور مسیح دجال کی آزمائش سے (بھی) تیری پناہ مانگتا ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یوں دعا فرمایا کرتے تھے: [اللھم انی أعوذبک من عذاب القبر ……… و أعوذبک من فتنۃ المسیح الدجال] ’’اے اللہ! میں قبر کے عذاب سے بچنے کے لیے تیری پناہ چاہتا ہوں۔ اور آگ کے عذاب سے بچنے کے لیے تیری پناہ چاہتا ہوں۔ اور زندگی و موت کے فتنے سے تیری پناہ چاہتا ہوں اور (جھوٹے) مسیح دجال کے فتنے سے تیری پناہ میں آتا ہوں۔‘‘","f2":"(۱) ’’موت کے فتنے‘‘ سے مراد ممکن ہے موت کے وقت شیطان کے بہکاوے میں آنا ہو یا قبر میں سوال و جواب کے وقت صحیح جواب نہ سوجھنا ہو۔ (۲) اس روایت میں عذاب قبر سے مراد دوسرے معنی ہیں۔ (دیکھیے، حدیث: ۲۰۵۸)"}],[2061,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس کے بعد عذاب قبر سے پناہ مانگتے سنا۔\n§وضاحت\n۱؎: یعنی: یہودی عورت کے عذاب قبر کے ذکر کے بعد آپ نے عذاب قبر سے پناہ مانگنی شروع کر دی تھی، دیکھئیے حدیث رقم: ۲۰۶۶۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ نے فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو اس کے بعد عذاب قبر سے اللہ تعالیٰ کی پناہ مانگتے سنا۔","f2":"’’اس کے بعد‘‘ اشارہ ہے یہودی عورت کی بات کی طرف جس نے عذاب قبر کی بات کی تھی۔ اس کی تفصیل آگے حدیث نمبر ۲۰۶۶ میں آ رہی ہے۔"}],[2062,"اسماء بنت ابی بکر رضی اللہ عنہا کہتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کھڑے ہوئے (اور) اس آزمائش کا ذکر کیا جس سے آدمی اپنی قبر میں دوچار ہوتا ہے، تو جب آپ نے اس کا ذکر کیا تو مسلمانوں نے ایک چیخ ماری جو میرے اور رسول اللہ صلی اللہ علیہ وسلم کی بات سمجھنے کے درمیان حائل ہو گئی، جب ان کی چیخ و پکار بند ہوئیں تو میں نے ایک شخص سے جو مجھ سے قریب تھا کہا: اللہ تجھے برکت دے! رسول اللہ صلی اللہ علیہ وسلم نے اپنے خطاب کے آخر میں کیا کہا تھا؟ اس نے کہا: (آپ نے فرمایا تھا:) \"مجھ پر وحی کی گئی ہے کہ قبروں میں تمہاری آزمائش ہو گی جو دجال کی آزمائش کے قریب قریب ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت اسماء بنت ابی بکر رضی اللہ عنہا نے فرمایا: رسول اللہ صلی اللہ علیہ وسلم (خطبے کے لیے) کھڑے ہوئے تو آپ نے اس آزمائش کا ذکر فرمایا جس میں ہر شخص کو قبر کے اندر مبتلا ہونا پڑے گا۔ جب آپ نے یہ ذکر فرمایا تو مسلمان آہ و بکا کرنے لگے حتی کہ میں رسول اللہ صلی اللہ علیہ وسلم کا کلام نہ سمجھ سکی۔ جب ان کی آہ و بکا کی آواز رک گئی تو میں نے ایک قریبی شخص سے کہا: اللہ تعالیٰ ٰتیرے لیے برکت فرمائے! رسول اللہ ئ نے پخر میں کیا فرمایا ہے؟ اس نے کہا: آپ نے فرمایا تھا: ’’مجھے وحی کی گئی ہے کہ قبروں میں تمھاری فتنۂ دجال جیسی آزمائش ہوگی۔‘‘","f2":"’’فتنہ دجال جیسی آزمائش‘‘ سے مراد قبر میں سوال و جواب ہے۔ اسے فتنۂ دجال سے تشبیہ دی گئی ہے کیونکہ دونوں پر خطر مقام ہیں۔ دجال کی دہشت، اقتدار و اختیارات کے سامنے کلمۂ حق پر قائم رہنا تلوار کی دھار پر چلنے کے مترادف ہے۔ اسی طرح قبر کی ہولناکی، فرشتوں کا رعب، دہشت اور قید تنہائی کوئی معمولی چیز نہیں۔ اللہ تعالیٰ کی رحمت کے بغیر ’’درست بات‘‘ پر قائم رہنا سخت مشکل ہوگا۔"}],[2063,"عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا انہیں اسی طرح سکھاتے تھے جیسے قرآن کی سورت سکھاتے تھے، آپ فرماتے کہو: «اللہم إنا نعوذ بك من عذاب جهنم وأعوذ بك من عذاب القبر وأعوذ بك من فتنة المسيح الدجال وأعوذ بك من فتنة المحيا والممات» \"اے اللہ! ہم تیری پناہ مانگتے ہیں جہنم کے عذاب سے، اور میں تیری پناہ مانگتا ہوں عذاب قبر سے، اور تیری پناہ مانگتا ہوں مسیح دجال کے فتنے سے، اور تیری پناہ مانگتا ہوں موت اور زندگی کی آزمائش سے\"۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم یہ دعا صحابۂ کرام رضی اللہ عنہم کو قرآن کی سورت کی طرح سکھاتے تھے، فرمایا: ’’تم کہو: [اللھم! انا نعوذبک من عذاب جھنم ……… و أعوذبک من فتنۃ المحیا و الممات] اے اللہ! ہم جہنم کے عذاب سے بچنے کے لیے تیری پناہ چاہتے ہیں اور قبر کے عذاب سے بچنے کے لیے تیری پناہ چاہتے ہیں اور (جھوٹے) مسیح دجال کی پزمائش سے بچنے کے لیے تیری پناہ چاہتے ہیں اور زندگی اور موت کے فتنے سے بچنے کے لیے تیری پناہ چاہتے ہیں۔‘‘","f2":"’’دجال‘‘ کو ’’مسیح‘‘ اس لیے کہا گیا کہ اسے یہودی اپنا مسیح قرار دیتے ہیں، نجات دہندہ سمجھتے ہیں اور اس کے انتظار میں ہیں، حالانکہ اصلی مسیح تو عسیٰ علیہ السلام ہیں جو کب کے آچکے اور قیامت کے قریب ان کا دوبارہ آسمان سے نزول ہوگا۔ گویا طنزاً دجال کو مسیح کہا گیا ہے۔ ایک وجہ دجال کا ممسوح العین ہونا بھی ہے۔"}],[2064,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے، میرے پاس ایک یہودی عورت تھی، وہ کہہ رہی تھی کہ تم لوگ قبروں میں آزمائے جاؤ گے، (یہ سن کر) رسول اللہ صلی اللہ علیہ وسلم گھبرا گئے، اور فرمایا: \"صرف یہودیوں ہی کی آزمائش ہو گی\"۔ ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: پھر ہم کئی رات ٹھہرے رہے پھر رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مجھ پر وحی آئی ہے کہ تمہیں (بھی) قبروں میں آزمایا جائے گا\"، اس کے بعد سے میں رسول اللہ صلی اللہ علیہ وسلم کو عذاب قبر سے پناہ مانگتے سنتی رہی۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: (ایک دفعہ) رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے تو میرے پاس ایک یہودی عورت بیٹھی تھی اور وہ کہہ رہی تھی کہ قبروں میں تمھارا امتحان لیا جائے گا (یا تمھیں عذاب ہوگا۔) رسول اللہ صلی اللہ علیہ وسلم گھبرا گئے اور فرمایا: ’’صرف یہود کو عذاب ہوگا۔‘‘ کچھ دن گزرے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مجھے وحی کی گئی ہے کہ قبروں میں تمھارا امتحان ہوگا۔‘‘ حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: اس کے بعد میں نے سنا کہ رسول اللہ صلی اللہ علیہ وسلم عذاب قبر سے اللہ تعالیٰ کی پناہ طلب کیا کرتے تھے۔","f2":"(۱) اس روایت میں امتحان اور عذاب قبر سے مراد ایک ہی چیز ہے، یعنی سوال و جواب۔ اللہ تعالیٰ کی پناہ طلب کرنے کا مطلب ثابت قدمی اور صحیح جواب کی توفیق ہے۔ (۲) ابتداءً نبی صلی اللہ علیہ وسلم کا خیال تھا کہ قبر کا امتحان یا عذاب صرف کفار کے ساتھ خاص ہے۔ بعد میں پتا چلا کہ یہ سب کے ساتھ ہوگا إلا ماشا اللہ۔ ثابت ہوا کہ نبیٔ اکرم صلی اللہ علیہ وسلم کو علم غیب نہ تھا۔ اسی وجہ سے آپ نے انکار کر دیا تھا، بعد میں بذریعۂ وحی اللہ تعالیٰ نے خبر دی تو پتا چلا۔"}],[2065,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم قبر کے عذاب، اور دجال کے فتنے سے پناہ طلب کرتے، اور فرماتے: \"تم اپنی قبروں میں آزمائے جاؤ گے\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے کہ نبی صلی اللہ علیہ وسلم عذاب قبر اور فتنہ دجال سے اللہ تعالیٰ کی پناہ طلب کیا کرتے تھے اور نبی صلی اللہ علیہ وسلم نے فرمایا: ’’قبروں میں تمھارا امتحان ہوگا۔‘‘"}],[2066,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ ایک یہودی عورت ان کے پاس آئی (اور) اس نے ان سے کوئی چیز مانگی تو عائشہ رضی اللہ عنہا نے اسے دیا تو اس نے کہا: اللہ تجھے قبر کے عذاب سے بچائے! عائشہ رضی اللہ عنہا کہتی ہیں: تو اس کی یہ بات میرے دل میں بیٹھ گئی یہاں تک کہ رسول اللہ صلی اللہ علیہ وسلم آئے تو میں نے آپ سے اس کا ذکر کیا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"انہیں ان کی قبروں میں عذاب دیا جاتا ہے جسے چوپائے سنتے ہیں\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت مسروق سے روایت ہے کہ ایک یہودی عورت حضرت عائشہ رضی اللہ عنہا کے پاس آئی اور ان سے کوئی چیز مانگی۔ حضرت عائشہ رضی اللہ عنہا نے وہ چیز اسے دے دی۔ تو اس نے کہا: اللہ تعالیٰ تجھے عذاب قبر سے بچائے۔ حضرت عائشہ رضی اللہ عنہا نے فرمایا: ’’مجھے اس بارے میں کچھ تردد ہوا حتی کہ جب رسول اللہ صلی اللہ علیہ وسلم تشریف لائے تو میں نے یہ بات آپ سے بیان کی۔ آپ نے فرمایا: ’’یقینا ان (یہودیوں) کو ان کی قبروں میں عذاب ہوتا ہے حتی کہ جانور اسے سنتے ہیں۔‘‘"}],[2067,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں یہود مدینہ کی بوڑھی عورتوں میں سے دو عورتیں میرے پاس آئیں، (اور) کہنے لگیں کہ قبر والوں کو ان کی قبروں میں عذاب دیا جاتا ہے، تو میں نے ان کو جھٹلا دیا اور مجھے یہ بات اچھی نہیں لگی کہ میں ان کی تصدیق کروں، وہ دونوں نکل گئیں (تبھی) رسول اللہ صلی اللہ علیہ وسلم میرے پاس آئے تو میں نے عرض کیا: اللہ کے رسول! یہود مدینہ کی بوڑھیوں میں سے دو بوڑھیاں کہہ رہی تھیں کہ مردوں کو ان کی قبروں میں عذاب دیا جاتا ہے، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان دونوں نے سچ کہا، انہیں عذاب دیا جاتا ہے جسے سارے چوپائے سنتے ہیں\"، (پھر) میں نے دیکھا آپ ہر صلاۃ کے بعد عذاب قبر سے پناہ مانگتے تھے۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں: مدینے کی دو یہودی عورتیں میرے پاس آئیں اور کہنے لگیں کہ قبروں والوں کو ان کی قبروں میں عذاب ہوتا ہے۔ میں نے ان کی تکذیب کی۔ میرا دل ان کی تصدیق پر مطمئن نہ ہوا۔ وہ چلی گئیں تو رسول اللہ صلی اللہ علیہ وسلم میرے پاس تشریف لائے۔ میں نے عرض کیا: اے اللہ کے رسول! دو بوڑھی یہودی عورتوں نے کہا ہے کہ فوت شدگان کو قبروں میں عذاب ہوتا ہے۔ آپ نے فرمایا: ’’وہ سچ کہتی ہیں۔ ان کو عذاب ہوتا ہے حتی کہ جانور اسے سنتے ہیں۔‘‘ اس کے بعد میں نے دیکھا کہ جب بھی آپ نے نماز پڑھی، عذاب قبر سے ضرور پناہ طلب کی۔"}],[2068,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں رسول اللہ صلی اللہ علیہ وسلم مکہ یا مدینہ کے باغات میں سے ایک باغ کے پاس سے گزرے، تو آپ نے دو انسانوں کی آوازیں سنیں جنہیں ان کی قبروں میں عذاب دیا جا رہا تھا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"ان دونوں کو عذاب دیا جا رہا ہے، اور انہیں کسی بڑے جرم میں عذاب نہیں دیا جا رہا ہے ۱؎، بلکہ ان میں سے ایک اچھی طرح اپنے پیشاب سے پاکی نہیں حاصل کرتا تھا، اور دوسرا چغل خوری ۲؎ کرتا تھا\"، پھر آپ نے ایک ٹہنی منگوائی (اور) اس کے دو ٹکڑے کئے پھر ان میں سے ہر ایک کی قبر پر ایک ایک ٹکڑا رکھ دیا، تو آپ سے سوال کیا گیا: اللہ کے رسول! آپ نے ایسا کیوں کیا؟ تو آپ نے فرمایا: \"شاید ان کے عذاب میں نرمی کر دی جائے جب تک یہ دونوں (ٹہنیاں) خشک نہ ہوں\"۔ راوی کو شک ہے کہ آپ نے «ما لم ييبسا أو أن ييبسا» فرمایا، یا «إلى أن ييبسا» فرمایا۔\n§وضاحت\n۱؎: کسی بڑے جرم میں عذاب نہیں دیا جا رہا ہے کا مطلب ہے ان کے خیال میں وہ کوئی بڑا جرم نہیں ورنہ شریعت کی نظر میں تو وہ بڑا جرم تھا، اور بعض لوگوں نے کہا ہے کہ کبیر سے مراد ہے کہ ان کا ترک کرنا کوئی زیادہ مشکل امر نہیں تھا اگر چاہتا تو آسانی سے اس گناہ سے بچ سکتا تھا۔ ۲؎: دو آدمیوں میں فساد ڈالنے کی نیت سے ایک بات دوسرے تک پہنچانے کا نام چغل خوری ہے۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دو قبروں کے پاس سے گزرے اور فرمایا: ’’ان دونوں کو عذاب ہو رہا ہے اور یہ عذاب کسی بڑے کام کے بارے میں نہیں ہو رہا۔ ان میں سے ایک شخص تو اپنے پیشاب سے بچتا نہ تھا اور دوسرا چغلیاں کھایا کرتا تھا۔‘‘ پھر آپ نے کھجور کی ایک تازہ شاخ لی، اسے چیر کر دو حصے کیے اور پھر ہر قبر پر ایک حصہ گاڑ دیا۔ لوگوں نے عرض کیا: اے اللہ کے رسول! آپ نے ایسے کیوں کیا؟ آپ نے فرمایا: ’’مجھے امید ہے جب تک یہ خشک نہیں ہوں گی، ان سے عذاب میں تخفیف رہے گی۔‘‘","f2":"(۱) ’’وہ بڑی ہی ہے۔‘‘ مطلب یہ ہے کہ ان کے لیے یہ کوئی مشکل اور بھاری کام نہ تھا، جبکہ حقیقتاً تھا وہ کبیرہ گناہ ہی۔ (۲) ’’پیشاب سے نہ بچتا۔‘‘ (یعنی وہ شخص چھینٹوں سے پرہیز نہیں کرتا تھا۔ (۳) ’’چغلیاں‘‘ باہمی لڑائی اور فساد ڈالنے کے لیے ادھر کی بات ادھر اور ادھر کی ادھر پہنچانا، چاہے وہ سچ ہی ہو۔ یہ بھی گناہ کبیرہ ہے کیونکہ فساد سے بری کوئی چیز نہیں۔ دروغ مصلحت آمیز بہ، از راستیٔ فتنہ انگیز۔ ’’جس سچ سے فساد بڑھے اس سے وہ مصلحت آمیز جھوٹ، جس سے فساد مٹے، بہتر ہے۔‘‘ (۴) نبی صلی اللہ علیہ وسلم کا ان قبروں پر چھڑیاں رکھنا آپ کی فعلی شفاعت ہے کہ یا اللہ! ان کے خشک ہونے تک ان سے عذاب رک جائے۔ اس کا مطلب یہ نہیں کہ ہم بھی چھڑیاں رکھنا شروع کر دیں۔ اگر اس طرح چھیڑیاں رکھنے سے عذاب رک جاتا ہو تو پھر تو لوگ قبر پر درخت ہی لگا دیا کریں، وہ خشک ہو نہ عذاب شروع ہو۔ یہ تو سب سے آسان طریقہ ہے۔ حقیقت یہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے یہ فعل وحی کی بنیاد پر متعین وقت کے لیے کیا تھا، ورنہ چھیڑی کا عذاب کی تخفیف سے کوئی تعلق نہیں۔ رسول اللہ صلی اللہ علیہ وسلم نے بھی اس واقعے کے علاوہ کبھی کسی قبر پر چھڑی نہیں رکھی۔ یہ آپ کا خاصہ تھا، سنت نہیں۔ اس حدیث سے بزرگوں کی قبروں پر پھول چڑھانے کے لیے استدلال کرنا عجیب ہے۔ اس استدلال کا منطقی نتیجہ یہ ہے کہ ان کا عمل یہ واضح کر رہا ہے کہ ان کے بزرگوں کو یا قبروں میں مدفون لوگوں کو عذاب ہو رہا ہے۔ ورنہ قبروں پر گل پاشی وغیرہ کرنے کا کیا جواز ہے؟"}],[2069,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم دو قبر کے پاس سے گزرے تو آپ نے فرمایا: \"ان دونوں کو عذاب دیا جا رہا ہے، اور یہ کسی بڑے جرم میں عذاب نہیں دئیے جا رہے ہیں، رہا ان میں سے ایک تو وہ اپنے پیشاب سے اچھی طرح پاکی حاصل نہیں کرتا تھا، اور رہا دوسرا تو وہ چغل خوری کرتا تھا، پھر آپ نے کھجور کی ایک ہری ٹہنی لی (اور) اسے آدھا آدھا چیر دیا، پھر ہر ایک کی قبر پہ گاڑ دیا\"، تو لوگوں نے پوچھا: اللہ کے رسول! آپ نے ایسا کیوں کیا؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"شاید ان دونوں کا عذاب ہلکا کر دیا جائے جب تک یہ دونوں (ٹہنیاں) خشک نہ ہوں\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! جب تم میں سے کوئی شخص فوت ہو جاتا ہے تو اس پر اس کا ٹھکانا صبح شام پیش کیا جاتا ہے۔ اگر وہ جنتی ہو تو جنتی ٹھکانا اور اگر وہ جہنمی ہو تو جہنمی ٹھکانا (اور یہ سلسلہ جاری رہے گا) حتی کہ اللہ تعالیٰ اسے قیامت کے دن قبر سے اٹھا لے (تو پھر وہ اس میں داخل ہو جائے گا)۔‘‘"}],[2070,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"سنو! جب تم میں سے کوئی مر جاتا ہے تو اس پر صبح و شام اس کا ٹھکانہ پیش کیا جاتا ہے، اگر جنتی ہے تو جنت میں کا، اور اگر جہنمی ہے تو جہنم میں کا، یہاں تک کہ اللہ تعالی اسے قیامت کے روز اٹھائے\" ۱؎۔\n§وضاحت\n۱؎: یعنی اٹھائے جانے کے بعد یہ سلسلہ ختم ہو جائے گا، اور وہ اپنے اس ٹھکانے میں پہنچ جائے گا۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’خبردار! جب تم میں سے کوئی شخص فوت ہو جاتا ہے تو اس پر اس کا ٹھکانا صبح شام پیش کیا جاتا ہے۔ اگر وہ جنتی ہو تو جنتی ٹھکانا اور اگر وہ جہنمی ہو تو جہنمی ٹھکانا (اور یہ سلسلہ جاری رہے گا) حتی کہ اللہ تعالیٰ اسے قیامت کے دن قبر سے اٹھا لے (تو پھر وہ اس میں داخل ہو جائے گا)۔‘‘","f2":"ابن عمر رضی اللہ عنہا کی اس حدیث کی باب سے مناسبت واضح نہیں کیونکہ اس میں چھڑیوں کے قبر پر رکھنے کا ذکر نہیں۔ ممکن ہے نساخ سے ترجمۃ الباب ساقط ہوگیا ہو۔ امام بخاری رحمہ اللہ نے صحیح بخاری میں اس حدیث پر یہ باب باندھا ہے: [باب: المیت یعرض علیہ مقعدہ بالغداۃ والعشي] ’’میت پر اس کا (ابدی) ٹھکانا صبح شام پیش کیا جاتا ہے۔‘‘"}],[2071,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی مرتا ہے تو اس پر صبح و شام اس کا ٹھکانا پیش کیا جاتا ہے، چنانچہ اگر وہ جہنمی ہے تو جہنمیوں (کے ٹھکانوں) میں سے (پیش کیا جائے گا)، اور کہا جاتا ہے: یہ ہے تمہارا ٹھکانا یہاں تک کہ اللہ تعالی تمہیں قیامت کے روز اٹھائے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص مر جاتا ہے تو اس پر اس کا ٹھکانا صبح شام پیش کیا جاتا ہے۔ اگر وہ جنتی ہو تو جنتی ٹھکانا پیش کیا جاتا ہے اور اگر وہ جہنمی ہو تو جہنمی ٹھکانا پیش کیا جاتا ہے اور اسے کہا جاتا ہے کہ یہ تیرا ٹھکانا ہے حتی کہ تجھے اللہ تعالیٰ قیامت کے دن اس سے اٹھائے۔‘‘","f2":"بات ہر جنتی اور جہنمی میت سے کہی جاتی ہے۔ یہاں صرف جہنمی کا ذکر ہے۔ یہ غالباً کسی راوی کا اختصار ہے، ورنہ دوسری روایات میں اہل جنت اور اہل نار دونوں کا ذکر ہے۔ اس حدیث کی بھی باب سے مناسبت واضح نہیں ہے کیونکہ اس میں بھی چھڑیاں رکھنے کا ذکر مفقود ہے۔"}],[2072,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم میں سے کوئی مرتا ہے تو اس کا ٹھکانا اس پر صبح و شام پیش کیا جاتا ہے، اگر وہ جنتی ہے تو جنتیوں (کے ٹھکانوں) میں سے، اور اگر جہنمی ہے تو جہنمیوں (کے ٹھکانوں) میں سے، (اور اس سے) کہا جاتا ہے: یہ تمہارا ٹھکانا ہے یہاں تک کہ اللہ عزوجل تمہیں قیامت کے روز اٹھائے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہما سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم میں سے کوئی شخص مر جاتا ہے تو اس پر اس کا ٹھکانا صبح شام پیش کیا جاتا ہے۔ اگر وہ جنتی ہو تو جنتی ٹھکانا پیش کیا جاتا ہے اور اگر وہ جہنمی ہو تو جہنمی ٹھکانا پیش کیا جاتا ہے اور اسے کہا جاتا ہے کہ یہ تیرا ٹھکانا ہے حتی کہ تجھے اللہ تعالیٰ قیامت کے دن اس سے اٹھائے۔‘‘","f2":"’’یہ تیرا ٹھکانا ہے‘‘ اشارہ اصل ٹھکانے کی طرف ہے، یعنی تیرا اصل ٹھکانا تو یہی ہے (جو پیش کیا جاتا ہے) مگر فی الحال تو اس میں نہیں جا سکتا۔"}],[2073,"کعب بن مالک رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"مومن کی جان جنت کے درختوں پہ اڑتی رہے گی یہاں تک کہ قیامت کے دن اللہ تعالی اسے اس کے جسم کی طرف بھیج دے\"۔","الألباني: صحيح",{"u2":"حضرت کعب بن مالک رضی اللہ عنہ بیان کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مومن کی روح (وفات کے بعد) جنت کے درختوں میں اڑتی رہتی ہے حتی کہ اللہ تعالیٰ قیامت کے دن اسے اس کے جسم میں داخل کرے گا۔‘‘","f2":"مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ سنن ابن ماجہ کی تحقیق میں بعینہٖ اسی روایت پر سنداً ضعف کا حکم لگانے کے بعد لکھتے ہیں کہ اس سے سنن ابن مجہ ہی کی روایت نمبر: ۴۲۷۱، کفایت کرتی ہے جس سے معلوم ہوتا ہے کہ مذکورہ روایت محقق کتاب کے نزدیک بھی قابل حجت ہے۔ علاوہ ازیں دیگر محققین نے بھی اسے صحیح قرار دیا ہے۔ بنابریں مذکورہ روایت سنداً ضعیف ہونے کے باوجود دیگر شواہد اور متابعات کی بنا پر قابل حجت ہے۔ واللہ أعلم۔ مزید تفصیل کے لیے دیکھیے: (الموسوعۃ الحدیثیۃ مسند الامام احمد: ۵۹-۵۵/۲۵، والصحیحہ للألبانی، رقم: ۹۹۵، و ذخیرۃ العقبی شرح سنن النسائي: ۱۴۳-۱۲۳/۲۰) ’’جسم‘‘ سے مراد برزخی جسم ہے جس پر برزخی زندگی کی کیفیتا گزریں گی جس کی اصل حقیقت اللہ ہی جانتا ہے، تاہم وہاں اسے جنت اور جہنم کی نعمتوں اور تکلیفوں کا احساس ہوگا۔"}],[2074,"انس رضی اللہ عنہ کہتے ہیں کہ ہم عمر رضی اللہ عنہ کے ساتھ مکہ اور مدینہ کے درمیان تھے کہ وہ ہم سے اہل بدر کے سلسلہ میں بیان کرنے لگے، اور کہنے لگے کہ رسول اللہ صلی اللہ علیہ وسلم نے ہمیں (کافروں کے) مارے جانے کی جگہیں ایک دن پہلے دکھلا دیں، اور فرمایا: \"اگر اللہ تعالی نے چاہا تو کل فلاں کے پچھاڑ کھا کر گرنے کی جگہ یہاں ہو گی، اور فلاں کی یہاں\"، عمر رضی اللہ عنہ کہتے ہیں: قسم اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا! ان جگہوں میں کوئی فرق نہیں آیا، چنانچہ انہیں ایک کنویں میں ڈال دیا گیا، (پھر) نبی اکرم صلی اللہ علیہ وسلم ان کے پاس آئے، (اور) پکارا: \"اے فلاں، فلاں کے بیٹے! اے فلاں، فلاں کے بیٹے! کیا تم سے تمہارے رب نے جو وعدہ کیا تھا اسے صحیح پایا؟ میں نے تو اللہ نے جو وعدہ مجھ سے کیا تھا اسے صحیح پایا\"، اس پر عمر رضی اللہ عنہ نے کہا: آپ ایسے جسموں سے بات کر رہے ہیں جن میں روح نہیں؟ تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو میں کہہ رہا ہوں اسے تم ان سے زیادہ نہیں سنتے\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ سے روایت ہے کہ ہم مکہ مکرمہ اور مدینہ منورہ کے درمیان حضرت عمر رضی اللہ عنہ کے ساتھ تھے۔ وہ ہمیں بدر کے کافر مقتولین کے بارے میں بتانے لگے کہ اللہ کے رسول صلی اللہ علیہ وسلم جنگ سے ایک دن قبل ہمیں ان کے ہلاک ہونے کی جگہیں دکھا رہے تھے۔ آپ نے فرمایا: ’’ان شاء اللہ کل یہ فلاں کی ہلاکت گاہ ہوگی۔‘‘ حضرت عمر نے فرمایا: قسم اس ذات کی جس نے آپ کو برحق نبی بنایا! وہ ان جگہوں سے ذرہ بھر بھی ادھر ادھر نہیں ہوئے، پھر انھیں ایک کنویں میں پھینک دیا گیا، پھر نبی صلی اللہ علیہ وسلم ان کے پاس (اس کنویں پر) گئے اور بلند آواز سے پکارا: ’’اے فلاں بن فلاں! اے فلاح بن فلاح! کیا تم نے سچ پائی وہ چیز جس کا تم سے تمھارے رب نے وعدہ کیا تھا؟ میں نے تو اللہ کے وعدے کو سچ پایا ہے۔‘‘ حضرت عمر رضی اللہ عنہ نے کہا: آپ ایسے اجسام سے باتیں کر رہے ہیں جن میں روح نہیں؟ آپ نے فرمایا: ’’تم میری باتوں کو ان سے زیادہ سننے والے نہیں۔‘‘","f2":"(۱) کفار کی ہلاکت گاہوں کا تعین وحی سے تھا، لہٰذا ہر مقتول آپ کی بیان کردہ جگہ ہی میں مرا۔ (۲) کنویں میں انھیں پھینکنا تعفن سے بچنے کے لیے تھا، نیز اس میں کچھ ان کے جسموں کی حفاظت بھی تھی۔ معلوم ہوا کافر کی لاش کو بھی محفوظ کیا جا سکتا ہے۔ (۳) ’’بلند آواز سے پکارا‘‘ روایت کے ظاہر الفاظ سے یہی معلوم ہوتا ہے کہ ان مقتولین نے رسول اللہ صلی اللہ علیہ وسلم کے الفاظ سنے۔ اس سے استدلال کیا گیا ہے کہ مردے سنتے ہیں لیکن ان میں حس و حرکت نہیں ہوتی، یعنی جواب نہیں دے سکتے۔ جو اہل علم اس کے قائل نہیں ہیں، وہ اس حدیث میں سماع کو علم کے معنی میں لیتے ہیں بلکہ حضرت عائشہ رضی اللہ عنہا سے تو یہ الفاظ آتے ہیں کہ آپ نے اسمع کے بجائے أعلم کے لفظ ہی ارشاد فرمائے تھے۔ دیکھیے، (صحیح البخاري، المغازي، حدیث: ۳۹۷۹) یعنی اب ان کو پتا چل چکا ہے کہ اللہ تعالیٰ کے وعدے سچے تھے۔ ان کے نزدیک أسمع کا لفظ سننے والے صحابی کی غلط فہمی ہے۔ مگر محققین نے حضرت عائشہ رضی اللہ عنہا کی اس توجیہ کو ت سلیم نہیں کیا، اس لیے کہ وہ موقع پر موجود نہ تھیں جبکہ راویٔ حدیث حضرت عمر رضی اللہ عنہ موقع کے گواہ ہیں، البتہ مجازاً ’’سماع‘‘ سے علم مراد لیا جا سکتا ہے کیونکہ سماع، علم کا سبب ہے۔ سبب بول کر مسبب مراد لینا بلغاء کے کلام میں عام ہے۔ بعض اہل علم نے کہا ہے اصل یہی ہے کہ مردے نہیں سنتے مگر اللہ تعالیٰ چاہے تو انھیں کبھی کبھار کوئی بات سنا سکتا ہے۔ نبی صلی اللہ علیہ وسلم کی باتیں بھی اللہ تعالیٰ نے انھیں سنا دیں تاکہ ان کی ندامت، حسرت، افسوس اور عذاب میں اضافہ ہو۔ حضرت قتادہ نے یہی مفہوم مراد لیا ہے۔ (صحیح البخاري، المغازي، حدیث: ۳۹۷۶) تمام نصوص کو تسلیم کرنے کے لیے یہ توجیہ بہت مناسب ہے۔ ورنہ کسی نہ کسی نص کا انکار لازم آئے گا۔"}],[2075,"انس رضی اللہ عنہ کہتے ہیں کہ مسلمانوں نے رات کو بدر کے کنویں پر رسول اللہ صلی اللہ علیہ وسلم کو کھڑے آواز لگاتے سنا: \"اے ابوجہل بن ہشام! اے شیبہ بن ربیعہ! اے عتبہ بن ربیعہ! اور اے امیہ بن خلف! کیا تم سے تمہارے رب نے جو وعدہ کیا تھا اسے تم نے صحیح پایا؟، میں نے تو اپنے رب کے وعدہ کو صحیح پایا\"، لوگوں نے عرض کیا: اللہ کے رسول! آپ ان لوگوں کو پکارتے ہیں جو محض بدبودار لاش ہیں؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"جو میں کہہ رہا ہوں اسے تم ان سے زیادہ نہیں سن سکتے، لیکن (فرق صرف اتنا ہے کہ) وہ جواب نہیں دے سکتے\"۔","الألباني: صحيح",{"u2":"حضر ت انس رضی اللہ عنہ فرماتے ہیں کہ مسلمانوں نے (جنگ بدرکے بعد) رات کو بد ر کے کنویں پر رسول اللہ کو کھڑے فر ماتے ہوئے سنا: \" اے ابو جہل بن ہشا! اے شیبہ بن ربیعہ!\nاے عتبہ بن ربیعہ! اے امیہ بن حلف! کیا تم نے اپنے رب کا وعدہ سچ پا یا؟میں نے تو اپنے رب کا و عدہ سچ پا یا ہے۔ \" لو گوں نے کہا: اے اللہ کے رسول!ٗ ا ٓٓٓٓ پ ان لو گو ں کو پکار رہے ہیں جو لا ش بن چکے ہیں؟ آپ نے فرمایا:\" تم میری بات کو ان سے زیا د ہ نہیں سنتے مگر وہ جواب نہیں دے سکتے۔\""}],[2076,"عبداللہ بن عمر رضی اللہ عنہما سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم بدر کے کنویں پہ کھڑے ہوئے (اور) فرمایا: \"کیا تم نے اپنے رب کے وعدہ کو صحیح پایا؟\"(پھر) آپ نے فرمایا: \"اس وقت جو کچھ میں ان سے کہہ رہا ہوں اسے یہ لوگ سن رہے ہیں\"، تو ام المؤمنین عائشہ رضی اللہ عنہا سے ذکر کیا گیا، تو انہوں نے کہا: ابن عمر رضی اللہ عنہما سے بھول ہوئی ہے، رسول اللہ صلی اللہ علیہ وسلم نے (یوں) کہا تھا: \"یہ لوگ اب خوب جان رہے ہیں کہ جو میں ان سے کہتا تھا وہ سچ تھا\"، پھر انہوں نے اللہ کا قول پڑھا: «إنك لا تسمع الموتى» (النمل: ۸۰) یہاں تک کہ پوری آیت پڑھی۔","الألباني: صحيح",{"u2":"حضرت ابن عمر رضی اللہ عنہ سے روایت ہے کہ نبی صلی اللہ علیہ وسلم (جنگ بد ر سے اگلے دن) بد ر کے کنویں کے کنارے جا کھڑ ے ہوئے اور فرمایا: \" کیاتم نے اپنے رب کے وعدے کو بر حق پایا؟\" آپ نے فرمایا:اب یہ میری بات کو بخوبی سن رہےہیں۔\" یہ بات حضرت عائشہ رضی اللہ عنہا سے ذکر کی گئی تع انھوں نے فرمایا: بن عمر کو غلط فہمی ہوگئی ہے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا تھا: \" اب وہ بخو بی جان چکے ہیں کہ میں جو کچھ ان کو کہتا رہا ہوں، وہ بالکل سچ ہے۔\" پھر انہوں نے اللہ تعالیٰ کا یہ فرمان پڑ ھا (انک لا تسمع المو تی۔۔۔۔) \" یقینا تو مردوں کو نہیں سنا سکتا۔ انھون نے پوری آیت پڑھی۔","f2":"حضرت عائشہ رضی اللہ عنہا کی مندرجہ بالا تاویل پر بحث حدیث نمبر 2076 میں گز ر چکی ہے۔ اور اس مسئلے کی مختصر تحقیق بھی۔ با قی رہا حضرت عائشہ رضی اللہ عنہا کا مذکورہ آیت سے استدلا ل تو جواب یہ ہے کہ نفی آپ کے سنانے کی ہے، نہ کہ اللہ تعالیٰ کے سنانے کی (ان اللہ یسمع من یشا) اور آپ کے الفاظ ان کو اللہ تعالیٰ نے سنائے تھے،نیز رسول اللہ صلی اللہ علیہ وسلم نے ان کے سننے کی جو تصریح فر مائی ہے تو وہ سماع وقتی تھا جیسا کہ احادیث میں \"الا ن \" کی قید آتی ہے، یقینا یہ رسو ل اللہ صلی اللہ علیہ وسلم کا معجزہ ہی ہے۔ بہر حال سماع مو تیٰ کا مسئلہ متکلم فیہ ہے۔ اہل علم کا ایک گرہ سماع مو تیٰ کا قائل ہے، دوسرا قائل نہیں۔ کچھ محقیقن معتدل ہیں جیسا کہ حدیث نمبر 2076کے فوائد میں گز را لیکن یاد رہے، سما ع موتیٰ کے قائل ہونے کایہ مطلب ہر گز نہیں کہ انھیں عبادت میں پکارنا جائز ہے کیونکہ حاجات میں تو زندوں کو پکارنا بھی جائز نہیں جو کہ سب کے نزدیک سنتے ہیں، پھر مردو ں کو پکارنا کس طر ح جائز ہو گا واللہ اعلم۔"}],[2077,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"بنی آدم (کے جسم کا ہر حصہ)، (مغیرہ والی حدیث میں ہے) ابن آدم (کے جسم کے ہر حصہ کو) مٹی کھا جاتی ہے، سوائے اس کی ریڑھ کی ہڈی کے، اسی سے وہ پیدا کیا گیا ہے، اور اسی سے (دوبارہ) جوڑا جائے گا\"۔","الألباني: صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \" (مرنے کے بعد) انسان کے تمام اعضاء کو مٹی کھا لیتی ہے سوائے بن دُم کے۔ (ریڑ ھ کی ہڈی کا آخر ی سرا) اسی وجہ سے انسان کی پیدائش کی ابتدا ہوئی اور اسی سے (دوبارہ) جسم جوڑا جائے گا۔\"","f2":"(1)\"مٹی کھا لیتی ہے \" یعنی سب اعضا ء مٹی بن جاتے ہیں لیکن یہ ہر شخص میں ضروری نہیں کیونکہ انبیاء علیہ السلام کے بارے میں صراحت ہے کہ ان کے اجسام مقدسہ جو ں کے توں رہتےہیں، حدیث میں ہے: \" بلاشبہ اللہ تعالیٰ نے زمین پر حرام کردیا ہے کہ وہ پیغمبرو ں کے جسموں کو کھائے۔\" ّ(سنن ا بی داود الصلاۃ باب فضل یوم الجمعۃ، حدیث: 1047، وسنن ماجہ، اقامۃ الصلوات، باب فی فضل الجمعۃ، حدیث 1085) ان کے علاوہ بھی کسی کا جسم، اگر اللہ تعالی ٰ چاہے، یعنی باقی رہ سکتا ہے۔ (2)\" بن دم \" یہ بہت ہی چھوٹا اور لطیف حصہ ہے جو ضروری نہیں کہ الگ نظر ا ٓئے۔ ایک اور روایت میں آپ نے اسے رائی کر دانے سے تشبیہ دی ہے۔ دیکھیے: (المو سو عۃ الحدیث مسند الا مام ا حمد: 17/332، حدیث:111230) یعنی بہت چھوٹا۔ کہا گیا ہے کہ انسان جسم میں سب سے پہلے یہ حصہ بنتا ہے اور اخروی جسم بھی اسی سے بنے گا۔ اور یہ قیامت تک۔ ان کے نزدیک اس حدٰیث کا مطلب ہ ہے کہ جب نیا جسم بنے گا تو اس کی ابتدا بھی بن دم سے ہوگی اگر چہ وہ نیا بنایا جائے۔واللہ اعلم"}],[2078,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اللہ تعالی فرماتا ہے ابن آدم نے مجھے جھٹلایا حالانکہ مجھے جھٹلانا اس کے لیے مناسب نہ تھا، ابن آدم نے مجھے گالی دی حالانکہ مجھے گالی دینا اس کے لیے مناسب نہ تھا، رہا اس کا مجھے جھٹلانا تو وہ اس کا (یہ) کہنا ہے کہ میں اسے دوبارہ پیدا نہیں کر سکوں گا جیسے پہلی بار کیا تھا، حالانکہ آخری بار پیدا کرنا پہلی بار پیدا کرنے سے زیادہ دشوار مشکل نہیں، اور رہا اس کا مجھے گالی دینا تو وہ اس کا (یہ) کہنا ہے کہ اللہ کے بیٹا ہے، حالانکہ میں اللہ اکیلا اور بے نیاز ہوں، نہ میں نے کسی کو جنا، نہ مجھے کسی نے جنا، اور نہ کوئی میرا ہم سر ہے\"۔","الألباني: حسن صحيح",{"u2":"حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فر ما یا:\" اللہ عزوجل نے فر مایا: آدم کا بیٹا میری تکذیب کر تا ہے، حالانکہ اسے میری تکذیب جچتی نہیں۔\n(اسی طرح) آدم کا یبٹا مجھے گالی دیتا ہے، حا لانکہ اسے جچتا نہیں کہ وہ مجھے گالی دے۔ اس کا میری تکذیب کر نا تو یہ ہے کہ وہ کہتا ہے: اللہ تعالیٰ مجھے دوبارہ پیدا نہیں کرسکے گا، حالانکہ میں نے اسے پہلی دفعہ پیدا کیا ہے اور دوسری دفعہ بنایا میرے لیے پہلی دفعہ سے مشکل نہیں۔ اور اس کا مجھے گالی دینا یہ ہے کہ وہ کہتا ہے: اللہ تعالی ٰ کی بھی اولا د ہے، حالانکہ میں یکتا اللہ ہو ں جس کو کسی قطعا کو ئی ضرورت نہیں۔ نہ مجھ سے کوئی پیدا ہو ا، نہ میں کسی سے پیدا ہو ا اور نہ کوئی میرا ہمسر ہے۔\"","f2":"(۱) ’’آدم کا بیٹا‘‘ کہنے کا مقصد، انسان کو اس کی اصلیت یاد دلانا ہے کہ اسے شرم آنی چاہیے، وہ مٹی سے بن کر اللہ تعالیٰ کی قدرت سے انکار کرتا ہے یا اللہ تعالیٰ کو اپنے جیسا سمجھتا ہے۔ (۲) ’’میری تکذیب‘‘ یعنی میری قدرت کی تکذیب، نیز جب قدرت کی تکذیب کر دی تو گویا ذات ہی کی تکذیب کر دی۔ (۳) ’’گالی‘‘ جو چیز کسی کے لائق نہ ہو، اس کی طرف نسبت کرنا گالی ہی ہے، جیسے کسی غیرشادی شدہ کی طرف اولاد کی نسبت کی جائے۔"}],[2079,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو کہتے سنا: \"ایک بندے نے اپنے اوپر (بڑا) ظلم کیا، یہاں تک کہ موت (کا وقت) آپ پہنچا، تو اس نے اپنے گھر والوں سے کہا: جب میں مر جاؤں تو مجھے جلا دینا، پھر مجھے پیس ڈالنا، کچھ ہوا میں اڑا دینا اور کچھ سمندر میں ڈال دینا، اس لیے کہ اللہ کی قسم! اگر اللہ تعالی مجھ پر قادر ہوا تو ایسا (سخت) عذاب دے گا کہ ویسا عذاب اپنی کسی مخلوق کو نہیں دے گا\"، تو اس کے گھر والوں نے ایسا ہی کیا، اللہ تعالی نے ہر چیز کو جس نے اس کا کچھ حصہ لیا تھا حکم دیا کہ حاضر کرو جو کچھ تم نے لیا ہے، تو کیا دیکھتے ہیں کہ وہ سامنے کھڑا ہے، (تو) اللہ تعالی نے اس سے پوچھا: تجھے ایسا کرنے پر کس چیز نے اکسایا؟ اس نے کہا: تیرے خوف نے، تو اللہ تعالی نے اسے بخش دیا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے سنا: ’’ایک آدمی نے اپنے آپ پر بہت ظلم کیا تھا (بہت گناہ کیے تھے) حتی کہ اس کی وفات کا وقت آگیا۔ اس نے اپنے گھر والوں سے کہا: جب میں مر جاؤں تو مجھے جلا دینا، پھر میری ہڈیوں کو پیس لینا، پھر ہوا والے دن میری راکھ سمندر میں اڑا دینا۔ اللہ کی قسم! اگر اللہ تعالیٰ نے مجھے پکڑ لیا تو مجھے ایسا عذاب دے گا جو اس نے اپنی مخلوق میں سے کسی کو نہ دیا ہوگا۔ اس کے گھر والوں نے ایسے ہی کیا۔ اللہ تعالیٰ نے ہر اس چیز کو، جس میں اس کے جسم کا کوئی حصہ تھا، حکم دیا کہ جو کچھ تجھ میں اس کا حصہ ہے، نکال دے۔ تو ناگہاں وہ اللہ تعالیٰ کے سامنے پو رے کا پورا کھڑا تھا۔ اللہ تعالیٰ نے فرمایا: جو کچھ تو نے کیا، کس بنا پر کیا؟ اس نے کہا: تیرے ڈر کی بنا پر۔ تو اللہ تعالیٰ نے اسے معاف کر دیا۔‘‘","f2":"(۱) ’’مجھے پکڑ لیا‘‘ اس نے سمجھا کہ اس طریقے سے جسم کو بظاہر ختم کرنے کے بعد اللہ تعالیٰ مجھے پکڑ نہ سکے گا، مگر یہ اس کی نادانی تھی کیونکہ اس طریقے سے بھی جسم کی شکل و صورت تو بدل سکتی ہے کہ وہ گوشت اور ہڈیوں سے راکھ بن گیا مگر ختم تو نہ ہوسکے گا، راکھ تو موجود ہی ہے۔ (۲) ’’معاف کر دیا‘‘ اس کی جہالت کو عذر قرار دیا، نیز اس کی نیت تو اللہ تعالیٰ کے عذاب سے بچنے ہی کی تھی اگرچہ طریقہ غلط تھا۔ معلوم ہوا عمل کے بجائے نیت کا اعتبار زیادہ ہوتا ہے۔ نیت غلط ہو اور عمل صحیح تو عمل غیر معتبر ہوتا ہے، جیسے دکھلاوے کی نماز، لیکن اگر نیت صحیح ہو، عمل غلط ہو جائے تو ثواب مل جاتا ہے، جیسے حق کی تلاش کرنے والے مجتہد کو حق نہ بھی مل سکے تب بھی وہ ثواب کا مستحق ہوتا ہے۔ (۳) حدیث سے معلوم ہوتا ہے کہ وہ کافر نہ تھا، قابل معافی تھا ورنہ کفر اور شرک تو کسی صورت بھی معاف نہیں ہوسکتا۔ گناہوں کا احساس اور خوف بھی ایمان کی علامت ہے۔ (۴) موت کے بعد اٹھنے کا اثبات ہوتا ہے۔ (۵) اللہ تعالیٰ کی عظیم قدرت معلوم ہوتی ہے۔ (۶) اللہ تعالیٰ سے ڈرنے کی فضیلت کا پتا چلتا ہے۔ (۷) اللہ کی رحمت بہت وسیع ہے۔"}],[2080,"حذیفہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم سے پہلے لوگوں میں کا ایک آدمی اپنے اعمال کے سلسلہ میں بدگمان تھا، چنانچہ جب موت(کا وقت) آپ پہنچا، تو اس نے اپنے گھر والوں سے کہا: جب میں مر جاؤں تو مجھے جلا دینا، پھر پیس ڈالنا، پھر مجھے دریا میں اڑا دینا، کیونکہ اگر اللہ تعالی مجھ پر قادر ہو گا تو وہ مجھے بخشے گا نہیں، آپ نے فرمایا: اللہ تعالی نے فرشتوں کو حکم دیا تو وہ اس کی روح کو پکڑ کر لائے، اللہ تعالی نے اس سے پوچھا: تجھے ایسا کرنے پر کس چیز نے ابھارا؟ اس نے کہا: اے میرے رب! میں نے صرف تیرے خوف کی وجہ سے ایسا کیا ہے، تو اللہ تعالی نے اسے بخش دیا\"۔","الألباني: صحيح",{"u2":"حضرت حذیفہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تم سے پہلے لوگوں میں ایک آدمی اپنے اعمال کے بارے میں برا گمان رکھتا تھا (کہ وہ قابل معافی نہیں)، لہٰذا جب اس کی وفات کا وقت قریب آیا تو اس نے اپنے گھر والوں سے کہا: جب میں مر جاؤں تو مجھے جلا دینا، پھر پیس کر آٹا کر دینا، پھر میری راکھ کو سمندر میں اڑا دینا۔ اگر اللہ تعالیٰ نے مجھ پر قابو پا لیا تو مجھے ہرگز معاف نہ کرے گا۔ اللہ تعالیٰ نے فرشتوں کو حکم دیا تو انھوں نے اس کی روح نکال لی، پھر اللہ تعالیٰ نے (اس کا ڈھانچا حاضر کیا اور) فرمایا: جو کچھ تو نے کیا، کیوں کیا؟ اس نے کہا: اے میرے رب! میں نے جو کچھ کیا، تیرے ڈر سے کیا۔ تو اللہ تعالیٰ نے اسے معاف کردیا۔‘‘","f2":"دفن کے بعد ’’روح‘‘ کا ’’جسم‘‘ سے اتنا تعلق ہو جاتا ہے کہ سوال و جواب ہوسکیں، مگر یہ دنیوی زندگی سے یکسر مختلف ہے، پھر روح کو (علیین) اور (سجین) میں بھیجا جاتا ہے۔ (علیین) اللہ تعالیٰ کے عرش کے پاس ایک مقام ہے اور (سجین) زمین کے نیچے جہنم کے قریب، لیکن اس کا تعلق اپنے جسم، خواہ وہ کسی حال میں ہو، سے ایک حد تک قائم رہتا ہے حتی کہ قیامت کے دن دوبارہ ارواح اجسام میں داخل ہو جائیں گی۔ یاد رہے روح اور جسم کا تعلق (برزخی زندگی میں) ہماری سمجھ میں آنے والی چیز نہیں۔ ہمیں اس کی ضرورت ہے نہ ہمارے دماغ ایسی چیزیں سمجھنے کے لیے بنائے گئے ہیں، جیسے بھینس ریاضی نہیں سمجھ سکتی، اگرچہ دو اور دو چار ہی ہے۔"}],[2081,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر خطبہ دیتے سنا آپ فرما رہے تھے: \"تم اللہ تعالی سے ننگے پاؤں، ننگے بدن(اور) غیر مختون ملو گے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما سے مروی ہے کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر پر خطبے کی حالت میں یہ فرماتے ہوئے سنا: ’’تم ننگے پاؤں، ننگے جسم اور بغیر ختنوں کے اللہ تعالیٰ سے ملو گے۔‘‘","f2":"یعنی جس حالت میں اس دنیا میں آئے تھے، اسی حالت میں لوٹا کر آخرت میں لے جایا جائے گا۔ عمل کے علاوہ وہ دنیا کی کوئی چیز ساتھ نہ ہوگی۔ اور عمل بھی روحانی اثرات کی صورت میں۔ اللہ تعالیٰ سے ملنے کا مطلب اس کے حضور حاضری ہے۔"}],[2082,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"لوگ قیامت کے دن ننگ دھڑنگ، غیر مختون اکٹھا کیے جائیں گے، اور مخلوقات میں سب سے پہلے ابراہیم علیہ السلام کو کپڑا پہنایا جائے گا، پھر آپ نے یہ آیت کریمہ تلاوت فرمائی: «كما بدأنا أول خلق نعيده» \"جیسے ہم نے پہلی دفعہ پیدا کیا تھا ویسے ہی دوبارہ پیدا کریں گے\" (الانبیاء: ۱۰۴)۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت کے دن لوگ ننگے جسم اور بغیر ختنوں کے اکٹھے کیے جائیں گے۔ اور انسانوں میں سے سب سے پہلے حضرت ابراہیم علیہ السلام کو کپڑے پہنائے جائیں گے، پھر آپ نے یہ آیت تلاوت فرمائی: (کما بدانا اول خلق نعبدہ) جیسے ہم نے اسے پہلی دفعہ پیدا کیا تھا، ویسے ہی پھر اسے پلٹائیں گے۔‘‘","f2":"(۱) حضرت ابراہیم علیہ السلام کو سب سے پہلے لباس مہیا ہونا ان کی بہت بڑی فضیلت ہے۔ اور وہ ان کا ایسا امتیاز ہے جس پر کوئی اور نبی حتی کہ خاتم النبیین صلی اللہ علیہ وسلم بھی شریک نہیں۔ یہ ان کی جزوی فضیلت ہے۔ اور یہ کوئی بعید نہیں کہ کسی نبی کو جزوی طور پر خاتم النبیین صلی اللہ علیہ وسلم پر فضیلت حاصل ہو، البتہ یہ بات قطعی ہے کہ مجموعی طور پر خاتم النبیین صلی اللہ علیہ وسلم ہی افضل ہیں۔ کہا جاتا ہے کہ حضرت ابراہیم علیہ السلام کو یہ فضیلت اس بنا پر حاصل ہوئی کہ انھیں آگ میں پھینکتے وقت اللہ کے راستے میں ننگا کیا گیا اور انھوں نے اسے اللہ تعالیٰ کی رضا کی خاطر برداشت کیا اور ثواب کے طالب ہوئے۔ یا، اس لیے کہ انھوں نے سب سے پہلے لباس پہنا جو یقیناً وہ دار لباس ہے۔ اس کا بدلہ ان کو اس فضیلت کی صورت میں دیا جائے گا۔ (۲) ’’ویسے ہی‘‘ یعنی تمام اعضاء اصلی حالت میں ہوں گے حتی کہ ختنہ بھی نہیں ہوگا (کیونکہ یہ بعد کی تبدیلی ہے) البتہ جسامت کے لحاظ سے جسم بڑا ہوگا۔"}],[2083,"ام المؤمنین عائشہ رضی اللہ عنہا سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگ قیامت کے دن ننگے پاؤں، ننگے بدن (اور) غیر مختون اٹھائے جائیں گے\"، تو اس پر عائشہ رضی اللہ عنہا نے پوچھا: لوگوں کی شرمگاہوں کا کیا حال ہو گا؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اس دن ہر ایک کی ایسی حالت ہو گی جو اسے (ان چیزوں سے) بے نیاز کر دے گی\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت کے دن سب لوگ ننگے پاؤں، ننگے جسم اور بغیر ختنوں کے (قبروں سے) اٹھائے جائیں گے۔‘‘ حضرت عائشہ رضی اللہ عنہا نے عرض کیا: شام گاہوں کا کیا بنے گا؟ آپ نے فرمایا: (لکل امریء منھم یومئذ شان بغنیہ) ’’ہر شخص کی اس دن ایسی حالت ہوگی جو اسے (ہر چیز سے) بے نیاز کر دے گی۔‘‘","f2":"یعنی اس قدر دہشت اور خوف ہوگا کہ کسی شخص کو ادھر ادھر دیکھنے کا ہوش ہی نہ ہوگا جیسے حادثات وغیرہ کے موقع پر ہوتا ہے۔ قیامت تو سب سے عظیم حادثہ ہے جس کا اس دنیا میں تصور بھی نہیں کیا جا سکتا۔"}],[2084,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم لوگ (قیامت کے دن) ننگے پاؤں (اور) ننگے بدن اکٹھا کیے جاؤ گے\"، میں نے پوچھا: مرد عورت سب ایک دوسرے کو دیکھیں گے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"معاملہ اتنا سنگین ہو گا کہ انہیں اس کی فکر نہیں ہو گی\"۔","الألباني: صحيح",{"u2":"حضرت عائشہ رضی اللہ عنہا سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بلاشبہ تمھیں ننگے پاؤں اور ننگے جسم (اللہ تعالیٰ کے سامنے) جمع کیا جائے گا۔‘‘ میں نے کہا: مرد اور عورتیں ایک دوسرے کو دیکھیں گے؟ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: ’’عائشہ! صورت حال اتنی ہولناک ہوگی کہ کسی کو اس کا خیال بھی نہ آئے گا۔‘‘"}],[2085,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"لوگ قیامت کے دن تین گروہ میں جمع کیے جائیں گے، کچھ جنت کی رغبت رکھنے والے اور جہنم سے ڈرنے والے ہوں گے ۱؎، اور کچھ لوگ ایک اونٹ پر دو سوار ہوں گے، ایک اونٹ پر تین سوار ہوں گے، ایک اونٹ پر چار سوار ہوں گے، ایک اونٹ پر دس سوار ہوں گے، اور بقیہ لوگوں کو آگ ۱؎ اکٹھا کرے گی، ان کے ساتھ وہ بھی قیلولہ کرے گی جہاں وہ قیلولہ کریں گے، رات گزارے گی جہاں وہ رات گزاریں گے، صبح کرے گی جہاں وہ صبح کریں گے، اور شام کرے گی جہاں وہ شام کریں گے\"۔\n§وضاحت\n۱؎: اس آگ کا ذکر بہت سی حدیثوں میں آیا ہوا ہے، یہ عدن سے نکلے گی اور لوگوں کو شام کی طرف ہانک کر لے جائے گی۔ ۲؎: یہ پہلا گروہ ہو گا جو موقع کو غنیمت سمجھتے ہوئے اسی وقت چل پڑے گا جب سواریوں اور زاد راہ کی بہتات ہو گی، چنانچہ وہ سوار ہو کر کھاتا اور پہنتا پہنچے گا، اور کچھ بیٹھے رہیں جب سواریاں کم ہو جائیں گی تب چلیں گے، ایک اونٹ پر کئی کئی لوگ سوار ہوں گے، اور تیسرا گروہ وہ ہو گا جو سواریوں سے محروم ہو گا، اور جسے آگ پا پیادہ ہانک کر لے جائے گی۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’قیامت کے دن لوگ تین حالتوں میں اکٹھے کیے جائیں گے۔ ایک گروہ رحمت کی امید رکھے ہوئے اپنے انجام سے ڈرتا ہوگا۔ (ااور دوسرا گروہ) دو آدمی ایک اونٹ پر ہوں گے یا تین آدمی ایک اونٹ پر یا چار ایک اونٹ پر یا دس آدمی ایک اونٹ پر اور باقی لوگوں (تیسرے گروہ) کو آگ اکٹھا کرے گی۔ جہاں وہ لوگ دوپہر کو آرام کے لیے ٹھہریں گے، آگ بھی وہاں ان کے ساتھ ٹھہرے گی۔ اور جہاں وہ رات گزاریں گے، آگ بھی ان کے ساتھ رات گزارے گی۔ جہاں وہ صبح کریں گے، وہاں آگ بھی ان کے ساتھ صبح کرے گی اور جہاں وہ شام کریں گے، وہیں آگ بھی ان کے ساتھ شام کرے گی۔‘‘","f2":"(۱)’’قیامت کے دن‘‘ ظاہر روایت سے معلوم ہوتا ہے کہ یہ حشر قیامت کے دن نہیں بلکہ قیامت سے پہلے ہوگا۔ بہت سے محدثین نے اس قسم کی روایات کو علامات قیامت میں ذکر کیا ہے کیونکہ اس میں اونٹوں، دوپہر، رات، صبح اور شام کا ذکر ہے۔ ظاہر ہے یہ چیزیں دنیا میں ہیں نہ کہ قیامت کے روز۔ اگرچہ بعض اہل علم نے اسے قیامت ہی کے دن پر محمول کیا ہے مگر اس میں بہت تکلف ہے۔ قیامت کے دن سے مراد قرب قیامت بھی ہوسکتا ہے اور یہی صحیح ہے۔ (۲) ’’تین حالتوں میں‘‘ یعنی کچھ خالص نیک، کچھ ملے جلے کاموں والے، کچھ خالص کافر۔ یا حشر کی تین حالتیں مراد ہیں: کچھ لوگ تو وقت ہی پر رغبت اور رہبت کے زیر اثر اپنے آپ محشر میں پہنچ جائیں گے۔ کچھ لوگ تنگ وقت میں بھاگیں گے جب سواریوں کی کمی ہوگی، پھر دو دو، تین تین، چار چار بلکہ اس سے بھی زیادہ ایک اونٹ پر سوار ہوکر بڑی تنگی کے ساتھ پہنچیں گے۔ کچھ لوگ آگ کے ساتھ زبردستی اکٹھے کیے جائیں گے۔ (۳) یہ آگ قیامت سے قبل عدن کے ساحل سے نکلے گی۔ (صحیح مسلم، باب في الآیات التي تکون قبل اساعۃ، حدیث: ۲۹۰۱) بعض لوگوں نے اس آگ سے حقیقی آگ کے بجائے فتنہ مراد لیا ہے اور مجازاً فتنے کو بھی آگ کہہ لیا جاتا ہے لیکن پہلی بات ہی درست ہے۔ واللہ أعلم۔"}],[2086,"ابوذر رضی اللہ عنہ کہتے ہیں کہ صادق و مصدوق صلی اللہ علیہ وسلم نے مجھ سے بیان کیا کہ لوگ (قیامت کے دن) تین گروہ میں جمع کیے جائیں گے: ایک گروپ سوار ہو گا، کھاتے (اور) پہنتے اٹھے گا، اور ایک گروہ کو فرشتے اوندھے منہ گھسیٹیں گے، اور انہیں آگ گھیر لے گی، اور ایک گروہ پیدل چلے گا (بلکہ) دوڑے گا۔ اللہ تعالی سواریوں پر آفت نازل کر دے گا، چنانچہ کوئی سواری باقی نہ رہے گی، یہاں تک کہ ایک شخص کے پاس باغ ہو گا جسے وہ ایک پالان والے اونٹ کے بدلے میں دیدے گا جس پر وہ قادر نہ ہو سکے گا۔","الألباني: ضعيف",{"u2":"حضرت ابوذر رضی اللہ عنہ سے روایت ہے، نبی صادق و مصدوق صلی اللہ علیہ وسلم نے مجھ سے بیان فرمایا: ’’لوگ تین گروہوں کی صورت میں اکٹھے کیے جائیں گے: کچھ تو سوار ہو کر کھاتے پیتے پہنتے (خوش خوش) آئیں گے۔ اور کچھ لوگوں کو فرشتے چہروں کے بل گھسیٹتے ہوئے لائیں گے اور آگ ان کو اکٹھا کرے گی۔ اور کچھ لوگ پیدل چلتے اور دوڑتے بھاگتے، گرتے پڑتے آئیں گے۔ اللہ تعالیٰ سواری کے جانوروں پر کوئی وبا ڈال دے گا تو وہ ختم ہو جائیں گے (بہت ہی کم رہ جائیں گے) حتی کہ باغ والا آدمی اپنا پورا باغ ایک اونٹنی کے بدلے دینے پر تیار ہوگا مگر اونٹنی نہ لے سکے گا۔‘‘","f2":"(۱) ’’صادق و مصدوق‘‘ صادق سے مراد خود سچے اور مصدوق سے مراد جن کو (اللہ تعالیٰ کی طرف سے) سچ بتایا گیا۔ گویا ان کی بات میں جھوٹ کا امکان تک نہیں کیونکہ نہ وہ خود جھوٹ بولتے ہیں، نہ وہ وحی جھوٹی ہے جو ان پر اتری، تو جھوٹ کدھر سے آئے گا۔ (۲) یہ حشر قیامت سے پہلے ہوگا جیسا کہ اوپر گزرا۔"}],[2087,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نصیحت کرنے کھڑے ہوئے تو فرمایا: \"لوگو! تم اللہ تعالی کے پاس ننگے جسم جمع کئے جاؤ گے،(ابوداؤد کی روایت میں ہے ننگے پاؤں اور غیر مختون جمع کئے جاؤ گے، اور وکیع اور وہب کی روایت میں ہے: ننگے جسم اور بلا ختنہ) جیسے ہم نے پہلی دفعہ پیدا کیا تھا ویسے ہی دوبارہ پیدا کریں گے، آپ صلی اللہ علیہ وسلم نے فرمایا: سب سے پہلے جسے قیامت کے دن کپڑا پہنایا جائے گا ابراہیم علیہ السلام ہوں گے، اور عنقریب میری امت کے کچھ لوگ لائے جائیں گے (ابوداؤد کی روایت میں «یجائ» ہے اور وہب اور وکیع کی روایت میں «سیؤتی» ہے) اور وہ پکڑ کر بائیں جانب لے جائے جائیں گے، میں عرض کروں گا: اے میرے رب! یہ میرے اصحاب (امتی) ہیں، کہا جائے گا: آپ نہیں جانتے جو آپ کے بعد انہوں نے شریعت میں نئی چیزیں ایجاد کر ڈالی ہیں، تو میں وہی کہوں گا جو نیکوکار بندے (عیسی علیہ السلام) نے کہا تھا کہ جب تک میں ان کے درمیان موجود تھا ان پر گواہ تھا جب تو نے مجھے وفات دے دی (تو تو ہی ان کا نگہبان تھا) اب اگر تو انہیں سزا دے تو یہ تیرے بندے ہیں، اور اگر انہیں بخش دے تو تو زبردست حکمت والا ہے، تو کہا جائے گا: یہ لوگ برابر پیٹھ پھیرنے والے رہے، (اور ابوداؤد کی روایت میں ہے: جب سے تم ان سے جدا ہوئے یہ اپنے ایڑیوں کے بل پلٹنے والے رہے)۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہما بیان کرتے ہیں کہ ایک دفعہ رسول اللہ ئ وعظ و نصیحت کے لیے کھڑے ہوئے تو فرمایا: ’’اے لوگو! یقینا تمھیں اللہ تعالیٰ کے سامنے ننگے جسم، ننگے پاؤں بغیر ختنے کے جمع کیا جائے گا۔ ارشاد باری تعالیٰ ہے: (کما بدانا اول خلق نعبدہ) ’’جس طرح ہم نے پہلے پیدا کیا تھا، اسی طرح ہم پلٹائیں گے۔‘‘ پھر آپ نے فرمایا: ’’قیامت کے دن سب سے پہلے حضرت ابراہیم علیہ السلام کو لباس پہنایا جائے گا۔ میری امت کے کچھ لوگ لائے جائیں گے، پھر انھیں بائیں طرف نکال لیا جائے گا۔ میں کہوں گا: اے میرے رب! یہ تو میری امت سے ہیں (یا میرے ساتھی ہیں؟) تو کہا جائے گا: آپ نہیں جانتے، انھوں نے آپ کی عدم موجودگی میں کیا کچھ کیا۔ تو میں (اسی طرح) کہوں گا: جس طرح اللہ کے نیک بندے (حضرت عیسیٰ مسیح علیہ السلام) کا قول ہے: (وکنت علیھم شھیدا ما دمت فیھم ……… وان تغفرلھم فانک انت العزیز الحکیم) ’’(اے اللہ!) میں تو ان پر گواہ تھا جب تک میں ان میں رہا، جب تو نے مجھے اپنے قبضے میں لے لیا، پھر تو تو ہی ان پر نگران تھا (لہٰذا تجھے ہی ان کے کاموں کا علم ہے) اور تو ہر چیز پر خوب گواہ ہے، اگر تو عذاب دے تو وہ تیرے بندے ہیں اور اگر بخشش دے تو بے شک تو غالب ہے خوب حکمت والا ہے۔‘‘ پھر کہا جائے گا: جب سے آپ ان کو چھوڑ کر (ہمارے پاس) آگئے یہ اسی وقت سے مرتد ہوگئے تھے اور مرتد ہی رہے۔‘‘","f2":"(۱) اس روایت کی کچھ باتوں کی تفصیل پیچھے گزر چکی ہے۔ (دیکھیے، حدیث: ۲۰۸۴) (۲) ’’بائیں طرف‘‘ یعنی انھیں جہنم کی طرف لے جایا جائے گا۔ جنہمیوں کو اصحاب اشمال کہا گیا ہے۔ (۳) ’’اسی وقت مرتد ہوگئے تھے‘‘ فتنہ تو رسول اللہ صلی اللہ علیہ وسلم کی وفات کے فوراً بعد شروع ہوگیا تھا اور اب تک جاری ہے۔ کوئی نہ کوئی بدنصیب مرتد ہوتا ہی رہتا ہے۔ أعاذنا اللہ منہ۔ ممکن ہے صرف وہ لوگ مراد ہوں جو آپ صلی اللہ علیہ وسلم کی وفات کے فوراً بعد مرتد ہوگئے تھے اور جن سے حضرت ابوبکر صدیق رضی اللہ عنہ برسر پیکار ہوئے۔ اور ممکن ہے اسلام سے ارتداد کے بجائے سنن سے ارتداد مقصود ہو، یعنی رسول اللہ صلی اللہ علیہ وسلم کے بعد بدعتی ہوگئے تھے اور اصل اسلامی تعلیمات سے انحراف کرکے اسی بدعتی انحراف پر قائم رہے۔ أعاذنا اللہ من البدع و الخرافات۔"}],[2088,"قرہ رضی اللہ عنہ کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم جب بیٹھتے تو آپ کے صحابہ کی ایک جماعت بھی آپ کے پاس بیٹھتی، ان میں ایک ایسے آدمی بھی ہوتے جن کا ایک چھوٹا بچہ ان کی پیٹھ کے پیچھے سے آتا، تو وہ اسے اپنے سامنے (گود میں) بٹھا لیتے (چنانچہ کچھ دنوں بعد) وہ بچہ مر گیا، تو اس آدمی نے اپنے بچے کی یاد میں محفل میں آنا بند کر دیا، اور رنجیدہ رہنے لگا، تو (جب) نبی اکرم صلی اللہ علیہ وسلم نے اسے نہیں پایا تو پوچھا: \"کیا بات ہے؟ میں فلاں کو نہیں دیکھ رہا ہوں؟\" لوگوں نے کہا: اللہ کے رسول! اس کا ننھا بچہ جسے آپ نے دیکھا تھا مر گیا، چنانچہ نبی اکرم صلی اللہ علیہ وسلم نے اس سے ملاقات کی، (اور) اس کے بچے کے بارے میں پوچھا، تو اس نے بتایا کہ وہ مر گیا، تو آپ نے اس کی (موت کی خبر) پر اس کی تعزیت کی، پھر فرمایا: \"اے فلاں! تجھ کو کون سی بات زیادہ پسند ہے؟ یہ کہ تم اس سے عمر بھر فائدہ اٹھاتے یا یہ کہ (جب) تم قیامت کے دن جنت کے کسی دروازے پر جاؤ تو اسے اپنے سے پہلے پہنچا ہوا پائے، وہ تمہارے لیے اسے کھول رہا ہو؟\" تو اس نے کہا: اللہ کے نبی! مجھے یہ بات زیادہ پسند ہے کہ وہ جنت کے دروازے پر مجھ سے پہلے پہنچے، اور میرے لیے دروازہ کھول رہا ہو، آپ نے فرمایا: \"تمہارے لیے ایسا (ہی) ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت قرہ مزنی رضی اللہ عنہ بیان کرتے ہیں کہ جب نبی صلی اللہ علیہ وسلم بیٹھتے تو آپ کے ساتھ آ پ کے صحابہ میں سے کچھ نہ کچھ لوگ بیٹھا کرتے تھے۔ ان میں ایک شخص تھا جس کا ایک معصوم بیٹا تھا۔ وہ پیچھے سے آتا تو باپ اسے اپنے آگے بٹھا لیتا تھا۔ اتفاقاً وہ بچہ فوت ہوگیا تو وہ شخص اپنے بیٹے کی یاد میں (کئی روز تک) آپ کی مجلس میں حاضر نہ ہوا کیونکہ اسے اس (کی وفات) کا شدید غم تھا۔ جب نبی صلی اللہ علیہ وسلم نے اسے (کئی دن) نہ دیکھا تو فرمایا: ’’کیا وجہ ہے کہ فلاں شخص نظر نہیں آتا؟‘‘ لوگوں نے کہا: اے اللہ کے رسول! اس کا وہ چھوٹا سا بچہ جو پ نے بھی دیکھا تھا، فوت ہوگیا ہے، پھر نبی صلی اللہ علیہ وسلم اس شخص سے ملے اور اس کے بیٹے کے بارے میں پوچھا۔ اس نے بتایا کہ وہ تو فوت ہوچکا ہے۔ آپ نے اسے تسلی دی۔ آپ نے فرمایا: ’’اے شخص! تجھے کون سی چیز زیادہ پسند ہے کہ تو اپنی ساری عمر اس سے فائدہ اٹھاتا (آنکھیں ٹھنڈی کرتا) یا یہ کہ تو جنت کے جس دروازے کے پاس بھی جائے، اسے وہاں پائے کہ وہ تجھ سے پہلے پہنچ کر اسے تیر لیے کھول دے؟‘‘ اس نے کہا: اے اللہ کے نبی! مجھے یہ بات زیادہ پسند ہے کہ وہ مجھ سے پہلے جاکر میرے لیے جنت کا دروازہ کھولے۔ آپ نے فرمایا: ’’بس! یہ چیز تجھے مل جائے گی۔‘‘","f2":"(۱) لیکن یہ تب ہے جب کوئی شخص اپنے نابالغ بچے کی موت پر صبر کرے اور ثواب کا طالب ہو۔ دراصل یہ صبر کا ثواب ہے جو اسے جنت میں داخل کرنے کا سبب بنے گا۔ اس کا ظہور اس طرح ہوگا کہ وہ بچہ اس کے لیے جنت کا دروازہ کھول کر اس کا استقبال کرے گا۔ بچہ خود تو معصوم ہونے کی وجہ سے قطعاً جنتی ہے۔ (۲) چھوٹے بچوں کو بھی مجالس علم میں لے جانا چاہیے۔"}],[2089,"ابوہریرہ رضی اللہ عنہ کہتے ہیں موت کا فرشتہ موسی علیہ السلام کے پاس بھیجا گیا، جب وہ ان کے پاس آیا تو انہوں نے اسے ایک طمانچہ رسید کیا، تو اس کی ایک آنکھ پھوٹ کر بہہ گئی، چنانچہ اس نے اپنے رب کے پاس واپس جا کر شکایت کی کہ تو نے مجھے ایسے بندے کے پاس بھیج دیا جو مرنا نہیں چاہتا، اللہ تعالی نے اس کی آنکھ اچھی کر دی، اور کہا: اس کے پاس دوبارہ جاؤ، اور اس سے کہہ: تم اپنا ہاتھ بیل کی پیٹھ پر رکھو اس کے ہاتھ کے نیچے جتنے بال آئیں گے ہر بال کے عوض انہیں ایک سال کی مزید عمر مل جائے گی، تو انہوں نے عرض کیا: اے میرے رب! پھر کیا ہو گا؟ اللہ تعالی نے فرمایا: پھر مرنا ہو گا، (موسی علیہ السلام) نے کہا: تب تو ابھی (مرنا بہتر ہے)، تو انہوں نے اللہ تعالی سے درخواست کی کہ وہ انہیں ارض مقدس سے پتھر پھینکنے کی مسافت کے برابر قریب کر دے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر میں اس جگہ ہوتا تو تمہیں راستے کی طرف سرخ ٹیلے کے نیچے ان کی قبر دکھلاتا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ موت کے فرشتے کو حضرت موسیٰ علیہ السلام کی طرف (انسانی صورت میں) بھیجا گیا۔ جب وہ فرشتہ آیا تو موسیٰ علیہ السلام نے اسے تھپڑ مار کر اس کی آنکھ پھوڑ دی۔ وہ اپنے رب تعالیٰ کے پاس واپس گیا اور عرض کیا: اے اللہ! تو نے مجھے ایسے بندے کی طرف بھیجا جو مرنا نہیں چاہتا۔ اللہ تعالیٰ نے اس کی آنکھ درست فرما دی اور فرمایا: اس کے پاس دوبارہ جا اور اسے کہہ کہ اپنا ہاتھ کسی بیل کی پشت پر رکھ۔ اسے ہر بال کے عوض، جو اس کے ہاتھ کے نیچے آئے گا، ایک سال زندگی ملے گی۔ (اس ساری کارروائی کے بعد) موسیٰ علیہ السلام نے کہا: اے میرے رب! پھر کیا ہو گا؟ فرمایا: (پھر) موت! انھوں نے کہا: پھر ابھی ٹھیک ہے لیکن انھوں نے اللہ تعالیٰ سے یہ گزارش کی کہ مجھے ایک پتھر پھینکنے کے فاصلے تک مقدس سرزمین کے قریب کر دیا جائے۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر میں وہاں ہوتا تو تمھیں راستے کی ایک جانب سرخ رنگ کے ٹیلے کے نیچے ان کی قبر دکھاتا۔‘‘","f2":"(۱) بعض بدعقیدہ حضرات نے اس واقعے کا انکار کیا ہے کہ یہ کیسے ممکن ہے کہ ایک نبی ملک الموت کو تھپڑ مار دے اور مرنے سے انکار کرے، حالانکہ یہ ان کی جہالت ہے۔ اس واقعے میں کوئی استبعاد نہیں۔ نقلاً یہ واقعہ بالکل صحیح ہے، عقلاً بھی کوئی اشکال نہیں۔ بات صرف اتنی ہے کہ ملک الموت انجانی انسانی صورت میں حضرت موسیٰ علیہ السلام کے پاس پہنچے کہ میں تیری جان نکالنے آیاہوں۔ ظاہر ہے اس طرح تو کوئی بھی شخص کسی بھی انسان کو جان نکالنے نہیں دیتا بلکہ اپنا دفاع کرتا ہے، لہٰذا انھوں نے انسان سمجھ کر ملک الموت کو تھپڑ مارا۔ تھپڑ چہرے پر لگا اور آنکھ کو نقصان پہنچا۔ فرشتہ جب انسانی صورت میں آئے گا تو اس پر انسانی احکام ہی لاگو ہوں گے، لہٰذا آنکھ کے نقصان پر کوئی تعجب نہیں۔ فرشتے نے اللہ تعالیٰ سے شکایت کی تو اللہ تعالیٰ نے آنکھ درست کر کے بھیجا تو موسیٰ علیہ السلام سمجھ گئے کہ یہ انسان نہیں فرشتہ ہے (تبھی تو آنکھ فوراً ٹھیک ہوگئی۔) لہٰذا فوراً موت کے لیے تیار ہوگئے اگرچہ انھیں لمبی زندگی کی پیش کش کی گئی تھی۔ بتائیے اس میں کون سا عقلی اشکال ہے جس کی بنا پر صحیح حدیث کا انکار کیا جائے؟ [وکم من عائب قولا صحیحا و افتہ من الفھم السقیم] ’’کتنے ہی نقص نکالنے والے راست بول کو معیوب سمجھتے ہیں ان (عیب جوؤں) پر یہ سختی کمزور فہم کی وجہ سے ہوئی۔‘‘ (۲) ’’آنکھ پھوڑ دی‘‘ یہ دلیل ہے کہ فرشتہ انسانی صورت میں آیا تھا، ورنہ فرشتے کی تو آنکھ نظر ہی نہیں آتی، پھوٹے گی کیسے؟ (۳) ’’مرنا نہیں چاہتا‘‘ یہ ملک الموت کا ظاہری حالات سے اندازہ ہے، ورنہ یہ وجہ نہ تھی بلکہ تھپڑ مارنے کی وجہ یہ تھی کہ فرشتہ اس حالت میں نہیں آیا تھا جس حالت میں روح قبض کرتا ہے، اس لیے انھوں نے اسے انسان سمجھا اور اپنا دفاع فرمایا، اور یہ ان کا حق تھا۔ (۴) ’’بیل کی پشت پر ہاتھ رکھے‘‘ اس بات کا مقصد دراصل فرشتے کو یہ سمجھانا تھا کہ موسیٰ کا تھپڑ مارنا موت سے انکار کی بنا پر نہیں اور واقعتاً ایسا ہی ہوا۔ جب موسیٰ علیہ السلام کو پتا چل گیا کہ یہ فرشتہ ہے تو زندگی کی پیش کش قبول نہیں کی۔ درحقیقت یہ پیش کش نہیں تھی بلکہ موسیٰ علیہ السلام کی براءت مقصود تھی۔ ورنہ موت کا دن تو مقرر ہے۔ آگے پیچھے نہیں ہوسکتا، پیش کش کیسی؟ (۵) ’’قریب کر دیا جائے‘‘ معلوم ہوا مقدس مقام میں دفن ہونے کی خواہش درست ہے کیونکہ پڑوس کا بھی اثر ہوتا ہے۔ حضرات ابوبکر صدیق و عمر فاروق و عائشہ رضی اللہ عنہم نے رسول اللہ صلی اللہ علیہ وسلم کے جوار میں دفن ہونا پسند فرمایا، خواہش کی، اجازت حاصل کی اور پہلے وہ بزرگ تو دفن بھی ہوئے۔ (۶) ’’رسول اللہ صلی اللہ علیہ وسلم نے فرمایا‘‘ یہ پوری روایت ہی آپ کا فرمان ہے۔ اگرچہ اس سند میں آپ کا ذکر صرف آخر میں ہے۔ (۷) اس روایت میں تسلی اس طرح ہے کہ جب آخر کار مرنا ہی مقدر ہے تو کسی کی موت پر ضرورت سے زائد گھبراہٹ کیوں؟"}],[2090,"طلحہ بن عبیداللہ رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس پراگندہ بال آیا، (اور) اس نے عرض کیا: اللہ کے رسول! مجھے بتائیے اللہ تعالی نے مجھ پر کتنی نمازیں فرض کی ہیں؟ آپ نے فرمایا: \"پانچ (وقت کی) نمازیں، اِلاَّ یہ کہ تم کچھ نفل پڑھنا چاہو\"، پھر اس نے کہا: مجھے بتلائیے کہ اللہ تعالی نے مجھ پر کتنے روزے فرض کیے ہیں؟ آپ نے فرمایا: \"ماہ رمضان کے روزے، اِلاَّ یہ کہ تم کچھ نفلی (روزے) رکھنا چاہو\"، (پھر) اس نے پوچھا: مجھے بتلائیے اللہ تعالی نے مجھ پر کتنی زکاۃ فرض کی ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اسلام کے احکام بتائے، تو اس نے کہا: قسم ہے اس ذات کی جس نے آپ کی تکریم کی ہے، میں کوئی نفل نہیں کروں اور نہ اللہ تعالی نے مجھ پر جو فرض کیا ہے اس میں کوئی کمی کروں گا، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس نے سچ کہا تو یہ کامیاب ہو گیا\"، یا کہا: \"اگر اس نے سچ کہا تو جنت میں داخل ہو گیا\"۔","الألباني: صحيح",{"u2":"حضرت طلحہ بن عبیداللہ رضی اللہ عنہ سے روایت ہے کہ ایک بکھرے بالوں والا اعرابی رسول اللہ صلی اللہ علیہ وسلم کے پاس ایا اور کہنے لگا: اے اللہ کے رسول! مجھے بتائیے، اللہ تعالیٰ نے مجھ پر کتنی نمازیں فرض کی ہیں؟ آپ نے فرمایا: ’’پانچ نمازیں الا یہ کہ تو خوشی سے مزید پڑھے۔‘‘ اس نے کہا: مجھے بتائیے، اللہ تعالیٰ نے مجھ پر روزے کتنے فرض کیے ہیں؟ آپ نے فرمایا: ’’ماہ رمضان کے روزے، مگر یہ کہ تو خوشی سے زائد رکھے۔‘‘ اس نے کہا: مجھے بتائیے، اللہ تعالیٰ نے مجھ پر کتنی زکاۃ فرض کی ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے اسے اسلام (اور زکاۃ) کے (تفصیلی) احکام بتائے۔ وہ کہنے لگا: قسم اس ذات کی جس نے آپ کو عزت بخشی! میں اللہ تعالیٰ کے مقرر کردہ فرائض سے نہ زائد کچھ کروں گا اور نہ ان میں کمی کروں گا۔ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اگر یہ اپنی بات پر پکا رہا تو کامیاب ہو جائے گا یا جنت میں داخل ہو جائے گا۔‘‘","f2":"۱) روزے شعبان ۲ ہجری کو فرض ہوئے۔ روزؤں کی فرضیت قرآن وسنت اور اجماع امت سے ثابت ہے۔ (۲) ’’نہ کمی کروں گا‘‘ یعنی ظاہر گنتی وغیرہ کے لحاظ سے، ورنہ ادائیگی میں نقص نہ ہونے کا دعویٰ نہیں کیا جا سکتا۔ (۳) ’’اگر یہ اپنی بات پر پکا رہا‘‘ یعنی وہ فرائض میں کمی نہ کرے گا۔ (نہ یہ کہ ان سے زیادتی نہ کرے گا کیونکہ نوافل کی اداورنہ ادائیگی میں نقص نہ ہونے کا دعویٰ نہیں کیا جا سکتا۔ (۳) ’’اگر یہ اپنی بات پر پکا رہا‘‘ یعنی وہ فرائض میں کمی نہ کرے گا۔ (نہ یہ کہ ان سے زیادتی نہ کرے گا کیونکہ نوافل کی ادائیگی تو مطلوب ہے اور بیان میں مذکور بھی ہے۔ اور یہی مشکل چیز ہے۔) یا مطلب یہ ہے کہ وہ فرائض میں اپنی طرف سے اضافہ نہ کرے گا۔"}],[2091,"انس رضی اللہ عنہ کہتے ہیں: ہمیں قرآن کریم میں نبی اکرم صلی اللہ علیہ وسلم سے لایعنی بات پوچھنے سے منع کیا گیا تھا، تو ہمیں یہ بات اچھی لگتی کہ دیہاتیوں میں سے کوئی عقلمند شخص آئے، اور آپ سے نئی نئی باتیں پوچھے، چنانچہ ایک دیہاتی آیا، اور کہنے لگا: اے محمد! ہمارے پاس آپ کا قاصد آیا، اور اس نے ہمیں بتایا کہ آپ کہتے ہیں کہ اللہ تعالی نے آپ کو بھیجا ہے؟ آپ نے فرمایا: \"اس نے سچ کہا\"، اس نے پوچھا: آسمان کو کس نے پیدا کیا؟ آپ نے کہا: \"اللہ تعالی نے\" (پھر) اس نے پوچھا: زمین کو کس نے پیدا کیا؟ آپ نے کہا: \"اللہ نے\" (پھر) اس نے پوچھا: اس میں پہاڑ کو کس نے نصب کیے ہیں؟ آپ نے کہا: \"اللہ تعالی نے\" (پھر) اس نے پوچھا: اس میں نفع بخش (چیزیں) کس نے بنائیں؟ آپ نے کہا: \"اللہ تعالی نے\" (پھر) اس نے کہا: قسم اس ذات کی جس نے آسمان اور زمین کو پیدا کیا، اور اس میں پہاڑ نصب کیے، اور اس میں نفع بخش (چیزیں) بنائیں کیا آپ کو اللہ تعالی نے بھیجا ہے؟ آپ نے کہا: \"ہاں\"، پھر اس نے کہا: اور آپ کے قاصد نے کہا ہے کہ ہمارے اوپر ہر روز دن اور رات میں پانچ وقت کی نماز فرض ہے؟ آپ نے فرمایا: \"اس نے سچ کہا\"، تو اس نے کہا: قسم ہے اس ذات کی جس نے آپ کو بھیجا! کیا اللہ تعالی نے آپ کو ان (نمازوں) کا حکم دیا ہے؟ آپ نے کہا: ہاں، (پھر) اس نے کہا: آپ کے قاصد نے کہا ہے کہ ہم پر اپنے مالوں کی زکاۃ فرض ہے؟ آپ نے فرمایا: اس نے سچ کہا، (پھر) اس نے کہا: قسم اس ذات کی جس نے آپ کو بھیجا! کیا آپ کو اللہ تعالی نے اس کا حکم دیا ہے؟ آپ نے کہا: \"ہاں\"، (پھر) اس نے کہا: آپ کے قاصد نے کہا ہے: ہم پر ہر سال ماہ رمضان کے روزے فرض ہیں، آپ نے کہا: \"اس نے سچ کہا\" (پھر) اس نے کہا: کیا اللہ تعالی نے آپ کو ان (دنوں کے روزوں) کا حکم دیا ہے؟ آپ نے کہا: \"ہاں\"، (پھر) اس نے کہا: آپ کے قاصد نے کہا ہے: ہم میں سے جو کعبہ تک جانے کی طاقت رکھتے ہوں، ان پر حج فرض ہے؟ آپ نے فرمایا: \"اس نے سچ کہا\"، اس نے کہا: قسم اس ذات کی جس نے آپ کو بھیجا! کیا اللہ تعالی نے آپ کو اس کا حکم دیا ہے؟ آپ نے فرمایا: \"ہاں\"، تو اس نے کہا: قسم اس ذات کی جس نے آپ کو حق کے ساتھ بھیجا فرمایا: میں ہرگز نہ اس میں کچھ بڑھاؤں گا اور نہ گھٹاؤں گا، جب وہ لوٹا تو نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"اگر اس نے سچ کہا ہے تو یہ ضرور جنت میں داخل ہو گا\"۔","الألباني: صحيح",{"u2":"حضرت انس رضی اللہ عنہ بیان کرتے ہیں کہ ہمیں قرآن مجید میں اس بات سے روک دیا گیا تھا کہ ہم رسول اللہ صلی اللہ علیہ وسلم سے زیادہ سوالات کریں تو ہماری یہ خواہش ہوتی تھی کہ بدوی لوگوں میں سے کوئی سمجھ دار شخص آئے اور آپ سے سوالات کرے۔ اتفاقاً (ایک دن) ایک بدوی آیا اور کہنے لگا: اے محمد! آپ کا قاصد ہمارے پاس آیا اور اس نے بتایا کہ آپ کہتے ہیں کہ اللہ تعالیٰ نے آپ کو رسول بنایا ہے۔ آپ نے فرمایا: ’’اس نے سچ کہا۔‘‘ اس (بدوی) نے کہا: تو آسمانوں کو کس نے پیدا کیا؟ فرمایا: ’’اللہ تعالیٰ نے۔‘‘ اس نے کہا: زمین کو کس نے بنایا؟ فرمایا: ’’اللہ تعالیٰ نے۔‘‘ اس نے کہا: زمین میں پہاڑ کس نے نصب کیے؟ آپ نے فرمایا: ’’اللہ تعالیٰ نے۔‘‘ اس نے کہا: زمین میں منافع کس نے نصب کیے؟ آپ نے فرمایا: ’’اللہ تعالیٰ نے۔‘‘ اس نے کہا: زمین میں منافع کس نے رکھے؟ آپ نے فرمایا: ’’اللہ تعالیٰ نے۔‘‘ اس نے کہا: قسم ہے اس ذات کی جس نے آسمان وزمین پیدا کیے اور زمین میں پہاڑ نصب کیے اور دوسرے منافع رکھے! کیا اللہ تعالیٰ نے آپ کو (رسول بنا کر) بھیجا ہے؟ آپ نے فرمایا: ’’ہاں۔‘‘ اس نے کہا: اور آپ کے قاصد نے کہا ہے کہ ہم پر ایک دن رات میں پانچ نمازیں فرض ہیں؟ آپ نے فرمایا: ’’اس نے سچ کہا۔‘‘ اس نے کہا: قسم اس ذات کی جس نے آپ کو رسول بنایا! کیا اللہ تعالیٰ نے آپ کو ان کا حکم دیا ہے؟ فرمایا: ’’ہاں۔‘‘ اس نے کہا: ’’اور آپ کے قاصد نے کہا ہے کہ ہم پر ہمارے مالوں کی زکاۃ بھی واجب ہے۔ فرمایا: ’’اس نے سچ کہا۔‘‘ اس نے کہا: قسم اس ذات کی جس نے آپ کو رسول بنایا! کیا اللہ تعالیٰ نے آپ کو اس کا حکم دیا ہے؟ آپ نے فرمایا: ’’ہاں۔‘‘ اس نے کہا: اور آپ کے قاصد نے کہا ہے کہ ہم پر ہر سال ماہ رماضن کے روزے فرض ہیں؟ فرمایا: ’’اس نے سچ کہا۔‘‘ اس نے کہا: قسم اس ذات کی جس نے آپ کو رسول بنایا! کیا اللہ تعالیٰ نے آپ کو یہ حکم دیا ہے؟ آپ نے فرمایا: ’’ہاں۔‘‘ اس نے کہا: اور آپ کے قاصد نے کہا ہے کہ جس شخص کو بیت اللہ تک پہنچنے کی طاقت ہو اس پر حج بھی فرض ہے۔ آپ نے فرمایا: ’’اس نے سچ کہا۔‘‘ اس نے کہا: قسم اس ذات کی جس نے آپ کو رسول بنایا! کیا اللہ تعالیٰ نے آپ کو اس کا حکم دیا ہے؟ آپ نے فرمایا: ’’ہاں۔‘‘ اس نے کہا: تو پھر اس ذات کی قسم جس نے آپ کو برحق نبی بنایا! میں نہ ان پر اضافہ کروں گا اور نہ ان میں کمی کروں گا۔ جب وہ واپس مڑا تو آپ نے فرمایا: ’’اللہ کی قسم! اگر یہ اپنی بات پر پکا رہا تو لازماً جنت میں داخل ہوگا۔‘"}],[2092,"انس بن مالک رضی اللہ عنہ کہتے ہیں: ہم مسجد میں بیٹھے تھے کہ اسی دوران ایک شخص اونٹ پر آیا، اسے مسجد میں بٹھایا پھر اسے باندھا، (اور) لوگوں سے پوچھا: تم میں محمد کون ہیں؟ اور رسول اللہ صلی اللہ علیہ وسلم ان کے درمیان ٹیک لگائے بیٹھے تھے۔ تو ہم نے اس سے کہا: یہ گورے چٹے آدمی ہیں، جو ٹیک لگائے بیٹھے ہیں، آپ کو پکار کر اس شخص نے کہا: اے عبدالمطلب کے بیٹے! تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"میں نے تمہاری بات سن لی\" (کہو کیا کہنا چاہتے ہو) اس نے کہا: محمد! میں آپ سے کچھ پوچھنے والا ہوں، (اور ذرا) سختی سے پوچھوں گا تو آپ دل میں کچھ محسوس نہ کریں، آپ نے فرمایا: \"پوچھو جو چاہتے ہو\"، تو اس نے کہا: میں آپ کو آپ کے، اور آپ سے پہلے (جو گزر چکے ہیں) ان کے رب کی قسم دلاتا ہوں! کیا اللہ تعالی نے آپ کو تمام لوگوں کی طرف (رسول بنا کر) بھیجا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے کہا: \"اے اللہ! (میری بات پر گواہ رہنا) ہاں\"، (پھر) اس نے کہا: میں اللہ کی قسم دلاتا ہوں! کیا اللہ تعالی نے آپ کو دن اور رات میں پانچ (وقت کی) نماز پڑھنے کا حکم دیا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! (گواہ رہنا) ہاں\"، (پھر) اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں! کیا اللہ تعالی نے آپ کو سال کے اس ماہ میں روزے رکھنے کا حکم دیا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! (گواہ رہنا) ہاں،\" (پھر)اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں! اللہ تعالی نے آپ کو مالداروں سے زکاۃ لے کر غریبوں میں تقسیم کرنے کا حکم دیا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے کہا: \"اے اللہ! (گواہ رہنا) ہاں\"، تب (اس) شخص نے کہا: میں آپ کی لائی ہوئی (شریعت) پر ایمان لایا، میں اپنی قوم کا جو میرے پیچھے ہیں قاصد ہوں، اور میں قبیلہ بنی سعد بن بکر کا فرد ضمام بن ثعلبہ ہوں۔ یعقوب بن ابراہیم نے حماد بن عیسی کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یہ مخالفت اس طرح ہے کہ انہوں نے لیث اور سعید کے درمیان ابن عجلان کا واسطہ بڑھایا ہے، ان کی روایت آگے آ رہی ہے۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ ایک دفعہ ہم مسجد میں بیٹھے تھے کہ ایک آدمی اونٹ پر سوار ہو کر آیا۔ اس نے اونٹ کو مسجد میں بٹھا دیا، پھر اس کا گھٹنا باندھ دیا اور کہنے لگا: تم میں سے محمد(صلی اللہ علیہ وسلم) کون ہیں؟ رسول اللہ صلی اللہ علیہ وسلم لوگوں کے درمیان بیٹھے تھے۔ ہم نے کہا: یہ سفید چہرے والے شخص جو ٹیک لگا کر بیٹھے ہیں۔ تو وہ شخص (آپ سے مخاطب ہو کر) کہنے لگا: اے ابن عبدالمطلب! رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بات کر میں تجھے جواب دوں گا۔‘‘ (یعنی میں تیری باتیں سن رہا ہوں۔) اس آدمی نے کہا: اے محمد! میں آپ سے کچھ باتیں پوچھنے لگا ہوں اور میں سخت الفاظ میں پوچھوں گا تو آپ ناراضی محسوس نہ فرمائیے گا۔ آپ نے فرمایا: ’’جو دل چاہے پوچھ۔‘‘ اس نے کہا: میں آپ سے آپ کے اور پہلے تمام لوگوں کے رب کا واسطہ دے کر پوچھتا ہوں کہ کیا اللہ تعالیٰ نے آپ کو تمام لوگوں کی طرف رسول بنایا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ سے اللہ تعالیٰ کا واسطہ دے کر پوچھتا ہوں: کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ ہم دن، رات میں پانچ نمازیں پڑھا کریں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: تو میں آپ کو اللہ تعالیٰ کا واسطہ دے کر پوچھتا ہوں: کیا اللہ تعالیٰ نے آپ کو سال میں سے اس مہینے (رمضان المبارک) کے روزے رکھنے کا حکم دیا ہے؟ فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ سے اللہ تعالیٰ کا واسطہ دے کر سوال کرتا ہوں: کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ آپ ہمارے مال دار لوگوں سے زکاۃ لے کر ہمارے غریب لوگوں میں بانٹ دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس آدمی نے کاہ: میں ان تمام چیزوں پر ایمان لاتا ہوں جو آپ لائے ہیں اور میں اپنی قوم کی طرف سے قاصد ونمائندہ ہوں۔ میرا نام ضمام بن ثعلبہ ہے اور میں قبیلہ سعد بن بکر سے تعلق رکھتا ہوں۔‘‘\nیعقوب بن ابراہیم نے عیسیٰ بن حماد کی مخالفت کی ہے۔","f2":"(۱) یہ دونوں حضرت لیث کے شاگرد ہیں۔ یعقوب بن ابراہیم نے حضرت لیث اور سعید کے درمیان ابن عجلان وغیرہ کا واسطہ ذکر کیا ہے جبکہ عیسیٰ بن حماد نے کوئی ایسا واسطہ ذکر نہیں کیا۔ اور یہی روایت درست ہے۔ واقعے سے معلوم ہوتا ہے کہ حضرت ضمام بن ثعلبہ رضی اللہ عنہ بہت سمجھ دار شخص تھے کہ آپ کے پاس حاضری اور اظہار ایمان میں جلد بازی نہیں کی۔ تسلی سے اونٹ کو بٹھایا، گھٹنا باندھا، پوری تحقیق و تفتیش کی اور اس میں کسی قسم کی رعایت نہیں کی۔ جب یقین ہوگیا تو پھر اپنے ایمان کا اعلان کیا اور پھر اپنا تعارف کروایا۔ یہ اپنی قوم کے سردار تھے… (۲) ’’ابن عبدالمطلب‘‘ عرب میں اسی نسبت سے مشہور تھے کیونکہ آپ کے دادا عبدالمطلب مشہور شخصیت تھے جبکہ آپ کے والد شہرت یاب ہونے سے پہلے اور آپ کی پیدائش سے بھی پہلے فوت ہو چکے تھے۔ اس وقت وہ بالکل نوجوان تھے، لہٰذا وہ زیادہ معروف نہ تھے، نیز آپ کی ابتدائی پرورش بھی آپ کے دادا ہی نے کی تھی۔ خود رسول اللہ صلی اللہ علیہ وسلم نے بھی غزوئہ حنین میں یوں ہی کہا تھا: [اَنَا ابْنُ عَبْدِالْمُطَّلِبْ] (صحیح البخاری، الجہاد والسیر، حدیث: ۲۸۴۲، وصحیح مسلم، الجہاد، حدیث ۱۷۷۶) (۳) حدیث سے معلوم ہوتا ہے کہ اس قوم کو دین اسلام کا پیغام پہنچ چکا تھا۔ حضرت ضمام بن ثعلبہ رضی اللہ عنہ مزید تصدیق اور اعلان کے لیے حاضر ہوئے تھے۔ (۴) مندرجہ بالا تینوں روایات کے الفاظ سے معلوم ہوتا ہے کہ یہ تینوں الگ الگ واقعات ہیں مگر حقیقت یہ ہے کہ دوسرا اور تیسرا ایک ہی واقعہ ہے اور ان میں جو اختلاف ہے یہ رواۃ کے بیان کا اختلاف ہے۔"}],[2093,"انس بن مالک رضی اللہ عنہ کہتے ہیں: ہم رسول اللہ صلی اللہ علیہ وسلم کے پاس مسجد میں بیٹھے تھے کہ اسی دوران ایک شخص اونٹ پر سوار آیا، اس نے اسے مسجد میں بٹھا کر باندھا (اور) لوگوں سے پوچھا: تم میں محمد کون ہیں؟ اور آپ صلی اللہ علیہ وسلم لوگوں کے درمیان ٹیک لگائے ہوئے تھے۔ ہم نے اس سے کہا: یہ گورے چٹے آدمی ہیں جو ٹیک لگائے ہوئے ہیں، تو (اس) شخص نے (پکار کر) آپ سے کہا: اے عبدالمطلب کے بیٹے! تو رسول اللہ صلی اللہ علیہ وسلم نے اس سے فرمایا: \"میں نے تمہاری بات سن لی\"، (کہو کیا کہنا چاہتے ہو) تو اس شخص نے کہا: اے محمد! میں آپ سے کچھ پوچھنے والا ہوں (اور ذرا) سختی سے پوچھوں گا، تو آپ صلی اللہ علیہ وسلم نے فرمایا: \"پوچھو جو تم پوچھنا چاہتے ہو\"، تو اس آدمی نے کہا: میں آپ کو آپ کے، اور آپ سے پہلے (جو گزر چکے ہیں) کے رب کی قسم دلاتا ہوں! کیا اللہ تعالی نے آپ کو تمام لوگوں کی طرف (رسول بنا کر) بھیجا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے کہا: \"اے اللہ! (گواہ رہنا) ہاں\"، پھر اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں! کیا اللہ تعالی نے آپ کو سال کے اس ماہ کے روزے رکھنے کا حکم دیا ہے؟ تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! (گواہ رہنا!) ہاں\"، (پھر)اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں، کیا اللہ تعالی نے آپ کو حکم دیا ہے کہ آپ ہمارے مالداروں سے یہ صدقہ لو اور اسے ہمارے غریبوں میں تقسیم کرو، تو رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ! (گواہ رہنا) ہاں\"، تب (اس) شخص نے کہا: میں آپ کی لائی ہوئی (شریعت) پہ ایمان لایا، میں اپنی قوم کا جو میرے پیچھے ہے قاصد ہوں، اور میں بنی سعد بن بکر کا فرد ضمام بن ثعلبہ ہوں۔ عبیداللہ بن عمر نے ابن عجلان کی مخالفت کی ہے ۱؎۔\n§وضاحت\n۱؎: یہ مخالفت اس طرح ہے کہ انہوں نے اسے «عن سعید بن ابی سعید المقبری عن ابی ہریرۃ» کے طریق سے روایت کیا ہے، اور ابن عجلان نے اسے «عن سعید عن شریک عن انس» کے طریق سے روایت کیا ہے، اور یہ مخالفت ضرر رساں نہیں کیونکہ ہو سکتا ہے کہ سعید نے دونوں سے سنا ہو تو انہوں نے کبھی اس طرح طریق سے روایت کیا ہو، اور کبھی اس طریق سے :(عبیداللہ کی روایت آگے آ رہی ہے )۔","الألباني: صحيح",{"u2":"حضرت انس بن مالک رضی اللہ عنہ فرماتے ہیں کہ ہم ایک دفعہ رسول اللہ صلی اللہ علیہ وسلم کے پاس مسجد میں بیٹھے تھے کہ ایک آدمی اونٹ پر سوار ہو کر آیا۔ اس نے اسے مسجد میں بٹھا دیا، پھر اس کا گھٹنا باندھا، پھر کہنے لگا: تم میں سے محمد(صلی اللہ علیہ وسلم) کون ہے؟ اس وقت آپ لوگوں کے درمیان ٹیک لگائے بیٹھے تھے۔ تو ہم نے اس سے کہا: یہ روشن چہرے والے شخص جو تیک لگا کر بیٹھے ہیں۔ وہ آپ سے مخاطب ہو کر کہنے لگا: اے ابن عبدالمطلب! آپ نے فرمایا: ’’میں نے تجھے جواب دیا ہے۔‘‘ (میری تیری بات سن رہا ہوں۔) اس نے کہا: اے محمد(صلی اللہ علیہ وسلم)! میں آپ سے کچھ سوال کرنا چاہتا ہوں اور وہ سوالات میں سخت الفاظ میں کروں گا۔ آپ نے فرمایا: ’’جو جی چاہے پوچھ۔‘‘ اس نے کہا: میں آپ کو آپ کے اور آپ سے پہلے لوگوں کے رب کا واسطہ دے کر پوچھتا ہوں، کیا اللہ تعالیٰ نے آپ کو تمام لوگوں کے لیے رسول بنایا ہے؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ سے اللہ تعالیٰ کا واسطہ دے کر پوچھتا ہوں، کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ سال کے اس مہینے کے روزے رکھیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ سے اللہ تعالیٰ کا واسطہ دے کر پوچھتا ہوں، کیا اللہ تعالیٰ نے آپ کو یہ حکم دیا ہے کہ آپ ہمارے مال دار لوگوں سے زکاۃ لے کر ہمارے غریب لوگوں میں بانٹ دیں؟ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ وہ آدمی کہنے لگا: میں ان احکام پر ایمان لاتا ہوں جو آپ لائے ہیں۔ اور میں اپنی قوم کا قاصد ونمائندہ ہوں۔ اور میرا نام ضمام بن ثعلبہ ہے۔ میں قبیلہ سعد بن بکر سے تعلق رکھتا ہوں۔\nعبیداللہ بن عمر نے لیث بن سعد کی مخالفت کی ہے۔","f2":"یہ مخالفت بھی سند میں ہے۔ اس میں عبیداللہ بن عمر لیث بن سعد کی مخالفت یوں کرتے ہیں کہ لیث اسے بواسطہ سعید المقبری شریک بن عبداللہ سے اور وہ حضرت انس رضی اللہ عنہ سے روایت کرتے ہیں، یہی روایت راجح ہے، ابوحاتم اور امام دارقطنی نے اسے ہی ترجیح دی ہے۔ جبکہ عبیداللہ بن عمر نے سعید المقبری عن ابی ہریرۃ کی سند سے روایت کیا ہے۔ بہرکیف اس اختلاف سے متن پر کوئی اثر نہیں پڑتا کیونکہ صحیحین وغیرہ میں یہ روایت اسی طرح آتی ہے۔ دیکھیے (ذخیرۃ العقبیٰ: ۲۰ ۲۳۵)"}],[2094,"ابوہریرہ رضی اللہ عنہ کہتے ہیں: نبی اکرم صلی اللہ علیہ وسلم اپنے صحابہ کے ساتھ تھے کہ اسی دوران دیہاتیوں میں ایک شخص آیا، اور اس نے پوچھا: تم میں عبدالمطلب کے بیٹے کون ہیں؟ لوگوں نے کہا: یہ گورے رنگ والے جو تکیہ پر ٹیک لگائے ہوئے ہیں (حمزہ کہتے ہیں: «الأمغر» سرخی مائل کو کہتے ہیں) تو اس شخص نے کہا: میں آپ سے کچھ پوچھنے ولا ہوں، اور پوچھنے میں آپ سے سختی کروں گا، تو آپ صلی اللہ علیہ وسلم نے کہا: \"پوچھو جو چاہو\"، اس نے کہا: میں آپ سے آپ کے رب کا اور آپ سے پہلے لوگوں کے رب کا اور آپ کے بعد کے لوگوں کے رب کا واسطہ دے کر پوچھتا ہوں: کیا اللہ نے آپ کو رسول بنا کر بھیجا ہے؟ آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ تو گواہ رہ، ہاں\"، اس نے کہا: تو میں اسی کا واسطہ دے کر آپ سے پوچھتا ہوں کیا اللہ نے آپ کو حکم دیا ہے کہ آپ روزانہ پانچ وقت کی نماز پڑھیں؟ آپ نے کہا: \"اے اللہ تو گواہ رہ، ہاں\"، اس نے کہا: کیا اللہ نے آپ کو حکم دیا ہے کہ آپ ہمارے مالداروں کے مالوں میں سے (زکاۃ) لیں، پھر اسے ہمارے فقیروں کو لوٹا دیں، آپ صلی اللہ علیہ وسلم نے فرمایا: \"اے اللہ تو گواہ رہنا، ہاں\"، اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں، کیا اللہ تعالی نے آپ کو سال کے بارہ مہینوں میں سے اس مہینہ میں روزے رکھنے کا حکم دیا ہے؟ تو آپ صلی اللہ علیہ وسلم نے کہا: \"اے اللہ تو گواہ رہنا، ہاں\"، اس نے کہا: میں آپ کو اللہ کی قسم دلاتا ہوں کیا اللہ تعالی نے آپ حکم دیا ہے کہ جو اس خانہ کعبہ تک پہنچنے کی طاقت رکھے وہ اس کا حج کرے؟ آپ صلی اللہ علیہ وسلم نے کہا: \"اے اللہ گواہ رہنا ہاں\"، تب اس شخص نے کہا: میں ایمان لایا اور میں نے تصدیق کی، میں ضمام بن ثعلبہ ہوں۔","الألباني: صحيح الإسناد",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ فرماتے ہیں کہ ایک دفعہ نبی صلی اللہ علیہ وسلم اپنے صحابہ کرام رضی اللہ عنہم کے ساتھ تھے کہ ایک بدوی شخص آیا اور کہنے لگا: تم میں ابن عبدالمطلب کون ہیں؟ انہوں نے کہا: یہ سرخ وسفید (گورے) چہرے والے جو ٹیک لگائے بیٹھے ہیں۔ تو اس نے (آپ سے مخاطب ہو کر) کہا کہ میں آپ سے کچھ سوال کرنا چاہتا ہوں اور میں یہ سوالات سخت الفاظ میں کروں گا۔ آپ نے فرمایا: ’’جو جی چاہتا ہے پوچھ۔‘‘ اس نے کہا: میں آپ سے آپ کے اور آپ سے پہلے اور بعد والے لوگوں کے رب کا واسطہ دے کر پوچھتا ہوں: کیا اللہ تعالیٰ نے آپ کو رسول بنایا ہے؟ آپ نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ کو اللہ کا واسطہ دے کر پوچھتا ہوں، کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ آپ ہر دن، رات میں پانچ نمازیں پڑھا کریں؟ آپ نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ کو اسی ذات کا واسطہ دے کر پوچھتا ہوں: کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ ہمارے مال دار لوگوں سے زکاۃ لے کر غریب لوگوں میں تقسیم کر دیا کریں؟ آپ نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں آپ کو اسی ذات کا واسطہ دے کر پوچھتا ہوں: کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ بارہ مہینوں میں سے اس مہینے (رمضان المبارک) کے روزے رکھا کریں؟ آپ نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں اللہ تعالیٰ کا واسطہ دے کر آپ سے پوچھتا ہوں، کیا اللہ تعالیٰ نے آپ کو حکم دیا ہے کہ جو شخص بیت اللہ تک پہنچ سکتا ہو، وہ اس کا حج کرے؟ آپ نے فرمایا: ’’اللہ کی قسم! ہاں۔‘‘ اس نے کہا: میں ایمان لاتا ہوں اور آپ کی تصدیق کرتا ہوں اور میرا نام ضمام بن ثعلبہ ہے۔","f2":"یہ دونوں روایات سابقہ حدیث: ۲۰۹۴ ہی کا بیان ہیں۔ ان کو ذکر کرنے سے مصنف رحمہ اللہ کا مقصد راویوں کا اختلاف بیان کرنا ہے جو سند دیکھنے سے معلوم ہو سکتا ہے، مثلاً: تیسری حدیث بجائے، حضرت انس رضی اللہ عنہ کے حضرت ابوہریرہ رضی اللہ عنہ سے ہے، وغیرہ۔"}],[2095,"عبداللہ بن عباس رضی اللہ عنہما کہتے تھے: رسول اللہ صلی اللہ علیہ وسلم لوگوں میں سب سے زیادہ سخی آدمی تھے، اور رمضان میں جس وقت جبرائیل علیہ السلام آپ سے ملتے تھے آپ اور زیادہ سخی ہو جاتے تھے، جبرائیل علیہ السلام آپ سے ماہ رمضان میں ہر رات ملاقات کرتے (اور) قرآن کا دور کراتے تھے۔ (راوی) کہتے ہیں: جس وقت جبرائیل علیہ السلام رسول اللہ صلی اللہ علیہ وسلم سے ملاقات کرتے تو آپ تیز چلتی ہوئی ہوا سے بھی زیادہ سخی ہو جاتے تھے۔","الألباني: صحيح",{"u2":"حضرت عبداللہ بن عباس رضی اللہ عنہ فرمایا کرتے تھے کہ رسول اللہ صلی اللہ علیہ وسلم سب لوگوں سے زیادہ سخی تھے اور آپ رمضان المبارک میں زیادہ سخاوت کرتے تھے جب جبریلg آپ سے ملتے تھے۔ اور رمضان المبارک کے مہینے میں جبریلg ہر رات آپ سے ملتے اور آپ سے قرآن مجید کا دور کیا کرتے تھے۔ جب رسول اللہ صلی اللہ علیہ وسلم سے جبریلg ملتے تو آپ چھوڑی ہوئی (تیز) ہوا سے بھی بڑھ کر سخاوت فرماتے تھے۔","f2":"(۱) ’’زیادہ سخاوت‘‘ رمضان المبارک میں ہر کام کا ثواب بہت زیادہ بڑھ جاتا ہے، اس لیے آپ اس مہینے میں زیادہ سخاوت فرماتے تھے۔ حضرت جبریلg کی ملاقات کے وقت اس میں اور اضافہ ہوتا تھا کیونکہ ان کے ساتھ نازل شدہ قرآن کا دور ہوتا تھا۔ قرآن کا نزول اللہ تعالیٰ کا بہت بڑا احسان تھا، پھر دور کے ذریعے سے اس کی حفاظت اس سے بھی بڑھ کر احسان ہے، لہٰذا شکرانے کے طور پر آپ سخاوت فرماتے تھے، نیز یہ بھی قرآن مجید پر عمل کرنے کی ایک صورت ہے۔ (۲)’’چھوڑی ہوئی (تیز) ہوا‘‘ یعنی خیر و برکت اور بارش والی ہوا سے بھی زیادہ صاحب خیر وسخاوت ہوتے تھے۔ ظاہر ہے مذکورہ ہوا قریب وبعید کے تمام کے لیے بہت مفید ہے۔"}],[2096,"ام المؤمنین عائشہ رضی اللہ عنہا کہتی ہیں: رسول اللہ صلی اللہ علیہ وسلم نے کوئی لعنت ایسی نہیں کی جسے ذکر کیا جائے، (اور) جب جبرائیل علیہ السلام کے آپ کو قرآن دور کرانے کا زمانہ آتا تو آپ تیز چلتی ہوئی ہوا سے بھی زیادہ فیاض ہوتے۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ (روایت) غلط ہے، اور صحیح یونس بن یزید والی حدیث ہے (جو اوپر گزری) راوی نے اس حدیث میں ایک (دوسری) حدیث داخل کر دی ہے۔","الألباني: صحيح الإسناد",{"u2":"حضرت عائشہ رضی اللہ عنہا فرماتی ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے کوئی لعنت ایسی نہیں کی جو قابل ذکر ہو۔ اور جب حضرت جبریل علیہ السلام سے دور کرنے کا وقت قریب ہوتا تو آپ (تیز) چھوڑی ہوئی ہو اسے بڑھ کر سخاوت فرمایا کرتے تھے۔\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ روایت غلط ہے، صحیح روایت یونس بن یزید کی ہے۔ اس حدیث کے راوی نے دو حدیثوں کو گڈمڈ کردیا ہے۔","f2":": (۱) امام صاحب کا مقصود یہ ہے کہ اس حدیث میں لعنت کا ذکر غلطی ہے بلکہ وہ ایک اور روایت ہے۔ راوی نے غلطی سے اس حدیث میں بھی لعنت والے الفاظ ذکر کر دیئے، یونس بن یزید کی روایت میں لعنت کا ذکر نہیں اور یہی درست ہے۔ (۲)’’قابل ذکر ہو‘‘ مطلب یہ ہے کہ لعنت کرنا نبی صلی اللہ علیہ وسلم کی عادت نہ تھی۔ حقیقت یہی ہے کہ آپ نے شخصی طور پر کبھی کسی پر لعنت کی ہی نہیں۔ بعض انتہائی ناقابل برداشت لوگوں پر ان کی بری صفت ذکر کے لعنت کی ہے، مثلاً: [لَعَنَ اللّٰہُ السَّارِقَ یَسْرِقُ الْبَیْضَۃَ فَتُقْطَعُ یَدُہُ] (صحیح البخاری، الحدود، حدیث: ۶۷۸۳، وصحیح مسلم، الحدود، حدیث: ۱۶۸۷)"}],[2097,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان کا مہینہ آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب ماہ رمضان المبارک شروع ہو جاتا ہے تو جنت کے دروازے کھول دیئے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں۔‘‘"}],[2098,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک شروع ہوتا ہے تو جنت کے دروازے کھول دیے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں۔‘‘","f2":"(۱)’’جنت کے دروازیـ‘‘ یعنی آسمانی جنت کے حقیقی دروازے کھول دیے جاتے ہیں، بطور استقبال کے، یہ بھی ممکن ہے کہ مراد وہ کام ہوں جو جنت میں جانے کا سبب ہیں، یعنی ان کاموں کا کرنا آسان ہو جاتا ہے۔ واقعتا رمضان المبارک میں ہر شخص کے لیے نیکی کے کام بہت آسان ہو جاتے ہیں۔ پہلے معنی حقیقت کے زیادہ قریب ہیں۔ (۲) آگ کے دروازوں سے مراد بھی وہ دونوں معانی ہو سکتے ہیں جو اوپر بیان ہوئے۔ (۳) ’’شیطان‘‘ حقیقی شیطان یا گمراہی کے اسباب تقریباً ختم ہو جاتے ہیں۔ رمضان المبارک میں عموماً ہر طرف نیکی کا دور دورہ ہوتا ہے اور برائی کرنا مشکل مگر یہ سب کچھ ایمان والوں کے لیے ہے۔ ایمان نہ ہو تو رمضان اور غیر رمضان برابر ہیں۔ (۴) جنت اور جہنم کوئی خیالی چیزیں نہیں بلکہ ان کا وجود حقیقی ہے۔ ان کے دروازے بھی ہیں جو کھولے اور بند کیے جاتے ہیں۔"}],[2099,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں، اور شیاطین زنجیر میں جکڑ دئیے جاتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک شروع ہوتا ہے تو جنت کے دروازے کھول دیے جاتے ہیں اور جہنم کے دروازے بند کر دیے جاتے ہیں اور شیاطین قید کر دیے جاتے ہیں۔‘‘"}],[2100,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان آتا ہے تو رحمت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک آتا ہے تو رحمت کے دروازے کھول دیے جاتے ہیں اور جہنم کے دروازے بند کر دیے جاتے ہیں اور شیاطین زنجیر بند کر دیے جاتے ہیں۔‘‘","f2":"’’رحمت کے دروازے‘‘ لفظ رحمت سے اس تاویل کی گنجائش نکلتی ہے کہ جنت کے دروازوں سے مراد نیکی کے کام ہیں، اگرچہ اس لفظ سے حقیقی دروازوں کی نفی بھی نہیں ہوتی نہ کرنے کی ضرورت ہی ہے۔ ممکن ہے دونوں معانی مراد ہوں۔"}],[2101,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔ اسے ابن اسحاق نے بھی زہری سے روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک آتا ہے تو جنت کے دروازے کھول دیے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں۔‘‘ اس روایت کو زہری سے ابن اسحاق نے بھی بیان کیا ہے۔ (جو آگے آرہی ہے)۔"}],[2102,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب ماہ رمضان آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ ابن اسحاق (والی) حدیث غلط ہے، اسے ابن اسحاق نے زہری سے نہیں سنا ہے، اور صحیح (روایت) وہ ہے جس کا ذکر ہم (اوپر) کر چکے ہیں۔","الألباني: صحيح لغيره",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب ماہ رمضان المبارک آتا ہے تو جنت کے دروازے کھول دیے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین کو زنجریں لگا دی جاتی ہیں۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ بیان کرتے ہیں کہ یہ، یعنی ابن اسحاق کی حدیث خطا ہے کیونکہ ابن اسحاق نے یہ حدیث زہری سے نہیں سنی۔ درست وہی ہے جو ہم پیچھے ذکر کر چکے ہیں۔","f2":"ابن اسحاق کے عدم سماع پر آئندہ الفاظ دلالت کرتے ہیں جس میں ابن اسحاق نے صرف یہ کہا ہے کہ محمد بن مسلم زہری نے یہ روایت ذکر کی۔ گویا اپنے سماع کی صراحت نہیں کی۔ یاد رہے ابن اسحاق مدلس راوی ہے۔ ایسا راوی جب تک سماع کی صراحت نہ کرے اس کی روایت درست نہیں ہوتی۔ ابن اسحاق نے زہری کا استاد انس بن ابو انس بنایا ہے جبکہ صحیح بات یہ ہے کہ زہری کے استاد نافع بن ابو انس ہیں نہ کہ انس بن ابو انس، اس لیے امام نسائی نے ابن اسحاق کی روایت کو خطا اور دوسروں کی روایت کو صحیح بتلایا ہے۔ واللہ اعلم"}],[2103,"انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"یہ رمضان ہے جو تمہارے پاس آپ پہنچا ہے اس میں جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔ ابوعبدالرحمٰن (نسائی) کہتے ہیں: یہ حدیث غلط ہے۔","الألباني: صحيح لغيره",{"u2":"حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ رمضان المبارک تمہارے پاس تشریف لا چکا ہے، اس میں جنت کے دروازے کھول دیے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین قید کر دیے جاتے ہیں۔‘‘\nامام ابوعبدالرحمن (نسائی) رحمہ اللہ فرماتے ہیں: ’’یہ حدیث صحیح نہیں۔‘‘ (یعنی حضرت ابوہریرہ رضی اللہ عنہ کے بجائے حضرت انس رضی اللہ عنہ کا ذکر صحیح نہیں۔‘‘","f2":"ابن اسحاق نے یہاں محمد بن مسلم زہری سے بیان کیا اور کہا: [وَذَکَرَ مُحَمَّدُ بْنُ مُسْلِمٍ عَنْ اُوَیْسِ بْنِ اَبِیْ اُوَیْسٍ عَنْ اَنَسِ بْنِ مَالِکٍ] اور باقی تمام حفاظ کی مخالفت کی ہے، حالانکہ باقی تمام حفاظت [عِنِ الزُّھْرِیِّ عَن ابْنِ اَبِی اَنَسٍ عَنْ اَبِیْہِ عَنْ اَبِی ہُرَیْرَۃَ] کہتے ہیں۔ ان میں عقیل بن خالد، صالح بن کیسان، شعیب بن ابی حمزہ اور یونس بن یزید ایلی ہیں۔ ان سب نے حضرت ابوہریرہ رضی اللہ عنہ کی حدیث بتائی ہے۔ ابن اسحاق مدلس ہیں، یہی وجہ ہے کہ انہوں نے سند میں وذکر محمد بن مسلم کہہ کر روایت بیان کی ہے جو کسی تدلیس کی غماز ہے اور اسی وجہ سے مذکورہ خطا کا صدور ہوا۔ مزید دیکھئے (ذخیرۃ العقبی شرح سنن النسائی: ۲۰/ ۲۶۰)"}],[2104,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم صلی اللہ علیہ وسلم عزیمت و تاکید بغیر واجب کئے قیام رمضان کی ترغیب دیتے تھے، اور فرماتے تھے: \"جب رمضان آتا ہے تو جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور اس میں شیاطین جکڑ دئیے جاتے ہیں\"۔ ابن مبارک نے اسے مرسلاً (منقطعاً) روایت کیا ہے۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم قیام رمضان (تراویح) کی ترغیب دیتے تھے لیکن ضروریق رار نہ دیتے تھے، نیز آپ صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک آتا ہے تو جنت کے دروازے کھول دیے جاتے ہیں، بھڑکتی آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں۔‘‘\n(معمر کے شاگرد) ابن مبارک نے اس روایت کو مرسل (منقطع) بیان کیا ہے۔ (یعنی ابو سلمہ کا واسطہ ذکر نہیں کیا۔)"}],[2105,"ابوہریرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"جب رمضان آتا ہے تو رحمت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور شیاطین جکڑ دئیے جاتے ہیں\"۔","الألباني: صحيح لغيره",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’جب رمضان المبارک شروع ہوتا ہے تو رحمت کے دروازے کھول دیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں اور شیاطین قید کر دیے جاتے ہیں۔‘‘"}],[2106,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان کا مبارک مہینہ تمہارے پاس آ چکا ہے، اللہ تعالی نے تم پر اس کے روزے فرض کر دیئے ہیں، اس میں آسمان کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور سرکش شیاطین کو بیڑیاں پہنا دی جاتی ہیں، اور اس میں اللہ تعالی کے لیے ایک رات ایسی ہے جو ہزار مہینوں سے بہتر ہے، جو اس کے خیر سے محروم رہا تو وہ بس محروم ہی رہا\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’تمہارے پاس ایک بابرکت مہینہ رمضان آچکا ہے، اللہ تعالیٰ نے تم پر اس مہینے کے روزے فرض قرار دیے ہیں۔ اس میں آسمان کے دروازے کھول دیے جاتے ہیں، جہنم کے دروازے بند کر دیے جاتے ہیں اور سرکش شیاطین کو طوق پہنا دیے جاتے ہیں۔ اس میں ایک رات ہے جو ہزار ماہ سے بہتر ہے۔ جو اس رات کی نیکی (عبادت) سے محروم رہا، وہ حقیقتاً محروم شخص ہے۔","f2":"(۱) مذکورہ روایت کو محقق کتاب نے سنداً ضعیف قرار دیا ہے جبکہ یہ روایت دیگر شواہد کی روشنی میں اصولی طور پر صحیح ہے، نیز دیگر محققین نے بھی شواہد کی بنا پر اسے صحیح قرار دیا ہے۔ تفصیل کے لیے ملاحظہ فرمائیے: (صحیح الترغیب للالبانی، رقم الحدیث: ۹۹۹، والموسوعۃ الحدیثیہ مسند الامام احمد: ۲/ ۵۹) (۲) ’’آسمان کے دروازے‘‘ ماہ رمضان کے استقبال کے لیے، یا اہل ایمان کے اعمال صالحہ کی وصولی کے لیے، یا اس سے اعمال صالحہ کی کثرت مراد ہے کہ سب دروازے کھولنے پڑتے ہیں کیونکہ کمزور سے کمزور ایمان والا شخص بھی اس میں کچھ نہ کچھ اعمال صالحہ کرتا ہے۔ (۳) ’’جہنم یا آگ کے دروازے‘‘ رمضان کے استقبال کے لیے احتراماً، جیسے کسی معزز شخصیت کے آنے پر ناپسندیدہ چیزوں کو ڈھانپ دیا جاتا ہے۔ یا مراد ہے کہ عذاب قبر موقوف ہو جاتا ہے لیکن یہ سب کچھ مومنین کے لیے ہے، کفار کے لیے سب کچھ کھلا رہتا ہے۔ (۴) ’’سرکش جن‘‘ یعنی بڑے بڑے شطان جکڑ دیے جاتے ہیں۔ چھوٹے چھوٹے شتونگڑے کھلے رہتے ہیں، تبھی کچھ نہ کچھ گناہ ہوتے رہتے ہیں۔ ویسے سب گناہ شیاطین ہی کی وجہ سے نہیں ہوتے، انسان کا اپنا نفس بھی تو شیطان بن جاتا ہے، لہٰذا باوجود شیاطین کے جکڑے جانے کے گناہوں کا عادی نفس گناہ میں جاری رہتا ہے۔ (۵) ’’ہزار مہینے سے بہتر ہے۔‘‘ یعنی اس رات میں عبادت عام دنوں کے ہزار مہینے کی عبادت سے بہتر ہے اور یہ مومنین کے لیے اللہ تعالیٰ کی خصوصی رحمت ہے۔ اور یہ رات ہمیشہ کے لیے ایک مقررہ رات نہیں بلکہ یہ آخری عشرے کی طاقت راتوں میں بدل بدل کر آتی ہے تاکہ لوگوں میں عبادت کا ذوق بڑھے اور وہ متعدد راتوں میں قیام کریں۔"}],[2107,"عرفجہ کہتے ہیں کہ ہم نے عتبہ بن فرقد کی عیادت کی تو ہم نے ماہ رمضان کا تذکرہ کیا، تو انہوں نے پوچھا: تم لوگ کیا ذکر کر رہے ہو؟ ہم نے کہا: ماہ رمضان کا، تو انہوں نے کہا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: \"اس میں جنت کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دئیے جاتے ہیں، اور شیاطین کو بیڑیاں پہنا دی جاتی ہیں، اور ہر رات منادی آواز لگاتا ہے: اے خیر (بھلائی) کے طلب گار! خیر کے کام میں لگ جا ۱؎، اور اے شر (برائی) کے طلب گار! برائی سے باز آ جا\" ۲؎۔ ابوعبدالرحمٰن (امام نسائی) کہتے ہیں: یہ غلط ہے ۳؎۔\n§وضاحت\n۱؎: کیونکہ یہی اس کا وقت ہے کیونکہ اس وقت معمولی عمل پر بہت زیادہ ثواب دیا جاتا ہے۔ ۲؎: اور توبہ کر لے کیونکہ یہی توبہ کا وقت ہے۔ ۳؎: غلط ہونے کی وجہ یہ ہے کہ اس روایت میں ہے کہ عرفجہ نے اسے عتبہ بن فرقد رضی اللہ عنہ کی روایت بنا دیا ہے، جب کہ صحیح بات یہ ہے کہ یہ کسی اور صحابی سے مروی ہے، جیسا کہ اگلی روایت میں آ رہا ہے، واللہ اعلم۔","الألباني: صحيح لغيره",{"u2":"حضرت عرفجہ سے منقول ہے کہ ہم حضرت عتبہ بن فرقد رضی اللہ عنہ کی بیمار پرسی کے لیے گئے۔ وہاں ہم رمضان المبارک کا تذکرہ کرنے لگے۔ انہوں نے کہا: تم کیا ذکر کر رہے ہو؟ ہم نے عرض کیا: ماہ رمضان کا تذکرہ کر رہے ہیں۔ فرمایا: میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا ہے: ’’اس ماہ مبارک میں جنت کے دروازے کھول دیے جاتے ہیں اور آگ کے دروازے بند کر دیے جاتے ہیں اور شیاطین جکڑ دیے جاتے ہیں اور ہر رات ایک اعلان کرنے والا اعلان کرتا ہے: اے نیکی کے طلب گار! ادھر آ۔ اور اے گناہ کے طلب گار! رک جا۔‘‘\nابوعبدالرحمن (امام نسائی) رحمہ اللہ بیان کرتے ہیں: یہ حدیث غلط ہے۔","f2":"(۱) امام نسائی رحمہ اللہ کا مقصد یہ ہے کہ مذکورہ روایت کی سند میں خطا ہے۔ سفیان بن عیینہ کا اسے عطاء بن سائب، عن عرفجۃ، عن عتبۃ بن فرقد کے طریق سے بیان کرنا درست نہیں کیونکہ اس طرح یہ روایت عتبہ بن فرقد کی سند سے شمار ہوگی، جبکہ حقیقت اس کے برعکس ہے۔ وہ اس طرح کی یہ روایت عرفجۃ عن عتبۃ کے بجائے عرفجۃ عَنْ رَجُلٍ مِنْ اصْحَابِ النَّبِیِّ چاہیے کہ عرفجہ ایک صحابی رسول سے روایت کرتا ہے۔ (۲) ’’اعلان کرتا ہے۔‘‘ اللہ تعالیٰ کی اس کائنات کا انتظام اللہ تعالیٰ کے حسب ہدایت ہوتا ہے اور فرشتے اس پر عمل درآمد کرتے ہیں، لہٰذا ہمارے سننے، نہ سننے سے اس اعلان پر کوئی فرق نہیں پڑتا۔ جب سچے نبی صلی اللہ علیہ وسلم نے بتلا دیا تو ہر مومن کو یہ اعلان اپنے دل کے کانوں سے سننا چاہیے۔"}],[2108,"عرفجہ کہتے ہیں: میں ایک گھر میں تھا جس میں عتبہ بن فرقد بھی تھے، میں نے ایک حدیث بیان کرنی چاہی حالانکہ صحابہ کرام رضی اللہ عنہم میں سے ایک (صاحب وہاں) موجود تھے گویا وہ حدیث بیان کرنے کا مجھ سے زیادہ مستحق تھے، چنانچہ (انہوں) نے نبی اکرم صلی اللہ علیہ وسلم سے روایت کی کہ آپ صلی اللہ علیہ وسلم نے فرمایا: \"رمضان میں آسمان کے دروازے کھول دئیے جاتے ہیں، جہنم کے دروازے بند کر دیئے جاتے ہیں، اور ہر سرکش شیطان کو بیڑی لگا دی جاتی ہے، اور پکارنے والا ہر رات پکارتا ہے: اے خیر (بھلائی) کے طلب گار! نیکی میں لگا رہ، اور اے شر (برائی) کے طلب گار! باز آ جا\"۔","الألباني: صحيح الإسناد",{"u2":"حضرت عرفجہ بیان کرتے ہیں کہ میں ایک گھر میں تھا جس میں حضرت عتبہ بن فرقد رضی اللہ عنہ بھی تھے۔ تو میں نے ایک حدیث بیان کرنے کا ارادہ کیا۔ (وہاں) نبی صلی اللہ علیہ وسلم کے صحابہ میں سے ایک صاحب تھے، لہٰذا وہ میری بجائے حدیث بیان کرنے کا زیادہ حق دار تھے۔ انہوں نے نبی صلی اللہ علیہ وسلم سے حدیث بیان فرمائی کہ آپ نے رمضان المبارک کے بارے میں بیان فرمایا: ’’اس میں آسمان کے دروازے کھول دیے جاتے ہیں، آگ کے دروازے بند کر دیے جاتے ہیں، ہر سرکش شیطان کو بیڑیوں میں جکڑ دیا جاتا ہے اور ہر رات ایک اعلان کرنے والا اعلان کرتا ہے: اے نیکی کے طلب گار! آگے اور اے شر کے طلب گار! رک جا۔‘‘","f2":"’’آگے آ‘‘ یعنی نیکی کر کیونکہ یہ نیکی کا موسم ہے اور اس میں بکثرت نیکیاں کمائی جا سکتی ہیں۔"}],[2109,"ابوبکرہ رضی اللہ عنہ روایت کرتے ہیں کہ نبی اکرم صلی اللہ علیہ وسلم نے فرمایا: \"تم میں کوئی ہرگز یہ نہ کہے کہ میں نے پورے رمضان کے روزے رکھے، اور اس کی پوری راتوں میں قیام کیا\" (راوی کہتے ہیں) میں نہیں جانتا کہ آپ نے آپ اپنی تعریف کرنے کو ناپسند کیا، یا آپ نے سمجھا ضرور کوئی نہ کوئی غفلت اور لاپرواہی ہوئی ہو گی (پھر یہ کہنا کہ میں نے پورے رمضان میں عبادت کی کہاں صحیح ہوا) یہ الفاظ عبیداللہ کے ہیں۔","الألباني: ضعيف",{"u2":"حضرت ابوبکرہ رضی اللہ عنہ سے روایت ہے، نبی صلی اللہ علیہ وسلم نے فرمایا: ’’تم میں سے کوئی شخص یہ نہ کہے کہ میں نے پورے رمضان کے روزے رکھے یا میں نے تمام راتوں کا قیام کیا۔‘‘ (راوی کہتا ہے) میں نہیں جانتا کہ آپ نے اپنے منہ تعریف کو برا سمجھایا اس لیے کہ انسان سے غفلت اور نیند کا ہونا جانا لازمی امر ہے۔ یہ الفاظ عبیداللہ (بن سعید) کے ہیں۔","f2":"(۱) یہ روایت ضعیف ہے۔ ایک دوسری ضعیف روایت میں آتا ہے کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’رمضان مت کہو کیونکہ رمضان اللہ کے ناموں میں سے ایک نام ہے، ہاں: رمضان کا مہینہ کہہ سکتے ہو۔‘‘ دیکھیے (ذخیرۃ العقبی: ۲۰/ ۲۶۹، ۲۷۰) (۲) معلوم ہوا اس قسم کے الفاظ بولنے میں کوئی حرج نہیں جیسا کہ حدیث: ۲۱۰۰، ۲۱۰۱، ۲۱۰۲ اور مابعد کی صحیح حدیث ہے کہ نیکی کی نسبت اپنی طرف کرنا مناسب نہیں بلکہ نسبت اللہ تعالیٰ کی توفیق کی طرف کرے، نیز بلا وجہ نیکی کا اعلان نہیں کرنا چاہیے۔ قبولیت کے بغیر نیکی کی کوئی حیثیت نہیں اور قبولیت کا علم سوائے اللہ تعالیٰ کے کسی کو نہیں، لہٰذا تزکیہ اللہ تعالیٰ ہی کی طرف سے ہو سکتا ہے۔"}],[2110,"عطا کہتے ہیں میں نے ابن عباس رضی اللہ عنہما کو سنا، وہ ہمیں بتا رہے تھے کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک انصاری عورت سے کہا: \"جب رمضان آئے تو اس میں عمرہ کر لو، کیونکہ (ماہ رمضان میں) ایک عمرہ ایک حج کے برابر ہوتا ہے\"۔","الألباني: صحيح",{"u2":"حضرت ابن عباس رضی اللہ عنہ بتاتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے انصار کی ایک عورت کو فرمایا: ’’جب رمضان المبارک شروع ہو جائے تو اس میں عمرہ کر لینا کیونکہ رمضان المبارک میں عمرہ حج کے برابر ہے۔‘‘","f2":"(۱) ’’حج کے برابر ہے۔‘‘ یعنی حج کے ثواب کے نہ کہ حاجی کے ثواب کے کیونکہ حاجی کے ثواب میں تو اس کے خلوص، مشقت اور نفقہ وغیرہ کا ثواب بھی شامل ہے جو ہر حاجی کے لحاظ سے مختلف ہو سکتا ہے، نیز اس بات پر اتفاق ہے کہ ایسا عمرہ فرض حج سے کفایت نہیں کر سکتا، بلکہ فرض حج کرنے کے ساتھ ہی ساقط ہوگا۔ (۲) اجنبی عورت سے مخاطب ہوناجائز ہے کیونکہ عورت کی آواز کا پردہ نہیں۔ لیکن گفتگو ضرورت کے تحت اور اخلاق کے دائرے میں رہ کر ہونی چاہیے۔ نرم ونازک انداز سے اجتناب ضروری ہے۔"}],[2111,"کریب مولی ابن عباس کہتے ہیں: ام فضل رضی اللہ عنہا نے انہیں معاویہ رضی اللہ عنہ کے پاس شام بھیجا، تو میں شام آیا، اور میں نے ان کی ضرورت پوری کی، اور میں شام (ہی) میں تھا کہ رمضان کا چاند نکل آیا، میں نے جمعہ کی رات کو چاند دیکھا، پھر میں مہینہ کے آخری (ایام) میں مدینہ آ گیا، عبداللہ بن عباس رضی اللہ عنہما نے مجھ سے (حال چال) پوچھا، پھر پہلی تاریخ کے چاند کا ذکر کیا، (اور مجھ سے) پوچھا: تم لوگوں نے چاند کب دیکھا؟ تو میں نے جواب دیا: ہم نے جمعہ کی رات کو دیکھا تھا، انہوں نے (تاکیداً) پوچھا: تم نے (بھی) اسے جمعہ کی رات کو دیکھا تھا؟ میں نے کہا: ہاں (میں نے بھی دیکھا تھا) اور لوگوں نے بھی دیکھا، تو لوگوں نے (بھی)روزے رکھے، اور معاویہ رضی اللہ عنہ نے بھی، (تو) انہوں نے کہا: لیکن ہم لوگوں نے ہفتے (سنیچر) کی رات کو دیکھا تھا، (لہٰذا) ہم برابر روزہ رکھیں گے یہاں تک کہ ہم (گنتی کے) تیس دن پورے کر لیں، یا ہم (اپنا چاند) دیکھ لیں، تو میں نے کہا: کیا معاویہ رضی اللہ عنہ اور ان کے ساتھیوں کا چاند دیکھنا کافی نہیں ہے؟ کہا: نہیں!(کیونکہ) رسول اللہ صلی اللہ علیہ وسلم نے ہمیں ایسا ہی حکم دیا ہے۔","الألباني: صحيح",{"u2":"حضرت کریب بیان کرتے ہیں کہ مجھے حضرت ام فضل رضی اللہ عنہا نے (کسی کام کے لیے) علاقہ شام میں حضرت معاویہ رضی اللہ عنہ (امیرالمومنین) کے پاس بھیجا۔ میں شام گیا اور ان کا کام پورا کیا۔ میں ابھی شام ہی میں تھا کہ رمضان المبارک کا چاند طلوع ہوگیا۔ میں نے بذات خود جمعے کی رات چاند دیکھا، پھر میں ماہ رمضان المبارک کے آخر میں مدینہ منورہ واپس آیا تو حضرت ابن عباس رضی اللہ عنہ نے چاند کا ذکر کرتے ہوئے مجھ سے پوچھا کہ تم نے (رمضان المبارک کا) چاند کب دیکھا تھا؟ میں نے کہا: ہم نے جمعۃ المبارک کی رات دیکھا تھا۔ وہ فرمانے لگے: تو نے خود جمعے کی رات دیکھا تھا؟ میں نے کہا: جی ہاں۔ دوسرے لوگوں نے بھی دیکھا تھا، پھر لوگوں نے اور حضرت معاویہ رضی اللہ عنہ نے روزہ رکھا۔ آپ نے فرمایا ہم نے تو ہفتے کی رات دیکھا تھا۔ ہم تو روزے رکھتے رہیں گے حتیٰ کہ تیس پورے ہو جائیں یا چاند دیکھ لیں۔ میں نے کہا: کیا آپ حضرت معاویہ رضی اللہ عنہ اور ان کے ساتھیوں کے چاند دیکھ لینے کو کافی نہیں سمجھتے؟ انہوں نے کہا نہیں، ہمیں رسول اللہ صلی اللہ علیہ وسلم نے یہی حکم دیا ہے۔","f2":"(۱) ’’یہی حکم دیا ہے‘‘ کہ چاند دیکھ کر روزہ رکھو اور چاند دیکھ کر عید کرو۔ اس کا مطلب یہ نہیں کہ ہر شخص چاند دیکھے بلکہ کوئی ایک معتبر آدمی بھی چاند دیکھ لے یا کسی اور جگہ چاند نظر آنے کی خبر پہنچ جائے تو اس علاقے کے تمام لوگ روزہ رکھیں گے یا عید کریں گے اور نیا مہینہ شروع ہو جائے گا، البتہ یہ تحقیق ضروری ہے کہ دونوں جگہوں میں اتنا فاصلہ نہ ہو جتنے فاصلے سے چاند دیکھنے میں ایک یا دو دن کا فرق پڑ سکتا ہے۔ جس جگہ چاند نظر آیا ہو، اس کے اردگرد جتنے علاقے میں وہ چاند نظر آ سکتا ہو، اتنے علاقے کے لیے وہ رؤیت معتبر ہوگی۔ اس سلسلے میں علمائے رصد سے رہنمائی حاصل کی جائے۔ آج کل ہر اسلامی ملک اتنا چھوٹا ہے کہ اس ملک میں کسی جگہ بھی چاند نظر آجائے تو وہ پورے ملک میں نظر آسکتا ہے، لہٰذا ایک ملک میں کسی جگہ چاند نظر آنے پر سارے ملک میں روزہ یا عید ہو سکتے ہیں، البتہ مختلف ممالک میں چاند مختلف ہو سکتا ہے، مثلاً: سعودی عرب اور پاکستان ایک دوسرے سے خاصے فاصلے پر ہیں۔ اس سلسلے میں علمائے ہیئت ورصد ہی صحیح فیصلہ کر سکتے ہیں، لہٰذا رؤیت ہلال کمیٹی میں ان کی شرکت انتہائی ضرو ری ہے۔ اس سلسلے میں چند اصول مسلمہ ہیں: * جب ایک شہر میں چاند نظر آئے تو اس سے ملتے جلتے طول بلد پر واقع تمام شہروں میں چاند ہوگا، خواہ ان کا درمیان فاصلہ ہزاروں میل ہی میں ہو۔ *کسی شہر میں چاند نظر آئے تو اس سے مغرب میں واقع تمام علاقوں میں خواہ مخواہ چاند نظر آجائے گا، دیکھنے کی ضرورت نہیں، خواہ فاصلہ ہزاروں میل ہو، البتہ اس کے الٹ ضروری نہی، یعنی مغرب کا چاند مشرق کے لیے معتبر نہیں، الگ دیکھنا ہوگا۔ *بالائی علاقے میں چاند نظر آئے تو نشیبی علاقے میں چاند کا نظر آنا ضروری نہیں، البتہ اس کے الٹ ضروری ہے، یعنی نشیبی علاقے میں چاند نظر آیا تو بالائی علاقے میں لازماً چاند ہوگا، اور یہ اصول بدیہی ہیں، ان میں اختلاف ممکن نہیں۔ (۲) مدینہ منورہ اور دمشق کے درمیان ویسے تو کافی فاصلہ ہے مگر طول بلد کے لحاظ سے صرف چھ درجے کا فرق ہے۔ گویا طلوع اور غروب میں ۲۴ منٹ کا فرق ہے، اتنے فرق سے چاند کی رؤیت میں فرق نہیں پڑتا۔ دونوں جگہ ایک ہی دن چاند ہونا چاہیے، مگر اس دور میں پیغام رسانی کے تیز ذرائع نہ ہونے کی وجہ سے اتنے فاصلے سے بروقت خبر پہنچنا ناممکن تھا، لہٰذا حضرت ابن عباس رضی اللہ عنہ نے مدینہ منورہ کے لیے شام (یعنی دمشق جو اس وقت دارالخلافہ تھا) کی رؤیت کو کافی نہ سمجھا۔"}],[2112,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک دیہاتی نبی اکرم صلی اللہ علیہ وسلم کے پاس آیا (اور) کہنے لگا: میں نے چاند دیکھا ہے، تو آپ نے کہا: \"کیا تم شہادت دیتے ہو کہ اللہ کے سوا کوئی حقیقی معبود نہیں، اور محمد اس کے بندے اور رسول ہیں؟\" اس نے کہا: ہاں، تو نبی اکرم صلی اللہ علیہ وسلم نے لوگوں میں روزہ رکھنے کا اعلان کر دیا۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہ سے روایت ہے کہ ایک اعرابی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: میں نے چاند دیکھا ہے۔ فرمایا: ’’تو گواہی دیتا ہے کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور حضرت محمد(صلی اللہ علیہ وسلم) اللہ تعالیٰ کے بندے اور رسول ہیں؟‘‘ اس نے کہا: جی ہاں۔ تو نبی صلی اللہ علیہ وسلم نے اعلان کر دیا: ’’روزہ رکھو۔‘‘","f2":"(۱) معلوم ہوتا ہے چاند کا دیکھنا اور خبر مل جانا برابر ہیں۔ بشرطیکہ مطلع ایک ہو جیسا کہ پچھلی حدیث کے فوائد میں بیان ہوا۔ (۲) ماہ رمضان المبارک کے چاند کے بارے میں جمہور اہل علم کا قول یہی ہے کہ ایک مسلمان کی گواہی کافی ہے جیسا کہ حدیث میں واضح ہے اور یہی صحیح ہے، البتہ بعض فقہاء گواہی کے مدنظر دو مسلمانوں کا ہونا ضروری سمجھتے ہیں، لیکن عید کے بارے میں ائمہ اربعہ میں اتفاق ہے کہ دو مسلمانوں کی گواہی ضروری ہے کیونکہ عید میں لوگوں کا اپنا مفاد بھی ہوتا ہے، لہٰذا حقوق العباد کی طرح اس میں بھی دو گواہ ہونے چاہئیں جبکہ روزے میں لوگوں کا ذاتی مفاد نہیں، لہٰذا وہاں ایک مسلمان کی خبر کافی ہے کیونکہ یہ خبر ہے شہادت (گواہی) نہیں اورخبر کے لیے ایک معبر شخص کافی ہے۔ (۳) ’’تو گواہی دیتا ہے؟‘‘ گویا مسلمان ہونا ضروری ہے، نیز وہ قابل اعتبار بھی ہو، یعنی جھوٹ بولنے میں معروف نہ ہو اور فرائض شرع کا پابند ہو، دین کو مذاق نہ بناتا ہو۔ (۴) یہ اور آئندہ تینوں روایات ضعیف ہیں لیکن ابوداؤد (حدیث: ۲۳۴۲) میں ابن عمر رضی اللہ عنہ سے اسی مفہوم کی صحیح حدیث موجود ہے، اس لیے حدیث میں بیان کردہ مسئلہ اور دیگر مستنبط مسائل درست ہیں۔ واللہ اعلم"}],[2113,"عبداللہ بن عباس رضی اللہ عنہما کہتے ہیں کہ ایک اعرابی (دیہاتی) نے نبی اکرم صلی اللہ علیہ وسلم کے پاس آ کر کہا: میں نے آج رات چاند دیکھا ہے، آپ نے پوچھا:\"کیا تم شہادت دیتے ہو کہ اللہ کے سوا کوئی معبود برحق نہیں، اور محمد اس کے بندے اور رسول ہیں؟\" اس نے کہا: ہاں، تو آپ نے فرمایا: \"بلال! لوگوں میں اعلان کر دو کہ کل سے روزے رکھیں\"۔","الألباني: ضعيف",{"u2":"حضرت ابن عباس رضی اللہ عنہ بیان کرتے ہیں کہ ایک اعرابی نبی صلی اللہ علیہ وسلم کے پاس آیا اور کہنے لگا: میں نے آج رات چاند دیکھا ہے۔ آپ نے فرمایا: ’’تو گواہی دیتا ہے کہ اللہ تعالیٰ کے سوا کوئی معبود نہیں اور محمد(صلی اللہ علیہ وسلم) اس کے بندے اور رسول ہیں؟‘‘ اس نے کہا: جی ہاں۔ آپ نے فرمایا: ’’اے بلال! لوگوں میں اعلان کر دو کل روزہ رکھیں۔‘‘"}],[2114,"اس سند سے عکرمہ سے یہ حدیث مرسلاً مروی ہے۔","الألباني: ضعيف",{"u2":"ابوداؤد (عمر بن سعد حفری) نے حضرت سفیان سے، انہوں نے سماک سے، انہوں نے حضرت عکرمہ سے یہ روایت مرسل بیان کی ہے۔"}],[2115,"اس سند سے بھی عکرمہ سے یہ حدیث مرسلاً مروی ہے۔","الألباني: ضعيف",{"u2":"عبداللہ نے حضرت سفیان سے، انہوں نے سماک سے، انہوں نے حضرت عکرمہ رحمہ اللہ سے یہ روایت مرسل بیان کی ہے۔"}],[2116,"عبدالرحمٰن بن زید بن خطاب سے روایت ہے کہ انہوں نے ایک ایسے دن میں جس میں شک تھا (کہ رمضان کی پہلی تاریخ ہے یا شعبان کی آخری) لوگوں سے خطاب کیا تو کہا: سنو! میں نے رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کی ہم نشینی کی، اور میں ان کے ساتھ بیٹھا تو میں نے ان سے سوالات کئے، اور انہوں نے مجھ سے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"تم چاند دیکھ کر روزہ رکھو، اور چاند دیکھ کر افطار کرو، اور اسی طرح حج بھی کرو، اور اگر تم پر مطلع ابر آلود ہو تو تیس(کی گنتی) پوری کرو، (اور) اگر دو گواہ (چاند دیکھنے کی) شہادت دے دیں تو روزے رکھو، اور افطار (یعنی عید) کرو\"۔","الألباني: صحيح",{"u2":"حضرت حسین بن حارث جدلی سے روایت ہے کہ حضرت عبدالرحمن بن زید بن خطاب نے اس دن لوگوں کو خطاب کیا جس دن رمضان المبارک ہونا مشکوک تھا۔ انہوں نے فرمایا: میں رسول اللہ صلی اللہ علیہ وسلم کے صحابہ کرام رضی اللہ عنہم کے پاس بیٹھتا رہا ہوں اور ان سے مسائل بھی پوچھتا رہا ہوں۔ انہوں نے مجھے بیان کیا ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جاند دیکھ کر روزے رکھنا شروع کرو اور چاند دیکھ کر روزے رکھنا بند کرو۔ اور چاند دیکھ کر ہی حج اور قربانی کرو۔ اگر چاند نظر نہ آئے تو (مہینے کے) تیس دن پورے کر لو۔ اور اگر دو شخص چاند دیکھنے کی گواہی دیں تو بھی روزے رکھنا شروع یا بند کر دو۔‘‘","f2":"(۱) ’’مشکوک دن‘‘ سے مراد شعبان کا تیسواں دن ہے کیونکہ اس کے بارے میں دونوں امکان ہوتے ہیں، شعبان کی تیسویں ہو یا رمضان امبارک کی یکم، خصوصاً جب چاند کا امکان تھا لیکن مطلع ابر آلود تھا، چاند نظر نہ آ سکا۔ (۲) ’’چاند نظر نہ آئے‘‘ بادل، غبار یا دھواں وغیرہ کی وجہ سے۔ (۳) ’’دو شخص گواہی دیں۔‘‘ دو شخص تب ضروری ہیں جب مطلع بالکل صاف ہو کیونکہ ایسی صورت میں زیادہ اشخاص کے دیکھنے کا امکان ہوتا ہے، البتہ اگر مطلع ابر آلود ہو تو ایک شخص کی گواہی بھی کافی ہے جیسا کہ پیچھے حدیث میں بیان ہوا، کیونکہ ایسی صورت میں عموماً نظر آنے کا امکان نہیں ہوتا، ایک آدھ کو نظر آنا بھی غنیمت ہوتا ہے، اس طرح احادیث میں تطبیق ہو جائے گی اور تطبیق ہی بہتر ہوتی ہے، البتہ عید کے لیے دو گواہ ضروری ہیں۔ واللہ ا علم"}],[2117,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چاند دیکھ کر روزے رکھو، اور چاند دیکھ کر افطار کرو، اگر مطلع ابر آلود ہو تو تیس (دن)پورے کرو\" ۱؎۔\n§وضاحت\n۱؎: اس کا مطلب یہ ہے کہ اگر ۲۹ شعبان کو آسمان میں بادل ہوں اور اس کی وجہ سے چاند نظر نہ آئے تو شعبان کے تیس دن پورے کر کے روزوں کی شروعات کرو، اسی طرح ۲۹ رمضان کو اگر عید الفطر کا چاند نظر نہ آ سکے تو تیس روزے پورے کر کے عید الفطر مناؤ۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’روزوں کا آغاز چاند دیکھ کر کرو اور اختتام بھی چاند دیکھ کر کرو۔ اگر بادل ہوں (اور چاند نظر نہ آئے) تو تیس دن پورے کرو۔‘‘","f2":"(۱) ان میں اختلاف کی صورت یہ ہے کہ ابوہریرہ رضی اللہ عنہ سے نیچے کے رواۃ میں شعبہ کے تلامذہ میں اختلاف ہے۔ جب اسماعیل بن علیہ امام شعبہ سے بیان کرتے ہیں تو فَعُدُّوا ثَلَاثِیْنَ کے الفاظ نقل کرتے ہیں۔ لیکن جب ان سے ورقاء بن عمر یشکری بیان کرتے ہیں تو فَاقْدُرُوْا ثَلَاثِیْنَ کہتے ہیں لیکن اس سے حدیث کی صحت پر کوئی اثر نہیں پڑتا۔ مزید تفصیل وتحقیق کے لیے دیکھئے (فتح الباری: ۴/ ۲۱، رقم الحدیث: ۱۹۰۹) (۲) مہینہ کوئی بھی ہو، حکم یہی ہے۔ بع روایات میں شعبان کا لفظ صرف اس لیے ہے کہ روزوں کا تعلق شعبان کے اختتام سے ہے، ورنہ خود رمضان بھی اس صورت حال میں (یعنی جب شوال کا چاند نظر نہ آئے) تیس دن ہی کا شمار کیا جائے گا۔"}],[2118,"ابوہریرہ رضی اللہ عنہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"چاند دیکھ کر روزہ رکھو، اور چاند دیکھ کر افطار کرو، (اور) اگر مطلع تم پر بادل چھائے ہوں تو تیس دن پورے کرو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے مروی ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’چاند دیکھ کر روزے رکھنا شروع کرو اور چاند دیکھ کر ہی روزے رکھنا بند کرو اور اگر بادل ہوں (اور چاند نظر نہ آئے) تو مہینہ تیس کا سمجھو۔‘‘"}],[2119,"ابوہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: \"جب تم (رمضان کا) چاند دیکھو تو روزہ رکھو، اور جب (شوال کا) چاند دیکھو تو روزہ رکھنا بند کر دو، (اور) اگر تم پر مطلع ابر آلود ہو تو (پورے) تیس دن روزہ رکھو\"۔","الألباني: صحيح",{"u2":"حضرت ابوہریرہ رضی اللہ عنہ سے منقول ہے، رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب تم (رمضان المبارک کا) چاند دیکھ لو، تب روزے رکھنا شروع کرو اور جب تم (شوال کا) چاند دیکھ لو تو روزے رکھنا بند کر دو۔ اگر بادل ہوں (اور تمہیں شوال کا چاند نظر نہ آئے) تو تیس روزے پورے کرو۔‘‘"}],[2120,"عبداللہ بن عمر رضی اللہ عنہما کہتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: \"جب تم چاند دیکھو تو روزہ رکھو، اور جب (شوال کا) چاند دیکھو تو روزہ رکھنا بند کر دو، (اور) اگر تم پر مطلع ابر آلود ہو تو اس کا اندازہ لگاؤ\"۔","الألباني: سكت عنه الشيخ",{"u2":"حضرت عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو فرماتے سنا: ’’جب تم چاند دیکھو تو روزے رکھنا شروع کر دو اور جب تم (شوال کا) چاند دیکھو تو روزہ رکھنا بند کر دو۔ اگر بادل ہوں (اور چاند نظر نہ آئے) تو اس مہینے کو تیس کا سمجھو۔‘‘"}]]);
